-- ============================================================================
-- OceGossipUA — база перекладів ДІАЛОГІВ (Gossip)
-- ============================================================
-- СЮДИ: репліки NPC у вікні діалогу.
--
-- Формат:  [ID] = "Український текст",
--
-- Як отримати ID:
--   1) Відкрий діалог з NPC
--   2) Натисни кнопку ID (або /ogua dump)
--   3) Встав рядок сюди і переклади значення
--
-- Після правок: /reload
-- ============================================================================

OceGossipUA_DB = {

[791079078] = "Вітаю, $N",  -- db:1
[840023817] = "Привіт, $N. Чим можу допомогти?",  -- db:2
[439003713] = "Гей, громадянине! Ти виглядаєш міцним хлопцем. Нас, охоронців, тут не так багато, і мені б не завадила твоя допомога...",  -- db:197
[115755377] = "Карлики з племені «Диких Молотів» можуть і мати швидких коней, але чи витримають ті грифони з Піку Орлиного Гнізда спеку Великої Кузні?  Гадаю, що ні!",  -- db:401
[816818693] = "Долина Випробувань загартує навіть найслабшого, перетворивши його на воїна, гідного приєднатися до Орди. Ті, хто не зможе витримати її випробувань, будуть залишені смажитися під палючим пустельним сонцем.",  -- db:447
[262818259] = "Стільки справ, стільки справ! Профспілка визначила нам терміни, і їх аж ніяк не хочеться пропустити!",  -- db:518
[130870355] = "Директор Рідлвокс доручив мені керівництво програмою розробки шредерів Союзу. Лише кілька місяців на цій посаді — а я вже в скрутному становищі! Мені б не завадила твоя допомога, $n!",  -- db:519
[240519237] = "Бачиш, новий подрібнювач від компанії «Venture» кращий за мій останній — від змінних насадок до ручок управління! Мій бос поставив мені досить жорсткий термін, але ми з хлопцями ніяк не могли нічого придумати.$b$bНіщо не працювало, тож ми вирішили «позичити» один із їхніх прототипів. Я відправив Візлкранка до Болота Шламу, щоб він один вкрав, але він ще не повернувся!",  -- db:520
[353735353] = "Ти вбив «Примарний Виск». Ти — справжній герой!",  -- db:521
[873236504] = "Підійди ближче, юнаку. У мої часи я міг чути, як б’ється серце здобичі, але тепер тобі доведеться говорити голосніше, якщо хочеш, щоб тебе почули.",  -- db:522
[759078285] = "Я бігав цими рівнинами багато-багато сезонів.  І полював на величезних звірів.  І мене ніколи не перемагали… доки я не зіткнувся з Примарним Виттям.$B$BDавним-давно цей величезний вовк був союзником тауренів і хоробро боровся проти Палаючого Легіону.  Але його жорстоко поранив демон, і рана на його тілі так і не загоїлася.  Зрештою… це звело «Примарний Виск» з розуму.$B$BТепер він блукає рівнинами в муках, шукаючи кінця своїм стражданням.  На мій сором, під час нашої сутички мені не вистачило сил, щоб убити його…",  -- db:523
[306726991] = "Вітаю, магу.  Чи бажаєш ти дізнатися більше про світ магії?",  -- db:538
[186248162] = "Радий бачити тебе, $c.  Ось моя порада тобі: подорожуючи світом, будь обережним із магією, бо вона спалить тих, хто не навчений.",  -- db:539
[518023532] = "Вітаю.  Я — інструктор магів, а ти — маг.",  -- db:558
[147304848] = "Вітаю.  Я — тренер-гном-маг, а ти — маг.",  -- db:560
[334808446] = "Радий бачити тебе, $c.  Хочеш пораду?  Подружися з магом!  У нас є кілька хитрощів у запасі, справді...",  -- db:561
[641972167] = "Вітаю.  Я — тренер магів-нежить, а ти — маг.",  -- db:562
[209206572] = "Вітаю, $c.  Ти прийшов, щоб дізнатися про таємні мистецтва?",  -- db:564
[231640798] = "Вітаю, $c.  Мені шкода таких, як ти, адже таємниці справжньої магії тобі недоступні...",  -- db:565
[678198163] = "Твій час ще не настав. Я допоможу тобі повернутися у світ живих… за певну ціну.",  -- db:580
[730572623] = "З дозволу леді Сильвани чисельність «Смертошукачів» зростає. Все більше мечів, щоб нанести удар по наших ворогах, коли вони цього найменше очікують.",  -- db:581
[806902487] = "Чого ти хочеш, $c? Я запізнююся, а мій роботодавець не схвалює запізнень.",  -- db:623
[454880175] = "Так, це я. А тобі що до того?",  -- db:624
[356031851] = "«Розбита Рука» поверне Орді колишню славу, незважаючи на боязкість Вождя.",  -- db:638
[935871782] = "Що такий молодий $c, як ти, робить у гостях у старого фермера, як я?",  -- db:678
[444201959] = "Наралекс знову заснув!$b$bДавним-давно Наралекс вирушив до цієї печери з благородною метою — увійти в «Смарагдовий Сон» і перетворити Пустощі на буйний ліс. Його зосередженість ослабла, а думки були затьмарені зміїними видіннями.$b$bТепер рептильні чудовиська вириваються з його снів у світ. Його треба пробудити від цього кошмару, інакше він буде назавжди втрачений, а велике зло вирветься на волю.$b$bЛише після того, як його зіпсовані слуги, Лорди Іклів, будуть знищені, я зможу провести ритуал пробудження.$B$B",  -- db:698
[234883702] = "Володарі Клінів мертві! Надія ще не втрачена!$b$bОднак ритуал пробудження є досить складним. Його неможливо провести самотужки.$b$bЯ подбаю про всі необхідні приготування, але мені знадобиться твоя допомога, щоб захистити мене. Кошмари, викликані подорожжю Наралекса Смарагдовим Сном, виявляються досить грізними. Без твоєї допомоги ця місія приречена на провал.$b$bКоли будеш готовий захищати мене, скажи слово — і я поведу тебе до покоїв Наралекса.",  -- db:699
[309426154] = "Машина повертається до вас.$B$BНа задній панелі машини розташований порожній, дивно викривлений отвір із гравіюванням: «Власність капітана Гелкака Гіромаста»",  -- db:718
[488981612] = "Гей!  Ти виконуєш доручення Тірта?  На твоєму місці я б тримався від нього якнайдалі!  Його розум затуманений від надмірного вживання алкоголю, але його магія сильна, як і раніше!",  -- db:720
[301066801] = "Звісно, я тобі скажу цю фразу.  Тільки б мені не довелося навіть наближатися до Тірта!",  -- db:738
[561326836] = "Ключ Гелкака всунувся у вільний отвір.",  -- db:758
[754059134] = "Ти знущаєшся з мене, коли я не можу захиститися, прикутий до цієї залізної кулі?",  -- db:759
[70233203] = "У одного з людей є ключ від цього пекельного пристрою. Здається, його звали Естон.",  -- db:760
[581165096] = "Забирайся звідси, $c, інакше тебе теж закують у ланцюги.",  -- db:761
[953399474] = "Марлген... Один із тюремників. У нього є ключ від моїх кайданів.",  -- db:762
[69508971] = "Банк Штормовію розташований у Торговому районі, на північний захід від міських воріт. Зараз я покажу вам це на карті.",  -- db:764
[456971166] = "«Штормовійська лічильна контора» розташована біля головних воріт у Торговому районі Штормовію. А коли ви втомитеся рахувати свої гроші, обов’язково загляньте до «Позолоченої троянди», щоб випити чогось.",  -- db:764
[776838695] = "«Штормовійська лічильна контора» розташована біля головних воріт у торговому районі Штормовію. А коли ви втомитеся рахувати свої гроші, обов’язково загляньте до «Позолоченої троянди», щоб випити чогось.",  -- db:764
[984034920] = "Якби ж то весь цей сніг просто розтанув. Він постійно намочає мій халат і все псує!",  -- db:766
[648072424] = "Дурний сніг... Гей, ти ж $n, правда? Мені щойно надійшло повідомлення, в якому запитують про тебе.",  -- db:767
[143240279] = "Вас викликав Лаго Блекренч, майстер-чаклун з Айронфорджа. Вам слід негайно з’явитися до нього. Ви знайдете його в районі «Печера Загублених» у місті.",  -- db:768
[108019431] = "Вітаю, $R, я — Тарнаріун Трітендер.",  -- db:769
[804532790] = "Якщо мене запитати, то я вважаю, що гобліни — це безпрограшний варіант. У нас є все необхідне, і у нас є таланти!",  -- db:778
[498977807] = "Якби не та проклята гномська удача, вони б ніколи не виграли гонку!",  -- db:778
[907256680] = "Якби я був на твоєму місці, то купив би ваучер на расу гоблінів. Вболівати за іншу команду — це марна трата часу.",  -- db:778
[820520102] = "Я ставлю на гоблінів!  І якщо ти хоч трохи розсудливий, то ти теж!",  -- db:778
[113042357] = "Я чув, що в наступних перегонах вони збираються підірвати машину гнома!  Правда це чи ні, але я б тримався подалі від їхньої піт-зони.",  -- db:778
[189402327] = "А, ти маєш на увазі Джонсона? Я чув, що він переховується.",  -- db:779
[244440157] = "Ха!  Тірт уже кілька днів його шукає, але той не хоче, щоб його знайшли.  Він боягуз!",  -- db:779
[741815730] = "Шукаєш сміливця?  Ну, я цього не казав, але... може, якщо запитаєш Кронрайдера, що сидить у вежі, він тобі скаже...",  -- db:779
[517308244] = "Якби не неймовірна, безглузда удача гоблінів, вони б розбивали свою машину під час кожної гонки!",  -- db:780
[650368886] = "Ці змагання — чудова нагода проявити нашу винахідливість!",  -- db:780
[941653337] = "Я встановив новий пристрій у матричний регулятор нашого автомобіля. Це має збільшити його коефіцієнт швидкості щонайменше у п’ятнадцять разів!",  -- db:780
[923217920] = "Мій син зміг би сконструювати машину, швидшу за цю громіздку купу брухту, схожу на гобліна!",  -- db:780
[167811225] = "Мій «Gizmotic Almanacotron» каже, що ми маємо перемогти гоблінів на двадцять секунд швидше, ніж минулого разу!",  -- db:780
[783668917] = "Тірт останнім часом не в собі, як і його помічник.",  -- db:781
[220994735] = "Джонсон?  Здається, він десь тут поруч...",  -- db:781
[116857447] = "Сміливець?  Я чув, що організатор перегонів Кронкрайдер, який сидить на вежі, знає, де він.",  -- db:781
[418230231] = "Нарешті! Я нарешті звільнився з цієї камери!$b$b«Кірін-Тор» відправив мене з Даларана, щоб я з’ясував, як просуваються справи Аругала з нежиттю тут, у Сріблясто-сосновому лісі. Ми й гадки не мали, що чарівник втратив розум.$b$bЯ мушу негайно повідомити про цей безлад! Але перш ніж піти, дозвольте мені зняти магічний замок з дверей внутрішнього двору.$b$bВи перемогли Ретілгора, тож, можливо, ви виживете й у тому, що чекає за цими дверима...",  -- db:798
[765955804] = "Нарешті! Хтось, хто визволить мене з цієї камери!$b$bВисокий виконавчий Хадрек відправив нас зібрати інформацію про Фортецю, щоб можна було розробити план остаточного повалення Аругала.$b$bАле старий чарівник має чимало хитрощів у запасі, і нас виявило магічне захисне закляття. Мене кинули до цієї в'язниці. Вінсенту пощастило не так.$b$bЯ мушу негайно повернутися до Хадрека, щоб доповісти йому про все. Але спершу я відімкну для тебе замок на дверях, що ведуть у двір. Можливо, ти зможеш спробувати щастя у боротьбі з ворогами, які чатують за ними.",  -- db:799
[335323532] = "Колись я слідував вченням «Молота Сутінків». Одержимий ідеєю воскресити Старих Богів, я вирушив углиб цього лігва, щоб спробувати черпнути силу з проклятої bestii, Аку'маї!$b$bСтавши свідком жертвопринесення незліченної кількості невинних, я схаменувся.$b$bЯ був у пастці, але тепер я вільний! Та я так далеко від своєї батьківщини — Хаз-Модану!$b$bХоробрий мандрівнику, я пропоную тобі шлях до дуже особливої землі в обмін на вбивство Аку'маї. Якщо бажаєш, я можу перенести тебе до міста Дарнассус.",  -- db:818
[10549777] = "Ласкаво просимо до мого готелю, втомлений мандрівник. Чим можу вам допомогти?",  -- db:820
[366670763] = "Трохи відпочиньте, розслабте втомлені кістки.",  -- db:821
[29027389] = "Як вітер на рівнинах, ти тут завжди бажаний гість.",  -- db:822
[338161484] = "Наповніть свої кухлі та підсуньте стільці. Нам є що розповісти, а бочки — спорожнити.",  -- db:823
[29803553] = "Ваше тіло виглядає виснаженим, а душа — стомленою. Відпочиньте під нашим дахом і дозвольте Елуні вести вас у снах.",  -- db:824
[339853456] = "Заходьте, заходьте. Тільки не сідайте занадто близько до плити. Сьогодні вона ще не вибухнула, але, щоб перестрахуватися, думаю, вам краще сісти десь інде.",  -- db:825
[150283707] = "Привіт, $r, радий познайомитися з вами.$B",  -- db:838
[866004627] = "Ну-ну... погляньте, кого сюди привела кішка... і чим я можу вам допомогти, $c?",  -- db:878
[813977885] = "Майстра грифонів можна знайти на північно-східному валу, звідки відкривається вид на Долину Героїв.",  -- db:879
[434877355] = "Ааа, ви шукаєте Дунгара Лонгдрінка. У нього є одні з найшвидших грифонів на цій стороні Хаз-Модана! Ви знайдете його на крепостних валах у Торговому районі.",  -- db:879
[316427609] = "Хочеш прокотитися на грифоні, так? Дунгар тримає своїх птахів на валу в Торговому районі. Тільки не забудь міцно триматися!",  -- db:879
[455575985] = "Грифони, так? Мені ці тварини ніколи особливо не подобалися, але кожному своє.$B$BДунгара Лондрінка можна знайти на валу в Торговому районі.",  -- db:879
[154956827] = "Ви можете знайти Олдвіна Лафліна в Центрі для відвідувачів Штормовію, що у Торговому районі.",  -- db:882
[997143194] = "Збираєшся створити гільдію, так? Тоді удачі тобі!$B$B Поговори з Алдвіном Лафліном у Центрі для відвідувачів Штормовію. Він розташований у Торговому районі, одразу після входу з Долини Героїв.",  -- db:882
[672731535] = "Ааа, тоді вам саме те, що треба — Центр для відвідувачів Штормовію. Це перша будівля ліворуч, якщо йти через головні ворота з Долини Героїв.",  -- db:882
[859282035] = "Якого тренера з занять ви шукаєте?",  -- db:898
[221478699] = "Магів збираються у Святилищі Чарівника в Кварталі магів. У них там справжня вежа. На тлі неї наші казарми виглядають як селянські халупи.",  -- db:899
[697778952] = "О, ти, мабуть, шукаєш якесь таємниче просвітлення? Немає кращого місця, ніж «Святилище чарівників» у Кварталі магів.",  -- db:899
[348382821] = "Схоже, тобі треба поговорити з Магінором Дюма! Зазвичай його можна знайти у Святилищі чарівників у Кварталі магів. Звісно, ніколи не знаєш, коли і куди ці маги раптом телепортуються.",  -- db:899
[601223670] = "Тоді тобі слід поговорити з Осборном. У Штормовії немає кращого вчителя мистецтва маскування, ніж він. Шукай його в Старому місті.",  -- db:900
[410007633] = "Ех, ці розбійники тільки й роблять, що ускладнюють нам роботу тут, у Штормовій. Хотів би я витягнути й Осборна, й Матіаса зі Старого міста і відправити їх прямо до в’язниці.",  -- db:900
[151433199] = "Якщо ви хочете знайти розбійників, вам слід відправитися до Старого міста. Воно розташоване в північно-східній частині Штормовію.",  -- db:900
[516783581] = "Воїнів зазвичай можна зустріти або в таверні «Свиня і Свисток», або в казармах у Старому місті. Але скажу тобі, що таверна, мабуть, кращий варіант для пошуків.",  -- db:901
[71270569] = "Хочеш потренуватися, так? Я міг би навчити тебе краще, ніж будь-хто в Штормовій, але охорона це забороняє. Мабуть, тобі доведеться задовольнитися кимось із тих колишніх бійців, що тиняються біля казарм або в таверні «Свиня і Свисток» у Старому місті.",  -- db:901
[834262455] = "Загляньте в Старе місто — до «Казарм» або до таверни «Свиня і Свисток». Якщо завітаєте до таверни, обов’язково скуштуйте їхні чудові сорти пива. Повірте, вони затьмарюють навіть елі гномів.",  -- db:901
[717169749] = "Що ж, ви можете знайти Терідана або Мальдріна біля місячного колодязя в парку. Просто вирушайте до західної частини Штормовію, на північ від Району магів, але на захід від Соборної площі.",  -- db:902
[324999807] = "Якщо ви шукаєте інструкторів-друїдів, вам слід завітати до Парку. Терідана та Мальдріна зазвичай можна зустріти біля місячного колодязя в центрі району.",  -- db:902
[686992994] = "Ми — діти природи? Тоді вам не треба шукати нічого іншого, крім місячного колодязя в парку.",  -- db:902
[120532185] = "У Соборі Світла на Соборній площі мешкають священики Штормовію. Там ви зустрінете верховну жрицю Лаурену.",  -- db:903
[413880635] = "Лаурена — Верховна жриця Штормовію. Її можна знайти в Соборі Світла на Соборній площі.",  -- db:903
[320326534] = "Я б порадив зазирнути до Собору Світла на Соборній площі.",  -- db:903
[769702907] = "Якщо ви мрієте стати могутнім паладином, кращого наставника, ніж лорд Грейсон Тіньолом, годі й шукати. Його можна знайти в Соборі Світла на Соборній площі.",  -- db:904
[916192202] = "Торфін Стоуншилд приїхав до нас аж із Айронфорджа, щоб поділитися з нами своїм досвідом у полюванні. Якщо вас не бентежить димне повітря Кварталу гномів, то ви знайдете його в його будинку в північно-східній частині кварталу.",  -- db:905
[104684165] = "Ти — мисливець?  Ну, тоді тобі варто поговорити з Торфіном Стоуншилдом у Дварфському кварталі.  $B$BО, і не забудь сказати йому, що якщо я ще раз втручуся в справи його улюбленця, він буде навчати інших мисливців з-за ґрат у в’язниці «Стокейд»!",  -- db:905
[975865256] = "Що? Я не знаю жодного інструктора-чаклуна у Штормовії. $B$BХоча... У районі Магів, біля таверни «Забита вівця», спостерігалися випадки демонічної активності. Гадаю, ти міг би там подивитися.",  -- db:906
[867056074] = "Чаклуни, еге ж. Ну, не від мене це чули, але я чув чутки, що ці типи збираються в барі під назвою «Забита вівця» у Магічному кварталі.",  -- db:906
[297666857] = "Що привело тебе в цю частину світу, $n?",  -- db:907
[799031348] = "З кожним днем він стає все товстішим і корумпованішим. Ви можете відчути сморід, що йде від його тіла. Він брудний, і я маю на увазі не лише те, що йому треба помитися.$B$BДосить базікати, Хульфдане. Звідки ти прийшов і чим я можу тобі допомогти, $c?$b",  -- db:908
[968195045] = "Якого тренера з професійної підготовки ви шукаєте?",  -- db:918
[103937331] = "Якщо вам потрібне навчання з алхімії, у Штормовій є лише одне місце, куди вам слід звернутися... «Alchemy Needs». Ви знайдете його в Магічному кварталі, вздовж зовнішнього ряду крамниць.",  -- db:919
[219062884] = "У магічному кварталі прихована невеличка крамниця під назвою «Alchemy Needs». Проходячи через магічний квартал, ви напевно побачите безліч дивних крамниць, але якщо триматися зовнішнього краю, то обов’язково її знайдете.",  -- db:919
[11526194] = "Терум Діпфордж — це той карлик, з яким вам варто поговорити. На мій погляд, він — один із найкращих ковалів у цих краях. Ви знайдете його в самому центрі Карликового кварталу.",  -- db:920
[664351364] = "Ти хочеш сказати, що звідси не відчувається запах диму з гномівських кузень?  Що ж, якщо ти хочеш навчитися ковальству, тобі слід шукати Терума Глибококузника.  Він знаходиться у Гномівському кварталі, що розташований трохи північніше від Соборної площі.",  -- db:920
[266355577] = "Якщо ви мрієте стати чудовим кухарем, завітайте до таверни «Pig and Whistle» у Старому місті й поговоріть зі Стівеном Райбеком. Цей чоловік, як ніхто інший, вміє готувати реберця.$B$BОй... тепер я вже зголоднів і хочу скуштувати його знамениті реберця. Але не сподівайтеся, що він поділиться з вами цим рецептом!",  -- db:921
[990242078] = "У таверні «Pig and Whistle» у Старому місті працює чудовий кухар. Я бачив, як він користується ножем під час приготування їжі, і, між нами кажучи, не думаю, що він завжди був кухарем.  Не зрозумійте мене неправильно... якщо ви все-таки хочете навчитися, він — найкращий з усіх, хто у нас є.",  -- db:921
[864332890] = "Інструктором-інженером у Штормовії є винахідливий гном на ім’я Лілліам Спаркспіндл. Його можна знайти в глибині Дварфського кварталу.",  -- db:922
[366816613] = "Гей, це нагадало мені, що мені треба відремонтувати ракетні черевики. Порада, друже: ракетні черевики й грифони — погане поєднання. $B$BО, але тобі потрібні вказівки... Просто прямуй до Дварфського кварталу, там у глибині ти знайдеш Ліліам Спаркспіндл.",  -- db:922
[848107330] = "Собор Світла — це центр усіх цілительських практик Штормовію. Там ви зможете знайти Шайну Фуллер, яка допоможе вам опанувати це ремесло.",  -- db:923
[101727827] = "Немає кращого місця для навчання наданню першої допомоги, ніж під пильним наглядом Шайни Фуллер у Соборі Світла.  $B$BЩоб туди дістатися, просто шукайте жовті дахи або височенний шпиль самого собору, який видно майже з будь-якої точки міста.",  -- db:923
[718785427] = "Ви знайдете Таннісу біля магазину «Alchemy Needs» у Магічному кварталі.",  -- db:924
[369565151] = "Ніщо не зрівняється зі спілкуванням з природою... принаймні так мені кажуть нічні ельфи.  Я не дуже люблю розмовляти з квітами та деревами, але впевнений, що Танніса зможе тобі допомогти.  Вона перебуває у Магічному кварталі, біля крамниці «Alchemy Needs».",  -- db:924
[438275787] = "Хочеш навчитися обробці шкіри, так? Саймон Таннер міг би тебе цьому навчити. Його можна знайти в Старому місті, у крамниці «Захисна шкіра».",  -- db:925
[977910529] = "Тобі подобається шкіра, так?  Схоже, тобі варто поговорити з Саймоном Таннером у Старому місті.  Він там має магазин під назвою «Protective Hide».",  -- db:925
[979922878] = "Звернися до Гелмана Стоунхенда. Здається, у нього є будинок у Дварфському кварталі, але я точно не пам’ятаю. Я б подивився там.",  -- db:927
[950383132] = "Тільки гноми могли надіслати фахівця з гірничої справи з Айронфорджа, щоб той навчив нас, як копати.  Хіба так важко взяти кирку й відколупати трохи скелі?  Ну, раз він уже тут, то, мабуть, саме до нього вам і слід звернутися.  Його звати Гельман, і він мешкає у Дварфському районі.",  -- db:927
[660236903] = "Якщо ви хочете навчитися знімати шкуру, вам варто завітати до Старого міста й зазирнути до «Захисної схованки».",  -- db:928
[663819160] = "Знаєш, я міг би проткнути орка наскрізь або розрубати троля, міг би навіть викарбувати свої ініціали на боці огра, але просто не можу знести зняття шкури з тварини.  Хто б міг подумати, еге ж.  $b$bНу, якщо у вас вистачить на це сміливості, то йдіть до Маріс Грейнджер у крамниці «Захисна шкура» в Старому місті.",  -- db:928
[365041576] = "У «Duncan's Textiles» працює один із найкращих кравців Штормовію — Джорджіо Болеро. Шукайте крамницю в Магічному кварталі.",  -- db:929
[608516885] = "Кравець, так?  Ну, якщо ти пробудеш тут достатньо довго, рано чи пізно почуєш від когось про Джорджіо Болеро.  Він уже кілька місяців визначає модні тенденції.  Якщо хочеш повчитися у нього, його можна знайти в Кварталі магів на зовнішньому кільці.",  -- db:929
[567607212] = "Плакі не хоче, щоб Тірт дізнався, що він досі перебуває на Мерехтливих рівнинах, тому він перетворився на курку!$B$BЯкщо ви знайдете Плакі, помахайте йому рукою. Можливо, він вийде зі своєї схованки.",  -- db:930
[470378808] = "Сподіваюся, ти готовий до роботи.",  -- db:931
[85591186] = "Ласкаво просимо на перегони!  Приємного перебування, і не ставте всі свої гроші на одне місце!",  -- db:932
[867720853] = "Привіт, $c!  Ласкаво просимо на перегони на «Мерехтливих рівнинах»!",  -- db:932
[110220926] = "У кого найшвидша машина?  Хто знає?!?",  -- db:932
[302903899] = "Гоблін-гонщик має неабияку потужність, але гноми приховали в своїй машині кілька хитрощів...",  -- db:932
[669882185] = "Куди вам потрібні вказівки?",  -- db:933
[753694946] = "Як кішка, яку затягли з дощу, ти дряпаєшся й шкрябаєшся, а потім все повторюєш спочатку... Я ще повернуся за добавкою...$B$BОй, я не помітив, що ти зайшов, $N! Чим можу тобі допомогти? $b",  -- db:934
[672908294] = "Якщо ми хочемо заволодіти цими новими землями, нам потрібні місця, де ми зможемо відпочити після виснажливих боїв. Покладіть сокиру біля багаття й поділіться розповідями про свої славні битви.",  -- db:938
[775349620] = "Немає нічого кращого, ніж провести день на риболовлі біля Кришталевого озера. Арнольд Ліланд — саме той, хто навчив мене цьому. Зазвичай його можна зустріти на причалі в районі Канал-Дістрікт, де він просто рибалить цілий день. $B$BО, і не вірте жодній з його історій про монстрів у каналах.",  -- db:940
[923911223] = "Той ледар Ліланд? Він тільки й робить, що сидить на причалі біля Торгового району й цілими днями ловить рибу.  Сподіваюся, він у цьому справді вправний, зважаючи на те, скільки часу він цьому присвячує.  Якщо хочеш навчитися, чому б тобі не піти до нього й не поговорити?",  -- db:940
[369196246] = "У Лукана Корделла є невеличка крамниця на березі каналу біля Стокейда. Я впевнений, що він зможе навчити вас мистецтву зачарування.",  -- db:941
[424826089] = "А, ви шукаєте Лукана Корделла. Він має крамницю на околиці Чарівного кварталу, по дорозі до Стокейда.",  -- db:941
[138848413] = "Я йду цією дорогою сам, шукаючи способи захистити свою честь і позбавити цю землю від наших ворогів.$B$BЧим я можу тобі допомогти, $N?",  -- db:942
[367966991] = "Так, я бачив шаманку, яку ти шукаєш. Востаннє я бачив її на захід від цього місця. Вона ховається в горах над племенем Разормане. Якщо ви будете кмітливі, то зможете знайти стежку до її хатини в горах. Вона розташована недалеко на північ від цього місця. Ця стежка дозволить вам знайти її, не вступаючи в бій з квілбоарами.",  -- db:943
[175384545] = "Орден «Розбитої Руки» існував ще до Тралла і існуватиме й після нього.",  -- db:1038
[33705123] = "Зандо'зан із «Розбитої Руки». Чим Зандо'зан може вам допомогти? Нічим! Він не допоможе!$B",  -- db:1039
[582235764] = "Ти тут, щоб тренуватися?  Чи просто прийшов, щоб згаяти час воїна?",  -- db:1040
[824385252] = "Машина оживає від вашого дотику.",  -- db:1041
[189229731] = "Він принесе вам медовуху$bВін принесе вам пиво$bЗ посмішкою від вуха до вуха$bВін обслуговує нас усіх з року в рік$bМи називаємо його «Усміхнений Джим».",  -- db:1058
[321743569] = "Це екзотичний зразок флори, якого не зустрінеш в інших частинах Телдрасілу.",  -- db:1059
[627908489] = "Ця рослина виділяється серед звичайної флори Телдрасіля і випромінює дивне фіолетове сяйво.",  -- db:1060
[33558101] = "Вітаю.  Моє завдання полягає в тому, щоб надати вам доступ до інформації про те, як Творці створили земних істот у світі під назвою Азерот, а також, у разі можливості, допомогти вам глибше її зрозуміти.  Я готовий поділитися цією інформацією з вами зараз, коли вам буде зручно.",  -- db:1079
[487928432] = "«Земні» — це синтезована раса, створена Творцями, яка виконує роль однієї з «расових зародків» у початковому населенні світу під назвою Азерот.  «Земляни» були створені для того, щоб допомагати Творцям у формуванні глибинних регіонів цього світу.$B$BВони є модифікацією стандартної матриці підземних істот, яка використовувалася в інших світах, заселених Творцями.  Створення цієї прототипної раси призвело до виникнення різних аномалій, які були виявлені після початкового синтезу.",  -- db:1080
[533181636] = "Це одна з матриць синтезу, які Творці використовують під час заселення світу. Кожна матриця синтезу застосовується для досягнення цілей Творців.  Для Азерота матриця підземних істот була модифікована з метою створення істоти з підвищеною витривалістю та схильністю до формування глибинних регіонів; Земляни є результатом цієї модифікації.$B$BПісля того, як Земляни були задіяні на службі у Творців, було виявлено непередбачені аномалії, які впливали на їхню матрицю синтезу через умови високого навантаження.",  -- db:1081
[147985708] = "Щоб правильно відповісти на це запитання, вам необхідно надати додаткову довідкову інформацію про «Земних».$B$BОбробка.$B$BЩоб зрозуміти аномалії «Земних», насамперед важливо усвідомити, що саме «Земні» символізують у своїй концептуальній задумі.  «Земляни» уособлюють спробу Творців удосконалити парадигму виживання стандартної матриці підземних істот. Це було досягнуто шляхом включення до зазначеної матриці міцного будівельного фундаменту, властивого цьому світу.",  -- db:1082
[342800731] = "Це базовий матеріал, що використовується для синтезу рас.  Основою для синтезу Земляних послужив зріз земної кори Азерота, а не типова основа з біомаси, яку зазвичай використовують Творці.$B$BДослідження складу світу привели Творців до гіпотези, що можна синтезувати вдосконалену істоту, яка уособлюватиме стійкість сутності цього світу.  Це було досягнуто завдяки використанню суміші різних сполук кам'яного ядра Азерота як основи.",  -- db:1083
[78514959] = "Простіше кажучи, це вірно.$B$BФізичні особливості Землян відповідають гуманоїдам невеликого зросту, хоча їхня будова складається з різних сполук кам’яного ядра Азерота. Їхня будова забезпечує максимальну силу та витривалість без шкоди для когнітивних здібностей.  Їхня шкіра та м’язи майже непіддатні фізичним ушкодженням, а завдяки незначним модифікаціям Земляни демонструють надзвичайну стійкість до небажаних магічних сил.",  -- db:1084
[539373891] = "Для усвідомлення цих даних важливо розуміти, що Творці прагнули створити расу, яка б і після їхнього відходу надовго стала невід’ємною частиною циклу розвитку цього світу. Ця раса мала відіграти ключову роль у реалізації довгострокових цілей Творців щодо розвитку Азерота.  $B$BДо речі, Творці визнали назву «Земляни» доречною для нової раси, виходячи з її складу.",  -- db:1085
[930639751] = "Єдина аномалія «Землянина» під час синтезу полягає у схильності матриці до дестабілізації під час експлуатації в умовах високих навантажень.$B$BДодаток: глибоке моделювання землі природним чином відповідало новій конструкції матриці, а тому ніколи не відповідало критеріям, необхідним для відтворення умов високих навантажень.$B$BДестабілізація була виявлена лише на пізній стадії основного циклу експлуатації «Землянів» для Творців. Творці розпочали роботу над модифікацією після синтезу, а не над відкликанням та повторним синтезом.",  -- db:1086
[865763581] = "[Після того, як ви задали це питання, настає помітна пауза.]$B$BІнформація, яку ви запитуєте, наразі недоступна в циклі оновлення даних цього сховища.  Я щиро вибачаюся за це упущення.$B$BБудь ласка, зверніться за цією інформацією після оновлення циклу даних у цьому сховищі.  Ви також можете звернутися за цією інформацією до іншого сховища, розташованого в Азероті.",  -- db:1087
[368597851] = "Існує два можливі результати, коли матриця синтезу Землянина дестабілізується.  Запускаємо візуальну ілюстрацію № 1.$B$BПерший варіант матриці є дегенеративним продуктом синтезу, який відтепер позначається загальноприйнятою назвою «Трогг».  Цей варіант зберігає силу та витривалість, порівнянні з Земним, але його когнітивні здібності майже повністю порушені. Сила волі та гострий розум — єдині рушійні сили в психіці трога.",  -- db:1088
[357951835] = "На жаль, я не можу обробити вашу хронологічну посилання у порівнянні із записами цих даних, прошу вибачення.$B$BТрогг зберігає певний склад різних кам’яних сполук Азерота, але втрата когнітивних здібностей робить цей варіант неприйнятним для Творців.$B$BТрогг розмножується як стандартна біомаса.  За замовчуванням він споживає камінь та все інше, що може здобути, включаючи інших трогогів.  Канібалізм вважається Творцями неприйнятним.",  -- db:1089
[618694032] = "Запуск візуального зображення № 2.$B$BДруга похідна варіація матриці «Земля» зберігає багато бажаних елементів у порівнянні зі стандартною підземною матрицею.  Загальноприйнята назва цього варіанту — «Карлик».$B$BЦей варіант зберігає силу та витривалість, властиві матриці «Земля».  У деяких випадках «Карлик» навіть перевершує когнітивні здібності матриці «Землянина».  Однак «Карлик» не зберігає жодних фізичних властивостей різних кам’яних сполук Азерота.",  -- db:1090
[810337469] = "Дані, що зберігаються в цьому репозиторії, дійсно узгоджуються з вашим влучним припущенням.$B$BКарлик зберігає спорідненість із кам’яним складом Азерота, але через аномалію навколишнього середовища з високим рівнем напруги в матриці синтезу Земних істот він повертається до стандартного складу біомаси, як це спостерігається у типовій підземній матриці.$B$BОтже, варіант карлика дійсно синтезується в результаті дегенерації матриці створення Земних, як ви й припустили у своєму запиті.",  -- db:1091
[701602879] = "На жаль, я не можу обробити вашу хронологічну посилання у порівнянні із записами цих даних, прошу вибачення.$B$BХоча карлик зберігає більшу частину ментальної гармонії землян із кам’яним складом Азерота, повернення до стану живої біомаси залишається основною дегенерацією матриці.  Карлики харчуються та розмножуються типовими для інших стандартних форм біомаси способами.$B$BТворці розглядають карликів як прийнятний варіант, гідний самостійного створення.",  -- db:1092
[753016763] = "Творці — це... Творці.$B$BЦе істоти, які за своїм задумом зародили та сформували цей світ.  Саме вони є причиною існування цього світу, а також багатьох інших світів.  Вони — джерело, з якого походить Азерот.",  -- db:1093
[965147205] = "Творці усвідомлюють масштабність інформації, що зберігається в цьому сховищі.  Відповідно, переносна копія даних, що зберігаються тут, буде надана вам, щойно ви налаштуєтеся на Диски Норганнона.$B$BВважайте, що ваші початкові вимоги щодо засвоєння цих знань виконано.  У зручний для вас час зверніться до «Дисків Норганнона», щоб розпочати синтез ваших дисків.",  -- db:1094
[570646913] = "То ти хочеш стати ковалем, так? Одягай фартух і бери молоток, хлопче : дівчино;, подивимося, на що ти здатний.",  -- db:1118
[816158970] = "Я вже багато років $N не бачив кращої броні. З тих пір, як навчався у Грумнуса Стілшепера у Великій Кузні. Готовий побитися об заклад, що він міг би навчити тебе дечому про виготовлення броні, що неодмінно зацікавило б тебе.",  -- db:1119
[922457963] = "Якщо ви хочете знайти Грумнуса, то перш за все вам слід вирушити до Айронфорджа. Ідіть у самий центр міста й шукайте Велику Кузню — там ви його й знайдете.",  -- db:1120
[544467323] = "У тебе, $N, справді вражаюча майстерність. Леза та молотки, які ти виготовляєш, перевершують навіть мої власні — як би мені не було важко це визнати. Єдина людина, яку я коли-небудь зустрічав і чия майстерність ще вища, — це Боргус Сталерукий. Готовий побитися об заклад, що він міг би навчити тебе дечому.",  -- db:1121
[472424062] = "Хочеш потренуватися з Боргусом? Так, я можу підказати, де його знайти. Пройди через площу на північний захід від моєї кузні, а потім рухайся західною дорогою. Ти знайдеш його у другій будівлі праворуч.",  -- db:1122
[249171674] = "Вплив «Розбитої Руки» панує на цих землях. Ми — завіса, що вкриває Калімдор: протекторати, поліція, судді, присяжні і, зрештою, кати. Ми бачимо все, ми знаємо все.$B$BТи значно зріс за той час, що провів на службі у «Руці», $N. Настав час відправити тебе на завдання.$B$BЧи готовий ти взятися за наступне завдання?$B",  -- db:1124
[491945600] = "Ласкаво просимо до Великої Кузні, хлопче : дівчино;. Надворі, можливо, й холодно, але тут, внизу, у нас затишно й тепло. Бери молоток, бий по ковадлу й доведи мені, що ти гідний стати ковалем Великої Кузні!",  -- db:1127
[200185170] = "Гарна форма, $N. Ставлю цілу кружку в «Bruuk’s Corner», що функція така ж надійна. Знаєш, тобі, мабуть, варто поговорити з Міолором Сандерфюрі. Він тебе просвітить.",  -- db:1128
[606349936] = "Звісно, я можу показати тобі, де знаходиться Мійол. Ось там, біля ковадла Великої Кузні — саме там він працює. Уважно слухай його слова, хлопче/дівчино: Мійол — майстер найвищого класу.",  -- db:1129
[746708198] = "Ви маєте моє схвалення, $N. Ви куєте мечі краще, ніж будь-хто з тих, кого я навчав за останні роки. Але якщо ви хочете виготовити справжню зброю, вам слід поговорити з Міолором Сандерфюрі. Цей гном направить вас на правильний шлях.",  -- db:1130
[623736828] = "То що, йдемо до Мійола, так? Він ось там... позаду тебе! Е-е, а може, і попереду! Біля Великого Ковадла!",  -- db:1131
[635148626] = "Щось турбує цю вежу. Я захворів, і інші співробітники «Venture Co.», які працюють поруч із вежею або в ній, також захворіли.$B$BЛише минулого тижня двоє наших патрульних загинули, але миттєво повернулися до життя у вигляді бездумних дронів!$B$BЖиттєва сила витікає з мого тіла. Я відчуваю, як втрачаю контроль. Мене охоплюють потяги... Погані потяги... *Фізул дає собі ляпаса по обличчю* Ще не час... Послухай... Я займаю впливову посаду. Ця посада дає мені доступ до певної конфіденційної інформації.",  -- db:1132
[562650709] = "Ви що, з глузду з’їхали? Це ж не зброя, а обідній ніж. Я не треную аматорів.",  -- db:1133
[558539111] = "Ви мене за це докоряєте? Краще б ви прив’язали до спини мертвого кролика й пробігли через лігво троля, ніж носили б це сміття.",  -- db:1135
[756853745] = "$N, так? У тебе вийшла справді чудова робота. Я візьму тебе до себе і навчу, як виготовляти обладунки, гідні самого короля Магні.",  -- db:1136
[966842316] = "Приблизно п’ять місяців тому підрозділ «Стренглторн» компанії «Venture Co.» отримав у свої руки особливу отруту від сумнівного торговця з Буті-Бей на ім’я Кранк Фізлбаб. Фізлбаб, судячи з усього, вкрав цю отруту у Занзіла!$B$BТак, саме у Занзіла Вигнанця — троля, якого вигнали з власного племені через характер його «експериментів» у некромантії.$B$BЗвісно, що, отримавши отруту, вони одразу ж почали випробовувати її один на одному. Результати виявилися катастрофічними.",  -- db:1138
[500606269] = "Головний майстер Пузік Галлівікс нарешті втрутився, забравши надлишки отрут до своєї вежі, що тут, у Болоті Сладж, щоб вивчити та дослідити нестабільну природу цих токсинів. Зрештою було прийнято рішення поділитися секретом отрути з Братством Дефіас в обмін на дуже великий запас стабільної, придатної для використання отрути.$B$BКлавену Мортвейку з Братства Дефіас було доручено завдання змінити хімічні властивості суміші Занзіла.",  -- db:1158
[262447218] = "Перенесімося у сьогодення: отримана формула працює, що дозволяє створити дрон, який краще піддається контролю, однак недоліком є те, що неактивна сполука надзвичайно летка.$B$БГаллівікс, усі в цій вежі та всі зовні заражені отрутою. Вона впливає на наш розум і тіло. Наші внутрішні органи стали м’якими та надзвичайно крихкими. Це твій шанс, $N. У мене вже немає сил продовжувати, і я відчуваю, що незабаром стану одним із «них».",  -- db:1159
[970909365] = "Зараз оборонні сили вежі найслабші. Патрульні, вартові, спостерігачі і навіть сам Галлівікс — усі вони заражені й надзвичайно вразливі до твоїх спеціальних здібностей та атак.$B$Я хочу побачити, як ти увійдеш у ту вежу, а коли вийдеш — хочу бачити тебе вкритого кров’ю ворогів, з головою головного майстра Пузіка Галлівікса в руках і останніми залишками отрути у рюкзаку. Віднеси все, що знайдеш, до Шентула. Він знатиме, що з цим робити... Сподіваюся.$b",  -- db:1160
[134274301] = "Сподіваюся, що ви перервали мене з поважної причини, адже я саме був у розпалі важливої роботи.",  -- db:1202
[35502911] = "Ще один травник, хм. Сумніваюся, що твої навички такі ж високі, як мої, тож, можливо, я зможу навчити тебе кільком правильним прийомам.",  -- db:1203
[386502571] = "А, колега-рибалка. Може, тобі не завадило б трохи потренуватися? Можливо, я зможу навчити тебе чомусь?",  -- db:1205
[330506671] = "Ласкаво просимо до Штормовію. На її відновлення пішло чимало часу, але це було того варте. То ти просто приїхав у гості чи у справах?",  -- db:1206
[712082218] = "До мене не так вже й багато кухарів приходить, щоб пройти навчання, але, гадаю, я міг би чогось тебе навчити, якщо ти готовий.",  -- db:1207
[189532542] = "Хіба я виглядаю так, ніби маю час чи сили, щоб бавитися з кожним туристом, який заходить до мене? Скажіть, що вам потрібно, і робіть це швидко.",  -- db:1208
[174840465] = "До мене не так вже й багато Скіннерів приходять, щоб потренуватися, але, гадаю, я міг би чогось тебе навчити, якщо ти готовий.",  -- db:1210
[999076874] = "Можливо, великі війни поки що закінчилися, але нам все одно треба підтримувати свої навички на високому рівні!",  -- db:1215
[493352575] = "Штормовій — це опора людства, що тримається завдяки силі волі та гостроті міцного меча.",  -- db:1216
[269678822] = "Вітаю.  Ви бажаєте навчитися військовому мистецтву?",  -- db:1217
[102800057] = "Вітаю.  Ви бажаєте навчитися мистецтву війни?",  -- db:1217
[371592366] = "Скільки б людина не вчилася, завжди є що ще дізнатися.",  -- db:1218
[352164345] = "Роль воїна полягає в захисті. Так само, як ми захищаємо своїх співвітчизників у бою, ми повинні також захищати інтереси Покинутих.",  -- db:1219
[68284368] = "О, колега-лікар. Я з радістю навчу вас усьому, що може стати в нагоді під час ваших подорожей.",  -- db:1220
[208708000] = "Так, мій $g сину : донько;? Чим я можу тобі допомогти?",  -- db:1221
[982095348] = "Я приїхав з Айронфорджа, щоб допомогти з відновленням міста. Якщо мені вдасться навчити достатню кількість з вас своїм навичкам, то, можливо, я зможу доручити цю справу вам і повернутися додому.",  -- db:1225
[327133584] = "Так? Ти мене перервав, тож тобі краще мати для цього дуже вагому причину.",  -- db:1226
[523451296] = "Вітаю, $N.",  -- db:1228
[290915901] = "З часу падіння Даларана та руйнування Квель'Таласа товари такого роду стало важко дістати. Проте Лукан Корделл та деякі інші наші торговці чудово справляються з виконанням наших замовлень, постачаючи якісний товар.",  -- db:1231
[411889456] = "Я продаю лише найкраще магічне спорядження, виготовлене майстрами та магами тут, у місті Штормовій.",  -- db:1231
[19243717] = "Виготовлено найкращими майстрами усього Телдрасіля, перевезено вручну з Калімдору до Азероту як знак зміцнення союзу між народом Великого Дерева та людьми цієї землі. Якщо вам щось знадобиться, просто скажіть.",  -- db:1233
[440408368] = "Найкращі пропозиції у всьому Штормовій, друже, кращих ти не знайдеш. Тож, чим можу тобі допомогти?",  -- db:1235
[50181719] = "Ви просто переглядаєте мій асортимент чи, можливо, вам потрібно знайти щось конкретне?",  -- db:1235
[982516437] = "Я продаю лише найкраще спорядження, перевірене й надійне. Ціни фіксовані, тож якщо хочете торгуватися — йдіть шукайте гобліна.",  -- db:1238
[277550343] = "Нехай світло освітлює ваш шлях і допомагає вам у подорожах. Якщо вам знадобиться допомога з навігацією, я буду тут поруч.",  -- db:1241
[980592935] = "Нехай світло освітлює ваш шлях і допомагає вам у ваших подорожах. Якщо вам знадобиться допомога з навігацією по сайту, я завжди поруч.",  -- db:1242
[641632026] = "Не дай людям на Базарі обдурити тебе, хлопче $g : дівчино;, завдяки метро, яке побудували ті гноми, перевозити товари з Айронфорджа простіше, ніж ти можеш собі уявити. Якщо вони спробують накинути імпортні збори, просто скажи їм, що купуватимеш спорядження в мене.",  -- db:1243
[214296682] = "Якщо вставити виступ А в отвір Б, то, звісно, пролунає БУМ! Ось, давай я тобі покажу, що у мене є, а потім ти зможеш запитати Ліліам, як це зібрати, щоб нічого не вибухнуло.",  -- db:1249
[818303721] = "Звідси ще ніхто нічого не крав. Ніколи за всю історію... за всю історію!",  -- db:1250
[343944446] = "Ласкаво просимо до Банку Штормовію. Ми пропонуємо відкриття фінансових рахунків та оренду сейфів для зберігання цінних речей. Чи маєте Ви вже рахунок у нашому банку, $g пане : пані;?",  -- db:1250
[80629179] = "Ласкаво просимо до «Блу Реклюз», де любителі магії збираються, щоб розвіятися. Хоча, звичайно, не в буквальному сенсі. Чим можу вам допомогти, $g, пане : пані?",  -- db:1252
[116862686] = "Послухай моєї поради: не сідай близько до тіней.",  -- db:1253
[154503200] = "Ласкаво просимо до «Pig and Whistle»! Візьми собі випивку, друже, і сідай — чим більше нас, тим веселіше!",  -- db:1254
[828140683] = "Ми — єдиний постачальник корисних для здоров’я квітів у всьому Штормовій. Ми пропонуємо чудові квіти на будь-який випадок.",  -- db:1255
[559260568] = "Куди б ти хотів поїхати, хлопче : дівчино? За кілька монет мої грифони доставлять тебе туди швидше, ніж навіть найшвидший кінь.",  -- db:1256
[143105730] = "Ці величні звірі знають стежки, які ви не зможете знайти пішки; вони швидко довезуть вас до місця призначення і, можливо, водночас покажуть вам щось нове.",  -- db:1256
[54354659] = "Говоріть тихо й дуже обережно — одне неправильне слово в цих краях може коштувати вам життя. Тож, що вам від мене потрібно?",  -- db:1257
[456861707] = "Ласкаво просимо до офісу Реєстру гільдій Штормовію. Чим я можу вам допомогти сьогодні?",  -- db:1259
[172942777] = "Сподіваюся, ти не проїхав весь цей шлях до Великої Кузні лише для того, щоб зігрітися. Говори голосніше, хлопче чи дівчино, скажи, чим я можу тобі допомогти?",  -- db:1261
[913639296] = "Ти маєш вигляд справжнього коваля. Сажа під нігтями, сталь у кістках. Так, у твоїх жилах тече кров коваля. А це означає, що ти прийшов до мене, щоб навчитися чомусь новому, тож, хлопче : дівчино, бери молоток. Подивимося, чого я зможу тебе навчити.",  -- db:1262
[421174976] = "Що ви шукаєте?",  -- db:1272
[212681282] = "Крумн — це той бик, якого ви шукаєте. Його можна знайти на нижньому пагорбі біля Центру громадської інформації «Грім-Скеля».",  -- db:1291
[66361736] = "Спільнота однодумців може стати потужною силою. Крумн допоможе вам це досягти. Ви знайдете його в Громадському інформаційному центрі Громового Утвору, на нижньому пагорбі поруч із підйомниками.",  -- db:1291
[447271396] = "Банк «Грім-Блафф» розташований на нижньому пагорбі.",  -- db:1292
[222219274] = "Ви можете позбутися своїх матеріальних цінностей у банку «Громовий Уступ», що розташований на нижньому пагорбі.",  -- db:1292
[665348097] = "«Гніздо Вершників Вітру» розташоване на вершині тотемних сходів у центрі міста.",  -- db:1293
[734309641] = "Ах, якби ж можна було злетіти разом із великими птахами неба. Знайдіть Тала на вершині «Гнізда Віндер-Райдерів». Він вкаже вам шлях до місця, куди ви прямуєте.",  -- db:1293
[128479824] = "Знайдіть Турака Рунетотема в Залі Старійшин на Пагорбі Старійшин.",  -- db:1294
[42838012] = "Вітаю, шановний. Турак Рунетотем та інші друїди чекають на вас у Залі Старійшин на Пагорбі Старійшин.",  -- db:1294
[66673551] = "Ага, тоді тобі доведеться вирушити до Залу мисливців. Там, на «Мисливському пагорбі», можна зустріти кількох видатних мисливців, таких як Холт Грімрог.",  -- db:1295
[609596894] = "Кожен, хто любить тварин, — мій друг. «Зал Мисливців» — саме те, що ти шукаєш. Він розташований на вершині Мисливського пагорба.",  -- db:1295
[452537604] = "Ти — послідовник таємних наук?  Хм!  Ну що ж... Ти знайдеш їх біля «Басейнів бачення» під «Духовним піднесенням».",  -- db:1296
[932928549] = "Дуже сумно думати про те, що сталося з цими бідними неживими душами.  Ви можете знайти архімага Шимма, який занурився в роздуми біля «Басейнів прозріння» під «Піднесенням духів».",  -- db:1296
[857279360] = "Вам слід поговорити саме з отцем Коббом. Його можна знайти під «Сходженням Духу» у печері «Басейни Бачення».",  -- db:1297
[354759575] = "Незважаючи на свою трагедію, Немертві проклали весь цей шлях, щоб допомогти нам. Я лише сподіваюся, що ми зможемо бути для них такими ж корисними. Знайдіть отця Кобба біля «Басейнів бачення» під «Духовним піднесенням».",  -- db:1297
[172114899] = "«Зала Духів» — це місце, яке наші шамани називають своїм домом.  Її можна знайти на «Духовому пагорбі».  Нехай ваші предки бережуть вас.",  -- db:1298
[867743817] = "Мати-Земля кличе, і ти відповідаєш. Ти знайдеш Залу Духів на Духовному Пагорбі.",  -- db:1298
[238001460] = "Мрієте колись приєднатися до наших лав?  Сарк Рагетотем може допомогти вам на цьому шляху.  Він перебуває в Залі Мисливців.",  -- db:1299
[32699542] = "Сильний тілом і духом.  Немає сильнішого поєднання!  Знайдіть своє призначення разом із Сарком Рагетотемом у Залі Мисливців.",  -- db:1299
[756612725] = "Якого тренера ви шукаєте?",  -- db:1300
[380556166] = "Яка професія?",  -- db:1301
[735022520] = "Це захоплююче... Я чув, як орки називали запах людей огидним, і чув, як люди називали запах орків жахливим; проте для мене всі раси цих земель випромінюють один і той самий запах: огидний, запаморочливий запах жадібності.$B$BВи сумніваєтеся в правдивості мого твердження? Хіба ви не бачите, що ці речі, які керують вашим життям, — лише побічний продукт тієї жадібності, яка диктує кожне ваше рішення?$B$BХай буде так. Як саме жадібність вигнала мене з дому, так і жадібність поверне мене туди.",  -- db:1302
[9486895] = "То ти повернувся, щоб допомогти Куміші, $r? Не хвилюйся, той біль, який ти відчуваєш у шлунку, — це лише твоя сила волі, що зникає.$B$BНа щастя, для цього завдання тобі не знадобиться сила волі. Я впевнений, що тобі сподобаються дрібнички, які я підготую для тебе, коли ти повернешся з цим предметом.",  -- db:1303
[188475008] = "Потім вирушайте до «Алхімії Бени», що розташована на середньому пагорбі, і поговоріть із самою Беною.  Вона допоможе вам опанувати мистецтво приготування зілля.",  -- db:1332
[595984978] = "Трави, що ростуть у природі, можуть стати потужним союзником, якщо ставитися до них з повагою. Щоб продовжити своє навчання, вам варто відвідати Бену в її алхімічній крамниці на середньому пагорбі.",  -- db:1332
[509581265] = "Хочеш навчитися працювати з ковадлом і молотком, так?  Карн Стоунхуф може тебе цьому навчити.  У нього є кузня на нижньому пагорбі біля ставка.",  -- db:1333
[341065195] = "Метал, як і все інше, слід використовувати, дотримуючись рівноваги з природою.  Карн Стоунхуф має кузню біля ставка на нижньому пагорбі.  Зверніться до нього за порадою.",  -- db:1333
[799506742] = "У Тандер-Блаффі немає кращого кухаря, ніж Аска Містраннер.  Мммм, я навіть звідси відчуваю запах того, що вона готує.  Загляньте до її кухні, яка розташована на верхньому поверсі.$b$bЧорт... тепер я зголоднів.",  -- db:1334
[341086860] = "Ви вшановуєте духів тварин, яких мусите вбити, не даючи їх піти намарне. Аска Міструнер покаже вам, як це зробити. У неї є кухня на верхньому поверсі.",  -- db:1334
[510225451] = "Тоді загляньте до «Зачарувальників Доунстрайдерів» на середньому пагорбі. Тег із задоволенням допоможе вам усім, чим зможе.",  -- db:1335
[586501371] = "Професія «Зачарування» відображає цикл руйнування та творення, що лежить в основі природи. Тег із гільдії «Зачарувальники Світанкового Стрибуна», що розташована на середньому пагорбі, покаже вам, як це робити.",  -- db:1335
[797349630] = "Вміння надавати першу допомогу завжди стане в нагоді.  Не раз під час бою це рятувало мені життя.  Завітайте до «Духовного зцілення» на горі Спірит-Райз.  Панд Стоунбайндер може навчити вас усьому, що потрібно знати, щоб і вам вдалося врятувати своє життя.",  -- db:1336
[911652306] = "Життя — це боротьба, і вислів «те, що не вбиває, робить сильнішим» не завжди є правдивим. Іноді рани загоюються повільно, саме тому у нас є бинти. Панд Стоунбайндер із «Духовного піднесення» може навчити вас мистецтву надання першої допомоги.",  -- db:1336
[309539093] = "Не дивно, що ти захопився риболовлею. У Мулгорі знаходяться одні з найкращих місць для риболовлі в Південному Калімдорі, а в магазині «Mountaintop Bait & Tackle», що на високому пагорбі, є все необхідне спорядження, щоб цим скористатися.    Скажи Ка Містрраннеру, що це я тебе прислав!",  -- db:1337
[663190116] = "Ка Міструнер із магазину «Mountaintop Bait & Tackle», що розташований у багатоповерхівці, покаже вам, як знайти внутрішній спокій і умиротворення під час риболовлі, готуючи собі наступний обід.",  -- db:1337
[44489020] = "Тоді вам варто поговорити з Коміном Вінтерхуфом із «Holistic Herbalism». Його можна знайти на середньому поверсі.",  -- db:1338
[432903313] = "Природа дає нам усе, що нам потрібно. Зверніться до Коміна Вінтерхуфа в «Holistic Herbalism», що розташований на середньому ярусі.",  -- db:1338
[109547655] = "Тоді загляньте до Уни в майстерні зброярів у Громовому Утворі. Вона розташована на середньому пагорбі.",  -- db:1339
[95619772] = "У ідеї, що шкура твого ворога може стати для тебе захистом, є певна симетрія. Щоб удосконалити свої навички кожевенного ремесла, знайди Уну в майстерні зброярів «Громового Уступу», що розташована на середньому пагорбі.",  -- db:1339
[941192669] = "Брека Стоунхуфа можна знайти в «Стоунхуф Геолоджі» на нижньому пагорбі; він може навчити вас, як правильно добувати дорогоцінні руди та самоцвіти.",  -- db:1340
[2045721] = "Мати-Земля приховує безліч таємниць, і Брек Стоунхуф допоможе вам розкрити деякі з них. Ви знайдете його на нижньому пагорбі біля компанії «Стоунхуф Геолоджі».",  -- db:1340
[851990008] = "Тепа відома своїми ткацькими виробами. Її можна знайти в майстерні «Броневики Грім-Скелі» на середньому рівні.",  -- db:1341
[799647214] = "Одягати членів племені — це така ж важлива робота, як і будь-яка інша.  Вам слід пошукати Тепу в майстерні зброярів у Громовому Утворі.  Вона має природний талант до роботи з голкою.",  -- db:1341
[150594345] = "Муранта може допомогти вам навчитися знімати шкури. Її можна знайти біля майстерні зброярів у Громовому Утворі, на середньому уступі.",  -- db:1343
[673266270] = "Кожен використаний клаптик робить нас менш марнотратними та наближає нас до Матері-Землі. «Мооранта» може вказати вам шлях. Шукайте її біля майстерні зброярів у Громовому Утворі, на середньому пагорбі.",  -- db:1343
[585618352] = "Звірі цих проклятих земель мають надприродні властивості, яких досі не зустрічалося в природі.$B$BМи висунули гіпотезу, що енергія, яка вивільнилася під час відкриття Темного порталу, проникла в їхні тіла й змусила цих істот еволюціонувати до їхніх нинішніх форм.$B$BЦе, без сумніву, жахливі звірі, але ми також вважаємо, що вони можуть виявитися досить корисними для наших досліджень.$B$BМожливо, вам буде цікаво допомогти нам у дослідженні цих звірів, $N?$B",  -- db:1351
[881210839] = "У той час як мій брат, Дразіал, зосереджує свій аналіз на фізичних особливостях звірів спустошених земель, я, як правило, приділяю увагу інтелектуальним та духовним аспектам дикої природи.$B$BДійсно, ці звірі демонструють надзвичайно незвичайну силу, спритність і витривалість, але деякі з них також володіють великим інтелектом і здатністю до регенерації, що не пов’язані з їхньою фізичною сутністю.$B$BМожливо, вам буде цікаво допомогти мені у моїх дослідженнях, $r?$B",  -- db:1371
[918571977] = "Важко уявити, що стільки смерті й відчаю може вміститися на такій невеликій території; проте за болотом розкинулася земля, охоплена хаосом і руйнуванням.$B$BБудь обережним, мандрівнику. «Спустошені землі» — це місце останнього спочинку істот, набагато могутніших за тебе.",  -- db:1391
[192769271] = "«Залізна Хватка Тралла» — так нас називали: двадцять найдосвідченіших і найшанованіших воїнів Тралла.$B$BЯ віддав наказ полку розбити табір тут, на кордоні Зруйнованих Земель, поки ми чекали на накази з Оргримара. Минали тижні, а від вождя не було жодної звістки; бійці ставали дедалі неспокійнішими.$B$BЦе було рішення, прийняте на власний розсуд, $N. Я був молодим і амбітним, нічого не боявся. Батальйон мав вирушити в Спустошені землі під моїм командуванням.$B$BРішення, про яке я згодом пошкодував.",  -- db:1392
[677773073] = "Жаль. Це все, що у мене залишилося. Одне неправильне рішення призвело до низки жахливих наслідків. Якби ж я дочекався тих наказів! Можливо, у них би детально описувалися ті жахи, що чекали на нас у тих проклятих краях! Можливо, нас мали перенаправити на інше завдання? Зрештою, це була моя вина. Усе це — моя вина.",  -- db:1411
[890308901] = "Чи повірите ви, що в найчорнішу годину, на вершині свого існування, я зазнав поразки.$B$BКоли я втікав від безжального руйнування з боку сил, що нас перевершили, єдиними звуками, які я міг чути, були крики моїх воїнів і прискорене биття мого власного серця.$B$BНезабаром я повернувся до Спустошених Земель, сподіваючись врятувати своїх людей і відновити свою честь. Натомість мене полонили й били до смерті.$B$BТе, що я дізнався під час допиту та подальших тортур, було жахливим.",  -- db:1451
[945561371] = "Мої викрадачі були неймовірно жорстокими, $N. Вони по черзі катували то лейтенанта Кіріта, то мене — одного з нас, поки інший спостерігав. Під час перерви в діях того особливо жорстокого дня Кіріт розповів мені, що сталося з моїми людьми, і про план, який він розробляв, щоб звільнити їх від їхніх господарів.$B$BЇх спіткала доля, набагато гірша за смерть, чи навіть за той біль, який ми з Кірітом  перенесли.",  -- db:1452
[752765912] = "Ні ви, ні я не можемо навіть уявити, який біль відчуває людина, коли її душу виривають із тіла. Вони не мертві, але й аж ніяк не живі. Натомість вони блукають по землі, будучи слугами тих, хто прив’язує їх до цього світу.$B$BЛорд Разеліх, демонічний володар цих земель, поневолив їх усіх. Дев’ятьох він забрав собі, розмістивши камені прив’язування поблизу Темного Порталу. Решту дев’ятьох було розподілено між його підлеглими.",  -- db:1453
[879103808] = "Архімаг Алістардж із «Присяжних Тіні» отримав три. Леді Севін, чаклунка з «Присяжних Тіні», також отримала три. Решту три отримав Грол Руйнівник, володар огрів «Страшного Молота» з цих спустошених земель.$B$BРозумієш, $N, без душі тіло не можна вбити. Те, що залишилося від моїх людей, тепер є незнищенними бойовими одиницями. На щастя, камені прив’язування обмежують відстань, на яку вони можуть подорожувати.",  -- db:1454
[836121338] = "Саме їх тобі й треба знищити, щоб звільнити полк! Як я вже казав тобі раніше, у Кіріта був план.$B$BУ кожного зі слуг є слабке місце. Наносьте удари по їхніх тілах поблизу каменів, доки вони не опиняться на межі розпаду. Саме в цей момент, і тільки в цей момент, камені, що їх сковують, стають вразливими до атак. Однак ти повинен поспішити знищити камені, бо щойно поневолені відновлять самоконтроль, вони знову стануть невразливими до будь-якої шкоди.",  -- db:1455
[409323738] = "Якби ж це було правдою, $N, але щоб перемогти сили Разеліха та його підлеглих, одних твоїх сил буде замало.$B$BЗбери гідну групу шукачів пригод і майбутніх героїв та звільни моїх людей від вічних мук! Ти повинен розбити вісімнадцять каменів.$B$BБийся відважно і помри з честю, $N.",  -- db:1456
[356144491] = "Тобі потрібні матеріали для алхімії, чи не так?  Або ти прийшов до мене з іншою справою?",  -- db:1471
[133927886] = "Жити тут, у пустелі, — це нелегко! Я так хочу пити, коли стою на вулиці в таку спеку.",  -- db:1493
[985591224] = "Допоможіть!$B$BЯкщо ви мене звідси витягнете, я зможу підірвати двері, що ведуть до ватажка Зул’Фаррака!",  -- db:1511
[104365187] = "Ми маємо вбити ще більше тролів!  Вбийте їх достатньо — і я підірву двері до лігва вождя тролів!",  -- db:1513
[11529052] = "Дякую, $N. Якби ти не з’явився, я впевнений, що ми б уже були мертві! Тепер єдине, що стоїть між нами та головним тролем, — це ті двері он там...",  -- db:1514
[669188650] = "Допоможіть!  Мене та мою групу захопили тролі, і вони збираються принести нас у жертву!$B$BВитягніть нас звідси, і я дам вам усе, що забажаєте.",  -- db:1515
[631486519] = "У нас немає часу на розмови!  Треба подумати про тих тролів!",  -- db:1516
[541335076] = "Дуже дякуємо, $N.  Без тебе ми б не впоралися.  А, і якщо я раніше згадував щось про те, щоб віддячити тобі за те, що ти нас врятував, то... можеш про це забути!",  -- db:1517
[959964229] = "Привіт! У мене є пропозиція для такого шукача пригод, як ти, якщо ти готовий прийняти виклик!$B$BЗа допомогою свого винаходу, «Супер-Егг-О-Матика», я наполегливо працюю, допомагаючи друїдам у їхній кампанії з порятунку гіпогрифів. На цих птахів чинять згубний вплив огри Гордунні, що мешкають у руїнах Фераласа, і їхня чисельність стрімко зменшується.$B$BЯ збираю багато різних видів яєць. Чи допоможеш ти мені й знайдеш для мене кілька?",  -- db:1519
[877667157] = "У місці під назвою Фералас, що на захід від нас, гіпогрифи — давні супутники нічних ельфів — опинилися в небезпеці.$B$BМені потрібно, щоб ти врятував яйце з руїн Ісілдієна, що на півдні, ось там. «Супер-Яйце-Матик» може проаналізувати будь-яке яйце, яке йому принесуть, і визначити, чи є ймовірність, що воно вилупиться. Потім я відправляю яйця до друїдів, де вони будуть у безпеці від темної магії огрів Гордунні.$B$BЗверніть увагу, $N, що деякі з врятованих яєць є зіпсованими і ніколи не вилупляться.",  -- db:1521
[30284108] = "Привіт, $N! Якщо ти не бачиш цього товару в моєму магазині, є велика ймовірність, що я зможу його дістати!",  -- db:1571
[125575395] = "Так далеко від Айронфорджа не часто зустрінеш ковалів. Чим можу тобі допомогти?",  -- db:1597
[193624676] = "Я ніяк не можу почуватися комфортно, якщо над головою немає міцного гранітного даху. Усі ці зірки там, нагорі, — їх так багато, що аж мурашки по шкірі бігають.",  -- db:1598
[723979342] = "Ось це справді шматок сталі, який варто носити. І форма, і функціональність, хлопче/дівчино, я вражений. Лише раз бачив щось подібне — майстра у Великій Кузні на ім’я Грумнус Сталеформер. Готовий побитися об заклад, що з тих пір він дечому навчився, тож, мабуть, міг би дечому навчити й тебе.",  -- db:1599
[526088600] = "Зайдіть до Великої Кузні, що розташована в самому центрі Айронфорджа. Він працює там разом з іншими майстрами нашого роду.",  -- db:1600
[403233826] = "Ласкаво просимо до моєї кузні, Ковалю. Дозволь мені відкрити тобі маленький секрет. Нікому, нікому у світі не можна довіряти. Ні чоловікам, ні жінкам, ні звірам… Ось чому ти можеш довіряти — Сталі.",  -- db:1605
[728563543] = "Чого ти шукаєш у моїй кузні? Навчання? А може, ти прагнеш дізнатися секрети сталі? Таємниці кузні? Говори, Грант!",  -- db:1606
[947863845] = "Відправляйся до Оргримара, у Долину Честі. Там вона живе разом зі своїм чоловіком та двома доньками. Усі вони — майстри-ковалі з великим досвідом, але духи підказують мені, що саме вона найкраще допоможе тобі у навчанні.",  -- db:1609
[695859013] = "Ти керуєш духами в сталі, щоб захищати й обороняти, набагато вправніше, ніж я коли-небудь зміг би. Учень перевершив вчителя, і тепер я мушу відправити тебе туди, де ти зможеш продовжити навчання. $N, ти повинен знайти Шаїс Стілф'юрі в Оргримарі. Вона — найкраща майстриня з виготовлення обладунків, яку я коли-небудь знав, і вона зможе багато чого тебе навчити.",  -- db:1610
[343535695] = "У всьому є дух, і якщо навчитися його чути, можна змусити його прийняти будь-яку форму, яку забажаєш. Ковальство — це не просто кування металу, не спроба змусити його підкоритися твоїй волі. Це вміння прислухатися до духу, що живе в сталі, і спрямувати його до тієї форми, яку, як ти знаєш, він сам прагне прийняти.",  -- db:1611
[683476392] = "Ти маєш вигляд $g чоловіка : жінки, яка прагне знань. Можливо, ти шукаєш знань про кузню та молот. Можливо, я зможу наставити тебе на цей шлях. Але лише тоді, коли ти приймеш духів і прислухаєшся до їхнього поклику.",  -- db:1615
[51960907] = "Відправляйся до Оргримара — ти знайдеш її та її потомство в Долині Честі.",  -- db:1616
[561470170] = "Броня, подібна до тієї, що ти виготовляєш, здатна зупинити навіть найгострішу сокиру. Я вражений, $N, таке трапляється нечасто. Знайди орка на ім’я Шаїс Стілф’юрі — вона виготовляє найкращу броню за межами тієї проклятої фортеці гномів.",  -- db:1617
[487028512] = "Як там лезо вашої сталі? Досить гостре, щоб прорізати живіт ворога? Дозвольте мені показати вам кілька прийомів, як зробити його ще гострішим.",  -- db:1618
[771712642] = "Хочеш стати ковалем? Хочеш кувати мечі, щоб розрізати ворога на шматки? Молотки, щоб розтрощити йому череп? Так, я можу допомогти, і з радістю, якщо завдяки цьому проллється кров.",  -- db:1619
[711458050] = "Відправляйся до міста орків Оргримар і знайди його в Долині Честі в крамниці під назвою «Зброя легенд».",  -- db:1620
[51612942] = "Ти виготовляєш чудові клинки, $N. Ними можна розрубати камінь, і вони все одно залишаються достатньо гострими, щоб перерізати горло. Хоча я бачив і кращі — їх виготовляє орк на ім’я Келгрум Кровосокира. Іди до нього й навчися усього, чого він може тебе навчити.",  -- db:1621
[739385691] = "Ласкаво просимо знову до Великої Кузні, $N. Ти прийшов провідати старого гнома чи, може, вважаєш, що готовий до наступного етапу свого навчання?",  -- db:1633
[424012374] = "Гарна сталь, $N. Візьми молоток і підійди сюди — я покажу тобі секрет кування легендарної зброї.",  -- db:1634
[255826773] = "Що це таке? Хіба ти не бачиш, що я зайнятий?",  -- db:1635
[377219703] = "Хочеш дізнатися більше, $N? Підійди сюди й покажи мені, що ти готовий.",  -- db:1637
[328875280] = "Як пройшли твої подорожі, $N? $g Сумі та Тумі сумували за тобою, тобі варто привітатися з ними після уроку: я чула розповіді про твої пригоди, схоже, ти була дуже зайнята. А тепер давай подивимося, чого ти навчилася, поки тебе не було.",  -- db:1638
[373787144] = "Я не навчаю ковалів без навичок, повертайся, коли матимеш що-небудь гідне, щоб мені показати.",  -- db:1640
[863852190] = "Я бачу в тобі потенціал, $N. А тепер бери молоток і кілька тих обрізків — тобі потрібно багато тренуватися.",  -- db:1641
[883890392] = "Брззз!$B$BЛаскаво просимо до Matrix Punchograph 3005, цикл A — терміналу рівня безпеки «альфа».$B$BДля доступу до функцій терміналу вам необхідна біла перфокартка.$b$b01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001",  -- db:1643
[138713274] = "Картка безпеки «White» успішно вставлена...$B$BВидача пристрою з рівнем безпеки «бета».$b$b01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101",  -- db:1644
[983230947] = "Гордунні — це велике плем’я огрів, яке контролює значні ділянки лісів у Фераласі. Їхня темна магія просочується в навколишні стихії, завдаючи шкоди як навколишньому середовищу, так і істотам, що його населяють.$B$BЯкщо ви все-таки вирішите відправитися до Фераласу, будьте обережні з цими ограми — вони досить небезпечні, і багато хто з них володіє потужною темною магією.",  -- db:1646
[70929219] = "Бррррр!$B$BЛаскаво просимо до Matrix Punchograph 3005, режим B — терміналу з бета-рівнем безпеки.$B$BДля доступу до функцій терміналу вам необхідна жовта перфокартка.$B$B01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001",  -- db:1647
[422696845] = "Жовта картка безпеки вставлена успішно.  Видається одиниця енергії «чі» відповідного рівня безпеки.$b$b01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001",  -- db:1648
[418179965] = "Брззз!$B$BЛаскаво просимо до Matrix Punchograph 3005, тип C — терміналу рівня безпеки «чі».$B$BДля доступу до функцій терміналу вам необхідна синя перфокартка.$B$B01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000",  -- db:1649
[203986598] = "Синя картка безпеки вставлена успішно.  Видача блоку «Дельта» рівня безпеки.$b$b01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111",  -- db:1650
[370025847] = "Бррррр!$B$BЛаскаво просимо до Matrix Punchograph 3005, тип D — терміналу з рівнем безпеки «дельта».$B$BДля доступу до функцій терміналу вам необхідна червона перфокартка.$B$B01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100",  -- db:1651
[511591521] = "Картка безпеки червоного кольору вставлена успішно.  Видається картка з даними про зміну рівня безпеки.$b$b00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110",  -- db:1652
[162502344] = "Ерака но Кімбул$BБог тигрів, Володар звірів, Король котів, Згуба здобичі$B$BУїтей но Муе'зала$BБог смерті, Батько сну, Син часу, Друг ночі.",  -- db:1653
[401917822] = "Елорта но Шадра$BБогиня павуків, Мати отрути, Танцівниця шовку, Кохання Смерті.",  -- db:1654
[755430557] = "Технологічний «Хуеріст-о-метр» від Matrix Punchograph виявив у вас схильність до інженерії. Тепер ви можете вибрати один із таких варіантів:$b$b01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001",  -- db:1655
[180871486] = "Отримання доступу...    Порожнє -- інженер <skill_level == n3wb>     01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010    ДОСТУП ВІДМОВЛЕНО!",  -- db:1656
[237448599] = "Доступ до даних надано.  Гарного дня!$b$b01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011",  -- db:1657
[980398860] = "Будь ласка, зачекайте хвилинку, $N. Кіндал зараз внизу, у таборі Грімтотем, намагається звільнити феєричних драконів із полону. Нам просто пощастило, що допомога прибула саме вчасно. Хто знає, що б ті огидні таурени з ними зробили.",  -- db:1673
[101094498] = "Вітаю.  Я — охоронець входу.  Якщо у вашому наборі дисків ще немає «Плит Улдума», я не дозволю вам увійти на територію Улдума.",  -- db:1674
[561822151] = "«Пластини Улдума» — це диски, синтезовані Творцями, які надають доступ до комплексу Улдума.  Ці диски містять і зберігають конкретні дані, пов’язані з діяльністю Творців у цьому місці.$B$BЗа своїми фізичними параметрами вони майже ідентичні за обхватом набору дисків, який ви зараз маєте. Однак їхні позначки безпосередньо пов’язані з інформацією про Улдум, а не про комплекс Улдаман.",  -- db:1675
[649657296] = "Моє завдання — регулювати доступ Творців до комплексу Улдум. Я дозволяю вхід на територію лише в тому випадку, якщо відвідувач пред’являє для допуску відповідні диски з послідовностями.$B$BВаш набір дисків наразі не містить «Плит Улдума» — головної умови для входу.  Доступ не надається, якщо «Пластини Улдума» відсутні.",  -- db:1676
[206485074] = "Творці синтезували кілька комплектів «Пластин Ульдума» для використання виключно за їхнім призначенням. Творці контролюють розподіл зазначених дисків серед усіх комплексів у цьому світі.  У зв’язку з цим графік відвідування Азерота було перенесено, тож у майбутньому диски можуть з’явитися в обігу саме в той час.$B$BНаявні диски було повністю розподілено серед осіб, що мають відповідний рівень допуску до секретної інформації.",  -- db:1677
[924111960] = "Творці використовують візити як засіб для відновлення контролю над засіяними світами, коли зовнішні та внутрішні сили порушують пов’язану з ними динаміку матриці.  Не слід легковажно ставитися до таких тактик, коли їх застосовують Творці.$B$BДля отримання додаткової інформації щодо запланованого візиту до цього світу, будь ласка, зверніться до відповідного сховища даних, яке містить усі відомості щодо графіків, пов’язаних із Творцями.",  -- db:1678
[429936007] = "Ульдум — це науково-дослідний центр, де Творці продовжують працювати над вдосконаленням біосфери Азерота.  Конкретна інформація щодо їхньої роботи, пов’язаної з Улдумом, доступна лише тим особам, які мають у своїх наборах дисків «Пластини Улдума».$B$BХранища даних усередині комплексу Улдум запрограмовані для обробки даних конкретних експериментів та збірок даних; детальну інформацію можна знайти саме там.",  -- db:1679
[337806240] = "Слава Світлу, що ти тут! У такій ситуації я б погодився навіть на допомогу від двоголового огра.$B$BМісто заполонили троги! Спроби знищити їх призвели до масового радіоактивного забруднення. Але надія ще є.$B$BНаші вчені, які евакуювалися до Айронфорджа, працюють над ліками від радіаційної хвороби. А тим часом, якщо ти допоможеш мені зупинити вторгнення трогів, можливо, місто вдасться відбити.",  -- db:1693
[936298813] = "Дай мені пару хвилин, $N. Тут щойно було трохи гамірно, і я просто хочу переконатися, що все вже заспокоїлося. Скоро з тобою зв’яжуся.",  -- db:1713
[56806429] = "Ласкаво просимо до «Blue Moon Odds and Ends, $c». Якщо у вас виникнуть запитання, будь ласка, звертайтеся до мене.",  -- db:1734
[287314195] = "Бррррр!$B$BЛаскаво просимо до Matrix Punchograph 3005, цикл A — терміналу рівня безпеки «альфа».$B$BВиявлено білу перфокартку.  Доступ надано.$b$b01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111",  -- db:1753
[659346896] = "Бррррр!$B$BЛаскаво просимо до Matrix Punchograph 3005, режим B — терміналу з бета-рівнем безпеки.$B$BВиявлено жовту перфокартку.  Доступ надано.$b$b01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001",  -- db:1754
[261462806] = "Бррррр!$B$BЛаскаво просимо до Matrix Punchograph 3005, рівень безпеки «чі».$B$BВиявлено синю перфокартку.  Доступ надано.$b$b01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001",  -- db:1755
[313426592] = "Бррррр!$B$BЛаскаво просимо до Matrix Punchograph 3005, тип D — терміналу з рівнем безпеки «дельта».$B$BВиявлено червону перфокартку.  Доступ надано.$b$b01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111",  -- db:1756
[665306587] = "Неймовірна сила криється в духах, або «муісек», тих істот, з якими ми боремося.$B$BЗазирни в себе; навчися керувати силою власного духу, і ти станеш могутнішим, ніж міг собі уявити.",  -- db:1757
[382954452] = "«Сул’тразе»… Вперше я почув це слово, коли був приблизно твого віку. Тоді воно для мене нічого не означало, так само як і для тебе зараз. Лише тоді, коли загін тролів із Зул’Фаррака спустошив ці землі, я зрозумів… і злякався.$B$BБагато хто скаже тобі, що «Розколений клинок Страждання» не існує. Що це міф; чутка, яку поширили, щоб «налякати» дітей. Але повір мені, $r, він існує.$B$B<Трентон відволікається, проводячи рукою по нерівному шраму на обличчі.>",  -- db:1758
[367559033] = "Розділившись на дві частини, вони утворюють єдине ціле. Два мечі пов’язані із Зул’Фарраком.$B$BСуль’тразе відродиться, коли близнюки будуть знайдені.",  -- db:1759
[780288732] = "Гвардія Терамора — це найкращий загін солдатів Альянсу, що базується в Калімдорі. Наш обов’язок — дотримуватися законів Альянсу навіть так далеко від рідних домівок.",  -- db:1793
[439081704] = "Ми не знаємо багато про пожежу в готелі «Шейді Рест», окрім того, що дружина та дитина Джеймса Гіала не змогли врятуватися.$b$bНам вдалося витягнути Джеймса, але з тих пір він вже не той.$b$bУ нас є багато зачіпок, але мало доказів. Ми сподіваємося, що завдяки зусиллям охорони та пильній допомозі мешканців Терамора нам вдасться розкрити цей жахливий злочин.$b$bЯкщо ви бажаєте допомогти у розслідуванні, залишки готелю можна знайти на кордоні з Пустками.",  -- db:1794
[501781784] = "Ти їх бачиш, смертний? Ні... Я й не думав, що ти зможеш. Бачиш, але сліпий — це і твій дар, і твоє прокляття.",  -- db:1796
[613185507] = "У часи війни Разеліх-Осквернитель був найстрашнішим із заступників лорда Каззака. Коли Легіон зазнав поразки, а Каззак був змушений відступити до Зараженої Шрами, Разеліх отримав від свого господаря завдання забезпечити контроль над Спустошеними Землями.$B$BПоки Альянс вів дрібні сутички з Ордою за території за межами Спустошених Земель, Разеліх об’єднував розрізнені секти Ради Тіней та брутальних огрів Дредмаул, що мешкали на цих землях.",  -- db:1813
[880819663] = "На жаль, саме мудрість Тралла остаточно закріпила союз між володарем демонів та його поплічниками. Саме полк Требора став каталізатором, що об'єднав володаря демонів, секти «Присяжних тіней» та огрів. Привабливість майже необмеженої влади та надання кожному з лідерів безсмертних ударних загонів закріпили угоду кров'ю.$b",  -- db:1814
[944709186] = "Севін, Алістардж і Грол не усвідомлювали, що так само, як їхні слуги були прив’язані до цієї землі, так само і вони самі стануть... Бачте, ціною їхнього безсмертя стало ув’язнення та вічне рабство під владою Разеліха. Жорстока хитрість Разеліха вкотре взяла гору.$b",  -- db:1815
[16872970] = "Їхні розуми тепер зіпсовані, $r. Так, навіть більше, ніж раніше. Вони живуть лише для того, щоб служити Разеліху та захищати його. Уламки амулета, які кожен із них зберігає, є ключем до виклику повелителя демонів. Ти не розумієш, що жодному з них не можна заподіяти шкоди звичайними засобами.",  -- db:1816
[287121253] = "Тоді уявімо, що ти берешся за довгу й важку справу — створення заклинання, необхідного для подолання демонічних захисних бар’єрів, накладених на тріаду. Яким буде твій наступний крок? Зіткнутися з Осквернителем у його лігві?$B$B<Лорамус сміється.>$b",  -- db:1817
[449309991] = "Люди захопили для себе значну частину Болота Пилової Ями, але клан Стоунмаул, завдяки нашій допомозі, зміг відтіснити їх.",  -- db:1818
[455884768] = "Люди збудували заїжджий двір на околиці Пусток. Вони назвали його «Тінистий притулок». Кілька тижнів тому його спалили.$b$bВійськовий вождь наказав нам не чіпати людей, доки вони не перетинають наших кордонів, але, схоже, хтось порушив його наказ.$b$bВін доручив мені розібратися в цій справі. Якщо ви бажаєте допомогти, вирушайте до руїн корчми «Тінистий притулок» і принесіть мені всі знайдені вами докази.",  -- db:1819
[884996846] = "Якщо Ріт якось причетний до підпалу готелю «Шейді Рест», тобі доведеться знайти його й витягнути з нього відповіді.$b$bЯ відправив Огрона, щоб той його розшукав. Він рушив на південний схід, у бік головної дороги, що пролягає через болото. Зустрінься з Огроном, а потім вирушай на пошуки Ріта.",  -- db:1820
[86339427] = "Мені це не цікаво, $N. Ні, нізащо тебе не впустять у Палюче Ущелине. Неможливо. Цього не буде. Скільки разів мені тобі повторювати — я не можу тебе впустити! Ти що, не розмовляєш загальною мовою? Ти, може, орк у маскуванні? Н-І. НІ!$B$BЯкщо я впущу тебе, то доведеться впускати всіх. Незабаром твої близькі друзі захочуть сюди, потім їхні далекі родичі, потім їхні друзі, і так далі, і так далі. Останнього разу, коли таке сталося... ну, про останній раз ми краще не будемо згадувати.",  -- db:1833
[855475153] = "Ти з глузду з’їхав? Ти хоч уявляєш, які звірі мешкають у тому місці? У гіршому випадку нам доведеться зібрати твої останки лопатою. Ми вже втратили кількох хороших гномів через цих жахливих монстрів.$B$BТож відповідь — ні. Якщо ти так хочеш дістатися до Палючого Ущелини, тобі доведеться знайти інший шлях.",  -- db:1834
[104752072] = "Мені навіть не слід було б тобі цього розповідати, але якщо ти зможеш пройти повз усіх тих тварюк і чудовиськ у Пустках, то, можливо, тобі вдасться дістатися до Палючого Ущелини.$B$BТак, саме Пустки. Біля Каргата орки проклали якусь бічну дорогу. Це тільки доводить, з якими дурнями ми тут маємо справу! Задній вхід до пекла? Що вони собі думали?",  -- db:1835
[679455459] = "Неуразливий?",  -- db:1836
[594500668] = "Ти дурень, тож тобі слід прислухатися до моїх застережень. Ніхто не є невразливим. Було б розумно з твого боку запам’ятати цю пораду.",  -- db:1837
[550046164] = "Ось що я тобі скажу. Оскільки ти вважаєш себе героєм, якщо зможеш пробратися через Пустощі до Палючої ущелини й принести мені щось на доказ своєї героїчності, я подивлюся, що можна зробити, щоб дістати тобі ключ.$B$BУ найпівденнішому куточку Палючої ущелини живе жінка, майже така ж сувора, як і я, — Маргол Розлючена. Можливо, тобі варто це перевірити.",  -- db:1838
[235482978] = "Що можна робити в готелі?$B$BНу, коли ви зупиняєтеся в готелі, ви відпочиваєте дуже комфортно.  Завдяки цьому ви «відпочинете» набагато швидше, ніж у дикій місцевості.  Коли ви добре відпочинете, ви отримаєте більше досвіду.$B$BВи також можете звернутися до будь-якого господаря готелю, щоб отримати камінь повернення, який згодом можна буде використати для швидкого повернення до цього готелю.",  -- db:1853
[417993638] = "Ти вже на правильному шляху, $N.  Але тобі ще багато чого треба навчитися.  Можливо, саме в південній частині Пусток ти знайдеш свій наступний урок.",  -- db:1874
[20991611] = "Хоча ми називаємо цю землю «Пусткою», для того, хто знає, куди дивитися, це місце просто кишить життям.",  -- db:1875
[931902963] = "Я продаю найкращий одяг із тканини та шкіри на цій стороні долини!",  -- db:1914
[305321350] = "Ти досягнув більшого, ніж багато хто, $N. Стався з повагою до навколишнього світу, і тобі вдасться набагато більше, ніж більшості.",  -- db:1916
[252977886] = "Здається, ніби вівтар манить вас, ніби він живий.",  -- db:1918
[294804776] = "Слава Елуні! Вже багато років я не приймав гостей.",  -- db:1920
[896196927] = "Будучи молодим нічним ельфом у Темному Березі, я зіткнувся з групою сумнівних осіб, відомих як «Молот Сутінків». Деякі з них подружилися зі мною, і, на жаль, я зрештою зрадив свою віру в Елуну та приєднався до жорстокої секти «Молота Сутінків».$B$BЛише після того, як до мене прийшло видіння від Елуни, я прокинувся від того занепаду, в який впав, ставши послідовником Старих богів.$B$BУ знак покаяння я почав працювати над своєю молитвою до Елуни.",  -- db:1921
[214480756] = "На табличці з чистого золота було викарбувано втілення мого каяття, сорому, жалю та скорботи. На жаль, «Молот Сутінків» знайшов цю табличку і назвав мене богохульником. Мене без суду й слідства стратили, і моя молитва до Елуни залишилася незавершеною. Тепер я прив’язаний до цього світу як дух, не маючи змоги перейти до Нетера; мене утримують у цій клітці як попередження для всіх, хто наважиться зрадити віру «Молота Сутінків».",  -- db:1922
[55876849] = "Стародавній вівтар Хаккара мовчазно стоїть біля входу до кімнати.$B$BПоглянувши на балкони, що знаходяться над ним, ви помічаєте, що на кожному з них стоїть велика статуя у вигляді змії. Ці статуї дуже схожі на ті, що стоять на вівтарі перед вами. Мабуть, вони якимось чином пов’язані між собою...",  -- db:1923
[41354403] = "У цій місцевості мешкає чимало істот, яких вважають союзниками нічних ельфів. Ельфи вже мали доступ до сили, що криється в кожній із цих істот; настав час надати таку саму можливість і Орді. Я придумав спосіб, як цю силу можна захопити й використати на нашу користь.$B$BНе сумнівайся в тому, що я тобі кажу, $N. Допоможи мені, і ти переконаєшся, що я говорю правду.",  -- db:1924
[940833099] = "Якщо ви захоплюєтеся пошиттям одягу, у Vizzklick ви точно знайдете все необхідне. Огляньте асортимент, $N, і дайте мені знати, якщо захочете щось придбати!",  -- db:1933
[325515288] = "Збирай свої речі, $N! Я щойно отримав повідомлення від Ніліт Локрав із Палючої ущелини, що «Підземний ринок» розгорнув свою діяльність у самому серці «Котла». Знайди Ніліт Локрав у Палючій ущелині й дізнайся всі подробиці!",  -- db:1934
[173123602] = "У кінці кімнати з’являється яскраве світло, а потім зникає. Потім ти помічаєш ще один промінь… а потім ще один.$B$BЗдається, вони показують тобі якийсь візерунок.",  -- db:1935
[708673163] = "Помста буде моєю.",  -- db:1953
[715417841] = "Мій батько був убитий мерзотою, що мешкає в казані. Мої благання про допомогу до магістрату Штормовію залишилися без відповіді. Ні, вони навіть не хочуть визнавати, що ця частина світу взагалі існує, не кажучи вже про те, щоб відправити сюди свої дорогоцінні війська для відправлення правосуддя.$B$BI Я прагну помсти, $r, просто і ясно. Чи є в цьому світі справа, що викликає більше пристрасті?",  -- db:1954
[898892763] = "Як бачите, я — лише одна людина з незграбним і тупим зброєносцем. Сила темнозалізних гномів та звірів, що перебувають у владі Рагнароса, безперечно, здолала б мене самого, але я цілком впевнений, що такий хоробрий і амбітний мандрівник, як ви, без проблем впорається з мешканцями казана. Якщо ви вирішите допомогти мені, я винагороджу вас багатством і розкішшю, про які ви навіть не мріяли.",  -- db:1955
[135376065] = "Щиро вітаю вас, пане. Ви проклали довгий шлях далеко від уторованих стежок лише для того, щоб поговорити з кимось, хто мешкає в печері. Сподіваюся, у вашому дивному, хоча й не несподіваному візиті сюди є якась причина. Так?",  -- db:1973
[821575985] = "Вітаю, $Gsir:miss;. Я — Нірілл, учень Майстра Ксилема. Якщо у вас є якісь питання, будь ласка, звертайтеся до майстра.$B$BI буде тут, щоб допомогти вам, коли ви будете готові повернутися до підніжжя гори.",  -- db:1994
[354134408] = "Я знаю, хто ти, $N.  Доля та сили, що стоять за нею, привели тебе до мене не просто так, і мені аж ніяк не приємно брати участь у цьому.  У найближчий час тобі доведеться прийняти багато рішень, і я сподіваюся, що ти будеш достатньо мудрим, щоб зробити правильний вибір.$B$BПовір мені, $r, коли я кажу тобі це — правильні рішення існують.",  -- db:1995
[236552175] = "Ви досить допитливі, хоча така допитливість свідчить про загальний брак розуміння. Я кажу це тому, що якби у вас була чітка мета перебування тут, ваше запитання здалося б безглуздим. $B$BНа цьому я бажаю вам гарного дня.",  -- db:1996
[599258642] = "Ти ж знаєш, що так, смертний; я відмовляюся тут від чималої кількості прикидів, і раджу тобі зробити те саме.$B$BТи прийшов сюди, очевидно, тому що знаєш: те, що ти маєш — здобуте завдяки твоїм діям у Затонулому Храмі Атал’ала — привело тебе до мене з певною метою.  Ця мета — дати спокій моєму соратнику… моєму братові. Він ув’язнений у кошмарі всередині самого Сну. Сам він не може вирватися на свободу.",  -- db:1997
[321992110] = "У всьому цьому винен бог, якого породили тролі Атал’ай. Ми знищили фізичне втілення цього бога і затопили храм, але бог виявився набагато сильнішим, ніж ми навіть очікували.  Насіння його розтління проникло глибоко, спотворюючи все на своєму шляху.$B$БЕранікусу було доручено охороняти затоплений храм, щоб ні прості Аталаї, ні їхній бог не змогли знову піднятися.  Він став мимовільною жертвою цього розтління, а ми — жертвами того, що недооцінили його силу.",  -- db:1998
[239954844] = "Те, що ви тут, — це перший крок… правильний вибір, якщо хочете, у справі допомоги Драконьому зграї Ісери.$B$BМожливо, ви тут виключно заради особистої вигоди, а може, вас привело сюди моральне почуття обов’язку.  Жодна з цих причин сама по собі не має значення, але обидві вони насправді є вирішальними для досягнення цієї мети: саме муки, які терпить Еранікус, вирвали мене з мого Сну, і тепер моє завдання — покласти край його стражданням.  Тепер я прошу вас допомогти мені в цій місії.$B$B",  -- db:1999
[558209281] = "Цікаво, цікаво... Я знаю одну друїдку, яка живе на вершині пагорба над Печерами Плачу, $N. Можливо, вона зможе розповісти тобі більше про цей осколок, який ти знайшов.$B$BА тепер мені треба повертатися до роботи!",  -- db:2013
[339849499] = "Дні, які ми провели тут, в Азшарі, не належать до наших найкращих і найславетніших, але ми ще молоді, і кров досі тече в наших жилах — ми здобудемо тут перемогу. Це лише питання часу.",  -- db:2033
[753929862] = "Белгром відправив нас сюди з Оргримара, щоб ми допомогли йому в цьому необачному союзі, але якщо його ризик виправдається, то це принесе велику користь усій Орді.$B$BЗанадто багато орків уже загинуло через його бажання догодити жінкам, але він і досі командує нами, і наша честь вимагає, щоб ми якнайкраще використали цю ситуацію.",  -- db:2034
[860229409] = "Я тут не заради честі, $N. Я тут заради гордості одного орка.$B$BЯкби я не відхилив пропозиції Белгрома, то, впевнений, досі був би в Оргримарі, займаючись справді важливими справами.$B$BЙого потяг до жінок добре відомий багатьом войовницям у Дуротарі, але це не заважає йому залишатися таким самим чарівним, як і раніше.$B$BПроте йому пощастило, що він не намагався задовольнити своє бажання щодо мене ще довше — інакше йому б не вистачило не лише пальців на руках.",  -- db:2035
[339411868] = "Вітаю, $N. Бачу, ти приїхав з Оргримара, щоб допомогти нам. Я радий. Хочу якнайшвидше вибратися з цього проклятого лісу. Набагато краще б я провів час в Оргримарі за келихом доброго елю.$B$BХоча мені не терпиться дізнатися, як Белгром вмовив тебе приїхати сюди.",  -- db:2036
[545427798] = "Що привело тебе до «Круга Сенаріона», $N?",  -- db:2037
[150285056] = "Я знаю, я знаю, я тут, посеред ніде!$B$BНасправді я живу в Ратчеті, але після того, як мій цепелін тут розбився, я вирішив, що можна вже й розпочати дослідження, заради яких я сюди й приїхав!",  -- db:2038
[36045327] = "Цей дух витає над своїм мертвим тілом. Його примарні очі пронизують тебе, дивлячись кудись у далечінь...",  -- db:2039
[751529255] = "Земля Фераласа пережила чимало, $r. Земля, дерева, істоти — все це змінює те, чим є Фералас зараз і чим він стане в майбутньому.$B$BПроте Два Колосальні, що височіють над нами, залишаються незмінними попри все, що тут відбувалося...",  -- db:2053
[629411243] = "Щоб безпечно спуститися, я дарую крила тим, хто цього потребує.",  -- db:2054
[106509435] = "Ну, раз ти вже про це згадав, так, вчора вдень я справді побачив щось, що мені здалося трохи дивним!$B$BЯ пробігав повз якісь старі руїни тролів на південний схід відсюди; ну, власне, я не так біг, як скоріше стрибав... Пісок такий гарячий!$B$BAле, як би там не було, я стрибав повз руїни, коли помітив там розбитий табір. На мій погляд, дивне місце для таборування... Я б ще трохи пороздивлявся, але один із тих божевільних величезних грифів прогнав мене.",  -- db:2055
[316235176] = "Дякую, що врятували мене!$B$BIЯ — кухар і алхімік зі Штормовію.  Я був тут, шукаючи місцеві трави та рецепти для свого дядька Ангуса, коли ці квілбоари мене захопили.  Якби ви не з’явилися, я впевнений, що опинився б у їхньому казані!",  -- db:2113
[284765058] = "Хм... так, у мене є рецепт, який, можливо, тобі стане в нагоді.  Давай я тобі покажу!",  -- db:2114
[75937198] = "Ну так, я справді знаю один рідкісний алхімічний рецепт.  Дозволь мені навчити тебе!",  -- db:2115
[349114331] = "Вітаємо! Якщо ви завітали сюди, щоб отримати доступ до інженерних схем гоблінів, будь ласка, підготуйте свою членську картку інженера-гобліна для перевірки.",  -- db:2133
[454355921] = "Вітаємо! Якщо ви завітали сюди, щоб ознайомитися зі схемами Gnome Engineering, будь ласка, підготуйте свою членську картку Gnome Engineer для перевірки.",  -- db:2134
[378501136] = "Привіт, $glad:lass;... Мене звати Оглторп, і, можливо, саме я створив один із тих дивовижних гномських пристроїв, що, можливо, є у вашому розпорядженні!  Якщо воно вибухнуло — то це не я; а якщо воно зробило вас багатим — то ми можемо обговорити роялті!$B$BО, і якщо ви з Гномерегана, то просто візьміть два кути під 90 градусів, зіткніть їх і починайте марширувати.  Мені вам нічого сказати.",  -- db:2135
[694131078] = "О, це ж $N!  Радий знову вас бачити; я не можу висловити всю свою вдячність за допомогу, яку ви надали мені та моїй винахідницькій діяльності до цього часу.$B$BЧим я можу вам допомогти сьогодні?",  -- db:2136
[898343667] = "Мене звати Тінкмастер Оверспарк, і я є головним архітектором сучасних принципів гномської інженерії у сучасному світі.  Моє завдання — забезпечити, щоб сила винахідництва й надалі сяяла найяскравіше саме з наших гайкових ключів «Арклайт», ніж деінде!$B$BДо речі, якщо вам трапиться знати хорошу схему для усунення радіації, то ми якраз зараз шукаємо таку...",  -- db:2137
[469603868] = "Давай я тобі трохи розкладу це математично: «гоблін» плюс «інженерія» дорівнює НОУ-ХАУ, друже.  Той, хто скаже тобі щось інше, просто не вміє додавати.",  -- db:2138
[722981553] = "З моїх досліджень випливає, що перемога над аватаром бога Хаккара ослабила його.  Однак основна частина його сили залишається, причаївшись у найвіддаленіших куточках Нетера.$B$BТи вже одного разу переміг його аватара, $N.  Можливо, якщо ти переможеш його ще раз, то зможеш ще більше ослабити бога, щоб одного дня ми змогли зіткнутися з його справжньою сутністю.$B$BЯ підготував заклинання, за допомогою якого ти зможеш знову викликати аватара Хаккара у Святилищі Поваленого Бога.  Чи хочеш ти ще раз зіткнутися з ним?",  -- db:2139
[928524141] = "Вітаю, $c.  Хоча час і випивка притупили мої зовнішні чуття, мої внутрішні очі залишаються гострими.",  -- db:2140
[850145190] = "Привіт, $N. Я тут треную молодих гіппогрифів і доглядаю за ними; можеш сміливо роздивитися все навколо.",  -- db:2153
[897082072] = "Друїди дуже чутливі до долі всіх істот у світі. Коли з'ясувалося, що ці птахи опинилися в небезпеці, ми організували систему їхнього порятунку від розтління Фераласу.$B$BA Цю справу очолює гномка на ім'я Кергл Кранклхоп; вона збирає яйця й надсилає їх сюди, де я про них піклуюся.$B$BНам завжди знадобиться додаткова допомога у нашій справі, $N. Можливо, тобі варто вирушити до Гаджетзана й пошукати Кергл.",  -- db:2154
[648577343] = "Дякую, маленький $r!",  -- db:2155
[659159624] = "Твої кулінарні здібності поки що не надто високі.  Можливо, якщо трохи потренуємося, я зможу навчити тебе тому, що знаю.",  -- db:2173
[760894877] = "Твої навички в алхімії ще не настільки високі, щоб ти міг скористатися моїми настановами.  Можливо, якщо ти поговориш зі мною пізніше...",  -- db:2174
[664359205] = "Магія спотворює лише тих, хто слабкий. Навіть якщо ти не йдеш шляхом чаклуна, тобі варто про це пам’ятати.",  -- db:2175
[5056080] = "Магія спотворює лише тих, хто слабкий. Продовжуй тренуватися, інакше тебе може спіткати така сама доля.",  -- db:2193
[691609564] = "Я назавжди прив’язаний до цього проклятого світу. Чого ти бажаєш, смертний?",  -- db:2213
[786022362] = "Вітаю, $N. Ти прийшов, щоб дізнатися про історію Айронфорджа?",  -- db:2234
[108555677] = "Повідомте мене, коли будете готові послухати цю історію.",  -- db:2235
[131756400] = "Сотні років тому величне місто Тауріссан гордо височіло серед пишних просторів, які нині перетворилися на занедбані Палаючі Степи.$B$BТауріссан був батьківщиною народу темнозалізних гномів і в той час перебував у епіцентрі громадянської війни, що охопила весь гномський народ.$B$BСправа в тому, що ця частина світу колись була частиною Гір Червоногір'я — аж до того дня, коли Тауріссан знищив гігантський вибух. Місто лежало в руїнах, а навколишні території перетворилися на попелясту пустку.$b",  -- db:2236
[779767957] = "Ми цього не знаємо.$B$BТі з Темнозалізних, хто вижив, пробралися в гори й почали відбудовувати своє місто.$B$BЗ попелу Тауріссана тоді постала Шпиль Чорної Скелі та нова нація Темнозалізних. У Палючому Ущелині, в районі, відомому як «Котел», було зведено додаткові укріплення.$B$BПочали поширюватися чутки про древнє зло, яке панувало над королівством Темних Заліз.",  -- db:2237
[566762442] = "Останнім часом Темні Залізні все частіше з’являються на поверхні світу. У Пустках зведено фортеці. У глибини Улдамана відправлено величезні розвідувальні загони в пошуках стародавніх знань. Вони навіть вторглися на нашу власну батьківщину, завдавши удару по нашій греблі біля озера.",  -- db:2238
[690204272] = "Нам потрібні шукачі пригод, які допоможуть нам, $N. Ви допоможете?",  -- db:2239
[489269049] = "Е-е-е, привіт! Якщо ви тут у зв’язку зі стягненням боргу та/або повісткою до суду, то, мабуть, ви мене з кимось переплутали. Дуже вибачте!",  -- db:2253
[333311397] = "Здається, моє намисто впало в озеро.  Його мені подарував тато, і тепер він, напевно, розсердиться.",  -- db:2273
[10498935] = "Дякую, $g пане : пані, за те, що знайшли моє намисто! Ви найкращі!",  -- db:2274
[872472765] = "Окрім «Грантів» зовні, ми з братами брали участь у битві за Гіял. Кожен, хто спробує пограбувати банк, спочатку повинен зіткнутися з нами.",  -- db:2275
[899163894] = "Я гарантую безпеку цього банку власною кров’ю — чи цього вам достатньо?",  -- db:2275
[581584914] = "Чи довірили б ви свій товар гобліну?",  -- db:2275
[847790566] = "Привіт, $g пане : пані;... чи не могли б Ви виділити трохи часу, щоб нам допомогти?  Будь ласка?",  -- db:2276
[678572727] = "Ще раз дякую за допомогу Хіларі, $g пане : пані;!  Коли я виросту, хочу стати таким самим героєм, як ви!",  -- db:2277
[574594600] = "Стільки років боротьби та рабства — так приємно знову мати дім.",  -- db:2278
[678325262] = "Скажи, чого ти хочеш, і пошвидше.",  -- db:2278
[820815881] = "Я живу лише для того, щоб служити господареві.",  -- db:2279
[173877858] = "Навіть у мирний час війна не вщухає, і багато кланів досі воюють під прапором Воєначальника. Ти прийшов, щоб приєднати свій клан до тих, хто бореться за Оргриммар?",  -- db:2280
[983939994] = "Привіт, $N! Я — головний інженер Скуті.",  -- db:2282
[786155208] = "Земля приховує багато таємниць, $c; наш обов’язок — подбати про те, щоб ті з них, які мають залишатися таємницею на благо всіх, і надалі залишалися такими.",  -- db:2284
[814244974] = "Якщо ти тут, щоб марнувати мій час, то ти марнуєш час усього «Кругу Сенаріону». Заради твого ж блага сподіваймося, що ти не настільки нерозумний, щоб робити саме це.",  -- db:2285
[222696209] = "Не можу повірити, що влада Штормовію відправляє основну частину нашої армії за кордон... коли наш тил перебуває під таким сильним тиском!$B$BЗ огляду на те, що з Вестфолла насуваються розбійники, а гноли вторгуються зі сходу та заходу, дивно, що сам Штормовій ще не опинився в облозі.",  -- db:2286
[23356466] = "Привіт, $C.  Сподіваюся, ти прийшов, щоб поповнити наші ряди.  Звірі та розбійники заполоняють наш улюблений Елвінн, а у нас ледь вистачає людей, щоб забезпечити безпеку на дорогах!$B$BІ якщо ти ще цього не зробив, прочитай те оголошення про Хоггера.  Це звірина з тих лісів, з якою треба розібратися.",  -- db:2287
[140590304] = "Привіт, $n.  Ласкаво просимо до Телсамара, і, поки ти тут, не забудь завітати до нашої місцевої пивоварні!",  -- db:2288
[664784055] = "Ласкаво просимо до Телсамара — вашого другого дому в Лох-Модані!$B$BТелсамар — чудове місце, але для тих, хто відгукується на поклик обов’язку, тут не все так просто!  Якщо ви готові ризикувати життям заради Альянсу, то прочитайте оголошення біля відділення Ліги дослідників у Телсамарі.",  -- db:2289
[746704114] = "Ахой, $N! Не дуже приємна картина, чи не так?$B$B«Горизонт Скаут» лежить на дні моря, моя команда в розпачі, а наш вантаж і пасажири розкидані, наче сміття, так що можна подумати, ніби це один із каналів Штормовію після фестивалю.$B$BІ на цьому не закінчуються неприємності...",  -- db:2293
[266985309] = "Кажу вам, змов тут повно. Є такі, кому бракує прозорливості, щоб зрозуміти, чим я займаюся, і які намагаються тримати мене прикутим до безвісності!$B$BНе наступайте на бруд.",  -- db:2313
[899223317] = "Що я роблю?  Вам бракує уяви?  Я — мрійник, шановний $g пане : пані;, і я мрію про краще майбутнє для нас усіх.  Очевидно, я — провидець.$B$BОднак є ті, хто прагне утримати нас у болоті банальності.  Я сказав йому, що я мрійник, а Великий друїд Стагхельм відповів: «Ну, світу теж потрібні копачі канав».$B$BДоки з нас не будуть зняті кайдани банальності, я допомагатиму Колу Сенаріону, перекидаючи ці купи землі з місця на місце.",  -- db:2314
[863721823] = "Вітаю, $r. Мене звати Франклорн Форджрайт. Ви прийшли, щоб дізнатися про Шпиль і Темне Залізо?",  -- db:2315
[481152124] = "У мене не було вибору — принаймні, так я думав. Я мав змиритися зі знищенням Тауріссана й стояти пліч-о-пліч зі своїм королем та його народом.$B$BПід владою Рагнароса король Дагран Тауріссан вирвав серце цієї гори й звів Шпиль Чорної Скелі. Ми невтомно працювали, щоб збудувати місто гномів, могутніше за будь-яке місто чи фортецю, що існували до цього... або з’являться після.",  -- db:2316
[154904702] = "Я стояв осторонь і спостерігав, як розпуста Рагнароса просочувалася в серця й уми народу Темного Заліза. Ця колись благородна раса, доведена до божевілля… до зла.$B$BКоли будівництво Шпиля було завершено, моя воля жити серед свого народу згасла. Я пішов з життя як герой нової нації Темного Заліза. Цю гробницю було споруджено тут — біля входу до міста, яке я спланував і збудував, — на честь моїх зусиль.",  -- db:2317
[728049630] = "Мій величний молот, «Айронфел», перейшов у руки нового головного архітектора, Фінеуса Дарквіра — людини з підлими намірами та мізерним талантом.$B$BОсь тут і з’являєшся ти, $N. Я хочу, щоб його зупинили. Він надто нездарний, щоб опанувати справжню силу Айронфела, але якщо з’явиться хтось, хто зможе використати Айронфел на повну потужність, руйнування, які вони можуть спричинити своїми творіннями, стануть катастрофічними для цього світу.$B",  -- db:2318
[311498002] = "Так, але це принесе тобі більше задоволення, якщо ти володієш навичками травництва!  Від вас вимагатиметься доглядати та вирощувати особливі насіння — а не сліпо розмахувати сокирою чи несамовито жестикулювати, дивлячись на пролітаючі тіні. Хоча «Вічнозелений мішечок», який ви отримаєте, дозволяє навіть найпростішому бруталу виростити щось, ті, хто проявить певні здібності, отримають більш рясні врожаї.",  -- db:2320
[784459567] = "Зверніть увагу, $g Джексон : Принцеса; — я не в настрої вислуховувати будь-які коментарі, які ви вважаєте милими чи кумедними. Я тут для того, щоб переконатися, що дослідження Верховного друїда просуваються згідно з планом, і моє завдання — відсіяти всіх, хто не є хакерами та не має необхідного спорядження для служби в моєму улюбленому Коло Сенаріону.",  -- db:2333
[251522290] = "Вітаю, благородний $c. Цей скромний слуга Кола Сенаріона бажає, щоб благословення та щедрі дари супроводжували вас і ваших близьких.",  -- db:2353
[684865329] = "Дивись під ноги, $c, бо у мене є заклинання «Поліморф», яке я підготував саме для тебе...",  -- db:2354
[215502407] = "Я люблю пиріг.",  -- db:2355
[722967053] = "Нана завжди казала, що у всьому світі немає нічого кращого, ніж теплий, ароматний шматочок свіжого домашнього вишневого пирога.",  -- db:2355
[362337013] = "Цей пиріг такий смачний, хочеш шматочок?",  -- db:2355
[614455201] = "Поганий день? Спробуй трохи вишневого пирога.",  -- db:2355
[821333432] = "Цей вишневий пиріг настільки смачний, що навіть дорослий гном міг би розплакатися.",  -- db:2355
[577165136] = "Скуштуйте цей вишневий пиріг — він викличе на вашому обличчі посмішку, широку на десять миль.",  -- db:2355
[830978219] = "Продається свіжий вишневий пиріг — виглядає так смачно, що аж сльози на очі навертаються.",  -- db:2355
[11158420] = "Вишневий пиріг — це моя найулюбленіша страва у всьому Азероті.",  -- db:2355
[827012243] = "Ласкаво просимо до табору «Мохаче», відважні $C. Чим я можу вам допомогти сьогодні?",  -- db:2368
[750722690] = "О, якби ж у мене була гілка, яку я міг би підняти перед собою. Тоді охоронці мене б ніколи не побачили.",  -- db:2393
[140036560] = "$N, тобі доведеться трохи почекати. Мій Spybot зараз працює над дуже делікатною справою. Я підійду до тебе за секунду.$B$BА, і зроби мені ласку, постарайся, щоб Лесковар тебе не побачив... ми збираємося влаштувати на нього засідку.",  -- db:2394
[42303873] = "Важкі часи, еге ж, $N? Куди не поглянь — хтось потребує допомоги, і ми з дружиною не виняток.",  -- db:2414
[44649129] = "Привіт! Мене звати Греган. Чим можу допомогти?",  -- db:2433
[100735593] = "Звісно, $N. Ти виглядаєш так, ніби тобі можна довіряти... Надійний! Я це бачу за милю... $B$B У будь-якому разі, повернемося до того, про що я говорив. Щоб приготувати еліксир «Відере», потрібна одна рослина «Еворут». Решта інгредієнтів — це, власне, дрібниці, але «Еворут»... ну, його може бути трохи складно дістати.",  -- db:2434
[208205814] = "«Давай вже з цим покінчимо, ти, мерзенний $r.$B$B<Харан опускає голову, оголюючи свою коротку шию.>»",  -- db:2473
[554937733] = "Все втрачено...",  -- db:2474
[265235059] = "Ти що, $r, вважаєш мене дурнем? Я міг би й сам підписати їй смертний вирок! Чому я маю тобі довіряти?$B",  -- db:2475
[789001001] = "<Харан зітхає.>$B$BI Гадаю... Гадаю, ти маєш рацію.$B$BGор'шак розповів мені, що у твого Вождя великі плани. Плани, які можуть змінити характер взаємовідносин між Альянсом та Ордою. Що ти про це знаєш?",  -- db:2476
[866340577] = "Тоді слухайте уважно, $r.$B$BКілька місяців тому магістрат Лейкширу відправив послів до Айронфорджа, благаючи короля про допомогу у боротьбі з нападами Чорної Скелі, що надходять з Червоногір'я та Палаючих Степів.$B$BПринцеса Мойра, незважаючи на мої заперечення, зголосилася допомогти. Мені виділили двадцять елітних гвардійців для охорони принцеси під час небезпечної подорожі від Лоха до Лейкширу.",  -- db:2477
[978537522] = "<Харан прочищає горло.>$B$BМи пройшли тунелем Палючого Ущелини й опинилися на спустошеній пустці, що утворювала ущелину. Згадуючи те, там панувала моторошна тиша. Єдиною небезпекою, з якою ми зіткнулися, була місцева дика природа: істоти, з якими мої люди легко впоралися.$B$BМи відносно легко дісталися до Чорнокам’яної гори й без жодних перешкод пройшли крізь кам’яні споруди.",  -- db:2478
[76082690] = "Коли ми просувалися через Палаючі степи, на нас влаштували засідку. Їх, мабуть, було з сотню... Карлики Темного Заліза! Вони виринали зі стін, зі скель у степах; з кожної щілини, затишного куточка та щілини, що потрапляли в поле зору. Вони накинулися на нас, перевершивши чисельністю охоронців та тих небагатьох відважних героїв, які погодилися допомогти нам у цій місії.$B$BОдне було ясно: це була ретельно спланована засідка. Складалося враження, ніби вони знали кожен наш крок ще до того, як ми його зробили...",  -- db:2479
[419962545] = "Як інакше це могло статися? Хтось, мабуть, попередив «Темні Заліза».$B$B<Харан погрожує тобі кулаком.>$B$BКлянуся, якщо я коли-небудь виберуся звідси, я присвячу решту свого життя пошукам зрадника.",  -- db:2480
[353799380] = "На чому я зупинився? Ах так, нас захопили в полон. Моїх елітних гвардійців стратили на місці. Мене вони пощадили, а принцесу вивезли на таран. Мене відвели до камер у «Шлаковій ямі», а потім перевели до цієї в’язниці.$B$BI можу лише припустити, що я досі живий, бо вони хочуть вимагати викуп за моє жалюгідне життя. А може, просто з жорстокості — щоб я назавжди переживав у думках ті події, що сталися. Жаль — найжорстокіший тюремник із усіх, $r.",  -- db:2481
[157537489] = "Зараз вона перебуває поруч з імператором Тауріссаном. Він піддав її якомусь потужному закляттю, що впливає на свідомість… а я сиджу тут, абсолютно безпорадний.$b",  -- db:2482
[592432570] = "Тільки дурень наважився б потурбувати мене в моєму лігві.",  -- db:2493
[232667915] = "<Очі Кіруса яскраво світяться>$B$BЗ’їсти тебе цілком чи залишити в живих?$B$BМожливо, ти ще можеш стати мені в нагоді...$B$BКинь виклик моєму слузі, $r. Виживи та принеси мені доказ своєї перемоги.",  -- db:2494
[183563227] = "Бурчить, бурчить...",  -- db:2496
[842978534] = "Шукайте «Алхімію та зілля Єлмака».  Ви знайдете її посеред району «Драг», на захід від величезного дерева.",  -- db:2497
[739011080] = "Зілля та олії — саме цьому вас навчить Єлмак, якщо ви виявитеся гідними. Шукайте його крамницю посеред вулиці «Драг».",  -- db:2497
[948258614] = "Поговоріть із Сару Стілф'юрі в «Палаючому ковадлі».  Відправляйтеся до Долини Честі.  Вона розташована в кінці стежки праворуч від шахти «Ред-Каньйон».",  -- db:2499
[898863636] = "Можливо, Сару Стілф'юрі колись навчить тебе робити сокиру, не гіршу за мою. Знайди його в таверні «Палаюче ковадло» у Долині Честі — йди стежкою праворуч, повз шахту «Ред-Каньйон».",  -- db:2499
[307000027] = "Вам потрібно знайти Замджу біля «Вогнища Борстана» на верхньому рівні «Драга». Підніміться сходами ліворуч, увійшовши до «Драга» з «Долини Сили».",  -- db:2500
[985764792] = "Вам варто повчитися у Зам’ї.  Прямуйте до «Вогнища Борстана» на верхньому рівні «Драга», піднявшись сходами ліворуч від входу з «Долини Сили».",  -- db:2500
[599968560] = "Вам слід завітати до «Рунічних майстерень Годана». Шукайте їх на західному кінці вулиці «Драг», прямо поруч із «Долиною Мудрості».",  -- db:2501
[587368645] = "Чи можеш ти зачарувати мою сокиру?  Мені потрібне постійне зачарування.  Тоді, мабуть, пізніше.  Знайди «Рунічну майстерню Годана» на західному кінці вулиці «Драг», неподалік від Долини Мудрості.",  -- db:2501
[594874528] = "Арнок виготовляє якісні бинти.  Його можна знайти в хатинці «Виживання найсильніших» на березі озера поруч із «Хатинкою Духів» у Долині Духів.  Вона розташована вище та на захід від Долини Сили.",  -- db:2502
[716929980] = "Мабуть, після бою комусь доведеться перев'язати нас, воїнів. Знайдіть Арнока в хатинці «Виживання найсильніших», що розташована поруч із «Хатиною Духів» у Долині Духів. Подивіться вгору та на захід від Долини Сили — там ви побачите озеро. Саме там він і перебуває.",  -- db:2502
[153405496] = "Отой Лумак... завжди рибалить замість того, щоб битися.  Ти знайдеш його на його причалі на озері в Долині Честі.  Коли будеш там, передай від мене привіт Шанкісу.",  -- db:2503
[117958480] = "Риболовля — це спорт для старих, які не загинули в бою!  Знайди Лумака на озері в Долині Честі.",  -- db:2503
[154833593] = "Трави... Вам потрібно поговорити з Джанді в її дендрарії в районі «Драг». За ринком «Асоран» у Долині Мудрості є дерев'яні сходи. Підніміться ними на верхній рівень району «Драг», і ви її знайдете.",  -- db:2504
[593087554] = "Ага, чувак, тобі ж треба «Арборетум Джанді».  Я що, це щойно сказав?  Глок'тар, мабуть, я втомився!  Піднімися дерев'яними сходами за ринком Асорана в Долині Мудрості аж до «Драга», і там, на верхньому рівні, ти знайдеш «Джанді».",  -- db:2504
[714677971] = "Зайдіть до майстерні «Kodohide Leatherworkers» у районі «The Drag». Попросіть покликати Каролека.",  -- db:2513
[719875919] = "«Kodohide Leatherworkers» — саме те, що вам потрібно.  Знайдіть цей магазин у самому центрі району «The Drag».",  -- db:2513
[1577972] = "Знайдіть шахту «Ред-Каньйон» на північному сході від озера, у Долині Честі.  Там поговоріть з Макару.",  -- db:2515
[233962426] = "Макару можна зустріти вдень і вночі на шахті «Ред-Каньйон» у Долині Честі, неподалік від озера.",  -- db:2515
[6993771] = "Тхуд покаже вам, як знімати шкуру з впольованої дичини. Шукайте його в майстерні «Кодохіде» у районі «Драг».",  -- db:2516
[65164600] = "Дуже добре, що ти хочеш вшанувати своїх жертв, знаходячи практичне застосування їхнім тілам. Знайди Тууда в майстерні «Кодохайд Ледерворкс», що розташована в центрі району «Драг».",  -- db:2516
[704400587] = "Магазин «Magar's Cloth Goods» розташований у районі «The Drag». Ви знайдете його на південь від величезного дерева, поруч із шкіряною майстернею «Kodohide Leatherworks».",  -- db:2518
[837416686] = "Одяг!?  Це тобі не допоможе проти міцної сталі!  Ех, якщо ти впевнений, що хочеш стати кравцем, то йди до крамниці «Тканини Магара» у районі «Драг».",  -- db:2518
[132604794] = "У нас є свої обов’язки, $c.  Обов’язки перед Ордою.",  -- db:2533
[34225123] = "Здається, я чую, як він наближається!  Погляньте на захід!",  -- db:2534
[580763750] = "Банк Оргримара розташований у Долині Сили. Шукайте його на північ від головного входу до міста.",  -- db:2554
[988297087] = "Відправляйтеся до Долини Сили та знайдіть Банк Оргримара на південь від Небесної вежі.",  -- db:2554
[747223195] = "Знайдіть Майстра Вітряних Вершників на вершині Небесної Вежі в Долині Сили. Дорас подбає про те, щоб ви знайшли шлях до битви, яку шукаєте.",  -- db:2555
[917879352] = "Як ти думав, де може бути Майстер Вітряних Вершників?  Прямуй на вершину Небесної Вежі в Долині Сили!",  -- db:2555
[473778966] = "Ви шукаєте Уртруна Кланбрінгера в посольстві Орди. Знайдіть його на західній стороні Долини Сили.",  -- db:2556
[569766916] = "Посольство Орди розташоване в Долині Сили, у західній частині.",  -- db:2556
[317706053] = "Це друга будівля праворуч у Долині Сили, на північ від головного входу до міста. Поговоріть із трактирником Гришкою.",  -- db:2557
[919152457] = "Шукайте господиню готелю Гришку в Долині Сили. Її готель розташований у східній частині, на північ від головних міських воріт.",  -- db:2557
[559409332] = "Один із них ви знайдете біля Банку Оргримара, що розташований посеред Долини Сили.",  -- db:2558
[923615727] = "Ви можете забрати свої любовні листи біля банку, що розташований посеред Долини Сили.",  -- db:2558
[105387985] = "Зайдіть до Залу мисливців у Долині Честі, що на захід від Колізею.  Там поговоріть з Ормаком Грімшотом.",  -- db:2559
[139231287] = "Прямуйте одразу до північно-західної частини Долини Честі. Там ви знайдете Зал Мисливців.",  -- db:2559
[31288235] = "Поговоріть із Пефредо в «Хаті Темного Терну» у Долині Духів, що розташована вище та на захід від Долини Сили.",  -- db:2560
[866323036] = "Що, ти не можеш туди телепортуватися?  Зайди до «Даркбріар Лодж», що розташована біля озера в Долині Духів, вище та на захід від Долини Сили.",  -- db:2560
[269029928] = "Заюс та його жерці перебувають у Храмі Духів, що розташований у Долині Духів. Шукайте його на озері, яке знаходиться вище та на захід від Долини Сили.",  -- db:2561
[610016146] = "Зцілення призначене для тих, хто не може терпіти біль.  Однак якщо вам це необхідно, вирушайте до «Хати Духів», що стоїть на березі озера в Долині Духів, вище за Долиною Сили на захід.",  -- db:2561
[232553207] = "Вам потрібно знайти Кардріс Дрімсікер. Вона та інший шаман перебувають у передпокої Фортеці Тралла в Долині Мудрості.",  -- db:2562
[185547950] = "Ваш пошук майже завершився.  Шукайте свою істину у передпокої фортеці Тролла в Долині Мудрості.",  -- db:2562
[413694994] = "Шукаєш Шентула з Братства «Тіньових Стрільців», так? У районі «Драг», навпроти «Дрофферс і Син — утилізація», знайди тунель, що веде вниз до «Тріщини Тіні».",  -- db:2563
[345237948] = "Не дай мені зловити тебе на крадіжці!  Шукай Шентула та його Братство «Тіньових Стрільців» у підземній «Тріщині Тіні».  Знайди тунель, що веде туди, на південь від Долини Мудрості.",  -- db:2563
[491554471] = "Ви шукаєте Грол'дара та Енклаву Темного Вогню? Знайдіть їх у підземній печері під назвою «Ущелина Тіні». До цієї печери ведуть два тунелі: один — на південь від Долини Мудрості, а інший — від «Драга».",  -- db:2564
[625610906] = "Хіба ми щойно не звільнилися від Палкого Легіону, а ти вже знову зв’язуєшся з демонами?  Знайди Енклаву Темного Вогню в підземній печері, відомій як «Розщелина Тіні».  Тунель, що веде туди, ти знайдеш у «Дразі».",  -- db:2564
[702369710] = "Поговоріть із Греззом Рейджфістом у Залі Хоробрих, що знаходиться в Долині Честі.  Заступитеся за мене!",  -- db:2565
[706309213] = "Знайдіть Зал Хоробрих у Долині Честі та поговоріть із Грецом Рейджфістом.  Повідомте йому, що я повернуся після закінчення своєї зміни тут.",  -- db:2565
[103104386] = "Будь ласка, дайте спокій старому духу.",  -- db:2567
[674369617] = "До мене звертаються дуже рідко... Чим можу вам допомогти?",  -- db:2568
[279006504] = "Хе-хе... Ти справді допитливий, чи не так, $n? Ну що ж, ось що тобі треба зробити.$B$BNа північ від цього місця, у старих руїнах, мешкає дуже неприємний гнол на ім’я Міблон Снарлтут. Він охороняє єдиний Евокорінь, про який я знаю, але пильнує його цілодобово! Схоже, він навіть ніколи не спить!$B$BТи можеш підкупити його. Я можу продати тобі приманку, яка йому сподобається — просто поклади її поруч із ним, і це відверне його увагу на достатній час, щоб ти зміг забрати евокорінь. Удачі!",  -- db:2570
[469268000] = "Так, але це принесе вам більше задоволення, якщо ви володієте навичками травництва!  Ви будете доглядати та вирощувати особливі насіння.  Хоча «Вічнозелений мішечок», який ви отримаєте, дозволяє навіть новачкові щось виростити, ті, хто має певні здібності до травництва, отримають більш рясні врожаї.",  -- db:2574
[353998579] = "Вітаю, $c.  Чим цей скромний слуга Крепості Федермун може вам сьогодні допомогти?",  -- db:2575
[394630366] = "Смерть нашого тіла ознаменувала народження нашого духу та наше священне завдання.",  -- db:2595
[228676034] = "Наш лідер, Дум'рел, готовий прийняти цей виклик.",  -- db:2596
[235219967] = "Мені назавжди відмовлено в дотику до каменю. Я ніколи більше не пізнаю величі обробленого заліза...",  -- db:2598
[451816116] = "Вам не дозволяється пройти. Ви не належите до нашого роду, та й виклику ви не кидали.",  -- db:2600
[303316293] = "Наша доля — це загибель усіх, хто стикається з Великим Пожежею.",  -- db:2601
[873117424] = "Наше покарання — це водночас і наше благословення.",  -- db:2602
[144156027] = "Хочеш опанувати стародавнє ремесло?  Хочеш виплавити темне залізо?$B$BЗадобри мене, $r.  Принеси мені жертву, і я розгляну твоє прохання!",  -- db:2604
[954042214] = "Твоя воля сильна, а намір чіткий.$B$BМожливо, ти гідний...",  -- db:2605
[389896204] = "Ти показав мені своє бажання і заплатив дорогоцінним каменем. Я навчу тебе...",  -- db:2606
[710504504] = "Я... Я не зовсім впевнений, як я тут опинився...$B$B Здається, я пригадую, що подорожував... на плоті...$B$B",  -- db:2633
[662986069] = "Заплати мені, і я розповім...$B$BО, привіт, це ж ти, $N! Забудь про це...",  -- db:2634
[631470507] = "Чи не здається вам моє ім'я знайомим? Можливо, ми знали одне одного дуже давно...$B$B Гадаю, мене назвали на честь когось важливої особи...",  -- db:2634
[629761703] = "Привіт! Радий, що ти повернувся, $n. Скажи, ти вже виконав перше завдання, яке я тобі дав? Якщо так, то, можливо, у мене для тебе є друге завдання...",  -- db:2634
[689943030] = "Коли я блукав кратером після того, як тут розбився, я згадав те, що мені колись сказали... «Піднімайся, піднімайся на ту гору попереду», — пролунав голос у моїй голові.$B$BСаме тому, що я його послухав, я й опинився тут, $N!",  -- db:2634
[198677028] = "Давним-давно, під час своїх мандрівок, я зустрів чоловіка, який сказав мені: «Майстре, якщо ти навчишся цим користуватися, то зможеш це отримати».$B$BЯк ви гадаєте, що це означає? Я не знав цього тоді, і, чесно кажучи, не знаю й зараз...",  -- db:2634
[140536072] = "Це таємниця для всіх... включаючи мене!$B$BIЯ радий, що ти мене знайшов — добре, що я не ховаюся в кущах чи під каменем, чи не так?",  -- db:2634
[599414978] = "Дякую, $N! Ти — герой кратера Унгоро!",  -- db:2635
[102604634] = "Рагнарос пануватиме безроздільно!",  -- db:2636
[663520331] = "Випий, $c.  Може, це буде твоя остання!",  -- db:2636
[352195056] = "Якби не «Грім-Гузлер», я б проводив вільний час, відриваючи крила дитинчатам драконів.",  -- db:2636
[887518870] = "Якби не «Грім-Гузлер», я, мабуть, проводив би вільний час, відриваючи крила дитинчатам драконів.",  -- db:2636
[991700815] = "Елементалі води ведуть війну з елементалями вогню, що, по суті, означає, що вони воюють проти нас. Один із їхніх ватажків, Гідраксіс, збирає агентів для своєї справи...",  -- db:2636
[292176711] = "Я чув, що один із вельмож серед водяних елементалів, Гідраксіс, веде війну проти слуг вогню.  Сподіваймося, що він програє!",  -- db:2636
[765462089] = "Водяний володар Гідракс ховається в Азшарі, на острові в Затоці Бур.  Яку ж загрозу може створити цей дурень звідти?",  -- db:2636
[560765134] = "Якщо Гідраксіс залучить до своєї війни ще більше воїнів, це може змінити баланс сил...",  -- db:2636
[189963330] = "Там панують зброя та полум’я, поки хтось не програє і не загине.",  -- db:2637
[734266123] = "Мій батько казав мені, що траплятимуться такі дні, коли до мене підійде незнайомець, і мені доведеться стримувати себе, щоб не вбити $ghim:her;.",  -- db:2637
[890379585] = "Ти вже пробував це пиво «Thunderbrew Lager»?  Воно дуже смачне!",  -- db:2637
[982424174] = "Через годину у мене зміна, але до того часу... вип’ємо до дна!",  -- db:2637
[348758685] = "Ласкаво просимо до табору «Мохаче», відважний $c.  Чим я можу тобі допомогти сьогодні?",  -- db:2638
[177257498] = "Вітаю, $c — якщо ти шукаєш вироби зі шкіри та матеріали для шкіряного ремесла, то потрапив до потрібного «напівпенсіонера-паладина».",  -- db:2639
[564322688] = "Клянуся... якщо Квінт спробує ще раз підкинути мені рибальську приманку, я зрубаю його дерево своїм не надто іржавим мечем.",  -- db:2639
[917498577] = "Схоже, вам може знадобитися переправа через Велике море. Що ж, ви потрапили в потрібне місце — це причал корабля «Мрія Діви», найкращого пасажирського судна, що курсує цими водами. Коли він прибуде, просто підніміться на борт — і, не встигнете озирнутися, як вже будете насолоджуватися сонцем на піщаних пляжах Стренглторна.",  -- db:2640
[984105410] = "Мушу сказати, що в Буті-Бей готують найкращий суп із молюсків у всьому Південному морі. О, вас не цікавить кухня, так? Що ж, тоді дозвольте мені першим привітати вас на причалі «Maiden's Fancy» — найкращого пасажирського корабля, що курсує між Східними Королівствами та Калімдором. Незабаром він має повернутися для чергового рейсу до Ратчета, тож влаштовуйтеся зручніше, поки він не прибуде.",  -- db:2641
[477029820] = "Звісно, немає жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить вас до Андерсіті швидше й безпечніше, ніж будь-який човен, а краєвид звідти справді захоплює дух. До речі, про дихання: на борту цепеліна заборонено палити, а під час польоту заборонено застосовувати вогняні заклинання.",  -- db:2642
[65632619] = "Звісно, немає жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить вас до Андерсіті швидше й безпечніше, ніж будь-який човен, а краєвид звідти справді захоплює дух. До речі, про дихання: на борту цепеліна заборонено палити",  -- db:2642
[618446282] = "Привіт!  Ти саме та людина, яку я шукав.  Сідай і послухай, бо у мене є план, який зробить нас обох багатими!",  -- db:2643
[990170183] = "Мій брат казав, що ми зможемо добре заробити на цьому торговому шляху, але він не сказав мені, що саме я буду жити на цій стороні. Якщо ти повернешся сюди на «Цепеліні», не міг би ти привезти мені щось поїсти? В Оргримарі продають одне з найкращих м’яс, і мені б не завадило щось таке, що не померло за кілька тижнів до того, як перестало рухатися.",  -- db:2644
[70803129] = "Шукайте майстерню «Nogg's Machine Shop» у Долині Честі, на північний схід від шахти «Red Canyon Mining».",  -- db:2653
[268804460] = "Ти знайдеш того гобліна та його магазин іграшок у Долині Честі.",  -- db:2653
[851929565] = "Привіт, $n. Якщо ти хочеш дізнатися щось нове про кулінарію, завітай до мене в будь-який час.",  -- db:2676
[235404456] = "<Леді Престор грізно дивиться на вас.>",  -- db:2693
[91107596] = "Я стояв прямо поруч із тобою, недоумку. Я знаю, чого ти прагнеш.",  -- db:2694
[43273559] = "Ви прагнете послабити нашу глобальну оборону, аби задобрити параноїдального суддю та зграю негідників, які, найімовірніше, страждають від теплового удару.",  -- db:2695
[502610764] = "Звісно, ні, дорогий $g boy:girl;. Такі «авантюристи», як ти, часто стають жертвами обставин; вони опиняються в епіцентрі політичних драм, що зазвичай розгортаються між народом і королівською родиною.$B$BТож моя порада тобі — пошукати щось інше, а точніше: нову кар’єру.$B$BУ цьому світі й так вистачає героїв.",  -- db:2696
[48769870] = "Чого ти хочеш? *хик*",  -- db:2713
[53662002] = "Того дня Віндзор був особливо примхливий — і повірте, для Віндзора це справді грандіозне досягнення. Він постійно повторював мені, що «щось тут не так». Ну, він не жартував!$B$BМи були посеред гори Блекрок, коли на нас напали ці огидні тварини. Я, звісно, маю на увазі орків. Слухайте уважніше, гаразд? Коли вони кинулися на нас, було чутно лише бурчання та брязкіт сталі.",  -- db:2714
[935405834] = "Я проти п’ятдесяти орків? Я ж не дурень, $N. Мій тато завжди казав мені: «Дискредитація — це найкраща частина хлібця», чи щось таке, і я розумів, що це означає.",  -- db:2715
[106765345] = "Гаразд, гаразд. У будь-якому разі, я так би мовити, зник у тіні.$B$BЦе не дуже сподобалося Віндзору, враховуючи, що він і так був надзвичайно роздратований. Тож він почав крутити старого Айронфоу і кричати на орків, наче божевільний.",  -- db:2716
[721791930] = "Ага. Ти ніколи не чув про «Залізного ворога»? Той легендарний молот, що вбиває орків? Ага, ага, це був молот старого Віндзора. Він розповідав мені, що сам Франклорн Форджрайт викував цей молот для свого пра-пра-прадідуся. ТІЙ САМИЙ Франклорн Форджрайт: Темнозалізний, який відповідальний за кам’яні архітенк... будівельні штуки. Він також казав, що у молота був близнюк, який Франклорн залишив собі. Здається, він називав його «Айронфел» чи щось таке.",  -- db:2717
[865254786] = "То на чому я зупинився? А, так, отже, орки кинулися на Віндзора, а Віндзор? Ну, він не поворухнувся ні на дюйм. Він стояв, не змигнувши, поки вони на нього накидалися, по десять за раз. Я бачив лише сяйво «Айронфоу» та море крові. Це тривало годинами, а може, й днями. Я вже не пам’ятаю. У будь-якому разі, НАРЕШТІ це скінчилося.",  -- db:2718
[800814609] = "Помер? Ти що, з глузду з’їхав, $N? Вибачте, $g пане/пані: $N! Віндзор не помер би від п’ятдесяти орків. Так само, як тельсамарська кров’яна ковбаса — найсмачніша страва у світі, він стояв там: він був укритий шматками орків з голови до ніг, просочений приблизно вісімнадцятьма шарами їхньої крові, але він точно був живий… і дуже, дуже розлючений.",  -- db:2719
[170596776] = "Чому ти постійно повторюєш, що він загинув? Хто тобі сказав, що він загинув? Я ніколи не казав, що він загинув.$B$BВін просто зник, ось і все.$B$BРозумієш, судячи з усього, ми опинилися посеред великої битви між орками та карликами Темного Заліза. Орки, як брудні й жалюгідні негідники, якими вони є, з’явилися ще рано, розставляючи пастки та інші диявольські пристрої, які ти, мабуть, не зрозумієш.",  -- db:2720
[740885200] = "«Гноми не напиваються, $g містер:місіс;. Я просто трохи розхлябався.»$B$BТа що там, Віндзор? Гадаю, він десь у Глибинах Чорної Скелі. Це місто Темного Заліза — для вас, неосвічених людей.",  -- db:2721
[559148780] = "Повільніше! Я саме до цього й підходив!$B$BОтож він стояв там, весь у крові та кишках, що стікали з нього, як раптом з’явилися…$B$B«Темні Залізні»! Ти що, ні слова не почув з того, що я казав??$B$BНу, «Темні Залізні» трохи хитріші за тих орків із «Чорної Скелі». Вони прийшли підготовленими. Під «підготовленими» я маю на увазі, що їх було близько 300... *хик* Вибачте.",  -- db:2722
[223348259] = "$G Містер:Міссі;, якби я не знав краще, то подумав би, що ти одна з тих «особливих» людей. Ми називаємо їх трогами.$B$BУ Віндзора не було ніяких суперечок із Темними Залізними — зрештою, найкращим другом його прапрапрадідуся був саме Темний Залізний. І, мабуть, саме тому та армія Темних Залізних не вбила його одразу ж, як тільки побачила.",  -- db:2723
[729680222] = "Тобі бракує знань. Повертайся до мене, коли вдосконалиш свої навички плавлення!",  -- db:2724
[492932333] = "Нарешті! Затуліть вуха пальцями — ваш мозок, мабуть, щойно збільшився на п’ять розмірів, і я боюся, що він може витекти.$B$BОтже, Темні Залізні пощадили його життя й взяли в полон. Їхній ватажок, якийсь самовпевнений, зарозумілий тип на ім’я Тауріс-щось-там, забрав Айронфоу собі. І це було востаннє, коли я бачив старого Віндзора... *хик* Вибачте.$B$B",  -- db:2725
[906599015] = "Корупція Фелвуда ув’язнила мою душу тут… Можливо, я ніколи не знайду спокою…",  -- db:2726
[524213633] = "Ласкаво просимо до «Грім Газзлер»!",  -- db:2727
[52424942] = "Обов’язково спробуйте наше ель «Темне залізо».  Кажуть, місцеві гноми просто не можуть ним насититися.",  -- db:2727
[661490076] = "Мій господар, Плаггер Спаззрінг, — хороший начальник.  І він заробляє купу грошей.  Його кишені просто розриваються!",  -- db:2727
[731454562] = "Гарна ідея!",  -- db:2728
[332720244] = "Ще раз дякую, $N.  Ми з Rocknot справді чудово ладнаємо!",  -- db:2729
[656127687] = "Ти бачив усі ці дивовижні речі тут, у кратері Унгоро, $N? Це просто неймовірно. Звісно, не настільки дивовижно, як деякі речі, які я можу створити завдяки своїм інженерним навичкам, але з огляду на те, що тут усе природне… це зовсім непогано.$B$BМій дядько Ремтревел обожнює такі старовинні місця, як це. Я нібито йду його слідами — теж хочу відкривати нові речі з втрачених культур!",  -- db:2734
[14625186] = "Хм, у мене немає мітрілових гільз. Вони в мене всі закінчилися. Це все, що тобі потрібно, щоб полагодити А-Ме? О, це було б чудово!$B$BMітрілові гільзи не так вже й важко знайти в цивілізації. Просто попроси будь-якого досвідченого інженера виготовити тобі одну. Гадаю, для цього знадобиться кілька злитків мітрілу, але якщо ти мені допоможеш, я подбаю, щоб ти отримав гідну винагороду!",  -- db:2735
[591586518] = "Ось це — найкращий і найсучасніший засіб пересування, який тільки можна створити за гроші. Що? Трамвай «Діпран»? Гноми? Послухай, друже, якщо ти віриш у цю нісенітницю, то я маю тобі на продаж статую в Странглторні. То що, підеш пішки до Гром'Гола чи поїдеш із шиком на цій чудовій літаючій машині? Вибір за тобою.",  -- db:2753
[331621815] = "Ти на мене дивишся, $gladdy:lassy;?",  -- db:2758
[145772735] = "Я візьму пінту елю «Dark Iron».  О, ви ж не офіціант/офіціантка?",  -- db:2758
[371312465] = "Мені здається, Плаггер занадто переповнив одну зі своїх бочок.  Схоже, вона ось-ось вибухне!",  -- db:2758
[156001721] = "Не заважай мені, коли я розважаюся...",  -- db:2758
[348384643] = "Куди вам потрібні вказівки?",  -- db:2760
[321095201] = "У вас є якісь нові скарби, які ви хочете зберегти цілими й неушкодженими?  Тоді вам варто здати їх на зберігання в «Сховище» у родини Стоунмантлів.  $B$«Сховище» розташоване всього за кидок молотка на північний схід від входу в Айронфордж.",  -- db:2761
[959302212] = "Чи є у вас якісь нові скарби, які ви хочете зберегти цілими й неушкодженими? Тоді вам варто здати їх на зберігання в «Сховище» до родини Стоунмантлів. «Сховище» розташоване всього за кидок молотка на північний схід від входу в Айронфордж.",  -- db:2761
[673025850] = "Банк?  А, ти маєш на увазі «Сховище»!  Немає безпечнішого місця для зберігання твоїх цінностей, ніж «Сховище». Ти знайдеш його на північний схід від входу до Айронфорджа.",  -- db:2761
[938191212] = "Хочете покататися на грифоні, так?  З цього приводу вам слід звернутися до Гріта Турдена.  $B$Його можна знайти на східній стороні Великої Кузні, у самому центрі Айронфорджа.",  -- db:2762
[904661142] = "Ах, немає нічого кращого, ніж поїздка на грифоні, чи не так?  Нехай нічні ельфи залишають собі своїх бегемотів, а мені — тільки грифона та вітер у волоссі!  $B$BНу що ж, не буду більше затримувати тебе. Просто підійди до Гріта Турдена на східній стороні Великої Кузні, і він вкаже тобі шлях.",  -- db:2762
[882027536] = "Якщо ти думаєш про створення гільдії, тобі потрібно буде зареєструвати її у Джондора Стілброу в Центрі для відвідувачів Айронфорджа. Просто рушай на південний схід від воріт Айронфорджа, щоб знайти його.",  -- db:2764
[303583169] = "Що ж, для створення гільдії вам знадобляться документи, і Джондор Сталебровий допоможе вам розпочати цей процес. Коли ви будете готові приступити до справи, його можна знайти в Центрі для відвідувачів Айронфорджа.",  -- db:2764
[562579112] = "Якого саме тренера ви шукаєте?",  -- db:2766
[614734230] = "Таверна?  А, ви хочете випити трохи найкращого елю, який може запропонувати Айронфордж?  Тоді вам слід завітати до таверни «Кам’яний вогонь».  $B$Ви знайдете її ліворуч від входу до Айронфорджа, якщо йдете туди, або праворуч — якщо виходите з міста.",  -- db:2768
[370706092] = "Таверна?  А, ви хочете випити трохи найкращого елю, який може запропонувати Айронфордж?  Тоді вам слід завітати до таверни «Кам’яний вогонь». $B$Ви знайдете її ліворуч від входу до Айронфорджа, якщо йдете туди, або праворуч — якщо виходите з міста.",  -- db:2768
[1682547] = "Якщо вам потрібна корчма, то «Корчма «Кам’яний вогонь» — саме те, що вам потрібно. Ви знайдете її ліворуч від входу до Айронфорджа, якщо йдете туди, або праворуч, якщо виходите звідти.  $B$BО, і якщо ви підете туди, то скажіть їм, щоб приготували для мене кухоль пива.",  -- db:2768
[981888330] = "Поруч із таверною «Стоунфайр» ви знайдете поштову скриньку. Вона розташована трохи північніше від воріт Айронфорджа.",  -- db:2769
[304474612] = "Фу!  Поштові скриньки...  Останнім часом я отримую лише спам!  $B$BЗбільште розмір цього... зменште розмір того... дійте зараз, щоб отримати безкоштовний «Меч драконоборця».  Мені доводиться змінювати номер поштової скриньки кожні два місяці!  $B$BНу, не можна сказати, що я вас не попереджав.  Якщо шукаєте поштову скриньку, вона знаходиться прямо біля таверни «Кам’яний вогонь».",  -- db:2769
[8036977] = "Нещодавно я випадково почув, як Регнус Громограніт у Залі зброї хвалився новим трофеєм для своєї лігвища. Якщо ти хочеш потренуватися під керівництвом досвідченого мисливця, то Регнус — саме та людина, до якої варто звернутися.",  -- db:2770
[727521973] = "Чи є у тебе задатки, щоб стати вправним мисливцем?  Ну, $gladdie : lassie;, це покаже тільки час.  Тільки не стріляй у яблука, які лежать на головах людей, доки не поговориш із Регнусом у Залі зброї.",  -- db:2770
[648270472] = "Та маленька чарівниця, Бінк, що сидить у Залі Таємниць, напевно зможе допомогти вам у будь-яких магічних справах.  $B$BЗал Таємниць розташований трохи північніше від воріт Айронфорджа.",  -- db:2771
[682788110] = "Та маленька чарівниця, Бінк, що мешкає у Залі Таємниць, напевно зможе допомогти вам у будь-яких магічних справах.$B$BЗал Таємниць розташований трохи північніше від воріт Айронфорджа.",  -- db:2771
[37346293] = "Ну, у Залі Таємниць, що на північ від воріт Айронфорджа, ви напевно знайдете курси з магічних мистецтв. Джулі Стормкеттл завжди можна там зустріти — вона постійно занурена в книгу.",  -- db:2771
[808145636] = "Ах, Бреанна Флінткраг. У неї справді чарівні руки. З усіх питань, пов’язаних зі священством, слід звертатися саме до Бреанни. $B$Вам слід рухатися на північ від воріт Айронфорджа до Залу Таємниць. Саме там ви її знайдете.",  -- db:2772
[492507823] = "Ах, немає нічого кращого за священика, щоб вилікувати те, що вас турбує. Звісно, хороша велика пінта теж виліковує багато недуг, але не думаю, що Бреанна Флінткраг викладає пивоваріння. Мабуть, вам доведеться задовольнитися навчанням у священика в Залі Таємниць.",  -- db:2772
[74953506] = "Вам варто зустрітися саме з Брандуром Айронхаммером. Ви знайдете його в Залі Таємниць, що на північ від воріт Айронфорджа.",  -- db:2773
[121199309] = "Ах, старий добрий Брандур Залізний Молот.  Немає сумнівів, що він надасть тобі пораду, якої ти шукаєш, $glad : lass;.  Ти знайдеш його у Залі Таємниць на північ від воріт Айронфорджа.",  -- db:2773
[698256483] = "А навіщо вам взагалі потрібні послуги когось із таких типів?  Нам і так вистачає клопоту з тим розбійником, Хульфданом Чорнобородим, у «Загубленій печері» — чи мені ще й на вас звертати увагу?",  -- db:2774
[748111203] = "Усі ці шахраї тусуються в «Печері Занедбаних», на північ від воріт Айронфорджа.  Готовий побитися об заклад, що ти там знайдеш Фентвіка, який, без сумніву, перераховує монети з чергової пограбованої сумки.  Я його колись-небудь спіймаю!  $B$BTим часом я й за тобою теж стежитиму, $glad : lass;.",  -- db:2774
[367403201] = "Де ще краще шукати похмуру й таємничу особу, як не в темній частині Айронфорджа, що має влучну назву «Печера Загублених». Там напевно можна знайти Тістлхарта, який, ймовірно, саме зараз викликає якусь огидну істоту, щоб та виконувала його накази.",  -- db:2775
[446394175] = "Чаклун, еге ж...  Ну, якщо ти маєш намір займатися тут такими справами, то краще тримай своїх демонів на повідку $gboyo : girlie;.  Я не люблю демонів, але обожнюю розрубувати їх своєю сокирою.  Розумієш, про що я?  $B$BА тепер просто відчепися від мене й загубися в Печері Загублених.  Саме там ти й знайдеш того чаклуна, Тістлхарта.",  -- db:2775
[322223800] = "Ой! Ти хочеш навчитися мистецтву воїна, так?  Келструм Камнелом випробує твої сили!  Просто вирушай до Залу зброї, що на схід від воріт Айронфорджа.",  -- db:2776
[3249232] = "Келструм — базікало і хвалько… і якби цього було замало, він ще й один із найвправніших воїнів, яких ви коли-небудь зустрінете!  $B$BI кажу вам: якщо ви хочете навчитися воїнському ремеслу, то саме до нього вам і слід звернутися.  Я впевнений, що його можна знайти в Залі зброї на схід від Воріт Айронфорджа.",  -- db:2776
[887789383] = "Якого тренера з професійної підготовки ви б хотіли знайти?",  -- db:2793
[212219349] = "Вам потрібен інструктор з алхімії?  Ну, я щойно звідти повернувся.  Ви знайдете пані Берріфіз у Тінкер-Тауні, де збираються гноми.",  -- db:2794
[523028839] = "Ти шукаєш інструктора з алхімії, так?  Я щойно звідти повернувся.  Ти знайдеш пані Берріфіз у Тінкер-Тауні, де збираються гноми.  $B$B::зітхання:: ...чому ж, чому я не взяв те синє зілля?",  -- db:2794
[764601549] = "Ви потрапили в потрібне місце $glad : lass;!  Сюди з’їжджаються люди з усього світу, щоб навчитися ковальській справі.  Ви знайдете Бенгуса Глибококувального, який стукає молотом по ковадлу посеред нашого чудового міста, біля самої Великої Кузні.",  -- db:2795
[468410247] = "Ти справді питаєш мене, де знаходиться коваль?  Хіба ти не чув про Велику Кузню!?  Усі наші найкращі ковалі збираються там, щоб виготовляти зброю та обладунки!  $B$BВона розташована прямо в самому центрі Айронфорджа, і саме там ви знайдете одного з наших найталановитіших ковалів — Бенгуса Діпфорджа.",  -- db:2795
[818467109] = "Це ж інструктор з кулінарії, так?  Тоді вирушай до «Бронзового казана», що на північно-східній стороні Великої Кузні.  Деріл Рікнуссун навчить тебе готувати чудову страву, яка неодмінно поверне тобі сили!",  -- db:2796
[825693141] = "Ой! Цей Даріл Рікнуссун — просто геніальний кухар! Він готує таке гостре чилі, що ним можна загартовувати сталь! Не думаю, що він поділиться з тобою рецептом, але точно допоможе тобі стати хорошим кухарем.  Ти знайдеш його в «Бронзовому казані», що розташований на північно-східній стороні Великої Кузні.",  -- db:2796
[976469905] = "А, гадаю, вам знадобиться Гімбл Тістлфазз, якщо ви хочете опанувати професію чарівника. Ви знайдете Гімбла в його крамниці «Арканерія Тістлфазза», що розташована прямо біля майстра грифонів у «Великій кузні».",  -- db:2797
[397233068] = "Ой!  Будьте обережні з тим, що зачаровуєте $glad : дівчино;.  Я зачарував свою чашку, щоб з неї не пролилася ні краплі, але тепер не можу з неї пити!  Справжня трагедія.  $B$BОбов’язково прислухайтеся до моєї поради, коли побачите Гімбла.  Він буде у своїй крамниці, прямо біля Майстра грифонів у «Великій кузні».",  -- db:2797
[199149925] = "Тобі до душі ремесло майстра-винахідника?  Без сумніву, ти захочеш відвідати Спрінгспіндла Фізлгіра в Містечку Майстрів.  $B$BПросто рушай на схід від воріт Айронфорджа або йди за звуком вибухів.",  -- db:2798
[269143733] = "О, значить, ти шукаєш Спрінгспіндла Фізлгіра.  Ой, цей маленький гном і його пристосування...  Послухай, якщо підеш до його крамниці в Тінкер-Тауні, тримай руки при собі й не гладь жодну з його механічних овець!  $B$BВибухові вівці... навіщо взагалі створювати таке!?",  -- db:2798
[276719625] = "Надання першої допомоги — це дуже корисна навичка. Наша штатна інструкторка, Нісса Файерстоун, може показати вам, як це робити. Шукайте її на південній стороні «Великої кузні» біля лікаря в Айронфорджі.",  -- db:2799
[122393508] = "Перша допомога?  Ну, на мій погляд, ти не виглядаєш пораненим.  Якщо ти справді хочеш навчитися надавати першу допомогу, то Нісса Файерстоун — саме та людина, у якої варто цьому навчитися.  Зайди до неї в крамницю «Лікар Іронфорджа», що розташована біля Великої Кузні.",  -- db:2799
[774737299] = "Грімнур Стоунбренд розповідатиме вам неймовірні історії про ту рибу, яка вислизнула, але він все одно залишається одним із найкращих рибалок у цих краях. У «Печері Загублених» він відкрив крамницю під назвою «Мандрівний рибалка».",  -- db:2800
[509614708] = "Я колись чув, як старий Грімнур розповідав, що виловив меч. А може, це був меч-риба? Чорт забирай того Грімнура — він розповів стільки рибальських байок, що я вже й не пам’ятаю, що є чим.  Ну, чому б тобі не зайти до нього в «Печеру Загублених» і не попросити його розповісти, що це було.",  -- db:2800
[588079354] = "Квіти, насіння та інше?  Це саме та сфера, в якій Рейна Стоунбранч є справжньою експерткою.  Ви можете знайти її, коли вона доглядає за своїми рослинами, у «Лікаря Іронфорджа», що розташований у південній частині Великої Кузні.",  -- db:2801
[188328702] = "О, ти хочеш навчитися збирати ромашки, так?  Ха!  Я просто дражню тебе, $gladdie : lass;.  $B$BA — чудова професія, і Рейна Стоунбранч може показати тобі, як це робиться.  Вона працює в «Лікарні Айронфорджа», що на південній стороні Великої Кузні.",  -- db:2801
[246921794] = "Фімбл Файнспіндл має майстерню на північно-західній стороні Великої Кузні.  Готовий побитися об заклад, що він зможе навчити вас виготовляти чудові обладунки.",  -- db:2802
[973491745] = "Ти точно не хочеш стати ковалем? Ну, якщо ти твердо вирішив займатися шкіряним ремеслом, то тобі краще поговорити з Фімблем Файнспіндлом у його крамниці на північно-західній стороні Великої Кузні.",  -- db:2802
[589524743] = "Чи є тут інструктори з гірничої справи?  Ви що, не знаєте, де перебуваєте!?  $B$BОдного з найкращих гірників у всьому Дун-Морозі ви знайдете в Гільдії гірників Глибокої Гори, що розташована на північному боці Великої Кузні.  Там Геофрам Боулдертоу покаже вам справжнє мистецтво гірничої справи.",  -- db:2804
[958938877] = "Ну-ну! Ти потрапив у саме те місце, щоб навчитися гірничій справі, $gboyo : girlie;! У Гільдії гірників «Глибока гора» мешкає сам Геофрам Боулдертоу. Кращого наставника, ніж він, годі й шукати.",  -- db:2804
[657062247] = "З приводу зняття шкіри звертайтеся до Балтуса Стоунфлейера. Якщо з чогось можна зняти шкіру, він навчить вас, як це зробити. Просто підійдіть до крамниці «Шкіряні вироби Файнспіндла», що розташована на північній стороні Великої Кузні.",  -- db:2805
[313754504] = "Знімання шкур?  Єдине, що ти, здається, зміг би зняти, — це шкіру з власного коліна!  Ха!  А тепер чому б тобі не піти до Балтуса Стоунфлейера, щоб він навчив тебе, як правильно знімати шкури з тварин.  Ти знайдеш його в крамниці «Шкіряні вироби Файнспіндла» на північній стороні Великої Кузні.",  -- db:2805
[900030872] = "Цей Йормунд Стоунброу справді має хист до шиття. Якщо вам знадобиться навчання, то ви знайдете його в крамниці «Стоунброу» на північній стороні Великої Кузні.",  -- db:2807
[758662753] = "Можливо, ви цього не знаєте, але, окрім того, що Йормунд — вправний кравець, він ще й мисливець на велетнів!  Мабуть, він підслухав, як дехто з нас ділився історіями, коли вигукнув, що вбив сімох одним ударом!  $B$Завітайте до нього в крамницю на північному боці Великої Кузні й спробуйте дізнатися, чи розповість він вам цю історію!",  -- db:2807
[444202409] = "Я страждав, але тепер відчуваю, як це повільно відходить від мене. Я відчуваю себе... вільним.",  -- db:2809
[860234224] = "Кришталеві пілони Ун'Горо залишаються загадкою для всіх. Для нечисленних мешканців цих місць вони є предметом легенд, а їхнє призначення викликає безліч припущень.",  -- db:2810
[369176934] = "При детальному огляді пілона ви помічаєте невеликий столик, на якому лежать сині, жовті та зелені кристали, розташовані, як видається, у певній комбінації.$B$Велике синє коло з кристалів з обох боків оточене меншими колами — жовтим та зеленим.$B$BВи уважно запам'ятовуєте кольори кристалів, розуміючи, що Дж. Д. буде дуже зацікавлений у тому, щоб дізнатися про вашу знахідку.",  -- db:2811
[709008922] = "При детальному огляді пілона ви помічаєте невеликий столик, на якому лежать жовті, червоні та зелені кристали, розташовані, як видається, у певній компоновці.$B$Велике жовте коло з кристалів з обох боків оточене меншими колами — одним із червоних кристалів та іншим із зелених кристалів.$B$BВи уважно запам'ятовуєте кольори кристалів, розуміючи, що Дж. Д. буде дуже зацікавлений у тому, щоб дізнатися про вашу знахідку.",  -- db:2812
[543968910] = "При детальному огляді пілона ви помічаєте невеликий столик, на якому лежать червоні, сині та зелені кристали, розташовані, як здається, у певній комбінації.$B$BA Велике червоне коло з кристалів з обох боків оточене меншими колами — синім та зеленим.$B$B Ви уважно запам'ятовуєте кольори кристалів, розуміючи, що Дж. Д. буде дуже зацікавлений у тому, щоб дізнатися про вашу знахідку.",  -- db:2813
[88611991] = "Вітаю, $c. Для декого полювання — це спосіб життя, обрана професія. Для інших це своєрідне захоплення, знак мужності або обряд ініціації, залежно від вашого племені.$B$BДля мене раса та професія нічого не значать — я поважаю лише випробування вашого духу та розуму. Змогти протистояти силам природи та випробувати всі свої вміння — ось справжня ознака честі.$B$BЯкщо ти бажаєш випробувати себе та заслужити мою повагу, то розкажи мені більше.",  -- db:2816
[819714190] = "Ти, мабуть, не очікував зустріти мене в цій печері, правда?$B$BМене звати Дж.Д., і я, чесно кажучи, не можу багато розповісти про те, як я тут опинився, але можу сказати, що ця печера тепер — мій дім!$B$BЯ проводжу час, вивчаючи дивні кристали, які можна знайти по всьому кратеру.",  -- db:2817
[258229114] = "Я сам зможу повернутися до Твердині — мені просто потрібна допомога, щоб вибратися з цього вулика!$B$BХто... хто ти такий?",  -- db:2818
[440754605] = "«Палаючі степи» — «Табличка Семи»",  -- db:2819
[745159432] = "Символи на табличці ретельно розшифровані...",  -- db:2820
[266953067] = "Ти ступив на шлях честі, $N. Мої предки поважають твою рішучість, але я не дам тобі свого схвалення, доки ти не виконаєш до кінця мої завдання.$B$BТи знаєш, що тобі треба зробити, якщо хочеш довести, що ти мисливець у душі.",  -- db:2821
[954251681] = "Я щиро вітаю тебе, $c, як і «Розбита Рука».$B$BНе дивись так здивовано, $N. Навіть на найвищих висотах Оргримара є тіні — там щось має ховатися. «Розбита Рука» охоче бере на себе цю роль. Навіть Трал, незважаючи на своє добре серце, визнає, що «Рука» необхідна для забезпечення безпеки орків і тролів.$B$BАле ти тут не для того, щоб говорити про мої справи, ти тут з іншої причини.",  -- db:2822
[515263406] = "Кратер Ун'Горо розташований далеко на півдні від Калімдора. За Тисячею Голками в Танарісі. Зверніть увагу на великі плаваючі камені... вони позначають вхід до кратера. Але будьте обережні... шлях нелегкий. Неподалік від входу ховаються раптори.",  -- db:2823
[665740666] = "Завдяки вам ми тепер можемо розкрити таємниці кристалів і загадкових пілонів, $N. Якщо вам коли-небудь знадобиться додаткова інформація, будь ласка, завітайте до мене ще раз!",  -- db:2833
[298781473] = "Східний пілон приймає сині, жовті та зелені кристали.$B$BВін зосереджується на енергії, яку можна створити, використовуючи сині кристали як основне джерело енергії. Існує два можливі ефекти: один надає бонус до духу, а інший створює щит, що завдає шкоди.$B$B«Кристальна сила» вимагає синіх та зелених кристалів. Це забезпечить вам збільшення духу.$B$B«Кристальна вежа» вимагає синіх та жовтих кристалів. Це створить щит, який завдає шкоди нападникам.$B$B",  -- db:2834
[18069158] = "Равазаври, що мешкають тут, в Ун’Горо, схоже, є родичами рапторів з Пусток — надзвичайно розумні, непередбачувані та наділені своєрідним кодексом поведінки. Наймогутнішим із них, з ким мені доводилося стикатися, є Лар’корві. Він — одна з найнебезпечніших тварин, яких я коли-небудь бачив. У мові таурахе «Лар’корві» означає «гострий кіготь», але це не віддає йому повної справедливості.$B$BНе варто недооцінювати Лар’корві, якщо ви коли-небудь плануєте полювати на нього, але я допоможу вам усім, чим зможу, якщо ви це зробите.",  -- db:2835
[705295816] = "«Північний пілон» приймає жовті, червоні та зелені кристали.$B$BОсновна увага приділяється енергії, яку можна створити, використовуючи жовті кристали як основне джерело енергії. Існують два можливі ефекти: один завдає шкоди, а інший — нейтралізує її. $B$B«Кристальний заряд» вимагає червоних і жовтих кристалів. Це спричинить потужний вибух, який оглушить ваших ворогів.$B$B«Кристальне відновлення» вимагає жовтих і зелених кристалів. Це надасть вам цілющу ауру.",  -- db:2836
[125621281] = "Західний пілон приймає червоні, зелені та сині кристали.$B$BПілон зосереджується на енергії, яку можна створити, використовуючи червоні кристали як основне джерело енергії. Існує два можливі ефекти: один підвищує ваш захист від шкоди, а інший послаблює захист супротивника.$B$B«Кристальна оборона» вимагає червоних і зелених кристалів. Це забезпечить вам підвищення броні.$B$B«Кристальний удар» вимагає синіх і червоних кристалів. Це може знизити броню конкретної цілі.",  -- db:2837
[395594493] = "Звісно, $N. Ось ще одне для тебе.",  -- db:2838
[49478663] = "Ці колись прекрасні ліси страждають від жахливого прокляття!  Згубні сили перетворюють все живе тут на тіні колишніх себе.  Якщо ти не є поплічником цієї згубної сили, то, можливо, ти зможеш допомогти мені повернути Фелвуд!",  -- db:2842
[401782704] = "Тауре?$B$BДруїдка-тауренка дивиться на тебе з надією, але очевидно, що ти не можеш порозумітися з нею словами.  Не знічуючись, вона вказує на себе й посміхається.  Потім вона вказує на тебе й знову посміхається.  Нарешті вона кілька разів жестом вказує на стежку, що веде на південь.$B$BМожливо, вона натякає, що трохи далі по дорозі є друїд, з яким ти зможеш поговорити?$b",  -- db:2843
[577033772] = "«Дарнасса?»$B$BДруїдка-нічна ельфійка дивиться на тебе з надією, але очевидно, що ти не можеш з нею спілкуватися словами.  Не зневірившись, вона вказує на себе й посміхається.  Потім вона вказує на тебе й знову посміхається.  Нарешті вона кілька разів жестом вказує на стежку, що веде на північ.$B$BМожливо, вона натякає, що трохи далі по дорозі є друїд, з яким ти зможеш поговорити?",  -- db:2845
[396668701] = "ДОПОМОЖІТЬ!!!!",  -- db:2846
[35506958] = "Це «Crest» вас направив?",  -- db:2847
[959442191] = "У Фелвуді є рослини, які можна врятувати від спотворення, якщо нанести на них мазь Сенаріону. Я знаю, як приготувати цю мазь із кількох різних видів предметів; залежно від ваших навичок, у вас може бути кілька варіантів, як мені допомогти.$B$BДля роботи тут вам також знадобиться маяк Сенаріону — пристрій, що дозволяє бачити забруднення та спотворення природи, які не помітні неозброєним оком.",  -- db:2848
[256456872] = "Останки вкриті мухами та личинками.",  -- db:2850
[237347998] = "Цей величний храм був зведений багато років тому нічними ельфами, які колись населяли ці землі.$B$BЯкі таємниці він може приховувати?",  -- db:2873
[943002661] = "Таємниці, приховані в пілонах кратера Ун'Горо, тепер належать вам. Відвідуйте пілони в будь-який час, щоб скористатися їхньою силою та отримати корисні ресурси.",  -- db:2933
[129513499] = "Ця рослина-пісня-квітка виділяється, немов скеля, серед моря корупції, яким є Фелвуд. Її пелюстки мають потужний аромат, що піднімає настрій і зміцнює рішучість.",  -- db:2953
[702163706] = "Ласкаво просимо до Танаріса, $N. Чим можу вам допомогти сьогодні? На мій погляд, ви не схожі на коваля, але я знаю, що зовнішність може бути оманливою.",  -- db:2954
[355134480] = "Ця рослина «вітроквітка» виділяється, немов маяк у темряві Фелвуда. З рослини звисають соковиті ягоди, готові до збору.",  -- db:2955
[565103047] = "Ця міцна рослина з коренем-віппером є повною протилежністю хворобливому духу корупції, що панує у Фелвуді.  Ніжні й здорові коріння дають смачні бульби, які лежать на землі поруч із рослиною.",  -- db:2956
[599830040] = "Ця яскрава рослина «Нічний дракон» різко контрастує з демонічним прокляттям, що роздирає Фелвуд. З рослини важко звисають рідкісні й соковиті плоди, відомі як «Подих нічного дракона».",  -- db:2957
[948133047] = "Мені не подобається розмовляти.",  -- db:2973
[488124342] = "Вітаю, $C. За своє життя я бачив чимало завзятих новачків, які прагнуть довести свою цінність для племені. Не слід забувати, що завзяття не замінить мудрості та досвіду.",  -- db:2981
[208161904] = "Вони загублені, $r. Лібрами, написані ельфійськими майстрами. Розкидані по всьому світу, коли на Квель-Талас обрушився Пошесть.$B$BТепер ми шукаємо ці лібрами. Шукаємо, щоб розкрити таємниці, які вони приховують, — щоб відновити колишню могутність.$B$BЯ шукаю десять лібрамів, написаних майстром Каріелем Вінталусом. Якщо ви знайдете лібрам, дозвольте мені поглинути його магічні властивості, і я створю для вас поєднання сил… Звісно, все має свою ціну. Ви побачите, що моя ціна висока; але заплатити вам доведеться.",  -- db:2993
[190598897] = "<Матредіс пильно дивиться на лібрам.>$B$BТи прийшов за злиттям? Ти виконав все, як наказано в лібрамі?",  -- db:2995
[336724329] = "Дай мені аркани, і я створю злиття, смертний.",  -- db:2996
[325705745] = "Справді, рідкісна знахідка.$B$B<Матредіс киває головою.>$B$B Якщо ви бажаєте продовжити, мені знадобляться необхідні компоненти.",  -- db:2997
[272064980] = "Нехай Світло захищає вас сьогодні.",  -- db:2999
[352289889] = "Чого ви хочете від Raze??",  -- db:3001
[575433441] = "Де знаходиться Аукціонний дім?  Він розташований прямо біля воріт Айронфорджа, коли ви в’їжджаєте до нашого чудового міста.  Ви знайдете його прямо навпроти «Сховища».",  -- db:3014
[805872679] = "З усіх дивовижних місць у Дарнассусі, куди б ви хотіли, щоб я вас провів?",  -- db:3016
[410204294] = "Ви можете знайти місце для зберігання своїх матеріальних цінностей у банку Дарнассуса, що розташований у центрі нашого дивовижного міста.",  -- db:3017
[642220791] = "Ще один матеріал $gboy : дівчино, так?  Ну, якщо ти так дбаєш про свої дорогоцінні речі, то, мабуть, захочеш зберігати їх у банку Дарнассуса, що в центрі нашого міста.",  -- db:3017
[977124286] = "Гіпогрифи Веспристуса швидко доставлять вас до місця призначення. Знайдіть його в селі Рут'теран, пройшовши через портал, що розташований у західній частині Дарнассуса.",  -- db:3018
[565406508] = "Саме Веспристуса ви шукаєте. Він пильнує за гіпогрифами, які прилітають і відлітають від підніжжя Телдрасіла. Ви знайдете його, пройшовши через портал на заході Дарнассуса, який перенесе вас до селища Рут'теран.",  -- db:3018
[291474983] = "Якщо ви бажаєте створити гільдію, то вам слід звернутися до головуючої гільдії, Лішеани. Ви знайдете її на Терасі ремісників у північно-східній частині Дарнассуса.",  -- db:3019
[452882166] = "Лишеана може надати вам необхідні документи; вона мешкає на Терасі Ремісників у північно-східній частині Дарнассуса. Нехай ваша дружина принесе славу нічним ельфам!",  -- db:3019
[945808633] = "Хоча я вважаю, що прохолодна трава, якою вкритий Телдрасіл, — не гірше за будь-яке інше ліжко, ліжка, які Саелієнна готує в готелі на Ремісничій терасі, цілком підійдуть тим, хто полюбляє розкіш.",  -- db:3020
[365411592] = "Сонце вже зійшло?  Ніч завжди така коротка!  Ну що ж, Саелієнн добре про тебе подбає.  Ти знайдеш її на «Терасі ремісників» у північно-східній частині Дарнассуса, де вона обслуговує своїх гостей.",  -- db:3020
[736887230] = "Біля банку, який розташований у центрі Дарнасуса, стоїть поштова скринька.",  -- db:3021
[92681913] = "Поштова скринька?  Ви хочете відправити листа чи, можливо, отримали його?  Сподіваюся, це щось приємне!  Поштова скринька розташована прямо біля банку в центрі Дарнассуса.",  -- db:3021
[576620491] = "Тут, у Дарнасусі, ви знайдете досвідчених наставників, які завдяки багаторічним тренуванням і відданості своїй справі довели майстерність обраного ними класу до досконалості. Я направлю вас до того, хто зможе стати вашим наставником — вам залишається лише назвати обраний вами шлях.",  -- db:3022
[155344880] = "Вам пощастило, що ви потрапили до Дарнассуса, де серед наших інструкторів ви можете зустріти таку досвідчену мисливицю, як Йокаста.  Раджу вам завітати до неї в Енклаву Сенаріону та звернутися до неї за наставництвом.",  -- db:3023
[249612490] = "Йокаста була найкращою мисливицею свого часу.  Зараз її можна зустріти в Енклаві Сенаріону, де вона навчає тих, хто тільки-но ступив на шлях мисливця.",  -- db:3023
[718989437] = "Друїди, які завжди пильно дбають про збереження природи, перебувають під керівництвом верховного друїда Фандрала Стагхельма, що мешкає в Енклаві Сенаріону. Ви знайдете його та інших інструкторів-друїдів у північній частині Дарнассуса.",  -- db:3024
[400432070] = "У скрутні часи друїд може стати вірним другом для тих, хто його оточує. Запитайте будь-якого друїда з Енклави Сенаріону — і він підтвердить це.",  -- db:3024
[198686070] = "У Храмі Місяця мешкають жерці Елуни. Там ви зустрінете Джандрію та Ларію, які нададуть вам подальші настанови на шляху до священства.",  -- db:3025
[726798476] = "Сила Елуни спонукає тебе!  Сила Елуни спонукає тебе!  $B$BРушай негайно!  Знайди Джандрію в центральному залі Храму Місяця у південній частині Дарнассуса!",  -- db:3025
[376221491] = "Якщо ви вирішили піти шляхом розбійника, то саме Сюрну вам і слід шукати. Вона мешкає в Енклаві Сенаріону, вниз по спіральній стежці, у найзахіднішому дереві.",  -- db:3026
[162070511] = "Є ті, хто намагається йти шляхом розбійника, але лише нічні ельфи по-справжньому прийняті ніччю. Якщо ти прагнеш ступати тінистим шляхом, то знайди Сюрну в Енклаві Сенаріону.",  -- db:3026
[714924200] = "Ви знайдете Сільдінаїр на Терасі Воїнів серед охоронців: її пильний погляд обшукує ліс у пошуках ворогів, які могли б наважитися вторгнутися в наше прекрасне місто.",  -- db:3033
[304550241] = "Сільдінейр підготувала багатьох із Стражів, які охороняють наше улюблене місто. Я впевнений, що вона зможе виховати з таких, як ти, справжнього воїна. Знайди її на Терасі Воїнів біля входу до нашого міста.",  -- db:3033
[485888464] = "Тут, серед майстрів Дарнасуса, накопичено тисячоліття знань, які стануть у нагоді у вашому обраному ремеслі. А тепер скажіть мені, яке ремесло вам здається найцікавішим?",  -- db:3034
[296173568] = "Якщо ви справді маєте бажання опанувати цю професію, то я б порадив вам звернутися до Айнетіл — досвідченої алхімічки на Терасі ремісників у північній частині Дарнассуса.",  -- db:3035
[904328964] = "Алхімік?  Зовсім не проблема $c.  Айнетіл, завдяки своїй наполегливій праці та зусиллям, стала найдосвідченішою алхімісткою на Терасі Ремісників.  На твоєму місці я б негайно вирушив туди. Негайно!  А тепер біжи!",  -- db:3035
[744235922] = "Алегорн — майстерний кухар, який протягом століть вдосконалював свою кулінарну майстерність. Якщо він вирішить вас навчити, вважайте це великою честю. Якщо ви вважаєте себе гідним, ви можете знайти його на Терасі ремісників.",  -- db:3036
[772590191] = "Страви, які готує Алегорн, просто неймовірні. Він завжди зайнятий приготуванням нових делікатесів на «Терасі ремісників». Обов’язково скуштуйте його «Зелений Сенаріон», якщо у нього ще залишилося.  $B$BА тепер, якщо ви не проти, я мушу розібратися з цією хвилею зникнень оленів.",  -- db:3036
[876100659] = "Коли поруч немає лікаря, який міг би перев’язати ваші рани, знання з першої допомоги можуть врятувати вам життя. Я б звернувся до Даннелора на «Терасі ремісників», щоб він навчив мене цьому вмінню.",  -- db:3037
[679941924] = "Це займає багато часу, але приносить задоволення. Поговоріть з Астаєю на «Террасі ремісників» — можливо, ви дізнаєтеся щось корисне.",  -- db:3038
[219393206] = "За довгі роки, які Астая присвятила риболовлі, їй вдалося виловити кілька цікавих скарбів.  Чому б вам не завітати до неї на терасу «Торговців» і не попросити її показати вам деякі з них?",  -- db:3038
[570792992] = "Збирання та знання про лікарські трави — це спеціальність Фіродрена Мунколлера. Шукайте його в Садах Храму, що розташовані в південно-західній частині Дарнассуса.",  -- db:3039
[766415349] = "Ти — майбутній травник?  Тоді тобі варто завітати до Фіродрена Мунколлера в Садах Храму.  Можливо, він поділиться з тобою деякими секретами своєї справи.",  -- db:3039
[623184632] = "Майстерність, з якою Телоніс виготовляє обладунки, не має собі рівних.  Вам слід бути вдячним за те, що він не бере надто високу плату за знання, якими ділиться з іншими.  Ідіть зараз і знайдіть його на Терасі ремісників у північно-східній частині Дарнассуса.",  -- db:3040
[617717158] = "Ми садимо овочі.  Наші овочі з’їдає кролик.  Кролика з’їдає вовк.  Вовка вбиваємо ми.  Ми забираємо м’ясо та шкуру з туші вовка.  Ось таке воно, «Магічне коло життя», чи як там його називають.  $B$BТепер йдіть до Телоніса в Енклаві Сенаріону, щоб розпочати справу, а я повернуся до своїх обов’язків.",  -- db:3040
[94460327] = "Померши, тварини всього світу дарують нам і життя, і захист. Якщо ви відчуваєте, що зможете висловити належну повагу до їхньої жертви, то професія шкіряника може вам підійти. Щоб дізнатися більше, поговоріть з Еладріелем на Терасі ремісників у північній частині Дарнассуса.",  -- db:3042
[356214327] = "Померши, тварини всього світу дарують нам і життя, і захист. Якщо ви відчуваєте, що зможете висловити належну повагу до їхньої жертви, то професія шкіряника може вам підійти. Щоб дізнатися більше, поговоріть з Еладріелем на Терасі ремісників у північній частині Дарнассуса.",  -- db:3042
[61299082] = "У нашій культурі ми віримо, що нічого не можна давати на марно. Коли ми змушені вбити тварину, ми забираємо все, що можна, аби її жертва не була марною.  $B$BЯкщо ви хочете навчитися правильно знімати шкуру з убитої тварини, зверніться до Еладріеля на Терасі ремісників.",  -- db:3042
[374108163] = "Якщо ви хочете навчитися кравецькій справі, вам, безперечно, слід звернутися до Ме'Лінн. Вона мешкає на «Терасі ремісників» у північно-східній частині Дарнассуса.",  -- db:3044
[991041937] = "Дивлячись на одяг, який шиє Ме'Лінн, можна подумати, що її голку благословила сама Елуна. Якщо ваша голка не має такого благословення, вам краще завітати до неї та послухати її настанови. Ви знайдете її на «Терасі ремісників» у північно-східній частині Дарнассуса.",  -- db:3044
[527719208] = "Я помітив чотири різні види рослин, які зазнали впливу корупції: пісенну квітку, вітроквітку, батогисте коріння та нічну драконову рослину. Пісенна квітка та вітроквітка — поширені рослини у Фелвуді, тоді як батогисте коріння та нічна драконова рослина зустрічаються рідше.  Усі вони є важливою частиною екосистеми Фелвуда.",  -- db:3046
[96253431] = "Саме тут відбулася велика битва. Багато великих битв.",  -- db:3048
[944153500] = "Поговоріть із Регтаром. Він мудрий і зможе допомогти вам знайти те, що ви шукаєте.",  -- db:3049
[157899199] = "Ало?",  -- db:3055
[420207389] = "Так, без проблем, $N! Вибач... Я думав, ти вже з цим впорався.",  -- db:3056
[945452084] = "Що вам більше до вподоби — зброя чи лук?",  -- db:3061
[474314871] = "Мені треба трохи часу, $c, нага зараз на нас нападають. Я зв’яжуся з тобою, щойно атака закінчиться!",  -- db:3073
[158801445] = "Гаразд *хик*... Скажи, ти мені здаєшся знайомим *хик*. Я тобі колись розповідав про той випадок, коли ми з Віндзором відбилися від трьох, е-е... тисячі... мільйона орків?$B$BОй, заспокойся, друже, це ж класна історія!",  -- db:3074
[319783854] = "Аукціонний дім Оргримара розташований у Долині Сили. Шукайте його на східній стороні, поруч із «Boomstick Imports».",  -- db:3075
[994864770] = "У тебе голос охрип від криків, так?  Знайди аукціонний дім Оргримара в Долині Сили.",  -- db:3075
[223945225] = "Ласкаво просимо до Банку Дарнассуса. Ми пропонуємо відкриття фінансових рахунків та оренду сейфів для зберігання цінних речей. Чи маєте Ви вже рахунок у нашому банку, $g пане : пані?",  -- db:3076
[246897950] = "Неймовірно, чи не так? Усі ці артефакти та рештки.$B$BЯ навіть не знаю, що мене вражає більше: їхні розміри чи історії, пов’язані з ними. Є стільки всього, що можна вивчати й дізнаватися. І ті зв’язки, які ми можемо встановити...$B$BЧи знали ви, що ходять чутки, нібито багато рас мають те саме походження, що й нічні ельфи?",  -- db:3077
[381083419] = "Привіт, мене звати Петра.  Праворуч від мене — мій кодо, Даданга.  Ми працюємо в «Marshal Expeditions» — вже кілька років, ще з тих пір, як Даданга був малюком.$B$BЯкщо у вас є запалені смолоскипи чи будь-які відкриті джерела вогню, прошу вас, по можливості, прибрати їх подалі.  Даданга не любить дим.",  -- db:3093
[838359338] = "Заради всього святого й дорогого, будь ласка, скажи мені, що ти прийшов, аби врятувати нас із цієї занедбаної землі. Хоча я й працюю в «Marshal Expeditions», я віддав би тобі навіть свої золоті зуби, аби тільки змогти залізти в твій рюкзак і покинути це місце.",  -- db:3094
[634507002] = "О, привіт!  Я — Холані, головний науковець і біолог компанії «Marshal Expeditions».  Ми з братом, разом із нашими супутниками, мандруємо Азеротом, досліджуючи його дику й неприборкану велич.  Це захоплююче... але, е-е... Здається, цього разу ми трохи занадто захопилися!",  -- db:3095
[918427804] = "Привіт, незнайомцю, і ласкаво просимо до дикої величі кратера Ун'Горо!$B$BМене звати Вілліден Маршал.  Разом із сестрою та нашими супутниками ми утворюємо «Експедиції Маршала» — вчених і дослідників дикої та величної невідомості Азерота.$B$BМи тут потрапили в скрутне становище і шукаємо допомоги, якщо у вас є час!",  -- db:3096
[545430335] = "Поглянь на ці зразки! Що це означає? Що це означає? Мені знадобиться час, час, щоб ознайомитися з усією цією інформацією. І мені знадобиться ще більше інформації. Інформації, яку я не можу отримати... чорт! Думай, Ларісе, думай!$B$BЩо ти збираєшся робити? Що?!$B$BМає ж бути якесь рішення!",  -- db:3098
[972119869] = "Ні, наскільки я можу судити. Схоже, це здебільшого залежить від регіону. У деяких расах їх називають слимаками, в інших — слизом. Схоже, це здебільшого питання уподобань.$B$BКожного разу, коли я стикався зі слизом, мулом або слимаком, це були, по суті, одні й ті самі істоти. Відмінності, здається, залежать від їхнього середовища існування, саме тому нам потрібен чистий зразок.",  -- db:3100
[104252221] = "Чистий зразок — це такий, що не зазнав впливу випадкових факторів. Нам потрібно знайти цих істот у якомога простішому та природнішому середовищі.$B$BТобто в місці, де немає слідів цивілізації чи впливу домінуючих рас Азерота. У місці... незайманому.",  -- db:3101
[208474753] = "Це точно не буде ніде в Східних Королівствах, це безсумнівно.$B$BЦе має бути десь на Калімдорі, але все ж досить далеко від Орди та інших рас. Десь, де не було наслідків Розколу — а це означає, що й поблизу цивілізації нічних ельфів теж не буде.$B$BЯ б припустив, що це буде якесь захищене місце... наприклад, долина чи кратер. Не знаю. Це лише мої припущення. Вибач, що не зміг тобі більше допомогти.",  -- db:3102
[154769734] = "Чому хтось захотів би покинути ці сонячні береги та кришталево-блакитні води — я й гадки не маю. Тут справді як у раю. Але не кажіть цього моєму братові Запетті — він і так уже достатньо роздратований тим, що змушений цілими днями сидіти там, у Тірісфалі. Цей цепелін доставляє пасажирів до Оргримара, тож вам не доведеться слухати його скиглення. Але якщо ви найближчим часом опинитеся в Тірісфалі, прислухайтеся до мого застереження й не давайте йому приводу для скарг.",  -- db:3133
[847204012] = "Шукайте господиню готелю Палу в будівлі, що розташована трохи південніше від банку «Громовий Утвір» на нижньому пагорбі.",  -- db:3153
[262396050] = "Господиня готелю Пала допоможе вам відпочити тілом і душею.  Ви знайдете її в будівлі, що розташована трохи південніше від банку, на нижньому пагорбі.",  -- db:3153
[823579969] = "Поштова скринька розташована прямо біля банку «Тандер-Блафф» на нижньому пагорбі.",  -- db:3154
[600885652] = "Мені здається, я нещодавно помітив, що привезли нову партію пошти. Поштова скринька знаходиться прямо біля банку «Тандер-Блафф», на нижньому пагорбі.",  -- db:3154
[681779134] = "Він знаходиться в найнижчій частині Грім-Скелі. Шукайте поблизу берега. Це недалеко звідти.",  -- db:3155
[801283951] = "Аукціонний дім розташований на центральному шпилі Громового Уступу. Шукайте його біля підніжжя Вежі Вітряних Вершників. Нехай ваші предки бережуть вас.",  -- db:3155
[310321307] = "Це, можливо, вас здивує, але останнім часом справи йдуть не надто добре...",  -- db:3156
[647044871] = "Вітаю вас у Тераморі, $N.$B$B Прошу вибачення за різкість і те, що у мене немає часу на ввічливі розмови, але інтереси мого міста для мене на першому місці. Занадто багато загроз нависає над нашим способом життя та святістю Альянсу. Я мушу завжди бути пильним щодо сил, які перебувають поза нашим контролем, якщо хочу забезпечити безпеку та щастя мого народу.$B$BМожливо, пізніше у нас буде більше часу для розмови.",  -- db:3157
[686812785] = "Гендель зараз перебуває під нашою вартою, $N, завдяки вам.$B$BХоча допит просувається повільно, запевняю вас, він розповість нам усе, що знає.$B$BПоки що, будь ласка, наберіться терпіння. Я негайно зв’яжуся з вами, якщо нам знадобиться ваша допомога.$B$BДо того часу, будь ласка, насолоджуйтеся Терамором, і я запрошую вас залишатися в межах стін нашого міста стільки, скільки забажаєте, як друг Альянсу.",  -- db:3158
[972366329] = "Одразу за головними воротами міста стоїть вказівник. Він вкаже вам шлях до західної вежі цепеліна.",  -- db:3173
[830408081] = "Ми з братом присвятили себе Сильвані. Вона — наш промінь світла в найтемніші часи. Ми день у день приносимо себе в жертву, аби наш рід подолав долю, яка нас обрала.$B$BМи не залишимося слабкими. Ми візьмемо те, що нам належить. Ми повернемо вдесятеро той біль, який нам заподіяли. І зробимо це з посмішкою на обличчі.",  -- db:3193
[440838595] = "Леді Сильвана наказала провести дослідження деяких природних явищ Азерота. Вона вважає, що з його таємничого минулого можна дізнатися щось надзвичайне.$B$BЯ не знаю, звідки вона дізналася про такі речі, але я повністю їй довіряю, тож зроблю все, що в моїх силах.$B$BЗараз я досліджую слизнів, мул та подібних істот. Усі ці істоти, здається, мають схожу будову, але на них сильно впливає навколишнє середовище.$B$Мені знадобилася б ваша допомога у зборі зразків цих істот...",  -- db:3194
[601865929] = "<Волкор навіть не дивиться на тебе, коли ти підходиш до нього. Схоже, він зосереджений на тому, щоб його бинти не зісковзнули. Через мить він піднімає на тебе погляд, трохи здивований.>$B$BOй, вибач, $c. Зараз не дуже вдалий момент. Сподіваюся, ти розумієш.",  -- db:3213
[272561241] = "Ну, як на мене, $N, у нас є два варіанти, як вибратися з цієї печери.$B$BМи можемо пробратися непомітно — я скористаюся плащем, який ти мені дав, а ти залишишся сам на сам із ситуацією, або — і це може бути складнішим варіантом, з огляду на мої поранення — ми проб’ємося назовні, стоячи спиною до спини.$B$BЯ залишу рішення за тобою, оскільки ти краще за мене знаєш свої сильні сторони.",  -- db:3214
[733149567] = "Привіт, $g, хлопче : дівчино;, якщо ти шукаєш найкращі пропозиції за межами самого Айронфорджа, то ти потрапив у потрібне місце.",  -- db:3218
[449262933] = "Ти бачив тих забруднених водяних елементалів у нашому озері, $N? Це сумне видовище, але я не знаю, звідки вони беруться.$B$BТвоє ім’я згадувалося в минулих розмовах, тож, можливо, ти міг би допомогти мені з цією проблемою.$B$BПерше, що нам треба з’ясувати, — хто керує цими елементалями.",  -- db:3233
[460277184] = "Привіт.  Я — Губер Блумп.",  -- db:3234
[399349558] = "...смажені на сковороді, у фритюрі та у вок...",  -- db:3253
[786351189] = "Усі рідини та суміші бурлять і пульсують, коли ви наближаєтеся. Поруч з обладнанням лежить велика пара щипців, які, судячи з усього, підійдуть для занурення зразків мулу.$B$BЗасоби безпеки є, але вони, здається, припали пилом і їх давно ніхто не використовує.$B$BВи вважаєте, що торкатися чого-небудь нерозумно.",  -- db:3273
[675048246] = "Привіт, $N. Ласкаво просимо до «Refuge Pointe».",  -- db:3293
[207721042] = "Не звертайте уваги на Скуерто, $N. Він не хоче бути грубим, просто він страшенно зайнятий. Поки ми чекаємо, поки він закінчить розвідку, чому б нам не зайнятися чимось більш корисним?",  -- db:3294
[410118140] = "Привіт, $N!$B$BI! Мені треба попрацювати над своїми пристроями, але зрештою... мені знадобиться хтось, хто дістане для мене драконячі яйця!",  -- db:3295
[608300874] = "«Палаючі степи» — небезпечне місце, але вчені, такі як я, готові піти майже на все, аби розширити свої знання.",  -- db:3296
[355015567] = "Нехай твої навички у плавленні темного заліза стануть тобі в нагоді, $N.  Але не дозволяй своїм знанням спотворити тебе... так, як вони спотворили нас.",  -- db:3297
[300413129] = "Кар Аман, $N. Ти, здається, сильний $c — тобі варто бути обережним у цьому питанні. Втручання у справи, про які ти нічого не знаєш, або прояв неповаги до старших — це пряма підстава для покарання.$B$BМожливо, ти не поважаєш мене чи моїх супутників, але ти навчишся поважати нашу силу, якщо виявишся достатньо нерозумним.$B$BНу що ж, досить приємностей, чи можу я чимось тобі допомогти?",  -- db:3298
[790315311] = "Ага, колега-чаклун, який певною мірою довів $ghis:свою; цінність.$B$BI радий познайомитися з вами. Мене звати Менара Войдрендер... і це не без підстав.$B$BВи здаєтеся настільки могутнім і ерудованим, що інші інструменти... потужніші засоби... були б доречними і не стали б предметом безглуздого розголосу. Якщо це правда, то розкажіть мені більше. Якщо ні, то, ну що ж, ви знаєте дорогу  назад до причалів і далі — у відкрите море.",  -- db:3299
[398642184] = "У минулі десятиліття — часів вже давніх воєн і конфліктів — наш вид опинився на межі вимирання. Ми багато чого пережили, $r.$B$BНапад Палаючого Легіону. Душу Демона. Розкол Аспектів. Сходження на трон Смертокрила. Поневолення нашої королеви, Алексстрази, Драконопащею.$B$BПройшовши через усе це, ми стали непохитною волею драконів — незламною силою, яка боролася, щоб відстояти наше згасаюче існування в цьому світі.",  -- db:3301
[308113733] = "Справді. Я стою перед тобою у вигляді, який ти можеш осягнути, смертний. Звісно ж, ти б не зміг витримати присутності дракона на ім’я Ваеластраз.$B$B<Ваелан сміється.>$B$BМені продовжувати?",  -- db:3302
[242070698] = "Мабуть, мені слід розповісти тобі, чому я тут.$B$BЧи знаєш ти про Аспекта Смертокрила? Або про його нащадків — Нефаріана та Оніксію?",  -- db:3303
[68321591] = "Десвінг, або Нелтаріон, як його колись називали, був Аспектом, що уособлював силу світу — титан-творець на ім’я Хаз’гороф, відомий як Творець світу.$B$BЗа допомогою зради та обману цей мерзенний створіння переконав чотирьох інших Аспектів наділити своїм силами предмет, відомий як «Душа Демона», — що значно ослабило їх і спричинило розкол серед колись величних Аспектів. $b",  -- db:3304
[343378729] = "Дійсно. Зрештою цей предмет було знищено, а Десвінг ледь не загинув від об’єднаної та відновленої сили чотирьох Аспектів, що залишилися. Де зараз перебуває Десвінг, невідомо. Однак ми знаємо, що один із його нащадків, Нефаріан, править цією цитаделлю і прагне продовжити справу, яку розпочав його батько.",  -- db:3305
[115338441] = "Перед своїм вигнанням Десвінг намагався створити нечисте потомство — напівкровок, які не тільки були б імунітетними до вроджених природних сил та здібностей своїх Аспектів, а й перебували б під повним контролем Десвінга.$B$BСхоже, що там, де його батько зазнав поразки, Нефаріан, можливо, досяг успіху — принаймні частково.$B$BСаме Ісера, Аспект Мрій, побачила ці потвори й змусила нас вжити заходів. Якщо ці «хроматичні» дракони існують, їх треба знищити.",  -- db:3306
[129584921] = "Це не в наших звичаях, та й неможливо. Нефаріан охороняється древніми захисними заклинаннями, такими ж давніми, як і самі Аспекти. Саме це заважає мені проникнути у внутрішнє святилище цієї цитаделі. Темна магія не дозволяє нікому з інших представників польоту увійти без відповідного дозволу... хіба що.",  -- db:3307
[999428905] = "Людина, яка не належить до роду драконів, може здобути Прикрашену Печатку Вознесіння та пройти крізь захисний бар’єр. Хоча володіння таким предметом, безсумнівно, знищило б мене, можливо, ти міг би скористатися ним і послабити бар’єр.",  -- db:3308
[788265222] = "Ви повинні знайти серед негідників у нижній частині цієї цитаделі того, хто отримав «Неприкрашену печатку вознесіння». Для нижчих істот отримати цей предмет — велика честь, адже це перший крок до отримання доступу до верхньої частини цитаделі та вступу до лав елітних гвардійців Нефаріана — Легіону Чорної Руки. Знайдіть такий предмет і поверніть його мені, щоб я міг дослідити його властивості. Я зрозумію, як діяти далі, щойно завершу огляд печатки.",  -- db:3309
[872882974] = "Майте на увазі, смертний: надзвичайно рідко трапляється, щоб один із менших кланів у цій цитаделі мав у своєму розпорядженні такий предмет. Ваші пошуки можуть тривати десятиліттями. Раджу вам безжально знищити цих тварюк.",  -- db:3310
[991751460] = "Не піднось це ближче, смертний. Я відчуваю зло, що пронизує печатку, навіть звідси, де стою.$B$BДай мені хвилинку, щоб оглянути цей предмет — тримай його міцно.",  -- db:3311
[718941960] = "Це не гра, чувак. Якщо хочеш скористатися сокирою, то мусиш промовити цю фразу. Повтори за мною??? Скажи «привіт» моєму маленькому приятелю.",  -- db:3321
[556985944] = "$N, я прибув сюди, щоб з’ясувати, наскільки широко поширилися наслідки дії «Фель-моху» по всьому Темному березі. Зараження Телдрасіля та навколишніх земель справді турбує друїдів «Круга Сенаріанців» і всіх нічних ельфів.$B$BМоя мета — з’ясувати, чому це сталося, і покласти цьому край.",  -- db:3334
[556739956] = "Оскільки лезо ніколи не буває занадто гострим, а обладунки — занадто міцними, талановитий чарівник завжди буде незамінним.  Саме таким чарівником є Таладан, який може навчити вас правильно накладати зачарування, щоб покращити вашу зброю та обладунки.  Знайдіть його на Терасі ремісників.",  -- db:3337
[432616763] = "Мені приємно, але, чесно кажучи, мені це не цікаво... Що?  Ти хочеш дізнатися, де можна навчитися зачаровувати?  Ой, як ніяково!  Ну, тобі слід...  Я впевнена, ти міг би... піти до, е-е...  Таладана!  Так, піди до Таладана на Терасу ремісників!",  -- db:3337
[721443130] = "Ласкаво просимо до мого магазину, $c. Чим брати Гудстіч можуть вам допомогти?",  -- db:3357
[558390647] = "Ах, один із моїх улюблених клієнтів. Ви, здається, чаклун чималої сили, $N. Радий познайомитися з вами. Якщо я можу чимось вам допомогти, будь ласка, просто скажіть.$B$BМій брат і я вважаємо, що саме такі, як ви, приведуть нас у наступну велику еру. Такий, що володіє такою силою… таким контролем… це лише питання часу, коли сама Легіон підкориться вашій волі.$B$BЯ навіть трохи заздрю.",  -- db:3358
[668461537] = "Ах, $r... Я володію великими знаннями про світ і про те, як створювати талісмани великої сили.",  -- db:3375
[227120194] = "Мауарі знає, чому ти її шукаєш...$B$BПринеси мені той Е'ко, який ти знайдеш у світі, і я зможу перетворити його для тебе.",  -- db:3377
[506849637] = "Так-так, я знаю, що Даданга не любить дим. Але, судячи з запаху, схоже, Даданга ще й не любить купатися.",  -- db:3380
[446493135] = "Скарбниця Мауарі приховує великі таємниці... Осколки, з яких його виготовлено, мають відбиваючі властивості, і ви можете використовувати його блискучу поверхню, щоб висмоктувати силу з інших предметів, а потім відбивати її на себе.$B$BЗберігаючи цей талісман у своєму інвентарі, ви зможете збирати «е'ко» — духовну силу звірів, з якими ви боретеся. Як тільки ви знайдете «е'ко», віднесіть його до Мауарі.",  -- db:3382
[76768417] = "«Е'ко» — це сила, якою володіє кожна істота. Амулет, який я зробив для тебе, дозволяє тобі втілити її у фізичній формі.$B$BЯ знаю заклинання, яке може перетворити знайдене тобою «е'ко» на «джуджу».$B$BТоді ти зможеш взяти Скарб Мауарі й використати його, щоб відбити силу «джуджу» на себе.$B$BНу ж бо, спробуй. Принеси «е'ко» до Мау'арі, і ми трохи розважимося.",  -- db:3383
[432855745] = "Доброго дня, $g хлопче : дівчино;. Чим можу допомогти?",  -- db:3395
[644300141] = "Ти тут на навчання, так? Я сам щойно почав навчатися, але з радістю навчу тебе всьому, що знаю.",  -- db:3396
[939114665] = "Ти швидко вчишся, хлопче : дівчино;, набагато швидше, ніж я встигаю за тобою. Якщо хочеш продовжити навчання, раджу звернутися до мого вчителя. Його звати Ротгат, Ротгат Кам’янобородий, і ти знайдеш його в Айронфорзі, у «Великій кузні».",  -- db:3397
[595773336] = "Е? У мене немає часу базікати, тато хоче, щоб я доробив для нього це замовлення.",  -- db:3398
[483679210] = "У тебе є певний талант. Гадаю, цього вистачить, щоб навчитися дечому. Давай подивимося, чому я можу тебе навчити, гаразд?",  -- db:3399
[277127568] = "Ви знаєте більше за мене, це безперечно. Але ось що: підіть поговоріть з моїм батьком. Він захоче, щоб ви довели свою спроможність, але він — справді чудовий вчитель. Його звати Ротгат, і ви знайдете його біля ковадл — він обробляє сталь для старого Бенгуса.",  -- db:3400
[972528152] = "Що ж, друже мій, ти вправніший за мене. Чому б тобі не знайти мого старого друга Ротгата Кам’янобородого? Він залишився в Айронфорджі, коли я пішов, щоб приєднатися до армії Джейни. Я впевнений, що він зможе тебе чомусь навчити або принаймні знає когось, хто зможе це зробити. Якщо він ще там, то, напевно, його можна знайти у «Великій кузні».",  -- db:3401
[908970064] = "Істоти у Вінтерспрингу — гарне місце для початку.$B$BПроте, можливо, є й інші місця, де можна пошукати...",  -- db:3402
[161069941] = "Звичайно, я можу допомогти тобі з тренуваннями. Сам я лише підмайстер, але впевнений, що можу тобі дещо показати.",  -- db:3403
[954167807] = "Я не кажу це просто так, але ти — набагато кращий коваль, ніж я. Якщо ти хочеш дізнатися більше, ніж можуть дати мої скромні настанови, то раджу тобі звернутися до гнома на ім’я Терум Глибококузний у Штормовії. Ти знайдеш його в Гномському кварталі.",  -- db:3404
[963268599] = "Вибачте, я зараз трохи зайнятий виготовленням підків для Вернера Осгуда в Лейкширі.",  -- db:3405
[693680823] = "Хіба я виглядаю так, ніби у мене є час на балачки?",  -- db:3406
[790085447] = "Ти непогано справляєшся, але дозволь мені показати тобі кілька хитрощів, які можуть тобі стати в нагоді.",  -- db:3407
[508063209] = "Він набагато кращий коваль, ніж я, це точно. Хоча я це заперечуватиму, якщо ти комусь скажеш, що я так сказав. Тобі варто поговорити з Терумом Глибококувальником. Якщо хтось і може навчити тебе більше, то це саме він.",  -- db:3408
[811436916] = "Як тільки я почую хоч один коментар про водоплавних птахів, тобі доведеться їсти через зонд.",  -- db:3409
[141398859] = "Саме по собі те, що ти б’єш молотком по ковадлу, ще не робить тебе ковалем. Віддай це мені, і я навчу тебе дечому, перш ніж ти поставиш нас усіх у незручне становище.",  -- db:3410
[883121253] = "Непогано. Підійди до Снарла, він щойно переїхав до Оргримара, щоб навчатися у Сару. Шукай його в районі Воїнів, неподалік від кузні Сару. А ще він тебе випробує, тож краще будь готовий настільки, наскільки вважаєш себе готовим.",  -- db:3411
[711219046] = "Снарл називає мене простаком, бо я занадто повільний. Я просто хочу виконати роботу як слід, а на це потрібен час.",  -- db:3412
[813264710] = "Я можу показати тобі те, що ти хочеш знати, але ти повинен набратися терпіння. Не поспішай, обробляючи сталь, і відчуй, як вона змінює форму під ударами твого молотка. Коли ти станеш єдиним цілим зі сталлю, тоді ти й зрозумієш.",  -- db:3413
[239073001] = "Ти швидко вчишся, і це не погано. Просто обов’язково виконуй роботу як слід, скільки б часу на це не знадобилося. А тепер, боюся, мені доведеться відправити тебе до Снарла, щоб ти дізнався більше. Вчися у нього всьому, чого він може навчити, але не звертай уваги на його гнівні слова. Він так поводиться, коли дочки Сару сміються з нього.",  -- db:3414
[710742159] = "Я слухаю й слухаю, але не чую тих духів, про яких говорить Карн.",  -- db:3415
[69635074] = "Карн каже, що нам треба прислухатися до духів кузні та сталі, що вони нас направлять. Я ж чую лише дзвін у вухах. Ось, візьми молоток, і давай спробуємо разом прислухатися до духів.",  -- db:3416
[633164559] = "Мабуть, духи люблять тебе більше, ніж мене. Я досі не чув їхнього поклику, а ти, здається, добре засвоїв їхні настанови. Підійди до Карна — він буде радий побачити того, хто чує їх так само, як і він.",  -- db:3417
[878515706] = "Твоє втручання забирає у мене дорогоцінний час, тож сподіваюся, це дійсно щось вартісне.",  -- db:3418
[762935854] = "Ага, ще один, хто розпалюватиме вогонь і куватиме зброю для війни. Звісно, я навчу тебе, як це робити.",  -- db:3419
[705010317] = "Ти добре навчився, дитино моя. Іди до Підмістя, знайди коваля на ім’я Джеймс Ван Брант. Він зможе навчити тебе багато чого такого, чого я не можу. Як я розумію, він проводить час поблизу тренувального залу Воїнів, куючи для них зброю та обладунки.",  -- db:3420
[732252631] = "Я сподіваюся, що одного дня зможу викувати зброю та обладунки з кісток своїх ворогів.",  -- db:3421
[983259884] = "Ти ж не намагаєшся розбити ковадло своїм молотком — ти намагаєшся створити зброю, щоб вбити своїх ворогів. Давай я тобі покажу, що ти робиш не так.",  -- db:3422
[72658421] = "Ти багато чого навчився — більше, ніж я можу тебе навчити. Звернися до Джеймса Ван Бранта, він навчить тебе того, чого я не можу.",  -- db:3423
[255293916] = "«Е'ко» — це розсіяна форма надприродної сили, а «Джуджу» — її сконцентрована суть. За допомогою потужного заклинання я можу перетворити «Е'ко» на «Джуджу».  Як тільки воно перетвориться на «Джуджу», ти зможеш скористатися «Скарбницею Мау'арі», щоб відбити ці сили на себе.",  -- db:3424
[982227721] = "Я дуже здивований, що людина з таким недбалим характером дійшла аж до цього...$B$БТак, можливо, у тебе є ще один талісман, але Мауарі дуже незадоволений твоїми вчинками!$B$БІди вже.",  -- db:3425
[458499045] = "Ти вже трохи вмієш поводитися з молотком і ковадлом, але цього недостатньо. Підійди до Дейна Ліндгрена — він підготує тебе до того, щоб ти міг засвоїти те, чого я тебе навчу.",  -- db:3453
[295735812] = "Я казав, що в тобі тече кров коваля, і я мав рацію. Звернися до Айронфорджа, до Великої Кузні, і знайди там гном-коваля на ім’я Бенгус Діпфордж. Це мій вчитель і один із найвидатніших ковалів, яких я коли-небудь знав.",  -- db:3454
[960085681] = "Життя коваля нелегке, але воно загартовує кістки і розпалює вогонь у серці. Мій батько був ковалем, а перед ним — мій дід у кузнях під Грім-Батолом. А тепер мій син йде нашими слідами — я пишаюся цим хлопцем.",  -- db:3456
[948939672] = "Вибач, $g, хлопче : дівчино;, ти ще не готовий до того, щоб навчатися у мене. Звернися до мого сина Грума — він буде дуже радий, якщо у нього з’явиться новий учень.",  -- db:3457
[791560179] = "Твої вміння не позбавлені цінності, але перш ніж взяти тебе до себе, я мушу піддати тебе ще одному випробуванню.",  -- db:3458
[394815307] = "Так, я з радістю навчу тебе дечому з ковальської справи. Візьми фартух і молоток — подивимося, що у нас вийде, гаразд?",  -- db:3459
[485868245] = "Ти швидко вчишся, та й ще й чудовий коваль. Я б із задоволенням затвердив твою роботу в будь-який день тижня. Але мені здається, тобі ще є чому повчитися. Сходи поговори з Бенгусом Глибококувальним — він суворий наставник, але й один із найкращих.",  -- db:3460
[715786918] = "Не вискакуй так з тіні. Наступного разу попередь дівчину заздалегідь.",  -- db:3461
[233027516] = "Відтоді, як тіні охопили Сутінковий ліс, я не можу заснути. Мене не дають заснути примарні звуки криків, що доносяться з вітерцем. Вони звучать майже як крики ягнят, і вони не вщухають.",  -- db:3461
[68698831] = "Хм, твоя робота непогана, але вона далеко не відповідає тим стандартам якості, яких я очікую від студента. Підійди до Сміта Аргуса в Голдширі — я впевнений, він зможе навчити тебе основам. А коли закінчиш, повертайся до мене, і я проведу невеликий тест, щоб переконатися, що ти готовий.",  -- db:3462
[167967265] = "Так, я чув по чутках, що рано чи пізно, можливо, зустрінуся з тобою. Але я не беру до себе кого завгодно — спочатку мушу переконатися, що ти маєш те, що потрібно. Готовий пройти мій невеличкий тест і дізнатися?",  -- db:3463
[669813756] = "Ти добре справляєшся, але ще трохи не допрацьовано. Не переймайся, це прийде з практикою. До речі, може, подивимося, над чим ти працював?",  -- db:3464
[969283113] = "Тепер це я здаюся трохи незграбним, і, чесно кажучи, не думаю, що мені ще є чому тебе навчити. Але знаєш, хто може? Бенгус Діпфордж в Айронфорджі — ось це карлик, який знається на сталі. Зайди до нього у «Велику кузню» в Айронфорзі й поцікався, чи готовий він взяти під своє крило нового учня.",  -- db:3465
[96197751] = "Якщо я доведу Сару свою спроможність, у нього не залишиться іншого вибору, як дозволити мені поборотися за руку однієї з його дочок. Тоді й побачимо, хто з нас буде посміхатися з презирством.",  -- db:3466
[135640628] = "Тримайся подалі від Сумі та Тумі. Вони... вже зайняті.",  -- db:3466
[584104756] = "Ще раз прийди до мене з такою жалюгідною роботою — і я відправлю тебе додому в маленькій залізній скриньці, яку я загартував у козячій сечі. А тепер йди до того ідіота Уг’тока — він краще підійде для твоїх потреб.",  -- db:3467
[419153622] = "То ти вважаєш, що гідний навчатися у мене? У великого Снарла? Ти — не більше ніж нікчемний черв’як під моїм черевиком. Втім, якщо я візьму під своє крило якогось підлеглого, це, можливо, зробить мене привабливішим для Сумі та Тумі. Подивимося, якими мізерними навичками ти володієш.",  -- db:3468
[453327087] = "Ти вже нічого не можеш мене навчити, тож забирайся геть. І навіть не думай наближатися до Сару — такого негідника, як ти, він використає твою кров, щоб загартувати свою сталь.",  -- db:3470
[868447079] = "Духи привели тебе до мене, і тому я відчуваю, що вони мене благословили.",  -- db:3471
[259391372] = "Тобі слід трохи уважніше прислухатися до порад духів, юнаку. Твій шлях лежить до іншого — Трага Стоунхуфа в Громовому Утворі. Можливо, ви зможете чогось навчитися одне в одного.",  -- db:3472
[640098079] = "Скажи мені, чи відчуваєш ти себе готовим прийняти виклик, який я тобі поставив? Духи кажуть мені, що ти впораєшся, але чи віриш ти в них чи в себе?",  -- db:3473
[993562075] = "Наші життєві шляхи перетинаються лише на мить, і настав час нам розійтися. Я вважаю себе щасливцем, що мав змогу провести цей час, навчаючи тебе, і тепер відправляю тебе, щоб ти приєднався до свого наступного наставника. Знайди Сару Стілфюрі з Оргримара — він навчить тебе всього, що тобі потрібно знати.",  -- db:3475
[679190336] = "У тебе величезний потенціал, але спершу ти повинен досягти розуміння, прийняти духів і прислухатися до їхнього поклику. Лише тоді ти будеш готовий до шляху, яким тобі належить йти. Іди поговори з Трагом — гадаю, ви, можливо, зможете багато чого навчитися одне в одного.",  -- db:3476
[361479521] = "Ти багато чого навчився, але я відчуваю, що духи ще можуть навчити тебе чомусь новому. Я можу поставити тебе на шлях, але не можу керувати твоїми кроками. Іди й знайди Сару Стілфюрі в Оргримарі — саме там розпочнеться наступний етап твоєї подорожі.",  -- db:3478
[574035719] = "Ти марнуєш мій час, йди поговори з моїм учнем Василем.",  -- db:3479
[318287739] = "Ти виготовляєш справді чудове спорядження, справді чудове. Відправляйся до Оргримара — столиці орків — і знайди коваля на ім’я Сару Стілф’юрі. Треба віддати оркам належне: вони виготовляють прекрасні знаряддя смерті.",  -- db:3481
[988428993] = "Вибач, $g, хлопче : дівчино; але в тебе просто немає необхідних знань, щоб засвоїти те, чого я можу навчити. Та не переймайся, піди поговори з моїм учнем Ротгатом, він тобі допоможе.",  -- db:3482
[611766987] = "Я не можу нахвалитися твоєю роботою — ти твориш справді дивовижні речі за допомогою молотка та ковадла. Тільки нікому не кажи, що я порадив тобі знайти гобліна, який би тебе навчив, але саме це я й збираюся зробити. Його звати Брік Кінкрафт, і, з того, що я чув, він тримає крамницю в Буті-Бей.",  -- db:3484
[757195233] = "Це не та гра, з якою можна бавитися, малий! Іди, поговори зі Снарлом назовні. Він, може, і змія в моєму лігві, але з ковадлом він знає, що робити.",  -- db:3485
[329216695] = "Бачу, ти знаєш про таємницю сталі більше, ніж я. Це добре, адже її й слід розкрити. Тепер тобі треба вирушити до джунглів на південь від людських земель, до міста гоблінів Буті-Бей. Там ти знайдеш гобліна на ім’я Брік Кінкрафт. Я не люблю гоблінів, але його знання про таємницю сталі не мають собі рівних серед усіх, кого я знаю.",  -- db:3487
[257010907] = "Так? Звісно, я коваль. Що, ти думаєш, тільки гноми варті своєї ваги в ковадлах? Гаразд, як хочеш. Іди, знайди собі гнома, щоб тобі допоміг!",  -- db:3488
[265082479] = "Ти що, жартуєш? Ти, мабуть, жартуєш! Або це, або ти вважаєш мене клоуном, який тут для того, щоб розважати тебе. Ти так думаєш? Що я клоун? Га? Так і є! Ти вважаєш мене клоуном, чи не так!",  -- db:3489
[323679906] = "Ти ведеш себе так, ніби це найкраща нісенітниця, яку я коли-небудь бачив. Звісно, вона нормальна, але я щодня бачу такі «нормальні» речі. Ось що я тобі скажу: знайди спосіб мене вразити, і я навчу тебе речам, від яких гноми посміхаються уві сні.",  -- db:3490
[649026486] = "Хоч як мені не хочеться це визнавати, але ведмідь все-таки взяв над мною гору. Ой-ой, це ж справді величезний старий ведмідь!$b$bПроте, якщо тобі вдасться здолати цього ведмедя, це буде подвиг, яким можна пишатися! Він додав чимало клопоту навіть деяким із наших найкращих мисливців.$b$b<Він поплескує тебе по спині.>$b$bПереможи ведмедя, і ми приймемо тебе як повноправного члена Ложі «Далекобіжців».",  -- db:3493
[29836363] = "Тут, у лоджі «Фарстрайдер», ми понад усе цінуємо мисливські навички. Хочеш заслужити моє схвалення? Тоді тобі доведеться за це поборотися.$B$BТи готовий прийняти виклик, $Glad:lass;!",  -- db:3494
[90588939] = "Ти став справжнім мисливцем, $N! Ти не тільки довів свою майстерність, а й перевершив Даріла, за що в моїх очах отримуєш додаткові бали!$B$BЗавжди радий бачити тебе тут.",  -- db:3495
[828954354] = "З радістю... тільки дай мені ще хвилинку насолодитися цією миттю.",  -- db:3496
[461644425] = "Вони знаходяться в «Чарівному кварталі». Шукайте їх у моторошній будівлі у формі черепа.",  -- db:3513
[263457810] = "Ми знаємо, де вони! Будівля у формі черепа в «Чарівному кварталі» на зовнішньому кільці міста.",  -- db:3513
[9255162] = "Банк у центральній вежі «Trade Quarter». Ви його точно не пропустите.",  -- db:3514
[425606764] = "У нас одне око, але ми бачимо краще за вас!  Банк у центрі Андерсіті!",  -- db:3514
[721699039] = "Майкл Гарретт на верхньому ярусі в «Трейд-Квотер».",  -- db:3515
[844687748] = "Людина-кажан на верхньому рівні «Трейд-Квотер».",  -- db:3515
[400420903] = "Так, ти шукаєш Крістофера Дракула в Торговому кварталі. Він на східній платформі.",  -- db:3516
[974307728] = "Приєднаємося до гільдії?  Ні?  Гаразд, знайди майстра гільдії на східній платформі в Торговому кварталі.",  -- db:3516
[653930458] = "Варто поговорити з трактирником Норманом, що на верхньому кільці Торгового кварталу.",  -- db:3517
[305218965] = "Грішникам не буде спокою, але, мабуть, з вами все гаразд. Ви знайдете трактирника Нормана на верхньому кільці Торгового кварталу.",  -- db:3517
[529500314] = "Поштова скринька в центрі міста, у Торговому кварталі, на верхньому кільці... поруч із корчмою.",  -- db:3518
[140930017] = "Нам треба перевірити, чи наш «Хакер мозку»… «Хакер мозку»… «Хакер мозку» був проданий на аукціоні. Поштова скринька знаходиться поруч із корчмою на верхньому кільці Торгового кварталу.",  -- db:3518
[367743481] = "У нас є аукціонний дім у Центральному кільці.",  -- db:3519
[728185621] = "Центральне коло.  Вперед!",  -- db:3519
[686424045] = "Маленький гоблін на даху будівлі на північ від Руїн Лордаерона.  Вийдіть з Андерсіті — і ви опинитеся там.",  -- db:3520
[903062233] = "Ми бачимо повітряну кулю на північ від руїн, високо в небі. Вона перенесе вас у далекі краї.",  -- db:3520
[938225534] = "Тренер-священик?  Зайди у зовнішнє коло Воєнного кварталу і пошукай їх там.",  -- db:3521
[38961356] = "Ага.  Нечестиві у «Військовому кварталі» стоять навколо головної будівлі на зовнішньому кільці міста.",  -- db:3521
[205919952] = "Знайди ту голову — вона точно налякає Даріла. Не те щоб він цього не заслуговував — цей клятий зарозумілий виродок. Але ха! Не можу дочекатися, щоб побачити вираз його обличчя, коли ти йому її покажеш.",  -- db:3522
[262668463] = "Ласкаво просимо до готелю «Farstrider Lodge», $N!",  -- db:3523
[364591189] = "Розбійники у будівлі на зовнішньому кільці «Кварталу розбійників».",  -- db:3524
[907715104] = "Вони вчать мене майстерно крастися. Їх можна знайти в «Кварталі розбійників» на зовнішньому кільці Андерсіті.",  -- db:3524
[109101185] = "Тобі тут завжди раді, $N. Дякую, що розсмішив мене — і не переймайся через Даріла, він це заслужив!",  -- db:3525
[232863226] = "Тренери-чаклуни у «Магічному кварталі» — у будівлі на зовнішньому кільці, поруч із магами.",  -- db:3526
[523007684] = "Ми хочемо завести фелхаунда як домашнього улюбленця. Ми будемо його годувати, дбати про нього та навчити грати в «апорт». Ви знайдете чаклунів у Магічному кварталі на зовнішньому кільці міста.",  -- db:3526
[279285422] = "У будівлі «Військового кварталу» на зовнішньому кільці міста.",  -- db:3527
[457965011] = "Тренери-воїни добре б’ються. Їх можна знайти у «Військовому кварталі» на зовнішньому кільці Андерсіті.",  -- db:3527
[996594574] = "Загляньте в «Апотекаріум». Саме там приймають доктор Герберт Хелсі та доктор Марш.",  -- db:3528
[684335458] = "Доктор Герберт Хелсі в «Апотекаріумі», де ми народилися. Він міг би зашити вас краще, ніж ми.",  -- db:3528
[682610969] = "Джеймс Ван Брант у районі «Вор-Квотер» на внутрішньому кільці.",  -- db:3529
[428623634] = "Внутрішнє коло «Військового кварталу», де працював Джеймс Ван Брант. Він виготовив для нас гарний ланцюг.",  -- db:3529
[867986635] = "Та сама Юніс Берч із Торгового кварталу.",  -- db:3530
[113951124] = "Юніс Берч продає залишки запчастин. Її можна знайти в Торговому кварталі.",  -- db:3530
[267746713] = "Ви прямуєте до внутрішнього кільця «Апотекаріуму». Там перебуває Лавінія Кроу.",  -- db:3531
[553183589] = "Леді навчить вас виготовляти магічні предмети. Вона перебуває у внутрішньому колі «Апотекаріуму».",  -- db:3531
[831605149] = "Грем Ван Тален у «Кварталі розбійників» на зовнішньому кільці Підміста.",  -- db:3532
[567431766] = "Хех, бомби — ми любимо бомби.  Грем Ван Тален покаже вам, як їх робити.  Він знаходиться у зовнішньому кільці «Кварталу розбійників».",  -- db:3532
[345135924] = "Ми її добре знаємо. Це Мері Едрас із найближчого оточення «Кварталу розбійників».",  -- db:3533
[149348965] = "Леді зашиває рани та накладає пов'язки, коли нас поранено. Її можна знайти у внутрішньому кільці «Кварталу розбійників».",  -- db:3533
[36111352] = "Ви не пропустите Арманда Кромвеля в «Магічному кварталі». Він стоїть на причалі.",  -- db:3534
[423394747] = "Арман Кромвель завжди стоїть біля причалу в «Чарівному кварталі».  Риба, занурена в зелену слизь, смакує особливо добре.  Спробуй сам.",  -- db:3534
[764807262] = "Шукайте Марту Алліестар. Вона перебуває у внутрішньому кільці «Апотекаріуму».",  -- db:3535
[798406428] = "Вам потрібно зайти до «Аптекаріуму» на внутрішньому кільці. Саме там Марта Алліестар навчить вас збирати квіти.",  -- db:3535
[15648557] = "Він знаходиться у внутрішньому кільці «Кварталу розбійників».",  -- db:3536
[891597336] = "Артур Мур, що мешкає у внутрішньому кільці «Кварталу розбійників», — один із тих, хто викладає шкіряне ремесло.",  -- db:3536
[246994054] = "Зайдіть у внутрішнє коло «Військового кварталу». Там знаходиться Бром Кілліан.",  -- db:3537
[324568741] = "Бром Кілліан навчить тебе, як знайти для мене «шині». Він перебуває на внутрішньому кільці Воєнного кварталу.",  -- db:3537
[350010633] = "Кілліан Хейджі викладає мистецтво зняття шкури в «Кварталі розбійників» на внутрішньому кільці.",  -- db:3538
[117966688] = "У нас є гак для зняття шкури. Ми отримали його від Кілліана Хейджі, який навчив нас знімати шкуру з вбитих тварин. У тебе гарна шкура. Ти знайдеш його на внутрішньому кільці «Кварталу розбійників».",  -- db:3538
[940990597] = "Шукайте Йозефа Грегоріана. Він у «Чарівному кварталі», на стороні внутрішнього кільця зеленого каналу.",  -- db:3539
[630725491] = "Хм, гарна ідея. Може, заїдемо туди, щоб замінити кілька швів? Він добре шиє. Йозефа Грегоріана можна знайти у внутрішньому колі Магічного кварталу.",  -- db:3539
[626934589] = "О, гаразд!  Ось, тримай, $N.  Це найменше, що я можу зробити в подяку за всю допомогу, яку ти мені надав.",  -- db:3540
[151429451] = "Послухайте розповіді старця. $N. У мене їх чимало...",  -- db:3545
[965581374] = "Ласкаво просимо до притулку, $N. Дехто приходить сюди з певною метою, інші опинилися тут випадково... Але, здається, у кожного тут є своя унікальна історія.",  -- db:3546
[385207349] = "Гррр...",  -- db:3550
[28304185] = "Я прибув до «Перехрестя» з півдня в пошуках допомоги, $c, але знайшов тут лише боягузів, які відвертаються від мене — навіть могутній Торк так мене ображає. Він — хороший вождь, але те, що він відкинув моє благання, викликає в мене ще більший гнів.$B$BВін стверджує, що моя лють змушує мене діяти поспішно — що вона затьмарює мій розум — але я не заспокоюся, доки не помщуся!",  -- db:3553
[13279739] = "Я дякую тобі, $N. Твоя відданість моєму благанню приносить спокій душі моєї загиблої дружини, і за це я ніколи не зможу віддячити тобі достатньо.$B$BНе можу сказати, що моя ненависть до квілбоарів коли-небудь зникне, але наразі вона вгамована.$B$BТепер я мушу почати відбудовувати своє життя.",  -- db:3554
[716634446] = "Це тіло жінки-орка-воїна.$B$BОчевидно, що вона загинула в бою, ймовірно, проти квілбоарів, які мешкають у цій місцевості.",  -- db:3557
[76617638] = "Ви перевертаєте тіло і бачите на померлій орчині сліди від мечів та магічних заклинань — її обладунки майже повністю зруйновані, а волосся злиплося на обличчі.$B$BСудячи з опису, який дав Манкрік, у вас немає жодних сумнівів, що це була його дружина.$B$BЦя новина його засмутить, але ви впевнені, що він повинен знати правду.",  -- db:3558
[685838652] = "Ласкаво просимо до «Перехрестя», $c. Мене звати Торк — я керую обороною цього місця від імені Вождя.$B$BБудь ласка, почувайтеся як вдома. Якщо ви не будете лізти не у свої справи, ніхто не матиме нічого проти того, щоб ви зайняли тут трохи місця.$B$BТут існує чимало загроз нашій безпеці. Якщо ви вже ознайомилися з місцевістю, поговоріть з іншими мешканцями — можливо, вони мають для вас завдання.",  -- db:3559
[445324759] = "<Горуз зубами плюється.>$B$BЯ — воїн Орди, $N. Мене охоплює лють від усвідомлення, що наші вороги сидять у фортеці, менш ніж за день їзди від Каргата, і плетуть проти нас змови.$B$BЯк же я прагну звільнитися від пут обов’язку й знищити їх усіх в ім’я Вождя.$B$BНа жаль, у кожного з нас є роль, яку ми мусимо виконувати.$B",  -- db:3560
[498210649] = "Справді, я заздрю вам: битися в ім’я Орди, на передовій конфлікту. Моя робота — командувати.$B$BЗвісно, у молодості я втілював мрії, завдяки яким моя старість стає терпимою. Тепер я насолоджуюся славою перемоги та гірким присмаком поразки — і все це завдяки солдатам, якими я командую.$b",  -- db:3561
[969765841] = "Я мрію, $N... о так, я мрію. У своїх снах я вмираю тисячу разів тисячею різних способів. Дехто назвав би такі сни, як мої, кошмарами. Але не я! У снах я гину в самому розпалі битви. За кожну мою смерть десять тисяч ворогів Орди гинуть переді мною. Це славно!",  -- db:3562
[770848679] = "Так, я це побачив, лише поглянувши на тебе, $N. Ти дуже нагадуєш мені самого себе, коли я був молодим воїном Орди.$B$BТи, безсумнівно, далеко зайдеш у житті, а після смерті — ще далі.$B$B<Горуб — віддає честь.>",  -- db:3563
[961671627] = "І ще й скромний... Можливо, настав твій час, $N.$B$BЧи готовий ти увійти до фортеці орків Чорної Скелі? Щоб посіяти хаос? Щоб зруйнувати основи гірської цитаделі?",  -- db:3564
[417055371] = "Я ні на секунду не сумнівався в тобі, $N.$B$BОсь твої завдання, $N. Я знаю, що ти мене не підведеш.$b",  -- db:3565
[651285681] = "О, гість! Мабуть, це якийсь мандрівник — у нас тут нечасто бувають туристи. Візьми стільця та щось випити, влаштовуйся зручніше. Скажи, ти виглядаєш так, ніби маєш солідну статуру. Може, думаєш взяти участь у поєдинках у клітці?",  -- db:3566
[544770601] = "Вітаю, юний $c.",  -- db:3573
[334284208] = "Ренд, син Чорної Руки: Безсилий вождь клану Чорної Скелі. Упертішого за нього не знайти.$B$BНаприкінці Другої війни Ренд разом зі своїм братом Меймом втік, щоб знайти притулок у гірській фортеці Чорноскельна Вежа. Саме там Ренд проголосив себе вождем ослабленого клану Чорноскельних.",  -- db:3574
[559172831] = "Так, юний друже, тобі не треба переконувати мене в таких речах — у нас із Вождям довга спільна історія. Проте твоя відданість не залишилася непоміченою.$B$BЯк я вже казав, Ренд знайшов нову батьківщину для свого народу, і я був серед тих, хто знесилено пішов за ним.$B$BОдин конфлікт породжував інші... безліч інших. Саме в тих битвах за Шпиль Чорної Скелі між кланом Чорної Скелі та карликами Темного Заліза загинули обидва мої сини. Саме тоді я усвідомив, що мій час у клані Чорної Скелі добіг кінця.",  -- db:3575
[648414687] = "Я пішов. Я не збирався залишатися з «Чорною скелею». Ні, смерть моїх дітей не буде марною. Я не збирався служити під керівництвом такого некомпетентного, спраглого влади маніяка, як Ренд.$B$BI Я знайшов притулок у лісах Лордаерона, де жив відлюдником поблизу Гертглена.",  -- db:3576
[796054085] = "<Ейтріг сміється.>$B$BМолодий друже, світ не завжди був у такому безладі. Це були часи, ще до того, як «Пораза» спустошила ці землі. До того, як ці землі Лордаерона стали відомі як Землі Чуми.$B$BСаме там Трал врятував мене від смерті, і саме тоді я приєднався до нової Орди... але я відволікся. Ця історія — на інший раз. Так, на інший раз... Можливо...",  -- db:3577
[178542471] = "Я впевнений, що ти це зробиш. Можливо, одного дня ти зможеш передати повідомлення моєму старому другові. Кажуть, він досі блукає тими лісами.$B$B<Ейтріг на мить схиляє голову, ніби молиться.>$B$BТож, Ренд, так... Ренд і його брат Майм правили Шпилем, перебуваючи у постійному конфлікті з карликами Темного Заліза. Їм вдалося витіснити карликів із верхньої частини міста, але лише після приходу драконів і лише після смерті Майма.",  -- db:3578
[996412910] = "Дійсно. Нефаріан, нащадок Смертокрила, тепер править Шпилем. Ренд перебуває під командуванням дракона.$B$BЯкби тільки тобі якось вдалося пройти через Зали Сходження.$B$B<Ейтріг зітхає.>$B$BНа жаль, лише ті, кого Чорний полк визнає гідними, отримують привілей піднятися.$b",  -- db:3579
[323562765] = "Можливо. А тепер іди, юний друже. Звернися за порадою до Вождя. Він, безсумнівно, захоче дізнатися про твоє відкриття.",  -- db:3580
[451032005] = "Долина Випробувань загартує навіть найслабкішого, перетворивши його на воїна, гідного приєднатися до Орди. Ті, хто не зможе витримати її випробувань, будуть залишені смажитися під палючим пустельним сонцем.",  -- db:3583
[174071080] = "Привіт, $N.  Мене звуть Хронорму, але ти можеш називати мене Хромі.  Мені не заважає така неформальність.$B$BА тепер — ти запитаєш, звідки я знаю твоє ім’я?  Я належу до бронзового драконячого полку, який назавжди налаштований на припливи й відпливи часу.  Можна сказати, що ми вже зустрічалися раніше.  Отже, ми ще зустрінемося.$B$BСподіваюся, що мій зовнішній вигляд вас не бентежить; хоча мені й доручено охороняти сумні місця, я вирішив не потопати у смутку цих країв.$B$B$B",  -- db:3584
[750398133] = "Ще раз вітаю, $N.  Я відчуваю, що плин часу й досі перебуває під загрозою з боку справді потужних сил.  Бронзовий драконячий полк завжди радо вітає твою постійну допомогу.$B$BХоча минуле є незмінним, майбутнє постійно змінюється.  Рішення, які ти приймаєш тут і зараз, допомагають скерувати ці зміни.",  -- db:3585
[705068061] = "Слухай старших, $N. Якщо ти маєш сильну волю і відданий справі, немає такої сили, яку ти не зміг би опанувати.",  -- db:3586
[923449973] = "Не всі «Покинуті» керуються волею Сильвани, $N. Декого з нас рухає справжня сила — та, яку ми здобуваємо власною працею.",  -- db:3587
[36621332] = "Це... не... найкращий... час, $N. Мені треба зосереди... ти.",  -- db:3589
[100066419] = "Твоє доручення, мабуть, дуже важливе, $c, якщо воно завело тебе так глибоко в болото...",  -- db:3590
[83815291] = "Пекельний — один із наймогутніших демонів, на підтримку якого чаклун може розраховувати в бою. Ця істота сильна, добре захищена бронею та завдає нищівних ударів будь-якому супротивнику. Якщо ви вирішите втілити дух інфернала у свою зброю, то отримаєте деякі з цих переваг — більший запас здоров’я, швидшу регенерацію тощо.$B$BЯкщо ви хочете дізнатися більше про фелхаундів, то вам слід поговорити з Вітулою, яка сидить навпроти мене.",  -- db:3591
[71085782] = "Фельхаунд… справді люта істота. Фізично він не такий сильний, як інфернал, але мудрий чаклун знає, що груба сила — не завжди найкращий вихід; якби це було так, ти б обрав шлях воїна, чи не так?$B$BФельгаунд черпає ману своїх супротивників, використовуючи її та свою швидкість, щоб перемогти ворогів. Його сила походить від таємних знань, і він використовує цю магічну силу для власних цілей.$B$BЯкщо ти хочеш дізнатися більше про інферналів, то тобі слід поговорити з Магазом, який сидить навпроти мене.",  -- db:3592
[845417621] = "$N, ти вже поговорив з кимось із моїх помічників у вежі? Ми не зможемо завершити створення твоєї кулі, доки ти не виконаєш одне з їхніх завдань. Якщо ти готовий, поговори з ними зараз.",  -- db:3594
[44211764] = "Будь ласка, допоможи мені, $g брате : сестро;...$B$BI, я незабаром покину цей світ, і хоч я й страждаю, я знаю, що після смерті мої страждання закінчаться.  Але дикі тварини, мій $g брате : сестро;... дикі тварини теж страждають, і для них немає порятунку.  Я прошу твоєї допомоги своїми останніми подихами життя.",  -- db:3633
[780553633] = "Так, я розмовляю мовою, яку ви розумієте, $r.  Ми не тварини, проте більшість представників вашого виду продовжує ставитися до нас саме так!  Проте наші розбіжності бліднуть на тлі трагедії, що спіткала цю землю.  Будь ласка, відкиньте свої розбіжності з моїм народом і вислухайте моє останнє благання.$B$BI я прибув на цю землю, щоб виправити те, що міг, і тепер це буде марним, якщо ви не допоможете мені.  Я прошу про таку допомогу, випускаючи останні подихи життя.",  -- db:3634
[137787116] = "\"...\"$B$BТіло друїда-таурена лежить нерухомо.  Складається враження, ніби він нарешті покинув цей світ і відправився у обіцяне потойбіччя.",  -- db:3635
[886253171] = "Я — міський чиновник, який відповідає за проведення перепису населення Підмістя.  З часу нашого визволення від Плетіння ми намагаємося вести точний облік населення нашого міста. Завдяки магічним методам та вигостреній розумовій дисципліні я маю доступ до цих записів. Якщо у вас є до мене справа, пов’язана з цим, будь ласка, звертайтеся. У будь-якому разі, ви повинні знати, чи є у вас така справа.",  -- db:3653
[665844453] = "Верховний вождь доручив мені вивчити всі види зброї та обладунків. Він відправив мене сюди, у центр культур тауренів та орків у Пустках, щоб я зустрів якомога більше мандрівників і дізнався про культури Пусток.$B$BВін вважає, що навіть із найжалюгідніших культур можна чогось навчитися... як-от з культури квілбоарів чи кентаврів.",  -- db:3654
[399863473] = "Ти! $R! Підійди сюди. <хрюкання>$B$BЧасу обмаль, і мій кінець <хрюкання> наближається. Манглетут переможе; ти це побачиш. <хрюкає>$B$BМоє полонення ще може допомогти <хрюкає> моєму народу. Плем’я «Бритвогриви» могутніше за «Щетиноспинів»!$B$BOрда прагне з’ясувати, хто очолює набіги на їхній народ. Ти <хрюкання> маєш допомогти Манглтуту в обмін на інформацію, яку знаю лише я. Манглтут може тобі допомогти! <хрюкання> Але ти мусиш допомогти Манглтуту.",  -- db:3656
[234259553] = "Ласкаво просимо до Штормовію!  Я — один із міських чиновників, який допомагає мешканцям міста через наше бюро перепису населення.  Якщо вам потрібно знайти конкретну особу, я, можливо, зможу вам допомогти.  Завдяки таємничим методам та витонченій розумовій дисципліні я маю доступ до цих записів.$B$BЯкщо у вас є до мене справа, будь ласка, підходьте!",  -- db:3657
[408012607] = "Моя ненависть сильна <хмикання>, але настав час розповісти вам одну історію, $r.$B$BDавним-давно між богами відбулася битва. Агамагган, наш великий бог-кабан, впав на землю після поразки у Війні Стародавніх: його кров лилася дощем, а кістки були розтрощені на шматки. <хрюкання>$B$BЗ землі, де його кров торкнулася ґрунту, виросли величезні колючки, а його череп прикрашає одну з печер на півдні.",  -- db:3658
[657542375] = "Уф... Мені треба покурити й відчути дотик чарівної гномки — хоча й не обов’язково саме в такому порядку!$B$BI я місяцями просидів у череві цієї потвори! А взагалі, який сьогодні день? А, та неважливо. Головне, що я нарешті на волі.$B$BВУУУ-ХУУУ!",  -- db:3659
[370894419] = "Як?? Ну, це довга історія.",  -- db:3660
[326056050] = "Ну що ж! Отже, я був біля лавових ям у «Розплавленому мосту», випробовуючи свій лавовий костюм. Усе йшло чудово. Я навіть зміг поплавати в цій рідині, не отримавши жодної травми!$B$BОтож я собі плаваю, нікому не заважаю, роблю кілька гребків на спині, як раптом з нізвідки ця штука проковтнула мене цілком! Якби не мій лавовий костюм і вбудований дозатор харчових гранул, мені б кінець!",  -- db:3661
[661687789] = "Слухай, я відчуваю у твоєму голосі певну дозу скептицизму — але так, саме так і було.",  -- db:3662
[253041390] = "Я вибрався з пащі цього чудовиська не більше двох хвилин тому, а хтось уже розпитує мене про мою поведінку у туалеті??? $G Містер:Міссі;, я б дав тобі по морді за таке запитання, якби не ти мене врятував!$B$BТа що там! Я вдячний за допомогу. Може, я зможу віддячити тобі?",  -- db:3663
[274443679] = "Ну, можливо, «платити» — не найкраще слово в цьому контексті. Розумієте, коли я застряг у череві тієї тварюки, я подумав:$B$BЦя істота живе в гарячій, палаючій магмі, але вогонь їй анітрохи не шкодить!$B$BЯкби тільки я міг знайти неушкоджену шкуру однієї з цих тварюк. Я міг би віднести її своєму дорогому другові, Маліфусу Даркхаммеру, в Еверлук. Якщо хтось і зможе щось зробити зі шкірою такої тварини, то це саме він. $b",  -- db:3664
[717494826] = "То як щодо того, щоб ти передав від мене повідомлення?",  -- db:3665
[940395752] = "Хочеш купити таргана?",  -- db:3666
[880712056] = "Час для мене добігає кінця... для нас усіх...",  -- db:3668
[275576791] = "У мене стільки справ... стільки всього, поки не настане чума...$B",  -- db:3668
[533158353] = "Джоне, коханий, де ти?",  -- db:3668
[855688263] = "Що з усіма відбувається?  Мені... холодно...",  -- db:3668
[442671066] = "Тсс... ти щось відчуваєш?",  -- db:3668
[656501884] = "Дух дивиться на тебе з відчуттям повноти та усвідомлення, яких раніше не було.$B$BЯ відчуваю, ніби з моєї душі зняли великий тягар.  Незабаром я назавжди спочиватиму в мирі.  Тепер я це знаю і терпляче чекаю на цей момент.$B$BДякую тобі, незнайомцю.",  -- db:3669
[399108386] = "Ти <хмик> допоміг Манглетуту більше, ніж я міг би й мріяти, $r.$B$BДякую.$B$BПоки я залишаюся тут у полоні, ти можеш приносити мені осколки крові квілбоара Брістлбека, і я благословлю тебе силою Агамаггана.",  -- db:3670
[111861044] = "Братство Торію не витрачає час на мурах. Забирайтеся геть!",  -- db:3673
[324131344] = "Для майстра мого рівня це простий процес.$B$BНайскладнішим у виготовленні предметів зі шкір та панцирів звірів є саме здобуття цих матеріалів. Отже, якби ви могли принести мені неушкоджену шкіру цього звіра, я зміг би виготовити з неї кілька різних потужних предметів.",  -- db:3674
[154095609] = "Гадаю, шанси отримати такий шматок шкіри становлять один до мільйона! Таку шкіру можна зустріти лише раз у житті! Навіть найдосвідченіші майстри цієї справи, без сумніву, зазнали б кількох сотень невдач під час зняття шкіри з тварини, перш ніж їм вдалося б отримати бездоганний зразок.$b",  -- db:3675
[919377458] = "А якщо ти справді приніс мені шкуру цієї тварини? Ну... Давай я тобі покажу...",  -- db:3676
[471355926] = "Осінній каталог «Братства Торію»:$B$BУ ньому ви знайдете найвигідніші пропозиції на все необхідне для ваших пригод! Ми навіть підкажемо, де можна придбати ті компоненти та припаси, які важко знайти.",  -- db:3677
[629053808] = "Назва цієї книги написана витонченим почерком: «Щоденник Морін Далсон».",  -- db:3693
[365848924] = "Щоденник із пожовклими сторінками лежить розгорнутим на останньому записі:$B$B\"Я не знаю, що буде далі, тепер, коли Гарольд перетворився.  Мені знадобилися всі сили, щоб затягнути його в єдине місце, яке я зміг знайти, де його можна надійно замкнути й утримати.  Я сховала ключ при собі і молюся, щоб він спрацював...$B$BСподіваюся, що зможу звідси вибратися, але для цього мені потрібні гроші.  Наші речі, здається, усі в шафі... а тепер, коли я про це замислилася, хіба Гарольд не тримає ключ при собі?$B$BЯ відпочину, бо зараз я вкрай втомлена.\"",  -- db:3694
[897604141] = "Що це у тебе там, $N$B$B<Маліфус вказує на невистрілені пластинчасті рукавиці, що стирчать із твого рюкзака.>",  -- db:3734
[420872802] = "Ласкаво просимо на передову, $c.  Хоча політики можуть між собою змовитися й плести інтриги, тут вони не матимуть такої розкоші.  Це «Булварк», і тут ми щодня боремося за своє виживання.$B$BЯкщо ви прийшли сюди, щоб довести, що ви герой, то знайдете безліч можливостей для цього... особливо коли ми наступаємо на Андорхал і на ту злісну силу, яка там керує «Покаранням».",  -- db:3753
[913878121] = "Ласкаво просимо на передову, $c.  Королівство Штормовій за допомогою своїх союзників відправило мене сюди, щоб протистояти зростаючій загрозі з боку Плеті.  Тут, у таборі Холодний Вітер, ми щодня боремося за своє виживання.$B$BЯкщо ти прийшов сюди, щоб довести, що ти герой, то знайдеш безліч можливостей для цього... особливо коли ми рушимо на Андорхал і на ту злісну силу, яка там керує Плетью.",  -- db:3754
[459567774] = "Приємно бачити інших, хто бореться з Плетью у Стратхолмі, адже саме тут вони найсильніші.$B$BВітаю.  Я — Ауріус.  Колись я був паладином «Срібної Руки», але, як і інші, чия віра похитнулася... Я впав у гріх.  Плеть спокусила мене й ледь не перетворила на лицаря смерті!$B$BНарешті усвідомивши небезпеку, я втік до цієї каплиці.  Це священне місце, де перший паладин, Утер Світлоносець, був посвячений у орден Срібної Руки.",  -- db:3755
[246208106] = "У мене не так багато часу в цьому світі, але, якщо Світло дозволить, його вистачить, щоб виконати моє призначення. Коли ти зіткнешся з бароном Рівендаре, я буду поруч із тобою.",  -- db:3756
[581510766] = "Залиш мене.  Мої рани дуже тяжкі, і я боюся, що вони мене здолають.  Дякую, $N.  Я помру тут, але завдяки тобі... я помру з миром.",  -- db:3757
[351602626] = "Не випробовуй моє терпіння, смертний.",  -- db:3758
[410396535] = "Прикуси язика, $r, інакше я вирву його з твоєї черепної коробки й використаю як грілку для рогу.",  -- db:3759
[453171194] = "Звісно ж, те, чим я займаюся. Я замислююся. Я нарікаю. Я ненавиджу. Я плету інтриги. Коли цей цикл завершується, я знову замислююся. Чого ти від мене хочеш? У мене стільки думок на думці.",  -- db:3760
[518795804] = "Ти?$B$B<Лоракс сміється.>$B$BЦе сумнівно.$B$BЯ стою серед цих руїн і мрію. Мрію про той день, коли я спіймаю того жалюгідного злодія, Горалука Анвілкрака.$B$BУ нас з ним була угода. Угода, яку він порушив. Зрадив.",  -- db:3761
[238181848] = "Я навчив би його мистецтву демонічного ковальства в обмін на його душу. Душа орка з Чорної Скелі мало чого варта, але в ці скрутні часи будь-яка душа — навіть найменш цінна — краще, ніж її повна відсутність.",  -- db:3762
[506520866] = "Він взяв некований нагрудник, покритий рунами, який використовувався для виготовлення нагрудника, викуваного демонами, і втік, не заплативши. Я, звичайно, не дурень, але... некований нагрудник ні до чого без знань або рецепта, як ці знання застосувати.$B$BЦікаво... чи сидить він у безпеці у своєму місті Блекрок-Спайр і намагається створити цей предмет із сировини? Я знаю, що він не наважиться вийти звідти!",  -- db:3763
[65799979] = "З того часу, як ми оселилися в кратері, Даданга дуже полюбила великі паростки «кров’яної пелюстки», які тут ростуть повсюди.$B$BIЯ впевнена, що вона з радістю з’їсть їх на перекус, якщо ти захочеш принести їй трохи...",  -- db:3793
[95302663] = "Привіт, друже.  Підійди й поговори з моїм майстром Гадріном, ось там.  Позбуйся заради нього того божевільного Залазана, і я тебе одразу вилікую!",  -- db:3794
[129507544] = "Так, чувак, я — помічник Гадріна. Ця волонтерська робота — мій спосіб оплатити навчання у Школі чаклунів. Оскільки ти йому допомагаєш, я тобі допоможу безкоштовно. Що тобі потрібно полагодити?",  -- db:3795
[676722334] = "Я... Я важко поранений...",  -- db:3797
[693714102] = "Послухай, $r. Слухай уважно...$B$BВночі прилетіли вершники-дракони, сидячи верхи на чорних крилатих створіннях. Вони атакували швидко й зі смертельною точністю, викрадаючи молодих дитинчат — таких, як я — і зникаючи під покровом темряви.$B$BЯ з жахом спостерігав, як вони використовували моїх братів і сестер у своїх експериментах. З нашої сутності мала бути створена хроматична зграя.",  -- db:3798
[998081557] = "Нефаріан наказав негайно знищувати непридатних піддослідних, але ці огидні тварюки не робили цього, не завдавши спочатку «достатньої» кількості тортур.$B$BКоли нас повністю «ламали», вони збирали те, що від нас залишалося, і кидали нас на поталу цим головорізам. Наші тіла використовували як інструменти в їхній хворий грі: кидали в лаву або ще гірше — у відкриті й чекаючі обійми кровожерливого легіону внизу.",  -- db:3799
[503428285] = "Ти з’явився саме в той момент, коли вони вже збиралися кинути мене на поталу демонам внизу — за це я тобі вдячний. Можливо, я — чи, краще сказати, ми, з «Блакитного полку», зможемо ще чимось тобі допомогти?$B$BТи дійшов аж сюди, $r, багато ризикував. Чи підеш ти ще трохи далі, щоб битися з Нефаріаном та його легіоном Чорної Скелі?",  -- db:3800
[105815406] = "Якщо ти тут, щоб полювати на драконів, будь ласка. Куди мені надіслати свої співчуття?",  -- db:3801
[820162554] = "Твій сморід привабить усіх драконів у радіусі кількох миль. Скажи мені, чого ти хочеш, і якнайшвидше.",  -- db:3802
[630283209] = "Духи сказали мені, що ти прийдеш, що ти з якоїсь причини шукатимеш мене, але що навіть ти, можливо, не знаєш цієї причини. Тож, ти знаєш, чому ти тут?",  -- db:3803
[858138548] = "О, привіт! Мене звати Сара. Чим можу допомогти?",  -- db:3804
[791864937] = "Ліс розповів мені про твою присутність, але не пояснив, чому ти тут. Тож розкажи мені, будь ласка.",  -- db:3805
[927648375] = "Як справи, друже!",  -- db:3806
[373021972] = "Вітаю тебе, $N. І «Смарагдове коло» вітає тебе.$B$BСподіваюся, разом ми зможемо допомогти відродити та захистити цей колись могутній ліс. Багато сил прагнуть знищити його як ззовні... так і зсередини.$B$BНе піддавайтеся впливу місцевої сили — вона лише зіпсує вас, як уже зіпсувала всю цю землю.",  -- db:3807
[135550158] = "Не вистачає сміливості покататися на грифоні, так?  Що ж, на щастя для тебе, у нас є альтернатива, завдяки якій ти зможеш тримати ноги на землі… більш-менш.  Це гномський транспортний засіб — трамвай «Діпран».  Він зручно розташований у глибині Дварфського кварталу.",  -- db:3813
[182824421] = "Ви ж чули про трамвай, правда?  Це просто неймовірна поїздка!  Його можна знайти в Дварфському районі, трохи вглиб.  О, і не забудьте тримати руки та ноги всередині трамвая, поки він рухається.",  -- db:3813
[608359196] = "Так, усі хочуть проїхатися на трамваї — це справді класна розвага. Ну, якщо хочете знайти трамвай, він знаходиться в Тінкер-Тауні, трохи на схід від воріт Айронфорджа.",  -- db:3814
[365903204] = "О, трамвай, трамвай...  всі хочуть проїхатися на трамваї.  А де ж ті старі добрі часи, коли можна було літати верхи на грифоні, тримаючись за сідло щосили, піднімаючись високо в небо?  $B$BБа!  Тоді їдь на трамваї... він стоїть у Тінкер-Тауні разом з рештою гномівських винаходів.",  -- db:3814
[476574210] = "У книзі розповідається про драконів, які об’єдналися проти іншого, ще могутнішого дракона на ім’я Десвінг. З того, що можна зрозуміти, хроматичний драконячий полк ледь не був випущений на світ. Аспекти були готові.",  -- db:3815
[121879450] = "На «Террасі ремісників» відкрився новий заклад. Якщо ви підете стежкою, що веде на південний схід від берега, його неважко буде знайти.",  -- db:3833
[417400919] = "О, ця вічна одержимість матеріальним багатством.  Що ж, удача тобі посміхається, адже ти можеш знайти аукціонний дім на «Террасі торговців».",  -- db:3833
[960206887] = "Він розташований у Торговому районі міста.  До нього веде майже пряма дорога від входу до Штормовію.",  -- db:3834
[576663461] = "Ще один підприємець, так? Що ж, Аукціонний дім розташований у Торговому районі. Неподалік від банку.$B",  -- db:3834
[226406518] = "Ще один підприємець, так? Що ж, Аукціонний дім розташований у Торговому районі.  Недалеко від банку.",  -- db:3834
[317176552] = "Вітаю, мандрівнику. Небагато хто знаходить мене в цих краях.$B$BМене звати Ріверн, і я готую «Морозних саблезубів» з Вінтерспринга, щоб вони стали верховими тваринами.$B$BЦі коти — найдикіші та найважчі для приручення серед усіх саблезубів. Лише найнадійніші та найшанованіші можуть спробувати осідлати одного з них.$B$BЯ не продам такого верхового тварину кому завгодно; ні, ти повинен заслужити це своєю працею та завоювати визнання не лише з мого боку, а й з боку самих саблезубів.",  -- db:3854
[544830639] = "Вважається, що він існує. Лише великий хроматичний дракон або дракон вищого рангу міг би мати такий панцир.",  -- db:3855
[320764743] = "Часто зустрічаються під час «малого хроматичного польоту»: молодняк, вилуплені дитинчата, малі драконята.",  -- db:3856
[417377812] = "Легенда свідчить, що в місцях найзапекліших боїв, на території, яка сьогодні відома як Землі Чуми, з-під землі можуть вириватися чисті й священні джерела. Воду з цих джерел — як ремісники, так і прості люди — називають «Кров’ю героїв» на честь тих, хто загинув у війні проти Плеті.",  -- db:3857
[335216200] = "Сім’я Баров із Шоломанса використовувала його як дзеркало, що відбиває душі, яких вони вже не мають. Цінна пам’ятка.",  -- db:3859
[48692558] = "У Штормовій є чимало закладів, де можна випити, але лише в одному з них можна переночувати. Завітайте до «Позолоченої троянди» у Торговому районі. Я чув, що ціна за номер там помірна, а постільна білизна чиста.",  -- db:3860
[501957912] = "Ах, «Позолочена троянда»... з її м'якими пуховими ліжками та теплими ваннами... лише від однієї думки про цей готель мені хочеться... ::позіхання:: Щасливці ті, хто збирається туди...  Ви знайдете його в західній частині Торгового району.   ...приємні м’які подушки, теплі ковдри.  ::позіхання::",  -- db:3860
[553245647] = "У Торговому районі, між Банком Штормовію та готелем «Позолочена троянда», зручно розташована поштова скринька.",  -- db:3861
[838912460] = "Не знаю, як їм це вдається... Ці поштові скриньки, мабуть, якісь чарівні портали чи щось таке. Адже я бачу, як люди цілий день збираються біля поштової скриньки поруч із банком і дістають з тієї маленької скриньки мечі, щити та різноманітні обладунки!",  -- db:3861
[775202305] = "Привіт, $c. Мене звати Джессір Мунбоу. Я приїхав із Дарнассуса, щоб розшукати двох друзів, які вирушили до Фелвуда на пошуки слідів Ради Тіней.$B$BСхоже, ті огидні істоти, які беруть на себе відповідальність за значну частину страждань раси орків, прагнуть відновити частину своєї могутності.$B$BМої двоє друзів вирушили до Джеденара, щоб з’ясувати, що ж насправді відбувається.$B$BЯ сподівався, що вони будуть тут, коли я приїду, але вони запізнюються вже кілька днів.",  -- db:3864
[156597045] = "Так холодно... і голодно.$B$BМій бідний друже, сподіваюся, ти знайшов спокій. Мені нестерпно думати про те, що вони могли з тобою зробити.$B$BТи! Ти там! Будь ласка, ти мусиш допомогти мені втекти. У когось із них є ключ, чи зможеш ти його знайти? Я знаю, що він у них є. Якщо ти його знайдеш, зможеш допомогти мені вибратися звідси. Трей, мабуть, уже мертвий, але ще є час! Будь ласка, ти можеш мені допомогти?",  -- db:3865
[97000271] = "Привіт! Я щойно повернувся з експедиції до Руїн Кель'Теріла, що на південному заході. Тепер я маю намір дослідити диких істот, які мешкають трохи вище по хребту, у Заростях Совиного Крила.$B$BТи вже розмовляв з Ереласом Амберскі в селі Рут'теран? Він попросив мене приїхати сюди, і, можливо, у нього є завдання й для тебе.",  -- db:3866
[446867425] = "Ти бачив Вартового Бекуса? Такий хоробрий...$B$BЯ думаю, він найміцніший з усіх Нічних Вартових. Цікаво, чи він взагалі помічає, що я поруч...",  -- db:3868
[42664697] = "Дякую! Ти мене врятував!",  -- db:3873
[194318861] = "О, дякую! Я вже так довго перебуваю в цьому кошмарі...",  -- db:3873
[749719743] = "Нарешті моя душа вільна!",  -- db:3873
[470441137] = "Дякую!  Битва за Дарроушир прирекла мене на загибель, але ти мене визволив!",  -- db:3873
[264875380] = "Ах!  Будь ласка, якщо побачите когось, хто вижив у Дарроуширі, скажіть їм, що я на волі!",  -- db:3873
[472143832] = "«Смарагдове коло» прагне зцілити поранену землю Фелвуда. Хоча ця земля отримала свою назву на честь того самого, що її зіпсувало, ми сподіваємося, що одного дня нам вдасться викорінити з неї цю порчу.",  -- db:3874
[146837321] = "Швидше-швидше, хоробрий $c!  У мене є для тебе найкращі вовчі верхові тварини, які ти можеш оглянути.  Ніде більше ти не знайдеш тварини з таким рівнем витривалості та інстинктом виживання, як у вовка!  Будь ласка, оглянь їх сам.",  -- db:3893
[377896504] = "І тобі гарного дня, хоробрий $c.  Я знаю, що ти шукаєш чудового скакуна.  Немає кращого скакуна, ніж хижак під твоїми вуздечками, повір мені, $g, друже : sis;!  Поглянь на тих, що я можу запропонувати — виведені з найлютішого породи у світі.",  -- db:3896
[608889956] = "Вони передають мені трупи, а я кидаю їх у яму.",  -- db:3935
[331122710] = "Вітаю, $N. Я — Мійолор Сандерфюрі, хранитель Великої Кузні.",  -- db:3937
[858665558] = "Ваші навички ковальства просто виняткові, $N. Настав час прийняти рішення. Ти можеш обрати один із двох шляхів: шлях зброяра або мистецтво броняра.$B$BМайте на увазі: коли ви вирішите присвятити себе одному зі шляхів, назад дороги не буде. Дисципліна, якої вимагає кожен із цих шляхів, не залишає місця для гібридних варіантів.",  -- db:3938
[114578418] = "Настав час, мій $g брате : сестро по зброї, відвоювати ніч у «Скордж»!",  -- db:3939
[452638710] = "З ласки Елуни я радий запропонувати тобі найкращого коня, якого можна знайти в Телдрасілі, а може, й у всьому світі, — нічного меча. Протягом багатьох років Армія Вартових покладалася на цінність цих супутників.$B$BНе поспішай, друже, і оглянь кожного з них, поки не залишишся задоволеним.  Я впевнений, що ти не будеш розчарований.",  -- db:3942
[876008675] = "Е-е-е... Мені здається, ви трохи завеликі, щоб кататися там на «Механо-страйдері», $g пане : пані;.  Ви, мабуть, розчавите ті ретельно налагоджені сервобалансери!",  -- db:3944
[254305169] = "Якщо ви шукали подарунок, який забезпечить швидку та безпечну мобільність, то ви потрапили саме туди, куди потрібно! Цьогорічна модель нових «Механо-страйдерів» нещодавно надійшла, і я готовий показати вам усі їхні можливості!",  -- db:3945
[920435754] = "Коли майстерність коваля досягає вашого рівня, я пропоную йому зробити вибір.$B$BХоча ви не зобов’язані робити вибір, рекомендується це зробити — зрештою, хіба ви хочете назавжди залишатися новачком? Саме майстри-броневики та зброярі забезпечують наші армії, виграють наші війни та здобувають славу!$B$BБудьте обережні, $N. Як тільки вибір зроблено і необхідні завдання виконано — назад дороги немає. Можна йти лише одним шляхом.",  -- db:3953
[7395597] = "Я — Краток, наглядач цих майстрів.",  -- db:3954
[237914944] = "Вітаю, $r.",  -- db:3959
[199276055] = "Привіт, $c!",  -- db:3960
[883247436] = "Чого ти хочеш?",  -- db:3961
[275184987] = "Нехай Світло буде з тобою, $c. Чим можу тобі допомогти?",  -- db:3974
[134436158] = "Може, ти й не дотримуєшся шляхів Світла, як лицар Срібної Руки, але завжди можеш звернутися до нас по допомогу.",  -- db:3975
[998137053] = "Насувається сильний вітер — я це відчуваю по болю в оголеному коліні.  Сподіваюся тільки, що ми не потрапимо під його вплив.",  -- db:3978
[943907245] = "Ну що ж, $N, давай візьмемося за ці казани! Якщо ти збираєшся зібрати необхідні нам компоненти, то візьми в мене скляний фокусувач.  Він тобі знадобиться, щоб ідентифікувати необхідні ресурси, знайдені на «Скауджі», які допоможуть запустити ці казани.$B$BТобі також знадобиться доза магічного прискорювача для казанів.  Він не дешевий і нестабільний.  Отримавши його, у вас буде лише тридцять хвилин, щоб використати його, перш ніж термін дії закінчиться; будьте розсудливими, купуючи його.",  -- db:3979
[192123282] = "Виходячи зі зразка токсину, який ви нам надали, ми вважаємо, що вам знадобляться такі речі: магічний прискорювач, шість кісткових агітаторів та чотири шматки рунічної тканини.  Взявши з собою скляний фокусувач, здобуйте агітатори у скелетних неживих тут, у Землях Чуми!$B$BКоли ви отримаєте ці предмети, ви зможете завантажити протиотруту в той казан.",  -- db:3980
[395373873] = "Виходячи зі зразка токсину, який ви нам надали, ми вважаємо, що вам знадобляться такі речі: магічний прискорювач, п’ять соматичних підсилювачів та чотири шматки рунічної тканини.  Взявши з собою скляний фокусувач, здобуйте підсилювачі у зомбі чи гулів-нежиті тут, у Країнах Чуми!$B$BКоли ви отримаєте ці предмети, ви зможете завантажити протиотруту в той казан.",  -- db:3981
[255451497] = "Виходячи зі зразка токсину, який ви нам надали, ми вважаємо, що вам знадобляться такі речі: магічний прискорювач, чотири ектоплазматичні резонатори та чотири шматки рунічної тканини.  Взявши з собою скляний фокусувач, здобуйте резонатори у привидів та примарних неживих тут, у Землях Чуми!$B$BКоли ви отримаєте ці предмети, ви зможете завантажити протиотруту в той казан.",  -- db:3983
[649110973] = "Ця робота точно не варта шістнадцяти п’яти на рік.",  -- db:3984
[727367188] = "Чума «Бича» досі панує в цій зоні, і нам ще далеко до того, щоб її можна було змінити настільки, щоб це вплинуло на них. Зберіть необхідні ресурси та долучіться до військових зусиль!",  -- db:3996
[876868729] = "Епідемія «Бича» майже досягла переломного моменту; ще кілька підривів котлів — і ми перейдемо рубіж!  Обов’язково зробіть свій внесок, щоб допомогти!",  -- db:3997
[505336450] = "Ми почали обернути чуму «Покарання» проти них, але наша перевага, м’яко кажучи, нестійка! Обов’язково допоможіть нашій справі, підриваючи їхні казани!",  -- db:3998
[95766237] = "Ми беремо гору над Плетью — наслідки зміненої чуми будуть впливати на них ще щонайменше цілий день!  Проте нам потрібно тримати ситуацію під контролем, тож не забудьте саботувати котел, коли буде така можливість.",  -- db:3999
[905409805] = "Ім'я тренера мисливців — Тотар.  Знайдіть його всередині нори в південно-західному куті Гори Бритви.",  -- db:4013
[382760618] = "Ти мисливець?  Що ж, у будь-якому разі, ти знайдеш Тотара, який ховається від сонця в норі в південно-західному куті міста.",  -- db:4013
[466830231] = "Поговоріть з Ун'Тувою, який знаходиться на півдні села Сен'джин.",  -- db:4014
[737519639] = "Це справа тролів. Шукайте Ун'Тхуву в селі Сен'джин, що на півдні.",  -- db:4014
[775358675] = "Ти шукаєш Тай'джин. Знайди її в казармах на східній стороні міста.",  -- db:4015
[161277336] = "Її звуть Тай'джин, і ви знайдете її всередині казарм на східному схилі Гори Бритви. Вона навчить вас поважати богів. Обов'язково проявіть до неї належну повагу у відповідь!",  -- db:4015
[921634975] = "Знайдіть Каплака на вершині нори в південно-західній частині міста.",  -- db:4016
[77350041] = "Навіщо тобі розмовляти з Каплаком?  Та нічого.  Шукай його на вершині нори в південно-західному куті Гори Бритви.  Тільки не забудь тримати руки в кишенях!",  -- db:4016
[217562562] = "Вам потрібно знайти Сварта. Шукайте його всередині казарм на східному схилі Разор-Хілл.",  -- db:4017
[758553907] = "Вождь приносить зміни, які приведуть Орду до перемоги!  Шукайте Сварта в казармах на східній стороні міста.",  -- db:4017
[797722800] = "На східному схилі пагорба Рейзор, за казармами, ви знайдете Дхугру Горелуста.",  -- db:4018
[678172919] = "Дхугру Горелуст ховається за казармами на східній околиці міста.  Не дай мені дізнатися, що ти в змові з Палким Легіоном!",  -- db:4018
[808624699] = "Шукайте Таршоу Джеггдскара в казармах на східній стороні міста.",  -- db:4019
[70255432] = "Знайди Таршоу Джеггдскара в казармах на східному схилі Гори Бритви.  Принеси гордість і честь Орді, юний воїне!",  -- db:4019
[569333377] = "Знайдіть Мяозана в селі Сенджин, що на півдні.",  -- db:4020
[921661702] = "Я чув, що серед тролів у селі Сен'джин є майстер зі створення зілля на ім'я Мяо'зан.  Пошукай його там.",  -- db:4020
[709885412] = "Це, мабуть, Двук. Знайдіть його біля розпеченої кузні в північно-західному куті міста.",  -- db:4021
[940926673] = "Якщо ви вважаєте, що у вас вистачить сил, щоб викувати з якісного металу зброю та обладунки для Орди, знайдіть Двукка біля розпеченої кузні в північно-західному куті Гори Бритви.",  -- db:4021
[668440039] = "Рухайтеся на північ по дорозі до Оргримара. Там ви можете запитати у одного з солдатів, як дістатися до інструктора з кулінарії.",  -- db:4022
[152615382] = "Мммм, їжа.  Дорога не надто довга, але тобі треба вирушити на північ, до Оргримара, і звернутися до одного з місцевих солдатів.",  -- db:4022
[439880851] = "Один із них знаходиться в Оргримарі.  Один із солдатів там підкаже тобі, як туди дістатися.  Просто йди на північ цією дорогою — ти не пропустиш його.",  -- db:4023
[79399382] = "Я не знаю, чи є тут хтось із них. Найкраще буде вирушити на північ, до Оргримара, і поговорити з одним із їхніх солдатів.",  -- db:4023
[548744926] = "У Разор-Хіллі є інструктор з інженерії.  Його звуть Мукдрак, і зазвичай його можна зустріти біля кузні.",  -- db:4024
[420553389] = "Та годі, це робота гоблінів!  Проте у нас тут, на Бритвовому Пагорбі, є орк, який навчить тебе цьому.  Шукай Мукдрака біля кузні.",  -- db:4024
[222889798] = "Один із них знаходиться всередині казарм на східному схилі Разор-Хілл. Шукайте Раурка.",  -- db:4025
[650221018] = "З огляду на те, що ми постійно беремо участь у боях, у Разор-Хіллі, звісно ж, є інструктор з надання першої допомоги. Знайдіть Раурка в казармах на східній стороні міста.",  -- db:4025
[809944700] = "Я бачив троля на ім'я Лау'Тікі, який ловив рибу на півдні, на Березі Темного Списа. Це прямо на околиці селища Сен'джин.",  -- db:4026
[138520524] = "Ви шукаєте Лау'Тікі. Ви знайдете його на Березі Темного Списа, що розташований на південь від селища Сен'джин.",  -- db:4026
[245825481] = "Ти шукаєш Мішікі.  У неї є хатина на півдні села Сендзін.",  -- db:4027
[6812554] = "Квіти?  На цій пустці?  Якщо хтось і зможе навчити тебе, як їх знайти, то це Мішікі з села Сен'джин, що на півдні.",  -- db:4027
[435818122] = "Для цього вам доведеться вирушити до Оргримара. Просто йдіть дорогою, що веде з Бритвового пагорба на північ через каньйон, і ви туди потрапите. Коли дійдете, запитайте в одного з їхніх солдатів, як далі йти.",  -- db:4028
[526608308] = "Щоб навчитися обробляти шкіру та працювати зі шкурами, вирушайте на північ, до Оргримара. Один із солдатів Оргримара вкаже вам шлях до інструктора з шкіряного ремесла.",  -- db:4028
[916403656] = "Звісно, звісно. У нас тут, у місті, є інструктор з гірничої справи. Шукайте Крунна в північно-західному куті, поруч із готелем.",  -- db:4029
[633899245] = "У Дуротарі, як я чув, можна чудово займатися гірничою справою. Настільки чудово, що у нас тут, у Рейзор-Хіллі, є інструктор з гірничої справи. Ви знайдете Крунна поруч із опалювальною кузнею в північно-західному куті міста.",  -- db:4029
[229009569] = "В Оргримарі є тренер зі зняття шкур. Щоб туди дістатися, рухайтеся на північ по дорозі, що веде з Разор-Хілл. По прибутті запитайте дорогу в одного з солдатів Оргримара.",  -- db:4030
[395812798] = "Один із них знаходиться в Оргримарі.  Йдіть на північ і поговоріть з одним із їхніх солдатів.",  -- db:4030
[870062625] = "Тоді вам слід вирушити до Оргримара. Північна дорога, що веде з Бритвового пагорба, веде прямо туди. Просто поговоріть з одним із солдатів, які там перебувають, — вони нададуть вам подальші вказівки.",  -- db:4031
[941046342] = "У Оргримарі можна навчитися шити.  Це на півночі.  Можливо, хтось із солдатів Оргримара зможе тобі допомогти.",  -- db:4031
[635845251] = "Що?  Банк знаходиться в Оргримарі.  Щоб туди дістатися, рухайтеся на північ по дорозі, а потім поговоріть з одним із їхніх солдатів.",  -- db:4032
[896003880] = "Так, мені самому треба здати кілька речей. Щоб знайти це місце, рухайся на північ по дорозі до Оргримара, а потім запитай у когось із місцевих солдатів.",  -- db:4032
[74279555] = "Ви знайдете Майстра «Вершника вітру» в Оргримарі. Щоб дістатися туди, рухайтеся на північ по дорозі та попросіть солдата з Оргримара вказати вам подальший шлях.",  -- db:4033
[405883976] = "Хіба ти не бачиш, що я тут зайнятий?  Йди на північ по дорозі до Оргримара і запитай там у когось із солдатів.  Ти не пропустиш це місце.",  -- db:4033
[579118080] = "Мені самому не завадило б випити і трохи відпочити. Ти знайдеш це місце прямо в північно-західному куті Разор-Хілл. Передай від мене привіт трактирнику Гроску.",  -- db:4034
[956790961] = "Це та велика будівля в Разор-Хіллі, яка не є казармою.  Просто поговори з трактирником Гроском, що там усередині.  Зрозумів?",  -- db:4034
[858178739] = "Оскільки казани пробиті, ми тепер можемо ввести в навколишнє середовище протиотруту. Це, так би мовити, дасть «Скорбі» скуштувати її ж власну пігулку!$B$BЗверніться до алхіміка Арбінгтона за інформацією щодо реагентів, необхідних для використання в казанах.  Я буду відповідати за всі інформаційні звіти про те, як у нас загалом йдуть справи з тим, щоб обернути чуму проти Пошесті!",  -- db:4039
[906507856] = "Оскільки казани пробиті, ми тепер можемо ввести в навколишнє середовище протиотруту. Це, так би мовити, дасть «Скорбі» скуштувати її ж ліки!$B$BЗверніться до аптекаря Дітерса за інформацією щодо реагентів, необхідних для використання в казанах.  Я буду відповідати за всі інформаційні звіти про те, як у нас загалом йдуть справи з тим, щоб обернути чуму проти Пошесті!",  -- db:4040
[984641046] = "Вітаю, юний $g Майстре:Господине;. Мене звати Ева Саркхофф, а це мій чоловік, Люсьєн. Приємно познайомитися з вами.",  -- db:4041
[221603441] = "Звичайно, $g, пане/пані;. Колись ми були слугами в домі Барових: у тому місці, яке зараз відоме як «Сколоманс».$B$BI була старшою покоївкою, а Люсьєн — дворецьким пана Барова.$B$BМи працювали на Барових десятиліттями, аж поки...$B$B<Ева плаче.>",  -- db:4042
[767897637] = "О, це просто жахливо, $g сер:пані;. Колись будинок Барових був сповнений життя... сповнений розкоші. Цей маєток був головною резиденцією Барових посеред їхньої величезної імперії.$B$BLюсьєн і я помітили, що з кожним днем Барові ставали дедалі пригніченішими. Зневіреними. Параноя та лють часто охоплювали господаря та пані. Вночі ми чули, як Барови сварилися у своїх покоях. З того, що ми зрозуміли, їхня жадібність, так би мовити, «прорвала греблю».",  -- db:4043
[594902152] = "Ми припускаємо, що задля збереження свого багатства та володінь — навіть після смерті — Барови уклали угоду з могутнім людським магом на ім’я Кел’Тузад.$B$B<Ева здригається.>$B$BЗ цієї угоди й виникла школа некромантії: Місце, яке породило Культ Проклятих і стало їхньою столицею.$B$BЗ кожним тижнем будинок Барових ставав дедалі занедбанішим...$B$BTемні істоти почали оселятися в різних крилах будинку. Утримувати його стало неможливо... і огидно.",  -- db:4044
[759438676] = "І куди ж іти? Це було все, що ми знали; все, що ми знали раніше, і все, що ми коли-небудь дізнаємося.$B$BЗрештою ми втратили зв’язок із Баровами й, врешті-решт, опинилися відокремленими від решти прислуги. Ми не знали, що сталося з іншими слугами, лише те, що лунали крики. Крики мук.$B$BРозуміючи, що нам нікуди йти, Люсьєн і я були змушені ховатися у своїх кімнатах. Вдень, коли в школі було відносно тихо, Люсьєн викрадався, щоб роздобути їжу та питво.",  -- db:4045
[648861659] = "Ми так протрималися близько шести місяців і спостерігали, як будинок зазнавав жахливих змін. Огидні монстри вільно бродили по маєтку. Темні культисти заповнили кожен дюйм різноманітними атрибутами, пов’язаними з ритуалами та жертвоприношеннями. Ми знали, що не зможемо ховатися ще довго.$B$BЯк і слід було очікувати, нас знайшли й захопили. Вони позбавили нас усього одягу й виклали всередині кола з крові. Ми сиділи там цілими днями, голі й налякані.",  -- db:4046
[88839691] = "Обмеження? У цьому світі є речі, набагато суворіші за ґрати та кайдани, юний $g господар:господиня;. Нежить оточила нас, безперервно мучаючи жахливими актами розпусти.$B$BНарешті він з’явився. Він представився як доктор Теолен Крастінов. Ми стали знати його як «Різника».",  -- db:4047
[981421400] = "Ми нарешті зрозуміли, звідки долинали ті крики. М’ясник піддав нас болю, про існування якого ми навіть не підозрювали. Він використовував нас у незліченних експериментах, намагаючись створити чуму.$B$BДні перетворилися на тижні. Ми б загинули вже першого дня, якби не те жорстоке чудовисько, яке підтримувало нас живими за допомогою магії.",  -- db:4048
[445490375] = "«М'ясник» говорив про «кров невинних» і про свого темного господаря, «Кіртоноса». Про те, як він мусить задобрити свого господаря.$B$BНарешті, чудовисько закінчило свої експерименти. З нас висмоктали все життя. Наші душі були розбиті. На нас опустилися ласкаві обійми смерті, і ми зустріли їх з розпростертими обіймами. Але у своїй безмежній жорстокості М’ясник повернув нас до життя з порогу смерті.$B$BНас мали тримати живими й кидати на поталу його ненаситним гулям. Він сміявся, спостерігаючи, як ці нечисті пожирають наше тіло.",  -- db:4049
[960280528] = "Ми нічого не відчуваємо. Наші душі залишаються тут, у підвішеному стані. Ми не можемо піти, доки не знайдуть наші останки і не поховають наші душі.",  -- db:4050
[580823810] = "Ах, щоб відвідати одне з таких місць, тобі доведеться піднятися на великі висоти Громового Уступу.  Йди стежкою на північ від селища Кровавий Копит.  Біля підніжжя уступу знаходиться ліфт, який доправить тебе на вершину.  Коли ти туди дістанешся, попроси в одного зі «Спостерігачів за Уступом» подальші вказівки.",  -- db:4051
[301364096] = "У нашому селі такого місця немає.  Але воно є на високих скелях Грім-Скелі.  Рушайте на північ по дорозі, що веде з села Кровавий Копит, аж до підніжжя скель.  Там підніміться ліфтом нагору й поговоріть із Вартовим Скелі.  Нехай ваші предки оберігають вас.",  -- db:4051
[76478665] = "У великому місті Грім-Блафф, що на півночі, знаходиться Майстер «Вершників вітру». Підніміться на ліфті від підніжжя Грім-Блаффа до вершини та зверніться до одного з «Стражів Блаффа», щоб отримати подальші вказівки.",  -- db:4052
[132600869] = "Ніщо так не звільняє дух, як політ у небі. У нашому величному племінному центрі «Громовий Утвір» є саме таке місце. До нього веде дорога на північ від селища «Кривавий Копит». Піднявшись ліфтом нагору, поговоріть з одним із «Стражів Утвору» — він надасть вам подальші вказівки.",  -- db:4052
[929589067] = "Готельєр Каут готовий допомогти вам. Його можна знайти на західній стороні села в одному з довгих будинків.",  -- db:4053
[703072070] = "Усе має свій час і місце, в тому числі й відпочинок. На західній околиці селища Бладхуф трактирник Каут утримує довгий будинок для тих, хто прагне відпочити. Саме там ви його й знайдете.",  -- db:4053
[599028746] = "Вам потрібна порада Геннії Рунетотем. Ви знайдете її у великому наметі на східній стороні села.",  -- db:4054
[842619943] = "Шлях друїда тісно пов’язаний із шляхом шамана. Геннія Рунетотем досконало володіє цими знаннями. Знайдіть її у великому наметі на східній стороні селища Кровавий Копит.",  -- db:4054
[489404010] = "Яу Шарпмейн чекає на вас на північному краю села. Він може навчити вас мистецтву мисливця.",  -- db:4055
[933581867] = "Навчитися бути єдиним цілим із Природою в очах Матері-Землі — це справжня гордість. Якщо ти бажаєш опанувати мистецтво мисливця, тобі слід знайти Ява Шарпмейна на північному краю селища Бладхуф.",  -- db:4055
[570032075] = "На східній стороні селища Бладхуф стоїть великий намет. Там на вас чекатиме Нарм Скайчейзер.",  -- db:4056
[246573082] = "У селі живе мудрець на ім’я Нарм Скайчейзер. Він може допомогти тобі продовжити навчання на шляху шамана.",  -- db:4056
[821115339] = "Кранг Стоунхуф стоїть, розставивши ноги, у своєму тренувальному колі в південно-східному куті села.",  -- db:4057
[136127505] = "Якщо ти прагнеш стати Воїном, тобі слід знайти Кранга Стоунхуфа. Ти знайдеш його в південно-східному куті села на його тренувальному майданчику, де він часто навчає своїх учнів.",  -- db:4057
[928912391] = "Хоча у селі Бладхуф немає тренера з алхімії, один є у Грім-Блаффі, що на півночі.  Йдіть туди дорогою, а коли дійдете до вершини, запитайте в одного зі «Стражів Блаффа», як туди дістатися.",  -- db:4058
[586057550] = "Використання дарів Матері-Землі для створення зілля, яке допоможе нам у нашій вічній боротьбі, — це почесна справа. Щоб дізнатися про це, вам слід вирушити на північ, до нашої величної батьківщини — Громового Утвісу. Коли ви дістанетеся вершини, зверніться за допомогою до одного зі «Стражів Утвісу», щоб отримати більш детальні вказівки.",  -- db:4058
[974671523] = "У нашому чудовому рідному місті Грім-Блаф, що на півночі, є інструктор з ковальства. Якщо ви прагнете здобути ці знання, вирушайте туди й попросіть одного з «Блаф-вартових» вказати вам дорогу.",  -- db:4059
[506207326] = "Ти прагнеш перетворити кістки Матері-Землі на знаряддя, які допоможуть Орді.  Добре, добре.  Йди на північ від селища Кровавий Копит, доки не дійдеш до ліфта, що веде на вершину Громового Утвору.  Тамтешній Страж Утвору зможе надати тобі подальшу допомогу.",  -- db:4059
[800363809] = "Ви знайдете Пайала Сайлентстрайда у великому наметі в північно-західному куті села. Він може навчити вас того, чого ви так прагнете.",  -- db:4060
[568941763] = "У мене аж слинка тече, коли я про це думаю.  Пайал Сайлентстрайд — найкращий кухар у селі Бладхуф.  Ви знайдете його у великому наметі в північно-західному куті села.",  -- db:4060
[169573044] = "Тоді, друже, твоя подорож приведе тебе на північ, до Громового Утвору.  Опинившись там, звернися за порадою до одного зі «Спостерігачів за Утвором» — він зможе точно підказати тобі, де знайти того, кого ти шукаєш.",  -- db:4061
[255894550] = "Ця мудрість оповита таємницею, яку можна розгадати лише у величному Громовому Утворі.  Йдіть стежкою на північ від селища Кровавий Копит, доки не дійдете до ліфта біля підніжжя скель.  Підніміться нагору та попросіть одного зі «Стражів Утвору» про допомогу.",  -- db:4061
[743999765] = "Віра Янгхуф веде свою практику в довгому будинку, що розташований у західній частині села.",  -- db:4062
[287969452] = "Бинти, протиотрути та інші подібні речі — це те, без чого не обійтися, живучи на рівнинах. Віра Янгхуф може поділитися з вами цими знаннями. Ви знайдете її у довгому будинку на західній стороні селища Бладхуф.",  -- db:4062
[301593275] = "Ви шукаєте Утана Стілвотера. Ви знайдете його на захід від села — він ловить рибу на озері Стоунбулл.",  -- db:4063
[449582400] = "Дай бику рибу — і він буде ситий один день.  Навчи бика ловити рибу — і він буде ситий все життя.  Утан Стілвотер може навчити тебе ловити рибу.  Звернися до нього за порадою на захід від селища Бладхуф, на березі озера Стоунбулл.",  -- db:4063
[118360218] = "Якщо ви бажаєте опанувати мистецтво траволікування, то вам слід вирушити до Грім-Скелі.  Йдіть дорогою на північ від селища Кровава Копита і підніміться на ліфті на вершину пагорба.  Там ви можете звернутися до сторожа Грім-Скелі за додатковою допомогою.",  -- db:4064
[703378546] = "У великому поселенні Грім-Скеля, що розташоване далеко на півночі, є люди, які навчать вас травознавству. Щоб дістатися туди, йдіть дорогою, що веде з села, а біля підніжжя скелі підніміться ліфтом на вершину пагорба. Там ви знайдете багатьох «Спостерігачів за скелею», які зможуть вказати вам подальший шлях.",  -- db:4064
[228006972] = "У великому наметі, що стоїть у північно-західному куті села, мешкає Чау Стронгхайд. Він навчить вас усьому, що вам наразі потрібно знати про шкіряне ремесло.",  -- db:4065
[671242241] = "Коли ми використовуємо шкури тварин, яких ми вбиваємо заради їжі чи захисту, ми віддаємо шану Матері-Землі та виявляємо повагу до тварини. Чау Стронгхайд може навчити вас цьому. Ви знайдете його у великому наметі в північно-західному куті селища Бладхуф.",  -- db:4065
[760648086] = "Хм, думаю, щоб це дізнатися, тобі доведеться піднятися до Громового Утвісу. Рушай на північ по дорозі, що веде з селища Кровавий Копит. Вона приведе тебе до підніжжя Громового Утвісу. Піднімися на ліфті нагору, і там ти зможеш звернутися за допомогою до будь-якого із «Стражів Утвісу».",  -- db:4066
[489778389] = "Я чув, що на півночі, у Грім-Блаффі, є інструктор з гірничої справи.  Вийдіть з села по дорозі, а коли дійдете туди, підніміться на ліфті на вершину пагорба.  Звідти вам повинен допомогти будь-який із «Спостерігачів за Блаффом».",  -- db:4066
[163620232] = "Йонн Діпкат знаходиться у великому наметі в північно-західному куті селища Бладхуф.",  -- db:4067
[421146966] = "Ах так, зняття шкур. Ніхто не володіє ножем для зняття шкур краще, ніж Йонн Діпкат. Його можна знайти у великому наметі в північно-західному куті села.",  -- db:4067
[843651334] = "На жаль, у селі Бладхуф немає нікого, хто б навчав кравецькій справі, але ви можете знайти інструктора в Тандер-Блаффі.  Йдіть стежкою на північ від села, доки не дійдете до ліфтів.  Підніміться на один із них на вершину пагорба і попросіть одного з «Блаф-вартових», що там перебувають, вказати вам шлях.",  -- db:4068
[591019430] = "«Пошиття», кажеш?  Хм.  А, так, звичайно.  Тобі потрібно вирушити до Громового Уступу, що на півночі.  Щоб дістатися туди, йди стежкою, що веде з села.  Коли дійдеш до підніжжя уступу, піднімися ліфтом на вершину пагорба й поговори з одним із Сторожів Уступу.",  -- db:4068
[515768242] = "У Бріллі немає банку, тож для цього вам доведеться поїхати до Підміста.  У південній частині Руїн Лордаерона знаходяться ліфти, які доставлять вас у Підмісто.  Опинившись там, попросіть одного з охоронців Підміста надати вам більш точні вказівки.",  -- db:4074
[975531985] = "Навіщо вам взагалі потрібен банк?  Гаразд, вам доведеться пройти через Руїни Лордаерона на південь від Брілла.  У глибині руїн є ліфти, що ведуть вниз, до Підмістя.  Коли дійдете туди, зупиніть будь-яку з тих неповоротких Потвор, яких вони називають «Стражами Підмістя», і попросіть її вказати точніший шлях.",  -- db:4074
[173642992] = "У Підмісті є тренер кажанів. Рухайтеся на південь по дорозі, що веде з Брілла, а потім на захід на Т-подібному перехресті. Руїни Лордаерона будуть ліворуч від вас. Зайдіть туди, а потім спуститься в Підмісто. Там ви можете звернутися до охоронця Підмістя за додатковою допомогою.",  -- db:4075
[286317382] = "Хочете кудись полетіти?  Для цього вам доведеться вирушити до Підміста!  Йдіть на південь по дорозі, що веде з міста, а потім на південний захід до Руїн Лордаерона.  З тильного боку руїн ви зможете спуститися на ліфті до Підміста, а коли опинитеся там, попросіть охоронця Підміста надати вам більш детальні вказівки.",  -- db:4075
[779385937] = "Ви знайдете власницю таверни Рене всередині таверни «Кінець шибениці», що розташована на південно-східному кінці вулиці, яка проходить через місто.",  -- db:4076
[231284185] = "Отже, якби я була власницею таверни Рене, де б я могла бути?  Хм?  О, мабуть, у таверні «Кінець шибениці».  Так, саме так, я в цьому впевнена.  Спробуй пошукати на південно-східній околиці Брілла... гадаєш, зможеш це знайти?",  -- db:4076
[81369859] = "Ви знайдете інструктора магів, Кейна Файерсонга, нагорі, на сходовому майданчику таверни «Кінець шибениці», що розташована на південно-східній околиці Брілла.  Мабуть, він завітав занадто пізно, щоб забронювати номер.",  -- db:4077
[372824722] = "Тобі здається, що я займаюся магією?  Ну, я справді чула, що Кейн Файерсонг тусувався на сходовій площадці нагорі в таверні «Кінець шибениці» на південно-східній околиці міста.  Дивно, як він просто так стоїть там, біля кімнати Гретхен.",  -- db:4077
[873882959] = "На південно-східній околиці міста розташована таверна «Кінець шибениці». Зайдіть туди та підніміться нагору — у читальному залі ви знайдете Темного клірика Берила.",  -- db:4078
[436885161] = "А, ти шукаєш Темного жреця Берила. Він нагорі, у читальному залі таверни «Кінець шибениці». Читає, молиться — хто знає, що він там витворяє, та й хто наважиться запитати?",  -- db:4078
[436048374] = "Ім'я тренера-розбійника — Маріон Колл.  Її можна знайти нагорі, у читальному залі таверни «Кінець шибениці», що на південно-східній околиці міста.",  -- db:4079
[618314972] = "Маріон Колл складає компанію Темному клірику Берилу в читальному залі на другому поверсі таверни «Кінець шибениці», що на південно-східній околиці Брілла.  Мені просто не терпиться дізнатися, хто виграє це змагання з поглядів.",  -- db:4079
[670346966] = "Його звати Руперт Бох.  Я чув, що він перебуває нагорі, в одній із кімнат таверни «Кінець шибениці», що розташована на південно-східній околиці міста.",  -- db:4080
[322646935] = "Це Руперт Бох — саме його ви шукаєте. Він зі своєю свитою зупинився нагорі в таверні «Галлоуз-Енд», що на південно-східній околиці Брілла.",  -- db:4080
[982080101] = "Загляньте до головної зали таверни «Кінець шибениці» — там ви знайдете Остіла де Мона.  Таверна розташована на південно-східній околиці Брілла.",  -- db:4081
[721607311] = "Так, це, мабуть, Остіл де Мон. Він завжди сидить у таверні на південно-східній околиці міста. Вона називається «Таверна „Кінець шибениці“», її неможливо не помітити.",  -- db:4081
[250006408] = "Нашу алхімічку звати Каролай Аніс. Ви знайдете її в будинку на північно-західній околиці Брілла.",  -- db:4082
[177976549] = "У північно-західній частині міста ти знайдеш Каролай Аніс, яка намагається підірвати свій будинок.  Чому б тобі не підійти до неї й не спробувати їй допомогти?",  -- db:4082
[625529549] = "Вибач, друже, у нас у Бріллі такого немає.  Для цього тобі доведеться вирушити до Підміста.  Підмісто розташоване під Руїнами Лордаерона, на південь від Брілла.  З тильного боку руїн спустися ліфтом вниз, а потім поговори з одним із Стражів Підміста, щоб дізнатися, як пройти далі.",  -- db:4083
[199255812] = "Коваль?  Ні, наш останній знову перетворився на одного з тих бездумних представників Плеті.  Хоча в Андерсіті, на південь від міста, є ще один.  Підмісто розташоване під Руїнами Лордаерона — влучна назва, еге ж?  Просто спустися на ліфтах, що знаходяться в глибині руїн, і тоді зможеш поговорити з одним із Стражів Підміста.  Вони повинні вказати тобі правильний напрямок.",  -- db:4083
[696748664] = "Мрієте стати шеф-кухарем?  Тоді вирушайте до Підмістя, що на південь від міста, щоб пройти навчання.  Спуститися туди можна на ліфтах, які знаходяться в глибині Руїн Лордаерона.  Після прибуття зверніться до одного з тих неповоротких Стражників Підмістя, щоб отримати подальшу допомогу.",  -- db:4084
[760213922] = "Навіщо готувати, якщо все в роті має смак попелу?  Звісно, якщо у вас взагалі є дистилятор.  Гаразд, вирушайте до Підміста на південь від Брілла і попросіть тамтешнього Стража Підміста вказати вам шлях до їхнього інструктора з кулінарії.  Щоб туди дістатися, можна спуститися на ліфтах з тильного боку Руїн Лордаерона.",  -- db:4084
[551242652] = "Ви можете знайти Венса Андерглума нагорі, у кімнаті таверни «Кінець шибениці», що розташована в південно-східній частині міста Брілл.",  -- db:4085
[515053515] = "Кажуть, що Венс Андерглум зняв постійну кімнату нагорі в таверні «Кінець шибениці», що на південно-східній околиці міста.  Гадаю, вона знаходиться прямо біля читального залу.",  -- db:4085
[730650689] = "Хоча в Бріллі немає інструктора з інженерії, один є в Підмісті. Щоб туди дістатися, вирушайте до задньої частини Руїн Лордаерона, що на південь від міста, і спуститься ліфтом вниз. Коли ви туди дістанетеся, попросіть охоронця Підмістя надати більш детальні вказівки.",  -- db:4086
[882888298] = "Гвинтівки, динаміт, бомби, вибухові вівці… Чого тут не любити? Щоб дізнатися, як виготовляти ці та багато інших захопливих інструментів ремесла, вирушайте до Підміста, що розташоване під Руїнами Лордаерона на південь від Брілла.  Спустіться на ліфтах, що знаходяться в глибині руїн.  Прибувши на місце, поговоріть з одним із Стражників Підміста, щоб дізнатися, де саме знаходиться інструктор.",  -- db:4086
[258290160] = "Медсестра Ніла вітає всіх своїх майбутніх клієнтів, коли ті заходять до таверни «Кінець шибениці», що розташована на південно-східній околиці міста.",  -- db:4087
[484927430] = "«М'ясник», кажеш?  А, інструктор з першої допомоги!  Це одне й те саме.  Коли побачиш медсестру Нілу, що стоїть біля входу в таверну «Кінець шибениці» на південно-східній околиці міста, ти зрозумієш, чому.",  -- db:4087
[685003827] = "Клайд Келен, місцевий майстер риболовлі на окуня, має своє улюблене місце для риболовлі трохи на схід від Брілла, на озері Брайтвотер.",  -- db:4088
[919686145] = "Так, Клайда Келлена завжди можна зустріти за риболовлею на березі озера Брайтвотер, що на схід від Брілла.  Тільки будьте обережні — там можуть з’являтися психи в масках.  Минулого року нам довелося закрити дитячий літній табір.",  -- db:4088
[862450603] = "Пошукай Фарузу. Востаннє я бачив її біля входу, між стайнями та будинком, у північно-західній частині містечка.",  -- db:4089
[651778591] = "Взагалі-то я віддаю перевагу традиційним лікам... п’явкам, личинкам, кісткорізам... і тому подібному. Ну, кожному своє. Нашу місцеву інструкторку з фітотерапії, Фарузу, можна знайти біля стайні в Бріллі.",  -- db:4089
[447067439] = "Це Шелін Роберт.  Виїжджайте з Брілла по дорозі на південний схід, а на перехресті поверніть на схід.  Вона перебуває в таборі біля дороги.",  -- db:4090
[830676151] = "Ніщо не зрівняється з відчуттям, коли до тебе торкається щось мертве.  Щоб знайти Шелен Роберт, рухайся на південний схід по дорозі, що веде з міста, а на перехресті поверни на схід.  Вона перебуває у невеликому таборі, що розташований неподалік від дороги.",  -- db:4090
[158518199] = "Я чув, що в Підмісті є інструктор з гірничої справи. Щоб туди дістатися, потрібно просто вийти з міста на південь і пройти до задньої частини Руїн Лордаерона. Потім спуститися на ліфті в саме Підмістя і запитати у Стража Підмістя, як пройти далі.",  -- db:4091
[405801014] = "Гадаю, твоє перше завдання полягатиме в тому, щоб прокопати собі шлях до Підміста.  Хе, зрозумів?  «Прокопати»… ну, неважливо.  Щоб дістатися до Підміста, йдіть у тил Руїн Лордаерона на південь від Брілла й спуститеся ліфтом вниз.  Зверніться до одного з тамтешніх Стражів Підміста за подальшою допомогою.",  -- db:4091
[158317552] = "Ренд Роберт досить добре справляється зі зняттям шкур з фелбатів та інших подібних істот. Його можна знайти в таборі, що розташований вздовж дороги на південний схід від Брілла. Вийдіть з міста на дорогу, що веде на південний схід, а на перехресті поверніть на схід.",  -- db:4092
[208917407] = "Ти мрієш стати таксидермістом?  Мені не подобаються люди, які думають, що можуть мене вичистити й виставити на огляд, бо вважають, що я мертвий.  Ні?  Добре!  Шукай Ренда Роберта в таборі на південний схід від міста.  Щоб дістатися до нього, вирушай дорогою на південний схід від Брілла й на перехресті поверни ліворуч.",  -- db:4092
[38012493] = "Тож ви шукаєте Боуена Брісбуаза. Ви знайдете його в його будинку на південний захід від Брілла, одразу за мостом, у маєтку «Колд-Херт».",  -- db:4093
[630349061] = "Чорний, сірий і темно-фіолетовий — ось визначені кольори.  Подбай про те, щоб не збитися з модного шляху, друже.  Боуен Брісбуа допоможе тобі цього уникнути.  Ти знайдеш його в маєтку «Холодне Вогнище», що розташований по той бік мосту на південному заході від міста.",  -- db:4093
[155324837] = "Ти вже зробив мені велику послугу, $N. За це я тобі вдячний.$B$BНайменше, що я можу зробити зараз, — це розповісти тобі, що привело мене сюди: мій давній друг Трей Лайтфордж і я прибули до Джеденара, щоб розслідувати діяльність Ради Тіней, коли вони застали нас зненацька. Вони відвели Трея глибше в Тіньову Твердиню, а мене зачинили тут, забравши все наше спорядження... Я досі чую його крики знизу, $N. Вони були... нелюдськими. Я не знаю, що вони з ним зробили, але вони за це заплатять.",  -- db:4113
[663706623] = "Оглядаючи клітку та нічну ельфійку, що сидить у ній, ти відчуваєш дивне відчуття дежавю. З якоїсь причини вона не дивиться тобі в очі — ніби тебе для неї взагалі немає.",  -- db:4114
[235969744] = "Вони не усвідомлюють, що вже мертві, $r. Вони приречені знову й знову переживати останній спогад, який у них залишився перед тим, як місто було з’їдене живцем зсередини. Принаймні, більшість із них. Декому пощастило менше.$B$BВи думали, що це справа рук Плеті? «Скорб» тоді ще не існувала, а якби й існувала, ми б принаймні дали їй проклятий відсіч.$B$BНі, це був наслідок чуми, що вирвалася зі «Сколоманса» й спустошила місто. Це було жахливо й руйнівно. Ніхто не вижив.$B$BА тепер залиш мене наодинці з моїм горем.",  -- db:4117
[863265409] = "Хіба ти не бачиш, що ми намагаємося підготуватися до візиту Утера? А тепер забирайся з дороги, у мене багато роботи!",  -- db:4118
[483093537] = "Ви вже пробували наш хліб? Пекар Мастерсон, мабуть, найталановитіший кухар у світі!",  -- db:4118
[418805926] = "Ласкаво просимо до Каер-Дарроу, незнайомцю.",  -- db:4118
[60584293] = "Ми насправді не грубі люди, незнайомцю, просто всі поспішають, намагаючись подбати про те, щоб до приїзду Утера все було ідеально. Адже Несучий Світло не так часто завітає до міста.",  -- db:4118
[636068408] = "Ще один чудовий день на нашому прекрасному острові.",  -- db:4118
[998290793] = "Дивись під ноги, незнайомцю. У нашому місті не терпимо негідників.",  -- db:4119
[837615502] = "Я стежу за тобою, $r.",  -- db:4119
[635637100] = "У мене накопичилося багато гніву й ворожості. Просто дай мені привід, вуличний шмаркач.",  -- db:4119
[59065026] = "Та ти ж виглядаєш як звичайний вуличний хлопчисько!",  -- db:4119
[567830712] = "У Каер-Дарроу заборонено безцільно тинятися, жебракувати, лаятися, битися та робити будь-що інше, що вам спаде на думку.",  -- db:4119
[855086092] = "Культ Проклятих значно розширив свої межі. Майже в кожному місті — від столиць до невеликих селищ і халуп як Орди, так і Альянсу — серед мешканців переховуються члени Культу.$B$BНе дивіться так здивовано. Члени Культу носять уніформу лише під час ритуалів та церемоній. Цілком можливо, що ви вже стикалися з кимось із них під час своїх пригод і навіть не здогадувалися про це.",  -- db:4122
[6330918] = "Невже? Це завжди був їхній спосіб дії. Що має більшу цінність для Кел’Тузада та армії Плітки, що постійно зростає? Запальний, живий послідовник, здатний проникнути в суспільство, а потім розпалити епідемію, знищивши тисячі людей; чи один-єдиний неживий солдат? Звісно, ти ж не настільки тупий$B$BТак, $r, вони живуть, працюють і плетуть інтриги серед вас.",  -- db:4123
[24424315] = "Зупинитися — ні. Зменшити темп — можливо.$B$B«Шоломанс» — це їхнє головне місце підготовки та навчання. Саме звідти члени Культу розходяться в різні боки і, зрештою, проникають у наше суспільство.$B$BОсь чому ми мусимо завдати удару по самому джерелу — у саме серце Культу Проклятих!",  -- db:4124
[685817267] = "Заспокойся, $r. Той, кого тобі треба вбити, вже мертвий. Вбивати його ще раз не має сенсу. Існує дуже мало способів, якими ліча можна насправді знищити, і жоден із них не доступний ані тобі, ані мені. Ось чому у мене є план. План, який матиме дуже помітний і реальний вплив на Культ.",  -- db:4125
[976409580] = "Насправді все дуже просто. Позбавити ліча Раса Фроствіспера його сил. Повернути йому людську подобу, а потім знищити його раз і назавжди.",  -- db:4126
[169609710] = "Ах, мабуть, я трохи забігаю наперед. Рас Фроствіспер — наглядач цієї школи. Істота, відповідальна за підготовку всіх її Темних Майстрів. Це лейтенант і улюблений учень Кел'Тузада. Колись він був магом-аматором зі Стромгарда: бродячим чарівником, який ніколи не проходив офіційного навчання в Даларані.$B$BКоли Кел'Тузад заснував Культ, Рас одним із перших приєднався до його лав. Рас знав, що завдяки темній магії він знайде безсмертя.",  -- db:4127
[450593462] = "І він її знайшов. Швидко піднявшись по службових сходах Культу, сам Король Ліч надав Расу безсмертя. Так з’явився на світ Рас Фроствіспер, ліч.$B$BТепер ти розумієш?",  -- db:4128
[786486639] = "Добре. Щоб реалізувати мій план, нам спочатку треба створити камінь життя. Ти готовий діяти?",  -- db:4129
[187715083] = "Декому вдалося уникнути мук, які приносять спогади.",  -- db:4130
[758917728] = "Будинок Барових, безперечно, не дає мені занудьгувати. Звідти постійно виносить якесь сміття.",  -- db:4133
[58859930] = "Моя посада — фахівець з управління відходами.",  -- db:4133
[951954760] = "Можливо, вам варто поговорити в ці пристрої для посилення звуку, прикріплені до моїх «Кулаків гніву».",  -- db:4133
[580803290] = "Ах, моя люба Бренді, як же я за нею сумую!",  -- db:4133
[518250932] = "Радий бачити тебе, друже.  Я — офіцер Гаруш, і я пишаюся тим, що є членом всесвітньої організації під назвою «Срібний Світанок».  Наша мета — швидко й безжально боротися з будь-яким злом, що з’являється в Азероті.  Ми не є політичною організацією і ніколи не прагнемо нею стати.  Наша мета єдина, і заради неї ми вважаємо і Орду, і Альянс своїми друзями — друзями у справі знищення зла!$B$BЗа «Світанок», мій $g брате : сестро;!",  -- db:4134
[520870995] = "Радий бачити тебе, друже.  Я — офіцер Пюрхарт, і я пишаюся тим, що є членом всесвітньої організації під назвою «Срібний Світанок».  Наша мета проста — швидко й безжально боротися проти будь-якого зла, що з’являється в Азероті.  Ми не є політичною організацією і ніколи не прагнемо нею стати.  Саме тому ми вважаємо і Альянс, і Орду своїми друзями — друзями у справі знищення зла!$B$BЗа «Світанок», мій $g брате : сестро;!",  -- db:4135
[492161782] = "«Срібний Світанок» вітає тебе, $c.  Я — Хасана — одна з небагатьох уповноважених інтендантів «Світанка», відповідальних за спорядження та матеріали.$B$BБоротьба зі злом під нашим керівництвом — за умови, що ти заслуговуватимеш на нашу повагу та довіру — дозволить тобі отримувати жетони доблесті від офіцера Гаруша.  Жетони мають два призначення: використовуйте їх для підвищення свого статусу в наших лавах або як платіжний засіб для придбання спеціальних предметів.$B$BУ міру підвищення вашого статусу в «Світанку» ви виявите, що вам стануть доступні нові предмети.",  -- db:4173
[221157665] = "Приєднуйтесь до боротьби зі злом!  Вже сьогодні прийміть завдання від «Срібного Світанку»!",  -- db:4174
[27851389] = "«Срібний Світанок» вітає тебе, $c!  Мене звати Лайтспарк, і я є уповноваженим інтендантом з питань спорядження та матеріальних засобів «Світанка».$B$BБоротьба зі злом під нашим керівництвом — під час якої ти завоюєш нашу повагу та довіру — дозволить тобі отримувати жетони доблесті від офіцера Пюрхарта.  Жетони мають два призначення: використовуйте їх для підвищення свого статусу в наших лавах або як платіжний засіб для придбання спеціальних предметів.$B$BУ міру підвищення вашого статусу в «Світанку» ви виявите, що вам стануть доступні нові предмети.",  -- db:4193
[595310768] = "Вітаю, $c.  Я — Міранда Брічлок — одна з небагатьох уповноважених інтендантів з питань обладнання та матеріальних засобів у «Світанку».$B$BБоротьба зі злом у складі нашої організації — завоювання нашої поваги та довіри — дозволить вам отримувати жетони доблесті від герцога Звереноффа.  Жетони мають два призначення: використовуйте їх для підвищення свого статусу в наших лавах або як платіжний засіб для придбання спеціальних предметів.$B$BУ міру підвищення вашого статусу в «Світанку» ви виявите, що вам стануть доступні нові предмети.",  -- db:4213
[322046426] = "Вітаю, $c.$B$BТі вартові, що там, дозволили мені залишитися в їхньому таборі за умови, що я пообіцяю не створювати проблем — я впевнений, що ви розумієте необхідність дотримуватися дипломатичності, перебуваючи тут, чи не так?$B$BЯ перебуваю тут, щоб розслідувати порушення спокою на цій землі, і оскільки це також сприяє їхній справі, вони погодилися, що моя присутність тут лише зміцнить крихкий союз між усіма расами Азерота. Якщо ви бажаєте допомогти мені, я буду вдячний, але в будь-якому разі, будь ласка, намагайтеся не створювати жодних проблем.",  -- db:4233
[746784679] = "Ласкаво просимо до «Steelgrill's Depot»!",  -- db:4253
[90317320] = "Раса не визначає честь, $r. Поки ви перебуваєте на моїй фермі, прошу вас пам’ятати про це кредо і дотримуватися його.$B$BЯ знав орків, які були такими ж чесними, як найблагородніші лицарі, і людей, які були такими ж підлими, як найжорстокіші представники «Покарання».$B$BАле я не буду набридати вам розповідями про свою молодість! Попереду багато роботи — якщо, звичайно, ви цього бажаєте.",  -- db:4254
[758722302] = "Банк?  Ну, найближчий банк у цих краях — це «Штормовійська казна».  Він розташований трохи далі по дорозі у Штормовії, неподалік від воріт.",  -- db:4260
[641045198] = "А, ти, мабуть, маєш на увазі «Будинок розрахунків» у Штормовії. Він розташований неподалік від воріт, одразу після в’їзду до Штормовію.",  -- db:4260
[440803402] = "Ну, у Штормовій є майстер грифонів, якщо тобі знадобиться кудись полетіти. Ти повинен побачити, як грифони приземляються праворуч від тебе, коли йтимеш через Долину Героїв.",  -- db:4261
[534343575] = "Майстер грифонів керує польотами грифонів у самому Штормовій. Якщо ви хочете прокотитися на грифоні, то саме туди вам і слід прямувати.",  -- db:4261
[698941165] = "Я вважаю, що Олдвін Лафлін досі є майстром гільдії Штормовію.  Шукайте його резиденцію ліворуч, коли ви пройдете через внутрішні ворота Штормовію.",  -- db:4262
[393378739] = "Зараз усі офіційні справи вирішуються у Штормовії. Якщо ви хочете заснувати гільдію, можете завітати до Центру для відвідувачів у Штормовії.",  -- db:4262
[596019679] = "Не шукайте далі — завітайте до готелю «Lion's Pride Inn» у Голдширі. Завдяки широкому вибору елів та м'яких ліжок ви не знайдете кращого місця для відпочинку.",  -- db:4263
[70323601] = "Готель «Гордість Лева» у Голдширі нічим не поступається іншим готелям у цих краях. Завітайте сюди, і господар Фарлі подбає про те, щоб ви почувалися як вдома.",  -- db:4263
[784007943] = "В Елвінні є чимало тренерів.  Якого саме ви шукаєте?",  -- db:4264
[754656090] = "Друїди?  Я тут ніяких друїдів не бачив.  Хоча у Штормовії є район, який нічні ельфи перетворили на своє власне гніздо.",  -- db:4265
[874235469] = "Я чув, що у Штормовій живе гном, який здобув певну славу завдяки своїм мисливським здібностям.  Може, тобі варто піти до нього й дізнатися, чи не зможе він тобі допомогти.",  -- db:4266
[333741630] = "Джосетта стала справжнім благословенням для цього міста, допомагаючи місцевим охоронцям. Якщо ви хочете звернутися до неї, щоб навчитися ремеслу священика, ви знайдете її в корчмі «Левова гордість».",  -- db:4267
[267081389] = "Готовий побитися об заклад, що Джосетта з радістю навчить тебе кільком новим заклинанням. Вона, мабуть, зараз у своїй кімнаті в готелі «Лев’яча гордість».",  -- db:4267
[59326798] = "Залдімар, мабуть, міг би навчити тебе кількох нових заклинань. Останнім часом він полюбив зупинятися в готелі «Лев’яча гордість», тож, можливо, тобі варто зазирнути в одну з кімнат і перевірити, чи він там.",  -- db:4268
[842360193] = "Я не дуже розбираюся в магії, але в готелі «Гордість Лева» зупинився маг на ім’я Залдімар, який, мабуть, міг би тобі допомогти.",  -- db:4268
[746107919] = "Зазвичай брата Вільгельма можна зустріти в глибині кузні, де він обмінюється історіями з Лірією. Він завжди готовий навчити інших паладинів новим навичкам.",  -- db:4269
[832187182] = "Брат Вільгельм часто тренується з Лірією Дю Лак за кузнею в Голдширі.  Можливо, ви зможете навчитися у нього дечому про те, як бути паладином.",  -- db:4269
[715235331] = "Розбійник?  Хм... Ну, я чув, що Керін Сильвіус тусується з цими сумнівними типами.  Може, тобі варто з нею поговорити й дізнатися, що вдасться з’ясувати.",  -- db:4270
[286311231] = "Готовий побитися об заклад, що Керін Сильвіус знає, кого ти шукаєш. Керін спілкується з не надто добропорядними людьми. Зазвичай вона проводить час у таверні «Лев’яча гордість».",  -- db:4270
[911431495] = "Мало хто в цих краях так вправно володіє мечем, як Лірія Дю Лак. Заглянь до неї за кузнею й поцікався, чи не має вона бажання навчити тебе чомусь новому.",  -- db:4271
[771304697] = "Якщо тобі потрібне навчання, звернися до Лірії. Зазвичай її можна знайти за кузнею, де вона чекає, поки їй зроблять броню чи зброю.",  -- db:4271
[853365326] = "О... один із таких типів.  Ну, Максиміліан — єдиний тут, хто розбирається в темних мистецтвах.  Його, мабуть, можна знайти в темряві підвалу корчми «Лев’яча гордість».",  -- db:4272
[74230045] = "Чаклун?  Ну, якби я був чаклуном, то, мабуть, перебував би в найтемнішому місці в околицях... а саме — у підвалі корчми «Лев’яча гордість».  Саме там тобі й слід шукати в першу чергу.",  -- db:4272
[898118724] = "Я знаю кількох людей у цих краях, які займаються однією чи двома професіями.  А про яку саме професію ви маєте на увазі?",  -- db:4273
[288708681] = "Відомо, що той відлюдник Маллорі час від часу готує різні зілля для місцевих мешканців. У нього є хатинка на пагорбах між Штормовійом і Нортширом.",  -- db:4274
[451214391] = "У горах між Нортширом і Штормовійом живе алхімік, який, можливо, зможе тобі допомогти. Чому б тобі не завітати до нього?",  -- db:4274
[927283446] = "Аргус — місцевий коваль у Голдширі.  Я впевнений, що він міг би навчити вас ковальській справі.",  -- db:4275
[901208190] = "Мабуть, ви шукаєте Сміта Аргуса. Якщо вам потрібне навчання, він зазвичай керує кузнею в Голдширі.",  -- db:4275
[858070572] = "Томас, можливо, і не найкращий кухар у околиці, але у нього є кілька страв, які справді смакують.  Зараз він працює в готелі «Lion's Pride Inn», тож якщо ви хочете опанувати цю професію, зверніться до нього.",  -- db:4276
[481538029] = "Чому б тобі не зазирнути до корчми «Лев’яча гордість»?  Можливо, тамтешній кухар зможе навчити тебе кількох чудових рецептів.",  -- db:4276
[291701700] = "Ні, не думаю, що тут, у Лісі Елвін, є якісь чарівники.  Хоча у Штормовії є хлопець на ім’я Лукан, який тримає крамницю.  Можеш звернутися до нього й дізнатися, чи не навчить він тебе.",  -- db:4277
[66684581] = "Хм... Наскільки я знаю, у цих краях працюють лише чарівники зі Штормовію.  Чому б тобі не запитати когось із вартових у Штормовії?",  -- db:4277
[842631130] = "Зазвичай я залишаю такі справи гномам. Якщо ти хочеш освоїти цю професію, впевнений, що в Штормовії знайдеш гномів, які зможуть тебе навчити.",  -- db:4278
[742579427] = "У Штормовії напевно знайдеться гном, який зможе навчити вас цій професії. Я впевнений, що хтось із штормвіндських гвардійців зможе вказати вам потрібний напрямок.",  -- db:4278
[95604691] = "Нещодавно я мав неприємну сутичку з декількома членами угруповання «Дефіас» з цих околиць, але Мішель Белль мене чудово підготувала. Звернися до неї в таверні «Гордість Лева» і запитай, чи не навчить вона тебе.",  -- db:4279
[999935593] = "Мішель Белл чудово спілкується з пацієнтами!  Хоча вона, можливо, й не зможе навчити вас цьому, але точно зможе навчити вас надавати першу допомогу.  Зараз вона мешкає в готелі «Lion's Pride Inn».",  -- db:4279
[761575915] = "Лі Браун проводить цілий день, рибалячи біля Кристал-Лейк.  Ймовірно, у нього є чим поділитися та якісь поради, якими він міг би з вами поділитися.",  -- db:4280
[812233833] = "Лі виловив у Кристал-Лейк кілька досить дивних речей. Він розповів мені історію про цю дивну маску, яку виловив кілька місяців тому. Якщо мене запитати, то я думаю, що він просто перебрав того вечора в барі «Lion’s Pride».",  -- db:4280
[434056358] = "Пані Померой збирає трави для алхіміка, який мешкає на пагорбах між Нортширом і Штормовійом. Загляньте до неї в його хатинку й дізнайтеся, чи не навчить вона вас цій професії.",  -- db:4281
[236721421] = "У горах на схід від Штормовію разом із нашим алхіміком живе травник. Досить вдале поєднання, чи не так?",  -- db:4281
[970672791] = "Біля Кришталевого озера живе жінка на ім’я Адель Філдер. Вона виготовляє латки для місцевої охорони з залишків шкіри, які отримує від місцевої шкіряниці Гелен. Якщо ви зацікавлені в освоєнні цієї професії, то, ймовірно, саме до неї варто звернутися.",  -- db:4282
[553395818] = "Адель Філдер здобула популярність як майстриня з обробки шкіри в околицях Елвіна. Її можна знайти за роботою в її будинку біля Кришталевого озера.",  -- db:4282
[892634222] = "Якщо ти хочеш навчитися видобувати корисні копалини, тобі краще вирушити до Штормовію, у район карликів. Напевно, хтось із місцевих карликів зможе навчити тебе цій професії.",  -- db:4283
[679907277] = "Гадаю, у Штормовій у тебе буде більше шансів.  Звернися до охоронця там, і він вкаже тобі правильний напрямок.",  -- db:4283
[874030755] = "Гелен Пелтскіннер має багаторічний досвід зняття шкур з тварин для Адель Філдер з метою виготовлення шкіряних виробів.  Гелен можна знайти в її будинку біля Кристал-Лейк.",  -- db:4284
[39022392] = "Біля Кристал-Лейк живе чудова шкіряниця. Вона обов’язково зможе показати вам, як розпочати кар’єру шкіряника.",  -- db:4284
[741236194] = "Елдрін — єдиний у Лісі Елвін, кого я б назвав кравцем. Якщо ви хочете освоїти цю професію, його можна знайти в лісозаготівельному таборі Іствейл.",  -- db:4285
[22244503] = "Хочеш навчитися кравецькій справі?  Хм... Гадаю, у лісозаготівельному таборі Іствейл є кравець, який, можливо, допоможе тобі зробити перші кроки.",  -- db:4285
[850499727] = "Найближчий банк, який ви знайдете, — це «The Vault» в Айронфорджі, $glad : lass;.",  -- db:4288
[354873870] = "«Сховище» в Айронфорджі — це найближчий банк, який ви зможете знайти в цих краях.",  -- db:4288
[777857945] = "У околицях Дун-Морога ви не знайдете тренера грифонів просто так, $glad : lass;.  Якщо ви хочете кудись полетіти на грифоні, вам доведеться вирушити до Айронфорджа.",  -- db:4289
[541231063] = "Найближчий майстер грифонів знаходиться в Айронфорджі, неподалік від самої Великої Кузні. Якщо ви хочете подорожувати на грифоні, вам доведеться вирушити до Айронфорджа.",  -- db:4289
[196639285] = "Усі ці чиновники мешкають в Айронфорджі. Вам варто завітати до Центру для відвідувачів Айронфорджа, щоб отримати документи для створення гільдії.",  -- db:4290
[254863682] = "Якщо вам потрібно дістати документи для створення гільдії, вам доведеться вирушити до Айронфорджа та завітати до Центру для відвідувачів Айронфорджа.",  -- db:4290
[399522992] = "Сім'я Тандербрю веде чудову корчму в Хараносі, яка носить їхнє ім'я. Загляньте туди, щоб випити пінту пива та трохи перепочити.",  -- db:4291
[323428393] = "Ооо, це ж корчма, так?  Ну, ніщо не зрівняється з винокурнею «Thunderbrew».  Відпочиньте, якщо треба, але обов’язково випийте там елю-другого, поки там будете.",  -- db:4291
[473665426] = "У цих краях є лише один мисливець, з яким я б радив тобі поговорити, — це Гріф Вайлдхарт. Ти знайдеш його біля кузні в Хараносі.",  -- db:4293
[511912149] = "Якщо ви мене запитаєте, то я вважаю, що Гріф трохи занадто багато часу проводить із тваринами.  Проте ніхто інший не знає мисливського ремесла так добре, як він.  Шукайте його біля кузні в Хараносі.",  -- db:4293
[339991030] = "На винокурні «Громовий ель» є маг, який, можливо, зможе навчити тебе кільком новим заклинанням.  Гадаю, його звати Магіс Спаркмантл.",  -- db:4294
[402092725] = "Ти впевнений, що не хочеш навчитися бути воїном?  Ну, адже на полі бою ризикуєш саме ти.  Якщо ти справді хочеш навчитися погрожувати пальцем, то краще поговори з Магісом Спаркмантлом у винокурні «Громовий ель».",  -- db:4294
[232074301] = "Ох... паладин?  Ну що ж, $glad : lass;, тобі пощастило!  Азар Стронгхаммер повернувся з тренувань і зараз перебуває на винокурні «Громовий ель» у Хараносі.",  -- db:4295
[611732274] = "Вам потрібне навчання?  Що ж, Азар Стронгхаммер завжди готовий поділитися своїм досвідом із молодшими паладинами.  Чому б вам не завітати до нього на винокурню «Громовий ель»?",  -- db:4295
[791149582] = "О, то це священик?  Ну, якщо тобі знадобиться трохи тренування, старого доброго Максана напевно знайдеш за келихом у винокурні «Громовий ель».",  -- db:4296
[60974242] = "Ви напевно знайдете Максана Анвола, який випиває кілька келихів у винокурні «Thunderbrew». Чому б вам не випити там пінту і не дізнатися, чи навчить він вас чомусь новому?",  -- db:4296
[655178098] = "Що ж, схоже, ми обоє шукаємо Хограла Баккана. Він, безперечно, гном, тож рано чи пізно він завітає до пивоварні «Громовий ель», щоб випити елю — можливо, він уже там.",  -- db:4297
[304696733] = "Ти шукаєш Хограла?  А ти вже заглянув у таверну?  Ой!  Якщо ти шукаєш розбійника, до того ж карлика, то тобі слід почати з «Інн»!  Іди вже поглянь.",  -- db:4297
[260761912] = "Чаклуни... Мені вони зовсім не до душі.  Ось, наприклад, той Грімрізз, що влаштувався біля винокурні «Громовий ель». Через нього ель там, мабуть, втратить свою газованість!  Чаклуни... фу!",  -- db:4298
[686368831] = "Така магія — це суцільна біда, кажу вам. Не розумію, чому цьому Грімрізу дозволили влаштуватися саме біля винокурні «Грімбрю»! Тримайтеся від нього подалі, ви, що тут!",  -- db:4298
[554091285] = "Ой!  Ось це вже інша справа!  Готовий побитися об заклад, що Граніс Свіфтаксе міг би навчити тебе кількох хитрощів у володінні мечем.  Зараз він перебуває на винокурні «Грімбрю» в Хараносі.",  -- db:4299
[942631607] = "Цей Граніс Свіфтаксе може випити рибу під стіл, а його сокира все одно влучно розмахується.  Проте, якщо ти хочеш навчитися, краще знайди його, поки ще можеш його зрозуміти.",  -- db:4299
[412545383] = "Ні, тут, у Дун-Морозі, алхіміків немає. Краще пошукай їх в Айронфорзі... спробуй звернутися до гномів у Тінкер-Тауні.",  -- db:4301
[550546817] = "Я чув, що в Айронфорзі є крамниця, якою керують гноми й яка спеціалізується на алхімії.  Тобі варто зазирнути туди.",  -- db:4301
[405739003] = "Ой!  Ось це справді корисна навичка.  Тогнус б’є по ковадлу з такою люттю, яку не часто побачиш.  Чому б тобі не підійти до нього і не поговорити, щоб дізнатися, чого він може тебе навчити?",  -- db:4302
[391753596] = "Мабуть, коли ви перебуваєте в Хараносі, ви чуєте, як Тогнус стукає по ковадлу. Хоча, якщо ви останнім часом не чистили вуха від вушної сірки, то чому б вам просто не зазирнути до кузні?",  -- db:4302
[695153700] = "Ель «Thunderbrew» та страви від Гремлока — це справді чудовий обід. Якщо ви хочете стати кухарем, вам дійсно варто звернутися до нього, щоб він вас навчив.",  -- db:4303
[91474626] = "Гремлок не завжди має успіх у кулінарії, але у нього є кілька смачних рецептів, які варто вивчити. Зайдіть до нього на розмову у винокурню «Грімбрю» і дізнайтеся, чому він вас навчить.",  -- db:4303
[899046467] = "Наскільки мені відомо, тут, у Дун-Морозі, немає жодного чарівника. Якщо ви хочете опанувати професію чарівника, вам доведеться відправитися до Айронфорджа.",  -- db:4304
[439526148] = "Якщо ви вирішили займатися зачаруванням, то варто зазирнути в Айронфордж.  Здається, коли я востаннє там був, то бачив крамницю неподалік від майстра грифонів.",  -- db:4304
[653182783] = "Вам варто зазирнути до «Steelgrill's Depot» і пошукати Бронка. Коли він не майструє якісь дивні пристрої, то зазвичай розмовляє з пілотами про їхні парові танки.",  -- db:4305
[794760537] = "З усіма цими гвинтами, які Бронк так ретельно закручував, мені здається, він дещо втратив розум, якщо ви мене розумієте.  Проте він, як і раніше, має чудовий хист до конструювання найдивовижніших пристроїв.  Вам варто завітати до нього на склад «Стілгрілл».",  -- db:4305
[483851753] = "«Перша допомога» може й не замінить зцілення священика, але в скрутній ситуації вона стане в нагоді.  Раджу вам поговорити з Тамнером у винокурні «Громовий ель» і дізнатися все, що зможете.",  -- db:4306
[617086349] = "Нещодавно старий добрий Тамнер перев’язав мені рану, коли я зіткнувся з огидним трогом. Кажу вам, я вже як новий! Я впевнений, що Тамнер із задоволенням покаже вам, як правильно накласти пов’язку.",  -- db:4306
[312587368] = "У цих краях не так вже й багато риби, але те, що є, — це точно у Пакстона. Його можна зустріти на риболовлі на озері Айсфлоу.",  -- db:4307
[374720098] = "У цих краях є лише кілька місць, де можна порибалити. Пакстон знає їх усі, а може, є ще кілька, про які він тобі не розповість. Чому б тобі не заїхати до озера Айсфлоу й не дізнатися, що він тобі скаже?",  -- db:4307
[134355035] = "Дивно бачити, як маленькі квіти витримують холод Дун-Морога...  але тут ви не знайдете жодного травника.  Щоб отримати навички цієї професії, вам доведеться вирушити до Айронфорджа.",  -- db:4308
[239791294] = "Ні, тут немає нікого, хто міг би навчити тебе травознавству.  Але, гадаю, в Айронфорзі тобі пощастить більше.",  -- db:4308
[676353825] = "Якщо ви хочете опанувати професію шкіряника, вам доведеться вирушити до Айронфорджа.  Я чув, що біля Великої Кузні є гарна майстерня, де можна навчитися цій професії.",  -- db:4310
[786453455] = "Айронфордж — це найкращий вибір для шкіряників. Якщо пам’ятаю правильно, біля «Великої кузні» є крамниця, яка має задовольнити ваші потреби.",  -- db:4310
[165351884] = "Ви ж, мабуть, не думали, що знайдете місто, де немає хоча б одного шахтаря, правда?  Ярра зазвичай можна зустріти біля «Стілгріллс Депо», що розташоване неподалік від Хараноса.",  -- db:4311
[781166797] = "Шахтар?  Не треба питати, чи $glad : lass;, а тільки де!  Ти шукаєш Ярра, і, гадаю, ти знайдеш його в схованці на станції Стілгрілл.",  -- db:4311
[787013575] = "Тут, у Дан-Морозі, ти не знайдеш жодних шкіродеров $glad : lass;, якщо хочеш пройти навчання, їх здебільшого можна знайти в Айронфорджі.",  -- db:4312
[862678753] = "Шкуродери зазвичай везуть усі свої шкури до Айронфорджа, щоб їх висушити. Чому б тобі не завітати туди й не спробувати знайти когось, хто міг би тебе навчити?",  -- db:4312
[430408959] = "Ах, Стоунброу останнім часом майже не виходить з Айронфорджа, тож якщо ви хочете опанувати професію кравця, вам доведеться поїхати до нього в Айронфордж.",  -- db:4313
[616939979] = "Ну, тут вам навряд чи пощастить знайти кравця.  Зате в Айронфорзі є чимало талановитих кравців.  Чому б вам не запитати там у вартового?",  -- db:4313
[275074741] = "У Телдрасілі є чимало місць, які ти можеш відвідати.  Розкажи мені, що ти шукаєш.",  -- db:4316
[851201089] = "Банк розташований у тихому місті Дарнас.  Якщо ви хочете зберігати там свої речі, вам слід туди завітати.",  -- db:4317
[908784656] = "Якщо вам потрібен банк, то ваша подорож приведе вас до самого центру Дарнассуса. Там ви знайдете місце для зберігання своїх скарбів.",  -- db:4317
[163833672] = "Щоб дістатися до порома в Рут'терані, вам потрібно вирушити до Дарнассуса і скористатися порталом, що веде до селища Рут'теран, розташованого біля підніжжя Телдрасіля.",  -- db:4318
[886497090] = "Пором «Рут'терана» відправляється до Аубердіна з селища Рут'терана, розташованого біля підніжжя Телдрасіля.  Через портал у Дарнассусі ви зможете безпечно дістатися до Рут'терана.",  -- db:4318
[45223751] = "Питання такого офіційного характеру вирішуються виключно в Дарнасусі. Вам необхідно вирушити туди, щоб розпочати процес створення вашої гільдії.",  -- db:4319
[326805259] = "Такі документи, як документи про створення гільдії, можна отримати у майстра гільдії в місті Дарнассус.",  -- db:4319
[604013332] = "У ліжках, які господар Келдамір підготував у готелі в Доланаарі, ви неодмінно зможете добре виспатися.",  -- db:4320
[318054342] = "Якщо вам потрібен час, щоб відпочити й відновити сили, найкраще місце для цього — готель у Доланаарі. Готельний господар Келдамір подбає про те, щоб про вас добре подбали.",  -- db:4320
[852745720] = "У околицях Доланаара ви знайдете безліч тренерів, які мають багаторічний досвід і готові надати вам індивідуальні заняття.  До кого б ви хотіли, щоб я вас направив?",  -- db:4322
[566408866] = "Ти звертаєшся за допомогою до друїда?  Тоді тобі слід завітати до Кала біля Місячного джерела, що розташоване трохи південніше від корчми в Доланаарі.",  -- db:4323
[112075667] = "Друїд Кал часто проводить час біля Місячного джерела в Доланаарі. Я впевнений, що він зможе надати тобі необхідне навчання.",  -- db:4323
[28139216] = "Якщо ви шукаєте мисливця, то вам слід завітати до Дазалара. Зазвичай його можна знайти біля готелю в Доланаарі.",  -- db:4324
[690325329] = "Дазалар добре відомий у Доланаарі своїми мисливськими навичками.  Чому б тобі не поговорити з ним і не дізнатися, чого він може тебе навчити?",  -- db:4324
[902283994] = "Жриця на ім’я Лаурна Морнінглайт мешкає в Доланаарі.  Гадаю, її можна знайти трохи північніше від корчми.",  -- db:4325
[997796476] = "Лорана Морнінглайт надає медичну допомогу мешканцям околиць Доланаара.  Можливо, вона зможе навчити вас ремеслу священика.",  -- db:4325
[6701882] = "Розбійник? Я зазвичай не раджу людям звертатися до таких типів, але, гадаю, Джаннок — саме той, кого ти шукаєш. Ти знайдеш його в корчмі в Доланаарі.",  -- db:4326
[566842584] = "Шукаєш розбійника?  Гадаю, Яннок підходить під цей опис.  Чому б тобі не піти поговорити з ним у корчмі в Доланаарі?",  -- db:4326
[76877917] = "Кайра Віндблейд дуже вправно володіє мечем.  Вона зможе провести для вас кілька тренувань.  Ви знайдете її в готелі в Доланаарі.",  -- db:4327
[331078759] = "Мені колись випало щастя побачити, як Кіра Віндблейд б’ється.  З огляду на те, що я побачив, я впевнений, що вона добре тебе навчить.  Шукай її в корчмі в Доланаарі.",  -- db:4327
[278089110] = "Шлях тих, хто обирає професію, є довгим і плідним. Який шлях ви оберете?",  -- db:4328
[360967374] = "Хоча Синдра й не така жвава, як її зілля, її доброзичливий характер ідеально підходить для викладання свого ремесла. Ви можете знайти її трохи на схід від готелю в Доланаарі.",  -- db:4329
[502117937] = "Знання Сіндри в галузі алхімії дещо обмежені, але я впевнений, що їх вистачить, щоб ти міг розпочати навчання. Вона займається своїм ремеслом трохи на схід від готелю в Доланаарі.",  -- db:4329
[10027961] = "Здається, Заррін добре розбирається в кулінарії.  Чому б тобі не підійти до нього і не попросити, щоб він поділився з тобою кількома рецептами?  Зазвичай він готує біля готелю в Доланаарі.",  -- db:4330
[228652426] = "Нам, безперечно, не завадив би ще один кухар у Доланаарі — не те щоб у Зарріна були якісь недоліки в кулінарії, звичайно. Чому б тобі не піти до нього і не дізнатися, чому він може тебе навчити?",  -- db:4330
[146776713] = "Аланна Равенай пов’язує частину свого таланту до чаклунства зі своїм спілкуванням із духами на Галявині Оракула. Зараз ви, мабуть, зможете її там знайти.",  -- db:4331
[916231859] = "Аланна проводить більшу частину дня на Галявині Оракула, де займається своєю справою. Якщо ви бажаєте опанувати професію чарівника, вам слід вирушити туди, щоб знайти її.",  -- db:4331
[177014723] = "Б'янсі часто допомагає вартовим, які патрулюють місцеві дикі території. Якщо ви хочете навчитися надавати першу допомогу, вам слід поговорити з нею.",  -- db:4332
[37632867] = "Навички Б'янсі у наданні першої допомоги неодноразово виявлялися корисними. Якщо ви хочете навчитися у неї, ви знайдете її трохи північніше від корчми в Доланаарі.",  -- db:4332
[911683112] = "Через нещодавні напади в околицях озера Аль-Амет усі рибалки переїхали до Дарнассуса.  Тобі варто спробувати знайти там когось, хто міг би тебе навчити.",  -- db:4333
[459315387] = "Тімберлінги настільки ускладнили рибалкам вилов риби в околицях Доланаара, що вам краще пошукати когось, хто навчить вас рибалити в Дарнассусі.",  -- db:4333
[123898741] = "Малорну якось вдається збирати найніжніші трави, не пошкоджуючи їх.  Безперечно, саме у нього варто брати приклад.  Він живе трохи на схід від корчми в Доланаарі.",  -- db:4334
[908074142] = "Травництво вимагає делікатного підходу, якому можуть навчити лише одиниці, такі як Малорн. Знайдіть його на схід від корчми в Доланаарі.",  -- db:4334
[50148645] = "Маневівери займаються своєю справою у себе вдома, що на дорозі до Дарнассуса. Надія — чудова вчителька з шкіряного ремесла. Вам варто дізнатися, чому вона може вас навчити.",  -- db:4335
[216075419] = "За роки своєї практики Надія стала справжньою майстринею з обробки шкіри. Рушайте на захід дорогою до Дарнассуса, щоб відвідати її, і, можливо, вона поділиться з вами своїми знаннями.",  -- db:4335
[90128398] = "Ви можете зустріти Раднаала, який відточує свою майстерність біля свого будинку на дорозі до Дарнассуса.  Вам варто зайти до нього і дізнатися, чому він може вас навчити.",  -- db:4336
[976291222] = "Я впевнений, що в Дарнассусі знайдеться кравець, який зможе навчити вас цьому ремеслу. Коли ви туди прибудете, попросіть одного з вартових у Дарнассусі, щоб він направив вас до кравця.",  -- db:4337
[888149525] = "Багато матеріалів, необхідних кравцям, надходить через Дарнас.  Тож не дивно, що вони всі переїхали туди, щоб працювати.  Якщо ви хочете стати кравцем, то вам краще вирушити до Дарнаса.",  -- db:4337
[366410444] = "Привіт, $c. Я розбив табір тут, у «Булварку», щоб підготуватися до подорожі в Землі Чуми. До мене дійшли чутки, що не так давно в «Хартглені» оселився великий людський чарівник. «Скарлетний хрестовий похід» доручив йому виготовити для своїх воїнів і мисливців нові луки та рушниці. Кажуть, що він встиг створити дивовижну зброю, перш ніж Хрестовий похід його вбив.$B$BМабуть, їхня недовіра до магії зросла.",  -- db:4353
[906571711] = "Привіт, $c. У мене не так багато часу на розмову — я просто зупинився в Чілвінд, щоб трохи перепочити перед тим, як вирушити до Хартглену. Я чув, що до того, як вони збожеволіли, у «Скарлет-Крусейді» працював маг, який намагався створити потужні луки та рушниці для їхніх солдатів. Не знаю, чи йому це вдалося... «Крусейд» вбив його ще до того, як будь-який з його готових виробів потрапив у світ. Можливо, вони вбили його, щоб зберегти це в таємниці... а може, вони настільки не довіряють магії.",  -- db:4354
[140396307] = "Він... привіт, $N. Вибач, я ще відходжу від отриманих поранень.$B$BЦі «Скарлет Крусейдерс» виявилися міцнішими, ніж я думав. Вони ледь не довели мене до смерті.$B$BТобі теж слід бути обережним. Не хотів би, щоб вони тебе застали зненацька.",  -- db:4355
[840132505] = "Моя родина працювала на лісопильні «Нортрідж» у місцевості, яка зараз називається Західні Землі Чуми. Вони були віддані родині Дума, а тепер «Скарлетний хрестовий похід» захопив її разом з усім Гертгленом!$B$BI Я не заспокоюся, доки цих фанатиків не буде знищено з Азерота.",  -- db:4356
[957958220] = "Давним-давно, ще до останньої великої війни, мій батько керував лісопилкою «Нортрідж». Це було все його життя, і він повністю присвятив себе цій справі. Потім почалася війна, і, хоч як це було для нього болісно, нам довелося втекти до Штормовію.$B$BУ ті часи ми втратили багатьох друзів і рідних, і мені боляче усвідомлювати, що «Скарлетний хрестовий похід» захопив лісопильню для своїх цілей.$B$BОсь чому я повернувся.",  -- db:4357
[592340822] = "Ми — останні представники раси фурболгів... Плем’я Тімбермоу досі не піддалося спотворенню, проте ми стикаємося з такою самою ворожістю з боку сторонніх; більшість вважає, що це неможливо... що насправді можуть існувати фурболли, які уникли спотворення...$B$BРозлючені на тих, хто надто поспішно наживає собі ворогів, мої побратими тепер нападають на кожного, хто наближається; вони нікому не довіряють.$B$BАле, можливо, якщо ви постараєтеся проявити до них доброзичливість, вони сприймуть вас як союзника.",  -- db:4393
[950216750] = "Ви повинні знайти спосіб довести, що ви обоє боретеся на одному боці. Хоча «Тімбермоу» зараз можуть на вас напасти, якщо ви проявите наполегливість, то знайдете вихід.$B$BВи повинні пам’ятати, що будь-які прямі атаки на фурболгів з племені Тімбермоу значно зменшать ваші шанси залучити їх на свій бік.$B$BГарним початком буде полювання на фурболгів Дедвуда, яких можна зустріти в багатьох частинах Фелвуда. Ці фурболи є ворогами племені Тімбермоу, і їхнє вбивство значно покращить ваше становище в очах Тімбермоу.",  -- db:4394
[563896592] = "Ми, Тімбермоу, можемо забезпечити вам безпечний прохід через трюм, однак ви повинні довести, що гідні нашої допомоги.",  -- db:4395
[239468192] = "Фурболи з племені Вінтерфолл, які мешкають тут, у Вінтерспрингу, колись були нашими союзниками... Але одного дня все змінилося.$B$BПід впливом дивних наказів свого верховного вождя вони почали нападати на всіх, з ким стикалися, включаючи й наше плем’я. Тепер вони тримаються осторонь...",  -- db:4396
[594591443] = "Я довіряю дуже небагатьом з таких, як ти, $N. Але я бачу, що ти — друг.",  -- db:4398
[966273853] = "Так, так. Я тебе бачу.$B$BІди собі. Можливо, ти й завоював довіру декого, але щоб переконати мене, цього буде замало!",  -- db:4399
[697641977] = "Якщо ти доведеш, що є справжнім союзником, я, можливо, розгляну можливість навчити тебе...",  -- db:4401
[949065985] = "Сподіваюся, що Світло з тобою, $N. Чи можу я тобі чимось допомогти?",  -- db:4433
[211635691] = "Не відвертайся від Світла, $c, адже саме воно одного дня може врятувати тебе.",  -- db:4434
[936503462] = "Нехай Світло захищає тебе, $c.",  -- db:4435
[208830664] = "Сподіваюся, Світло з тобою, $N. Чи можу я сьогодні чимось тобі допомогти?",  -- db:4436
[882362924] = "Нехай Елуна буде з тобою, $c.",  -- db:4437
[607861319] = "Моя мудрість — це твоя мудрість, так само як і мої знання. Чим я можу тобі допомогти, $N?",  -- db:4438
[594488202] = "Так, $c?",  -- db:4439
[359972134] = "Стережися, $c. Поважай наші звичаї, інакше прокляття впаде на тебе і твоїх близьких.",  -- db:4440
[289395057] = "Я роблю все, що в моїх силах, щоб навчити тебе священицькому ремеслу, якщо саме для цього ти тут.",  -- db:4441
[72061253] = "Що цей незначний слуга може для вас зробити, $N? Можливо, навчити?",  -- db:4442
[846376554] = "Я шукаю когось, $c. Будь ласка, дайте мені спокій... Мені дуже важливо знайти цю людину.",  -- db:4443
[607920046] = "Я — посланець зі Східних Королівств, $N. Мене послали сюди, щоб переконатися, що священики, які приїжджають сюди, отримують належні вказівки.",  -- db:4444
[72703722] = "Замовкніть! Хіба ви не бачите, що господар говорить?",  -- db:4445
[52661996] = "Менше базікайте, а більше слухайте.",  -- db:4445
[226774795] = "Ми маємо зосередитися, якщо хочемо вивести на світ наш драконячий полк!",  -- db:4445
[619126020] = "Замовкніть!  Я не можу собі дозволити пропустити навіть мить цієї лекції!",  -- db:4445
[215050215] = "Ви забули одяг для свого учня?  Ви вважаєте, що мода важливіша за панування Скорге?",  -- db:4445
[177865022] = "Ти виконав вчорашнє завдання? Якщо так, то сідай поруч зі мною!",  -- db:4445
[658340510] = "Будь обережним тут, $gboy:girl;.  Господар бачить усе...",  -- db:4445
[67225267] = "Ти приніс підручники?  Можна мені подивитися разом з тобою?",  -- db:4445
[651143251] = "Дозвольте запитати, що ви тут робите?  Одягніть свою студентську форму і займіться навчанням!",  -- db:4446
[288671763] = "Замовкніть!  Ви що, думаєте, що наші уражені хворобою дракони вилупляться і самі себе навчать?",  -- db:4446
[993817523] = "Ти прийшов із Палаючих степів?  У тебе є мої яйця чорного дракона?",  -- db:4446
[332857135] = "Ти розсіяний. Ти щось від мене приховуєш?",  -- db:4447
[128743548] = "Я відчуваю якесь занепокоєння, що витає навколо тебе...",  -- db:4447
[502012196] = "Твоє майбутнє залишається неясним. Зберися з думками і запитай ще раз.",  -- db:4447
[458910816] = "Ти не схожий на студента...",  -- db:4447
[971459223] = "Цей кодо зовсім не схожий на ту тварину, яку я спочатку приманив! Цікаво, чи можна застосувати «комбобулятор» до мене.",  -- db:4449
[28074750] = "Чому ж такі маленькі істоти, як гобліни, завжди так зачаровані більшими істотами?",  -- db:4449
[483298439] = "Як же гоблінам взагалі вдається прив’язувати рюкзаки до цих звірів?  Кодоси ж удесятеро більші!",  -- db:4449
[134825493] = "Землі чуми — чудове місце для нанесення удару по Плеті!",  -- db:4450
[286447513] = "Радий бачити вас, $c. Ви можете звертатися до мене, якщо у вас немає безпосередніх справ до моєї господині Магати.$B$BI Я виконую за неї більшість її обов’язків, щоб вона могла зосередитися на важливіших справах. Можливо, є деякі питання, які ми могли б обговорити, перш ніж ви попросите про аудієнцію з нею?",  -- db:4473
[208582391] = "Привіт, $N.",  -- db:4474
[936716323] = "Будь ласка, $N, не соромтеся звертатися до мене в будь-який час. Ви добре послужили Магаті. Я впевнений, що вона ще звернеться до вас у майбутньому.",  -- db:4475
[867377585] = "Не смій звертатися до мене так, ніби ти мій рівний, $c. Сильвана — моя королева, і я робитиму те, що вона накаже.$B$BЯкщо ти не виявиш належної поваги, запевняю тебе, ми зможемо знайти для тебе більш ніж гідне місце в Нетері.$B$BАле немає причин, чому ми не можемо поговорити, якщо ти бажаєш допомогти Темній Леді...",  -- db:4476
[514737024] = "У моїх очах усі члени Орди рівні, $N. Ми всі перенесли чимало випробувань, і якби не мудрість та честь, ми були б не кращі за Плеть чи мій народ, коли наша кров була заплямована демоном Манноротом.$B$BВаш обов’язок — допомагати Орді та захищати наш спосіб життя. Але твій обов’язок також полягає в тому, щоб розуміти, коли слід проявляти поблажливість і милосердя як до друзів, так і до ворогів.$B$BДобре це усвідомлюй. Це — нова Орда, а не якась породжена демонами армія, позбавлена вільної волі.",  -- db:4477
[825368720] = "Я мушу вибачитися за те, що не був з вами цілком відвертим щодо своєї особи. Мені потрібно було переконатися, що вам можна довіряти — мало хто безкорисливо надав би допомогу старому й забутому відлюднику.$B$BВи довели, що належите до таких людей: ви — людина чесна й благородна.",  -- db:4493
[844444324] = "Мій син, Таелан, був ще дитиною, коли мене визнали винним у зраді й вигнали з Альянсу, прирікши на життя у вигнанні. Я вирішив залишитися тут, щоб піклуватися про нього; щоб якось забезпечити, щоб він виріс чесною людиною.$B$BЯк я й сподівався, він зайняв моє місце як лорд Марденхолда; але, за жорстоким збігом обставин, приєднався до лав «Скарлетного хрестового походу». Зараз він є їхнім верховним лордом, $r.",  -- db:4494
[460395752] = "Справді. «Скарлетний хрестовий похід» — це відхилення від Ордену Срібної Руки.$B$BВи мусите мені повірити, $r; Таелан — хороша людина. Йому потрібна підтримка. Йому треба згадати... згадати, що таке бути благородним і чесним. Я знаю, що в глибині душі він усвідомлює, що те, що він робить, — неправильно. Ви допоможете йому? Ви допоможете йому згадати?",  -- db:4495
[736096923] = "Уважно слухайте те, що вам кажуть, і не поспішайте ні довіряти, ні не довіряти.  Адже навіть друзі переслідують власні цілі, $c.$B$BНаш великий Вождь знає це, і щоб довести, що в Орді є чаклуни, які не бажають знищити її зсередини чи захопити над нею владу, я зголосився допомогти нашому молодому лідеру всіма можливими способами.",  -- db:4513
[576480194] = "Витривалість Ву Піна просто вражає.  Спостерігаючи, як він годинами відпрацьовує прийоми з зброєю, мені потім стало шкода тренувального манекена.  Не можу придумати нікого, хто б краще підходив для того, щоб навчити вас бойовим мистецтвам зі зброєю.",  -- db:4516
[570445998] = "Майстер Ву Пін досконало володіє майже всіма видами зброї, відомими людству.  Особливо небезпечними є його прийоми володіння мечем.  Він проводить чимало часу в «Арсеналі Веллера», чекаючи на нові поставки зброї, тож якщо вам потрібне тренування, зверніться до нього.",  -- db:4516
[868055191] = "Протягом тисячоліть Іленія Міунфайр досконало опанувала безліч видів зброї і тепер пропонує навчити інших користуватися ними. Якщо ви бажаєте пройти навчання, ви можете знайти її на Терасі Воїнів.",  -- db:4517
[894875713] = "Більшу частину своїх навичок володіння зброєю я отримав від Іленії Мунфайр на Терасі Воїнів.  Вам варто звернутися до неї, якщо ви бажаєте навчитися користуватися новою зброєю.",  -- db:4517
[48847085] = "Якщо взяти Біксі та Булівіфа, то навряд чи знайдеться зброя, якою б вони ще не мали задоволення розрубати чи розтрощити орка. Якщо вам потрібне тренування, ви можете знайти їх у зброярні «Тімберлайн Армс».",  -- db:4518
[413995478] = "Хочеш навчитися користуватися новою зброєю, так?  Тоді тобі варто поговорити з Біксі або Булівіфом у зброярні «Тімберлайн Армс» $glad : lass;.  Вони знаються на зброї — від сокир до... е-е... дворучних мечів.",  -- db:4518
[74011317] = "Хочете навчитися користуватися новою зброєю?  Знайдіть Сайока та Ханаші в «Arms of Legend» у Долині Честі.",  -- db:4519
[82340928] = "Шукайте Сайока та Ханаші в «Долині честі» у грі «Arms of Legend». Слідкуйте за своїми словами в їхній присутності, інакше Сайок може вирішити віддати частину вас на перекус «Усміхненому Псу».",  -- db:4519
[591746707] = "А, ти шукаєш мудрість Ансекви. Шукай його на нижньому пагорбі біля крамниці «Зброя Громового Утвісу».",  -- db:4520
[401176886] = "Ніхто не володіє зброєю так майстерно, як Ансеква. Кажуть, що ним керують духи найкращих воїнів наших шанованих предків. Знайдіть його на нижньому пагорбі, і він навчить вас усього, що ви хочете знати.",  -- db:4520
[102714164] = "Арчібальд — це той, кого ти шукаєш. Він знаходиться біля крамниці зброї на внутрішньому кільці Військового кварталу.",  -- db:4521
[266606379] = "Маленький Забутий знає всі види зброї.  Його звуть Арчібальд.  Його можна знайти на внутрішньому кільці Воєнного кварталу.",  -- db:4521
[211756830] = "Було б розумно пояснити вам, на що готові піти наші вороги, аби приховатися прямо у нас під носом.$B$BНасамперед знайте: наш ворог — це Рада Тіней. Незалежно від того, яке завдання я вам доручу, чи проти кого я попрошу вас діяти, пам’ятайте про цей простий факт.$B$BУ складі Ради існує багато культів, але вони існують лише для того, щоб приховати її дії від нерозумних.$B$BТакі угруповання, як «Палаюче Лезо», «Пробудження Аргуса» та «Пекуче Лезо», — це все інструменти Ради. Вважайте їх одним і тим самим.",  -- db:4522
[522894527] = "Ага, один із наших. Приємно бачити, що наші ряди зростають так стрімко, що я вже не встигаю запам’ятовувати обличчя наших членів.$B$BТой дурень Тралл думає, що я так старанно працюю, аби очистити репутацію чаклунів і довести, що ми — його слуги. Ідіот! Палаюча Легіон перетворить весь цей світ на попіл після того, як повністю висмокче з нього всі ресурси.",  -- db:4533
[168084300] = "Наївний дурень. «Палаюче Лезо» — це й є Рада Тіней! Під владою Ради існує безліч культів та організацій, але всі вони — лише продовження її волі. Може, я й очолюю «Палаюче Лезо», але для Ради я — така сама маріонетка, як і ти для мене!$B$BПоглянь на «Пекуче Лезо» — більшість з них вважають, що стають новою групою могутніх чаклунів, яка замінить Раду Тіней.",  -- db:4534
[700948875] = "Ха-ха! За винятком їхніх ватажків — сатира Базалана та чаклуна Джергоша — так, усіх до одного. Ось чому я постійно насилаю на них послідовників Тролла. Це створює у Тролла враження, ніби я викорінюю зло в надрах його великого міста. Насправді перемога подвійна: вбити послідовників Тралла та перевірити силу членів «Палаючого меча», щоб побачити, чи справді вони гідні приєднатися до мене.",  -- db:4535
[636134782] = "Я тобі про це розповім. Судячи з усього, ти вже доводиш свою спроможність у наших лавах, якщо так швидко став лейтенантом. Можливо, ти зможеш повернутися до мене пізніше, і я матиму для тебе завдання. Рада дуже цінує тих, хто володіє магією, але слуги будь-якого роду завжди бажані, незалежно від їхньої професії.",  -- db:4536
[531787034] = "Як член Ліги дослідників, я займаюся пошуками артефактів у цій місцевості. Кажуть, що у Вінтерспрингу можна знайти дуже магічні предмети... Більшість із них ретельно охороняються.",  -- db:4573
[951882352] = "Це небезпечні часи, мандрівнику. Будь обережним.",  -- db:4633
[327387303] = "Вітаю! Що привело вас до Вінтерспринга? Ці холодні й безкрайні землі можуть здаватися похмурими, але це місце, сповнене таємниць...",  -- db:4634
[419400180] = "Який же це смуток... Минуле не можна повернути...",  -- db:4635
[556222739] = "Сідайте і послухайте мою історію, $r.",  -- db:4673
[398134619] = "$g Привіт, красуне, тобі підвезти до Гром'гола? Кажуть, у тих джунглях там дуже спекотно, може, я приєднаюся до тебе на короткий відпочинок і покажу тобі справжню джунгляну кішку. : Давай, вирушай у подорож до чудових, розкішних тропічних джунглів Странглторна. Саме так, ти теж можеш проводити час, засмагаючи біля кришталево-блакитних вод, поки я стою тут у цій нестерпній спеці, не маючи на що дивитися, крім мого брата Фреззи, цілий день! Насолоджуйся подорожжю!;",  -- db:4693
[515248174] = "Поклади босу в руку монетку — і подивись, що з того вийде. Я люблю свою роботу. Хоча, якби я зміг придумати спосіб перевести того маленького бешкетника Снурка в цей порт… ну, краще й уявити не можу. Але я готовий побитися об заклад, що ти тут не через мої ділові практики. Ти шукаєш цепелін до Андерсіті, я правий? Ну, це чудово, бо він причалює саме тут, прямо за моєю спиною. О, і, до речі, якщо побачиш Снурка, скажи про мене кілька добрих слів, гаразд?",  -- db:4694
[944983235] = "Ну ж бо, вирушайте у подорож до чудових, розкішних тропічних джунглів Стренглторна. Саме так, ви теж можете проводити час, засмагаючи біля кришталево-блакитних вод, тоді як я стою тут у цій нестерпній спеці, і цілий день не маю на що дивитися, крім свого брата Фреззи! Приємної подорожі!",  -- db:4697
[109121929] = "Кошмар нарешті закінчився!  Дарроушир, пробач мене!",  -- db:4713
[940633716] = "Дух вбитого Лунаклоу пильно дивиться на тебе, ніби чогось від тебе чекаючи.",  -- db:4714
[804890808] = "Дух пильно дивиться тобі в очі й бере тебе за руку. Ти відчуваєш, як тепло пронизує твоє тіло, ледь не збиваючи тебе з ніг.$B$BКоли тепло відходить, ти відчуваєш ледь помітну присутність ведмежого духу всередині себе... що зміцнює твою рішучість.",  -- db:4715
[800420892] = "Ми всі були свідками жахливих трагедій, але не повинні дозволити їм загнати нас у відчай.$B$BНатомість бережімо ці спогади, щоб одного дня ми змогли знайти відповіді.",  -- db:4716
[789734285] = "Ведмідь спокійно й терпляче дивиться на тебе, але нічого не каже.",  -- db:4718
[23725029] = "Дух ведмедя дивиться на тебе спокійним і мирним поглядом.  Ти чуєш голос, що звертається до тебе так, ніби він лунає з ведмедя, але сама тварина нічим не дає зрозуміти, що саме вона говорить.$B$B\"Вітаю, мій юний друже. Якщо ти прийшов до мене за порадою, то, можливо, я зможу допомогти тобі знайти те, що ти шукаєш.\"",  -- db:4719
[706773690] = "Я уособлюю силу, яка надає тобі, юному друїду, опору. Ти прийшов до мене, щоб навчитися цій силі, юний друїде, і я навчу тебе цьому.  Я навчу тебе всьому, що стосується духа ведмедя, за умови, що ти будеш слухати й розуміти.$B$BЩоб зрозуміти, що означає черпати силу з мого духу, тобі потрібно усвідомити важливість сили тіла, а також сили серця.",  -- db:4721
[20296869] = "Фізична сила — це потужність і швидкість дій.  Ви повинні завжди підтримувати себе у формі — як фізично, так і психічно.  Об’єм тулуба ведмедя підкреслює його силу, адже в бою він є грізним супротивником.  Однак об’єм тіла ведмедя приховує його гнучку спритність та гострий розум.  Ці несподіванки ви зможете використати на свою користь.$B$BВи повинні покладатися на силу тіла ведмедя, щоб опанувати Шлях Кігтя.",  -- db:4733
[957544986] = "Сила серця — це те, що надає вам рішучості діяти… діяти, виходячи з чистих і щирих намірів. Зберігати рівновагу — це не означає бути самовдоволеним чи банальним.$B$BВи повинні виявляти рішучість у тому, у що вірите, і бути готовими боротися за це.  Мати-ведмедиця виявляє безмежну рішучість у захисті своїх дитинчат, так само як і старий ведмідь, що захищає свою нору.  Саме цю рішучість, цю силу серця ви повинні пізнати, якщо хочете опанувати Шлях Кігтя.",  -- db:4734
[378199360] = "Ще невідомо, чи готовий ти, юний друїде. Навіть наймудріші й найстаріші друїди ніколи не бувають по-справжньому готовими, коли настає їхня вирішальна година випробувань.$B$BТи почув мої слова, і тепер тобі слід рухатися далі.  Дотримуйся того, чого я тебе навчив.  Настане час, коли твою силу випробують.  Ти повинен протистояти своєму ворогу, як це зробив би ведмідь — силою тіла та силою серця.  Вчися на цьому бою, юний друїде.  Іди... з моїм благословенням.",  -- db:4735
[813413459] = "Вітаємо, $c.  Ласкаво просимо до Найтхевена, а також до всього Місячного Гаю.  Коло Сенаріону радо приймає всіх істот, які поважають владу та закони природи.$B$BПоки ви тут, будь ласка, дбайте про збереження рівноваги у всьому.  Порушення порядку тут не вітаються, і наші вартові навчені беззаперечно припиняти будь-які ворожі дії.",  -- db:4753
[31502786] = "Тобі потрібна ілюзія?$B$BЯкщо твоя ілюзія зникне посеред твого пошуку, повертайся до мене, і я знову накладу на тебе маску.$B$BЯкщо твої зусилля не увінчаються успіхом, не здавайся! Повертайся до мене. Я допомагатиму тобі, доки ти не досягнеш своїх цілей.",  -- db:4773
[509333326] = "Намагайтеся зберігати рівновагу у всьому, $c. Саме в цьому полягає справжня гармонія.",  -- db:4774
[483204187] = "Ласкаво просимо, мій $g брате : сестро;.  Якщо ти тут, щоб тренуватися, то я з радістю навчу тебе.$B$BНіколи не завадить ще раз усвідомити своє місце в тому, що я люблю називати Великою Рівновагою.  Як охоронці цієї рівноваги, ми повинні прагнути постійно зберігати ясність розуму та силу серця.  Тренування допомагають нам у цьому.",  -- db:4775
[221927944] = "Битва закінчилася, і мешканці Дарроуширу врятовані.",  -- db:4776
[685311260] = "Битва закінчилася, і мешканці Дарроуширу врятовані.$B$BВони врятовані, $N, завдяки тобі.  Ти — справжній герой Дарроуширу.",  -- db:4777
[909997814] = "На мої очі опустилася темрява, але ти вирвав мене з моєї гріховної задуми. Ти врятував мене, $N.$B$BІ тепер я благаю тебе... пробач мене.",  -- db:4778
[482981679] = "Ласкаво просимо, мій $g брате : сестро;.  Якщо ти прийшов сюди, щоб навчатися, я з радістю буду твоїм наставником.$B$BМи — хранителі рівноваги, зараз і навіки, поки Малфуріон перебуває у Світі Снів.  Ніколи не забувай про це.",  -- db:4779
[511599030] = "Наш повелитель Малфуріон досі вважається зниклим у Світі Снів, $c.  Його світло — це маяк, що вказує нам шлях, і ми повинні зробити все, що в наших силах, аби зберегти це світло.",  -- db:4780
[735033558] = "Нехай благословення Сенаріуса супроводжують вас, $c.  Наш вождь, архідруїд Стагхельм, веде нас і весь Телдрасіл до нового життя!",  -- db:4781
[352705269] = "Ласкаво просимо, мій $g брате : сестро;.  Якщо ти прийшов сюди, щоб навчатися, я з радістю буду твоїм наставником.$B$BХодять чутки про розбрат у «Коло Сенаріону», але тобі не варто звертати уваги на такі плітки.  Наш архідруїд, Фандрал Стагхельм, веде нас і весь Телдрасіл до слави!",  -- db:4782
[465071770] = "Навіть у холодних кам’яних стінах, таких як ті, що оточують це містечко, можна знайти спокій і мир.  Насправді, їх можна знайти де завгодно... просто пошукайте цю гармонію всередині себе.",  -- db:4783
[433299775] = "Ласкаво просимо, мій $g брате : сестро;.  Якщо ти тут, щоб навчатися, то я з радістю буду твоїм наставником.$B$BНезабаром настане час, коли поклик Смарагдової Мрії охопить тебе.  Ти впадеш у багаторічну сплячку і будеш блукати серед найчистіших форм.  Саме там і саме тоді відбудеться твоє остаточне навчання.",  -- db:4784
[651763823] = "Ми прагнемо зберегти рівновагу, як вчить Сенаріус, $c.  Його світло — це маяк, що вказує нам шлях, і ми повинні зробити все, що в наших силах, аби зберегти це світло.",  -- db:4785
[270228016] = "Ласкаво просимо, мій $g брате : сестро;.  Якщо ти прийшов сюди, щоб навчатися, я з радістю буду твоїм наставником.$B$BМи — хранителі рівноваги, зараз і назавжди, як навчив нас Сенаріус.  Ніколи не забувай про це.",  -- db:4786
[298582002] = "Ще раз дякую, $n! Я дуже задоволений тим, що ми знайшли.$B$BБажаю тобі успіхів!",  -- db:4787
[229270758] = "Я готуюся піднятися на хребет, $N. Мені б не завадила допомога — може, ти підеш зі мною?",  -- db:4788
[498195094] = "Я не треную таких, як ти, $c.",  -- db:4793
[120674682] = "Ми — лише темрява й тіні. Вічні. Невидимі.",  -- db:4794
[370432698] = "Вітаю, юний розбійнику. Що ти шукаєш?",  -- db:4795
[94714874] = "Я не можу вас навчити. Вам потрібно звернутися до вашого інструктора.",  -- db:4796
[604411480] = "Нічим не можу тобі допомогти, $n. Я треную лише розбійників.",  -- db:4797
[162803078] = "Вибачте, але я треную лише розбійників.",  -- db:4799
[46705444] = "Ага... покупець! Зверніться до мого найвидатнішого винаходу — «Vendor-Tron 1000». У нього є все, що вам потрібно... деякі з найрідкісніших предметів, які ви коли-небудь зможете знайти на ринку в будь-якій частині Калімдора... не кажучи вже про те, що його програма не допускає жодних торгувань, тож ціна, яку ви бачите, — це та ціна, яку ви платите.",  -- db:4813
[542279459] = "Без сумніву, ти — ще один незграбний простак, якого Темна Леді послала на навчання до свого чемпіона.$B$B<Натанос зітхає.>$B$BЯ відправив кожного з вас до неї по шматочках, не бачу, чому цього разу має бути інакше.$B$BОднак моє завдання — не питати «чому», а виконувати волю Темної Леді.",  -- db:4814
[109026680] = "Сьогодні у тебе просто щасливий день: я щойно завершив технічне обслуговування «Super-Seller 680». Там безліч товарів на продаж за надзвичайно низькими цінами. Заходь і переконайся сам... Мій брат Корк вважає, що його «Vendor-Tron 1000» перевершить мій бот за обсягами продажів.",  -- db:4815
[209301424] = "Чим я можу тобі допомогти, $n?",  -- db:4834
[536994002] = "Ви виглядаєте як людина, біля якої мені слід пильнувати за своїм гаманцем. Чим можу вам допомогти?",  -- db:4835
[965613246] = "Не думаю, що ти хочеш навчитися чомусь із того, чому я можу навчити. Можливо, тобі варто знайти тренера з $c, який тобі допоможе.",  -- db:4837
[127225739] = "Прийшов повчитися у майстра, так?",  -- db:4838
[505311425] = "Я тобі здаюся $c? А тепер забирайся звідси, поки я не відчув бажання змастити своє лезо... твоєю кров’ю.",  -- db:4839
[377786428] = "Вітаю, друже.  Нехай Світанок береже тебе в ці неспокійні часи.",  -- db:4841
[680502026] = "Друже, ти не знаєш, що таке справжній кінь, доки не візьмеш у руки поводи високопородного гірського барана породи «Барак Торол». Будь ласка, не соромся оглянути цих чудових супутників для будь-якого мандрівника. Вони тобі добре послужать, повір мені.",  -- db:4855
[505564568] = "Я — найновіше втілення автоматизованих торгових автоматів... одного дня ми запануємо над світом... тільки не кажіть моєму начальнику, що я знімаю гроші з його товару...",  -- db:4856
[926195256] = "Моя програма не дозволяє мені знизити вартість будь-яких товарів.",  -- db:4857
[966273827] = "Багаторічний досвід застосування якісних методів розведення та ретельний догляд дають мені можливість представити вам цих коней!  Будь ласка, не поспішайте, обираючи собі коня.  Кінь — це супутник на все життя, друг.  Не обділяйте себе — придбайте свого скакуна тут уже сьогодні!",  -- db:4859
[345443462] = "Перш ніж вирушати на полювання, розумно буде запитати когось, що саме ви шукаєте, перш ніж почати це шукати.",  -- db:4861
[274510404] = "Звірі Кодо, друже мій!  Виховані змалку та вирощені на Золотих рівнинах Мулгора, ці чудові тварини стануть ще кращими верховими конями!  Будь ласка, перегляньте мій асортимент і переконайтеся самі, чому ми, таурени, так покладаємося на цих чудових створінь!",  -- db:4862
[771971111] = "Ласкаво просимо до «Круга Сенаріону», $c.",  -- db:4863
[918211368] = "Дозволь мені навчити тебе мистецтву полювання.",  -- db:4864
[569189471] = "Я маю багато знань, якими хочу поділитися з тобою, $c. Ти повинен навчитися полювати з честю.",  -- db:4866
[174595124] = "Я навчаю мисливців звичаям і традиціям наших предків.",  -- db:4867
[347094497] = "Таурени обожнюють полювання; це глибоко вкорінилося в нашій природі.",  -- db:4868
[235884593] = "Від імені Королівського товариства аптекарів я маю честь запропонувати вам найкращих коней, доступних для «Покинутих». Ці тварини, як і ми всі, пройшли через випробування та поневіряння, і тепер вони також стали сильнішими та витривалішими, ніж це було б можливо для звичайних смертних! Будь ласка, огляньте їх самі та переконайтеся в цьому.",  -- db:4869
[177581282] = "Приходьте, щоб пізнати шляхи мисливця. Гордість, честь і традиції.",  -- db:4870
[923812062] = "Я можу навчити тебе тонкощам верхової їзди на баранах, за умови, що у тебе вистачить золота, щоб оплатити урок!",  -- db:4871
[586472685] = "Я можу навчити вас тонкощам верхової їзди на скелеті, за умови, що у вас вистачить золота, щоб оплатити урок!",  -- db:4873
[536681422] = "Я можу навчити вас тонкощам верхової їзди в стилі «Кодо», за умови, що у вас вистачить золота, щоб оплатити урок!",  -- db:4874
[384918237] = "Я можу навчити тебе тонкощам верхової їзди на рапторі, за умови, що у тебе вистачить золота, щоб оплатити урок!",  -- db:4875
[516141900] = "Я можу навчити вас тонкощам верхової їзди, за умови, що у вас вистачить золота, щоб оплатити урок!",  -- db:4876
[772867025] = "Я можу навчити вас тонкощам верхової їзди на тиграх, за умови, що у вас вистачить золота, щоб оплатити урок!",  -- db:4877
[18867825] = "Я можу навчити вас тонкощам керування механострайдером, за умови, що у вас вистачить золота, щоб оплатити урок!",  -- db:4878
[119303166] = "Я можу навчити тебе тонкощам «Верхової їзди вовка», за умови, що у тебе вистачить золота, щоб оплатити урок!",  -- db:4879
[71941129] = "Я б даремно витрачав і твоє золото, і свій час, якби намагався навчити тебе керувати «Механострайдером», $c.  Ти просто занадто великий!",  -- db:4881
[195973309] = "Я навчаю та наставляю молодих мисливців, дотримуючись традицій, що передаються з покоління в покоління.",  -- db:4888
[862547929] = "Пам’ятайте: усе взаємопов’язане. Якби звірі зникли з цієї землі, наш народ загинув би від великої духовної самотності, адже те, що трапляється зі звірами, трапляється й з тауренами. Те, що спіткає Азерот, спіткає й усіх, хто його населяє. $B",  -- db:4889
[80293669] = "Якщо ви тут, щоб навчитися тактиці та стратегії полювання, то ви потрапили за правильною адресою!",  -- db:4890
[882449267] = "Привіт, друже! Ти коли-небудь занурювався в глибини океану? Я відкрию тобі маленький секрет, га? У глибинах океану можна знайти бульбашкові тріщини; завдяки їм ти зможеш дихати повітрям, перебуваючи під водою.  Але нехай це залишиться між нами, га? Мені не потрібна конкуренція за мої пастки для молюсків в інших місцях… якщо ти мене розумієш!",  -- db:4891
[538352532] = "Поглянь на мудрість і знання звіра — і ти побачиш самого себе. Спостерігай, як це робить сова, вчися хитрості у саблезубого тигра, втілюй у собі могутній дух вовка.",  -- db:4893
[794395430] = "Ти ж не друїд!",  -- db:4913
[220151278] = "Чи хотіли б ви скористатися перельотом до селища Рут'теран, який надає «Коло Сенаріону»?",  -- db:4914
[775535962] = "Якщо ви шукаєте рейс назад до Тандер-Блаффа, то вам слід поговорити з моїм колегою-тауреном, Бунтеном Плейнсвіндом.",  -- db:4915
[774396726] = "Якщо ви шукаєте рейс назад до селища Рут'терана, то вам слід звернутися до моєї колеги з народу нічних ельфів, Сільви Філ'навет.",  -- db:4917
[854837813] = "Чи хотіли б ви скористатися перельотом до Громового Утвору, який надає «Коло Сенаріону»?",  -- db:4918
[161360326] = "Часи, в яких ми живемо, мінливі, як вітер, $c.  Важливо пам’ятати про те, що в цьому світі є істинним і вічним, і берегти це.  Усе інше — марнотратство.",  -- db:4933
[259720277] = "Жодна інша раса в Азероті не зазнала стільки страждань, як наш народ, $c. Зміяти смерть стало для нас усіх другою натурою.",  -- db:4934
[730881458] = "Вітаємо, $N, і ласкаво просимо до табору Нараче. Новина про твоє прибуття швидко поширилася серед племені.",  -- db:4935
[322942074] = "Ах, краса Шейдоуглена ніколи не перестає радувати мої почуття!",  -- db:4936
[546854971] = "О, ти ж виглядаєш таким міцним! Можливо, ти зможеш мені трохи допомогти. Тут майже нікого немає, крім зелених підмайстрів, а вони мають інші турботи.",  -- db:4937
[203064946] = "Гей, громадянине!  Ти виглядаєш міцним хлопцем.  Нас, охоронців, тут не так багато, і мені б не завадила твоя допомога...",  -- db:4938
[267246963] = "Оскільки ви мені допомогли, я розповім вам те, що знаю про цю країну та про те, що тут варто побачити. Мої знання не надто великі, але, можливо, я зможу вказати на деякі речі, які можуть зацікавити таку людину, як ви.",  -- db:4953
[470863342] = "Мої знання про історію нічних ельфів обмежені, але кажуть, що давним-давно — ще в ті часи, коли нічні ельфи все ще шанували мистецтво чаклунства — Азшара була найвидатнішою серед свого роду. Прекрасну жінку вони проголосили королевою. На жаль, саме її пристрасть до таємних знань одного дня стала каталізатором найруйнівніших подій в історії цього світу.",  -- db:4954
[678590786] = "Колись це було величне місто нічних ельфів, де правили Хайборни, які володіли величною та могутньою таємною магією. Зараз вони прокляті й блукають цими землями, а їхнє зруйноване місто стало жертвою нагів Спітелаш. Я знаю, що наги шукають у руїнах могутні артефакти Хайборнів.",  -- db:4955
[259737150] = "Ходять чутки, що на півночі мешкає могутній маг-людина; з невідомих причин він пильнує за цими землями. Я сам там не бував, але кажуть, що він радо приймає гостей, і ті навіть можуть заслужити його прихильність, якщо погодяться виконувати для нього доручення.",  -- db:4956
[76365876] = "За останні кілька років я бачив, як з фурболгами траплялися жахливі речі — вони стали жертвами на багатьох фронтах. Але мені не зрозуміло, що сталося з цим племенем. Чи їх спотворила та сама чума, що вразила Фелвуд? А може, вони просто розлючені тим, що сталося з їхнім колись мирним народом, і тепер прагнуть захистити себе. У будь-якому разі, більшість із них виглядають вороже налаштованими до тих, хто заходить на цю територію.",  -- db:4957
[388835696] = "Самих блакитних драконів тут немає, але є послідовники Малігоса. Не знаю чому, але можу сказати одне: де б не були блакитні дракони, там обов’язково зустрінеш таємну магію. Я не здивувався б, якби нащадки драконів охороняли тут щось… можливо, те, що залишили після себе Високородні.",  -- db:4958
[203191575] = "Мені слід найняти когось на допомогу; мені не подобається сидіти тут цілий день і продавати рибальські приналежності. Я б набагато охочіше пішов на риболовлю, а вже потім продавав би приналежності.",  -- db:4959
[430708575] = "Тром-Ка, $c. Сьогодні у мене поганий настрій, тож, будь ласка, якщо ти не можеш мені допомогти, я волів би побути наодинці.",  -- db:4960
[797823597] = "Я не можу тебе навчити, $c.",  -- db:4973
[761555523] = "Я — Улісс Ракмор, капітан корабля «Галлант».  А це — щоденник останніх днів мого приреченого корабля.$B$BМи прямували до фортеці Фетермун із вантажем провізії, коли нага штурмували борти «Галланта».  Ми відбили їх, але розуміли, що вони повернуться.  Побоюючись втратити свої найцінніші речі, я скерував «Галлант» до острова біля узбережжя Десоласу, на якому стояли стародавні руїни нічних ельфів.  І там я залишив свою скриню зі скарбами.",  -- db:4974
[833343622] = "Мій скринь має геніальну конструкцію, і для його відкриття потрібні два ключі: один золотий, а другий — срібний. Перший ключ, срібний, я віддав своєму першому помічнику, а золотий залишив собі.$B$BАле нам судилося їх втратити.  Мій ключ загубився під час наступної атаки нагів, а ключ мого першого помічника — загубився днем пізніше, коли на нас напав драйснап макрура й затягнув його в глибину.$B$BЯ впевнений, що ключі тепер у нагів і макрури.  Я радий, що ці дві істоти — вороги й не поділяться ними між собою.",  -- db:4975
[713627422] = "Після нападу макрур ми зрозуміли, що «Галлант» не витримає ще одного.  Тож я та кілька вцілілих матросів покинули мій корабель.$B$BЗараз ми на березі й незабаром вирушимо до містечка Найджелс-Пойнт, але між нами та притулком чекає чимало небезпек, і я боюся, що Десолейс поглине нас.$B$BЯ пишу це зараз у надії, що хтось дізнається про наше скрутне становище і колись помститься за нас тим водяним чудовиськам, які стали причиною нашої загибелі.",  -- db:4976
[267676107] = "Храм Ремулоса — це священне місце для нас, членів Кола Сенаріона, тут, у Місячній галявині... тож, будь ласка, поводьтеся так, як личить відвідувачеві.$B$BA Тобто відвідувачеві, який не хоче, щоб я встромив у нього свою шаблю.",  -- db:4977
[227720420] = "Нехай Сенаріус береже тебе, $g брате : сестро;.$B$BI Я — Таджаррі, і я — присяжний захисник цього святилища. Для мене велика честь служити Хранителю Ремулосу як охоронець цієї священної землі.",  -- db:4978
[965982498] = "До того, як прийшла Пораза, у мене був чудовий бізнес. Я купував і продавав усе. Усе!$B$BІ мої ціни були просто БЕЗУМНІ!$B$BПросто запитайте будь-кого. Будь-кого, хто ще живий.",  -- db:4979
[443977038] = "Привіт, $N!  Ти прийшов щось купити?  Або, може, щось продати?$B$BКращих цін ти ніде не знайдеш — інакше я не Август Доторкнутий!",  -- db:4980
[10880028] = "Це небезпечне місце, $N. Будь обережним тут.",  -- db:4982
[357151151] = "Не марнуй мій час, $c.",  -- db:4984
[248774258] = "Я не треную таких, як ти, $c.  Знайди собі іншого тренера, поки не розлютив мене.",  -- db:4985
[10644896] = "Не переймайся, друже. Я треную лише воїнів.",  -- db:4986
[940506630] = "Чим можу тобі допомогти, друже?",  -- db:4987
[703034204] = "Через невідповідність у вашій специфікації класу я не можу допомогти вам вирішити будь-яку ситуацію, пов’язану з відсутністю відповідних здібностей.",  -- db:4988
[397463368] = "Чудово! Ви відповідаєте необхідним параметрам і технічним вимогам. Чим я можу вам допомогти?",  -- db:4989
[828633388] = "Хегнар Рамблшот, до ваших послуг!",  -- db:4990
[185355726] = "Хоча Терамор славиться своєю винятковою підготовкою воїнів, боюся, що я не можу вам допомогти.",  -- db:4991
[541796329] = "Ти прийшов тренуватися разом із гвардією Терамора, чи не так?",  -- db:4992
[486062823] = "Я не можу навчати такого $c, як ти.",  -- db:4993
[80896623] = "Чим я можу тобі допомогти, дитино?",  -- db:4994
[414838259] = "Колись Володар Вогню та його побратими панували над усім цим світом, смертний. Як слуга Стародавніх Богів, він воював проти Титанів за панування над цією планетою. Титани, здобувши перемогу, заслали мого господаря та його побратимів до Сфери Стихій — там вони мають залишатися ув’язненими до кінця часів.",  -- db:4995
[822555513] = "Я не можу навчити тебе, юний друже.",  -- db:4996
[53504573] = "Я не володію тими знаннями, які ви шукаєте.",  -- db:4998
[374104388] = "Чим я можу тобі допомогти?",  -- db:4999
[306841163] = "Я не можу тобі допомогти з тренуваннями. Тобі слід пошукати тренера з $c.",  -- db:5000
[83541467] = "Що?",  -- db:5001
[283310053] = "Не марнуй мій час.",  -- db:5002
[797299470] = "Я не можу тебе навчити.",  -- db:5003
[810943727] = "Ей, друже, тобі треба зазирнути до тренера $c.",  -- db:5004
[427551389] = "Духи привели вас до мене. Чим я можу вам допомогти?",  -- db:5005
[148047659] = "Нехай духи будуть з вами.",  -- db:5006
[368799419] = "Нехай духи будуть з тобою, друже. Що цей троль тобі зробив?",  -- db:5007
[304495726] = "Нехай духи бережуть тебе, друже.",  -- db:5008
[322118742] = "Куди ти збираєшся?  Ну, якщо хочеш дістатися туди швидко, то не шукай далі!",  -- db:5009
[431671567] = "Я намагаюся підтримувати запаси на Сентинел-Хіллі, але це нелегко, зважаючи на всі ті події, що тут відбуваються.",  -- db:5010
[38634697] = "Всього триста років тому безрозсудний гном на ім’я Тауріссан викликав Повелителя з його вогняного царства. Його повернення до цього нікчемного світу спустошило навколишні землі та створило це вулканічне Ядро. Відтоді могутній Рагнарос спить під цією горою. $B",  -- db:5011
[148891831] = "Ми, його вірні слуги, виконуємо його волю та забезпечуємо дотримання його залізного правління. Відрізаний від енергій свого вогняного царства, Рагнарос є лише тінню свого справжнього «я». Проте у нього більш ніж достатньо сили, щоб стати вашою загибеллю. $B",  -- db:5012
[689564499] = "Доброго дня, $gsir:ma'am;. Я б потиснув вам руку, але, як бачите, я зараз зайнятий. Чим можу допомогти?",  -- db:5013
[359018877] = "Ти добре розпочав, але тобі ще багато чого треба навчитися, $N.",  -- db:5014
[311130009] = "Ти вже вивчив усе, чого я міг тебе навчити, $N. Якщо хочеш продовжити навчання, звернися до нічної ельфійки Лілісії Найтбріз у Кварталі магів у Штормовії. Кажуть, вона — хороший викладач.",  -- db:5015
[666323999] = "Зачинений у цьому маленькому будиночку, я мрію приєднатися до битв, що вирують за міськими стінами. Проте обов’язок змушує мене ділитися своїми знаннями з тими, хто бореться замість мене… поки що.",  -- db:5016
[227861950] = "Ішну-алах, $gbrother:sister;. Чи є у тебе якісь звістки з-за кордону? Моє серце прагне новин про Телдрассіл.",  -- db:5019
[501583133] = "Для мене велика честь поділитися з тобою, $N, своїми знаннями. Постарайся їх правильно застосувати.",  -- db:5020
[901526575] = "Тобі слід обрати більш досвідченого вчителя, адже ти вже перевершив мої здібності. Раджу тобі поговорити з Лілісією Найтбріз, яка тут присутня: вона може поділитися з тобою великим багажем знань.",  -- db:5021
[391763094] = "Друїди кажуть, що це лише питання часу, коли сама природа вижене Орду з Калімдору. Проте розпад продовжує поширюватися нашими землями, навіть тут, у Телдрасілі.",  -- db:5022
[183510263] = "Молодець! Ти все краще розбираєшся в зіллях.",  -- db:5023
[760865218] = "На жаль, я мало що можу навчити людину з таким досвідом, як ти, друже. Звернися до нічної ельфійки Сильванни Форестмун, яка мешкає на Терасі ремісників у Дарнассусі.",  -- db:5024
[178065943] = "Elune-adore, мій $брат:сестра;. Ти тут завжди бажаний гість. Говори, і я зроблю все, що в моїх силах, щоб тобі допомогти.",  -- db:5025
[167616660] = "Хіба не дивно, що можна створити з лісових рослин? Справді, Елуна обдарувала нас своєю щедрістю.",  -- db:5026
[549263179] = "Дуже мило з вашого боку, що ви мене знайшли, але ваші навички набагато вищі за мої. Поговоріть із Сильванною Форестмун — вона там, неподалік. Вона саме шукає ще одного учня.",  -- db:5027
[857688306] = "Може, моя мила дівчинка Калі послала тебе до мене? Вона — зіниця мого ока.",  -- db:5028
[563631523] = "Напевно, ти прийшов не для того, щоб поговорити про мою чарівну Калі. Ну що ж, тоді. Тож поговоримо про зілля. Тобі хтось колись казав, що ти думаєш тільки про одне?",  -- db:5029
[746708931] = "Я не в змозі тебе навчити, $N. Іди потурбуй Таллі Берріфіз; вона — гномка, яка живе в Тінкер-Тауні в Айронфорджі. А, і оскільки ти все одно туди прямуєш, передай Калі мої вітання.",  -- db:5030
[252059480] = "Не дай тим великим, невинним очам ввести тебе в оману. Таллі — справжній експерт: я щодня дізнаюся щось нове. Як ти думаєш, чому я тут, у Тінкер-Тауні? Я, на твою думку, схожий на інженера? Так, я й не думав, що схожий.",  -- db:5031
[287965524] = "Постарайся, $glad:lass;. Важка праця та рішучість — ось що потрібно! Не дозволяй нікому втовкмачувати тобі, що книжкової мудрості — це все, що тобі потрібно.",  -- db:5032
[328722605] = "Ой, я тобі нічого навчити не можу, $N. Поговори з Таллі Берріфіз, що стоїть он там. Вона ледь дотягується до столів, але коли починає варити зілля — бережися!",  -- db:5033
[645908304] = "Ти виглядаєш як людина, яка прагне пригод. А я вже наївся їх до того, як ми, тролі, приїхали сюди. Тепер я живу одним днем і навчаю інших, як справлятися з пригодами замість мене.",  -- db:5034
[799656103] = "Готові до чергового уроку? Ну що ж, тоді. По-перше, розслабтеся. Щоб правильно розмішати зілля, треба бути розслабленим.",  -- db:5035
[942044356] = "У тебе є питання, але вони занадто складні, щоб я міг на них відповісти, $N. Тобі треба поговорити з орком Єлмаком у районі «Драг» в Оргримарі. Він тобі допоможе.",  -- db:5036
[174580753] = "Усі пляшки на цьому столі — це зілля, яке я зварив сьогодні. А кажуть, що коли дивишся на каструлю, вода ніколи не закипає. Ха!",  -- db:5037
[805219994] = "Вони називали мене дурнем, але я їм покажу. Я перевірю кожну свою каструлю і доведу, що всі вони все одно можуть кип’ятити. Так, у мене все виходить! Хто тепер дурень, га? Га!?",  -- db:5038
[720208301] = "Нічим не можу тобі допомогти. Ти знаєш про зілля більше, ніж я. До того ж, мені треба наглядати за казанами. Поговори з Єлмаком, що стоїть он там. Він багато знає про зілля.",  -- db:5039
[816801181] = "Бена працює, немов одержима. Я бачив, як вона день і ніч схиляється над цими зіллями, часто не спаючи й не їдячи. Я розумію, що нашим союзникам-неживим потрібна допомога, але починаю побоюватися, що вона нашкодить собі.",  -- db:5040
[541765969] = "Мабуть, я розбив сотні флаконів, коли тільки почав готувати зілля. Скло було таким крихким у моїх незграбних руках. Сподіваюся, ти будеш обережнішим, ніж я.",  -- db:5041
[569154755] = "Твоя здатність до навчання перевершила мою. Для отримання подальших вказівок тобі доведеться поговорити з Беною Вінтерхуф, яка стоїть он там. Але, будь ласка, не забирай у неї занадто багато часу. Їй потрібен відпочинок.",  -- db:5042
[51662871] = "Приємно бачити знайоме обличчя. Аптекар Йоган не дуже любить базікати, хіба що йому щось потрібно. Він уже занадто довго пробув поза могилою. Кажуть, колись я теж стану таким. Моторошно. Можливо, до того часу мені вже буде байдуже.",  -- db:5043
[985509012] = "Прийшов дізнатися про зілля? Я можу багато чого тебе навчити. Може, я й мертвий, але розум ще не втратив. Поки що.",  -- db:5044
[202650651] = "Я ціную твою компанію, але давай будемо відверті: ти маєш більше досвіду з зіллями, ніж я. Якщо хочеш навчитися, краще звернися до доктора Марша. Він — «Покинутий» і працює в Аптеці Підміста.",  -- db:5045
[263978454] = "Колись, це правда, я був людиною. Те, що в інших обставинах могло б вважатися недоліком, нам, $N, грає на руку, адже я досконало знаю людські слабкості.",  -- db:5046
[981014967] = "Дуже добре. Виріжте ще один шматок м’яса з одного з цих зразків. Давайте перевіримо, чого ви навчилися досі, і потім продовжимо далі.",  -- db:5047
[39119449] = "Твої знання про зілля перевершують мої, але тобі ще багато чого треба навчитися. Піднімися сходами на південний схід і знайди доктора Марша. Він навчить тебе справжньому стражданню… е-е-е. Він — «Покинутий», який продовжить твій вишкіл.",  -- db:5048
[832518215] = "Перестань так на мене дивитися. Може, я й не такий авантюрист, як ти, але це ще не означає, що я не можу мати трохи м’язів. Від такого постійного розмішування руки стають сильними.",  -- db:5049
[613515739] = "Я більше нічого не можу тебе навчити. Хоча я чув про нічну ельфійку, яка, можливо, зможе це зробити. Її звати Айнетіл, і вона мешкає на Терасі ремісників у Дарнассусі.",  -- db:5050
[266946135] = "Вибач, $N, але у мене немає часу на новачків. Тобі потрібен хтось, рівень майстерності якого ближчий до твого. Спробуй звернутися до нічної ельфійки Мілли Файранкори на Терасі ремісників у Дарнассусі.",  -- db:5051
[73341510] = "Хочеш, щоб я тобі допоміг? Звісно. Що тобі потрібно?",  -- db:5053
[131109124] = "Нехай вас не вводять в оману його маленькі очі та густа борода. Восур — талановитий учень і хороший друг, хоч у мене й болить шия, коли я з ним розмовляю.",  -- db:5054
[260825602] = "Е-е-е, ти вже знаєш усе, чого я міг би тебе навчити. Можливо, тобі час поговорити з кимось іншим. Спробуй звернутися до нічної ельфійки Айнетіл на Терасі ремісників у Дарнассусі. У неї справді є талант!",  -- db:5055
[756764203] = "Це чудово, $N. Іди покажи це Восуру, що там стоїть. Він відповість на всі твої запитання.",  -- db:5057
[513880865] = "Хто ти такий і чому мене турбуєш? А, так... студент-алхімік. Зрозуміло. Чим можу тобі допомогти?",  -- db:5058
[763133276] = "Ішну-дал-діб, $N. Ти прийшов сюди в пошуках знань?",  -- db:5059
[808182553] = "Викладання — це не односторонній процес, $N. Навчаючи тебе, я сам дізнаюся більше, і моє розуміння поглиблюється.",  -- db:5060
[276478445] = "Хоча мені приємно, що ви довіряєте моїм здібностям, навчити вас — це завдання, яке виходить за межі моїх можливостей. Вам слід вирушити на Терасу ремісників у Дарнасусі й поговорити з нічною ельфійкою Айнетіл. Вона зможе вам допомогти.",  -- db:5063
[260756875] = "Навіть незначні зміни в складі зілля можуть кардинально змінити його властивості. Терпіння й акуратність, юний друже: вони стануть тобі в нагоді в будь-якій сфері життя.",  -- db:5064
[787189028] = "Мої навички у приготуванні зілля поступаються твоїм. Ти готовий поговорити з Айнетіл — вона там, неподалік. Вона зрозуміє, що ти готовий до подальшого навчання.",  -- db:5065
[134726996] = "Ах, якби знову бути молодим і вперше відкрити для себе чарівні зілля. Дякую, що нагадав мені про це, $N. А тепер іди й поділися цим юнацьким ентузіазмом з тією Міллою Файранкорою.",  -- db:5067
[397872570] = "За довгі роки, $N, я багато дізнався про зілля, і ці знання у твоєму розпорядженні. Тобі залишається лише попросити.",  -- db:5068
[234949870] = "Я зайнятий, $N. Скажи Whuut, щоб він розібрався з цим, що б там не було. Той молодий щець цілий день кипить від злісті. Якщо він ще довго буде так поводитися, то обов’язково комусь нашкодить.",  -- db:5069
[118093137] = "Для мене велика честь познайомитися з тобою, $N, але твої навички у приготуванні зілля перевершують мої. Звернися до доктора Герберта Хелсі, неживого мешканця Аптекаріуму в Підмісті. Відтепер саме він зможе тобі допомогти.",  -- db:5070
[875736297] = "Ти звертаєшся не до того орка. Я не навчаю новачків. Поговори з тим молодим Вуутом... і використовуй прості слова.",  -- db:5072
[221817601] = "Ще один студент, так? Гаразд. Подивлюся, чим зможу тобі допомогти.",  -- db:5073
[398328240] = "У нас із Гліксом є домовленість: він забезпечує мене, а я дбаю про його багатство. Серйозно! Те, скільки цей пірат бере з мене за жалюгідний мішечок пом’ятого «королівської крові»… від цього навіть дорослий гоблін може розплакатися.",  -- db:5074
[862133223] = "У мене є безліч чудових рецептів, які ви можете переглянути, до того ж за зниженими цінами!",  -- db:5075
[682369254] = "Ти в цій справі кращий за мене! Тобі потрібен хтось із ще більшим досвідом, ніж у мене. Це — Айнетіл, нічна ельфійка, яка мешкає на Терасі ремісників у Дарнассусі.",  -- db:5078
[569665539] = "Коли я вперше побачив неживих, я заплакав, бо не міг уявити собі їхнього жаху й самотності. Тоді до мене промовила Мати-Земля; вона співала в моїй крові. І вона сказала мені: «Врятуй їх».",  -- db:5079
[861608426] = "Хіба ти не відчуваєш муки Матері-Землі через її загублених дітей — неживих? Говори швидше, $N. Кожна секунда обходиться мені дуже дорого. Ми мусимо допомогти їм знайти шлях назад до неї!",  -- db:5080
[219842304] = "Я не можу з чистою совістю витрачати час на навчання новачків, коли наші союзники — нежить — так страшенно страждають. Будь ласка, краще поговоріть з Креєм, який стоїть он там; він зможе вам допомогти на даний момент.",  -- db:5081
[904910882] = "Твої навички у приготуванні зілля набагато вищі за мої. Знайди неживого доктора Герберта Хелсі в «Апотекаріумі» Підміста. Він зможе навчити тебе ще більше, і ти зможеш на власні очі побачити тяжке становище його народу.",  -- db:5083
[502001560] = "Ще одне переривання. Як я взагалі маю працювати в таких умовах? Не відповідай; хіба я виглядаю так, ніби мені цікаво, що ти маєш сказати? Чому б тобі замість цього не піти потурбувати пана Всевишнього?",  -- db:5084
[840609880] = "Я, навчати тебе? Та годі — ми обоє знаємо, що я не можу. Річ у тому, що, розумієш, через це навчання страждають мої власні навички. Якщо хочеш навчитися, звернися до доктора Герберта Галсі, Покинутого з Аптекаріуму Підміста.",  -- db:5085
[896846285] = "Не марнуй мій час. У мене є дослідницькі проекти, які старші за тебе. Іди поговори з доктором Мартіном Фелбеном в «Апотекаріумі» Підміста. Він — «Покинутий», і, ймовірно, зможе навчити тебе основам.",  -- db:5087
[905337184] = "Ще один студент. Чудово. Ось чому Лайдон є членом Королівського товариства снобів і займається науковою роботою, а я змушений задовольнятися посадою викладача. Якщо я ще раз отримаю премію за викладання, мені це ніколи не пробачать!",  -- db:5088
[747779326] = "Оскільки Алджернон забезпечує мене всім необхідним, я можу виконувати всю свою роботу тут, не витрачаючи часу на пошуки жодної трави. Якщо мені більше ніколи не доведеться бачити чудеса природи, я не пошкодую про це.",  -- db:5089
[683609324] = "Я більше нічого не можу вам розповісти. Пройдіть крізь арку та спустіться по рампі на південний схід, а потім поговоріть з доктором Гербертом Галсі. Він — «Покинутий», який може навчити вас більш просунутим технікам.",  -- db:5090
[295764051] = "Мені не до вподоби твоя зухвалість — прийти до мене за навчанням. Пройди крізь арку й спустися по рампі на південний схід, а потім поговори з доктором Мартіном Фелбеном. Він — «Покинутий», який може навчити тебе основам.",  -- db:5092
[350725369] = "Прийшов вчитися? Добре. Гадаю, ти не завдаси нашим союзникам великої шкоди, якщо я тебе навчу. Головне, щоб ти справді зміг нашкодити нашим ворогам.",  -- db:5093
[427201474] = "Здається, це зілля з кожним новим приготуванням відновлює все менше шкоди, хоча я використовую ті самі інгредієнти. Висновок може бути лише один: рослини змінюються. Я не можу сказати, чому і на що саме.",  -- db:5094
[271575604] = "Настав час перейти до більш досвідченого наставника. У фортеці «Пір’яний Місяць» у Фераласі мешкає нічна ельфійка Кіланна Віндвіспер. Вона має блискучий розум; без сумніву, вона зможе продовжити ваше навчання.",  -- db:5095
[716857031] = "Твоя майстерність у приготуванні зілля має бути вищою, перш ніж ти зможеш стати одним із моїх учнів. А поки що, можливо, тобі допоможуть Сильванна Форестмун або Мілла Фейранкора — вони там, неподалік.",  -- db:5097
[601269129] = "Ваше навчання просувається добре. Ви маєте пишатися своїми досягненнями.",  -- db:5098
[14904710] = "Ми з колегами збираємо найсмертоносніші речовини, про які нам відомо, і випробовуємо їхній вплив на наших ворогів. Як тільки я отримаю все необхідне, я виготую такі пошесті, яких цей світ ще не бачив.",  -- db:5099
[913116078] = "Неймовірно. Твої зілля свідчать про знання, що не поступаються моїм. Я не можу навчати тебе далі, але поговори з орком Рогваром зі Стонарда в Болоті Скорботи. Він відомий своїми передовими експериментами.",  -- db:5100
[779918960] = "Ти ще не маєш достатніх навичок, щоб навчатися у мене. Підійди до доктора Мартіна Фелбена, що стоїть он там, або піднімися по рампі на південний схід і звернися до доктора Марша. Вони — «Покинуті», і саме вони можуть надати тобі необхідну підготовку.",  -- db:5102
[329911529] = "Готовий до навчання? Тоді намагайся не відставати, $N. Нам потрібно охопити чимало матеріалу.",  -- db:5103
[133696382] = "Колись я вітав темряву, бо вона була сестрою ночі. Тепер же темно постійно, навіть вдень, а ліси благають про їжу. Якщо ми не вживемо заходів якнайшвидше, ця пошесть, що поширюється, охопить весь світ.",  -- db:5104
[308584727] = "Ти прийшов сюди, щоб навчитися мистецтву приготування зілля? Ти помилився, якщо думав, що я надам тобі таку привілею просто так, без заслуг. Іди й не повертайся до мене, доки не набудеш більшої майстерності.",  -- db:5105
[393959101] = "Ваша майстерність свідчить про вашу незмінну прихильність до нашого мистецтва, але я хотів би побачити ще одне підтвердження вашої відданості. Я доручу вам завдання. Виконайте його — і я буду задоволений.",  -- db:5106
[38610111] = "Сам вождь Трал попросив мене приїхати сюди. Для мене було честю виконати його прохання, і це аж ніяк не тягар. Я й не міг би мріяти про краще місце служби, ніж Стонард. Практично всі трави, які мені можуть знадобитися, ростуть тут у болоті.",  -- db:5108
[772800893] = "Хм, що ж, бачу, ти трохи розбираєшся у приготуванні зілля. Однак чи гідний ти стати моїм учнем — це ще належить з’ясувати. У мене є для тебе завдання. Спробуй мене вразити.",  -- db:5110
[446000401] = "Як ти смієш просити мене навчити тебе, черв’яку? На що ти сподівався, ти, роззявлений селюк, — на лекцію про те, як правильно використовувати срібне листя? Геть! Тобі пощастило, що я не побив тебе до втрати свідомості за те, що ти марнуєш мій час.",  -- db:5111
[58416503] = "Тут треба лише трохи підкоригувати... ага, ось так!",  -- db:5112
[151819107] = "Я б навчив тебе, якби міг, але тобі потрібна допомога когось трохи більш… як це сказати? Розумного! Шукай Тріксі Квіксвіч в Айронфорджі. Скажи їй, що тебе прислав Бронк!",  -- db:5113
[343101893] = "Хочеш стати інженером, так? Ну що ж, клянусь Мурадіном, ти потрапив у потрібне місце!",  -- db:5114
[41447198] = "Де мій спінер? Я ж щойно тримав його десь тут...",  -- db:5115
[644339587] = "Твої нинішні здібності перевищують мої можливості як наставника. Тобі слід звернутися за додатковою інформацією до моєї колеги-гномихи Тріксі Квіксвіч в Айронфорджі!",  -- db:5116
[861758627] = "Я з радістю допоможу вам розпочати вашу подорож! Дайте мені лише взяти свій спінер, і ми почнемо...",  -- db:5117
[603544459] = "Я чув, що нова модель Henweigh 6000 незабаром зійде з конвеєра. Я ледь стримую своє захоплення!",  -- db:5118
[248361492] = "Ну... Мені не хочеться це визнавати, але якщо ти хочеш продовжувати тренування, тобі доведеться поговорити саме з моєю сестрою. Я знаю не так багато, як вона... поки що! Вона стоїть біля ракетного автомобіля.",  -- db:5119
[887649148] = "Я б із задоволенням навчила тебе! Покажи моїй сестрі, що не тільки вона знає дещо про інженерію...",  -- db:5120
[646289928] = "Привіт! Мене звати Дженна! А тебе?",  -- db:5121
[881867906] = "Ой, тобі ще стільки всього треба навчитися. Я б навчила тебе всьому, якби могла, але я сама ще вчуся! Чому б тобі не поговорити з Тріксі Квіксвіч в Айронфорджі? Вона допоможе тобі продовжити навчання!",  -- db:5122
[831128042] = "Хочеш потренуватися? Зі мною? Чудово! Єдине, що краще за складання патронів і вибухових пристроїв, — це поділитися цими знаннями з кимось іншим! Давай почнемо!",  -- db:5123
[352519411] = "О, який чудовий день, щоб щось підірвати!",  -- db:5124
[259262925] = "Тобі треба почати вивчати речі, які виходять за межі моїх знань! Поговори з Ліліамом Спаркспіндлом, який стоїть біля того намету. Він підкаже тобі, куди рухатися далі!",  -- db:5125
[745925745] = "Така робота — не для людей зі слабкими нервами. У мене є дядько, який втратив руку! Бідний старий Стампі... У будь-якому разі, якщо ти все ще зацікавлений, я, можливо, зможу тобі дещо показати.",  -- db:5126
[173571045] = "Що? Тобі щось потрібно?",  -- db:5127
[912978959] = "Я тобі не допоможу! Тобі треба звернутися до того, хто займається цим довше, ніж я! Давай подивимося... Ти з Альянсу, тож тобі треба поговорити з Ліліам Спаркспіндл у Штормовій.",  -- db:5128
[8726015] = "Так, я тобі дещо покажу. Побачимо, як у тебе вийде, може, ти мене здивуєш!",  -- db:5129
[28969126] = "(Вдихає, вдихає) Ти це відчуваєш? Хіба можна не ЛЮБИТИ запах жиру?",  -- db:5130
[32732404] = "Боюся, ти для мене занадто сильний, друже! Тобі варто звернутися до Ногга в Оргримарі — він допоможе тобі перейти на наступний рівень!",  -- db:5131
[154365511] = "Я люблю щось майструвати. Звісно, ще більше я люблю щось підривати!",  -- db:5133
[885130525] = "Знаєш, хто справді може тобі дещо показати? Ногг! Знайди його в Оргримарі.",  -- db:5134
[381161876] = "Я дещо знаю. Хочеш, щоб я тобі показав?",  -- db:5135
[628361944] = "Хто сказав, що орки не розумні? Щоб стати інженером, треба мати неабиякий розум!",  -- db:5136
[606263549] = "Знаєш, хто справді розумний? Ногг! Навіть розумніший за мене. Іди скажи Ноггу, що тебе прислав Тунд! Ти знайдеш його біля панелі управління он там.",  -- db:5137
[75406886] = "Думаєш, ти достатньо розумний? Думаєш, у тебе вийде? Давай перевіримо!",  -- db:5138
[985597185] = "«Темна Леді» сказала, що знання стануть нашою найпотужнішою зброєю у цій війні.",  -- db:5139
[548191894] = "Ви готові до великих звершень! Зверніть увагу на Франкліна Ллойда, який стоїть праворуч від мене. Відтепер саме він буде вашим наставником.",  -- db:5140
[480722791] = "Інженерія надасть вам навички та знання, необхідні для того, щоб розгромити ваших супротивників! Дозвольте мені показати вам, як це зробити...",  -- db:5141
[122342540] = "Я ніколи не настільки зайнятий, щоб не поговорити з незнайомцем! Принаймні, майже ніколи...",  -- db:5142
[54772345] = "Ти просуваєшся вгору??? Наразі ти вже вище за мене! Тобі варто поговорити зі Спрінгспіндлом Фізлгіром в Айронфорджі! Він покаже тобі набагато більше, ніж я коли-небудь зміг би!",  -- db:5143
[709254922] = "Я можу показати тобі кілька хитрощів... якщо, звичайно, ти не проти спочатку трохи попрацювати.",  -- db:5144
[356791295] = "Хм, ну, поки що я тобі допомогти не можу! Спочатку тобі треба освоїти основи. Чому б тобі не завітати до Спрайта Джампспрокета у Штормовій!",  -- db:5145
[994237027] = "Чудово! Ти справді такий працьовитий? Ну що ж, давай приступимо, гаразд?",  -- db:5146
[799637146] = "Давай подивимося... чотирнадцять плюс сім, переносимо дві... о, так?",  -- db:5147
[280965489] = "Ну, ти просто мчиш як вітер! Я не можу навчити тебе нічого такого, чого ти ще не знаєш, але Спрінгспіндл Фізлгір точно зможе! Ти знайдеш Спрінгспіндла в Айронфорджі. Удачі!",  -- db:5148
[405878216] = "«Що за що!» Я навчу тебе всьому, що знаю, але спочатку хочу, щоб ти виконав одне невеличке завдання?",  -- db:5149
[368133983] = "Згодом ти зможеш навчитися у мене, але поки що ще рано! Чому б тобі для початку не поговорити зі Спрайтом Джампспрокетом, який сидить праворуч від мене? А коли трохи освоїшся, тоді й звернися до мене!",  -- db:5150
[158341523] = "Ви, безперечно, не розчарували! Тепер, коли ми це з’ясували, можна розпочинати навчання!",  -- db:5151
[343391818] = "Плани щодо створення мого 20-футового шприца для поливання індички майже готові! Тепер мені потрібна лише 20-футова індичка...",  -- db:5152
[199036242] = "Нікому не кажіть, що я це сказав, але навіть я не все знаю! Якщо хочете продовжувати вчитися, вам слід поговорити з власником крамниці, Спрінгспіндлом Фізлгіром.",  -- db:5153
[118411509] = "Тобі доведеться довести, що ти цього вартий, перш ніж я розкрию свої секрети! У мене є для тебе саме те, що треба...",  -- db:5154
[856174708] = "Майже влучили, але не зовсім! Боюся, що спочатку тобі доведеться поговорити з моєю сестрою Джеммою. Коли вона ознайомить тебе з основами, заходь до мене — і я покажу тобі найцікавіше!",  -- db:5155
[747069429] = "Непогано, як для новачка! Гадаю, не завадить, якщо я тобі дещо покажу...",  -- db:5156
[225470647] = "Якби тільки день був на кілька годин довшим...",  -- db:5157
[971846482] = "Ти заслужив право тренуватися під керівництвом інструктора вищого рівня. Зайди туди до мого друга Роксіка.",  -- db:5158
[139980710] = "Кожен день — це випробування, і цей день не є винятком. Якщо ти пройдеш це випробування, я поділюся з тобою частиною своїх знань...",  -- db:5159
[756806970] = "Ти ще не заслужив права тренуватися зі мною. Спочатку підійди до Танда, він біля столу. Повертайся, коли він скаже, що ти готовий!",  -- db:5160
[430755500] = "Ви успішно склали іспит, вітаємо! Тепер ви можете продовжувати навчання.",  -- db:5161
[93359020] = "У мене немає часу на пусті плітки — я професіонал!",  -- db:5162
[558547555] = "Як ти думаєш, чому я міг би тебе навчити? Роксік впорається з цим набагато краще. Ти знайдеш його в Оргримарі. А тепер забирайся геть!",  -- db:5163
[159390490] = "Давай перевіримо, наскільки ти компетентний, гаразд? Якщо ти виконаєш це завдання так, як мені потрібно, я знайду час, щоб навчити тебе!",  -- db:5164
[783614798] = "Це марна трата часу — і мого, і вашого! Якщо хочете розпочати навчання, зверніться до Грема Ван Талена! Він стоїть там, ліворуч від мене.",  -- db:5165
[565896900] = "Якщо мої розрахунки правильні, колесо незабаром вийде з ужитку!",  -- db:5167
[808119308] = "Ви, безперечно, досягли значних успіхів у навчанні. Є лише один інструктор, який може продовжити ваше навчання. Знайдіть Буззека Брекетсвінга в Гаджетзані!",  -- db:5168
[828816185] = "Те, чого я тебе навчу, перетворить твій мозок на желе! Повертайся, коли вже достатньо навчишся!",  -- db:5170
[639639364] = "Чудово, ти довів, що гідний! А тепер перейдемо до наступного етапу твого навчання...",  -- db:5171
[719252758] = "Іноді я дивую навіть самого себе!",  -- db:5172
[196417550] = "Я не можу навчати того, чого сам не знаю! Якби ж тільки знайшовся хтось, хто знає більше за мене... Стривай, а він же є! Звернися до Буззека Брекетсвінга в Гаджетзані!",  -- db:5173
[925798192] = "Гарна спроба, але тобі ще треба набратися досвіду, перш ніж тренуватися зі мною! Повертайся в окопи!",  -- db:5175
[754547557] = "Молодець! Я знав, що мав рацію щодо тебе, хай там що говорили інші. Ха! Я жартую! Гаразд, продовжуй займатися.",  -- db:5176
[414043477] = "Я працюю над розробкою способу підземного транспортування нафти між великими містами, але всі кажуть мені, що це лише мрія.",  -- db:5177
[463454057] = "Покажи, на що ти здатний! Ти не пошкодуєш, обіцяю!",  -- db:5179
[418068472] = "Я ніколи не відмовив би тому, хто готовий тренуватися зі мною. На жаль, ти ще не готовий! Тобі ще є над чим працювати, хлопче!",  -- db:5180
[144073040] = "Вітаю, мандрівнику! Що привело тебе до моїх дверей?",  -- db:5181
[72252037] = "Боюся, що людині з вашим досвідом мені немає чого навчити. Але ви ще не дійшли до кінця шляху. Поговоріть із Луканом Корделлом, який стоїть за прилавком. Він допоможе вам пройти наступний етап вашої подорожі.",  -- db:5182
[293556553] = "Хм... що ж, ти здаєшся досить здібним. Якщо ти справді прагнеш навчитися, то ніщо не стане тобі на заваді! Я допоможу тобі зробити перші кроки на цьому шляху, який, сподіваюся, буде довгим і насиченим.",  -- db:5183
[439982676] = "Є й інші способи зміцнити сталь, окрім молота та кузні, юний мандрівнику.",  -- db:5184
[281372865] = "Ти справді чудовий чарівник! А тепер тобі час рушати далі. Я хочу, щоб ти поговорив із Гімблем Тістлфаззом, який перебуває нагорі. Він трохи дивакуватий, але відтепер саме він вкаже тобі правильний шлях!",  -- db:5185
[721027984] = "О, ти ж допитливий, чи не так? Чудово! Слухай уважно — це може врятувати тобі життя, коли справа дійде до найгіршого!",  -- db:5186
[21255667] = "Богиня наділила мене мудрістю, незнайомцю. Якщо це її воля, я передам її тобі.",  -- db:5187
[127453000] = "Твої вміння виходять за межі моїх можливостей. Настав час тобі взятися за нові виклики. Таладан допоможе тобі підготуватися. Він стоїть біля того столу.",  -- db:5188
[293174283] = "Я навчу тебе всьому, на що здатна. Кожен урок — це дар від самої Богині. Використовуй її дари з розумом, і ти не спіткнешся.",  -- db:5189
[437256330] = "Таємниць Елуни безліч, але їх не можна розкривати кому завгодно.",  -- db:5190
[192282637] = "Ти справді досягнув значних успіхів у вивченні магії чарів. Якщо ти готовий, тобі ще є чому навчитися. Поговори з Таладаном на Терасі ремісників у Дарнассусі.",  -- db:5191
[21928109] = "Відкрий свій розум, мандрівнику, і ми почнемо.",  -- db:5192
[935204987] = "Мені немає часу гаяти, незнайомцю. Скажи, що тобі потрібно, або забирайся геть!",  -- db:5193
[921401537] = "Ну що ж, раз ти вже дійшов аж сюди... підійди до Лавінії Кроу, вона стоїть біля тієї книжкової полиці. Якщо не налажаєш у стосунках з нею, то, можливо, дізнаєшся ще щось нове.",  -- db:5194
[523686655] = "На мій погляд, ти не виглядаєш нічим особливим, але хто знає, може, десь там у тобі ховається чарівник!",  -- db:5195
[322131318] = "Чого б я не віддав, аби опинитися на відкритих рівнинах у такий день... але обов'язок мене стримує.",  -- db:5196
[81461453] = "Я не можу навчити тебе нічого такого, чого ти ще не знаєш. Проте знання мого батька набагато перевершують мої. Зайди всередину й поговори з ним. Удачі!",  -- db:5197
[416944710] = "Існує безліч таємниць, які можна розкрити, проявивши терпіння та рішучість. А тепер давайте почнемо...",  -- db:5198
[256590011] = "Тром-ка! Що ти шукаєш, незнайомцю?",  -- db:5199
[815253124] = "Ви потрапили не туди. Зверніться до експерта Годана, який стоїть он там. Від нього ви дізнаєтеся більше.",  -- db:5200
[182647910] = "Загинути в бою — це славно! Але, завдяки тому, чого я вас навчаю, можливо, ви не загинете так швидко, га?",  -- db:5201
[146697777] = "Хто ти? Чого ти від мене хочеш?",  -- db:5202
[793213236] = "Я що, на мою думку, виглядаю як Великий Пооба чарівників? Твоїм навичкам потрібне керівництво Майстра! Знайди Кітту Фаєрвінд у Вежі Азори.",  -- db:5203
[52286835] = "Чудово, давайте почнемо... ха! Обдурив вас! Ви ж не думали, що все буде так просто. Вам доведеться довести свою мужність, як і всім іншим!",  -- db:5204
[368487123] = "Ти жартуєш, правда? Гадаю, ти шукаєш ІНШОГО маленького хлопця — Тоніса Пілларстоуна. Він внизу. А тепер забирайся звідси!",  -- db:5205
[157724395] = "Гаразд, ну що ж??? Не задирай носа! Але оскільки ти вже довів свою компетентність, то тепер можемо починати!",  -- db:5206
[747963260] = "Якщо у вас є все необхідне, я з радістю покажу вам, як це зробити.",  -- db:5207
[229406704] = "Справжній професіонал знає свої межі, і я не соромлюся визнати, що твої вміння перевершують мої. Я хочу, щоб ти завітав до Кітти Фаєрвінд у Вежі Азори. Вона має чудову репутацію, і це цілком заслужено.",  -- db:5208
[803021506] = "Ви виглядаєте впевнено. Напевно, ви не проти перевірити свої вміння?",  -- db:5209
[797502737] = "Ти ще не готовий. Поговори з Бетті Квінн — вона стоїть біля тих сходів. Повертайся до мене, коли досягнеш вищого рівня просвітлення.",  -- db:5210
[225911112] = "Твоя впевненість цілком виправдана, мандрівнику. Тепер може розпочатися твоя справжня освіта!",  -- db:5211
[963243331] = "Якщо ви збираєтеся полювати на нагу, то вам знадобиться будь-яка допомога, яку тільки можна отримати. На великій глибині ви можете знайти тріщини, з яких виходять бульбашки повітря, яких вистачить, щоб дихати під водою. Підпливіть ближче, щоб скористатися цими бульбашками.",  -- db:5212
[896939062] = "Це правда, що я маю навички, якими можу поділитися з тими, хто цього заслуговує. Можливо, це саме ти?",  -- db:5213
[562457405] = "Ти — винятковий чарівник. Боюся, що це виходить за межі моїх здібностей як вчителя. Знайди Кітту Фаєрвінд у Вежі Азори. Лише вона зараз може стати твоїм наставником.",  -- db:5214
[58006969] = "Я вірю, що ви впораєтеся з цим завданням. Чи приймете ви цей виклик?",  -- db:5215
[85476505] = "Ти ще не опанував ази, мандрівнику. Ти вже розмовляв з моєю помічницею, Лаліною Саммермун? Можливо, тобі варто це зробити.",  -- db:5216
[987814003] = "Чудова робота! Ти справді гідний тих знань, якими я тебе наділю!",  -- db:5217
[118826357] = "Якщо ви шукаєте справу, яка принесе справжнє задоволення, то життя, присвячене чарівності, — саме для вас!",  -- db:5218
[599457821] = "Я знаю багато чого, незнайомцю, але твої знання не поступаються моїм. Відомо, що чарівники, які бажають ще більше вдосконалити свої навички, вирушають до Вежі Азори, де мешкає майстриня на ім’я Кітта Фаєрвінд.",  -- db:5219
[213401434] = "Давай подивимося, на що ти здатний! Якщо ти виконаєш це завдання, я з радістю продовжу твою підготовку!",  -- db:5220
[49306743] = "«Enchanting» передається в нашій родині з покоління в покоління. Я навчилася цьому ще в дитинстві, так само, як зараз це робить мій син.",  -- db:5223
[818694536] = "Є одна людина, чиї знання перевершують мої. Ти готовий відправитися на її пошуки. Звернися до «Сан-Рок-Ретріт» у горах Стоунталон. Знайди Хгарта і продовжуй своє навчання.",  -- db:5224
[703665079] = "Я незабаром навчу тебе. Але спершу я хочу, щоб ти довів свою відданість.",  -- db:5225
[8161252] = "Напевно, Мот не відправив тебе до мене? Він же знає краще. Ти ще не здатний зрозуміти те, чого я хотів би тебе навчити. Звернися до мого сина Мота, який чекає там, за дверима, і заверши навчання разом з ним.",  -- db:5226
[770922555] = "Ага, чудово. Я переконався, що ти гідний учень. Тож, можемо розпочинати твоє навчання зі мною???",  -- db:5227
[991145621] = "До мене не часто заходять відвідувачі. Ви шукаєте щось конкретне, так?",  -- db:5228
[159451072] = "Якби я не сидів тут день у день, я б вже досяг того рівня майстерності, який потрібен для навчання таких, як ти! На жаль, це не так. Іди поговори з Хгартом у «Сонячній скелі» в горах Стоунталон.",  -- db:5229
[743697228] = "Хм, ти мені — я тобі. Якщо ти зробиш те, про що я прошу, і зробиш це добре, то, можливо, ми зможемо обговорити твоє навчання.",  -- db:5230
[37550828] = "Ні, ні, тобі знадобиться НАБАГАТО більше підготовки, перш ніж ти будеш готовий навчатися у мене! Іди поговори з тим занудою-дилетантом Малкольмом Вінном. Це той, що там занурився в книги.",  -- db:5231
[303778364] = "Ну, я бачив і краще. Але у тебе є потенціал, не буду заперечувати. Приділяй більше уваги — і, можливо, ти чогось навчишся!",  -- db:5232
[196702175] = "Вітаємо, мандрівнику! Хочеш заглибитися в таємниці магії? Гм?",  -- db:5233
[433569289] = "Деякі мандрівники вважають, що зачарування не діє. Я помітив, що коли я кидаю їм виклик на бій, вони змінюють свою думку!",  -- db:5238
[396456288] = "Твої навички набагато вищі за мої, незнайомцю. Поговори з Хгартом у «Сонячному скельному притулку» в Горах Стоунталон. Він поділиться з тобою більшою кількістю знань, ніж я.",  -- db:5239
[786570478] = "Можливо, у вас є все необхідне. Давайте це з’ясуємо!",  -- db:5240
[481615109] = "Ти не підходиш для тренувань зі мною, незнайомцю. Потренуйся трохи з моїм помічником Джагом, який стоїть он там.",  -- db:5241
[563893081] = "Молодець! У твоїх очах горить той вогник — я його добре знаю, це той самий вогник, що горів у мене, коли я був ще цуценям! А тепер давай подивимося, чи зможу я тебе чомусь навчити.",  -- db:5242
[585924770] = "Що привело вас до Вежі?",  -- db:5243
[174285936] = "Ти майже досягнув вершини свого навчання. Щоб стати найкращим чарівником, яким тільки можеш бути, тобі потрібно знайти ще одного наставника. Її звуть Аннора, і ти можеш знайти її в Улдамані.",  -- db:5244
[527168850] = "Ти сповнений ентузіазму — це добре. Однак ти ще не готовий тренуватися з такими, як я.",  -- db:5246
[194952070] = "Твої навички справді стають надзвичайними. А тепер давай продовжимо твоє навчання...",  -- db:5247
[491657355] = "Ви прийшли, щоб здобути знання про Хгарта?",  -- db:5248
[391968133] = "Є лише одна людина, чиї вміння перевершують мої. Ти готовий засвоїти її знання. Це Аннора, і ти зможеш знайти її... в Улдамані.",  -- db:5249
[63854523] = "Тренуйся наполегливо, тренуйся щодня. А коли вдосконалиш свої навички, повертайся до мене.",  -- db:5251
[766462991] = "Ви досягли нових висот на своєму шляху до досконалості. Давайте подивимося, чи зможемо ми допомогти вам просунутися ще далі...",  -- db:5252
[276404344] = "Вітаю, мандрівнику! Я безмежно вдячний тобі за те, що ти позбавив нас від цих жахливих істот! Я вже почав думати, що, можливо, доведеться ховатися до кінця життя!",  -- db:5253
[953609280] = "Ваша освіта майже завершена. Лише одне останнє завдання стоїть між вами та увінчанням усіх ваших зусиль.",  -- db:5255
[666948419] = "Є ще уроки, які ти повинен засвоїти від інших, перш ніж я зможу поділитися з тобою своїми знаннями. Будь старанним і не втрачай надії.",  -- db:5256
[134293059] = "Відколи мій чоловік пішов на фронт, ця Хелен стала для мене опорою. Її добре серце та гострий меч допомогли мені пережити чимало важких часів. Не знаю, що б я робила без неї.",  -- db:5257
[544459399] = "Ой, вибач. Я не можу навчити тебе нічого нового. Може, тобі варто поговорити з Саймоном Таннером у Старому місті Штормовію? Він — людина з потужними м’язами та чарівним рудим волоссям.",  -- db:5258
[100589900] = "Як справи? Я обожнюю запах шкіри, а ти?",  -- db:5259
[817691909] = "Я вже багато знаю про стиль. Тепер залишилося лише освоїти техніки роботи зі шкірою. Добре, що Саймон з радістю допомагає мені їх опанувати.",  -- db:5260
[443667875] = "Я нічого не можу тебе навчити, хіба що, можливо, розвинути твоє відчуття кольору та уваги до деталей. Поговори з Саймоном Таннером, що стоїть он там; він знає багато складних технік роботи зі шкірою.",  -- db:5261
[633469753] = "Цей наряд дійсно підкреслює блакитний колір моїх очей, чи не так? Мабуть, очевидно, що у мене вистачає майстерності на всіх, тож я можу дозволити собі поділитися кількома своїми професійними секретами. Слухайте уважно, добре?",  -- db:5262
[994174240] = "Ласкаво просимо до нашого дому, $N. У нас з Раднаалом небагато чого запропонувати, але ми раді прийняти вас і надати вам ту гостинність, на яку здатні.",  -- db:5263
[618320443] = "Вибачте, але ви вже дізналися все, що я знаю. Проте нічний ельф Фалдрон міг би надати вам подальше навчання. Шукайте його на Терасі ремісників у Дарнассусі.",  -- db:5264
[853607694] = "Вам потрібно зменшити розмір стібків, $N. Тоді з ваших колчанів і патронташів випадатиме менше речей. До того ж, нікому не подобається нерівна туніка.",  -- db:5265
[24166960] = "Якщо вас цікавить шиття зі шкіри, то ви, безперечно, потрапили за правильною адресою. Фалдрон і Телоніс — справжні майстри своєї справи, і я сподіваюся багато чому навчитися у них.",  -- db:5273
[619627255] = "Ой, вибачте, але на даний момент ви знаєте про шкіру більше, ніж я. Якщо хочете дізнатися більше, поговоріть з Фалдроном, який стоїть он там.",  -- db:5274
[45849968] = "Як же це захоплююче — бути тут, у Дарнасусі, в оточенні талановитих людей! Я просто впевнена, що моя родина буде мною пишатися. Можливо, якщо мені справді пощастить, «Стражі» запросять мене приєднатися до їхніх військ на фронті!",  -- db:5275
[313132721] = "Ця шкура ще не готова до обробки. Якби ж то виготовлення шкіри не займало стільки часу. Має ж бути якийсь спосіб скоротити все це очікування. Це, знаєте, не може йти на користь моєму здоров’ю.",  -- db:5276
[985422226] = "Ой, яка ж невдача! Мої навички недостатньо високі, щоб бути тобі корисними. Ну що ж. Поговори з Фімблом Файнспіндлом, який стоїть там біля ткацького верстата. Він працює зі шкірою набагато довше, ніж я.",  -- db:5277
[597530713] = "О, чудово, ще одне заняття, поки я чекаю! Ти — справжній рятівник, $N!",  -- db:5278
[63495344] = "Тобі подобається килим? Я сам вбив і зняв шкуру з цієї тварини. Нехай усі кентаври гинуть так само легко.",  -- db:5279
[46791081] = "Мені більше нічого тебе навчити. Якщо хочеш вдосконалити свої навички роботи зі шкірою, звернися до Каролека.",  -- db:5280
[485806264] = "Шкода, що ми не можемо зняти шкіру з людей та їхніх союзників. Уся ця шкіра просто пропаде даремно. Хоча, хто б захотів носити ту тоненьку шкіру, яку з неї можна було б зробити?",  -- db:5281
[54918697] = "Шкіра, чудова шкіра. Вона утримує твої внутрішні органи… всередині. Ти, мабуть, помітив, що з моєю шкірою не все гаразд. А ще недавно я переймався своїми порами. Зараз майже не залишилося шкіри, про яку можна було б турбуватися. У певному сенсі це дуже звільняє.",  -- db:5282
[301261277] = "Ти вже все освоїв. Я більше нічому тебе навчити не можу, але поговори з Артуром Муром — Покинутим, який працює в «Кварталі розбійників» у Підмісті. Скажи йому, що я тебе послав.",  -- db:5283
[739097065] = "До того, як спалахнула чума, я нічого не знав про шкіру. Тепер я знаю достатньо, щоб навчати інших. Смерть залишила мені багато вільного часу.",  -- db:5284
[841191431] = "М'ясо, шкура, кістки... справжній мисливець нічого не марнує. Кожен шматочок шкіри можна використати, наприклад, для зміцнення обладунків союзника. Отже, кожен з нас сильний сам по собі, але разом ми стаємо непереможними.",  -- db:5285
[312509062] = "Ти вже переріс усі настанови, які я міг би тобі дати. Рушай з благословенням Матері-Землі. Знайди таурена Тарна в північно-західних крамницях центрального плато Грім-Скелі. Довіряй його мудрості.",  -- db:5286
[73192176] = "Ми живемо і вмираємо, а земля залишається вічною, незворушною перед нашим приходом і відходом. Отже, земля не може належати нам, $N. Натомість ми належимо їй. Тому ми захищаємо землю, адже без неї ми не можемо сподіватися на виживання.",  -- db:5287
[795892816] = "Печери під нами — джерело дивних і дивовижних шкур, але, $N, тобі слід бути обережним, якщо ти наважишся заглибитися в їхні глибини. Пам’ятай, що твоя власна шкіра набагато цінніша.",  -- db:5288
[719453273] = "Ваше розуміння шкіри глибше, ніж моє. Можливо, вам варто відвідати таурена Крулму Фулмуна в таборі Таураджо в Пустках. Він може поділитися великим багажем знань із таким талановитим учнем, як ви.",  -- db:5289
[70879955] = "Кажуть, що сам Керн живе тут. Як тільки я закінчу виготовляти гідний подарунок, я піду до нього. Можливо, він поділиться зі мною мудрими словами.",  -- db:5291
[532224877] = "Твій талант перевершує мій, друже. Поговори з Тарном; його знання про шкіру набагато глибші за мої. Я впевнений, що він із радістю прийме ще одного учня.",  -- db:5292
[338921254] = "Перед початком будь-якої роботи ретельно вимийте руки. Плями крові чи бруду на шкірі зіпсують її природну красу.",  -- db:5293
[340761375] = "Коли я вибрався з могили, я думав, що моя родина зустріне мене з розпростертими обіймами. Натомість вони вигнали мене з села, кричачи мовою, яку я вже не міг зрозуміти.",  -- db:5294
[215944073] = "Я не можу тобі допомогти; твоя робота виходить за межі моїх компетенцій. Поговори з Артуром Муром — він там, біля трун. Він зможе навчити тебе всьому необхідному.",  -- db:5295
[625934808] = "Запам’ятайте кожне моє слово. Доки наші вороги не будуть знищені, ми ніколи не повинні упускати нагоди розширити свої знання. Зміцнюйте свою броню й ніколи не втрачайте пильності.",  -- db:5296
[253594753] = "Ти виходиш за межі моїх обмежених здібностей. Знайди нічну ельфійку Айнетіл на Терасі ремісників у Дарнассусі. Вона зможе навчити тебе більше. Якби ж я міг піти з тобою...",  -- db:5314
[750363405] = "На цьому етапі мої знання будуть для тебе занадто складними. Якщо ти хочеш дізнатися більше про зілля, краще поговори з Тел’Атіром, який тут знаходиться.",  -- db:5316
[737958038] = "Слухай уважно, $N, бо я маю багато знань, якими хочу поділитися.",  -- db:5317
[842219150] = "Навіть у мене є свої обмеження! Якщо хочеш продовжити навчання, звернися до Лавінії Кроу в Андерсіті.",  -- db:5318
[258289376] = "Непогано... Гадаю, навчити тебе — цілком реально. Чудово! Почнемо...",  -- db:5319
[21339085] = "Рендал — трохи денді, але на нього можна покластися, чого не скажеш про багатьох студентів, яких я беру під свою опіку. Хоча, мабуть, не можу їх звинувачувати за те, що вони прагнуть трохи пригод.",  -- db:5320
[225898212] = "Вибач, але ти досяг межі того, чому я можу тебе навчити. Якщо хочеш дізнатися більше, звернися до Телоніса на Терасі ремісників у Дарнассусі. Кажуть, він досить талановитий.",  -- db:5321
[245705265] = "Звернися до мене, коли пройдеш додаткове навчання. Рендал Ворт, який сидить он там, зможе тобі в цьому допомогти.",  -- db:5323
[766836092] = "Хм, мабуть, я можу взяти ще одного учня. Ну, не стій просто так. Розкажи мені, чого ти хочеш навчитися.",  -- db:5324
[563130388] = "Даріанна має великий потенціал, але вона настільки сповнена енергії, що їй важко сидіти на місці й слухати. З огляду на її силу та спритність, боюся, що незабаром її покличуть на бій. Ми мусимо швидко навчити її.",  -- db:5325
[917189936] = "Якщо ви прийшли сюди для подальшого навчання, то ви переоцінили мої здібності. Поговоріть з Телонісом, що стоїть он там; він зможе вам допомогти.",  -- db:5326
[310267974] = "Згодом ти будеш готовий до того, чому я маю тебе навчити, $N. А до того часу, будь ласка, попроси Даріанну, яка стоїть он там, допомогти тобі з тренуванням.",  -- db:5328
[348234549] = "Багато тварин пожертвували своїм життям, щоб ми могли отримати ці матеріали. Не ставтеся до їхньої жертви легковажно, $N. Ставтеся до шкіри з повагою, на яку вона заслуговує.",  -- db:5329
[941724604] = "Стільки справ! Я ще ніколи не був таким зайнятим, відколи мій кузен випадково випарував усю тканину та шкіру в Гномерегані. Ой, як же там тоді було прохолодно! Ах, $N, ось це були часи...",  -- db:5330
[458987085] = "Ні, боюся, що не можу тобі допомогти. Твої навички набагато кращі за мої! Якщо хочеш дізнатися більше, поговори з нічним ельфом Телонісом на Терасі ремісників у Дарнассусі. Він просто неймовірний!",  -- db:5331
[449037450] = "О, ну й диво! Це ж новий учень! Я з радістю навчу тебе всьому, що знаю, як тільки ти трохи вдосконалиш свої навички. Підійди-но до Грети Файнспіндл, що стоїть он там, гаразд? Вона вмить введе тебе в курс справи.",  -- db:5333
[745455561] = "Твої навички добре розвиваються. Незабаром ти відкриєш власний магазин шкіряних виробів. Буду радий твоїй допомозі, $N. Ти ж знаєш, мої руки не такі вже й швидкі. А роботи стільки!",  -- db:5334
[546875477] = "Найміцніші шкури отримують від тих кодо, які знайшли вічний спокій на цій пустці.",  -- db:5335
[463357466] = "Я не можу допомогти тобі з подальшими уроками: твої навички вже перевершили мої. Звернися до тауренки Уни, яка знаходиться в північно-західній частині крамниць на центральному плато Грім-Блаффа. Вона пропонує більш просунуте навчання.",  -- db:5336
[587934713] = "Я не проводжу навчання учнів. Зверніться до таурена Вальдора в «Печерах Плачу», що тут, у Пустошах. Він допоможе вам у будь-якому питанні.",  -- db:5338
[229119447] = "Ви приїхали на підвищення кваліфікації? Тоді струсіть з одягу дорожній пил і давайте приступимо до роботи.",  -- db:5339
[374021745] = "Моя сокира бачила чимало битв, і я люблю тримати її під рукою. Ворожі війська вже кілька разів проривалися до нашої столиці, але не бійтеся: ми завжди відбивали їхні атаки.",  -- db:5340
[104430697] = "Я не можу допомогти тобі з подальшим навчанням: твої навички роботи зі шкірою не поступаються моїм. Тобі слід поговорити з Уною, вона там. Якщо буде потрібно, я поручуся за твої навички.",  -- db:5341
[859118100] = "Твої навички недостатні для того, щоб освоїти те, чому я навчаю. Спробуй краще поговорити з Маком, який сидить он там. Він зможе тобі допомогти, поки ти не будеш готовий до більш просунутих уроків.",  -- db:5343
[346152969] = "Я задоволений вашими досягненнями на сьогодні. Безперечно, Мати-Земля надихнула ваші руки.",  -- db:5344
[45827946] = "Наразі ми маємо лише невеликий плацдарм на цьому континенті, але люди не зможуть відбивати наші атаки вічно. Тоді вони заплатять за те, що поневолили нас. Ми виріжемо їхні брехливі язики за зраду.",  -- db:5345
[644251029] = "Я б навчив тебе, якби міг, але ти для мене занадто складний випадок. Ось що: піди поговори з тауреном Уною в північно-західних крамницях центрального плато Грім-Блаффа. У неї справжній талант.",  -- db:5346
[669140823] = "У тебе більше сміливості, ніж розуму, якщо ти прийшов до мене без належної підготовки. Іди поговори з кимось, рівень майстерності якого ближчий до твого, наприклад, з орком Камарі, який живе в районі «Драг» в Оргримарі.",  -- db:5348
[275651342] = "Я зайнятий? Що це взагалі означає? Ти що, думаєш, я просто цілий день тут стою, розводивши руками? Якщо ти прийшов щось купити, звернися до Хандора.",  -- db:5350
[636082919] = "Від мене ти нічого нового не дізнаєшся — ти й так уже занадто багато знаєш. Якщо хочеш пройти додаткове навчання, звернися до тауренки Уни, яка перебуває в північно-західних крамницях на центральному плато Громового Уступу. Передай їй від мене привіт, га?",  -- db:5351
[565656764] = "Ви не зможете освоїти мої техніки, поки не опануєте основи. Якщо вас цікавить навчання, зверніться до Камарі.",  -- db:5353
[378729825] = "Лабіринти Оргримара створені для того, щоб заважати загарбникам. Уявляєш, як швидко один із тих кволих гномів тут заблукав би? Ха! Якщо йому пощастить, я його знайду і залишу собі як домашнього улюбленця.",  -- db:5354
[45249724] = "До своєї смерті я була бібліотекаркою; я не мала ніякого стосунку до воєн та епідемій. Я ніколи не просила, щоб зі мною так сталося. З іншого боку, тепер, коли я знову володію своїм розумом, я не збираюся здаватися без бою.",  -- db:5355
[104477296] = "Мені приємно визнати, що твої таланти перевершили мої. А тепер йди. Е-е-е, спробуй звернутися до тауренки Уни в північно-західних крамницях центрального плато Грім-Блаффа. Запевняю тебе, вона дуже вправна.",  -- db:5356
[946301344] = "Якби я навчав початківців, до мене приходило б набагато більше учнів, і тут стало б гамірно. Підійди-но поговори з Деном Голтасом, ось там. Він трохи занадто запальний, але має добрі наміри і є непоганим викладачем.",  -- db:5358
[547182732] = "Спочатку я влаштував свою крамницю в «Чарівному кварталі», але там було досить шумно. Тепер ситуація значно покращилася, за винятком кількох наполегливих студентів, які й досі мене розшукують, незважаючи на те, що я переїхав.",  -- db:5359
[299107242] = "Елуна наділила нічних ельфів багатьма дарами. Натомість ми зобов’язані захищати ці ліси від демонічного зараження, яке завжди несе з собою Орда.",  -- db:5360
[244560694] = "Я не в змозі надати тобі подальше навчання. Звернися до Телоніса на Терасі ремісників у Дарнассусі. Він завжди радий допомогти талановитим учням.",  -- db:5361
[474113645] = "Я навчаю лише тих учнів, які вже опанували основи. Тобі слід знайти нічну ельфійку Даріанну на Терасі ремісників у Дарнассусі. Її навички стануть ідеальним доповненням до твоїх.",  -- db:5363
[6319575] = "Завжди ретельно перевіряйте розміри, перш ніж починати розкроювати шкіру. Ми не можемо дозволити собі марнувати матеріали.",  -- db:5364
[532987981] = "Вам слід шукати у водах Вестфолла, прямо на захід-північний захід від місця, де кар’єр «Золоте узбережжя» стикається з берегом. Якір вказує на місце, де за ним, глибоко під водою, затонула човен. Підводний тиск тут надзвичайно сильний; якщо заплисти занадто далеко, навіть найсильнішого плавця звалить з ніг від виснаження.  $B$BШукайте природне утворення, яке допоможе вам, $N — неподалік знаходиться бульбашкова тріщина, що дає можливість глибоководним плавцям перепочити та набрати подиху.$b",  -- db:5373
[934979124] = "У Лісі Срібної Сосни, на березі Північної Припливної Річки, на березі лежить занедбаний човен. На захід від нього знаходиться те, що ви шукаєте; якщо попливете занадто далеко, океан знесилить вас від втоми.  Вона лежить на дні океану в сейфі, чекаючи, поки ти її забереш.$B$BТобі буде важко вижити під час занурення на таку глибину без допомоги, тож не впадай у відчай: бульбашкова тріщина дарує нове дихання дайверам, які шукають цю половину кулона.  Використовуй її з розумом.",  -- db:5374
[604935534] = "У північній частині Темного Берега протікає річка Кліфспринг, що спускається з земель, які нині відомі як Фелвуд. Коли річка витікає й впадає в Край Туману, рушайте на північ, туди, де починаються найглибші частини океану.  Саме біля кам'яної формації, яку дехто через її форму називає «Кам'яним Кігтем», ви зможете знайти те, що шукаєте.$B$BБудьте обережні — біля «Кам'яного Кігтя» збираються косарі, які атакуватимуть тих, хто вторгнеться на їхню територію.",  -- db:5375
[892921807] = "У північно-східній частині Пусток розташоване водоймище, забруднене шкідливими речовинами. Місцеві жителі називають його «Болотом шламу»; компанія «Венчур» перетворила колись кришталево-блакитні води на болото, заповнене промисловими відходами та залишками виробництва.  У самому серці цього болота лежить те, що ви шукаєте, $N.$B$BБудьте обережні — компанія «Венчур» не терпить порушників, і вважає такими всіх, хто не працює на неї.  Ви, як захисник природи, станете для них особливою мішенню, адже вони категорично виступають проти цього.",  -- db:5376
[331935733] = "Трава м'яка й соковита. Повітря свіже, сповнене світла й співу. Усе, що я побачила, свідчить про те, що Телдрасіл — це мрія, що збулася. Чому ж тоді моє серце сповнене тривоги?",  -- db:5393
[191231962] = "Твої вміння вже перевищили мої можливості як вчителя. Тепер вирушай до Піку Аері в Глибинних землях і поговори з карликом Дракком Стоунхендом. Його роботи — просто чудові, набагато кращі за мої.",  -- db:5394
[488086798] = "На жаль, мушу сказати, що не можу вам допомогти, $шановний пане:шановна пані;, доки ви не навчитеся краще працювати зі шкірою. Краще поговоріть тут із Фалдроном або Даріанною. Вони зможуть навчити вас необхідним навичкам.",  -- db:5396
[430397084] = "Не намагайтеся нав’язати шкірі свою волю. Натомість дозвольте її природним властивостям визначати, яку форму та функцію вона набуде. Це не битва, яку потрібно виграти. Працюйте зі шкірою, а не проти неї.",  -- db:5397
[972950777] = "Голка маленька, але нитка міцна, а стібки дрібні. Наша угода з Тролом та іншими витримає. Орду не виженуть з цих земель.",  -- db:5398
[207876635] = "Навіть мої здібності мають межу, і ти її досягнув. Вітаю, $N. Твоєю наступною зупинкою має стати табір Моджаче у Фераласі. Там мешкає тауренка Хахрана Айронхайд; вона славиться своєю майстерністю.",  -- db:5399
[525432030] = "Минуло вже так багато часу з тих пір, як я сам був новачком, що, мабуть, я не найкращий вчитель для тебе. Спробуй поговорити з Тарном або Маком — вони ось там. Хтось із них, мабуть, зможе відповісти на твої запитання.",  -- db:5401
[960247314] = "Керн привів нас у країну, сповнену перспектив на майбутнє. Нам пощастило, тож ми, у свою чергу, передаємо це щастя іншим. Ось чому я почав викладати, $N.",  -- db:5402
[390678402] = "З матеріалів, які я знаходжу тут, я можу створювати дивовижні речі. На бороду Мурадіна, у цих пагорбах мешкають фантастичні істоти! Спробуй поборотися з ними, $N, і принеси мені кілька неймовірних історій.",  -- db:5403
[294273326] = "Я люблю цікаві виклики; а ти? Так, звичайно, ти теж. І саме тому ти зараз зробиш саме те, що я скажу.",  -- db:5405
[984515729] = "Я тут не для того, щоб навчати малят, які щойно вилізли з колиски. У вас навіть близько немає тих навичок, яких я вимагаю від своїх учнів. Насправді, ви — жалюгідна фігура, і я був би вдячний, якби ви не стояли там і не базікали на мене.",  -- db:5406
[44755543] = "Усі замовлення на мої роботи покупець повинен робити особисто. Орвін часто просить мене передумати, але мої пріоритети — саме тут. Погляньте навколо: багато з цих бійців покладаються на мене в питанні броні.",  -- db:5407
[458559064] = "Якби ж у мене було більше таких студентів, як ти. Небагато хто наважиться заглибитися так далеко на ворожу територію. Я віддаю шану твоїй хоробрості.",  -- db:5408
[716476835] = "У цій війні ми не можемо дозволити собі поступитися ні на йоту. День і ніч я створюю нову броню та латаю все, що можна врятувати зі старої. У мене немає часу на інші справи. Чи не могли б ви щось для мене зробити?",  -- db:5409
[154167820] = "Ти змарнував і свій, і мій час, прийшовши до мене на навчання, $N. У мене немає часу навчати тебе базовим навичкам. Ми тут ведемо війну, і це одна з ліній фронту. Не повертайся до мене, доки не будеш краще підготовлений.",  -- db:5410
[984459066] = "Я бачу, що твій гардероб дуже потребує догляду.",  -- db:5413
[680360934] = "Я — проста людина, яка трохи розбирається в кравецькій справі, але тобі потрібна допомога, яку я не можу надати. Я чув про нічного ельфа, який є досить досвідченим кравцем. Він мешкає у Штормовій, у Магічному кварталі.",  -- db:5414
[358053688] = "Тож ви хотіли б дещо дізнатися? Я з радістю допоможу вам розпочати!",  -- db:5415
[35663854] = "Життя — це наче ретельно витканий гобелен.",  -- db:5416
[548791116] = "Хм... Те, що тобі треба вивчити, для мене трохи занадто складно. Поговори з Селандусом у крамниці «Larson's Clothiers» — вона знаходиться трохи далі по стежці праворуч. Саме він навчив мене всьому, що я знаю!",  -- db:5417
[665064107] = "Гаразд, нехай ваша подорож у світ кравецької справи розпочнеться.",  -- db:5418
[243694448] = "Рукоділля вимагає твердої руки. І терпіння... насамперед, терпіння.",  -- db:5419
[101202173] = "Настав час вирушити до Дарнассуса й поговорити з Мелінн. Відтепер саме вона буде твоїм провідником.",  -- db:5420
[265324068] = "Я з радістю візьму вас під своє крило. Давайте почнемо.",  -- db:5421
[269587308] = "Ласкаво просимо до мого магазину. Чим можу вам допомогти?",  -- db:5422
[13806440] = "Зачекайте-но, я всього лише помічник. Якщо хочете почати вивчати щось складніше, зверніться до старого Стоунбрю, що стоїть он там.",  -- db:5423
[903268224] = "Чудово! Я саме сподівався на нового учня. Ну що ж, тоді давайте одразу приступимо до справи!",  -- db:5424
[272512366] = "У своїх творах ми використовуємо багато шкур і шкір тварин.",  -- db:5425
[785285153] = "Я дещо знаю, але не є експертом. На щастя для тебе, Магар — експерт. Він стоїть у глибині крамниці. Спробуй звернутися до нього за допомогою, але будь обережним, щоб не роздратувати його. Він може бути дратівливим.",  -- db:5426
[347925802] = "Я навчу тебе всьому, чому зможу.",  -- db:5427
[738520727] = "Жодна частина тварин, на яких ми полюємо, не йде на марне.",  -- db:5428
[607739789] = "Ти прагнеш здобути вищі знання. Тепа володіє такими знаннями. Вона, мабуть, десь неподалік...",  -- db:5429
[853516525] = "З благословення Матері-Землі ми розпочнемо.",  -- db:5430
[733176796] = "Радий познайомитися з вами. Чим можу допомогти?",  -- db:5431
[712484304] = "Я добре розбираюся в цьому, але не є експертом. Знаєте, до кого вам слід звернутися? До Ріаннон! Вона неподалік. Поцікавтеся, де її знайти, в Андерсіті",  -- db:5432
[803214592] = "Отже... ти хочеш стати кравцем? Добре, подивимося, чи вистачить у тебе на це сил.",  -- db:5433
[175099514] = "До нас тут нечасто заходять гості. Може, вам щось зацікавить?",  -- db:5434
[866395054] = "Я, власне, теж лише студент. Експерт — це Ріаннон. Вона стоїть біля тих ящиків. У неї можна багато чого навчитися.",  -- db:5435
[441511579] = "Так, я вважаю, що в тебе є потенціал. Можливо, я зможу навчити тебе дечому.",  -- db:5436
[920348192] = "Немає кращого способу очистити розум, ніж плести.",  -- db:5437
[554311133] = "Я все ще навчаюся, а твої знання перевершують мої. Якщо ти хочеш дізнатися більше, тобі слід поговорити з Мелінн. Вона тобі допоможе.",  -- db:5438
[137413936] = "Ви не будете розчаровані, мандрівнику. Пошиття одягу — це справжня радість.",  -- db:5439
[268068097] = "Привіт, друже, чим можу тобі допомогти?",  -- db:5440
[829864277] = "На даний момент ти знаєш не більше за мене, друже. Може, заглянь до Магара в Оргримарі. Він, може, й не найвеселіший кравець у місті, але тобі все одно допоможе.",  -- db:5441
[402818692] = "Ось це настрій! Бери голку з ниткою — і давай творити!",  -- db:5442
[171334811] = "Боюся, що я вже не є ні лагідним, ні смиренним. Вік і незліченні битви загартували мою шкіру й душу. Можливо, саме тому Керн відправив мене до «Сонячної скелі»… Лагідні вітри й тепле сонце справді полегшують біль.",  -- db:5443
[868812816] = "Вітаємо. Наші кажани добре дресировані та добре годуються. Швидших ви не знайдете.",  -- db:5453
[232887528] = "Чим я можу допомогти?",  -- db:5454
[117273015] = "Вітаю вас і ласкаво прошу. Я не дуже вмію посміхатися, але повірте мені: я радий вам допомогти.",  -- db:5455
[257849092] = "Гіппогриф — це благородна тварина, горда й швидка. Тренувати їх — справжня честь, і вони здатні швидко доправити свого вершника на велику відстань.",  -- db:5473
[942877423] = "Щоб підтримувати зв’язок із материком, між селищем Рут’теран та Темним берегом постійно курсують гіппогрифи.",  -- db:5474
[548713997] = "Риба біля узбережжя Телдрасіля досить велика й міцна.  Ходять чутки, що причиною цього є стрімке зростання нашого нового світового дерева.",  -- db:5475
[649157067] = "Хоча узбережжя Темного берега небезпечніше, ніж узбережжя Телдрасіля, багато рибалок знаходять тут можливість заробити.",  -- db:5476
[785550106] = "Для мене велика честь допомагати мандрівникам, адже вони — майбутні герої.",  -- db:5477
[628564496] = "Найшвидші грифони на цій стороні Піку Аері. Хочете прокотитися?",  -- db:5479
[140563298] = "На північному причалі ви можете сісти на корабель, який доправить вас до селища Рут'терана та Дарнассуса. З південного причалу ви можете дістатися через Велике море до гавані Менетіл на Каз-Модані. Бажаємо вам щасливої подорожі!",  -- db:5480
[632249808] = "Ось цей причал?  Ну, звідси можна сісти на корабель, що пливе до того місця, де живуть нічні ельфи.  Як воно там називається?  Е-е-е... здається, Аубердін.  Я точно не знаю, я просто завантажую й розвантажую речі.",  -- db:5481
[824406113] = "Доставити ці бочки на місце розкопок — важка робота, але так багато людей розраховують на те, що ми доставимо туди вибуховий порошок.$B$BМи мусимо зробити все, що в наших силах, щоб протистояти Темним Залізним!",  -- db:5494
[655911508] = "Мої вітровершники навчені швидко літати у спекотному повітрі Пусток.",  -- db:5495
[871996644] = "«Барренс» із своїм палючим сонцем та ворожими мешканцями — ідеальне місце, щоб випробувати свою силу та витривалість.",  -- db:5496
[58406003] = "Вітаю. Якщо ви завітали сюди за шкіряними виробами, то переконаєтеся, що мої вироби виготовлені з високою майстерністю.",  -- db:5497
[976573189] = "Ви прийшли допомогти з доставкою? Міран уже майже готовий.",  -- db:5498
[144992860] = "Коли його осідлаєш на спині «вітровершника», стає зрозуміло, що його слава як сильного й швидкого створіння цілком заслужена.",  -- db:5500
[385328507] = "Це небезпечна справа!$B$BMіран щойно виїхав з доставкою. Він має повернутися за кілька хвилин.",  -- db:5501
[748498703] = "Ти в цій справі кращий за мене! Тобі потрібен хтось із ще більшим досвідом, ніж у мене. Це доктор Герберт Хелсі — нежить, який працює в «Апотекаріумі» Підміста.",  -- db:5513
[773841164] = "Поглянь на моє м'ясо, друже.  Ти ж не захочеш вирушати в Пустощі без доброго запасу провізії.",  -- db:5515
[794248055] = "Ти не прожив життя, поки не подивився на світ зверху, сидячи на спині вітроверта.",  -- db:5516
[435353245] = "З цього причалу можна дістатися до Терамора.  Прислухайтеся до моїх слів: для представників Альянсу ці землі рідко бувають безпечними для подорожей.  Будьте обережні й пильнуйте за спиною.",  -- db:5517
[817551841] = "Доброго дня.",  -- db:5519
[436904832] = "Ви виходите за межі моїх знань. Джорджіо Болеро, майстер з «Duncan's Textiles», що знаходиться за рогом, міг би допомогти вам удосконалити свої навички.",  -- db:5520
[461673918] = "Поговоріть з Лоуренсом Шнайдером у магазині «Duncan's Textiles», що знаходиться за рогом ліворуч. Він чудово ладнає з новачками.",  -- db:5522
[340977278] = "Чудовий прояв гідності. Тепер ви можете продовжувати своє навчання.",  -- db:5523
[596151024] = "О, ця дарнасська тканина — просто найкраща!",  -- db:5524
[229344489] = "Ну, ти що, такий розумник? Ти знаєш більше за мене, це я тобі скажу! Не задирай носа, але якщо хочеш і далі вчитися, поговори з Джорджіо Болеро у Штормовій. Кажуть, він знається на кравецькій справі!",  -- db:5525
[226950832] = "У мене немає часу на нянькування! Іди поговори з моїм помічником, Утраром!",  -- db:5527
[578155036] = "Хм... у тебе є певний потенціал, це треба визнати. Ну що ж, на чому ми зупинилися?",  -- db:5528
[524269528] = "Чи чуєш ти поклик полювання, $c?  Ти повинен прислухатися уважно, але цей поклик лунає з глибини твоєї душі.  Він лунає з глибини душі кожного з нас.",  -- db:5529
[631664605] = "Багато речей, які ви бачите в магазині, я зробив власноруч. Що скажете? Відповідайте обережно — від цього може залежати ваше життя.",  -- db:5530
[618763873] = "Тобі треба порадитися з кимось, хто знає більше, ніж я. Іди поговори з Йозефом Грегоріаном в Андерсіті. Ну, чого ти ще тут стоїш?",  -- db:5531
[815998950] = "Що? Чому ти мене турбуєш? Гадаю, ти навіть якісного халата створити не зможеш! Іди поговори зі Снангом і повертайся, коли станеш гідним мого таланту!",  -- db:5533
[616341969] = "Вже давно пора було показати мені якісь результати! А тепер я тобі покажу результати!",  -- db:5534
[901788277] = "Кажуть, вчасно зроблений шов економить… скільки, одинадцять? Ах, не пам’ятаю. Та й приказка взагалі дурна.",  -- db:5535
[226005834] = "Непогано... як для аматора! Втім, ти знаєш не більше за мене. Якщо хочеш дізнатися більше, тобі доведеться поговорити з Йозефом Грегоріаном в Андерсіті.",  -- db:5536
[619974774] = "Ну що ж, не так уже й погано. Можливо, я ДІЙСНО зможу тобі дещо показати...",  -- db:5539
[269378395] = "Який чудовий день! Він надихає мене на створення нового дизайну.",  -- db:5540
[355838348] = "Ваші таланти вражають! Ви справді натхненні. Щоб продовжити свій шлях до знань, поговоріть із Джорджіо Болеро у Штормовій. Він користується великою повагою і зможе продовжити ваше навчання.",  -- db:5541
[437507322] = "Є основи, які необхідно засвоїти. Тріанна стоїть неподалік — поговори з нею, а потім повернися до мене.",  -- db:5543
[954019564] = "Ти добре впорався, мандрівнику. Я пишаюся тим, що можу називати тебе своїм учнем!",  -- db:5544
[767094974] = "Ласкаво просимо до нашого намету. Чим можу допомогти?",  -- db:5545
[506887672] = "Ти маєш великі знання, мандрівнику. Тобі слід повчитися у того, хто мудріший за мене. Про мудрість Йозефа Грегоріана ходить чимало оповідей. Ти зможеш знайти його в Підмісті.",  -- db:5546
[188237724] = "Відмінно! А тепер давайте продовжимо ваше навчання...",  -- db:5549
[314423860] = "Хіба ці візерунки не прекрасні? Кожен із них має свій власний характер.",  -- db:5551
[702649353] = "Мої знання обмежені, хоча я все ще навчаюся. Настав час тобі рушати далі, мандрівнику. Знайди Йозефа Грегоріана в Підмісті та скажи йому, що ти готовий.",  -- db:5552
[152601797] = "Є кілька основних речей, які ти повинен вивчити, перш ніж я зможу тобі допомогти. Поговори з моїм учнем, Вханом. Він добрий і терплячий, і навчить тебе всьому, що тобі потрібно знати.",  -- db:5554
[358213860] = "Ти справді цілеспрямований учень. Я з радістю буду тебе навчати!",  -- db:5555
[376666211] = "Уміння шити може дуже знадобитися. Одного разу мені довелося пришити собі руку назад.",  -- db:5556
[636218940] = "Ти проклав собі шлях до вершини, настав час зустрітися з босом. Підійди до Йозефа і скажи йому, що ти готовий.",  -- db:5557
[488553699] = "Як я можу поділитися своїми секретами з новачком? Спробуйте спершу поговорити з Віктором Уордом.",  -- db:5559
[466586671] = "Чудово, у тебе є характер! Мені це подобається. Ну що ж, тоді рушаймо!",  -- db:5560
[447490934] = "Так, я вже деякий час керую цим магазином. Останнім часом справи йдуть досить добре. До нас заходить багато нових шукачів пригод...",  -- db:5561
[614757908] = "Мені відома лише одна людина, яка краще за мене розбирається в мистецтві кравецької справи. З останніх відомостей, його можна знайти на острові Терамор. Саме його вам і слід шукати.",  -- db:5562
[836100309] = "Боюся, що вам знадобиться ще трохи практики, перш ніж я зможу поділитися з вами своїми знаннями.",  -- db:5564
[749633978] = "Чудово! Я бачу, що мої зусилля не будуть марними!",  -- db:5565
[660107709] = "Тканина — це нормально. Особисто я віддаю перевагу роботі зі шкірою людини.",  -- db:5566
[496116952] = "Тобі потрібні настанови справжнього майстра! Звернися до Даріла Стека в Таррен-Міллі та прийми свою долю!",  -- db:5567
[535191384] = "Я дам тобі вказівки, коли настане відповідний час... але зараз ще не час. Тобі спочатку ще багато чого треба навчитися!",  -- db:5569
[45557035] = "Я одягав королів. З належним навчанням це зможете зробити й ви.",  -- db:5571
[587904237] = "Ти пройшов довгий шлях, мандрівнику. Тобі залишилося виконати ще одне завдання...",  -- db:5573
[577470650] = "Я не зможу тобі допомогти, доки ти не опануєш основні знання. Звернися до мене, коли будеш готовий.",  -- db:5574
[264467276] = "Тут трохи протяжно... але що мені до того? Я ж мертвий.",  -- db:5575
[223430154] = "Мушу визнати, що ти чудово справляєшся з мистецтвом кравецької справи. А тепер давай подивимося, наскільки ти насправді вправний...",  -- db:5577
[265003936] = "Хто тебе сюди прислав? Ти ще не готовий до мого навчання! Тобі скажуть, коли ти будеш готовий.",  -- db:5578
[610915513] = "Мені так подобається сидіти тут і слухати шум Великого моря.  О, що?  Так, є корабель, який доправить вас до гавані Менетіл.  Він час від часу причалює саме тут.",  -- db:5579
[448275189] = "Запам'ятайте мої слова!  У Східних Королівствах ви ніде не знайдете грифонів швидших, ніж ті, що мешкають саме тут, у Телсамарі!",  -- db:5580
[750540972] = "Якщо ви запитаєте мене, то немає кращої професії, ніж шахтар.  А якщо ви запитаєте мене, то немає кращого шахтаря, ніж гном!",  -- db:5581
[228858941] = "Карлики з племені «Диких Молотів» можуть і мати швидких коней, але чи витримають ті грифони з Піку Орлиного гнізда спеку Великої Кузні?  Гадаю, що ні!",  -- db:5582
[951327163] = "Найкращий шахтар міцно тримає в руках $ghis:her; кирку, має мужнє серце в $ghis:her; грудях, а в $ghis:her; волоссі — густий чорний пил.",  -- db:5583
[666601810] = "Міцна скриня стоїть посеред лісопильні, оточена уламками та надзвичайно завзятими прихильниками «Скарлетного хрестового походу».",  -- db:5584
[823495648] = "Цей ведмідь бродить стежкою неподалік від «Шляху Талондіп», що пролягає на захід від озера Містрал та форпосту Альянсу «Притулок Срібного Вітру». Хоча він є найлегшим з трьох істот, з якими вам доведеться зіткнутися під час «Полювання в Попеліній долині», з ним не варто легковажити.  Його присутність є постійною загрозою для мандрівників, які подорожують між Ашенвейлом та Горами Кам’яного Кігтя.",  -- db:5593
[53161961] = "«Гострий Кіготь» — наймогутніша з усіх звірів, що входять до складу «Полювання в Попеліній Долині», — вільно бродить цими краями завдяки самопроголошеним охоронцям цієї землі — нічним ельфам.  Шарпталон патрулює на південь від цього місця у пошуках здобичі, отримуючи насолоду від того, як розриває на шматки нічого не підозрюючих і необережних мандрівників.$B$BЗдобути таку тварину було б найвеличнішим трофеєм, $N.  Бажаю тобі удачі в полюванні на цю істоту!",  -- db:5594
[50320772] = "Ходять чутки, що ця нічна мечниця поводиться покірно в присутності нічних ельфів та їхніх союзників, що робить її ще більш гідним супротивником. Мисливський шлях Шадумбри веде її від «Рейневудського притулку» на захід від нас, аж до земель, що лежать на захід від нього.  Її шерсть має колір смоли, а її швидкість не варто недооцінювати.",  -- db:5595
[702987992] = "Вітаю, $c — ласкаво просимо на передову нашого завоювання Ешенвейла! Якщо ти шукаєш, чим зайнятися, то потрапив у потрібне місце. Я завжди шукаю сильних і відважних людей, які допоможуть принести славу Орді!",  -- db:5613
[475960083] = "Дракон ховається за королівським фасадом. Книги розкриють її справжню суть... Якщо те, що я побачив, виявиться правдою, я не виживу в цій битві, друже. Саме ти повинен завершити те, що я розпочав. Твої війська готові? Ти готовий? Почнемо за твоїм наказом.",  -- db:5633
[423366564] = "Якщо ти хочеш дізнатися про пересування караванів і купців тут, у Сплінтертрі-Пост, то, на щастя, я саме той орк, якого ти шукаєш.  Проте, на твою біду, я не люблю людей.$B$BЯкщо тобі щось потрібно, то поквапся.",  -- db:5653
[530705724] = "Елементи звертаються до нас, $c.  Вони діляться знаннями, які ми маємо засвоїти, і розкривають таємниці, які слід зберігати.",  -- db:5654
[950359994] = "У процесі ретельного перенавчання мені доводилося позбавляти багатьох учнів усього, чого вони навчилися раніше, щоб я міг навчити їх заново. З кожним разом виконувати цю послугу стає дедалі складніше. Саме через це з кожним перенавчанням вона стає дедалі дорожчою. Чи бажаєте ви, щоб я позбавив вас тих талантів, яких ви навчилися?",  -- db:5673
[349981218] = "Якщо ви бажаєте, крім навчання, я можу стерти з вашої пам’яті знання про ваші таланти. Майте на увазі, що з кожним разом, коли ви проходите цю процедуру, її виконання стає все складнішим, а отже, і дорожчим.",  -- db:5674
[760025434] = "Чим можу допомогти?",  -- db:5695
[522196825] = "Мені більше нічого тебе навчити! Принаймні, тому, хто знає стільки, скільки ти! Вам, представникам Орди, треба поговорити з Ноггом в Оргримарі!",  -- db:5696
[867995243] = "Я не маю наміру заподіяти вам шкоди. Я досліджую квілбоарів і веду записи про їхню діяльність. Мої люди помітили щось дивне — випромінювання чи темряву — що виходить із цієї місцевості. Я прибув, щоб це розслідувати, і те, що я виявив, дуже мене тривожить.$B$BСхоже, тут є неживий дипломат, який володіє потужними магічними здібностями. Я не вірю, що він належить до «Покинутих»… Гадаю, це щось гірше.",  -- db:5713
[537701611] = "Ти знаєш достатньо, щоб становити загрозу, але, як на мене, тобі все ще потрібне навчання, $N.",  -- db:5714
[365439913] = "Ваша воля недостатньо сильна, щоб маніпулювати силами, якими ми керуємо $c.",  -- db:5715
[504630384] = "$N, як я можу сприяти твоєму навчанню в очах Матері-Землі?",  -- db:5716
[375825238] = "Багато шляхів у Матері-Землі. Нехай твої предки оберігають тебе $c.",  -- db:5717
[791585077] = "Буде розумно, якщо ти проявиш покірність переді мною, $N, у своєму прагненні здобути більше знань чаклуна.",  -- db:5719
[470410851] = "У мене немає часу витрачати його на таких, як ти, $c.",  -- db:5720
[583775670] = "Я вже по тому, як ти стоїш, бачу, що ти аж ніяк не воїн.  $B$BЧому б тобі не зайнятися чимось безпечним, наприклад, почитати книжку?",  -- db:5721
[974442988] = "Темрява тебе не охопить, $c.  Припини свою балаканину і зникни з моїх очей!  Геть!",  -- db:5722
[128845610] = "Боюся, що твій рівень темряви недостатній, щоб я витрачав час на подальшу розмову з тобою. Прошу, йди собі.",  -- db:5723
[870155357] = "Ти ж не воїн... Ти б навіть дня не витримав за моєю програмою тренувань!  $B$BA $c хто вважає, що $ghe's : вона; воїн.  Ха!",  -- db:5724
[926766175] = "Я не бачу в тобі духу воїна, дитино. У мене немає вчень, які були б корисні такому $c, як ти.",  -- db:5725
[618032995] = "«Розбита Рука» змогла розмістити шпигунів по всій верхній цитаделі Чорної Скелі. Хоча процес збору інформації просувається повільно, нам вдалося зробити відкриття, які неможливо ігнорувати.",  -- db:5733
[330736523] = "Схоже, що вплив Чорного Драконячого Польоту поширився за межі Палаючих Степів і проник навіть у саме королівство Штормовій! З того часу узурпатора було викрито та усунуто від влади.",  -- db:5734
[439371779] = "Дійсно. Мати-засновниця Чорного Драконячого Польоту скористалася ілюзіями та хитрощами, щоб замаскуватися під члена королівського двору. Що ще гірше, вона взяла під свій контроль нинішнього Верховного лорда Штормовію, Болвара Фордрагона.$B$BНе дивно, що були прийняті такі безглузді військові рішення. Останні пересування військ Альянсу змушували нас ламати голову. Тепер ми розуміємо, що Чорний Політ намагався розколоти імперію — знищити її зсередини.",  -- db:5735
[220076360] = "<Трал сміється.>$B$BТобі ще так багато треба навчитися, $r.$B$BТи занадто молодий, щоб пам’ятати війни та кровопролиття минулих століть. Занадто молодий, щоб пам’ятати тягар прокляття, яке несе наш народ.$B$BНаше становище в Альянсі зараз є непевним. Звісно, трапляються сутички та дрібні бої, але панує мир — те, чого наш народ не знав тисячоліттями. Чи готовий ти відмовитися від цього й знову занурити нас у пащу хаосу, але вже проти нового ворога? Такого, що не заспокоїться, доки нас усіх не знищить?",  -- db:5736
[11976436] = "Ні, $N, ти цього не зробив. Однак я не звинувачую тебе, адже твій розум дуже схожий на мій у юності: імпульсивний, бунтівний і часто позбавлений хоч однієї впорядкованої думки! Це риси, які я більше не можу собі дозволити проявляти.$B$BДосить нарікати. $R, у мене є для тебе завдання; таке, яке ти, можливо, не переживеш.",  -- db:5737
[497585968] = "<Трал сміється.>$B$BЗрозуміло... А тепер слухай уважно, $N. Мати роду Чорного драконячого полку, Оніксія, була витіснена зі своєї позиції влади у Штормовій. Вона втекла до свого лігва в Болоті Дастволл.$B$BНе можна допустити, щоб вона жила так близько до наших столиць. Ми мусимо завдати удару першими, перш ніж нас атакують!$B$BЯ хочу, щоб її знищили, $N.",  -- db:5738
[624328006] = "Я бачу, як тут, у порту, з’являються й зникають різні цікаві персонажі. Будь обережним, $N. Ніколи не знаєш, кому можна довіряти, з огляду на всі ті сумнівні справи, що тут відбуваються...",  -- db:5753
[820490144] = "То ти прийшов за сокирами «Військової пісні». Ну, вже й пора, $N. Ця скриня вже кілька днів просто стоїть там.$B$BМожеш забирати її, коли будеш готовий.",  -- db:5754
[920512959] = "У горах Стоунталон у цьому регіоні розкидано безліч небезпечних печер. Дослідження цих печер може принести чимало пригод тим, хто готовий ризикнути життям заради слави.$B$B$C, можливо, ти шукаєш багатства, які можна здобути, лише слідуючи за своїм серцем і душею.",  -- db:5773
[942989645] = "Риба така смачна. Хочеш навчитися готувати рибу? Або просто поїсти рибу? Мммм...",  -- db:5793
[379847829] = "Так, я можу навчити тебе ловити рибу.",  -- db:5794
[161826480] = "Будь ласка, йди звідси, $N. Ти нічого не знаєш про те, що нас турбує...",  -- db:5795
[790503488] = "Зачарований торій — це метал, на який існує великий попит. Найкращий спосіб його знайти — звернутися до майстра-коваля або гірника.",  -- db:5796
[269310380] = "«Кристал відновлення» — це предмет, який важко дістати, якщо ви плануєте знайти його самостійно.$B$BI вважаю, що його можна знайти в кратері Ун’Горо, тож вам краще вирушити саме туди. Втім, можливо, вам вдасться знайти когось, хто готовий поділитися своїм запасом...",  -- db:5797
[500970705] = "Може, ми й страждаємо від посухи, але м’яса у нас вдосталь! Хочете подивитися, що у мене є?",  -- db:5798
[817115197] = "Чи може Зам'я тобі допомогти, $r?",  -- db:5799
[262680108] = "Я їх годую, хлопче. Так, Даріл Рікнуссун, до твоїх послуг.",  -- db:5800
[322375942] = "Я — орк-лікар, $r. Якщо ти прийшов сюди, щоб навчитися, я зроблю все можливе, щоб навчити тебе.",  -- db:5813
[908171979] = "Ви — студент медичного факультету?",  -- db:5815
[263272005] = "Чому ти прийшов сюди, $c?",  -- db:5816
[302055627] = "Мій народ — він так само розбитий, як і та реліквія, яку ви намагаєтеся відремонтувати.",  -- db:5817
[405788856] = "Хоча минуле вже не змінити, час здатний загоїти всі рани. Дякую тобі, $N, за те, що показав мені, що це можливо. Бажаю тобі всього найкращого.",  -- db:5818
[670619388] = "Вітаю, $c. Чим я можу вам допомогти?",  -- db:5819
[325660658] = "Ось моє запитання до вас, $c:$B Який із Аспектів, створених титанами, перетворився на зловісну істоту, відому як Смертокрил?",  -- db:5820
[253282476] = "Завжди приємно, коли хтось хоче зі мною поговорити. Як у тебе справи, $c?",  -- db:5821
[160157282] = "А тепер скажи мені, $N:$B Яка істота стала Королем Лічем, перш ніж поширити чуму по Лордаерону?",  -- db:5822
[204036253] = "Так, ти вже дещо знаєш! Якщо хочеш дізнатися більше, тобі доведеться поговорити з Джорджіо Болеро у Штормовій.",  -- db:5833
[902709854] = "Братство Торію володіє знаннями, необхідними для виготовлення священної зброї та озброєння Володаря Вогню, але нам бракує робочої сили для здобуття матеріалів, необхідних для їхнього виготовлення.$B$BI, Лохтос Темний Торговець, отримав від Братства повноваження обмінювати благородні рецепти на матеріали, зібрані в Розплавленому Ядрі.$B$BПредставте свою пропозицію, $r.",  -- db:5834
[550067713] = "Хочете зробити своїх демонів сильнішими?  Це вам обійдеться недешево, але ви звернулися за адресою.",  -- db:5835
[177517010] = "Ти не чаклун, і в мене немає на тебе часу. Забирайся геть!",  -- db:5836
[478147329] = "Ви прийшли на тренування, щоб потім навчити цьому своїх домашніх улюбленців?",  -- db:5838
[300164016] = "О, друже, я допомагаю лише мисливцям та їхнім вихованцям.",  -- db:5839
[263690959] = "Королівське товариство аптекарів не терпить дурнів, як і я. Можливо, наступного разу, коли ми з тобою поговоримо про моїх коней, ти будеш вважатися високопоставленою особою в Підмісті. А до того часу...",  -- db:5840
[963948258] = "Я надаю доступ до своїх верхових тварин лише тим, хто має статус «шанованого» в Оргримарі та серед раси орків.  Доведіть нам свою гідність, і я дозволю вам оглянути своїх могутніх вовків.",  -- db:5841
[900291039] = "Вибач, $g mon : sis;, але я не продаватиму своїх рапторів тому, хто ще не довів, що заслуговує на визнання племені Темних Списів.  Коли ти проявиш себе і доведеш, що для нас ти не менше, ніж шанований, тоді я надам тобі своїх рапторів.",  -- db:5842
[585443190] = "Мій народ тебе не знає.  Кодо — це могутній кінь, і він є плодом любові та турботи мого народу; таких тварин не віддають чужинцям.  Доки старійшини Громового Уступу не визнають тебе гідним, я не можу запропонувати тобі кодо на продаж.",  -- db:5843
[225726971] = "На жаль, $c, тебе ще не вважають гідним приєднатися до Дарнассуса та нічних ельфів Телдрасіля. Лише коли ти доведеш нам свою гідність вчинками — а не лише словами — я відкрию тобі доступ до своєї колекції верхових тварин, щоб ти міг з нею ознайомитися.",  -- db:5844
[566277297] = "Не підходь! Дітям тут не місце! Іди геть, дитино!",  -- db:5853
[274181013] = "Вибачте, але я не маю наміру продавати коней особам, які не мають принаймні звання «високоповажного» у Королівстві Штормовій.  Ці коні — найкращі з усіх, що ви коли-небудь бачили, і ми, звісно, не хочемо, щоб вони потрапили до рук наших ворогів.$B$BЗвісно, я не кажу, що ви — ворог... просто завоюйте довіру Штормовію, і тоді ми зможемо укласти угоду.",  -- db:5855
[693931273] = "Не так швидко, $g, друже : леді;... Я не віддам кермо могутнього барана тому, хто не є перевіреним союзником гномів з Айронфорджа.  Як тільки ти отримаєш статус «шанованого» в Айронфорджі, я з радістю покажу тобі, які сорти баранів я маю на продаж.",  -- db:5856
[698002974] = "Е-е-е... Я, чесно кажучи, не дуже добре тебе знаю, вибач.  Тобто, як офіційний дилер «Механо-страйдерів», я можу продавати своїх верхових тварин лише тим, кого гноми вважають «шанованими». Якщо тебе колись визнають «шанованим» у Гномерегані, я з радістю покажу тобі, що маю в асортименті.",  -- db:5857
[221086040] = "Тобі потрібно досягти високого рівня репутації серед гномів Айронфорджа, перш ніж я навчу тебе їздити верхи, $c.",  -- db:5858
[52541639] = "Тобі потрібно досягти високого рівня репутації серед «Покинутих» в Підмісті, перш ніж я навчу тебе навичкам верхової їзди, $c.",  -- db:5859
[747728157] = "Тобі потрібно заробити високий рейтинг у гномів «Вигнанців Гномерегана», перш ніж я навчу тебе керувати «Механострайдером», $c.",  -- db:5860
[780627754] = "Тобі потрібно здобути високий рейтинг серед жителів Штормовію, перш ніж я навчу тебе їздити верхи, $c.",  -- db:5861
[372137195] = "Тобі потрібно досягти високого рівня репутації серед нічних ельфів Дарнассуса, перш ніж я навчу тебе навичкам верхової їзди, $c.",  -- db:5862
[534585687] = "Тобі потрібно досягти високого рівня репутації серед орків Оргримара, перш ніж я навчу тебе їздити верхи, $c.",  -- db:5863
[888303948] = "Тобі потрібно здобути високий рейтинг у тауренів Громового Уступу, перш ніж я навчу тебе їздити верхи, $c.",  -- db:5864
[617357038] = "Тобі потрібно досягти високого рівня репутації серед тролів племені Темного Списа, перш ніж я навчу тебе навичкам верхової їзди, $c.",  -- db:5865
[153031096] = "Я не вірю, що ти володієш достатньою гостротою розуму, щоб осягнути суть портальної магії.",  -- db:5873
[946142139] = "Як маг, ти належиш до обраного кола тих, хто здатний створити портал, щоб повернутися саме сюди. Якщо ти готовий, я можу навчити тебе.",  -- db:5874
[389203680] = "Мене звати Монті, а щури — це моя справа.",  -- db:5894
[878004520] = "Ця синя шкіра справді привертає увагу, я знаю. Розумієте, у нас тут бігає безліч завзятих новобранців, які полюють і вбивають з більшим ентузіазмом, ніж розсудливістю. Треба вживати запобіжних заходів.",  -- db:5913
[915466248] = "Твої навички вже перевершили мої, юний друже. Звернися до Уни, у якої є крамниця на центральному плато Громового Уступу. Вона зможе дати тобі ті поради, яких ти шукаєш.",  -- db:5914
[247094381] = "Тепер ви готові вивчити тонкощі дублення шкіри методом «кодо». Почнемо...",  -- db:5917
[380698482] = "Між світлом і темрявою лежить тінь... і ці тіні мають сили, яких ти ще не бачив.",  -- db:5918
[341694639] = "На цій стороні Хаз-Модана ви не знайдете кращого шашлику з щурів!",  -- db:5920
[444676613] = "Схоже, тобі не завадило б трохи попрацювати, $g felle:lady;. Тобі варто сісти на трамвай і завітати до мого брата Монті на трамвайне депо «Айронфордж Діпран». Я впевнений, що він знайде для тебе якусь роботу.",  -- db:5921
[250745795] = "Будь обережним, незнайомцю.",  -- db:5933
[168915848] = "Маєток «Рейвенхолдт» не впізнає вас, $c.",  -- db:5933
[886631006] = "Зухвалість. Майстер Рейвенхолдт не любить зухвалість.",  -- db:5933
[364032621] = "Радий знову тебе бачити, $N.",  -- db:5934
[106313352] = "Привіт, $c. Ти вже розмовляв із Фарадом?",  -- db:5934
[947335513] = "«Синдикат» складається з купки некомпетентних людей — безладно організованих, некваліфікованих і ледачих...",  -- db:5934
[593824228] = "Відсутній текст із США",  -- db:5935
[6843287] = "Ти наважишся ступити в маєток Рейвенхолдт, черв’яку?",  -- db:5938
[834660143] = "Вибратися звідси без ножа в спині чи отрути в жилах — це вже було б досягненням.",  -- db:5938
[78253835] = "Ти непогано розвиваєшся, $N. Я чув про тебе хороші відгуки...",  -- db:5939
[87374329] = "Тобі варто поговорити з Вінстоном. Я чув, що він шукає злодіїв з такими ж навичками, як у тебе.",  -- db:5939
[285852747] = "Нехай Елуна супроводжує тебе, $c.  Храм Місяця прийшов на допомогу знедоленим мешканцям Аубердіна.",  -- db:5943
[50559062] = "Шоджа'мі вже біля готелю. А тепер йди собі, я зайнятий.",  -- db:5973
[60411251] = "Маєте домашніх улюбленців, про яких треба піклуватися?  Тільки не забудьте прибирати за ними!  Шукайте Шоджа’мі перед корчмою.",  -- db:5973
[585331398] = "Відправляйся до Долини Честі та знайди Ксон'чу біля стайні.",  -- db:5974
[245030623] = "Ксон'ча розмістить ваших зайвих вихованців у стайні.  Знайдіть його в Долині Честі, у стайні, що розташована між ареною та Залом Мисливців.  А тепер геть звідси!",  -- db:5974
[626695305] = "Ах так, тобі треба знайти Сейкву.  Здається, я востаннє бачив її біля входу в готель.",  -- db:5976
[899316460] = "Сейква може доглянути за вашими чотирилапими друзями, коли у вас виникне така потреба. Зверніться до неї перед готелем.",  -- db:5976
[691720303] = "Саме допомога Булруга вам і потрібна. Ви знайдете його на вулиці, на нижньому пагорбі, між таверною та банком «Громового Уступу».",  -- db:5977
[121128545] = "Ваша турбота про добробут ваших домашніх улюбленців заслуговує на похвалу.  Булруг, що знаходиться на нижньому пагорбі, може вам у цьому допомогти.  Шукайте його між банком і корчмою.",  -- db:5977
[802307718] = "Як не дивно, але Моргануса, управителя стайні, можна знайти саме перед стайнями.",  -- db:5978
[365788532] = "Ти не надто кмітливий, чи не так?  Хм, якби я був конюхом, то, мабуть, перебував би десь поблизу, скажімо, стайні?  Шукай там Моргануса.",  -- db:5978
[850133195] = "Аня Маулрей у готелі на верхньому кільці Торгового кварталу.",  -- db:5979
[592637731] = "Ми хочемо багато домашніх тварин.  Аня Маулрей допоможе вам доглядати за ними.  Ви знайдете її в готелі, у верхньому кільці Торгового кварталу.",  -- db:5979
[282952140] = "Ви можете бути впевнені, що Аласін добре подбає про ваших домашніх улюбленців. Він мешкає в Енклаві Сенаріону, де збираються мисливці.",  -- db:5980
[189155799] = "Вже багато сотень років Аласін піклується про тварин, з якими дружать наші мисливці.  Його допомога у догляді за тваринами дуже цінується місцевими мисливцями.  Якщо ви теж хочете звернутися до нього, шукайте його в Енклаві Сенаріону.",  -- db:5980
[908788792] = "Ми всі — це частинки набагато більшого пазла, $N. Так само, як ти направляєш частинку пазла до місця призначення, так і нас направляє хтось інший.$B$BІ, можливо, ті, хто нас направляє, самі перебувають під впливом ще більшої сили.",  -- db:5981
[139620762] = "Ах, лагідна Серіадне.  Усі тварини в безпеці, коли вона про них піклується.  Ви знайдете її прямо біля готелю в Доланаарі.",  -- db:5982
[782144591] = "Шукаєте когось, хто піклується про тварин?  Тоді вам слід пошукати Серіадне біля готелю в Доланаарі.  Саме вона — та, кого ви шукаєте.",  -- db:5982
[281099116] = "Стара добра Ерма — вона вже багато років опікується місцевими тваринами. Я впевнений, що вона з радістю подбає про будь-яку тварину, яку ви захочете їй довірити. Її можна знайти прямо біля готелю «Lion’s Pride Inn».",  -- db:5983
[495468089] = "Ерма тут відповідає за догляд за тваринами. Якщо вам потрібно з нею поговорити, вона знаходиться прямо біля готелю «Lion’s Pride Inn».",  -- db:5983
[591872387] = "Дженова Стоуншилд, що мешкає у Дварфському кварталі, — саме та, кого ви шукаєте. Вона доглядає за вихованцями мисливців, поки ті проходять навчання у її батька.",  -- db:5984
[721481573] = "Якщо вам потрібно десь розмістити свого улюбленця на час, поки ви тренуєте іншого, то вам слід звернутися до Дженови Стоуншилд у Дварфському районі.",  -- db:5984
[217555705] = "Ну що ж, $glad : lass;, Шелбі Стоунфлінт ви знайдете прямо біля винокурні «Thunderbrew» у Хараносі. Вона чудово подбає про ваших домашніх улюбленців.",  -- db:5985
[200003845] = "У Шелбі Стоунфлінт мешкає чимало домашніх тварин місцевих мисливців. Якщо вам потрібно, щоб вона доглянула за вашим улюбленцем, її можна знайти біля винокурні «Тандербрю».",  -- db:5985
[375277796] = "Ульбрек Фаєрхенд дуже серйозно ставиться до догляду за тваринами. Якщо ви хочете, щоб він доглянув за одним-двома домашніми улюбленцями, його зазвичай можна знайти серед мисливців у Залі зброї.",  -- db:5986
[678385626] = "У Залі зброї ви зможете зустріти нашого штатного конюха, Ульбрека Фаєрхенда. Він подбає про те, щоб ваші домашні улюбленці були добре нагодовані та отримували належний догляд.",  -- db:5986
[770673340] = "У мене є щось для тебе, $N. Виглядає важливо.",  -- db:5993
[896623368] = "Ласкаво просимо до штаб-квартири SI:7, $N.",  -- db:5994
[805828264] = "$N, це прийшло для тебе сьогодні вранці.",  -- db:5995
[402848873] = "Сьогодні вранці гінці з Равенхолдта передали мені цей лист. Він адресований тобі, $N.",  -- db:5996
[325730429] = "Так, $c? Ти зв’язуєшся з нами?",  -- db:6033
[521811252] = "Шахта «Холодний Зуб» розташована на території Орди, в горах на північ від Кладовища Морозних Вовків.$B$BВона перебуває під контролем коболдів.",  -- db:6058
[600571093] = "Шахта «Айрондіп» розташована на території Альянсу, на північ від Кладовища Штормпайк.$B$BВона перебуває під контролем трогів.",  -- db:6061
[826869930] = "Цей пам’ятник присвячений усім тим, хто загинув, захищаючи Штормовій. Наш народ пережив неймовірні випробування, щоб зберегти свою свободу та самостійно визначати свою долю. Саме тут ми вшановуємо кожну жертву, яку принесли наші громадяни під час Першої війни, що спустошила наш народ.",  -- db:6062
[542970684] = "У Долині Альтерак вирують бої, а спорядження в дефіциті.",  -- db:6066
[216562497] = "Наші підрозділи не модернізовані, і в мене недостатньо ресурсів, щоб їх модернізувати.",  -- db:6073
[868636537] = "Кров наших ворогів проллється на полі бою. Великі елементалі відгукнуться на наш заклик і знищать усіх, хто стане нам на заваді.",  -- db:6093
[985579795] = "Молодець, солдате. Мені треба повертатися до базового табору! Прикриєш мене?",  -- db:6095
[565817652] = "Нарешті хтось прийшов. Чому ти так довго? А, та нічого. Прикрий мене, солдате. Мені треба повернутися на базу!",  -- db:6096
[606445725] = "Попереду ще багато роботи, $N! Продовжуймо знищувати наших ворогів!",  -- db:6098
[201386522] = "Так, $N. Сили пробуджуються. Незабаром ми обрушимо їхню міць на наших ворогів. Вони будуть хитатися від ударів!",  -- db:6099
[558100728] = "Я встановив контакт, $N. Це Лохолар, Володар Льоду. Він визнав нашу справу гідною — нашу земну жертву достатньою. Він незабаром прибуде... підготуйся.",  -- db:6100
[437525512] = "Мені потрібно кілька надійних напарників, щоб безпечно вивести мене звідси й повернути на базу.",  -- db:6101
[49559067] = "Здається, сторінки журналу наповнені інформацією про угоди, покупців та інші різноманітні події, пов’язані з бізнесом.",  -- db:6104
[716264501] = "Ніколи не дивіться Командиру прямо в очі.",  -- db:6105
[546601806] = "Ми виконуємо прямі накази Керна, $r. Не заважайте виконанню завдання командира.",  -- db:6105
[421217150] = "З Командиром-шаманом не варто жартувати, $r.",  -- db:6105
[434079985] = "Незабаром Лохолар повстане... Незабаром... Дуже, дуже незабаром...",  -- db:6105
[280028712] = "Флот готовий, $N. Ви повинні взяти цей маяк і встановити його біля східного кратера центральної зони бою. Захищайте маяк від нападників, доки флот не зможе зафіксувати його координати!",  -- db:6107
[44995996] = "Я — Гідраксіс, герцог Володарів Води. Ти не є елементалем, тому не можеш зрозуміти нашу боротьбу, але, можливо, ми зможемо укласти угоду, яка принесе користь нам обом...",  -- db:6108
[430073395] = "$N, радий тебе бачити. Наша війна з іншими володарями стихій ще триває, але твої зусилля допомагають забезпечити нашу перемогу.",  -- db:6109
[315802028] = "Флот готовий, $N. Ви повинні взяти цей маяк і встановити його біля західного кратера центральної зони бою. Захищайте маяк від нападників, доки флот не зможе зафіксувати його координати!",  -- db:6110
[649295775] = "$N, чого ти чекаєш?  Знайди фельдмаршала Теравейна на Полі Битви та передай йому накази про наступ.  Як тільки він отримає накази, він разом зі своїми військами кинеться в атаку на Орду й не братиме полонених!",  -- db:6134
[569463330] = "$N, чого ти чекаєш?  Знайди фельдмаршала на Полі Битви та передай йому накази про наступ.  Як тільки він отримає накази, він разом зі своїми військами кинеться в атаку на Орду й не братиме полонених!",  -- db:6134
[344419643] = "Якщо ти шукаєш інформацію, яку «Коло Сенаріона» могло десь заархівувати, то я саме та людина, до якої тобі варто звернутися.  Хоча, з іншого боку, щоб я міг тобі справді допомогти, тобі спочатку треба знати, яку саме інформацію ти шукаєш.$B$BБачиш, як це працює?  Чудово!",  -- db:6153
[7841034] = "Не прислухайтеся до голосів світу — відповідь лежить всередині вас. Ви знаєте правду.",  -- db:6154
[899121346] = "У цих пустках живе минуле, $c.  Ми повинні бути обережними, щоб не розбудити його.",  -- db:6155
[405840897] = "$N, ти готовий до найважливішого завдання.  Вогняні руни, викарбувані на підлозі розплавленого ядра, є проходами до царства вогню, і їхня присутність є одночасно образою для нас і джерелом сили для Володарів Вогню.  Їх треба загасити!$B$BЩоб загасити руну, візьміть флакончик з аквальною квінтесенцією.  Вилийте її на руну, і її полум’я згасне, зробивши її марною та послабивши нашого ворога!",  -- db:6158
[481990779] = "Ласкаво просимо до Реєстру гільдій Підміста. Що вам потрібно?",  -- db:6159
[467358581] = "Ласкаво просимо до «Кругу Сенаріона», $c.  Чим можу вам допомогти?",  -- db:6160
[435405619] = "Поговоріть з Гідраксісом.",  -- db:6161
[969165526] = "Тобі до мене немає діла, малятко.",  -- db:6161
[862527359] = "Не розмовляй зі мною своєю вульгарною мовою! Лише Гідраксіс може це витримати.",  -- db:6161
[125042577] = "Вітаю, малятко.  У тебе є якісь справи з Володарями Води?",  -- db:6162
[904932603] = "Чутки про твої подвиги поширюються. Твоє ім’я нам добре відоме, $N.",  -- db:6162
[306786638] = "Ти прийняв наших ворогів як своїх. Я з радістю поділюся з тобою водою.",  -- db:6162
[960487987] = "Можливо, ви розповісте мені про свої подвиги, $N.  Для мене буде честю дізнатися про них.",  -- db:6163
[222075272] = "Наш володар Гідракс дуже високо відгукується про тебе. Моя вода — це твоя вода, друже.",  -- db:6163
[278386416] = "Коли ти наступного разу підеш до «Розплавленого ядра», вбий для мене одного Володаря Вогню, добре?",  -- db:6163
[491333466] = "«Всевидне око» необхідно повернути!",  -- db:6167
[907488561] = "Нас відправили сюди з Дарнассуса, щоб допомогти «Штормпайку» у скрутну хвилину.",  -- db:6173
[661403208] = "Архідруїд вважає, що Івус, Володар Лісу, з’явиться, щойно дізнається про руйнівні сили, які панують у цій долині.",  -- db:6173
[302282330] = "Не нам судити про ці звірства. Івус винесе вирок, коли прибуде.",  -- db:6173
[414932022] = "Моя віра визначає мої дії, $r. Я знаю, що Івус прийде.",  -- db:6174
[673858613] = "Я загубився у Сні. Я відчуваю його життєву силу, але мої сили ще не стали достатньо сильними, щоб встановити контакт.",  -- db:6175
[249544527] = "Так. $N. Я знайшов Володаря Лісу. Ми маємо подвоїти наші зусилля! Потрібно більше кристалів!",  -- db:6176
[983275680] = "Володар Лісу знає про руйнування в цій долині, $N. Незабаром нам доведеться вирушити до Кола Покликання. Будьте готові!",  -- db:6177
[30973761] = "Мене збив той безрозсудний дурень, Мулверік. Боюся, що якщо я не повернуся на базу, все буде втрачено! Мулверіка та його загін «Військових вершників» треба зупинити!",  -- db:6178
[937749424] = "Не можу в це повірити... Я виконував чергову розвідувальну місію над центральною частиною демілітаризованої зони, коли раптом розвернулося справжнє пекло. Я бачив, як командир крила Орди, Мулверік, збив і Ічмана, і Слідора! Мене охопив гнів, і я відірвався від свого напарника та збив того виродка Мулверіка. На жаль, перед тим, як розбитися, він зачепив мого грифона, змусивши мене теж сісти на землю. У підсумку я потрапив у полон до цих дикунів.$B$BЯ мушу повернутися на базу! Допоможіть!",  -- db:6179
[506023164] = "Я чув їхній глузливий сміх, коли мій грифон розбився й згорів, $c.$B$B«Слідоре, ти нікчема!» — кричали вони.$B$BНіхто не має права так говорити зі Слідором! Допоможіть мені вибратися звідси, щоб я міг показати їм, хто насправді нікчема!",  -- db:6180
[650742426] = "У цьому лісі легко заблукати! Будьте обережні.",  -- db:6193
[240469292] = "Бажаємо вам та вашим близьким вигідних сезонних знижок!",  -- db:6194
[970279404] = "Прямо з нашої ферми на ваш стіл — це корисні та смачні продукти від Smokywood Pastures!",  -- db:6194
[921227460] = "Настав час чудових знижок!  Фа-ла-ла-ла-ла!",  -- db:6194
[249366439] = "Бажаємо вам чудового Свята Зимової Завіси!  Почніть його як слід — зі смаколиків від Smokywood Pastures!",  -- db:6194
[280699652] = "Обов’язково розкажіть Великому Діду Зимі, який секретний сюрприз ви хотіли б отримати на Зимову Завісу!",  -- db:6194
[725429162] = "Не дозволяйте дзвінкому дзеньканню дзвіночків затьмарити дзвін монет у вашій кишені!  Купуйте ласощі від Smokywood Pastures для святкування Зимової завіси!",  -- db:6194
[143789547] = "Якби у мене були каштани, можете не сумніватися, я б їх смажив на відкритому вогні.  Мммм!",  -- db:6194
[889904834] = "Не забудьте запастися обгортковим папером у цей святковий сезон!  Ніщо так не передає атмосферу «Чудової Зимової завіси», як загорнуті в папір обладунки та зброя для ваших друзів і рідних.",  -- db:6194
[921864985] = "Наші підрозділи підвищені до рівня «Досвідчені», але у мене недостатньо ресурсів, щоб підвищити їх до рівня «Ветерани».",  -- db:6217
[422670483] = "Наші підрозділи підвищені до рівня «Ветеран», але у мене недостатньо ресурсів, щоб підвищити їх до рівня «Чемпіон».",  -- db:6218
[52496416] = "У мене є достатньо ресурсів, щоб підвищити рівень наших військ до «досвідчених».",  -- db:6219
[582642474] = "Наші підрозділи підвищені до рівня «Чемпіонів», але я все ще можу зібрати більше припасів.",  -- db:6222
[86531384] = "Я більше не можу зберігати запаси. У мене вже стільки, скільки я можу впоратися!",  -- db:6223
[802812279] = "Ти тут, щоб навчитися користуватися новою зброєю, чи просто щоб згаяти час?",  -- db:6233
[211267281] = "Скажи мені, яку зброю ти хочеш освоїти, або йди геть.",  -- db:6235
[888538893] = "Бажаю тобі чудового Зимового свята... е-е... маленький $G хлопчик : дівчинка;.  Хороші діти отримують особливі, е-е, знижки в будь-якому місцевому магазині мережі «Smokywood Pastures».  М-м-м.",  -- db:6250
[725838059] = "Я досить добре уявляю, чим займеться старий Дід Мороз, коли ця зміна закінчиться. У мене тут, у сумці, є пляшка «Зимової завіси», і я маю намір випити її до дна.",  -- db:6250
[135343340] = "Ні... ти не можеш сісти мені на коліна.",  -- db:6250
[220854753] = "Так, звичайно, давай, скажи старому Діду Морозу, що ти хочеш на це Свято Зимової Завіси.$B$BХо-хо, поспішай.",  -- db:6250
[294936062] = "Кажуть, що армія рухається завдяки їжі, і це справді так. Щоб будь-яка наступальна операція увінчалася успіхом, ваші війська мають бути добре нагодовані та забезпечені всім необхідним.",  -- db:6255
[144671427] = "Дехто каже, що для успіху армії найважливішими є сила та хоробрість. І це правда! Але армії також потрібні припаси, щоб підтримувати себе в хорошій формі, і саме моя робота — подбати про те, щоб у них було все необхідне.",  -- db:6257
[310884533] = "Вітаю, солдате. Ти прийшов, щоб допомогти нашій справі?",  -- db:6273
[504655210] = "Молодець, солдате. Ще кілька — і наші стайні будуть переповнені конями, на яких кавалерія вирушить у бій!",  -- db:6274
[217980007] = "Привіт, друже. Ти потрапив у потрібне місце, щоб навчитися користуватися новою зброєю.",  -- db:6275
[286921806] = "Ах, $N!  Ти саме та людина, на зустріч з якою я сподівався!  У нас вистачить ресурсів, щоб організувати наземний наступ проти Орди!  Фельдмаршал Теравейн чекає на накази на Полі Битви...$B$BТи — хоробрий ветеран, який не раз доводив свою відвагу.  Чи хочеш ти передати Теравейну накази?",  -- db:6276
[645094559] = "Чого ти хочеш навчитися, друже?",  -- db:6277
[533950037] = "Для мене буде честю навчити вас користуватися зброєю, якою я досконало володію, якщо ви маєте в собі здатність до навчання.",  -- db:6279
[441916611] = "Якщо вам потрібне додаткове навчання, я з радістю підкажу, до кого можна звернутися за допомогою. Яка зброя привернула вашу увагу?",  -- db:6281
[307294442] = "Смерть «Штормпайку»!",  -- db:6282
[124942359] = "$N!  Наші запаси вичерпуються, і доки ми не отримаємо поповнення, ми не зможемо розпочати масштабні наземні атаки на Поле Боротьби!$B$BЗверніться до інтенданта «Штормпайк».  Він розповість вам, що ви можете зробити, щоб поповнити запаси наших штурмових підрозділів.",  -- db:6284
[626431645] = "Мабуть, ти прийшов сюди, щоб навчитися користуватися новою зброєю?  Поспішай, я дуже зайнятий!",  -- db:6286
[838574539] = "Я скажу тобі, куди піти, якщо ти розповісиш мені, що тебе цікавить.",  -- db:6287
[625871638] = "$N, приємно бачити на полі бою таких ветеранів, як ти!  На жаль, мушу повідомити, що наших запасів наразі замало, щоб розпочати будь-які масштабні наземні атаки проти Орди.$B$BЗвернися до нашого інтенданта; у нього є місії з постачання.",  -- db:6288
[941969856] = "Ви прийшли, щоб навчитися мистецтву збройного бою?",  -- db:6289
[755932269] = "Яка саме зброя вас цікавить?",  -- db:6290
[575863718] = "Я не можу навчити вас тому, з якою витонченістю слід битися, але можу навчити вас користуватися різними видами зброї.",  -- db:6291
[177544971] = "Якщо хочете, я можу порекомендувати вам інших майстрів зброї. Що вас цікавить?",  -- db:6292
[299863281] = "Ви хочете навчитися користуватися зброєю, так? Ну то не стойте там з роззявленим ротом, кажіть, $gladdie : дівчинко!",  -- db:6293
[381245352] = "Яку зброю ви хотіли б освоїти?",  -- db:6294
[252277277] = "Привіт!  Ти прийшов, щоб навчитися правильно користуватися новою зброєю?",  -- db:6295
[289102565] = "Ой, не хочеш тренуватися зі мною? А яка ще зброя привернула твою увагу?",  -- db:6296
[534100900] = "Смерть Фроствулфу!",  -- db:6313
[88089980] = "Чекаю на вказівки від керівництва!",  -- db:6315
[204497137] = "Місцеві барани Альтерака мають вирішальне значення для боєздатності нашої кавалерії!",  -- db:6316
[302175350] = "Ще кілька — і наші стайні будуть переповнені верховими тваринами. Передайте його під мою опіку, солдате. Далі я сам про це подбаю.",  -- db:6317
[617138005] = "Радий бачити вас, $N. Нам доведеться бути лаконічними, адже попереду багато справ.",  -- db:6333
[78973115] = "Нехай Сенаріус веде тебе, $c.$B$BI. Я перебуваю на цій зіпсованій землі разом зі своїми сестрами, виконуючи надзвичайно важливе завдання для Сенаріанського Кола. Але прошу, щоб про такі справи зі мною говорили лише ті, хто достатньо могутній — відправляти сюди менш значущу істоту було б нерозумно.",  -- db:6334
[501994485] = "Ми з сестрами спустилися з гір Стоунталон, щоб покласти край трагедії, що сталася багато століть тому. На жаль, ми не маємо достатньої сили, щоб самостійно досягти своєї мети, і тому зараз шукаємо смертних, таких як ти, щоб вони нам допомогли.$B$BЯкщо ти достатньо сильний, то нам є про що поговорити, $c. Якщо ж ні, то заради твоєї безпеки я не буду розкривати подробиці своєї місії під час нашої розмови.",  -- db:6335
[20625682] = "Вітаю вас, $r.",  -- db:6336
[183482010] = "Мені не потрібен дім, щоб знати, що я все ще маю своє місце в цьому світі, $c. Племена побачать... усі вони. Вони воюють між собою, і заради чого? За залишки, які залишили стерв'ятники... за землі, заражені Легіоном... ба!$B$BКентаври повинні пишатися своєю спадщиною — вона така ж благородна, як і у нічних ельфів чи орків, — настав час почати поводитися відповідно!",  -- db:6353
[136750969] = "Нарешті я звільнився від корупції, яка колись прив’язувала мене до цього місця...",  -- db:6354
[342318021] = "Дякую тобі за те, що ти зробив, $N.$B$BБережи скіпетр; нехай він допоможе тобі у боротьбі зі злом, яке заполонило це місце...",  -- db:6373
[609846526] = "Моє скіпетр... Після стількох років... Ти його знайшов! Ти справді станеш рятівником цього місця...$B$BБудь ласка, $N, уважно вислухай мене. Головку та держак скіпетра можна з'єднати в одне ціле лише біля Каменя Мараудона.",  -- db:6375
[188416114] = "Між кольорами — стежка.$B$BПромайни крізь світло.$B$BТи виринаєш із води.",  -- db:6377
[112560603] = "Між помаранчевим і фіолетовим проходами біля входів до Мараудона ви знайдете третій шлях.$B$BСкіпетр, який ви тримаєте в руках, — це і є ключ.",  -- db:6378
[196943346] = "Я втомився...$B$BЗвідси видно водоспади, $n...Скіпетр надає вам здатність переноситися саме сюди, якщо ви коли-небудь захочете знову увійти через головні ворота Мараудона.$B$BБіля входу до Мараудона ви знайдете прохід, що веде вниз, під печери. Використайте скіпетр на стародавньому ритуальному майданчику, щоб створити портал, і ви знову опинитеся тут.",  -- db:6379
[52694298] = "Давним-давно ми з моїми сестрами-дріадами увійшли в ці печери, щоб звільнити змучену душу мого дядька, Заетара. Однак розпад, що вже поширився цими печерами, незабаром взяв над нами гору, і ми теж піддалися йому.$B$BНам судилося блукати цими ходами; токсини отруювали наші розуми...$B$BХоча моя душа, можливо, й знаходить тепер спокій, я знаю, що не виконала свою місію. Це великий смуток, який я мушу нести...",  -- db:6380
[481263765] = "Ах, Заетар... <Селебрас відводить погляд.>$B$BМій батько, Ремулос, намагався зупинити його...$B$BЗаетар був упертим, і коли він закохався в принцесу земних елементалів, мій батько розумів, що їхній союз проклятий, але Заетар відмовився слухати.$B$BКентаври — це наслідок його помилки. Вони народилися потворними й сповненими ненависті; мого дядька Заетара вбили його ж родичі...$B$BЗла принцеса Терадрас досі охороняє його останки тут, у кришталевих печерах.",  -- db:6381
[163640275] = "Ласкаво просимо до Ліги дослідників. Якщо вам потрібна інформація, яка міститься в книжках, то, можливо, я зможу вам допомогти.",  -- db:6383
[558132002] = "Коли токсини, що таїлися в Мараудоні, проникли в мій розум, я почала втрачати зв’язок із реальністю. Побоюючись, що його можуть використати в злісних цілях, мої сестри-дріади таємно відібрали у мене скіпетр, розламали його на дві частини й сховали в печерах.$B$BНезабаром вони теж стали жертвами божевілля, і дві частини скіпетра, що залишилися без нагляду, потрапили до рук самого Вілетонга. Сатир довірив одну частину Ноксіону, злому елементалю, а іншу зберігає у себе й донині.",  -- db:6384
[77674499] = "Не знаючи заклинань, необхідних для з’єднання двох частин, лорд Вайлетонг не міг скористатися скіпетром. Однак тепер, коли я звільнився від прокляття, що спричинило спотворення Вайлетонга, я зможу допомогти вам, якщо ви принесете мені обидві частини — і головку, і держак скіпетра.",  -- db:6385
[514756476] = "Ти запитуєш про Синів Сенаріуса — Ремулоса та Заетара.$B$BМій батько, Ремулос, був сильним і вродливим, а мій дядько, Заетар, — дуже хитрим і худорлявим. Хоча їх поважали однаково, Заетар завжди відчував, що ніколи не зможе зрівнятися зі славою та увагою, які, на його думку, належали Ремулосу.$B$BПісля того, як народилися ми з сестрами, Заетар, засліплений ревнощами, вирішив перевершити свого брата... Він сам став творцем своєї загибелі. Смуток, який це мені приносить, ніколи не зменшувався, навіть із плином часу...",  -- db:6393
[684980187] = "Вітаю, $N. Я — доктор Грегорі Віктор, головний хірург-травматолог у відділенні «Horde Trauma».",  -- db:6413
[264157700] = "Радий знову вас бачити, докторе $N. Я стежив за вашими успіхами і смію сказати, що настав час вам опанувати деякі більш складні техніки накладання пов’язок.$B$BЗвертайтеся до мене час від часу, у міру вдосконалення ваших навичок, і я навчу вас усьому, що знаю.",  -- db:6414
[217989690] = "Вітаю, $N. Я — доктор Густаф ВанХаузен, головний хірург-травматолог у «Alliance Trauma».",  -- db:6415
[211466014] = "Вітаю, $N!  Добре, що ти прийшов до мене.  Ми готові розпочати наземний наступ через Поле Битви!  Як тільки воєначальник Гаррік отримає накази, він разом зі своїми розбійниками прокладе собі шлях крізь Альянс!$B$BТи хочеш передати ці накази, $N?  Гаррік чекає на Полі Битви...",  -- db:6433
[101708215] = "Добре, що в Долині Альтерак є такі ветерани, як ти, $N. У нас занадто мало припасів, щоб розпочати наземний наступ через Долину Альтерак... Поговори з нашим інтендантом — він розповість тобі, як поповнити наші запаси.",  -- db:6435
[796545704] = "Ти!  $N!  Що ти тут робиш, блукаючи селом?  В Альтераку знаходяться вороги Альянсу!  Ми мусимо їх вигнати!$B$BУ нас занадто мало запасів, щоб розпочати великий наземний наступ, тож поговори з нашим інтендантом.  Він розповість тобі, як можна поповнити наші запаси.",  -- db:6437
[420521732] = "Я відповідаю за набір нових членів до клану «Морозних вовків». Як воїн клану «Морозних вовків», ти зобов’язаний звітувати переді мною у міру підвищення свого звання в клані.$B$BЧесть і повагу потрібно заробляти на цьому крижаному полі бою.",  -- db:6475
[589415086] = "Вітаю, $r! Я — лейтенант Хаггердін, офіцер, відповідальний за набір до Гвардії Штормпайка.$B$BКоли ти здобудеш престиж і славу серед Штормпайків, повернися до мене, і я подбаю про підвищення рівня твоїх знаків розрізнення. Крім того, якщо ти коли-небудь загубиш свої знаки розрізнення, я зможу надати тобі замінні.",  -- db:6476
[379957631] = "Наші предки вчать нас, що, хоча кожна людина має бути сильною, у єдності — сила. Чи хочете ви захистити честь Громового Уступу, створивши гільдію?",  -- db:6513
[318451900] = "Так, ти виглядаєш як людина, яка може стати лідером. Прийшов, щоб організувати гільдію для боротьби на боці Альянсу?",  -- db:6514
[816559859] = "Радий зустрічі, $c. Я — Рекксар.",  -- db:6533
[933663959] = "Чого ви вимагаєте від «Блакитного польоту»?",  -- db:6534
[21950537] = "На майстра Несінгварі чекає велике полювання.  Мені здається, допомагати йому готуватися до дня в джунглях набагато приємніше, ніж допомагати йому готуватися до бою.  Хоча я й сумую за деякими з тих славних моментів на полі бою.",  -- db:6535
[599508512] = "Я знаю ці ліси так, ніби вони — частина мене... Але знайте: у них ще багато чого можна навчитися, і там досі приховано чимало небезпек.",  -- db:6553
[412224635] = "Ти виконав завдання Тероніса, і я вдячний тобі за все, що ти зробив, $N.",  -- db:6555
[424414535] = "Привіт! Цей майстер-клас не мій, ні! Але одного дня, коли я закінчу навчання, я стану винахідницею, так само як мій кумир, Марвон Ріветсікер.$B$BВи ніколи про нього не чули? Ну, так вже вийшло, що він досить давно вирушив досліджувати якісь стародавні руїни тролів, про які він постійно розповідав. Він полетів на цепеліні... не зовсім впевнена, куди саме він поїхав...$B$BTанарасін? Тенкеріс? Танеранісані?$B$B<Лів хитає головою.>$B$BNі, це не те...",  -- db:6556
[311302631] = "Привіт. Ні, Марвона тут точно немає, і він ще довго не повернеться. Взагалі-то, я вже трохи за нього хвилююся...$B$BI Сподіваюся, він скоро повернеться. Для нього привезли великий скриню, і вона занадто важка, щоб я міг затягнути її сюди! Мені довелося залишити її біля дверей...",  -- db:6557
[561036734] = "Ви засвоїли все, чого я можу вас навчити на даний момент, докторе $N. Поверніться до мене, коли ваша практика розшириться, і я навчу вас більш просунутим методам лікарського мистецтва.",  -- db:6573
[88100441] = "Це місце... воно прокляте.$B$BМені ледь вдалося втекти, і я не можу змусити себе знову спуститися в тунелі.$B$BА от мій брат і сестри... Їм не пощастило так само. Застрягши всередині, вони страждають від лихоманки, спричиненої зіпсованим туманом, що витікає зі злого саду, який там росте.$B$BБудь ласка, ти мусиш допомогти.",  -- db:6574
[262373676] = "О, я так рада, що ти повернувся, $N.$B$BДуша мого брата тепер звільнилася від тління, але я вирішила залишитися тут, у своєму горі.$B$BДуже дякую тобі за допомогу, $N.",  -- db:6575
[555976800] = "Потрібні якісь матеріали?",  -- db:6594
[458470676] = "Можу я показати вам, що у мене є на продаж?$B$B",  -- db:6595
[549800239] = "Ти прийшов, щоб навчитися військовому мистецтву, $r? Ти потрапив не туди.",  -- db:6654
[853594475] = "Ви прийшли, щоб дізнатися про перемоги та поразки, що відбулися на цьому полі бою? Тут немає переможців...",  -- db:6655
[608105428] = "Будь насторожі, солдате! Розвідка «Штормпайк» повідомила, що тролі з племені «Зимовий Топор» взяли в полон майстра-гобліна-інженера. Собаки з племені «Морозний Вовк» активно намагаються його врятувати, щоб скористатися його технічними винаходами для нашого знищення! Не дай цьому статися.",  -- db:6657
[97334367] = "Повідомляється, що «Синдикат» нишпорить у печері на східному плато. З’ясуй, що вони там замишляють, солдате! Остерігайся активності «Морозних вовків»!",  -- db:6657
[142753022] = "Стережися, солдате, не заходь на територію «Фроствольфів». Усе це кляте місце заміноване! Там повно наземних мін! За додатковою інформацією звернися до нашого фахівця з вибухових речовин у першій вежі на передовій. Я впевнений, що він зможе навчити тебе, як розрядити ситуацію.",  -- db:6657
[307300785] = "Тоді слухай уважно, $c.$B$BЧи відчуваєш ти силу, що випромінюється від мене? Хіба твій бойовий дух не піднімається? Так, те саме відбувається й у супротивника. Зруйнувати їхню оборону та розрідити їхні війська буде нелегким завданням, але це треба зробити! Перемога буде за нами!",  -- db:6658
[616235453] = "Шість лейтенантів керують обороною на передовій. Їх треба знищити в першу чергу і якнайшвидше! Ми не можемо ризикувати, щоб хтось із їхніх священиків повернув до життя загиблих лейтенантів.$B$BЯкщо всіх лейтенантів вбити один за одним, бойовий дух на передовій похитнеться! Він буде зруйнований! Їхні війська втечуть у страху, залишивши решту солдатів без підкріплення.",  -- db:6659
[613647946] = "Безпорадна... безсила... відновити... треба відновити... Зеврім контролює... покласти край цим мукам...",  -- db:6694
[541918519] = "Дякую, смертний. Є лише одна послуга, яку я можу тобі надати, перш ніж повернутися до Сну.$B$BДвері до господаря Зевріма, Альзіна, перекривають тобі шлях. Я стану твоїм знаряддям руйнування. Двері будуть відчинені, я лише чекаю на твою команду.",  -- db:6695
[911569538] = "У нас є чимало запасів, але нам все ще потрібно набагато більше, щоб провести наземний наступ на Поле Боротьби.",  -- db:6718
[50383625] = "$N, у нас є достатньо припасів для проведення наземних атак на Поле Битви. Якщо ви хочете віддати накази і маєте достатньо високе звання, зверніться до сержанта Язри Бладснарл у селищі Морозних Вовків.",  -- db:6719
[337983797] = "У нас є деякі запаси, але їх небагато. Нам знадобиться набагато більше, щоб провести наземний наступ на Поле Боротьби.",  -- db:6720
[886644454] = "У нас майже немає запасів. Якщо ми хочемо провести наземний штурм на Полі Боротьби, то нам знадобиться набагато більше!",  -- db:6721
[66534703] = "$N, у нас є достатньо ресурсів для проведення наземних атак. Якщо ваш рейтинг у «Гвардії Штормпайк» достатньо високий, то зверніться до капрала Норега Штормпайка.",  -- db:6730
[633049680] = "У нас є чимало надлишкових запасів, але нам все одно потрібно ще більше, перш ніж ми зможемо відправити штурмовий загін на Поле Боротьби.",  -- db:6731
[623960654] = "У нас є надлишки запасів, але їх небагато. Нам знадобиться набагато більше, перш ніж ми зможемо розпочати наземний наступ на Поле Боротьби.",  -- db:6732
[504401061] = "У нас майже немає запасів.  Потрібно ще чимало попрацювати, перш ніж ми зможемо відправити черговий наземний десант на Поле Боротьби.",  -- db:6733
[346663319] = "Мені потрібно набагато більше ресурсів, щоб модернізувати наші підрозділи.",  -- db:6735
[395137071] = "У мене майже вистачає ресурсів, щоб покращити наші війська.",  -- db:6736
[627437334] = "Ой... ці шкідники не дають мені спокою ні вдень, ні вночі! Ти їх не бачив?$B$BI якби я тільки міг просто стрибнути в трубу, щоб втекти від них...",  -- db:6741
[948609351] = "У мене є приблизно половина ресурсів, необхідних для підвищення рівня до чемпіонських підрозділів.",  -- db:6775
[570828416] = "У мене майже вистачає ресурсів, щоб модернізувати підрозділи до рівня ветеранів.",  -- db:6779
[980295777] = "У мене є приблизно половина ресурсів, необхідних для перекваліфікації підрозділів у ветеранські.",  -- db:6781
[164072838] = "У мене майже немає ресурсів для модернізації.",  -- db:6784
[920518226] = "У мене є достатньо ресурсів, щоб підвищити рівень наших військ до рівня ветеранів.",  -- db:6789
[702144930] = "У мене є достатньо ресурсів, щоб перетворити наших солдатів на чемпіонів.",  -- db:6790
[687622006] = "Твій рівень майстерності вищий за мій, хоча я чув, що старий Хемінг у Буті-Бей має примірники книги «Бас і ти». Це, безсумнівно, допоможе тобі підвищити свій рівень майстерності.",  -- db:6793
[398294109] = "Твій рівень майстерності вищий за мій, хоча я чув, що старий Хемінг у Буті-Бей має примірники книги «Бас і ти». Це, безсумнівно, допоможе тобі підвищити свій рівень майстерності.",  -- db:6794
[695275294] = "Будь ласка, будь ласка, будь ласка, скажи мені, що ти прийшов, щоб визволити мене з цих кайданів.  Десь же має бути ключ...$B$BПринаймні, може, ти зможеш знешкодити охоронця Сліп’кіка.  Гадаю, я зможу тобі допомогти!$B$BБачиш ту зламану пастку он там?  Огри занадто тупі, щоб з’ясувати, як її полагодити.  Очевидно, їй потрібен торієвий пристрій і трохи морозного масла.  Якщо ти її полагодиш, я впевнений, що зможеш заманити Сліп’кіка в неї, і БАМ — огровий охоронець у пастці!",  -- db:6795
[184223211] = "В Альтераку є дві шахти: «Залізна глибина» на території Альянсу та шахта «Холодний зуб» на території Орди. Обидві шахти є багатим джерелом корисних копалин, і в минулому їх використовували для зберігання надлишкових запасів.$B$BЗараз за ці шахти постійно точаться бої між Ордою, Альянсом та місцевими мешканцями.",  -- db:6796
[215954740] = "Вежі та бункери в Долині Альтерака є надзвичайно важливими стратегічними об’єктами. Якщо ми контролюємо вежу, наші війська можуть вести вогонь з неї на великі відстані.",  -- db:6797
[359568144] = "На кладовищах у Долині Альтерак душі померлих знаходять спокій і розраду. Якщо ви загинете, ваш дух попливе до найближчого кладовища, яке контролюється нашою стороною.",  -- db:6798
[555213625] = "Поглянь на це спустошене поле і усвідом, яку силу мають стихії, $r.",  -- db:6812
[892021911] = "«Тауер-Пойнт» контролює перевал між «Полем битви» та територіями Орди на півдні.$B$BВін перебуває під контролем Орди.",  -- db:6832
[245261567] = "«Тауер-Пойнт» контролює прохід між «Полем битви» та територіями Орди на півдні.$B$BВін не перебуває під контролем жодної зі сторін.",  -- db:6833
[615771262] = "Вежа «Західний Морозний Вовк» охороняє ворота між селищем Морозних Вовків та фортецею Морозних Вовків.$B$BВона перебуває під контролем Орди.",  -- db:6838
[556389845] = "Я багато знаю, слухаю та навчаюся, $r.",  -- db:6842
[561172073] = "У часи, що передували початку часів, — у той період, який узурпатори згодом назвали Першою Епохою Створення, — мій володар та його брати й сестри правили цим світом. Саме вони, Старі Боги, створили все.$B$BІ саме їх зрештою скинули з трону ті, хто називав себе Творцями.$B",  -- db:6843
[87092553] = "Їхні матеріальні втілення, ослаблені віками битв, ув’язнені під поверхнею світу — того самого світу, який вони самі створили, — гниль Титанів-Творців просочувалася на поверхню й оскверняла Старих Богів.$B$BСаме тоді й саме там брати зрадили. Протягом п’яти тисячоліть у самому серці цього світу точилася битва.$B",  -- db:6844
[680349482] = "Капітани як Орди, так і Альянсу вийшли на поле бою. Наша капітанка Балінда Стоунхарт керує військами «Штормпайк» з аванпосту «Стоунхарт», а ворожий капітан Галвангар віддає накази з гарнізону «Айсблад».$B$BУ бій!",  -- db:6846
[459740022] = "Капітани як Орди, так і Альянсу вийшли на поле бою. Наш капітан Галвангар керує «Морозними вовками» з гарнізону «Крижана кров», а його суперниця, капітан Балінда Стоунхарт, переховується у своєму форпості «Стоунхарт».$B$BБитва розпочалася!",  -- db:6848
[735322000] = "Капітан Галвангар загинув! Вшануймо пам’ять нашого загиблого капітана та знову киньмо виклик Альянсу!",  -- db:6851
[501157065] = "Долина Альтерак вже багато років є батьківщиною клану Морозних Вовків; ми не дозволимо карликам та їхньому Альянсу вторгнутися на нашу землю!  Тож ми вступаємо в бій!$B$BЩоб відвоювати Альтерак, переможіть їхнього генерала Ванндара Штормпайка в Дун-Балдарі.$B$BЗа Орду!",  -- db:6853
[897197223] = "«Штормпіки» виявили стародавні артефакти в Долині Альтерака, але орки з племені «Морозних Вовків» не надто прихильно ставляться до дослідників. Якщо карликам доведеться битися за знання своїх предків, то нехай так і буде!$B$BЩоб виграти цю битву, переможіть орка Дрек’Тара в фортеці «Морозних Вовків».  Нехай удача буде з тобою, $c!",  -- db:6854
[813000081] = "Капітан Балінда Стоунхарт очолює війська Альянсу на передовій.  Вона базується в аванпості Стоунхарт, у північній частині Поля Битви.$B$BНаразі Балінда перебуває в аванпості Стоунхарт.",  -- db:6859
[813528392] = "Дрек'Тар — військовий і духовний вождь клану «Морозних вовків» в Альтераку, який керує своїми побратимами з фортеці «Морозних вовків».$B$BЯкщо його перемогти, то війська Орди в Альтераку зазнають поразки.",  -- db:6861
[379507711] = "Капітан Галвангар — надійний помічник Дрек’Тара. Він очолює війська Орди з гарнізону «Крижана кров», що розташований у південній частині Поля Сутички.$B$BКапітан Галвангар наразі перебуває в гарнізоні «Крижана кров».",  -- db:6863
[227924019] = "Саме під час «Розколу Стихій» Володар Вогню, Рагнарос, намагався поглинути мого Господа, Тундераана, Принца Повітря.$B$B<Демітріан схиляє голову, його обличчя спотворене люттю.>$B$BПромов його ім’я — і я прикрашу цим спустошеним табором твоїми нутрощами. Замовкни й слухай.$B",  -- db:6867
[921543617] = "Саме лейтенанти Рагнароса — Геддон і Гарр — вчинили зраду проти мого Господаря. Тундераан був захоплений зненацька.",  -- db:6868
[940954658] = "Про наміри Володаря Вогню Тандераан не мав жодного уявлення. Не встиг мій Володар зреагувати, як Сульфурас — легендарний молот Рагнароса — завдав йому нещадного удару. Тандераан впав, зазнавши повної поразки.$B$BВолодар Вогню наситився сутністю мого Володаря, але не зміг поглинути його повністю.",  -- db:6869
[64429501] = "Те небагато, що залишилося від сутності Тундераана, було збережено в талісмані, що зв’язував стихії. Потім Рагнарос розбив талісман на дві досконалі частини. Ці частини були передані його лейтенантам...$B",  -- db:6870
[416960091] = "Дун-Балдар — найміцніший оплот Альянсу в Долині Альтерак. Розташований у північній частині долини, Дун-Балдар є плацдармом для всіх наступальних операцій на південь.$B$BДун-Балдар залишається неушкодженим.",  -- db:6871
[759867512] = "Ви знайшли ключ?  Ну, а чи це саме ТОЙ ключ?  Тобто, чи це ключ, щоб відімкнути ці кайдани?  Ну, $G, пане : пані;, є лише один спосіб це з’ясувати!",  -- db:6875
[101091254] = "Тепер ти великий бос!  Ти — король!  Слава королю $N, королю Гордока!$B$BТепер, коли ти став босом, усі поплічники будуть платити тобі данину!  Ти залишив декого в живих, так, босе?",  -- db:6876
[359035198] = "Хочеш пограти, смердючко?",  -- db:6877
[943144088] = "У мене в руках ключ до країв свободи! Переслідуй мене — і ти побачиш!",  -- db:6878
[799853373] = "Ще живий? Ти мене дійсно дивуєш. Дивись, як я втікаю!",  -- db:6879
[225257252] = "Не хмурся, посміхнися!",  -- db:6880
[410369884] = "Це кінець шляху, друже мій!",  -- db:6881
[465981195] = "Е-е-е, ти вбив короля, так?  Це означає, що ти займеш його місце.  Тепер ти — новий бос!  Хай живе король!",  -- db:6882
[932865988] = "Що ж, з того, що я встиг дізнатися, чекаючи, поки мене з’їдять ці селюки... можливо, не обов’язково вбивати кожного огра, якого тут зустрінеш.$B$BНещодавно огри без кінця розповідали про те, як король Гордок прийшов до влади; а саме, що він вбив попереднього короля й зайняв його місце.  Що ж, прибічники короля — ті, кого Гордок пощадив, — одразу присягнули на вірність новому королю.$B$BХто знає — можливо, той огр, якого ти врятуєш, і є твоїм власним... у переносному сенсі, звісно!",  -- db:6883
[694075650] = "Тепер ти тут головний, так?  Хай живе новий король!$B$BКріг дозволив тобі подивитися на горілку Гордока.  Горілка огрів — найкраща з усіх горілок, а горілка Гордока — найкраща з усіх горілок огрів!  Може, купиш у мене трохи, босе?!",  -- db:6894
[450777632] = "Гаразд, шефе, коли будеш готовий до данини від своїх підлеглих, дай мені знати!",  -- db:6895
[181825490] = "Залиш це місце, незнайомцю, інакше воно поглине тебе, як поглинуло все, до чого торкнулося.",  -- db:6896
[355581820] = "Чи знаєте ви про Високородних? Про Шен’дралар?",  -- db:6897
[433218039] = "Шен'дралар були найшанованішими арканістами королеви Азшари. Саме в цих стінах виконувалися найважливіші доручення королеви — часто таємно.$B$BПісля руйнування Колодязя та подальшої летаргії, що охопила Високородних і менші секти нічних ельфів, принц Елдре'Таласа, Тортхельдрін, розпочав будівництво пілонів, які ви бачите, розкиданих по залах західного крила.$b",  -- db:6898
[955155206] = "Принц замислив ув’язнити демона неймовірної сили за величезним силовим полем. Опори мали б направляти приховану енергію в поле, забезпечуючи його функціонування.$B$BПеребуваючи в ув’язненні, Іммол’тар мав би слугувати джерелом енергії для мешканців Елдре’Таласа.",  -- db:6899
[688287260] = "Висмоктана енергія підтримувала магію Високородних, дозволяючи тим, хто перебував у стінах Елдре’Таласа, вгамовувати свої нескінченні й дедалі сильніші магічні прагнення.$B$BМинули тисячі років, і сила, необхідна для утримання Іммол’тара в ув’язненні та підтримання життя в Елдре’Таласі, почала змінюватися. Витрати на утримання Іммол'тара в кайданах зросли настільки, що перевершили темпи, з якими енергію можна було викачувати та розподіляти. Те, що колись було чистим прибутком, перетворилося на збиток.",  -- db:6900
[542920397] = "Привиди з роду Хайборн, яких ви бачите, як вони блукають по двору та залах Елдре’Таласа, були вбиті не нападниками-ограми з Гордока чи сатирами, а самим Принцом!",  -- db:6901
[37710484] = "Людей було знищено заради збереження безсмертя Принца та його майже безмежних сил. Сила, що колись була розподілена між тисячами, тепер зосереджується в Принці та фанатиках Шен’дралар. Ті нечисленні вцілілі безпосередньо подають силу до пілонів, щоб утримувати Іммол'тара в ув'язненні.$B$BЯкщо демон звільниться від своїх пут, він неодмінно знищить те небагато, що залишилося від цього колись величного бастіону магії.",  -- db:6902
[634200404] = "Ти тепер крутий, друже!",  -- db:6903
[742031508] = "Фенгуси роблять тебе лютим!  Оскаженілим!  РАР!",  -- db:6904
[13476503] = "Ти мене добре підловив, шефе!  Сліп'кік застряг тут у великому крижаному блоці!  Але я кмітливий, скоро виберуся!  Ха-ха!$B$BМоже, лід скоро розтане...",  -- db:6905
[520039060] = "Я покажу тобі, який я розумний, шефе!  Тепер ти станеш ще розумнішим завдяки потужній магічній силі!$B$BЕ-е-е... якби ти міг трохи розтопити лід для Сліп'кіка, це було б чудово...",  -- db:6906
[621192854] = "Ти — король Гордока! Ти — номер один!",  -- db:6907
[971949969] = "Я чув, що ти помер... ну, після цього тебе вже не так легко буде вбити!",  -- db:6908
[360248200] = "Протягом 10 000 років я правляв цим королівством. За цей час я почув безліч захоплюючих історій від тих, хто ступав на священну землю Дому Шен’дралара.$B$BОскільки я прив’язаний до цього місця, я часто обмінююся історіями з відвідувачами. Чи маєте ви для мене якусь історію, або, можливо, ви хотіли б почути якусь історію?",  -- db:6909
[553152337] = "Ми не повинні розгнівати Господаря. Його гнів — безмежно жорстокий.",  -- db:6911
[3110970] = "Говори тихіше, незнайомцю. Ти ж не хочеш заважати Господареві медитувати.",  -- db:6911
[283867446] = "Багато хто прийшов до цього притулку, але мало хто звідти пішов.",  -- db:6911
[736301309] = "Хранитель Переказів — це Стародавній. Він служив під керівництвом нашої славетної Королеви!",  -- db:6911
[616390606] = "Останнім часом книги починають зникати. Хранитель Переказів та його помічники у паніці. Вони підозрюють, що в Елдре’Таласі відбувається щось недобре.",  -- db:6911
[48735690] = "Чи відмовився Принц від розповіді про «Попелоносія»? Це наша найулюбленіша з його історій. А його улюбленою є продовження історії про «Попелоносія». Звісно, нікому ще не вдалося витягнути з нього цю історію.",  -- db:6911
[313857718] = "Я підозрюю, що імпи крадуть знання.",  -- db:6911
[855930551] = "Майстер виявляє великий інтерес до лігва Нефаріана. Якби тільки хтось переміг дракона та його поплічників і розповів про це Принцу. Готовий побитися об заклад, що це змусило б Принца розговоритися. Тоді «Попелоносець» міг би бути знайдений!",  -- db:6911
[564511748] = "Що ти тут робиш, блукаєш? Чому ці дрібні злочинці не в кайданах?!",  -- db:6913
[288689981] = "Тепер ти — найсильніший!  Слава новому королю Гордока!",  -- db:6914
[922205833] = "Я бачу, що вони все ще озброєні? Чому ти дозволив їм залишити зброю?!",  -- db:6915
[175220325] = "Усі поплічники боса — Стомпер Кріг, усі троє охоронців, капітан Кромкраш та Спостерігач — віддають данину новому босу. Якщо ти вб’єш поплічника, він не зможе віддати данину! Кожен, кого ти залишиш живим, принесе тобі більше данини.  Збережіть їх усіх живими — і ви отримаєте ВЕЛИКУ данину!$B$BТак!",  -- db:6916
[249561745] = "О, який жах! Яка трагедія! Ми на порозі прориву, але все може піти нанівець.",  -- db:6917
[725348864] = "Е-е... Вибач, що напав на тебе, босе.  Не вбивай мене, будь ласка, добре!?  Тепер ти король, а я допоможу тобі зробити твою данину ще кращою!",  -- db:6918
[343655870] = "Поверхневий огляд кісткових решток свідчить про те, що плоть була обпалена. Досить моторошне видовище.",  -- db:6919
[292737134] = "Може, тобі вдасться краще, ніж старому босу, повернути цінну реліквію Гордока від того моторошного принца з роду Високородних!",  -- db:6920
[491330271] = "Слава новому королю!",  -- db:6922
[895634709] = "Коли я на тебе нахмурився ще до того, як ти став новим королем... е-е... я просто жартував.$B$BТак!",  -- db:6922
[450519766] = "Ті інші огри були дурні, що на вас напали, босе! Ось чому я досі живий — я ж розумний і все таке!",  -- db:6922
[21760195] = "Ми набагато чистіші, ніж ті огри в Танарісі.  По всій пустелі, скільки сягає око, — огрівські екскременти.  Тут такого немає, ні, $g, пане : пані!",  -- db:6922
[558049425] = "Поки ти залишаєшся тут з нами, ти — король. Як тільки ти підеш, твоє місце займе якийсь інший людожер. Такі вже правила Гордока!",  -- db:6922
[878580773] = "Я такий розумний!  Р-О-З-У-М-Н-И-Й!",  -- db:6922
[819059008] = "Старий король помер?  Це неможливо!",  -- db:6922
[802977401] = "Я не створюю вам жодних клопотів, шефе.",  -- db:6922
[666175150] = "Якщо не поговориш із Міззлом, то не станеш королем! Звернися до Міззла-Хитрого!",  -- db:6923
[328173782] = "Отже... ти усунув короля, так?  Я знав, що ці дурні зроблять тебе новим королем, просто знав!  Це єдине, що ці дурні розуміють — влада.$B$BСхоже, чим більше поплічників ти залишиш живими, тим більшою буде твоя данина.  Непогано — я б сказав, це цікавий виклик.  Якщо ти підеш, я б не розраховував залишитися королем.  Один із цих селюків, без сумніву, висунеться й займе твоє місце.$B$BІ ще одне... ти часом не знайшов мій ключ, правда?",  -- db:6924
[489188341] = "Ви повинні зрозуміти: те, що я зміг охопити своїм баченням 10 000 років існування, дало мені досить унікальний погляд на життя. Ваші сучасні випробування та негаразди не мають жодного значення.",  -- db:6925
[861880086] = "О, скільки драматизму та галасу влаштував молодий пан! Можна було б подумати, що доля світу цілком лежала на його плечах. Лише смертні можуть мати таке викривлене уявлення про наш світ.$B$BНа жаль, він залишив мені свої мізерні магічні секрети... Лібрими чи ще якусь подібну нісенітницю. Мені ці мізерні чари ні до чого, але, можливо, вам будуть цікаві їхні заклинання.",  -- db:6926
[597618407] = "Їх викрали, $r! Три наших найцінніші томи. Якщо ви повернете ці фоліанти, нагорода вам гарантована.",  -- db:6927
[267159629] = "<Ти не можеш розібратися в жодній з технічних нісенітниць, що містяться в цьому сувої.>",  -- db:6929
[794944365] = "<На цьому пергаменті намальована схема польового ремонтного робота.>",  -- db:6930
[826911465] = "<Ці складні схеми занадто складні, щоб твої мізерні інженерні здібності змогли їх розібрати.>",  -- db:6931
[933628789] = "<Ви добре обізнані з принципом побудови та функціонування цього робота.>",  -- db:6932
[585550080] = "Тканина, з якої витканий наш світ, надзвичайно тендітна. Щоб розірвати її, достатньо лише трохи знань та вміння застосувати ці знання. Ось так і виникають розриви.",  -- db:6933
[97437485] = "Поглянь на ворога, $r. Подивись, до чого сила Орди зводить навіть наймогутніших драконів! Усі, хто протистоїть нам, зазнають такої самої долі!",  -- db:6934
[37398319] = "Я — той, хто беззаперечно виконує накази Вождя. Я — Орда.",  -- db:6935
[833644686] = "Я живу лише для того, щоб служити нашому Королю.",  -- db:6936
[573870207] = "Можливо, одного дня твій внесок у справу Альянсу буде таким же великим, як і внесок героїв, яких ти побачив сьогодні. Вшануй їх, $N.",  -- db:6937
[260267441] = "Ви вшановуєте нас своєю присутністю, мій пане.",  -- db:6938
[864070048] = "10 000 років накопичених знань, як правило, приваблюють до Атенеуму небажаних відвідувачів. Книги щодня крадуть, повертають, а потім знову крадуть.",  -- db:6939
[496997143] = "Кілдрат схильний надмірно драматизувати ситуацію. Наприклад, книгу «Гарона: дослідження про скритність і зраду» викрадали понад 400 разів.$B$BЗнак Атенеуму захищає фоліанти, запобігаючи будь-якому несанкціонованому перегляду.",  -- db:6940
[806565997] = "У мене немає часу на переривання.",  -- db:6947
[504625315] = "Чим можу допомогти?",  -- db:6948
[39083844] = "Так, але я знаю його справжнє ім’я — Елдре’Талас. Багато-багато років тому це було оплотом магічної сили для нічних ельфів.$B$BТи знаєш про Елдре’Талас, юнаку?  Хтось міг би сказати, що це збіг обставин, пов’язаний із моїм нинішнім становищем… але я не вірю у збіги.",  -- db:6949
[791888108] = "Агенти Кола Сенаріона виявили тривожну інформацію щодо поточної ситуації в Елдре'Таласі.  Я не знаю, що з цим робити, і, без сумніву, незабаром звернуся по допомогу до сильних істот, здатних дати відсіч у бою.$B$BОднак щоб вжити належних заходів в Елдре'Таласі, необхідно розібратися в історії предмета, відомого як «Плід родючості».",  -- db:6950
[291250121] = "У давні часи Елдре'Талас був осередком магічної сили, і ті, хто мешкав у його священних залах, володіли величезною владою.  Однією з таких нічних ельфів була Міллісент Серен — натуралістка, яка вкладала силу самої природи у потужні артефакти, що вона кувала.$B$B«Плід родючості» став її найвидатнішим досягненням… Вона використовувала спеціально підготовлене місячне джерело, щоб виростити екзотичну й яскраву лозу, наділену аурою захисту та зростання.  Увесь Елдре’Талас процвітав завдяки його існуванню.",  -- db:6951
[646127601] = "На жаль, завжди здається, що так і є. Я — як і решта членів Кола Сенаріону — вважав, що творіння Міллі було знищено під час Війни Древніх.  Як я з’ясував, це далеко не так.$B$B«Плід родючості» вижив… хоча тепер він відомий як Фелвайн.  Його спотворює демонічний володар тієї частини Елдре’Таласа, Альзін Дикий Творець.",  -- db:6952
[411818516] = "Я... навіть уявити собі не можу, $N.  Знаю лише одне: я не дозволю, щоб це сталося.  Воно буде знищено — якщо не заради того, щоб ми й надалі були захищені від демонічного зараження, то заради пам’яті про Міллісент Серен... Міллі...$B$BОсь тут, мій друже, я сподіваюся, що ти нам допоможеш.",  -- db:6953
[2002028] = "<Деметріан падає на коліна.>$B$BТи віднайшов вічну в'язницю мого Господаря!$B$BЯк довго я чекав на цей день, і ось, нарешті, він настав.$B$BЙого треба звільнити!",  -- db:6954
[804279606] = "Я тримаю в руках посудину його відродження. Якщо ти готовий взяти на себе це завдання, тобі доведеться зміцнити цю посудину і, зрештою, зняти закляття самого Рагнароса!",  -- db:6955
[32850265] = "Посудину відродження потрібно зміцнити елементієм. Мені відомо лише одне джерело цього мінералу: елементарні площини, що знаходяться в самому серці нашого світу.$B$BЄ один — Формувач Землі, — який, можливо, знає про здобуття таких речей більше, ніж я. Ти повинен знайти цього Формувача Землі!",  -- db:6956
[243480878] = "Вітаю тебе, герою!  Маю для тебе найсвіжіші новини з обох континентів та інших куточків світу.",  -- db:6957
[560481713] = "Фізичну форму Рагнароса необхідно знищити. З її уламків вийде його сутність. У цьому ослабленому стані влада Рагнароса над в’язницею Тундераан послабиться. Сама сутність виступить у ролі ключа...",  -- db:6958
[144684817] = "Щоб досягти кращих результатів, ніж зараз, вам потрібно знайти Ната Пейгла в Болоті Дастволл.",  -- db:6959
[596021603] = "Я можу навчити вас рибальським навичкам.",  -- db:6961
[91598717] = "У болоті Блюгілл-Марш, що на північ від гавані Менетіл у Водно-болотних угіддях, можна знайти безліч зачинених скриньок із затонулих суден, які винесло на берег.",  -- db:6974
[210969365] = "У водах північної частини берега Сар'теріс у Десоласі або у фортеці Ангор у Пустошах є зачинені скриньки, які можна відкрити за допомогою відмички.",  -- db:6975
[669260943] = "У «Озері сліз» у «Болоті скорботи» зберігаються стародавні зачинені скриньки, які загубилися ще в інші часи.",  -- db:6976
[877256223] = "У карликів Темного Заліза зі Шлакової Ями в Палючому Ущелині є велика кількість замкнених скриньок.",  -- db:6977
[973998650] = "Як у бухті Лост-Ріггер у Танарісі, так і в Затоці Бур у Азшарі є скриньки, які можна відкрити, щоб підвищити свій рівень майстерності.",  -- db:6978
[511661117] = "У «Скарлет-хрестовому поході» «Руки Тира» у Східних Землях Чуми є чимало скриньок, які стануть справжнім випробуванням для ваших навичок.",  -- db:6979
[919643622] = "Орки затопили в озері Еверстілл у Червоногір'ї безліч зачинених ящиків із припасами.",  -- db:6980
[809484414] = "Коли нага захопили Зорам-Стренд у Попеліній долині, було втрачено багато зачинених ящиків із припасами.",  -- db:6981
[589500877] = "Компанія «Venture», що базується поблизу скелі Віндшир-Крег у Стоунталоні, зберігає свої запаси у зачинених ящиках.",  -- db:6982
[990284785] = "Синдикат зберігає безліч зачинених ящиків із припасами у фортеці Дурнхолд у Хіллсбраді.",  -- db:6983
[966654040] = "Я вивчаю відомі та невідомі елементи нашого світу.",  -- db:6985
[799004079] = "Настає момент, коли життя, яке ми знаємо, виявляється недостатнім. Ми опиняємося в пастці, шукаємо відповіді — і знаходимо надію, що палає у темряві.$B$BЛише тоді, $N, ми робимо перші кроки до свободи.",  -- db:6990
[960696798] = "$C, у тебе є павуки чи жуки? Вони швидко бігають, але якщо ти будеш швидшим за них, то вони стануть для тебе справжньою смакотою!",  -- db:6991
[555165904] = "Ти щойно вийшов із підземелля?  Ти щось мені приніс?",  -- db:6992
[685467426] = "Коли я виросту, я хочу стати королем Штормовію!",  -- db:6992
[663489804] = "Я вже бував у Айронфорджі. Там дивний запах.",  -- db:6992
[553460088] = "Гриби завжди ростуть у вологих місцях, тому вони схожі на парасольки.",  -- db:6992
[375614803] = "Якщо комбінезон тримається на кнопках у верхній частині, то навіщо в ньому петлі для ременя?",  -- db:6992
[192889950] = "Що станеться, якщо соплі замерзнуть у носі?",  -- db:6992
[289151656] = "Чи буває у риб спрага?",  -- db:6992
[797106503] = "Якщо ви спробуєте зазнати невдачі, але досягнете успіху, що ви щойно зробили?",  -- db:6992
[793666688] = "Твоя броня виглядає страшно.  А ти теж страшний?",  -- db:6993
[857501828] = "Якщо ти справжній герой Орди, то я хочу побачити, як ти битимешся з драконом!  Так!",  -- db:6993
[139460069] = "Коли блискавка влучає в океан, чому не гинуть усі риби?",  -- db:6993
[712319833] = "Чи називали б муху без крил «ходоком»?",  -- db:6993
[344104659] = "У мене в носі застряг камінь.",  -- db:6993
[925896023] = "Якщо у черепахи немає панцира, то вона бездомна чи гола?",  -- db:6993
[922485547] = "Що означає «zug zug»?",  -- db:6993
[476894914] = "Якщо рукавичка завелика, чи все одно вона сидить як влита?",  -- db:6993
[861360260] = "Ви, безперечно, дуже далеко від дому, $r.",  -- db:6995
[955086379] = "Отже, ти мене знайшов. Припускаю, що ти прийшов, аби дізнатися про придушення та контроль.$B$BI Я навчу тебе набагато більше, ніж це... ти також дізнаєшся про жертву.$B$B<Дайо посміхається.>",  -- db:6996
[151418500] = "Це буде вибір демона, якого ти бажаєш викликати й підкорити. Ми володіємо темними силами і дорого платимо за використання цих сил.",  -- db:6997
[946522601] = "Якщо ти хочеш рухатися далі, нам спочатку треба збудувати в’язницю, щоб утримати ту звіра.",  -- db:6998
[462438154] = "Схилися переді мною, комахо! Ти ж, безперечно, відчуваєш ту владу, яку я маю над тобою.",  -- db:7001
[714207970] = "Отже, ти прибув до Нібі, щоб дізнатися секрети виклику пекельного слуги з Нижнього світу.$B$BТихо! Нібі знає все!$B$BNібі не так легко ділиться такими знаннями. Спочатку ти повинен допомогти Нібі виконати дуже важливе завдання.",  -- db:7002
[398869215] = "На північний схід від цього табору мешкає могутній інфернал на ім’я Крошіус. Саме тому Нібі тут. Крошіус — це великий інфернал, тобто інфернал, який проіснував довше, ніж очікувалося. Розумієш, новачку, інфернал з величезною силою врізається в землю, щоб служити своєму господареві, але ця сила швидко згасає. Як тільки палаюче полум’я згасає, інфернал розсипається.",  -- db:7003
[919400318] = "Не перебивай Нібі, дурню! Я зірву з тебе м’ясо з кісток і використаю твої скелетні останки як вішалку для одягу. Так, на чому я зупинився? Ах так, отже, Крошіус протримався майже вдесятеро довше, ніж будь-який звичайний пекельник. Не знаю, чому, але впевнений, що, ретельно дослідивши це питання, я зможу з’ясувати причину.$B$BI Потрібно, щоб ти віднайшов Пекельне Ядро Крошіуса.",  -- db:7004
[486468462] = "Якщо я маю навчити тебе таємницям виклику пекельного слуги, ти повинен знищити Крошіуса і принести мені пекельне ядро з його палаючих останків. Однак це не так просто, як здається. Крошіус майже повністю згорів. Ти повинен знову розпалити його труп і підняти його з-під уламків. Однак для цього тобі доведеться зібрати деякі компоненти від інших демонічних істот.$B$BМій імп, Імпсі, вкаже тобі шлях.",  -- db:7005
[485620625] = "Війна має свою ціну, $c... яку часто не беруть до уваги.  Ця ціна — це сироти — діти, які втратили батьків у результаті надто численних конфліктів, що вирують по всьому Азероту.  Ці діти, яким більше ні до кого звернутися, часто приходять сюди, щоб жити тут, доки не стануть достатньо дорослими, щоб самостійно дбати про себе.$B$BОдин тиждень на рік навесні Орда знаходить час, щоб віддячити цим невинним дітям.  Цей час називається Тижнем дітей.$B",  -- db:7010
[379814111] = "Війна має свою ціну, $c... яку часто не беруть до уваги.  Ця ціна — це сироти — діти, які втратили батьків у результаті надто численних конфліктів, що вирують по всьому Азероту.  Ці діти, яким більше ні до кого звернутися, часто приходять сюди, щоб жити тут, доки не стануть достатньо дорослими, щоб самостійно дбати про себе.$B$BOдин тиждень на рік навесні Альянс знаходить час, щоб віддячити цим невинним дітям.  Цей час називається Тижнем дітей.$b",  -- db:7011
[623586035] = "О... це дуже мило з вашого боку.  Як я розумію, ви присвячуєте свій час волонтерській роботі в рамках Тижня дітей, так, $c?  Що ж, ви заслуговуєте на похвалу.  Нам обов’язково слід пам’ятати про тих, кому пощастило менше, — особливо про дітей.$B$BIЗ радістю дам автограф.  Ось, будь ласка.",  -- db:7012
[41448515] = "Вітаю, юний друже, і ласкаво просимо до Громового Утвору.  Тут ти знайдеш надійний притулок від тягаря цього світу.  Усі мешканці Орди тут завжди бажані гості.$B$BУ цьому священному місці оживають духи сьогодення та минулого, мій друже.  Вшануй їх — і тим самим вшануй самого себе.",  -- db:7013
[361864360] = "Ага, без сумніву, майбутній молодий воїн!  Я так розумію, ти береш участь у Тижні дітей, так?  Мені так приємно чути, що ти подаєш приклад, за яким інші неодмінно підуть.$B$BIБуду радий допомогти тобі та цьому юнакові.  Хм... яку пораду мені йому дати?  Прислухатися до духів, так... може, ще щось про те, щоб він з’їдав усі овочі...",  -- db:7014
[661255314] = "Кулінарія — це справа всього життя, і я бачу, що ми поділяємо одну й ту саму пристрасть!",  -- db:7015
[751266481] = "Знайдіть Шандріну в Притулку Срібного Вітру.  Вона може продати вам «Кулінарну книгу для експертів».",  -- db:7016
[977819570] = "Дірдж Квікклів із Гаджетзана — майстер кулінарного мистецтва. Щоб вдосконалити свої навички, вам слід знайти його.",  -- db:7017
[723973048] = "Улан із селища Шейдоупрей може продати вам «Кулінарну книгу експерта». Вона знадобиться вам, якщо ви хочете вдосконалити свої навички.",  -- db:7019
[26411765] = "Я можу навчити тебе готувати!",  -- db:7021
[809817122] = "Зараз лише відомий доктор Грегорі Віктор може підвищити ваш рівень майстерності. Його можна знайти в Аратських височинах, у місті Хаммерфолл.",  -- db:7024
[556517085] = "Балай Лок'Вейн із села Брекенволл у Болоті Дастволл продає посібник, який вам потрібно буде вивчити, щоб підвищити свої навички!",  -- db:7025
[508868160] = "Поважний доктор Густаф ВанХаузен може надати вам подальше навчання. Його можна знайти в Тераморі, де він лікує поранених у казармах.",  -- db:7026
[336089019] = "Я чув, що у Денеба Уокера, який переховується у Стромгарді, є книга, яка, без сумніву, допоможе вам удосконалити свої навички надання першої допомоги.",  -- db:7027
[883041384] = "Я можу навчити вас навичкам надання першої допомоги.",  -- db:7028
[87126757] = "Душа «Страшного коня» вирує від люті.",  -- db:7036
[154177156] = "Шляхи Джеденара темні й підступні. Будь обережним у цьому місці, $C, інакше твої суперники зачарують твою душу...",  -- db:7037
[416113861] = "Геть!  Я радяться з Повелителями Жаху, і те, що ми обговорюємо, тебе не стосується!",  -- db:7038
[424086706] = "... Повідомлення з Бейнхоллоу?  Що це за повідомлення?  Чи потребує він допомоги свого великого радника й слуги Улатека?  Чи потрібна йому моя присутність?",  -- db:7039
[294385099] = "Що?  Але як?  Ні!  Це неможливо!  Я була така обережна... він не міг знати!$B$BТи брешеш!  Ти брешеш, і тепер помреш за свою брехню!",  -- db:7040
[764643554] = "Який чудовий день — бути живим! Поглянь на красу, що оточує тебе, друже. Насолоджуйся тим, що дарує життя!",  -- db:7041
[569542520] = "*ГРРРР* *ГАВ* *ГАВ*",  -- db:7042
[313324444] = "Лава? Не звертай на це уваги, друже. Подивися навколо. Насолоджуйся красою, яку дарує природа.",  -- db:7043
[126622472] = "Я щороку приблизно в цей час приїжджаю до Сілітуса. Погода тут просто чудова для моїх бурситів.$B$BТобі варто прогулятися зі мною, друже. Помилуйся краєвидами та іншим.",  -- db:7044
[396405344] = "Як чудово зустріти ще одну людину в цьому віддаленому куточку світу. Ходімо, прогуляймося разом. Нехай наші тіла зігріють одне одного.",  -- db:7045
[658409844] = "Шукайте його високо на західному схилі Долини Сили.",  -- db:7046
[130542345] = "Вам потрібно дістатися до Залу Легенд. Він розташований високо над Долиною Сили, на західному боці.",  -- db:7046
[345960942] = "Ти раптом став «Захисником Альянсу», так?! Ну що ж, мабуть, тепер ти захочеш вирушити до Залу Чемпіонів. Він розташований у Старому місті.",  -- db:7047
[770339903] = "О-о, бачимо, ми піднімаємося по кар’єрних сходах? Ти шукаєш Зал чемпіонів — його можна знайти на південно-східній околиці Старого міста. Удачі!",  -- db:7047
[471414347] = "Якщо ви шукаєте найкращі зразки майстерності на цьому чи будь-якому іншому континенті світу, то ви потрапили саме туди, куди треба!$B$BГріманд Елмор — до ваших послуг!",  -- db:7055
[789528461] = "Щоб викликати «Коня Жаху», спочатку потрібно створити «Коло Великого Викликання».  Портал до Ксорота можна створити лише всередині такого кола.$B$BДля «Кола Великого Прикликання» потрібні три могутні предмети: Дзвін Детмури, Колесо Чорного Походу та Свічка Судного Дня.",  -- db:7056
[136582282] = "Арр!   Немає нічого, що я люблю бачити більше, ніж людей, які б’ються на смерть на арені.   Якщо ти опинишся тут у потрібний час, то, можливо, зможеш стати одним із них!",  -- db:7074
[670744890] = "Так, це правда, я сліпий як кажан! І п’яний як… е-е, п’яний як щось, що п’ється.$B$BСкажу вам ось що, $r. Саме випивка допомагає мені зберігати гостроту чуттів. Загальновідомо, що коли втрачаєш одне чуття, інші стають гострішими. Моє п’яне чуття останнім часом просто неймовірне.",  -- db:7094
[481176389] = "Ми вирішили покинути захист і затишок Глибин, щоб... е-е, тобто... хм, так, саме так, ДОСЛІДЖУВАТИ світ.",  -- db:7095
[662351931] = "Можливо, це все-таки не найкраще місце для магазину...",  -- db:7114
[559527270] = "Мене звати Бернінат, я займаюся ковальством... і, е-е-е... ще трохи продаю їжу та воду на стороні. Хочеш трохи м'яса?",  -- db:7115
[391677222] = "Ну що ж, знову привіт, $N!  Не знаю, скільки ще я буду намагатися відкрити магазин посеред ніде.  Але, оскільки ти вже допомагав мені раніше, я покажу тобі дещо, що, можливо, тобі буде цікаво!",  -- db:7116
[142205158] = "Коли Лоло не хоче розливати своє дорогоцінне пиво чи забруднити свою маленьку сукню, мене викликають. Ага. Старий Ганзель — це той карлик, якого вони використовують, щоб роздати трохи справедливості й цілу купу болю.",  -- db:7117
[730297362] = "Як виконуючий обов’язки наглядача цього комплексу, я зобов’язаний забезпечити, щоб усі види діяльності, роботи, відпочинку та розваг, які можуть тут відбуватися, супроводжувалися певним рівнем нудьги.$B$BЯкщо ви вважаєте, що те, що вам доручають робити, є надто легким і не вимагає жодних зусиль, негайно повідомте мені про це.",  -- db:7120
[265233683] = "Ти виконав усе, про що я тебе просив, $N. Тут для тебе більше нічого не залишилося. Якщо ти хочеш продовжити кар’єру агента «Братства Торію», звернися до Лохтоса Даркбаргейнера в таверні «Грім Гузлер» у Глибинах Чорної Скелі.$B$BПрощавай!",  -- db:7121
[666393217] = "Незалежно від того, «Братство Торію» це чи ні, якщо хтось із тих «Темних Залізних» наблизиться до мене, він відчує на собі, як моя мотика влучить йому в скроню!  Тож, куди мені надіслати тобі $G, хлопче : дівчино;?",  -- db:7122
[890863326] = "Поки ті гноми залишаються там, у нас не буде жодних проблем. Куди ти прямуєш, $N?",  -- db:7123
[319441548] = "Ти сподіваєшся, що я злякаюся перед могутнім легіоном $N$?$B$BТи для мене ніхто. Менше ніж ніщо. Якби я забажав твоєї голови, її б мені подали на списі.$B$BТи припустився тієї помилки, яку роблять усі смертні.$B$B<Лорд Віктор Нефаріус зітхає.>$B$BЧас робить дивні речі з тими, хто використовує його як валюту.$b",  -- db:7134
[870287443] = "На поверхні кулі видно великий відбиток руки, схожої на людську. Незважаючи на те, що, судячи з усього, з нею постійно щось роблять і її часто беруть у руки, куля залишається без жодних пошкоджень.",  -- db:7154
[764524857] = "Візерунки на кулі збігаються з тавром на вашій руці.",  -- db:7155
[867520483] = "Я... Я зазнав поразки, $N. Володар Бла... Володар Блекрока занадто могутній. Він поглинув мою енергію з... з легкістю. Я перетворююся... Я... вбий мене... ти мусиш... ти мусиш мене вбити.",  -- db:7156
[398762795] = "Я — той, хто стежить за ними. Я — кулак відплати. Той, хто приборкує непокірних. Чи наважишся ти кинути виклик Вождю війни? Чи наважишся ти зіткнутися з моїм безжальним судом?",  -- db:7174
[227400725] = "Хіба ти не бачиш, що я тут рибалю!",  -- db:7175
[873849399] = "Ти налякав рибу!  Чого ти хочеш?",  -- db:7175
[895589109] = "Чим я можу вам допомогти, $c?",  -- db:7175
[655668672] = "Я збираюся залишитися тут, доки не зловив групера вагою 68 фунтів! А ти, навпаки, хочеш кудись звідси злетіти, чи не так?",  -- db:7175
[276538504] = "Поглянь на цього поваленого дракона, $r. Могутність Орди — поза сумнівом!",  -- db:7176
[395980847] = "«Ущелина Лютьвого Вогню» — це мережа вулканічних печер, що простягається під новою столицею орків — Оргримаром. Нещодавно поширилися чутки, що в полум’яних глибинах Ущелини оселився культ, відданий демонічній Раді Тіней. Цей культ, відомий як «Палаюче Лезо», загрожує самому суверенітету Дуротара. Багато хто вважає, що вождь орків Трал знає про існування «Палаючого меча» і вирішив не знищувати його, сподіваючись, що його члени приведуть його прямо до «Ради Тіней». $b",  -- db:7177
[546172590] = "Проходьте, громадянине. Тут нема на що дивитися.",  -- db:7179
[489093365] = "Чи хочете ви відвідати одне з цих підземель?",  -- db:7180
[821183893] = "Тут розкидано стос паперів і схем.",  -- db:7181
[726854764] = "Ці документи перебувають під охороною. Поговоріть із Замеком, щоб відвернути увагу!",  -- db:7182
[382265840] = "Нещодавно друїд нічних ельфів на ім’я Наралекс відкрив мережу підземних печер у самому серці Пусток. Вважаючи, що джерела цих печер допоможуть йому повернути Пусткам колишню пишність, друїд почав викачувати енергію легендарного Смарагдового Сну. Однак його мрія якимось чином перетворилася на кошмар, і незабаром Печери Плачу стали притулком жорстоких і смертоносних хижаків. Кажуть, що Наралекс досі перебуває десь усередині лабіринту, ув’язнений за межами Смарагдового Сну.",  -- db:7183
[683797710] = "Розчарований відсутністю прогресу у боротьбі чарівників Даларана з нежиттю під час Третьої війни, архімаг Аругал вирішив викликати позавимірних воргенів, щоб поповнити ряди своєї сторони, що поступово зменшувалися. Вовколюди розгромили Плеть, а потім швидко обернулися проти самих чарівників і взяли в облогу фортецю шляхтича, барона Сільверлейна. Фортеця швидко занурилася в тінь і руїну. Охоплений божевіллям від почуття провини, Аругал прийняв воргенів як своїх дітей і відступив до фортеці, яку відтепер називали «Тіньозуб». $b",  -- db:7185
[497640794] = "Гей, ти там!  Якщо хочеш заслужити повагу племені Темних Списів, то можеш почати з того, що пожертвуєш цінні ресурси тим, хто їх потребує!  Тканини та бинти ж не ростуть на деревах, як ти знаєш.$B$BЗамість того, щоб продавати різні шматки тканини, які ти знаходиш під час пригод, пожертвуй їх!  Це допоможе тобі заслужити визнання племені Темних Списів!",  -- db:7186
[833069482] = "Колись «Мертві копальні» були найбільшим центром видобутку золота на землях людей, а зараз їх заселяє Братство Дефіас, яке перетворило темні тунелі на своє особисте притулок. Ходять чутки, що злодії завербували кмітливих гоблінів, аби ті допомогли їм збудувати щось жахливе на дні копалень — але що саме це може бути, досі невідомо. Кажуть, що шлях до Мертвих копалень пролягає через тихе, непримітне селище Мунбрук.$b",  -- db:7187
[781654051] = "У ці нелегкі часи навіть невеликий дарунок у вигляді тканини може стати великою допомогою для тих, кому пощастило менше, ніж нам.  Тканина дуже знадобиться для пошиття одягу та виготовлення бинтів — і те, і інше має велике значення для військових зусиль!$B$BЯкщо ви бажаєте пожертвувати шматки тканини оркам з Оргримара, я з радістю їх прийму та подбаю про те, щоб ви отримали належну подяку за це.$B$BЗа Орду!",  -- db:7188
[21359316] = "Ти там... у твоїх власних інтересах допомогти «Покинутим» у ці тяжкі часи.  Слухай уважно, бо я не люблю повторюватися.$B$BЗараз ми відчуваємо гостру нестачу тканини.  Запаси бинтів і простих тканин вичерпуються, і ми приймаємо пожертви, щоб поповнити виснажені запаси.  Хоча ти не отримаєш фінансової компенсації — адже саме це і означає пожертва — твоя допомога не залишиться непоміченою.",  -- db:7189
[936220696] = "Вітаю, $g брате : сестро;... Дозвольте, будь ласка, зайняти у вас хвилинку.$B$BМи, таурени, пережили чимало випробувань і поневірянь, створюючи свою батьківщину. Зараз ми стикаємося з гострою нестачею тканини. Якщо у вас є зайві матеріали, прошу вас пожертвувати їх.  Допомагаючи нам, ти, безперечно, заслужиш вдячність тауренів з усього світу!",  -- db:7190
[879276317] = "Ущелина «Рейджфайр» розташована під «Тіньовою ущелиною» в центрі Оргримара.",  -- db:7191
[355078121] = "Вхід до «Печер Плачу» знаходиться в оазі «Люшвотер», що розташована на південний захід від «Перехрестя» в Пустошах.",  -- db:7192
[706346793] = "Вітаю, друже — дозволь, будь ласка, затримати тебе на хвилинку...$B$BМи багато витерпіли під час випробувань і поневірянь, створюючи Телдрасіл.  Ніби постійних конфліктів тих часів було недостатньо, тепер ми ще й зіткнулися з гострою нестачею тканини.  Якщо у вас є зайві матеріали, прошу вас пожертвувати їх.  Допомагаючи нам, ви, безсумнівно, заслужите вдячність нічних ельфів усього світу!",  -- db:7193
[111241188] = "Ми, вигнанці з Гномерегана, опинилися в ще скрутнішому становищі — у нас закінчуються запаси тканини!  Може, ви нам допоможете, га?!$B$BПринесіть мені зайві шматки тканини, які у вас є, щоб допомогти нам поповнити запаси.  Пожертвувавши їх, ви завоюєте повагу та довіру гномів усього світу.  Це те, чого не можна купити за гроші!  Ну, хоча тканину, мабуть, і можна, але це не має значення...",  -- db:7194
[372844406] = "Гей, ти там! Якщо хочеш заслужити повагу гномів Айронфорджа, то можеш почати з того, що пожертвуєш цінні ресурси!  В Айронфорзі починає бракувати шматків тканини; текстиль і бинти ж не ростуть на деревах, як ти знаєш!$B$BЗамість того, щоб обмінювати на гроші різні шматки тканини, які ти знаходиш під час пригод, пожертвуй їх!  Це допоможе тобі заслужити визнання карликів Айронфорга!",  -- db:7195
[348568673] = "Друже — Штормовій потребує твоєї допомоги та щедрості!$B$BНаші колись великі запаси текстилю критично скоротилися. Зараз Штормовій докладає зусиль у кількох напрямках, щоб відновити ці запаси для виробництва текстилю та бинтів!  Ваш дарунок у вигляді тканини стане величезною допомогою для Штормовію, а також дозволить вам заслужити повагу його мешканців!",  -- db:7196
[456296843] = "Замок Тіньовий Кіготь розташований на півдні Срібної Сосни, трохи північніше від селища Палі.",  -- db:7197
[15729255] = "У своєму прагненні до слави ти вважав, що темп гри залежить від твоїх дій. Чи можеш ти хоч уявити, наскільки абсурдно це звучить для такої істоти, як я? Істоти, яка, якби захотіла, могла б змусити твої власні нікчемні думки розчавити ту масу сірої речовини розміром з арахісове зернятко, що плаває у твоїй черепній коробці.$b",  -- db:7198
[643038148] = "Це насправді дуже просто. Дозвольте мені підсумувати...$b",  -- db:7199
[555750162] = "«Чорноглибські глибини» розташовані на північному краю Зорамського узбережжя, вздовж узбережжя Попелястої долини.",  -- db:7200
[465702243] = "Розташовані вздовж берега Зорам у долині Ешенвейл, «Чорноглибські глибини» колись були величним храмом, присвяченим богині Місяця нічних ельфів — Елуні. Однак Великий Розкол зруйнував храм, і той занурився під хвилі Завуальованого моря. Там він залишався недоторканим — аж доки, приваблені його древньою силою, наги та сатири не з’явилися, щоб розгадати його таємниці. Легенди свідчать, що в руїнах храму оселилася древня потвора Аку’май. $b",  -- db:7201
[616534032] = "Гномереган розташований у західній частині Дун-Морога.",  -- db:7202
[98906636] = "Розташоване в Дун-Морозі, Гномереган протягом багатьох поколінь було столицею гномів, хоча нещодавно його заполонили мутовані троги. У відчайдушній спробі дати відсіч Верховний Майстер Меккаторк наказав терміново провести скидання радіоактивних відходів із міських резервуарів. Хоча троги й зазнали опромінення, їхня облога тривала з незмінною силою, і гноми були змушені шукати притулку в місті карликів Айронфордж, де Верховний майстер зараз вербує відважних, щоб допомогти своєму народу повернути улюблене місто. $b",  -- db:7203
[86996349] = "Разорфен Краул знаходиться на самому південному краю Пусток, на західній стороні дороги.",  -- db:7204
[766965820] = "Під час Війни Древніх напівбог Агамагган виступив проти Палаючого Легіону. Колосальний кабан зазнав поразки, і з часом у місцях, де пролилася його кров, проросли величезні, вкриті колючками лози. Квілбоари заселили ці регіони й вважають їх священними. Серцем цих величезних колоній колючих лоз є Разорфен. Разорфен Краул був завойований старою жінкою Шарлгою Разорфланк, яка, як припускають деякі, вела переговори з агентами Плеті з якоюсь підступною метою.$b",  -- db:7205
[544972319] = "Монастир Скарлет розташований на пагорбах на північний схід від Полян Тірісфал.",  -- db:7206
[348264216] = "Колись монастир був центром освіти та просвітництва. З підйомом неживих — «Покарання» — під час Третьої війни, цей мирний монастир перетворився на твердиню фанатичного «Скарлатного хрестового походу». Хрестоносці не терплять жодних нелюдських рас, незалежно від їхнього альянсу чи приналежності. Вони вірять, що будь-які чужинці є потенційними носіями чуми нежиті — і їх необхідно знищити. $b",  -- db:7207
[217677650] = "Разорфенські рівнини розташовані на самому південному краю Пусток, на східній стороні дороги.",  -- db:7208
[307186596] = "Разорфен-Даунс, створений із тих самих лоз, що й Разорфен-Краул, є традиційною столицею раси квілбоарів. У цьому розлогих, усіяному колючками лабіринті мешкає справжня армія відданих квілбоарів, а також їхні верховні жерці — плем’я «Голова Смерті». Однак нещодавно над цим примітивним лігвом нависла загрозлива тінь. Агенти неживих «Покарання» — на чолі з лічем Амненнаром Холодоносцем — взяли під свій контроль расу квілбоарів і перетворили лабіринт з колючок на оплот могутності неживих.",  -- db:7209
[521246738] = "Улдаман розташований на самому північному краю Пусток.",  -- db:7210
[662034418] = "Лард тут підтримує спокій. Лард також продає рибу. Хочете риби?",  -- db:7211
[27028704] = "Улдаман — це стародавнє сховище титанів, яке лежало поховане під землею з часів створення світу. Нещодавно в результаті розкопок міста, проведених гномами, на волю вирвалися перші невдалі творіння титанів: троги. Легенди розповідають, що коли титани визнали експеримент із трогами невдалим, вони спробували ще раз, що призвело до створення раси гномів. Ці таємниці записані на легендарних Дисках Норганнона — величезних артефактах, що лежать на дні стародавнього міста, захищених гігантськими конструкціями з живого каменю.",  -- db:7212
[546573379] = "Руїни Зул'Фаррака розташовані в північно-західній частині пустелі Танаріс.",  -- db:7213
[755933452] = "Це випалене сонцем місто є домівкою для тролів Піщаної Фурії, відомих своєю особливою жорстокістю та темним містицизмом. Легенди тролів розповідають про могутній меч під назвою «Суль’тразе — Бич», зброю, здатну вселити страх і слабкість навіть у найгрізніших ворогів. Давним-давно ця зброя була розколота навпіл. Однак ходять чутки, що обидві половини можна знайти десь у межах стін Зул’Фаррака.$b",  -- db:7214
[514711913] = "Мараудон розташований у центрі західного узбережжя Десоласу, у Долині Списів.",  -- db:7215
[643353803] = "Мараудон — одне з найсвятіших місць у Десоласі. Ця велична печера-храм є місцем поховання Заетара, одного з двох безсмертних синів напівбога Сенаріуса. Легенда свідчить, що Заетар та принцеса елементалів землі Терадрас породили прокляту расу кентаврів. Кажуть, що після свого появи варварські кентаври повстали проти свого батька й убили його. Дехто вважає, що Терадрас, у своєму горі, ув’язнила дух Заетара в лабіринті печер — і використовувала його енергію для якихось злісних цілей.",  -- db:7216
[506175263] = "Затонулий храм розташований у центрі великого озера на сході «Болота Скорботи».",  -- db:7217
[97853737] = "Гора Блекрок розташована між Ущелиною Палаючого Вогню на півночі та Палаючими Степами на півдні.",  -- db:7218
[314953629] = "Колись це було столицею гномів Темного Заліза, а тепер цей вулканічний лабіринт слугує резиденцією Володаря Вогню Рагнароса. Рагнарос розкрив таємницю створення життя з каменю і планує створити армію непереможних големів, які допоможуть йому завоювати всю Гору Чорної Скелі. Одержимий ідеєю перемоги над Нефаріаном та його драконячими поплічниками, Рагнарос готовий піти на будь-які крайності, аби здобути остаточну перемогу.  $b",  -- db:7219
[641187626] = "Могутня фортеця, висічена у вогняних надрах гори Чорної Скелі, століттями перебувала під владою зловісних карликів Темного Заліза, аж поки Нефаріан — хитрий син дракона Смертокрила — не захопив контроль над Верхньою Шпилею та не розпочав війну проти володінь карликів у вулканічних глибинах гори. Зрозумівши, що на чолі гномів стоїть могутній вогняний елементаль Рагнарос, Нефаріан поклявся розгромити своїх ворогів і захопити всю Гору Чорної Скелі для себе.",  -- db:7220
[276548420] = "Руїни Діре-Маула розташовані в центрі Фереласа.",  -- db:7221
[240921722] = "Школа некромантії, відома як «Сколоманс», розташована на зруйнованому острові Каер-Дарроу у Західних Землях Чуми.",  -- db:7223
[491009551] = "Зруйноване місто Стратхолм розташоване у Східних Землях Чуми, на північ від Лісу Чуми.",  -- db:7225
[545045797] = "Місто Стратхолм, що колись було перлиною північного Лордаерону, стало місцем, де принц Артас зрадив свого наставника, Утера Світлоносія, та винищив сотні своїх підданих, яких вважали зараженими чумою нежиті. Незабаром після цього Артас присягнув на вірність Королю Лічу. Зруйноване місто тепер населяють неживі представники «Покарання» на чолі з могутнім лічем Кел'Тузадом, а також загін «Скарлатових хрестоносців» під командуванням Великого хрестоносця Датрохана. Обидві сторони ведуть безперервні запеклі бої.",  -- db:7226
[718853289] = "Шахти Мертвих розташовані під Місячним Бруком на півдні Вестфолла.",  -- db:7227
[977454848] = "Тюрми Штормовію розташовані поблизу кварталу магів у Штормовії.",  -- db:7229
[511262358] = "«Стокейдс» — це тюремний комплекс підвищеного рівня безпеки, прихований під районом каналів міста Штормовій. Під керівництвом начальника в’язниці Телвотера у «Стокейдс» утримуються дрібні злочинці, політичні повстанці, вбивці та десятки найнебезпечніших злочинців у країні. Нещодавно повстання, очолене в’язнями, призвело до хаосу в «Стокейдс» — охоронців вигнали, а засуджені вільно розгулюють. $b",  -- db:7230
[677605145] = "У мене є все кухонне приладдя, яке тобі коли-небудь знадобиться, друже!",  -- db:7237
[252639943] = "Ласкаво просимо до селища Ревантуск, незнайомцю. Я — Праймал Торнтуск, ватажок тролів Ревантуска.",  -- db:7238
[225418731] = "Якщо щось зламалося, Slagtree це полагодить!",  -- db:7239
[435867721] = "Мій бізнес — це містичні товари та продукти, незнайомцю.",  -- db:7240
[931253434] = "Риболовля — це просто неймовірне задоволення, друже. Розумієш? Своїм блаженством я завдячую своєму наставнику, найкращому рибалці у всьому світі — Нату Пейглу. Ти про нього чув, друже?$B$BЯкщо ти шукаєш просвітлення, то саме Нат Пейгл покаже тобі шлях.",  -- db:7241
[967501387] = "Зул’джин одного дня повернеться, $r. Запам’ятайте мої слова. А до того часу ми всі триматимемо свої позиції й робитимемо все можливе, щоб зберегти популяцію лісових тролів у повному складі.$B$BЗ огляду на це, як головний мисливець села Ревантуск, я несу відповідальність за те, щоб світ навколо нас був безпечним для проживання.$B$BЗвірів у цій місцевості треба тримати під контролем.$B$BВи шукаєте роботу?$B",  -- db:7242
[613747744] = "Я — Кілрам, майстер сокири.",  -- db:7243
[456394793] = "Не підходь надто близько, $N. Я можу не втриматися і розтрощити тобі голову об рукоятку мого молотка.",  -- db:7245
[492156856] = "Відійди, інакше я розрубаю тебе навпіл.",  -- db:7247
[7204825] = "Якщо ви хочете стати майстром з виготовлення мечів, просто скажіть.",  -- db:7248
[839466746] = "Я щойно завершив роботу над новим міжвимірним імплодером, який зробить мене багатим настільки, що це перевершить навіть мої найсміливіші гоблінські мрії!   Залишилося лише знайти досвідченого гоблінського інженера, який побудує міжвимірний ріпер, що підключається до нього, і випробувати його! $B",  -- db:7249
[785016022] = "Суть теорії полягає в тому, що ми повністю знищуємо тебе потужним вибухом, де б ти не був, відправляємо ці частинки крізь міжвимірний розрив, а потім знову стискаємо тебе тут, у «Машині». Миттєве переміщення! Можливо, це не завжди спрацює, але що ти за гоблін-інженер! Якби виживання було для тебе головним пріоритетом, ти ніколи не став би справжнім гоблін-інженером! Ось рецепт, який тобі знадобиться, щоб створити «Розрив між вимірами» і випробувати його!",  -- db:7250
[611248376] = "Завдяки деяким технологіям, які вдалося здобути сміливим гномам, що відважилися проникнути до Гномерегана, мені вдалося створити свій найвидатніший винахід:  Транспортер матерії!    Тепер мені потрібен лише досвідчений гномський інженер, щоб побудувати потужний маяк, налаштований на роботу з транспортером.",  -- db:7251
[337589416] = "Після того як ви зібрали пристрій, вам залишається лише увімкнути його, щоб миттєво опинитися в чарівному Гаджетзані!    Майже всі, хто скористався цим пристроєм, прибули на цю платформу в тому самому вигляді, в якому були на момент старту!    Були повідомлення про проблеми, коли перенесених осіб замінювали їхні злі двійники з паралельного всесвіту, але я впевнений, що ми незабаром вирішимо цю проблему...",  -- db:7252
[466321712] = "Якщо ви знайдете якийсь спосіб удосконалити цей пристрій, дайте мені знати!",  -- db:7253
[373644147] = "Я роблю останню послугу. Сподіваюся, цього вистачить...",  -- db:7256
[431198476] = "Знайди ключ і розблокуй ці ланцюги! Він у Хітах’ї, Хранителя… у глибині печери…",  -- db:7257
[686578509] = "Вакансії / Загублені та знайдені речі / Розшукуються:",  -- db:7274
[540054893] = "Зуг-зуг, друже!  Я — Келм Харгунт, головний постачальник «Варсонґ Аутрайдерів».  У міру того, як ти будеш покращувати свої стосунки з «Варсонговими розвідниками», я надаватиму тобі чудовий вибір товарів, які ти зможеш використовувати в ущелині «Варсонгової пісні».  Якщо тобі знадобиться ремонт предметів, я також надаю такі послуги.",  -- db:7294
[105903500] = "Нехай благословення ночі супроводжують тебе, друже!  Я — Ілліана Мунблейз, і я є головним постачальником для «Срібнокрилих вартових» тут, у Попеліній долині.  У міру того, як ти будеш покращувати свої стосунки зі «Срібнокрилими вартовими», я надаватиму тобі чудовий вибір товарів, які ти зможеш використовувати в Ущелині Воєнної Пісні.  Якщо тобі знадобиться ремонт предметів, я також надаю такі послуги.",  -- db:7295
[548975006] = "Ласкаво просимо!  Ласкаво просимо до «Дивного зоопарку Темного Місяця» Єбба Неблегіра — скарбниці живих легенд та міфічних дивацтв!  Насолоджуйся візитом, друже!$B$BАле будь обережним із тим, до чого торкаєшся!  Серед експонатів є як жахливі, так і божественні артефакти та звірі!  Вони можуть обпалити нерозсудливу руку надто допитливого глядача...",  -- db:7314
[41898619] = "Куди я можу сьогодні надіслати вам $c?",  -- db:7315
[494175711] = "Хоча «Перехрестя» і здається центром життя в «Пустошах», я віддаю перевагу тиші та спокою табору Таурахо. Куди вас відправити?",  -- db:7315
[89501485] = "Багато шляхів у Матері-Землі. Куди б ти не вирішив вирушити, нехай вона береже тебе.",  -- db:7315
[684234872] = "Стався до вітроверта з повагою, адже він доправить тебе до місця призначення.  Нехай твої предки оберігають тебе, $N.",  -- db:7315
[813987610] = "Вітаю, друже, і ласкаво просимо на найграндіозніше шоу в Азероті!$B$BБудь ласка, підходьте ближче й насолоджуйтеся всім, що ми можемо запропонувати.  Подивіться на дивовижні речі, які Ярмарок Темної Місяця відкрив у цьому величезному й таємничому світі!  Ми не шкодували коштів, щоб подарувати вам захоплюючі враження, які сподобаються дітям будь-якого віку!",  -- db:7334
[209047798] = "Не завжди йдеться про гроші, $N! Хоча ми отримуємо щедрі пожертви — деякі з них надзвичайно значні — творчою рушійною силою нашої мандрівної трупи є прагнення принести світло в цей роздираємий війною світ. Не турбуйтеся про нас, а дозвольте нам подбати про те, як найкраще розважити вас.",  -- db:7336
[922251109] = "Обміняйте квитки тут!  Обміняйте свої квитки на призи!  Заходьте!",  -- db:7337
[957164342] = "Іди собі, селюк.",  -- db:7338
[576342511] = "Це не розвага, Клем.  Забирайся звідси.",  -- db:7338
[610591887] = "Якщо ти намагаєшся бути привітним, не витрачай даремно сили. А ще краще — просто перестань дихати взагалі.",  -- db:7338
[871373461] = "Якщо це ще не стало зрозуміло, я тут не для того, щоб займатися роботою з клієнтами.",  -- db:7338
[39758380] = "Хто задирається до Сайласа — той задирається до мене. Гарного дня.",  -- db:7338
[675504892] = "Друга голова мені потрібна так само, як і втратити першу.",  -- db:7338
[159128500] = "Я деякий час мешкав у Діре-Маулі.  Це було весело.  Справді.",  -- db:7338
[286987362] = "На відміну від більшості огрів, я добре знаю, для чого призначений туалет на вулиці — щоб засунути тобі голову в унітаз. А тепер забирайся звідси.",  -- db:7338
[992646581] = "Я давно знав, що ти мене знайдеш, $N.$B$BКожна свідома істота в цьому світі керується тими рішеннями, які вона приймає.  Вибори породжують нові вибори, а ті, у свою чергу, формують особистість людини.  Саме звідси бере початок твоя доля — з того, хто ти є, і з виборів, які ти робиш.$B$BЧи готовий ти дізнатися, у чому полягає твоя доля?",  -- db:7339
[86470109] = "Ну що ж...$B$BВаш сеньйор доручив вам охороняти його кукурудзяні поля від браконьєрів і злодіїв.  Однієї ночі під час патрулювання ви натрапили на виснаженого чоловіка в пошарпаному одязі, який крав кукурудзу з поля.  Ви швидко зупиняєте його, і він одразу ж благає про пощаду.  Він стверджує, що краде кукурудзу, щоб прогодувати свою родину, оскільки володар цих земель — ваш сеньйор — вимагає занадто високих податків.  Ваш сеньйор справді відомий своїми суворими податками по всій країні.$B$BЗробіть свій вибір.$B",  -- db:7340
[219765096] = "На вас чекає наступний вибір.$B$BВи — присяжний кат свого сеньйора.  До вас привели чоловіка, якого мають стратити як зрадника сеньйора та вашого народу.  Ви знаєте цю людину як близького, доброчесного друга, який одного дня загадково зник.  Ви також знаєте, що злочини, за які його засудили, нібито призвели до загибелі багатьох невинних цивільних осіб.  Побачивши вас, він благає про пощаду, стверджуючи, що його підставили вищі чини.$B$BЗробіть свій вибір.$B$B",  -- db:7341
[493917125] = "Хіба ти не бачиш, що мені тут треба працювати?",  -- db:7354
[433119190] = "Ярмарок наближається!",  -- db:7354
[678627422] = "Саме так, друже! Ярмарок Темної Місяця відбудеться саме тут. Тільки-но я розвантажу ці величезні вози, розставлю всі намети, облаштую зоопарк і наллю напої. Обов’язково загляньте ще!",  -- db:7354
[423950573] = "Незабаром відкриється Ярмарок Темної Місяця. Загляньте пізніше, щоб перевірити, чи ми вже все завершили.",  -- db:7354
[303098196] = "Ласкаво просимо на ярмарок, юний друже!   Ми зібрали для тебе дивовижні речі з усього світу, щоб ти міг їх оглянути.   А ще, будь ласка, дай мені знати, якщо тобі вдасться зібрати комплект карт «Менших темних місяців», адже майстер... тобто, мені було б дуже цікаво їх побачити.",  -- db:7355
[3746046] = "Ми розкидали карти «Темного Місяця» по всьому світу, щоб перевірити, чи знайдуться гідні гравці, здатні зібрати повну серію будь-якої з восьми мастей.    Якщо вам вдасться зібрати всі вісім карт однієї з мастей, ми нагородимо вас однією з «Великих карт Темного Місяця», яка виконує функцію потужного амулета, а також надасть доступ до Ярмарку Темного Місяця.",  -- db:7356
[852887959] = "Якщо вам вдасться зібрати колоду карт «Звірів», ви отримаєте в нагороду карту «Блакитний дракон» серії «Велика Темна Місячна колода».   Вона дуже корисна для відновлення магічної енергії.",  -- db:7357
[242218728] = "Якщо вам вдасться зібрати повну колоду карт «Порталів», ви отримаєте в нагороду «Велику темномісячну карту» з «Викрученого Нетера». Ця карта час від часу повертатиме ваш дух у тіло після смерті та відновлюватиме вас.",  -- db:7358
[519624300] = "Якщо вам вдасться зібрати повну колоду карт «Елементалів», ви отримаєте в нагороду «Велику карту Темної Місяця» з «Виру». Ця карта час від часу завдаватиме значної шкоди ворогу, з яким ви ведете бій.",  -- db:7359
[753843358] = "Якщо вам вдасться зібрати повну колоду карт «Воєначальників», ви отримаєте в нагороду «Велику темномісячну карту героїзму».   Ця карта час від часу відновлюватиме ваше здоров’я під час рукопашного бою.",  -- db:7360
[701306307] = "На вас чекає наступний вибір.$B$BВи перебуваєте з дипломатичною місією від імені свого сюзерена в жорстокій країні, яка наразі перебуває у стані війни з вашою.  Ця війна обійшлася дорого обом сторонам.  Ваше завдання — забезпечити мир, який буде гідним для обох народів.$B$BPід час дипломатичної вечері ви випадково чуєте, як правитель ворожої країни жорстоко ображає вашого доброзичливого сеньйора.  Ви майже впевнені, що правитель мав намір сказати це так, щоб ви не почули, але, попри це, він заплямував честь вашого сеньйора.$B$BЗробіть свій вибір.$B$B$B",  -- db:7361
[214265485] = "На вас чекає наступний вибір.$B$BВаш брат прагне вступити до лав престижного військового ордену, членом якого ви вже є. Хоча ви впевнені в його відданості та лояльності, ви сумніваєтеся в його таланті та здатності виконувати важкі завдання ордену.  Хоча ви не впевнені, чи зможе він впоратися з викликами ордену — що може поставити вас та інших у небезпеку — ви впевнені, що лише ваше слово дозволить йому вступити або завадить цьому.$B$BЗробіть свій вибір.$B$B",  -- db:7362
[610323781] = "На вас чекає наступний вибір.$B$BСаме ви перемогли жахливого звіра, який спустошував околиці, і взяли його вухо як трофей.  Пізніше ви дізнаєтеся, що ваш сеньйор оголосив нагороду за вбивство звіра, і що добрий, але злиденний лицар, якого ви знаєте і який намагається утримувати сім’ю на мізерні кошти, заявляє, що саме він вбив звіра.  Вам самим гроші не дуже потрібні, але ви знаєте, що злиденний лицар бреше заради власної вигоди.$B$BЗробіть свій вибір.$B$B",  -- db:7363
[338172826] = "Ваша доля вирішена, $c.  Протягом наступних кількох годин ви відчуєте, що ваш дух перебуває в гармонії з вашою справжньою сутністю.  Будьте обережні, адже ваша доля — і ваше майбутнє — ніколи не є такими очевидними, як вам може здаватися.$B$BЯкщо ви хочете отримати невеликий натяк на те, над чим варто замислитися у майбутньому, обов’язково дайте мені знати.  Я з радістю дам вам письмове пророцтво, за умови, що у вас є місце в інвентарі.  Воно базується на проникливості, яку ви проявили, відповідаючи на мої запитання.",  -- db:7364
[138791595] = "Ось ваше передбачення, $N.  Нехай воно принесе вам користь.$B",  -- db:7365
[770000246] = "Ярмарок Темної Місяця наближається!  Не пропустіть!",  -- db:7366
[30313486] = "Не пропустіть усі дивовижні видовища та чудеса Ярмарку Темної Місяця, коли він завітає до вашого міста!",  -- db:7366
[681914372] = "Наближається Ярмарок Темної Місяця!  Тут знайдеться розвага для дітей будь-якого віку!  Запрошуємо всіх і кожного!",  -- db:7366
[865185655] = "Підходьте ближче та дізнайтеся про найдивовижніше видовище у всьому Азероті — Ярмарок Темної Місяця!  Ура!",  -- db:7366
[439361399] = "Ось і вона! Ярмарок Темної Місяця вже відкрився! Не пропустіть найзахопливіше шоу у всьому Азероті!",  -- db:7374
[627004446] = "Ярмарок Темної Місяця прибув до міста!  Не пропустіть найзахопливіше шоу, яке ви коли-небудь бачили!",  -- db:7374
[830923056] = "Ярмарок Темної Місяця триватиме лише короткий час, після чого завіса опуститься.  Обов’язково завітайте туди сьогодні!",  -- db:7374
[788521324] = "Хлопчики та дівчатка — діти будь-якого віку — ярмарок «Темний Місяць» вже розпочався!  Ура!",  -- db:7374
[627004476] = "Ярмарок Темної Місяця прибув до міста!  Не пропустіть найзахопливіше шоу, яке ви коли-небудь бачили?",  -- db:7375
[26679930] = "Коли відкриється Ярмарок Темної Місяця, він розміститься в Мулгорі. Ми розіб’ємо свої намети трохи на південний захід від Громового Уступу!",  -- db:7376
[58566867] = "Ярмарок Темної Місяця зараз проходить на золотих рівнинах Мулгора, трохи на південний захід від Громового Уступу.  Не пропустіть!",  -- db:7377
[245524348] = "Коли ярмарок «Темний Місяць» відкриється, він відбуватиметься в Лісі Елвін. Ми розіб’ємо свої намети трохи південніше від Голдшира!",  -- db:7378
[624434022] = "Ярмарок Темної Місяця зараз проходить у Лісі Елвін, трохи південніше від Голдшира.  Не пропустіть!",  -- db:7379
[444746148] = "Тут справді багато людей, які кидають сміття.",  -- db:7382
[471715811] = "Тобі весело?",  -- db:7382
[367328729] = "Не забудьте придбати прохолодні напої та сувеніри!",  -- db:7382
[6851314] = "Ярмарок Темної Місяця — це найграндіозніша подія у всьому Азероті!",  -- db:7382
[632128904] = "Ласкаво просимо на Ярмарок Темної Місяця, $c!$B$BМене звати Керрі Хікс, і я б потиснула вам руку, але боюся, що зламаю її, адже я найсильніша жінка на світі!",  -- db:7383
[412721014] = "Заходьте!  Купуйте «Red Hot Wings» прямо тут!",  -- db:7387
[513909806] = "Сосиски «Даркмун» — щойно з гриля.  Приходьте та куштуйте, поки вони гарячі!",  -- db:7387
[253068056] = "У вас є гроші, а у нас — їжа.  Чого ж ви чекаєте?!",  -- db:7387
[711094512] = "Тільки протягом обмеженого часу «Хрустка жаба» доступна виключно тут, на Ярмарку Темного Місяця.",  -- db:7387
[206287928] = "Кожен товар, який я виставляю на продаж, я придбав власноруч.  Я особисто гарантую його справжність.",  -- db:7389
[172457752] = "Картки «Ярмарку Темного Місяця»?  З цього приводу зверніться до професора, якого можна знайти тут.  Завітайте до мене, якщо ви торгуєте рідкісними старожитностями та артефактами.",  -- db:7389
[333609416] = "Завітайте та подивіться на мої товари, поки ще є така можливість. Ми будемо тут весь тиждень, а потім вирушимо до якоїсь далекої країни.",  -- db:7389
[762964731] = "Ви уявляєте, через що мені доводиться проходити, щоб привезти ці неповторні коштовності на продаж? Приходьте й подивіться на них на власні очі!",  -- db:7389
[913086825] = "Гей, хтось допоможіть мені зловити цю штуку!",  -- db:7390
[715468169] = "Воно втікає!",  -- db:7390
[305239484] = "Повертайся сюди!",  -- db:7390
[705212228] = "Продаються жаби та шкіряні м’ячі!",  -- db:7390
[479370325] = "На жаль... Мені прикро це казати, але наразі я не можу передбачити вам майбутнє, оскільки ви нещодавно вже отримували від мене прогноз.$B$BПоверніться до мене через кілька годин після того, як ви вперше отримали свій прогноз. Сили Долі встигнуть належним чином переналаштуватися, і я зможу зазирнути у ваше майбутнє.",  -- db:7393
[666099319] = "$N, радий знову тебе бачити!  Тобі подобається ярмарок?$B$BХочеш позмагатися в армрестлінгу?  Ні, звичайно ж ні... ти ж хочеш зберегти свою руку!",  -- db:7394
[292661675] = "Вітаю.  Я — Хронос — Той, Хто Ніколи Не Забуває.  Моя пам’ять бездоганна і точна до найдрібніших деталей.$B$BПовірте мені.",  -- db:7395
[306998312] = "Привіт!  І ласкаво просимо!  На жаль, мій кіоск поки що не працює... йому потрібні чималі ремонтні роботи...$B$BАле я все ще зобов’язаний кров’ю присягою викликати посмішку на вашому обличчі.  Тож, будь ласка, посміхніться, інакше мені доведеться відрізати собі руку й утримуватися від споживання живого м’яса, доки вона не відросте...",  -- db:7397
[624019821] = "Я не можу знайти свою домашню жабу, Джубджуб. Вона обожнює ель «Темне залізо» — це єдине, що вона п’є, але його так важко дістати! Тепер у мене він закінчився… і Джубджуб, мабуть, втекла, щоб знайти ще!$B$BЯ б хотіла, щоб вона повернулася…",  -- db:7400
[988864565] = "Ми повинні будь-що-будь забезпечити виживання цього табору, $c!  Нашим ворогам не можна давати жодного пощаду, адже вони напевно не дали б її нам, якби ми її потребували.",  -- db:7402
[198413685] = "Це небезпечні часи, $r.  Стародавнє зло пробуджується, і йому байдуже, чи ти з Орди, чи з Альянсу.",  -- db:7403
[967600141] = "У продажу — смачні напої!  Втамуйте спрагу найкращими напоями з Ярмарку Темного Місяця!",  -- db:7404
[97193849] = "Не соромтеся, пригостіть усіх!",  -- db:7404
[487251022] = "Чайові завжди приймаються з вдячністю, друже.",  -- db:7404
[72770444] = "Щойно надійшла... чергова партія «Darkmoon Special Reserve». Приходьте за своєю порцією, поки вони не розійшлися!",  -- db:7404
[874891295] = "Ква-ква.",  -- db:7406
[33548228] = "Поцілуй мене.",  -- db:7406
[440813240] = "Вітаю, юний $c. Саме тут твій Вождь кинув виклик Оргриму Думхаммеру! Хоча це сталося так давно, цей образ досі залишається в моїй пам’яті.",  -- db:7415
[103212078] = "966 доларів на тиждень, молодий $c.",  -- db:7416
[500255771] = "Прийшов вчитися, так? Ну, можливо, у мене для тебе знайдеться якась робота, новачку.",  -- db:7434
[579385530] = "<Сержант Стормпайк віддає честь.>$B$BІм’я, звання та серійний номер, солдате! Це єдина інформація, яку ти коли-небудь надаси цим брудним псам із «Морозних Вовків»!",  -- db:7435
[553391455] = "964w доларів, молодий $c.",  -- db:7436
[184072093] = "$962w Командири «Штормпайк» та $950w Лейтенанти «Штормпайк».$b",  -- db:7437
[436275637] = "Одне я вам обіцяю: Долина буде нашою.",  -- db:7438
[335081722] = "962 долара на тиждень, солдате.",  -- db:7439
[623080423] = "950 ват, солдате.",  -- db:7440
[498743063] = "Командири «Морозних вовків» вартістю 966 $ та лейтенанти «Морозних вовків» вартістю 964 $, солдате.",  -- db:7441
[195258489] = "Якщо ти прийшов, щоб врятувати світ, то ти потрапив у потрібне місце. Безликий — Бог Крові, Хаккар — повернувся у наш світ!",  -- db:7454
[826779248] = "Твоя непохитна рішучість вражає, $N. Ти й надалі доводиш, що є справжньою цінністю для нашого народу. Одного дня світ усвідомить всю велич твоїх подвигів.",  -- db:7455
[249365383] = "Наш героїчний новачок повертається! Радий знову тебе бачити, $N. Ти завжди бажаний гість у нашому селі.",  -- db:7456
[946325414] = "Дай мені їх, $N! Тільки скажи слово — і я сідлаю коня та атакую їхній міст!",  -- db:7476
[598136168] = "Я буду патрулювати перевал, що веде до фортеці «Фроствулф». Просто дайте мені знак, і я злечу, командире.",  -- db:7479
[280102191] = "Вітаю, $c.  Чи хочеш ти допомогти «Срібнокрилим вартовим» у їхній битві в Ущелині Воєнної Пісні?",  -- db:7481
[150701605] = "Слава Елуні!  Ви шукаєте нашого майстра бою в Ущелині Воєнної Пісні?  Її звуть Аеталас, і вона готова зустріти вас біля інструкторів-воїнів.",  -- db:7482
[626588872] = "$N, ти берешся за нелегке завдання. Щоб дістатися до Ущелини Воєнних Пісень, тобі слід поговорити з Еталас, бойовим майстром «Срібнокрилих Вартових». Вона вкаже тобі шлях. Нехай благословення Богині супроводжують тебе!",  -- db:7482
[789046046] = "Тож, $g хлопче : дівчино;, ти вважаєш, що в тебе вистачить сил захистити Альянс від Орди в Долині Альтерак?  Гаразд, тоді тобі слід поговорити з нашим Глордрумом Стілбірдом тут, у Айронфорджі.  Ти знайдеш його за розробкою стратегії за військовим столом у Залі зброї.",  -- db:7483
[223560613] = "Ах, Долина Альтерака, скажу тобі, у мене залишилися чудові спогади.  <зітхання>  Ну, я не зможу приєднатися до вас, але все одно не підведіть мене!  Щоб туди дістатися, вам потрібно поговорити з Глордрумом Стілбірдом у Залі зброї тут, в Айронфорджі.",  -- db:7483
[138990002] = "Якщо ви збираєтеся в Долину Альтерака, то підійдіть і поговоріть з Картрою Бладснарл. Ви знайдете її в Залі Хоробрих у Долині Честі.",  -- db:7484
[523112409] = "Як же я мрію приєднатися до вас у славній битві, але замість цього я змушений залишатися тут на службі.  Зайдіть до Залу Хоробрих у Долині Честі в Оргримарі та поговоріть із Картрою Бладснарл.  Вона допоможе вам дістатися до Долини Альтерак.  Не підведіть нас, $N!",  -- db:7484
[534512145] = "Є кілька полів бою, з яких можна вибрати. До якого бойового майстра мені вас відправити?",  -- db:7495
[407845410] = "Я знаю саме того, про кого ти говориш, $c.  Тобі треба знайти Брогуна Стоуншилда на Терасі Воїнів.",  -- db:7496
[285431500] = "Гвардія Штормпайка потребує вашої допомоги у боротьбі проти клану Морозних Вовків, $N.  Зверніться до Брогуна Стоуншилда на Терасі Воїнів, і він допоможе вам дістатися до Долини Альтерак.",  -- db:7496
[267086687] = "Так, а яке поле бою ви шукаєте?",  -- db:7497
[225069798] = "«Ущелина Воєнної Пісні», кажеш?  Що ж, тоді тобі варто поговорити з чарівною Ліландріс у Залі Зброї.",  -- db:7498
[946619013] = "На мій погляд, будь-яка нагода поборотися з Ордою, особливо з орками, — це чудова нагода. У «Ущелині Воєнної Пісні» на вас чекає безліч битв, це точно. Завітайте до «Залу зброї» і поговоріть із Ліландріс. Вона дасть вам подальші вказівки.",  -- db:7498
[289070498] = "Яке поле бою вас цікавить?",  -- db:7499
[857227706] = "Тоді вам слід поговорити з Телманом Слейтфістом. Ви знайдете його при дворі короля у фортеці Штормовій.",  -- db:7500
[862316091] = "І я б дуже хотів приєднатися до тебе, $N.  Зайди до фортеці Штормовій.  У королівській аудієнційній залі ти знайдеш Телмана Слейтфіста.  Він допоможе тобі дістатися до Долини Альтерак.",  -- db:7500
[359419774] = "Дійсно, фортеця «Срібне Крило» потребує вашої допомоги. Поговоріть з Ельфарраном у тронному залі фортеці Штормовій.",  -- db:7501
[706248211] = "«Срібнокрилі вартові» потребують будь-якої допомоги у боротьбі проти «Варсонгських розвідників». $N, вирушай до фортеці Штормовій і поговори з Ельфарраном, якщо хочеш їм допомогти.",  -- db:7501
[532976447] = "Ми маємо вигнати ельфів та їхній боягузливий Альянс із Ущелини Воєнної Пісні. Якщо ти готовий допомогти Орді, вирушай до Зали Хоробрих у Долині Честі та поговори з Бракгулом Смертоносець.",  -- db:7502
[275304155] = "«Срібнокрилі вартові» — це навряд чи те, що я б назвав гідними супротивниками. Але якщо ти налаштований на їхнє винищення $c, то знайди Бракгула Смертоносного у Залі Хоробрих.",  -- db:7502
[624495647] = "На якому полі бою ти прагнеш здобути славу?",  -- db:7503
[313269359] = "А на яке поле бою ви бажаєте вирушити?",  -- db:7504
[121719701] = "Тоді тобі слід звернутися до Таїма Рагетотема. Знайди його на Мисливському пагорбі.",  -- db:7505
[691575685] = "Я знаю одну людину тут, у Громовому Утворі, яка може допомогти тобі у подорожі до Долини Альтерак. На схилі Мисливців шукай Тайма Рагетотема. Сподіваюся, ти знайдеш те, що шукаєш, $N.",  -- db:7505
[619990694] = "Кергул Кровава Сокира на Хребті Мисливців готовий допомогти вам дістатися до Ущелини Воєнної Пісні.",  -- db:7506
[155229008] = "Такі даремні сутички, але якщо ельфи з фортеці «Срібне Крило» не хочуть вести з нами мирні переговори, то який інший вибір у нас залишається? Зверніться по допомогу до Кергула Кровосоки на Мисливському пагорбі, щоб дістатися до Ущелини Воєнної Пісні.",  -- db:7506
[192431920] = "Яке поле бою ти обираєш?",  -- db:7507
[147712230] = "Там холодно!  Зайди в «Королівський квартал» і поговори з Гріззлом Халфмейном.",  -- db:7508
[924962386] = "Його звуть Грізл Халфмейн. Він перебуває в Королівському кварталі разом із Королевою Банші та Лордом Жаху.",  -- db:7508
[403139472] = "Уявіть його в Королівському кварталі. Курден Бладклоу — маленький орк.",  -- db:7509
[557698850] = "Ельфи в Ущелині «Військової пісні» видають хрусткий звук.  Ти їх добре розчавлюєш.  Поговори з Курденом Кровавим Кігтем у Королівському кварталі.",  -- db:7509
[273408605] = "Я — Джин'рок Руйнівник, посланець Мугамби: Кулак Растахана!$B$BЯ маю справу з воїнами та язичниками.",  -- db:7514
[625134197] = "Я — Аль'табім Всевидячий — посланець короля Растахана.$B$BЯ маю справу зі священиками, магами та чаклунами.",  -- db:7515
[770483193] = "Ліга Аратора присягнулася відвоювати Араті для людей Стромгарда та Альянсу. Це буде важка битва, але вона того варта.",  -- db:7516
[22038111] = "Щоб виграти цю війну, ми не можемо сидіти склавши руки й чекати, поки події нас зметуть. Ми мусимо завдати удару — сильного й швидкого, інакше Араті ніколи більше не стане нашим.",  -- db:7517
[57157949] = "Ми маємо вигнати ельфів та їхній боягузливий Альянс із Ущелини Воєнної Пісні. Якщо ти готовий допомогти Орді, вирушай до Залу Хоробрих у Долині Честі та поговори з Бракгулом Смертоносець.",  -- db:7520
[966306149] = "«Срібнокрилі вартові» — це навряд чи те, що я б назвав гідними супротивниками. Але якщо ти налаштований на їхнє винищення $c, то знайди Бракгула Смертоносного у Залі Хоробрих.",  -- db:7520
[972671842] = "Такі даремні сутички… Але якщо ельфи з фортеці «Срібне Крило» не хочуть вести з нами мирні переговори, то який інший вибір у нас залишається? Зверніться по допомогу до Кергула Кровосоки на Мисливському пагорбі, щоб дістатися до Ущелини Воєнної Пісні.",  -- db:7523
[405554694] = "Там холодно! Зайди в «Королівський квартал» і поговори з Гріззлом Халфмейном.",  -- db:7525
[768756625] = "Його звуть Грізл Халфмейн. Він перебуває в Королівському кварталі разом із Королевою Банші та Лордом Жаху.",  -- db:7525
[321724147] = "Уявіть його в Королівському кварталі. Курден Бладклоу — маленький орк.",  -- db:7526
[514766891] = "Ельфи в Ущелині Воєнної Пісні видають хрусткий звук. Ти їх добре розчавлюєш. Поговори з Курденом Кровавим Кігтем у Королівському кварталі.",  -- db:7526
[367890374] = "«Ущелина Воєнної Пісні», кажеш? Що ж, тоді тобі слід поговорити з чарівною Ліландріс у Залі зброї.",  -- db:7528
[47521746] = "На мій погляд, будь-яка нагода битися проти Орди, а особливо проти орків, — це чудова нагода. У Ущелині Воєнної Пісні на вас чекає чимало битв, це точно. Завітайте до Залу Зброї та поговоріть із Ліландріс. Вона дасть вам завдання.",  -- db:7528
[514042579] = "Привіт, $N. Чим можу допомогти?",  -- db:7530
[330546366] = "А чого ти чекав, друже?$B$BMaywiki має справу лише з друїдами та шаманами.",  -- db:7534
[742476892] = "Вітаю, $c.  Настала пора Свята врожаю — час великої щедрості та час спогадів.  Ми беремо участь у бенкетах, щоб відсвяткувати все, за що маємо бути вдячні, і згадуємо наших предків та героїв минулого, щоб подякувати їм за спадщину, яку вони нам залишили.$B$BБудь ласка, не соромтеся долучитися до бенкету, який тут влаштовано.  Також я пропоную кілька феєрверків, щоб допомогти відсвяткувати цю радісну пору року.",  -- db:7535
[233478811] = "Ми не повинні дозволити Альянсу розширювати свою сферу впливу в Араті! Навіть їхній крихітний «Притулок-Пойнт» одного дня може перерости в загрозу для нас.",  -- db:7554
[542047010] = "Битва за Аратську улоговину — це боротьба за ресурси.  Деревина, руда, продовольство... Все це необхідно для того, щоб вести успішну війну.$B$BПозбавити ворогів їхніх запасів — це те саме, що вбити їх на полі бою.",  -- db:7555
[203718758] = "Може, я й сліпий, але бачення в мене є.$B$BВ основному я маю справу з мисливцями та розбійниками, $r.",  -- db:7556
[505125165] = "Вітаю, мандрівнику. Я — Рін’вошо, торговець із Зулдазара. Я прибув із Південних морів і привіз із собою багато екзотичних товарів та предметів із моєї батьківщини.$B$BМожливо, якщо ти доведеш свою цінність моєму племені, я погоджуся на обмін.  А якщо у тебе є якісь жетони честі мого племені, то, можливо, ми зможемо обмінятися ще більше.",  -- db:7574
[160910283] = "Я — Занза, Лоа Зандалара. Я прибув із Зандалара в цій ефірній подобі, щоб допомогти своєму народу. Хаккар не має влади над моєю душею.$B$BЯ допомагаю тим, хто допомагав народу Зандалара.",  -- db:7594
[158524458] = "Друг зандалріанців! Ти заглибився в лігво Бога Крові, $c. Тобі варто прислухатися до того, що я скажу.$B$BБагато тисяч років тому, коли корінні тролі імперії Зул'Аман вели боротьбу з нападниками-язичниками з числа високих ельфів, у Занзи було викрадено велику магію. Цю магію високі ельфи використали для зачарування своєї зброї та обладунків, щоб полегшити собі завоювання тролів цього регіону.",  -- db:7595
[63379172] = "А ви? Тоді ви знаєте, наскільки слабкою й жалюгідною була версія магії тролів у виконанні високих ельфів?$B$BВисокі ельфи не могли збагнути, чому народ, наділений такою ж магічною схильністю, як і вони, не міг протистояти силам трольського вуду. Для блідошкірих це було просто немислимо. Вони змирилися з тим, що мусили використовувати спотворену версію трольських заклинань. Гадаю, вони називали їх «Арканум».$b",  -- db:7596
[270505838] = "Занза може створити стародавні заклинання тролів, маючи відповідні компоненти. Ця магія допоможе вам перемогти Хаккара та його поплічників.$B$BI прошу лише принести мені три предмети. Зізнаюся, що один із цих предметів не є абсолютно необхідним, але я бажаю очистити світ від магії високих ельфів.",  -- db:7597
[896880381] = "Перший — це прадавній талісман, який потрібно забрати у наймогутнішого з Хаккарі.$B$BДругий — проколена лялька вуду. Їх можна знайти у купах сміття, що захаращують це огидне місце. Загляньте всередину проклятих куп худу.$B$BОстанній — це високоельфійська копія магії тролів, відома як «Арканум». Я не знаю, де їх можна знайти.$B$BПринесіть мені всі три, і я створя для вас потужне закляття!",  -- db:7598
[868991831] = "Вибач, $c, але ти ще не маєш достатнього досвіду, щоб увійти до Ущелини Воєнної Пісні.",  -- db:7599
[653605799] = "Ласкаво просимо на рибальський конкурс у Буті-Бей, де щотижня ми обираємо найкращого рибалку, який стане «Майстром риболовлі»!$B$BЗ 14:00 до 16:00 вздовж усього узбережжя Стренглторна з’являтимуться косяки смачних риб.  Якщо під час риболовлі ваш поплавок потрапить у зграю смачних риб, ви зловите саме її, а не звичайну рибу Странглторна.$B",  -- db:7614
[951483297] = "Вітаю, $c.  Я — Ексжал, слуга Растахана.",  -- db:7615
[956663824] = "Вибач, $c, але тобі треба набратися більше досвіду, перш ніж ти зможеш вижити в Долині Альтерака.",  -- db:7616
[378674268] = "«Взірці сили» — це залишки стародавньої Імперії Гурубаші.  Ми, жителі Зандалара, шукаємо їх — вони не лише мають для нас величезну колекційну цінність, але й, як ми віримо, містять приховані сліди магії, якою користувалася стара Імперія.$B$BУ Зул'Гурубі ви, швидше за все, знайдете три види «Взірців»: монети, прикраси та первинні предмети.  Принесіть їх нам у потрібній кількості, і ви отримаєте в нагороду найкращі предмети, які ми, жителі Зандалара, коли-небудь виготовляли.$B",  -- db:7634
[979582393] = "«Взірці сили» — це залишки стародавньої Імперії Гурубаші.  Ми, жителі Зандалара, шукаємо їх — вони не лише мають для нас величезну колекційну цінність, але й, як ми віримо, містять приховані сліди магії, якою користувалася стара Імперія.$B$BУ Зул'Гурубі ви, швидше за все, знайдете три види «Взірців»: монети, прикраси та первинні предмети.  Принесіть їх нам у потрібній кількості, і ви отримаєте в нагороду одні з найкращих предметів, які ми, жителі Зандалара, коли-небудь виготовляли.",  -- db:7634
[350496325] = "На цій табличці зображені стародавні символи та викарбувані грізні слова сили, але їхнє значення для вас залишається незрозумілим.",  -- db:7635
[53603395] = "На цій табличці зображені стародавні символи та грізні слова сили, які використовувалися для створення «Божевілля Моджо Гурубаші»...",  -- db:7636
[945840808] = "Якщо мене запитати, то найкраще в риболовлі — це її повільний темп. Це дає час подумати, обміркувати минулі події та спланувати майбутні.$B$BА ще це чудова нагода випити. І неабияк.",  -- db:7638
[52104810] = "Ще раз дякую за те, що повернув мені мою щасливу рулетку, $N.  Клянуся, вона допомагає мені ловити більшу рибу!",  -- db:7639
[524814962] = "Щоб зловити Газ'ранку, вам знадобиться спеціальна приманка «мудскунк». Я роблю їх сам!$B$BАле однієї приманки недостатньо; потрібні ще й мудскунки... їх треба покласти в приманку, щоб вона набула старого, смердючого запаху!$B$BКоли мудскунки будуть у вас, киньте приманку з мису Пагле в Зул’Гурубі... а потім візьміть щось випити й чекайте... але не надто довго, бо Газ'ранка обов’язково прибіжить, тупотячи ногами!",  -- db:7640
[384981432] = "*Жужж* *ДЗЕНЬК*$B$BI отримали вказівку приймати рідкісних риб високої якості та повертати цінні рибальські приналежності Ната Пейгла.   Потрібні риби.$B$B*БУМ* *Жужж*$B",  -- db:7641
[668871973] = "Вибач, $c, але тобі треба стати сильнішим, перш ніж я дозволю тобі увійти до Аратської улоговини.",  -- db:7642
[845147080] = "Грі'лек із «Залізної крові»$B$BМандрівник.  Нехай його сила та жага до бою простягаються крізь століття.  $B$BГрі'лек тепер мешкає далеко звідси.  Можливо, одного дня він повернеться...",  -- db:7643
[378353645] = "Відправляйтеся до Зали Хоробрих. Там ви знайдете Дефілера, Дезе Сноубейна, який допоможе вам дістатися до Аратської улоговини.",  -- db:7644
[531316998] = "Ви хочете допомогти «Покинутим» у їхній боротьбі проти людей в Аратській улоговині? Тоді вирушайте до Залу Хоробрих і поговоріть із Дезе Сноубейн.",  -- db:7644
[408965649] = "«Мудскунки» — це особливо смердюча порода риб, яка полюбляє тропічні води.  Зуліанський мудскунк — найсмердючіший з усіх — мешкає виключно у задушливих водах Зул'Гуруба.$B$BСаме зуліанські мудскунки, як я вважаю, привабили Газ'ранку до цього місця, хоча тролі, мабуть, скажуть вам, що він — один із їхніх богів...$B$BВірте, у що хочете, але повірте мені — наповніть одну з моїх приманок зулійськими мудскунками, і той старий обов’язково з’явиться!",  -- db:7645
[367578818] = "Іди до «Роял-Квотер». Знайди сера Малорі Вілера. Він страшний.",  -- db:7646
[612413049] = "Басейн Араті — місце, де можна забрати слабких людей. Сер Малорі Вілер відправив вас туди.",  -- db:7646
[511611109] = "Ви можете знайти Мартіна Лінді в «Басейнах бачення», що розташовані під «Піднесенням Духу». Він допоможе вам дістатися до Аратської улоговини.",  -- db:7648
[874334590] = "Ви хочете допомогти «Осквернителям» у їхній боротьбі проти «Ліги Аратора» в Аратській улоговині?  Дуже добре, тоді вам слід звернутися за допомогою до Мартіна Лінді.  Шукайте його в «Басейнах бачення».",  -- db:7648
[122164764] = "Люди потребують вашої допомоги у боротьбі проти «Покинутих» у Басейні Араті. Зайдіть до Залу зброї та поговоріть з їхнім представником, Доналом Осгудом.",  -- db:7649
[486922270] = "Ліга Аратора намагається відвоювати у «Покинутих» свої родові володіння в Аратській улоговині. Якщо ви хочете допомогти їм, $N, зверніться до Донала Осгуда в Залі зброї.",  -- db:7649
[990218907] = "У тронній залі короля ви зустрінете леді Хотешем. Вона допоможе вам дістатися до Аратської улоговини, де Ліга Аратора потребує допомоги у боротьбі проти Осквернителів.",  -- db:7650
[647382258] = "Варто віддати належне тому, що «Ліга Аратора» намагається зробити в Аратській улоговині.  Шкода, що на заваді стоять ці неживі потвори та їхні друзі з Орди.  Завітайте до фортеці Штормовій.  Леді Хотешем чекає на вас у тронній залі короля.  Вона допоможе вам дістатися до Аратської улоговини.",  -- db:7650
[724841659] = "Людям у Басейні Араті, безперечно, потрібна вся наша допомога. Той, з ким ви хочете поговорити, — це Керас Вовчесерде. Він чекає на вас на Терасі Воїна, готовий надати допомогу.",  -- db:7651
[415673605] = "Якщо це твоє бажання $c, то тобі потрібно буде поговорити з Керасом Вольфхартом на Терасі Воїнів. Він є представником Ліги Аратора і може допомогти тобі дістатися до Аратської улоговини.",  -- db:7651
[680461220] = "Тром'ка $c!  Ти готовий битися за Орду в Ущелині Воєнної Пісні?",  -- db:7652
[628181983] = "Слава тобі, $N.  Чи хочеш, щоб я допоміг тобі у подорожі до Ущелини Воєнної Пісні?",  -- db:7653
[581694470] = "$N, «Срібнокрилі вартові» мають бути розгромлені!  Ви готові до «Ущелини Воєнної пісні»?",  -- db:7654
[390515556] = "Ти прийшов, щоб битися за нас у Ущелині Воєнної Пісні?  Лок'тар Огар $c!",  -- db:7655
[440639580] = "$C, нам потрібна ваша допомога в Ущелині «Військової пісні». Чи допоможете ви нам у боротьбі проти «Військових вершників»?",  -- db:7656
[325106359] = "Ага, хлопче : дівчино; ти готовий вирушити до Долини Альтерак і дати Орді те, чого вона так просила?",  -- db:7657
[716681217] = "$N, ви хоч уявляєте, з чим нам доведеться зіткнутися в Долині Альтерака? Ви готові битися з кланом Морозних Вовків?",  -- db:7658
[394379378] = "«Гвардію Штормпайка» треба знищити!  Готові до Альтеракської долини $c?",  -- db:7659
[896884357] = "Лок'тар $c!  Нам потрібна ваша допомога в Долині Альтерак.  Додати вас до списку?",  -- db:7660
[867277772] = "Нашим військам у Долині Альтерака потрібна мудрість, щоб здобути перемогу $c.  Ви, здається, саме та людина, яка зможе очолити їх.",  -- db:7661
[733253328] = "Сподіваюся, ви тут, щоб вирушити до Долини Альтерак $N. Нам знадобиться будь-яка допомога, яку тільки можна отримати.",  -- db:7662
[539014224] = "Люди та їхня так звана Ліга Аратора мають намір витіснити нас з Аратської улоговини.  Я так не думаю, $c!  Чи готові ви вирушити туди й довести, що саме вони, а не «Осквернителі», незабаром звідти підуть?",  -- db:7663
[282529892] = "Басейн Араті колись був нашою домівкою, і з вашою допомогою знову нею стане! Чи допоможете ви нам, $c?",  -- db:7664
[488291686] = "Сподіваюся, ти тут, щоб допомогти нам відбити Аратську улоговину у «Осквернителів».  Що скажеш, $N?",  -- db:7665
[965644590] = "Я чекав на тебе, $N.  Ти готовий допомогти нам у Басейні Араті?",  -- db:7666
[847201818] = "Ти вважаєш, що в тебе вистачить сил, щоб знищити Лігу Аратора, $c?  Сподіваюся, що так.  Чого ти хочеш, чи ти просто прийшов, щоб згаяти мій час?",  -- db:7667
[718335735] = "Озирнися навколо, $c.  Ти, безперечно, перебуваєш у винятковому товаристві, але, на мою думку, тобі все ж таки треба довести свою спроможність.  Хм, можливо, я дозволю тобі допомогти нам у нашій справі в Аратській улоговині.  Ти б хотів цього?",  -- db:7668
[45470944] = "Грі'лек із «Залізної крові»$B$BМандрівник.  Нехай його сила та жага до бою простягаються крізь століття.$B$BГрі'лек зараз балансує на межі божевілля...",  -- db:7669
[562609179] = "Хазза'ра, Творець Снів.$B$BЙому належить сила кошмарів, і нехай його вороги назавжди заснуть.  $B$BЗараз Хазза'ра мешкає далеко звідси.  Можливо, одного дня він повернеться...",  -- db:7670
[549056297] = "Ренатакі з «Тисячі мечів».$B$BБіль — це його життєва сила.  Страх — його союзник.  Нехай він колись повернеться і принесе з собою радісне кровопролиття.$B$BРенатакі зараз перебуває на межі божевілля.",  -- db:7673
[173824396] = "Вушулай, Відьма Бурі.$B$BЇї сила — це сила неба, дощу та розтрощеної землі.  Нехай вона знову стане матір’ю для Гурубаші.  $B$BЗараз Вушулай мешкає далеко звідси.  Можливо, одного дня вона повернеться...",  -- db:7674
[639334599] = "Гей-гей-гей!  Я тут, щоб розповісти про чудовий рибальський турнір у Стренглторні, але вам треба бути достатньо витривалими, щоб вижити там, і мати достатньо навичок у риболовлі, щоб ловити рибу в цих водах.$B$BЗавітайте пізніше, коли будете краще підготовлені!$B$B",  -- db:7676
[784503919] = "Привіт, привіт, привіт!   Якщо хочете перевірити свої рибальські навички, то я знаю саме те місце, що вам потрібно!   Цієї неділі у Стренглторні відбудеться рибальський турнір!$B$B",  -- db:7677
[141481524] = "Ти ще не достатньо сильний, $c.  Іди собі.",  -- db:7678
[941163401] = "Наша потреба в допомозі в Аратській улоговині більша, ніж можна собі уявити, $N.  Однак не меншою є й честь та репутація, які можна здобути там у цей скрутний час.  Я настійно прошу вас знайти в цьому місті бойового майстра Аратської улоговини.",  -- db:7679
[306405541] = "Я дуже рада, що ви запитали. Ви знайдете сера Малорі Вілера в «Королівському кварталі» в присутності нашої Темної Леді.",  -- db:7680
[17832894] = "Звичайно, звичайно. Будь ласка, зверніться до Дезе Сноубейн у «Залі хоробрих» у «Долині честі» цього міста, $c.",  -- db:7681
[478201984] = "Тобі треба стати сильнішим, $c, перш ніж ти зможеш допомогти нам у Долині Альтерака.",  -- db:7683
[467082070] = "Вітаю, $c.  Зараз у Долині Альтерака існує велика потреба, а також можна здобути ще більшу честь і славу. Чи приєднаєшся ти до нашої боротьби проти Гвардії Штормпайк?",  -- db:7684
[146387199] = "Слава твоєму роду та предкам, $c!  Ти знайдеш Картру Бладснарл у Залі Хоробрих у Долині Честі.",  -- db:7685
[726316984] = "Дуже добре, $N.  Ти знайдеш Гріззла Халфмейна в Королівському кварталі Підміста.  Нехай ти здобудеш велику славу в Долині Альтерака.",  -- db:7687
[457123438] = "На жаль, ти ще не достатньо сильний, щоб вижити в «Ущелині Воєнної Пісні» $c.",  -- db:7688
[557261555] = "$C, нам дуже потрібна твоя допомога в Ущелині Воєнних Пісень у боротьбі проти Срібнокрилих Вартових.  А ще ти зможеш здобути ще більшу честь і репутацію серед «Воєнних Пісень-Передових»!  Чи вистачить тобі мужності вступити в бій?",  -- db:7689
[70318078] = "Тож із великою гордістю повідомляю вам, що Бракгул Смертоносець чекає на вас у Залі зброї, готовий допомогти вам на шляху до Ущелини Воєнної Пісні. Знайдіть його в Долині Честі.",  -- db:7690
[485229882] = "Ви зробили правильний вибір, $N.  Знайдіть Кергула Кроваву Сокиру на Мисливському пагорбі.  Він допоможе вам у подорожі до Ущелини Воєнної Пісні.",  -- db:7691
[164953376] = "Честь і слава чекають на тебе, $c!  Шукай Курдена Бладклоу в Королівському кварталі цього міста.",  -- db:7692
[80939951] = "Боюся, що ти не протримаєшся довго в Долині Альтерака, $c.  Повертайся до нас, коли набереш трохи більше досвіду.",  -- db:7693
[736780387] = "$N, Гвардія Штормпайка як ніколи раніше потребує вашої допомоги в битві проти клану Морозних Вовків у Долині Альтерак. Можливості здобути честь і славу також більші, ніж будь-коли! Чи приєднаєтеся ви до битви?",  -- db:7694
[325145365] = "Fishmaster Bassbait заселив місцеві водойми високоякісними приманками Tastyfish, щоб провести свій турнір.$B$BЯк тільки він визначить переможця, я дам тобі срібло за кожні п’ять приманок Tastyfish, які ти принесеш мені!$B",  -- db:7696
[706945968] = "Ти прийняв правильне рішення, $c.  Нашого бойового майстра, Глордрума Сталебородого, ти знайдеш у Залі зброї.  Удачі, $N!",  -- db:7697
[810844836] = "Дякую за пропозицію, $c.  На жаль, у тебе ще недостатньо досвіду, щоб впоратися з небезпеками Аратської улоговини.",  -- db:7699
[273874836] = "Чи допоможете ви нам у цей важкий для нас час у Басейні Араті, $c?  Шанс на здобуття більшої честі та підвищення авторитету зараз більший, ніж будь-коли, і ваша допомога, безсумнівно, сприятиме тому, щоб переломити хід битви проти «Осквернителів».  Чи можемо ми розраховувати на вас?",  -- db:7700
[946119217] = "Дякую, $N! Ти знайдеш Кераса Вольфхарта на Терасі Воїнів, поруч із місцевими інструкторами. Він покаже тобі шлях до Аратської улоговини. Удачі тобі та нехай супроводжує тебе велика честь.",  -- db:7701
[419770570] = "Ми будемо вам зобов’язані $c.  Шукайте Донала Осгуда в Залі гербів.  Він із задоволенням допоможе вам у подорожі до Аратської улоговини.",  -- db:7702
[254290960] = "Чудово!  Ви зробите велику послугу Лізі Аратора, вигнавши з Аратської улоговини Осквернителів та їхніх найманців з Орди.  Зверніться до леді Хотешем у королівській аудієнційній залі фортеці Штормовій.  Вона чекає на вас $N.",  -- db:7703
[27401713] = "Пори року змінюються для всіх у свій час, але ти все ще перебуваєш у весні свого життя. Будь ласка, повернися до нас пізніше, $c, коли набудеш більше досвіду.",  -- db:7704
[194379376] = "$C, ми не соромимося зізнатися, що нам потрібна будь-яка допомога, яку ми зможемо отримати у нашій боротьбі в Ущелині Воєнної Пісні.  Але зараз ви зможете здобути більшу честь, ніж будь-коли раніше, якщо вирішите поділитися з нами своїми навичками.  Крім того, «Срібнокрилі вартові» напевно більш прихильно оцінять ваші зусилля на нашу користь.  Чи приєднаєтеся ви до битви?",  -- db:7705
[453303567] = "Нехай світло Елуни осяє тебе, $N!  На Терасі Воїнів ти знайдеш Еталас, нашу майстриню бою.  Вона допоможе тобі дістатися до Ущелини Воєнної Пісні.",  -- db:7706
[473420402] = "«Взірці сили» — це залишки стародавньої Імперії Гурубаші.  Ми, жителі Зандалара, шукаємо їх — вони не лише мають для нас величезну колекційну цінність, але й, як ми віримо, містять найпотужніше магічне начало, яке використовувала стара Імперія.$B$BУ Зул'Гурубі ти зможеш знайти три види «Взірців»: монети, прикраси та первинні предмети.  Принесіть їх нам у потрібній кількості, і ви отримаєте в нагороду найкращі предмети, які ми, зандалари, коли-небудь виготовляли.$B$BМожете на це розраховувати, друже!$B$B",  -- db:7707
[915393678] = "Ти виявляєш мудрість, невластиву твоєму віку $c.  Дякую.  Нашого бойового майстра, Ліландріс, ти знайдеш біля бойового столу в Залі зброї.  Вона допоможе тобі дістатися до Ущелини Воєнної Пісні.",  -- db:7708
[551073213] = "«Срібні крила» будуть у вашому боргу на суму $c.  Ви знайдете Ельфаррана, нашого бойового майстра, у фортеці Штормовій, де він перебуває на аудієнції у юного короля.  Нехай богиня береже вас!",  -- db:7709
[760520818] = "Вітаємо, майстре вудки та котушки!   Якщо ви бажаєте випробувати свої сили у змаганні з найкращими рибалками цих земель, то слухайте уважно!   Цього недільного дня у Стренглторні відбудеться змагання, на якому буде визначено найкращого рибалку!$B$B",  -- db:7712
[688551800] = "«Взірці сили» — це потужна магія.  Це магія Імперії Гурубаші.  Ми, жителі Зандалара, мусимо здобути цю магію.  Плем’я забере цю магію собі.  Бог Крові не знищить нас.$B$BУ Зул’Гурубі є три види «Взірців».  Шукайте монети.  Шукайте біжу.  Шукайте первинні предмети.  Це й є «Взірці».$B$BВідправляйтеся до Зул’Гуруба негайно.  Вбивайте.  Захоплюйте «Взірці сили».  Принесіть їх до племені.  Заслужіть нашу повагу.  Заслужіть наше бойове спорядження.  Заслужіть справжню силу.",  -- db:7713
[592473289] = "Переможець нашого конкурсу вже визначений, але Чан готовий придбати будь-яку рибу Tastyfish, яку ви виловили!$b$bУ вас завжди є наступна неділя, щоб продемонструвати свої рибальські навички!",  -- db:7714
[632587589] = "За моєю спиною — Вівтар Занзи, священне місце для нас, жителів Зандалара.  Ми молимося тут, щоб зміцнити свою рішучість у підготовці до війни проти Бога Крові, Хаккара.$B$BДоведіть свою відданість племені, скориставшись вівтарем для знищення будь-якого з «Біжу» Хаккарі, які ви можете знайти всередині Зул’Гуруба.  Крім того, я обміняю тобі жетони честі, якими користується наше плем'я, на набори монет, які ти можеш знайти в Зул'Гурубі.  Принеси мені монети, які я шукаю, і ти отримаєш нагороду!",  -- db:7717
[135118664] = "Зандаларські тролі подолали довгий шлях і зазнали чимало випробувань, щоб дістатися сюди, але якщо ми не зробимо нічого… це означатиме нашу загибель…",  -- db:7718
[30494516] = "Ми, тролі Зандалара, прибули сюди з далеких островів, адже не можемо ігнорувати загрозу, яка зараз нависла над нашим світом.$B$BКерівник нашої експедиції, Молтор, привів нас на острів Йоджамба, що розташований уздовж північного узбережжя Странглторна, і навіть зараз набирає відважних героїв, щоб ті вирушили до стародавнього міста тролів... Зул'Гуруб.",  -- db:7720
[211990851] = "Ми, тролі-зандаларі, прибули сюди з далеких островів, адже не можемо ігнорувати загрозу, яка зараз нависла над нашим світом.",  -- db:7721
[913546575] = "Старого собаку не навчиш новим трюкам. Принаймні так мені колись хтось казав. На щастя для вас, я переконався, що це неправда.$b$bТож, чи хотіли б ви, щоб ваш улюбленець забув свої навички?",  -- db:7722
[218369376] = "Я — Ратерфорд Твінг, головний постачальник «Осквернителів», що дислокуються тут, у Басейні Араті.  У міру того, як ви будете підвищувати свій рейтинг у нас, я надаватиму вам чудовий вибір товарів, які можуть вам знадобитися.  Якщо вам знадобиться ремонт предметів, я також надаю такі послуги.",  -- db:7723
[500953553] = "Я — Семюел Хоук, головний постачальник Ліги Аратора, що базується тут, у Басейні Араті.  У міру того, як ви будете підвищувати свій рейтинг у нас, я надаватиму вам чудовий вибір товарів, які можуть вам знадобитися.  Якщо вам знадобиться ремонт предметів, я також надаю такі послуги.",  -- db:7724
[147259716] = "Битва за Ущелину Воєнних Пісень — це битва, яку ми не можемо програти. Ми боремося за свою честь і за свою землю, і жоден орк чи збитий з правильного шляху союзник не відбере їх у нас!",  -- db:7725
[789973721] = "Захищати лісозаготівельні роботи Орди тут, у Попеліній долині, — завдання не з легких, але ми ніколи не ухилялися від бою! Нічні ельфи та їхні союзники будуть розгромлені!",  -- db:7726
[251591984] = "Вітаємо, мандрівнику. Доки ви перебуваєте в межах стін Цитаделі Сенаріону, вам нічого не загрожує.$B$BБудьте обережні, залишаючи територію Цитаделі, оскільки останнім часом тут з’явилися рої силітидів.",  -- db:7727
[924129656] = "Я постачаю «Холд» різними реліквіями, необхідними для чаклування, а також іншими алхімічними реагентами.",  -- db:7728
[829338033] = "Велике зло пробуджується, $r. Ти це відчуваєш?$B$BBах! Звісно, що ні. Дай мені свою броню та зброю, і я відновлю їхню силу.",  -- db:7729
[344808180] = "Ой, у мене вже майже закінчилися запаси! Чому цей клятий гоблін так довго не повертається?",  -- db:7730
[835130861] = "Поглянь за себе, $r. У вулику кипить життя, а земля навколо нас здригається й тремтить.$B$BНастав час виконати обіцянку, яку я дав тисячу років тому. Піски знову зміщуються, а кіраджі готуються до війни.",  -- db:7731
[393650830] = "Чому саме зараз, $r? Я просто не розумію. Стільки роботи ще треба зробити...",  -- db:7732
[771396773] = "Останнім часом Командир не в собі. Його коханка зникла під час археологічних розкопок у південній пустелі — зникла без сліду! Справді, дуже дивно.$B$BI, мабуть, ти шукаєш роботу? Мені що, підказати тобі прямо в лоб?",  -- db:7733
[783664293] = "Ти чуєш це, незнайомцю? Гудіння з кожним днем стає все гучнішим. Мабуть, саме ці кристали доводять цих комах до божевілля.",  -- db:7734
[915521540] = "Поглянь на небо, $c. У цих краях вже тисячу років не бачили Польоти Драконів! Ці Кіраджі щось замишляють, я це точно знаю!",  -- db:7735
[499254397] = "Бронзобородий знову зник! Цей карлик, безперечно, не успадкував розсудливості свого брата.",  -- db:7736
[73999205] = "Попіл від спаленого «Вікермена» випромінює магічну силу.",  -- db:7737
[554356508] = "Попіл від спаленого «Плетеного чоловіка» випромінює магічну силу. Ти вже наніс цей попіл на своє обличчя.",  -- db:7738
[151514734] = "Зі святом «Хеллоу-Енд», $c!",  -- db:7739
[980367438] = "Ти любиш цукерки?  Я люблю цукерки.",  -- db:7739
[95078582] = "Вперед, «Forsaken»!  Ура нам!",  -- db:7739
[380936339] = "Ласкаво просимо на фестиваль «Вікермен», $c!$B$BПід час святкування «Хеллоу-Енду» «Покинуті» спалюють солом’яного чоловіка на честь цього найшанованішого свята.  Саме цього дня сама Королева Банші визволила нас із лап Короля Ліча та Плеті.  Відтоді ми залишаємося вільними. Тим, хто прагнув бачити нашу поразку, ми відплатили сповна… помстою!$B$BСпалення «Вікермена» розпочнеться о 20:00!",  -- db:7740
[349031091] = "Гей, ти!  Ти виглядаєш на здорового... Нам потрібна твоя допомога у захисті Саутшора!$B$BЦі кляті Покинуті всі розлючені, бо настало Свято Хеллоу.  Їхнє «святкування», без сумніву, приведе їх прямо до наших воріт.  Якщо у тебе є час, нам дуже знадобиться твоя допомога!",  -- db:7741
[380237503] = "Саме ми повинні завдати першого удару. Ми не можемо дозволити собі повторити помилки минулого...",  -- db:7742
[618133629] = "Геть, невірний!  Нехай сила Безодні знищить тебе!",  -- db:7744
[3267549] = "Вітаю, $c.  Ласкаво просимо до Цитаделі Сенаріону.  Звідси ми завдамо удару по силітидам там, де вони найсильніші.  Сподіваюся, ти прийшов, щоб допомогти.",  -- db:7746
[577882324] = "Радий знову бачити вас, $N.  Ваша допомога дозволила нам значно підвищити рівень безпеки наших ліній постачання.  Сподіваюся, ви розумієте важливість логістики в таких масштабних бойових операціях, як ця.",  -- db:7747
[797795614] = "Як ти смієш спілкуватися з герцогом Ради, черв’яку!",  -- db:7749
[649526841] = "Ти полюєш на Десклепс, $N?  Я справді вражений.  Тільки цього тижня вона забрала у мене двох бійців.  Сподіваймося, тобі пощастить більше, ніж їм.",  -- db:7751
[489897340] = "Привіт!  Дякую, що врятував мене!  Гадаю, я трохи полежу, поки не відновлю сили.",  -- db:7752
[137712786] = "Хто ти?  Де я?  Я відчуваю... таку слабкість...",  -- db:7753
[871461739] = "Яка комаха з’являється перед лордами Ради?  Без сумніву, комаха, яка хоче, щоб її розчавили!",  -- db:7754
[284186514] = "Тоді краще присядьте, бо це буде довга історія.$B$BКоли ми вперше прибули до Сілітуса, пані Мар’аліт стала першою з нічних ельфів із Ценріонського форту, яка приєдналася до експедиції. Наш розпорядок дня не відрізнявся від звичайного: ми збирали групу, щоб вирушати в різні вулики й шукати загублені артефакти.",  -- db:7755
[715541107] = "Це точно! У тих вуликах кипіло життя — там було повно різноманітних силітидів, які аж ніяк не раділи нашій появі.$B$BУсе йшло добре, поки ми не натрапили на кристал із гліфами у «Хайв-Регал». Її тягнуло до нього, наче метелика до вогню! Вона притулила свою милу щічку до кристала й миттєво впала в стан, схожий на транс. Звісно, це стурбувало мою команду. Ми підхопили її й швидко винесли звідти!",  -- db:7756
[404571962] = "Ми відвели її до Командира, сподіваючись, що друїди «Кола» зможуть її вилікувати. І справді, їм вдалося її привести до тями. Ми вирішили, що наші справи з «Колом» завершені й ми можемо повернутися до роботи.$B$B Минуло кілька тижнів, і все йшло добре. Бранн тоді ще був з нами, тож у нашій роботі панував певний порядок. Аж раптом одного дня вона несподівано з’явилася знову в нашому таборі.$b",  -- db:7757
[618177654] = "Ти що, здурів? Про кого ж іще я міг би говорити? Так, про ту дівчину — пані Мараліт. У всякому разі, вона повернулася, і настрій у неї був не надто гарний. Ось тоді й почалися всі ці вимоги.$b",  -- db:7758
[310033780] = "Вона вимагала, щоб ми негайно повернулися до «Хайв’Регал»! Бранн не збирався терпіти таких вибриків. Він сказав їй, що ми нізащо не повернемося до тих вуликів без армійського підкріплення. Це стало надто небезпечно. Кількість тих смердючих комах, здавалося, потроїлася порівняно з тим, коли ми вперше наважилися зайти туди.$B$BСаме тоді Наталія втратила самоконтроль!",  -- db:7759
[826810433] = "Що ти маєш на увазі, «що я маю на увазі»? Вона просто збожеволіла! Дівчина просто зійшла з розуму. Зазвичай я не б'ю дівчат, але коли я прийшов до тями після втрати свідомості, я був страшенно розлючений. Бранн, Рутгар, я і мавпа накинулися на неї, як справжні орки! Це диво, що нам вдалося її відбитися. Вона здавалася майже одержимою!",  -- db:7760
[942013091] = "Хто знає? У всякому разі, це було востаннє, коли я її бачив. Можливо, Франкал зможе надати тобі більш детальну інформацію.$B$BНе хочу відволікати тебе від теми, бо впевнений, що робота, яку ти виконуєш для Командира, є важливою, але ми натрапили на щось величезне. ВЕЛИЧЕЗНЕ! Наші прохання до Айронфорджа про надання війська поки що залишилися без відповіді. Мабуть, ми занадто розтягнулися на захист королівства чи ще якусь подібну нісенітницю. Як тільки ти передасиш звіт Командиру, повертайся сюди з кількома друзями. Нам потрібна твоя допомога!",  -- db:7761
[642922635] = "Ой, та ну, тільки не це знову... Сідай, $g sonny:missy;.$B$BI Я впевнений, що Рутгар вже розповів тобі частину цієї історії, тож я позбавлю тебе нудних подробиць і відразу перейду до суті справи.",  -- db:7762
[969671158] = "Ну що ж! Отже, Господиня повернулася, щоб ще раз спробувати розібратися з вуликами, але Бранн не мав наміру терпіти ці дурниці! Ще до початку сутички вона почала розмовляти з чимось або кимось. А ще дивніше — вона почала співати заклинання мовою, якої ніхто з нас ніколи не чув.",  -- db:7763
[505083370] = "І не кажи! Це ще дивніше, якщо врахувати, що Бранн, Рутгар, я та мавпа разом знаємо 38 різних мов, включаючи трохи титанської — як ванірської, так і асирської.$B$BТож, у будь-якому разі, про що б вона там не клацала, це точно не було адресовано нікому з присутніх. Потім вона кивнула і перейшла в наступ! Відверто напала на нас!",  -- db:7764
[226847636] = "Послухай, $g sonny:missy;, я хочу, щоб ти знав: те, що на нас напало, аж ніяк не була якоюсь там жрицею! Її очі палали чимось злим, і у неї справді піна йшла з рота! Вона увірвалася, випустила якийсь божевільний крик, від якого ми всі розбіглися в різні боки, а потім почала один за одним розривати наші розуми. Я чула у голові розмиті слова, бачила, як інші час від часу втрачали свідомість то тут, то там. Це було божевілля! Ми б загинули, якби не та клята мавпа.",  -- db:7765
[562040813] = "А що тут питати? Він же мавпа, ти, божевільний дурень. У будь-якому разі, так, мавпа впала в істерику, побачивши, як старий Бранн впав обличчям у пісок. Ніщо з того, що робила нічна ельфійка, не могло зупинити цього Глібба від того, щоб бити її по голові.",  -- db:7766
[61230998] = "Я тобі скажу, «що було далі». Вона побігла прямо до вулика. І знаєш, що найбожевільніше? Жодна клята комаха не стала їй на заваді й не спробувала її зупинити. Вона пробігла крізь них усіх, ніби була з ними в найкращих стосунках уже століттями.",  -- db:7767
[2751978] = "Так.",  -- db:7768
[383721591] = "Кристал вкритий хитромудрими символами та рунами. Ви не можете розібратися в цьому.",  -- db:7770
[311919342] = "З-під каменю доноситься ледь чутний шепіт...$B$BПривіт, малятко.  Чи є у тебе новини для тамплієра?",  -- db:7771
[320674462] = "З-під каменю може долинути шепіт...$B$BПривіт, малятко.  Чи є у тебе новини для тамплієра?",  -- db:7771
[668114180] = "З-під каменю лунає чіткий голос...$B$BДе твій медальйон рангу, малятко?  Ти не можеш розмовляти з герцогом без підтвердження свого титулу...",  -- db:7772
[784429283] = "Де твій медальйон, що підтверджує твій статус, малятко? Ти не можеш розмовляти з герцогом без підтвердження свого титулу...",  -- db:7772
[708973656] = "З-під каменю лунає чіткий голос...$B$BТи прийшов до нас із титулом, тож ми вислухаємо тебе, але не випробовуй нашу терплячість, $c.  Рада не має часу на пусті плітки від таких, як ти.",  -- db:7773
[818744577] = "Ви звертаєтеся до нас із офіційним зверненням, тож ми вислухаємо вас, але не випробовуйте нашу терплячість, $c.  Рада не має часу на порожні плітки від таких, як ви.",  -- db:7773
[631293139] = "З каменю лунає громоподібний голос...$B$BВітаю, командире. Які новини про Сілітус ти приніс Володарям Ради?",  -- db:7774
[408550988] = "Відсутній текст англійською мовою.",  -- db:7775
[594316581] = "З каменю лунає громовий голос...$B$BЩо це таке?  Я відчуваю, що тут десь метушиться якийсь маленький культист!  Забирайся геть, шкіднику, або зазнаєш гніву володарів Ради!",  -- db:7776
[116899593] = "Куди б ви хотіли полетіти?",  -- db:7778
[476003853] = "Духи Сілітуса кличуть нас, $n.  Земля плаче, бо має розповісти сумну історію...",  -- db:7779
[409871866] = "Привіт, $c. Хіба я не бачив тебе нещодавно на ексклюзивній зустрічі? Ти здаєшся мені знайомим, але, з іншого боку, у цьому місті завжди багато людей.$B$BЯкщо ти відвідував той з’їзд, то, безперечно, тобі дали секретний код. Скажи мені свій код, і я в обмін на це подарую тобі спеціальний приз.",  -- db:7780
[970359730] = "$N!  Сподіваюся, ти готовий взятися до роботи, адже на Острові Сонстрайдер на тебе чекає чимало справ.$B$BЗ часу руйнування Сонцеджерела Артасом та Плетью ми — раса, що дрейфує в морі невизначеності.  Ми балансуємо на межі забуття.  Це зміниться, $c, і ти будеш навчатися та водночас допомагати нам відродитися.$B$BЗовнішні землі чекають на нас!",  -- db:7781
[434164726] = "«Коло Сенаріону» — мудре товариство, яке розкрило чимало таємниць Землі. Майстрам варто прислухатися до слів цих друїдів.",  -- db:7782
[700574823] = "Примарна постать дивиться на тебе з недовірою в очах і мовчить.",  -- db:7783
[441741459] = "«Сонячна Вежа» колись відкривала чудовий краєвид на Сонячне Джерело... колись. Наше життя перевернулося з ніг на голову, $N, але ми, попри все, продовжуємо жити.  Такий вже наш шлях; ми — ті, хто виживає.$B$BЯкщо ти хочеш пережити ці потрясіння... і жити далі на власних умовах, то ти ПОВИНЕН навчитися виживати.  Усі кровні ельфи мусять це зробити.  Ти повинен опанувати свою ненаситну жагу до магії, перш ніж вона опанує тебе.",  -- db:7784
[628082566] = "Ваша подальша служба на благо Кровних ельфів має вирішальне значення для нашого виживання!  Ми всі маємо докласти зусиль, щоб вибратися з того болота, в якому опинилися.$B$BЯкщо ви готові до роботи, то давайте приступимо.",  -- db:7785
[419939220] = "Знання — це сила, справжня сила, мій юний друже. Тобі варто набути їх якомога більше і прислухатися до тих, хто вже це зробив.$B$BДо руйнування Сонячного джерела ми вводили себе в оману, вважаючи, що досягли вершини своєї цивілізації.  Лише «Плеть» змусила нас впасти на коліна… і, в певному сенсі, повернутися до реальності.",  -- db:7786
[535032359] = "Ви застали мене в дуже важливий момент моїх досліджень!  Не хвилюйтеся, можете приєднатися до мене у тихому роздумі... з акцентом на «тихому», якщо, звичайно, ви не проти.",  -- db:7787
[171730834] = "Якщо ти прямуєш до міста, то у мене для тебе є важливе завдання!",  -- db:7788
[104707350] = "Ласкаво просимо! Підходьте, не соромтеся. Ось це — моя гордість і радість… «Blastenheimer 5000 Ultra Cannon»! Хіба вона не красуня? Ви, щоправда, трохи повненькі в талії, але, гадаю, вам тут буде затишно. Літати — це так весело, хочете навчитися?",  -- db:7789
[228187901] = "О, це просто! Користуйся ним так само, як і будь-яким іншим пристроєм, що активується. Не хвилюйся, я сам подбаю про те, щоб запалити запал. Коли ти опинишся в повітрі, то помітиш, що, здається, «плаваєш», але це не триватиме вічно. Твоя мета — об’єкт на озері далеко-далеко там. Переконайся, що почнеш спуск, від’єднавши «крила» в потрібний момент, щоб приземлитися на воду, інакше… ну, я ж не продаю страховку на життя.",  -- db:7790
[484570597] = "Привіт, $c, і ласкаво просимо на Ярмарок Темної Місяця. На ярмарку стільки всього цікавого, що тим, хто тут вперше, може бути трохи складно зорієнтуватися. Саме тому я тут, щоб допомогти. У вас є якісь запитання?",  -- db:7792
[506220602] = "Чудове запитання! На цьому ярмарку у нас є багато речей на продаж. Якщо вас цікавлять їжа та напої, то завітайте до кіоску Стампа та Силаннії. Мій улюблений напій — «Darkmoon Special Reserve».$B$BЯкщо ж ви хочете придбати щось більш екзотичне, то у Лхари, можливо, знайдеться саме те, що вам потрібно. Вона спеціалізується на рідкісних товарах з усього світу.$B$BА ще десь тут бігає Флік. Якщо вам вдасться його наздогнати, він продає м’ячі для кидання та жаб, яких можна тримати як домашніх улюбленців.$B",  -- db:7793
[815143014] = "Раді, що ви запитали. Призові квитки «Ярмарку Темного Місяця» — це наш спосіб залучити вас до допомоги в організації ярмарку, а натомість ви зможете обміняти свої квитки на спеціальні призи!$B$BДля початку вам слід поговорити з Хроносом, Керрі Хікс, Рінглінгом та Єббом Небблгіром, щоб дізнатися, кому ви зможете найкраще допомогти. У них завжди знайдеться щось, що потрібно зробити для вдосконалення та розширення наших атракціонів.$B$BА коли у вас буде достатньо квитків, зверніться до Гелваса Грімгейта, і він надасть вам список призів на вибір.$B",  -- db:7794
[629013517] = "Ніхто достеменно не знає, хто виготовив Карти Темного Місяця і яке їхнє справжнє призначення, але можу сказати, що їх знаходили по всьому Азероту — зазвичай у руках лиходіїв, які намагаються розгадати їхні таємниці.",  -- db:7795
[455827155] = "Я настійно рекомендую вам завітати до Сайджа, щоб він вам поворожив. Я знаю, я знаю... він гнол. Але це дуже особливий гнол, який має здатність передбачати ваше майбутнє!$B$BІ ми постійно розширюємо ярмарок, додаючи всілякі нові атракціони!",  -- db:7796
[83872769] = "У Сілітусі у нас не один ворог, $N.$B$BПоки увага всіх прикута до сілітидів, ми з моїм старшим братом пильно стежимо за божевільними з «Молота Сутінків».$B$B",  -- db:7797
[237913828] = "Вітаю, $N.",  -- db:7800
[979288685] = "Вітаю, мандрівнику. Саме тут, майже 1 000 років тому, кіраджі розпочали свій руйнівний похід по Калімдору.$B$BПід час війни загинули тисячі людей, більшість із них — у цій проклятій пустелі під час початкового вторгнення.$B$BЯ — один із небагатьох, хто залишився, прикутий ланцюгами як до минулого, так і до сьогодення. Не знаю, чому я маю залишатися тут, але знаю, що мушу.",  -- db:7801
[417577922] = "Мене вбивали сотні разів. Я завжди прокидаюся тут, живим. Дехто каже, що на мене накладено прокляття, а інші...",  -- db:7802
[384240701] = "Кажуть, що я благословенний: посланець, який сповіщає про настання нової епохи.",  -- db:7803
[198767246] = "Пробуджуються древні сили — сили, яких не бачили й не відчували тисячі років. Світ плаче, $r. Можливо, насувається нове розколоття. Хвороба, що зародилася зсередини...$B$BНечисть почала просочуватися на наші землі. Зі Сну приходять кошмари. Кошмари, що отруюють нам життя навіть у стані бадьорості...",  -- db:7804
[550992153] = "З Днем Хеллоу-Енду!  Як тобі моя маска?  Дуже страшна!",  -- db:7805
[46420078] = "З Днем Хеллоу-Енду!  Як тобі моя маска?  Дуже страшна!",  -- db:7806
[720512844] = "Мені сумно! Сьогодні «Хелловін», а я захворіла. Я пропущу «трик-або-ласощі», бо не можу вийти на вулицю!",  -- db:7808
[651044931] = "Ти найкращий, $N — дякую, що пішов за мене збирати цукерки!",  -- db:7809
[294526940] = "Ти, мабуть, маєш на увазі: «А що там НЕ можна робити»!$B$BУсі власники таверн по всьому світу роздають солодощі на «トリк-ор-трет», а багато міст прикрашені до свята!  Крім того, щовечора неподалік від Підміста відбувається Фестиваль Вікермана.$B$BІ ще одне — я чула, що хвора дівчинка з притулку тут, в Оргримарі, шукає когось, хто допоможе їй зібрати солодощі до свята… Можливо, ти міг би їй допомогти?",  -- db:7812
[501130613] = "Ти, мабуть, маєш на увазі: «А що там НЕ можна робити»!$B$BУсі власники таверн по всьому світу роздають солодощі на «トリк-ор-трет», а багато міст прикрашені до свята!  Крім того, сержант Гартман у Саутшорі потребує допомоги у боротьбі проти Покинутих та їхнього Фестивалю Вікермена.$B$BІ ще одне — я чув, що хворий хлопчик із сиротинця у Штормвіні шукає когось, хто допоможе йому зібрати солодощі до свята.",  -- db:7813
[378665889] = "Дехто називає мене... Імпсі?",  -- db:7814
[644885725] = "Забирайся геть, незнайомцю!  Мені до тебе немає ніякого діла.",  -- db:7816
[946574307] = "Ви вже повернулися!  Чим я можу вам допомогти?",  -- db:7817
[42365843] = "Війна проти Орди набрала повних обертів, $N.  Зараз Альянс перебуває у скрутному становищі, і кожному з нас необхідно зробити свій внесок, щоб допомогти.",  -- db:7818
[726840152] = "Війна наближається, $N.  Настав час кожному члену Орди відгукнутися на заклик і приєднатися до боротьби проти боягузливого Альянсу.",  -- db:7819
[897371487] = "Ти ж за професією шкіряник, чи не так? Це той ледь вловимий запах вичинених шкур — я б його впізнав де завгодно.$B$BМій батько колись розповідав про відомого майстра, який жив у селі Саутвінд кілька століть тому. Шкода, що зараз це місце лежить у руїнах.",  -- db:7820
[194801635] = "У нас є всі необхідні мідні прутки. Дякуємо за допомогу, $c. Можливо, ти захочеш допомогти зі збором інших матеріалів, які тут збирають.",  -- db:7823
[259574917] = "$C, мені потрібно більше мідних злитків! Біля Воріт Ан’Кіраджа назріває війна, і нам потрібні запаси! Альянс зібрав $1997w, а загалом нам потрібно $1998w мідних злитків. Якщо я не отримаю ці мідні злитки, моя голова опиниться на тарілці!",  -- db:7824
[20377872] = "У кристалі ви бачите великі печерні тунелі та коридори. Ви впізнаєте цю місцевість — це Розплавлене Ядро.",  -- db:7825
[210687837] = "Вітаю, $r. Чудовий день, щоб жити, чи не так?",  -- db:7827
[185278591] = "Не всі таурени зневажають таких, як ви, $r. На жаль, мені заборонено запропонувати вам свої послуги.",  -- db:7828
[942416651] = "Слухай уважно, млинчику, нас чекає найважча битва в житті проти комах в Ан’Кіражі, і нам треба до неї підготуватися. Я тут збираю залізні бруски. Наразі Альянс має лише $2002w залізних брусків, але, за прогнозами, для ведення війни нам знадобиться загалом $2003w.",  -- db:7829
[834192070] = "Завдяки зусиллям усіх нас у нас тепер є всі необхідні залізні прути. Поцікавтеся в когось із інших, чи не потрібно ще щось зібрати для військових потреб. А я спробую трохи раніше вибратися звідси, щоб пограти в карти.",  -- db:7830
[567447699] = "$C, будь ласка, вислухай мене. Альянс і Орда готуються до війни з силітидами та їхніми господарями в Ан’Кіражі. Будемо дуже вдячні за будь-яку допомогу, яку ти зможеш надати. Як бачиш, я збираю тут злитки торію для військових потреб. Нам потрібно зібрати загалом $2012w, а наразі ми маємо $2011w.",  -- db:7831
[360677140] = "Дякую, що зв’язався зі мною, $c. Зараз у нас є всі необхідні торієві бруски, але, можливо, тобі варто запитати у інших присутніх, які відповідають за різні напрямки збору.",  -- db:7832
[230923454] = "Це правда, навіть душитель-водорость може стати в нагоді для виготовлення того, що нам знадобиться у майбутній війні в Ан’Кіражі! У нього безліч застосувань: наприклад, для приготування морозива в спекотні дні під сонцем Сілітуса, як мазь від впливу деяких огидних рослин, для дихання під водою, зміцнення шкіри, підвищення швидкості, відновлення магічної сили — стільки всього, що я навіть не можу перелічити! Я вже згадував про приготування морозива?$B$BУ будь-якому разі, у мене тут є приблизно $2047w, а мені потрібно загалом $2048w!",  -- db:7833
[562731512] = "Не те щоб я був цілком впевнений, що навіть за мільйон років у тебе вистачило б «странглкелпа», зважаючи на те, скільки морозива потрібно, але, здається, у нас його вистачає. Принаймні, так мені кажуть. Схоже, деяким іншим тут може знадобитися допомога з тим, що б вони там не збирали. Це цілком зрозуміло, якщо врахувати, що їхнє заняття просто не може бути таким цікавим, як збирання «странглкелпа».",  -- db:7834
[246933998] = "Вітаю, юний $c. У рамках підготовки до війни в Ан’Кіражі проти силітидів Альянс доручив мені очолити збір фіолетового лотоса. Ця квітка, наскільки мені відомо, має багато застосувань, тому я погодився допомогти їм зібрати $2055w. На сьогодні ми зібрали $2053w.",  -- db:7835
[786836318] = "Ми готуємося до війни, $c. Ми взяли все, що могли, у силітидів та їхніх господарів в Ан’Кіражі. Щоб підготуватися до неї, ми збираємо всілякі матеріали. Я відповідаю за збір «Сліз Артаса». Хоча й не знаю, навіщо вони нам потрібні. Якщо мене запитати, я не хочу мати нічого спільного з тим божевільним, навіть якщо це лише квітка, названа на його честь.$B$BПроте я — дочка свого батька і солдат, тож роблю те, що мені кажуть. Наразі у нас є $2057w, а загалом потрібно зібрати $2058w.",  -- db:7837
[481922056] = "Мабуть, на цьому все. У нас є всі необхідні «Сльози Артаса». Можна спробувати розпитати навколо. У когось із цих людей напевно знайдеться щось, що їм ще потрібно зібрати для військових потреб.",  -- db:7838
[399301237] = "Я постійно отримую звіти про твої подвиги у боротьбі з Радою Безодні, $N.  Ти робиш там справді великі справи!$B$BПродовжуй у тому ж дусі, і ми зробимо так, щоб твої зусилля не були марними!",  -- db:7839
[820671949] = "Війна за Ан'Кірадж наближається, $c, і в рамках підготовки до неї Альянс попросив мою родину зібрати значну кількість легкої шкіри для військових потреб. З необхідних $2061w у нас наразі є $2060w. Ти виглядаєш як людина, яка могла б нам допомогти.",  -- db:7840
[594609976] = "Дуже мило з твого боку, що ти запитав, $c, але у нас вже є вся світла шкіра, яка нам потрібна. Хоча, можливо, хтось із тих, хто тут відповідає за збір, потребує твоєї допомоги?",  -- db:7842
[456664628] = "$G Пане: Пані;, так $g пане: пані;! Рядовий Портер з’явився на службу і готовий допомогти вам із збором середньої шкіри. Наближається війна за Ан'Кірадж, і ми маємо бути максимально готовими.$B$BЯк бачите, ми зібрали рівно $2063w одиниць середньої шкіри, а мені доручено зібрати загалом $2064w.",  -- db:7843
[422686133] = "А, е-е, так, $g, пане : пані;. Схоже, ми зібрали всю шкіру середньої щільності, яку Альянс вважає необхідною для війни. Мені сказали, що тут, можливо, є й інші, яким все ще потрібна ваша допомога у зборі матеріалів.",  -- db:7844
[109186079] = "Привіт, $c! З наближенням Війни за Ан’Кірадж наші приготування тут йдуть повним ходом. Я відповідаю за збір товстої шкіри. Сьогодні чудовий день для збору товстої шкіри, чи не так? У мене тут є запаси, і, схоже, наразі ми маємо $2069w. Наше магічне число — $2071w. Хочеш допомогти?",  -- db:7845
[596634212] = "Ого! Схоже, ми вже зібрали всю товсту шкіру, яка, на їхню думку, нам знадобиться. Це справді швидко минуло. Знаєш, тут, мабуть, є й інші, яким твоя допомога могла б стати в нагоді, якщо ти хочеш їм допомогти.",  -- db:7846
[543754970] = "Привіт, $c. Я збираю тут лляні бинти для військових потреб Ань-Кіраджа; ці зусилля стануть для нас усіх випробуванням, але зміцнять нас перед майбутньою війною. Можу запевнити вас, що будь-які бинти, які ви вирішите пожертвувати, будуть використані з користю для порятунку життів наших солдатів, коли настане час. Мені потрібно $2077w, і на даний момент мені вдалося зібрати $2076w. Чи допоможете ви нам?",  -- db:7847
[609654693] = "Дякую за запит, $c, але, як бачиш, у мене вже є всі лляні бинти, які Альянс вважає необхідними для підготовки до війни в Ан’Кіражі. Проте нехай це не завадить тобі допомогти з іншими зборами, що тут проводяться.",  -- db:7848
[268308818] = "Привіт, як ти сьогодні почуваєшся, $c? Сподіваюся, все гаразд. Можливо, ти дивуєшся, що тут відбувається. В Ан’Кіражі готується війна, до якої зараз ведеться підготовка. Ми та Орда готуємося до неї якнайкраще.$B$BЗ цією метою Альянс доручив мені контролювати збір шовкових бинтів тут. На сьогодні нам вдалося зібрати $2082w із необхідних $2083w. Чи не хочеш допомогти?",  -- db:7851
[323914533] = "Дуже мило з вашого боку, що ви запитали, але, схоже, ми вже зібрали всі шовкові бинти, які нам знадобляться. Хоча ви могли б розпитати навколо, чи, можливо, комусь ще потрібна допомога зі збором.",  -- db:7852
[978277519] = "$C, навіть нашим найвитривалішим воїнам і розвідникам знадобиться допомога лікарів у майбутній війні в Ан’Кіражі. А коли магічне зцілення буде недоступним, вони муситимуть покладатися на наші зусилля тут.$B$BНа сьогодні я зібрав $2088w бинтів із рунічної тканини з необхідних $2090w. Якщо ви готові допомогти, давайте обговоримо, як саме ви можете долучитися до справи.",  -- db:7853
[369119379] = "$C, завдяки зусиллям багатьох нам вдалося зібрати всі бинти з рунічної тканини, які, на думку Альянсу, знадобляться для майбутнього конфлікту. На твоєму місці я б попросив когось із присутніх перевірити, чи є у них ще завдання зі збору, які потрібно виконати.",  -- db:7854
[287558235] = "На жаль, $N, я надто зайнятий, щоб розмовляти. Як я вже згадував, мені потрібен час, щоб обміркувати ситуацію, що склалася.$B$Бажаю тобі удачі у подорожах. Гарного дня.",  -- db:7855
[385024369] = "Ммм, ммм, ммм. Ти відчуваєш цей запах?! Ось це і є справжня смакота, $c. Альбакор «Райдужна плавник» — це завжди те, що треба. Перед вами Слікі Гастроном, видатний знавець усього їстівного, особливо риби. З наближенням війни за Ан'Кірадж Альянс вирішив, що розумно буде залучити експерта для військових потреб, тож ось я тут, великий і впливовий.$B$B Схоже, нам знадобиться $2093w цієї риби, а у нас є запас, який наразі становить $2092w.",  -- db:7856
[886737691] = "Ну що ж, схоже, у нас є вся приготована білоперка, яку ми можемо як слід засолити й зберегти для майбутньої війни в Ан’Кіражі. Але все одно дякую, що запитав, $c. Якщо є бажання, поцікався в інших збирачів. Готовий побитися об заклад, що тут знайдеться ще хтось, кому знадобиться твоя допомога у зборі того, що їм потрібно.",  -- db:7857
[270548164] = "О, привіт, $c. Мабуть, Альянс попросив мене прийти сюди й вести облік усього цього смаженого м’яса, яке люди збирають через наближення катастрофи в Ан’Кіражі. Хіба це не звучить весело?$B$BУ будь-якому разі, думаю, тобі цікаво дізнатися, скільки у нас його є. Коли я востаннє рахував, у нас було $2098w із загальних $2099w смажених рапторів, які потрібні.",  -- db:7859
[783893301] = "Схоже, ти запізнився, $c. У нас є стільки запеченого раптора, скільки потрібно: вбитий, приготовлений і посолений. У будь-якому разі, здається, іншим тут не завадила б допомога. Тобі варто підійти до них і поцікавитися. А я піду подивлюся, чи дозволять мені вже йти додому.",  -- db:7860
[929340527] = "Належне харчування дозволить солдату вижити ще довго після того, як рани, отримані на полі бою, мали б $g його : її; добити, $c. Якщо ми маємо вистояти у майбутній війні за Ан’Кірадж, нам знадобляться всі запаси, які ми зможемо взяти з собою. Я збираю тут рибу «плямистий жовтохвіст», перш ніж її відправлять.$B$BНаразі у нас є $2101w, але нам потрібно зібрати загалом $2103w, щоб прогодувати всіх.",  -- db:7861
[604580185] = "Нам потрібна велика кількість мідних злитків, $c. У майбутній війні в Ан'Кіражі знадобиться багато металу на зброю, броню та інше. Мені сказали, що лише Орді потрібно зібрати $1998w мідних злитків. Наразі у нас є $2018w.",  -- db:7866
[629351935] = "$N, радий знову тебе бачити.$B$BНе забувай зосереджуватися на навчанні. Ти — наше майбутнє, і якщо ти збиєшся з курсу, наше майбутнє буде справді похмурим.",  -- db:7869
[968880165] = "Тром'ка, $c. Ти прийшов допомогти мені зі свинцевими злитками? Мені сказали, що мені знадобиться $2006w, щоб виготовити зброю та обладунки для майбутньої війни за Ан'Кірадж, але зараз у мене є лише $2005w. Ти принесеш мені ще!",  -- db:7870
[435648462] = "Ласкаво просимо до готелю «Falconwing Square Inn». Чи можу я приготувати для вас їжу або підготувати номер?",  -- db:7872
[998346026] = "Вітаю, $c.  Бригада «Айронфордж» дислокується тут, щоб стежити за Хайв’Зорою.  Друїди «Круга Сенаріона» відстежують пересування силітидів і очікують, що в цьому районі відбудеться щось серйозне.",  -- db:7874
[397941570] = "Капітан зараз зайнятий. Він вивчає карти підземних вуликів силітидів, які ми нещодавно отримали. Залишайтеся з нами, якщо хочете допомогти — він вийде будь-якої миті.",  -- db:7875
[720958556] = "Привіт, друже, ти, без сумніву, прийшов принести мені злитки мітрілу. У пустелі Сілітус, біля Ан’Кіраджа, назріває велика халепа. Ми разом з Альянсом цього разу кидаємо всі сили на боротьбу з цими комахами, тому тут і зібралися всі.$B$BОрда просить мене зібрати $2009w на військові потреби, але в мене є лише $2008w. То ти мені допоможеш, чи як?",  -- db:7876
[543077686] = "Привіт, юний $c. Ти прийшов принести мені партію квітів миру? Ми збираємо їх, щоб виготовляти зілля та еліксири для військових потреб Ань-Кіраджа. Хоча й трагічно, що ми змушені вести цю війну, наслідки будуть ще жахливішими, якщо ми не підготуємося належним чином.$B$BОрда доручила мені зібрати $2020w квітів миру, і наразі нам вдалося зібрати $2021w. Якщо у вас є така можливість, будь ласка, зберіть усе, що зможете, і принесіть мені сюди.",  -- db:7878
[843291973] = "Ти хочеш мені нашкодити, $r?",  -- db:7880
[436253035] = "Мій годинник вічний, смертний.",  -- db:7881
[887624544] = "Магія — це не лише таємничі жести... але я ж розмовляю з тим, хто це вже знає, чи не так?$B$BТи прийшов до мене, щоб навчитися, і навчишся... за умови, що будеш уважно слухати й робити так, як я скажу.  Таємниці демонів не для дурнів, і я теж не для них.",  -- db:7882
[322516480] = "<Андоров суворо дивиться на тебе.>$B$BЯкщо воно кровоточить, ми можемо його вбити.",  -- db:7883
[731568390] = "Ти шукаєш уламок скіпетра, наділений силою захисту Блакитного Польоту?$B$B<Здається, Азурегос посміхається.>",  -- db:7885
[124601097] = "Звісно, у мене немає того осколка. Це було б безглуздо. Я ходжу серед дикунів на цій проклятій землі! Не можу зробити й п’яти кроків, щоб якийсь божевільний орк чи людина не спробували встромити мені в тіло гострий патик. У будь-який момент ти цілком можеш розмовляти з моїм примарним духом.$B$BУ будь-якому разі... Я його сховав.$B$BНу ж бо... запитай мене, де.",  -- db:7886
[642740886] = "Вам неодмінно сподобається ця історія, $r. Розумієте, справа ось у чому. Як тільки Малігос доручив мені захищати осколок скіпетра, я відразу зрозумів, що на мене чекає вічна головна біль і страждання.$B$BВсе, чого я хочу, — це дослідити ці насичені магією береги й дізнатися, які артефакти могли зберегтися після Великого розколу. Знаєте, колись тут процвітала цивілізація Високородних! Не треба мені говорити, що тут мають бути якісь потужні магічні предмети, $r. Я це відчуваю!",  -- db:7887
[832978682] = "Як я вже казав, я зберігав той уламок скіпетра цілих п’ятсот років, і це приносило мені лише неприємності. Він привертав до себе всіляку увагу — ту, якої не хотілося. Я хочу, щоб мене залишили в спокої займатися своїми дослідженнями, а не наглядати за квитком до слави якогось самозваного героя. Тож… я віддав його рибі.",  -- db:7888
[374090589] = "Це була не просто якась риба, смертний. Це була рибка-гольян. І зовсім особлива рибка-гольян.",  -- db:7889
[742820884] = "Саме так!",  -- db:7890
[524158181] = "Геніально, я знаю... Його ніколи не знайдуть; але на випадок, якщо все-таки знайдуть, я наділив цю рибку деякими надзвичайними здібностями.",  -- db:7891
[24146359] = "Правильно. Ти уважно слухав! Ця рибка — справді жахлива істота, яку я сам створив. Коли я відпочиваю, мені подобається уявляти собі тих нещасних рибалок, які натрапили на цю рибку і були з’їдені цілком. Б’юся об заклад, вони були неабияк здивовані!$B$B<Азурегос сміється.>",  -- db:7892
[223300613] = "Геніїв часто неправильно розуміють, $r. А тепер щодо уламка скіпетра... Якщо ти хочеш отримати цей уламок і не бажаєш витрачати на його пошуки наступні десять тисяч років, тобі доведеться дуже уважно слухати.",  -- db:7893
[646793849] = "Два слова: арканітовий буй.",  -- db:7894
[460954887] = "Отже... Тобі треба створити арканітовий буй і розмістити його в океані. Моя рибка буде притягнута магічними випромінюваннями. Коли вона наблизиться до буя — БАМ! Він вибухне славним спалахом арканічної енергії, розкривши справжню форму рибки. Крім того, ви можете накликати на себе гнів Нептулона, а можете й ні. Я б сказав, шанси 50 на 50.",  -- db:7895
[639263785] = "Якби я не знав краще, то подумав би, що ти з мене глузуєш, смертний; але так, це в основному вірно. Ти можеш залишатися повністю одягненим.",  -- db:7896
[120982539] = "Віднеси цей обліковий журнал моєму старому знайомому в Танарісі. Його звати Нарайн Сутфансі — жахливий, жахливий екстрасенс, але неймовірний інженер! Він, мабуть, зможе розібратися в усьому цьому.$B$BНе треба мені дякувати, $N. Це найменше, що я міг зробити.$B$BГарного дня!",  -- db:7897
[368289642] = "Я сказав: «Гарного дня!»",  -- db:7898
[189533683] = "Крокуй обережно, смертний. Ти ступаєш там, де могутніші істоти зустріли свою долю.",  -- db:7899
[614505370] = "Тисячу років тому, коли закінчилася Війна Рухомих Пісків, троє наших побратимів пожертвували собою й утримали кіраджів усередині цих залів, поки Анахронос і Стагхельм запечатували Аhn'Qiraj.$B$BКожен із нас пообіцяв розшукати Мерітру, Арігоса та Каелестраза, якщо Стіна Скарабея колись впаде.$B$BІ вона впала... тож ми й прийшли.",  -- db:7900
[969259545] = "Хіба тобі не слід рятувати світ?",  -- db:7901
[587936881] = "<Нарайн притискає до чола нерозкритий конверт.>$B$BЩо це... Мммм... Вельвет!$B$BЯ правий?$B$BЯкщо ти тут, щоб знову навчитися ремеслу, скористайся тією книгою...$B$B<Нарайн вказує на «Пророцтво для чайників».>",  -- db:7902
[51507407] = "Тільки не кажи! Тсс! Ти прийшов через «Порохоносія»?!? Так... Так... Ні! Вибачте.$B$BЧим можу допомогти, $r?$B$BЯкщо ви прийшли, щоб знову навчитися ремеслу, скористайтеся тією книгою...$B$B<Нарайн вказує на «Пророцтво для чайників».>",  -- db:7902
[967281287] = "Нарайн Сутфенсі, до ваших послуг! Інженер на пенсії та майстер-віщун! Я можу передбачити ваше майбутнє ще до того, як воно станеться!$B$BЯкщо ви тут, щоб спробувати знову опанувати ремесло, скористайтеся тією книгою...$B$B<Нараїн вказує на книгу «Ворожіння для початківців».>",  -- db:7902
[261385437] = "Твій шлях не збігається з моїм. Тобі доведеться шукати навчання деінде, $c.",  -- db:7903
[323172408] = "Ти хочеш отримати додаткові вказівки щодо використання сили наару, $n?",  -- db:7904
[357281428] = "Хе-хе-хе, як справи, друже? Пеле’кеїкі вважає, що ти йому дуже допоможеш. Нам потрібна просто шалена кількість трави «вогняного цвіту», щоб як слід підготуватися до війни за Ан’Кірадж. Орда каже: «Пеле’кеїкі, дістань нам якнайшвидше $2051w вогняних пелюсток».$B$BПеле’кеїкі каже тобі, що в нього є лише $2050w вогняного цвіту, але ти ж скоро докладеш до цього ще, правда, друже?",  -- db:7905
[545143364] = "А, ось ти де. Мені сказали, що до мене прийде допомога, тож, будь ласка, слухай уважно. Ситуація така: мені доручили зібрати 2055w фіолетового лотоса для підготовки до майбутньої війни в Ан’Кіражі. На сьогодні ми маємо $2054w.$B$BФактично, виходити в поле й збирати квіти доведеться вам та таким, як ви. Мене тут потребують, щоб стежити за тим, як їх належним чином зберігають, і шукати нові, креативні способи їхнього застосування проти силітидів та всього іншого, що нас там чекає.",  -- db:7907
[287077598] = "Ти тут, щоб допомогти з важкою шкірою для військових потреб Ань-Кіраджа, так, $c? Добре, добре. Як бачиш, я зібрав $2066w, але загалом нам знадобиться $2067w. Це чимало роботи зі зняття шкур, друже, тож сподіваюся, що твій ніж гострий. Шкіра знадобиться для різних цілей — виготовлення військового спорядження та забезпечення нашого успіху.",  -- db:7909
[723620408] = "Тут мешкає невимовний жах, смертний.  К'Тун та його послідовники — це не просто образа природи, їхнє існування віщує руйнування Азерота, яким ми його знаємо.$B$BМерітра пожертвувала собою тисячу років тому разом із Каелестразом та Арігосом, бо вони теж це розуміли.  Ми тут через нашу клятву повернутися за ними, але ми тут ще й тому, що Ц'Туна треба зупинити!",  -- db:7911
[716725766] = "Лок'тар, $c, у мене є важлива інформація! На Ань-Кірадж насувається війна, і нам треба до неї підготуватися. Я тут збираю всю товсту шкіру, яку тільки можу дістати. Наразі у нас є $2070w, але Вождь доручив мені зібрати $2071w. Як бачиш, мені трохи не вистачає.",  -- db:7912
[447161703] = "Вітаю, $c. Сподіваюся, ти приніс добрі звістки щодо підготовки до війни за Ан’Кірадж. Мене особисто призначили відповідальним за збір міцної шкіри для Орди; це завдання, для виконання якого я вважаю себе якнайкраще підготовленим. Ніколи не варто недооцінювати корисність гострого ножа.$B$BЩодо міцної шкіри, то наразі ми маємо $2073w із необхідних $2074w.",  -- db:7914
[875982182] = "Мені здається, що на дні океану панує справжня тиша.",  -- db:7916
[205745270] = "Так приємно знову тебе бачити, $N! Я справді не знаю, як тобі віддячити за те, що ти передав це повідомлення моєму дорогому маленькому гному.$B$BХочеш послухати пісню? З нею подорож по бурхливому морю стане набагато легшою!",  -- db:7917
[385415544] = "А, $c, радий тебе бачити. Нам тут потрібна допомога зі збором припасів для підготовки до майбутньої війни в Ан’Кіражі. Мене попросили зібрати велику кількість польових аптечок, і головний компонент, який мені потрібен, — це вовняні бинти. У мене вже є деякі, а саме $2079w, але мені потрібно зібрати $2080w.",  -- db:7918
[623765597] = "Привіт, $c, добре, що ти з’явився. Дозволь мені висловитися лаконічно: ми збираємо припаси для ведення війни проти Ан’Кіраджа. Ми ж не хочемо, щоб жертв було більше, ніж необхідно, чи не так? Я відповідаю за координацію збору $2086w бинтів із магічного полотна. На сьогодні ми зібрали $2085w. Не хочеш допомогти?",  -- db:7920
[300557444] = "Мати-Земля забезпечує нас усім необхідним, але іноді $c потребує трохи додаткової допомоги, щоб вижити. Тому я збираю всі бинти з рунічної тканини, які тільки можна, готуючись до війни, що насувається на Ан'Кірадж. Наразі ми зібрали $2089w, а наша мета — $2090w.",  -- db:7923
[929494882] = "Дуже мило з вашого боку поцікавитися нашими потребами, $c. Однак, схоже, ми вже зібрали всі бинти з рунічної тканини, які, на нашу думку, знадобляться нам під час війни. Чи можу я попросити вас поцікавитися у інших колекціонерів і, за потреби, надати їм допомогу? Нехай предки бережуть вас.",  -- db:7924
[18687380] = "Гррр, чого тобі треба, $r? А, ти, мабуть, прийшов за стейками з пісного вовка до майбутньої війни за Ан’Кірадж. Так, ти правильно почув, я їх збираю, а що з того? У тебе є для мене свіжа партія? Мені потрібно лише $2096w, а, схоже, зараз у нас є $2095w.",  -- db:7925
[53406622] = "Так, чувак, я збираю рибку-рибку для Орди. Вони готуються до великої війни в пустелі біля Ан’Кіраджа і просять мене дістати їм $2103w плямистого жовтохвоста. Але зараз у нас є лише $2102w. Ти тут, щоб допомогти?",  -- db:7927
[846962400] = "Вітаю, $c. Приємно бачити, що ти зацікавився участю у військових зусиллях. Наші збирачі організовують накопичення різних запасів товарів, щоб ми були готові, коли настане час.$B$BЯ відповідаю за закупівлю $2106w запеченого лосося, який потрібно запасти для тих, хто бере участь у боях в Ан'Кіражі. За моїми останніми підрахунками, ми зібрали $2105w.",  -- db:7929
[546954850] = "Добре, що ти запитав, $c, але у нас уже є весь запечений лосось, який нам знадобиться під час війни. Можливо, ти будеш такий люб’язний і запитаєш у інших збирачів тут; у них напевно знайдеться щось, у чому тобі зможеш їм допомогти.",  -- db:7930
[867374053] = "Зараз настав час, коли рік тільки-но почався, а місяць сяє яскраво.$B$BЦе наш час... коли прокидаються древні.",  -- db:7933
[9190028] = "У давні часи ми жили заради полювання. Ми полювали заради слави, заради честі...$B$BЧи так вже все змінилося зараз?",  -- db:7935
[39773635] = "Твої спроби вивчити драконівську мову марні, смертний. І навіщо тобі взагалі хочеться навчитися розмовляти цією стародавньою мовою? Це справді незрозуміло...",  -- db:7937
[214109088] = "Лок'тар, $r. Я — генерал Зог, посол Орди. Я тут, щоб тримати вас у курсі того, як просуваються справи могутньої Орди у її зусиллях, спрямованих на війну за Ан'Кірадж. Що саме ви хочете дізнатися?",  -- db:7942
[827768984] = "Скільки, кажете, металевих злитків? Станом на моє останнє оновлення щодо ситуації, ось що мені відомо. Орда зібрала 2018w мідних злитків із необхідних 1998w, 2005w олов'яних злитків із 2006w, а з 2009w мітрілових злитків, які потрібно зібрати, зібрано 2008w.",  -- db:7944
[448348274] = "З останніх відомостей, що у Орди накопичилося 2021w з 2020w «квітів миру», 2050w з 2051w «вогняних квітів» та 2054w з 2055w фіолетових лотосів.",  -- db:7945
[656327697] = "Шкіри? Так, я щойно отримав інформацію з цього приводу. Схоже, що з необхідних 2067w важкої шкіри Орда зібрала 2066w. Також зібрано 2070w з 2071w товстої шкіри та 2073w з 2074w міцної шкіри.",  -- db:7946
[784386574] = "Орда накопичує величезну кількість бинтів. Наразі зібрано $2079w з $2080w вовняних бинтів. Виготовлено $2085w з $2086w бинтів з магічного полотна. А також зібрано $2089w з $2090w бинтів з рунічної тканини.",  -- db:7947
[533070724] = "Хочете дізнатися про збір пайків? Добре. З того, що мені сказали, Орда підготувала 2095 w з 2096 w нежирних стейків з вовка. Ми також запасли 2102 w з 2103 w плямистого жовтохвоста та 2105 w з 2106 w запеченого лосося, що було потрібно.",  -- db:7948
[85764161] = "Вітаю, $r $c. Я — командир Стронгхаммер, посол, який представляє тут Альянс. Якщо у вас є якісь запитання щодо стану збору коштів Альянсу на військові потреби в Ань-Кіражі, $g lad : lass;, не соромтеся їх задавати.",  -- db:7949
[628306649] = "Дуже хороше запитання, $c. З того, що я чув востаннє, Альянсу вдалося виплавити $1997w з $1998w мідних злитків, $2002w з $2003w залізних злитків та $2011w з $2012w торієвих злитків, необхідних для ведення війни.",  -- db:7951
[547950124] = "Дайте-но подивитися, дайте-но подивитися. Ці цифри у мене десь тут були. А, так, ось вони! На сьогодні Альянс зібрав 2047w «задушливого водоростя» з необхідних 2048w. Тут також зазначено, що ми маємо 2053w фіолетового лотоса з необхідних 2055w та 2057w «сліз Артаса» з необхідних 2058w.",  -- db:7952
[771642357] = "Цікаво, що ти про це запитав... Я щойно отримав оновлену інформацію з цього приводу. Наразі Альянс зібрав 2060w з 2061w шкір тонкої товщини, 2063w з 2064w шкір середньої товщини та 2069w з 2071w шкір товстої товщини.",  -- db:7953
[889832762] = "Бинти, кажете? Так, ну, якщо пам'ять не підводить, з того, що мені казали минулого разу, здається, Альянс виготовив $2076w з $2077w лляних бинтів, $2082w з $2083w шовкових бинтів та $2088w з $2090w рунічних бинтів.",  -- db:7954
[994057813] = "Це нагадало мені, що незабаром мені доведеться щось поїсти. Щодо того, що там готує Альянс, мені повідомили, що з 2093w радужної альбакори було упаковано 2092w. Крім того, з 2099 вагових одиниць смаженого раптора було підготовлено 2098 вагових одиниць, а з 2103 вагових одиниць плямистого жовтохвоста — 2101 вагова одиниця; зараз вони знаходяться в холодильних камерах і чекають на транспортування до фортеці Сенаріон у Сілітусі.",  -- db:7955
[678543856] = "Зірки цього часу ведуть нас новими шляхами, стаючи маяками надії та сили для майбутніх поколінь.",  -- db:7956
[407268278] = "Тепер все вже вирішено, залишилося тільки плакати. Усі військові матеріали транспортуються до Цитаделі Сенаріону в Сілітусі й прибудуть туди менш ніж за $2113w днів. Незабаром скіпетр буде зібрано, і війна нарешті розпочнеться.",  -- db:7958
[647499925] = "Ура, поїхали! Усі вже зібрали все необхідне, і саме зараз це доставляється повітряним транспортом на цепеліні до Сілітуса. Останні вантажі мають прибути туди менш ніж за $2113w днів. Як тільки все буде на місці, а скіпетр зібрано, можна буде розпочати війну проти тих брудних комах. Як то кажуть: «Відправляйте!»",  -- db:7960
[400633082] = "Привіт, $c. З того, що мені розповіли, все вже зібрано, і всі військові матеріали саме зараз доставляються до Сілітуса. Все має прибути туди менш ніж за $2113w днів. Як тільки це буде зроблено, і пролунає удар у гонг Скіпетром Рухомих Пісків, війна по-справжньому розпочнеться.",  -- db:7962
[961082890] = "Ось і все, обидві сторони зібрали все необхідне. Зараз все це транспортується до Сілітуса і має прибути туди менш ніж за $2113w днів. Як тільки це відбудеться і хтось пролунає гонг на П'єдесталі Скарабея за допомогою Скіпетра Рухомих Пісків, війна розпочнеться!",  -- db:7964
[618429321] = "Ласкаво просимо до Буті-Бей, друже. Сподіваюся, твоє перебування в моєму місті буде приємним і спокійним — з акцентом саме на останньому.  У нас є чимало випивки, якщо ти спраглий, і чимало охоронців, якщо ти неспокійний.$B$BОтже... чим цей скромний слуга картелю «Стімвідл» може тобі допомогти?  А ще краще — чим ти можеш допомогти мені, га?",  -- db:7965
[680976303] = "Все готово, юний $c. У цей самий момент і Орда, і Альянс займаються перевезенням усіх останніх військових вантажів до Сілітуса, поблизу Цитаделі Сенаріону, і це має завершитися менш ніж за $2113w днів. Після цього можна буде пролунати гонг біля воріт Ан'Кіраджа, і війна розпочнеться.",  -- db:7967
[844532042] = "Ти з’явився на службу, $c? Усі військові матеріали як для Орди, так і для Альянсу вже готові й саме зараз відправляються до Сілітуса. Усе це має прибути менш ніж за $2113w днів. Сподіваюся, хтось уже знайшов усі частини Скіпетра Рухомих Пісків і зібрав їх воєдино.",  -- db:7969
[141899283] = "Як я розумію, люба, все вже зібрано, а остаточний комплект спорядження зараз комплектується та відправляється до Цитаделі Сенаріону. Остання партія має прибути менш ніж за $2113w днів. Як тільки наше спорядження та війська будуть на місці, носій Скіпетра Рухомих Пісків зможе вдарити в гонг біля Ан'Кіраджа, щоб відкрити ворота. Тоді й розпочнеться війна.",  -- db:7971
[993788870] = "А-тен-хат! Усі військові матеріали з Ан'Кіраджа перераховані та зараз транспортуються до Цитаделі Сенаріону, $g пане : пані! Мені повідомили, що остання партія має прибути менш ніж за $2113w днів. Як тільки це буде зроблено, і хтось пролунає тим гонгом, щоб відкрити ворота, я гарантую, що ми влаштуємо цим комахам справжню битву!",  -- db:7981
[474360393] = "Привіт, $c! Схоже, Орда зібрала останні свої речі, і саме зараз їхні та наші речі відправляють до Сілітуса. Мені сказали, що все прибуде туди менш ніж за $2113w днів, і тоді хтось зможе вдарити у великий гонг біля воріт Ан'Кіраджа, щоб розпочати війну.",  -- db:7984
[730581555] = "Саме в цю мить, $c, усі військові матеріали транспортуються до Сілітуса. Судячи з усього, все це має прибути менш ніж за $2113w днів. Після цього $g герой : героїня; повинен буде прийти й пролунати гонг на Подіумі Скарабея. Тоді війна розпочнеться по-справжньому.",  -- db:7988
[615020965] = "Схоже, що останні партії товарів, які ми зібрали, будуть відправлені до Сілітуса протягом наступних $2113w днів. А коли це буде зроблено, хтось повинен буде підійти й ударити в гонг на П'єдесталі Скарабея, що біля Ань-Кіраджа, щоб відкрити ворота. Ось тоді наші бинти стануть у нагоді.",  -- db:7991
[701124091] = "Все зібрано, $c. Усе транспортується до Сілітуса для остаточної підготовки і має прибути протягом $2113w днів. Усі наші об'єднані сили чекають на $g героя чи героїню, які завершать возз'єднання Скіпетра Рухомих Пісків, пролунають у гонг і розпочнуть війну за Ан'Кірадж.",  -- db:7994
[99799522] = "Уся риба та все інше вже прямує до Сілітуса і має прибути туди менш ніж за $2113w днів. Після цього комусь доведеться пролунати в гонг за допомогою «Скіпетра рухомих пісків», щоб розпочати війну.",  -- db:7997
[799865488] = "Тут ходять чутки, що ми вже зібрали все необхідне. Тепер все залежить від того, чи встигне Орда зібрати свої речі. Як тільки вони це зроблять, ми всі зможемо відправити наші товари до Сілітуса, і війна зможе розпочатися.",  -- db:7998
[824508532] = "Усі зібрані нами продовольчі запаси та військові матеріали вже прямують до Сілітуса. Вони мають прибути туди менш ніж за $2113w днів. Хтось мені сказав, що коли все це буде зібрано поблизу Цитаделі Сенаріону, хтось повинен буде пролунати гонг на Подіумі Скарабея, щоб відкрити ворота до Ан'Кіраджа та розпочати війну.",  -- db:8000
[782562500] = "Вітаю, $r. Військові матеріали поступово відправляються і мають прибути до Цитаделі Сенаріону протягом $2113w днів. Залишається лише сподіватися, що коли він туди прибуде, хтось, зібравши Скіпетр Рухомих Пісків, вийде вперед, щоб пролунати гонг і відкрити ворота.",  -- db:8003
[26369501] = "Несподівано, що ви всі здатні на таку організованість. І Альянс, і Орда завершили підготовку до війни за Ан’Кірадж. У цей самий момент матеріальні засоби доставляються до Сілітуса і мають прибути протягом $2113w днів. Тоді той, хто збере Скіпетр Рухомих Пісків, повинен буде вдарити в гонг на Подіумі Скарабея та відкрити ворота Ан'Кіраджа. Саме тоді війна по-справжньому розпочнеться!",  -- db:8006
[180749688] = "Як і слід було очікувати, Орда завершила всі свої приготування значно раніше, ніж ви та ваш так званий Альянс. Ви всі затримуєте нас, оскільки ми не можемо вжити остаточних заходів для початку війни, доки ви не виконаєте обіцяні обов’язки.$B$BА тепер йдіть і робіть свою справу, $r.",  -- db:8007
[297930289] = "Усе зібрано і зараз відправляється до Сілітуса, $c. Воно має прибути туди протягом $2113w днів. Мені залишається лише сподіватися, що після того, як пролунає гонг і відкриються ворота, наші зусилля тут дадуть результат і врятують багато життів.",  -- db:8037
[828093674] = "Схоже, залишилося всього лише $2113w днів на риболовлю, поки всі ці військові припаси не відправлять у пустелю Сілітус, чувак. Потім вони все підготують, і хтось повинен буде пролунати в гонг на південь від Цитаделі Сенаріону, щоб відкрити ворота й розпочати війну.",  -- db:8049
[618434734] = "Якщо ти чув, що всі колекції Орди та Альянсу вже зібрано, то ти почув правильно, $c. Усі військові припаси, які ми зібрали та підготували, зараз доставляються до Цитаделі Сенаріону в Сілітусі, і до прибуття останньої партії залишилося менше ніж $2113w днів. Після цього, гадаю, нам залишиться лише чекати й спостерігати, хто ж складе той скіпетр, щоб пролунав гонг, який відкриє ворота до Ан’Кіраджа та сповістить про початок війни.",  -- db:8052
[376061097] = "Ми з великою гордістю служимо Тролу. Ми вирушимо куди завгодно, аби перемогти ворога.",  -- db:8059
[912388721] = "Ти встиг якраз вчасно, $c.  Ти відчуваєш, як під тобою тремтить земля?$B$BЩось наближається з боку вулика.  Стань поруч із солдатами, $N.  Я розраховую на тебе!",  -- db:8060
[195240822] = "Сілітиди не можуть зрівнятися з синами та доньками Оргримара. Незабаром від них залишаться лише розчавлені кінцівки та крила під нашими ногами, $N.",  -- db:8061
[227866091] = "Щоб перебувати так близько до силітіда й залишатися непоміченим, потрібно трохи потренуватися. Я не раджу пробувати це, якщо можна цього уникнути.",  -- db:8063
[992726851] = "Не зрозумійте мене неправильно, я б волів не сидіти день у день у тунелі, заповненому силітидами, але якщо переховування тут і спостереження за рухами цих істот допоможе нам виграти війну, то я буду це робити стільки, скільки знадобиться.",  -- db:8064
[180426324] = "Незабаром ми позбавимо Азерот від огидної присутності силітидів. Їхній руйнівний потенціал набагато більший, ніж те, що ти бачив на власні очі, $N. За їхніми діями стоять ще більші й темніші сили.",  -- db:8065
[768980861] = "Печатка похвали Альянсу вручається $g герою чи героїні, які виходять за межі своїх обов’язків на благо Альянсу.  У всіх великих містах знаходяться різні офіцери з нагородження фракцій Альянсу; зверніться до того, у кого ви хочете підвищити свою репутацію, і передайте йому необхідну кількість знаків!$B$BДо речі, під час військових дій тут, якщо ви бажаєте отримати матеріальну винагороду за свої печатки замість репутації, зверніться до фельдмаршала Сноуфолла.",  -- db:8070
[848172853] = "Ми об’єднані спільною справою, $r. Стародавнє зло загрожує знищити все життя на Калімдорі та поглинути світ своєю розпустою... Воно ненавидить усе, що породили великі Творці: вічні Титани.$B$BМи — перша й остання лінія оборони проти армій К'Туна. Якщо ми не повстанемо й не завдамо удару по ворогові, він неодмінно знищить нас.$B$BВійна потребує вас!",  -- db:8071
[664044744] = "Печатка за заслуги перед Ордою вручається $g герою чи героїні, які виходять за межі своїх обов’язків перед Ордою.  У всіх великих містах знаходяться різні офіцери з нагородження фракцій Орди; зверніться до того, у кого ви хочете підвищити свою репутацію, і передайте йому потрібну кількість печаток!$B$BДо речі, під час військових дій тут, якщо ви волієте отримати матеріальну винагороду за свої печатки замість репутації, зверніться до воєначальника Горчука.",  -- db:8073
[459265492] = "На шиї цього оленя висить бирка з логотипом «Smokywood Pastures» та ім’ям — «Метцен».$B$BMетцен дивиться на вас сумними, розгубленими очима.  Складається враження, ніби оленя паралізувала якась невидима сила.",  -- db:8076
[371479556] = "Очі Метцена спалахують оленячою радістю, коли ти посипаєш його пилом.  Він похитує перед тобою рогами й випускає глибокий подих, що звучить наче полегшення.$B$BНавколо тебе починає наростати магічна енергія.  Схоже, ось-ось щось має статися!",  -- db:8077
[628180416] = "Навіть якби вам якимось чином вдалося звільнити нас, не перемогши К'Туна, ми б зосередили всі свої сили на тому, щоб ця потвора була вигнана назад у пекло, звідки вона прийшла, — ЗА БУДЬ-ЯКУ ЦІНУ.",  -- db:8078
[80996291] = "Герої Роду? Ц’Тун має бути вигнаний! Ми можемо тобі допомогти, смертний!",  -- db:8079
[550405716] = "Я є свідком дива, яке розгортається на моїх очах! За тисячу років полону я не бачив, щоб у ці зали потрапив хоч один ЖИВИЙ екземпляр — окрім тих огидних кіраджі та силітидів.",  -- db:8080
[912136170] = "Не забудьте залишитися, щоб подивитися наступний феєрверк! Починаючи з 18:00, вони відбуватимуться щогодини!",  -- db:8081
[750367989] = "Не знаю, що вони туди додають, але п’ється це як мед!",  -- db:8081
[988624407] = "Після феєрверку нам подадуть келихи, щоб ми могли підняти тост!",  -- db:8081
[39725868] = "Радий бачити тебе, друже!",  -- db:8081
[239853253] = "Вітаю, $c. Я — фельдмаршал Сноуфолл, командувач військових операцій у цьому регіоні. Нас чекає нелегкий шлях, $g хлопче : дівчино;, тож якщо зможеш допомогти, будь ласка, зроби це. І не соромся задавати питання.",  -- db:8082
[34564446] = "Ми це зробили, $g хлопче : дівчино;! Альянс і Орда завершили збір усього, що, на нашу думку, знадобиться для війни за Ан’Кірадж. Зараз останні вантажі доставляють до Цитаделі Сенаріону в Сілітусі, і все це прибуде протягом $2113w днів. Після цього якомусь відважному $g герою : героїні; доведеться вдарити в Гонг Скарабея за допомогою Скіпетра Рухомих Пісків, щоб відкрити ворота Ань-Кіраджа. Коли ці ворота відчиняться, війна розпочнеться!",  -- db:8084
[848280763] = "Ти вже чув цю чудову новину, $c? Альянс завершив збір усіх військових ресурсів! Тепер нам залишається лише дочекатися, поки Орда завершить свій збір. Як тільки це станеться, ми почнемо відправляти всі військові матеріали до Сілітуса, і незабаром після цього розпочнеться війна за Ан’Кірадж.",  -- db:8085
[60631634] = "Гарне запитання, $c. Згідно з останньою інформацією, нам вдалося зібрати мідні бруски на суму $1997w із необхідних $1998w. Крім того, мені повідомили, що ми маємо $2002w залізних брусків із $2003w, а також $2011w із $2012w необхідних торієвих брусків.",  -- db:8087
[818977839] = "Трави, трави, хм, дайте-но подивитися. Ага, ось воно. На сьогодні ми зібрали 2047w з 2048w «странглкелпа», 2053w з 2055w «фіолетових лотосів» та 2057w з 2058w «сліз Артаса», які потрібні.",  -- db:8088
[486391796] = "Щойно я отримав оновлену інформацію з цього приводу. Схоже, що з необхідних 2061w легкої шкіри у нас є 2060w. Щодо інших видів шкіри, у звіті зазначено, що з необхідних 2064 w середньої шкіри ми зібрали 2063 w, а з квоти на товсту шкіру в розмірі 2071 w — 2069 w.",  -- db:8089
[774219032] = "Збір бинтів проходить згідно з графіком. Що стосується лляних бинтів, то ми зібрали 2076w з 2077w. Шовкові бинти набрали 2082w з 2083w, а з необхідних рунічних бинтів у нас є 2088w з 2090w.",  -- db:8090
[800840134] = "Що стосується готової продукції, то, судячи з усього, нам вдалося зібрати та помістити на зберігання 2092w «райдужної» альбакори з загального обсягу 2093w, що було заплановано. Крім того, наразі у холодильних камерах ми маємо 2098 w із 2099 w смаженого раптора та 2101 w із 2103 w плямистого жовтохвоста.",  -- db:8091
[439526076] = "Тром'ка, Орда $C, тримайте голову високо! Я — воєначальник Горчук, командувач військових операцій Орди. Попереду нас чекають важкі часи, але ми, як завжди, переможемо.$B$BЯкщо у вас є питання, не соромтеся їх задавати.",  -- db:8092
[127039825] = "Час війни вже майже настав, $c! І Орда, і Альянс завершили свої приготування. У цей самий момент усі наші військові матеріали доставляються до Сілітуса. Я очікую, що все це прибуде протягом $2113w днів. Коли там усе буде зібрано, той, хто виконає важке завдання зі складання Скіпетра Рухомих Пісків, вдарить ним по Гонгу Скарабея й відкриє ворота до Ан’Кіраджа. Тоді розпочнеться битва, якої не бачили вже віки!$B$BLok’tar Ogar!",  -- db:8094
[707653679] = "З необхідних нам мідних злитків на суму $1998w у нас є $2018w. Щодо олов’яних злитків, то зібрано $2005w із необхідних $2006w. Крім того, для цієї справи було переплавлено $2008w з $2009w злитків мітрілу.",  -- db:8096
[64566187] = "Я щойно отримав інформацію з цього приводу. Наразі у нас є 2021w з 2020w трави «peacebloom», 2050w з 2051w трави «firebloom» та 2054w з 2055w трави «purple lotus», які були замовлені.",  -- db:8097
[310856966] = "Дайте мені хвилинку; тут багато цифр, які треба запам’ятати. Схоже, ми зібрали $2066w з $2067w важкої шкіри. Крім того, у нас є $2070w з $2071w товстої шкіри та $2073w з $2074w міцної шкіри на складі.",  -- db:8098
[648974924] = "Бинти? А що, ти збираєшся прожити так довго, що вони тобі знадобляться? Ха! Гаразд, $r, я тобі розповім. З необхідних вовняних бинтів на суму $2080w ми зібрали $2079w. Також на сьогоднішній день ми отримали $2085w з $2086w магічних тканинних бинтів та $2089w з $2090w рунічних бинтів, про які просили.",  -- db:8099
[208357431] = "Їжа — ось тема, в яку я можу вчепитися зубами! Мені сказали, що у нас є 2095w з 2096w нежирних вовчих стейків, 2102w з 2103w плямистої риби «жовта хвоста» та 2105w з 2106w запеченого лосося, які зберігаються на льоду.",  -- db:8100
[610421806] = "Радий бачити вас, $c. Сподіваюся, ви прийшли, щоб дізнатися про військові приготування в Ан’Кіражі. Нам знадобиться чимала допомога.$B$BЦі приготування — це спільні зусилля Альянсу та Орди з метою підготовки до майбутньої війни проти силітидів та їхніх повелителів в Ан’Кіражі. У Військовому кварталі Айронфорджа ми збираємо всілякі матеріали для виготовлення військового спорядження, і саме у цих завданнях зі збору ресурсів нам потрібна ваша допомога.$B$BЧи можу я переконати вас поговорити з нашим командиром про те, щоб долучитися до справи?",  -- db:8101
[212887396] = "Вітаю, $c. Сподіваюся, ти прийшов, щоб дізнатися про військові дії в Ан’Кіражі. Нам знадобиться чимала допомога.$B$BЦі військові дії — це спільні зусилля Орди та Альянсу з підготовки до майбутньої війни проти силітидів та їхніх повелителів в Ан’Кіражі. У Долині Духів в Оргримарі ми збираємо величезну кількість ресурсів для виготовлення військового спорядження, і саме у цих завданнях із збирання ресурсів нам потрібна ваша допомога.$B$BЧи можу я переконати вас поговорити з нашим командиром про те, щоб ви нам допомогли?",  -- db:8105
[883129744] = "Вітаю, $c. Я — Леорен, керівник стайні фортеці Сенаріон.",  -- db:8108
[148255352] = "Тут лежить купа загорнутих подарунків.",  -- db:8109
[87019776] = "На етикетці цього подарунка написано: «Для осіб віком від 40 років».",  -- db:8110
[669885528] = "Світ у боргу перед тобою та твоїми союзниками, $N.",  -- db:8111
[103554161] = "Наша свобода не мала б жодного сенсу, якби К'Тун вижив. Ти — справжній захисник пророцтва.",  -- db:8112
[791756663] = "Усі дізнаються про те, що сталося тут, у цьому проклятому храмі, герою. Про це напишуть у підручниках історії — ці оповіді стануть легендами, які розповідатимуть від Азерота аж до найвіддаленіших куточків самого Нетера!",  -- db:8113
[133367414] = "Тепер, коли війна в розпалі, у нас не бракує боєздатних бійців з Орди та Альянсу.$B$BЯкби тільки нам вдалося не дати їм накинутися один на одного...",  -- db:8114
[74528175] = "На етикетці цього подарунка написано: «Для осіб віком від 20 років».",  -- db:8115
[452552584] = "На етикетці цього подарунка написано: «Для дітей віком від 10 років».",  -- db:8116
[262365629] = "Щоденник Джандіс Баров наповнений тирадами та мареннями про неживих. Ближче до кінця книги міститься те, що схоже на кравецьку викрійку для пошиття якоїсь сумки. Ваші знання з кравецької справи недостатні, щоб розшифрувати цю викрійку.",  -- db:8120
[454772949] = "Лише ті, хто довів, що не вороже налаштований до «Тімбермоу», можуть пройти через Фортецю, не побоюючись нападу. Чи доклав ти зусиль, щоб заслужити нашу довіру, чужинець?",  -- db:8123
[774210780] = "Чого ти шукаєш, $c?",  -- db:8124
[709633968] = "Новинка цього року: PX-238 Winter Wondervolt.  Підходьте сміливіше, не соромтеся!$B$BІ не забудьте підписати ці бланки, перш ніж спробувати — ми ще виправляємо кілька недоліків у цій штуці...",  -- db:8125
[344473288] = "Вітаю, $c — я — офіцер з нагородження, що діє від імені Дарнассуса.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки нагород Альянсу.$B$BI приймаю печатки в різних кількостях, але найвигіднішим для вас варіантом обміну буде здача набору з десяти печаток одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від Дарнассуса за свій обов’язок і службу.$B",  -- db:8126
[38828633] = "Вітаю, $c — я — офіцер з нагородження, що діє від імені Дарнассуса.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки нагород Альянсу.$B$BЯ приймаю печатки в різних кількостях, але найвигіднішим для вас варіантом обміну буде здача набору з десяти штук одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від Дарнассуса за свій обов’язок і службу.$B$B",  -- db:8126
[612850660] = "Вітаю, $c — я — офіцер з нагородження, що діє від імені племені Темних Списів.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки похвали Орди.$B$BЯ приймаю печатки в різних кількостях, але найвигідніше для вас — здати одразу набір із десяти штук.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від племені Темних Списів за свій обов’язок і службу.$B",  -- db:8127
[398361745] = "Вітаю, $c — я — офіцер з нагородження, який діє від імені вигнанців Гномерегана.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки похвали Альянсу.$B$BЯ приймаю печатки в різних кількостях, але найвигідніше для вас — здати одразу комплект із десяти штук.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від «Вигнанців Гномерегана» за вашу відданість та службу.$B",  -- db:8128
[981821264] = "Вітаю, $c — я офіцер з нагородження, який діє від імені Айронфорджа.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки похвали Альянсу.$B$BЯ приймаю печатки в різних кількостях, але найвигіднішим для вас варіантом обміну буде здача набору з десяти печаток одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від Айронфорджа за свій обов’язок і службу.$B",  -- db:8129
[684684521] = "Вітаю, $c — я офіцер з нагородження, що діє від імені Айронфорджа.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки похвали Альянсу.$B$BЯ приймаю печатки в різних кількостях, але найвигіднішим для вас варіантом обміну буде здача набору з десяти штук одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від Айронфорджа за свій обов’язок і службу.",  -- db:8129
[384055237] = "Вітаю, $c — я офіцер з нагородження, що діє від імені Штормовію.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки похвали Альянсу.$B$BI приймаю печатки в різних кількостях, але найвигіднішим для вас варіантом обміну буде здача набору з десяти печаток одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від Штормовію за свій обов’язок і службу.$B",  -- db:8130
