[333541391] = "Вітаю, $c — я — офіцер з нагородження, що діє від імені Підміста.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки нагород Орди.$B$BI приймаю печатки в різних кількостях, але найвигіднішим для вас обміном буде здача набору з десяти штук одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від Підміста за свій обов’язок і службу.$B",  -- db:8133
[197630101] = "О 18:00 з найвищого скелястого берега розпочнеться феєрверк!",  -- db:8134
[522837193] = "Бочки наповнені міцним пивом!  Пий, друже, і святкуй!",  -- db:8134
[776300831] = "Я чув, що після феєрверку на столи подадуть келихи.  Тоді ми піднімемо чудові тости!",  -- db:8134
[682080268] = "Вітаємо, $c!  Ласкаво просимо на свято!",  -- db:8134
[877839015] = "Ха! Цей таурен хоче поцілунку!",  -- db:8138
[604824665] = "Щасливого Зимового свята тобі, друже!",  -- db:8139
[631492479] = "З наступаючими святами та миру вам!",  -- db:8139
[516193566] = "Бажаю тобі щасливих свят, друже!",  -- db:8139
[30602699] = "Ах, омела...",  -- db:8139
[804968816] = "У нас тут просто чудова погода, чи не так?",  -- db:8143
[801007238] = "Чому ж так виходить, що гірохронотом ніколи не трапляється під рукою саме тоді, коли він потрібен?",  -- db:8143
[434816254] = "Останнє слово буде за мною... вони ще побачать! О, привіт, $c, я тебе не помітив.",  -- db:8143
[840949136] = "Винахід, мій дорогий $c, — це два відсотки натхнення в пляшці, чотири відсотки сонячного світла, шість відсотків ймовірності того, що гроза розійдеться до середини дня, і дев’яносто три відсотки Румплснікера.$B$BХвилинку, а це ж у сумі сто? Мої нотатки десь тут мають бути.",  -- db:8143
[960021644] = "Ми мусимо з'ясувати, чим кіраджі годують цих монстрів! Тільки погляньте, які вони величезні!",  -- db:8145
[365338343] = "Вивчення та розуміння «Колоса» дасть нам необхідну перевагу над Кіраджі.",  -- db:8146
[158824144] = "Секрети, що лежать в основі потужності «Колоса», можуть стати джерелом найрізноманітніших наукових інновацій!",  -- db:8147
[645373946] = "Старійшина Грейвборн проводить час поблизу Брілла в Полях Тірісфал.",  -- db:8148
[665085379] = "Старійшину Мунстрайка можна знайти у Шоломансі, що у Західних Землях Чуми.",  -- db:8149
[523444705] = "Старійшину Даркора можна знайти в Андерсіті.",  -- db:8150
[803505998] = "Старійшина Обсідіан блукає поблизу Гробниці в Сріблястососновому лісі.",  -- db:8152
[73943194] = "Старійшину Сноукроуна можна знайти в Каплиці Надії Світла у Східних Землях Чуми.",  -- db:8153
[824909805] = "Старійшина Хайпік пильнує за Гінтерлендсом з пагорба, розташованого поблизу його центру.",  -- db:8154
[583218784] = "Старійшина Віндрун мешкає у Вежі Королівської гвардії у Східних Землях Чуми.",  -- db:8155
[763889758] = "Старійшину Фарвіспера можна зустріти, коли він блукає вулицями Стратхолма.",  -- db:8156
[962066193] = "Старійшина Айронбенд мешкає в печері Блекчар у Пекучому ущелині.",  -- db:8157
[100837355] = "Старійшина Голдвелл мешкає у селі Харанос у Дун-Морозі.",  -- db:8158
[370671953] = "Старійшину Бронзобородого можна знайти в родовому маєтку Бронзобородих — Айронфорджі.",  -- db:8162
[350807059] = "Старійшину Сільвервейна можна знайти поблизу Телсамара в Лох-Модані.",  -- db:8163
[583888306] = "Верховна Жриця не змогла покинути Дарнассус. Фандрал перебуває у вкрай поганому настрої.",  -- db:8164
[179952785] = "Тиранде передає свої молитви. Мати-Місяць благословляє нас усіх.",  -- db:8164
[422025817] = "Старійшина Морндіп проводить час у «Кільці Закону» в Глибинах Чорної Скелі.",  -- db:8166
[684935223] = "Старійшина Стоунфорт вирушив у підземелля Чорнокам’яної Вежі.",  -- db:8167
[936884491] = "Старійшина Рамблерок проводить свої дні в печері на вершині Скелі Дредмаул у Палаючих степах.",  -- db:8168
[51166770] = "Наскільки мені відомо, старійшина Старсонґ перебував у Затонулому храмі на Болоті Скорботи.",  -- db:8169
[577534346] = "Старійшина Стормброу, найімовірніше, перебуває в селі Голдшир у Лісі Елвін.",  -- db:8170
[448994902] = "Вінтерхуф? Я чув, що він розкошує в Буті-Бей.",  -- db:8171
[762225134] = "Старійшина Скайчейзер споглядає на Вестфолл з вершини пагорба Сентинел.",  -- db:8172
[681996615] = "Старійшину Доунстрайдера можна знайти в «Полум’яному гребені» на Палаючих степах.",  -- db:8173
[97947129] = "Старійшину Хаммершоута можна знайти в межах стін Штормовію.",  -- db:8174
[823270965] = "Старійшина Беллоурейдж пильнує Темний Портал з хребта у Спустошених Землях.",  -- db:8175
[380668488] = "Старійшина Блейдсвіфт мандрує стежками Дарнассуса на вершині Телдрасіла.",  -- db:8176
[799683159] = "Старійшину Скайгліма можна знайти поблизу пам’ятника «Воронячий гребінь» в Азшарі.",  -- db:8177
[335243599] = "У селі Доланаар, розташованому на вершині Телдрасіла, мешкає Старший Блейдліф.",  -- db:8178
[284360721] = "Старійшину Старвів можна знайти в прибережному селі Обердін у Темному березі.",  -- db:8179
[527296156] = "Старійшина Найтвінд проводить дні у святилищі в Джеденарі, що у Фелвуді.",  -- db:8180
[556311514] = "Село Астранаар у Попеліній долині — це місце, де зараз мешкає Старший Ріверсонг.",  -- db:8181
[980914632] = "Наскільки мені відомо, старійшина Стоунспайр перебував у Еверлуку в Вінтерспрингу.",  -- db:8182
[735550192] = "Старійшину Брайтспіра можна зустріти серед руїн Кель'Теріла у Вінтерспрингу.",  -- db:8183
[287503071] = "Старійшину Бладхуфа можна знайти в селі Бладхуф у Мулгорі.",  -- db:8184
[189911544] = "Старійшина Віндтотем перебуває в компанії гоблінів з Ратчета на узбережжі Пусток.",  -- db:8185
[62842121] = "Старійшина Хай-Маунтін перебуває в таборі Таурахо в Пустках.",  -- db:8186
[26040105] = "Старійшина Мунварден спостерігає за «Перехрестям» у Пустках.",  -- db:8187
[731169574] = "Старійшина Праудхорн милується краєвидами, що відкриваються над Мулгором з Грім-Скелі.",  -- db:8188
[7778826] = "Старійшину Даркхорна можна знайти серед червоних скель Оргримара.",  -- db:8189
[474175974] = "Старійшина Морнінгдью почав спостерігати за метушнею на іподромі «Міраж» у місті Таузенд-Нідлз.",  -- db:8190
[283937622] = "З того, що я чув, старійшина Рунетотем прямував до Разор-Гілл у Дуротарі.",  -- db:8191
[138479262] = "Ви знайдете старійшину Грімтотема в павільйоні Ларісс у Фераласі.",  -- db:8192
[954647529] = "Старійшина Міствукер із задоволенням спостерігає за сутичками в Маулі у Фераласі.",  -- db:8193
[989064958] = "Завітайте до таверни «Фрівінд» у місті «Тисяча Голків», і ви знайдете там Старця Скайсіра.",  -- db:8194
[289651329] = "Гадаю, старійшина Сплітрок вирушив до Мараудона в Десоласі.",  -- db:8195
[291347460] = "Старійшина Дрімсір мешкає в Гаджетзані, що в пустелі Танаріс.",  -- db:8196
[859670425] = "Старійшина Рагетотем проводить свої дні в Долині Спостерігачів у пустелі Танаріс.",  -- db:8197
[393732714] = "Зул'Фаррак у пустелі Танаріс — це домівка Старшого Вайлдмейна.",  -- db:8198
[552502749] = "З причин, які мені не зрозумілі, Старший Грімгорн вирушив до «Повзучої Шрами» в кратері Ун'Горо.",  -- db:8199
[870878650] = "Якщо ви вирушите до Цитаделі Сенаріону в Сілітусі, то там зустрінете Старшого Блейдсінга.",  -- db:8200
[356275106] = "Старійшина Праймстоун провів багато років у Кришталевій долині в Сілітусі.",  -- db:8201
[735948614] = "Шанувати старших — це шанувати свою культуру та свій народ, $c.  Саме тому «Монети предків» слугують матеріальним засобом визнання тих, хто вирішив йти по шанованому шляху поваги.$B$BПід час цього Місячного фестивалю у вас може з’явитися нагода вшанувати багатьох старших.  Роблячи це, ви отримаєте Монети Предків.  Принесіть мені ці монети, і я винагороджу вашу старанність добіркою унікальних предметів.$B",  -- db:8202
[457282788] = "Вітаємо, $N.  Ми прибули з Місячної галявини, щоб поширити дух Місячного фестивалю на всі боки.$B$BЧи не хочете приєднатися до нашого свята?",  -- db:8205
[834387365] = "Ми стоїмо пліч-о-пліч з Альянсом, $r. Зло, настільки давнє, що світ про нього забув, прагне поглинути нас усіх: спочатку Калімдор, а потім і решту Азерота. Воно рухається ненавистю до всього, що породили великі Творці: Вічних Титанів.$B$BЛише ми стоїмо на заваді арміям К'Туна. Ми завдамо першого удару й розгромимо сили Ан'Кіраджа. Нехай весь Азерот тремтить перед об'єднаною міццю Орди та Альянсу.$B$BВійна потребує вас!",  -- db:8209
[544379424] = "Востаннє я бачив старійшину Медоурана в «Печері Сліз» на Західних Землях Чуми.",  -- db:8210
[138335643] = "Ви знайдете старійшину Старглейда біля воріт Зул’Гуруба в Долині Странглторн.",  -- db:8211
[683909225] = "«Відмінно попрацював, збираючи ресурси для війни», — сказали вони, «Ось тобі підвищення», — додали вони. Насправді ж вони мали на увазі: «Карнес, тебе відправляють на службу біля комашиного вулика в Сілітусі разом із купою спітнілих гномів!»$B$BДякую за підвищення, капітане!",  -- db:8212
[975656739] = "Я, як і мій брат, шаную тих, хто шанує своїх предків. Мені приносить велику радість ділитися своїми секретами майстерності з учнями Місячного фестивалю!",  -- db:8213
[451725222] = "Я, як і багато інших, прийшов на допомогу своїм побратимам-друїдам, коли почалася війна.$B$BТепер, коли Ворота Ан’Кіраджа відкрилися, я усвідомив, що попереду ще багато роботи.  Я вирішив залишитися в Сілітусі й зробити все можливе, щоб допомогти справі, $N.",  -- db:8214
[321420615] = "Хоч силітиди й здаються смертельно небезпечними, вони — лише покірні істоти порівняно зі своїми володарями, кіраджі.",  -- db:8215
[62243421] = "Ця війна ще не закінчилася, вона тільки-но почалася!  У нас є відважні чоловіки та жінки, які день і ніч борються з нашим ворогом всередині Ан’Кіраджа, $N.  Незабаром місто Кірадж впаде.",  -- db:8216
[941207387] = "Наш стабільний прогрес у боротьбі з Кіраджі можна пояснити різноманітною допомогою, яку ми отримали майже з усіх куточків Калімдору.$B$BДля ведення війни потрібні не лише солдати, $N.  Багато хто з невизнаних героїв війни — це торговці та ремісники, які забезпечують наші війська необхідними ресурсами.",  -- db:8217
[308659934] = "Тут, у Мунглейді, вміють влаштовувати вечірки. Хто б міг подумати?",  -- db:8218
[178313955] = "Спробуйте ці пускові установки для феєрверків.  З ними — суцільний кайф!",  -- db:8218
[240931667] = "Цей промінь місячного світла веде до Штормовію.  Коли будете готові, скористайтеся своїм запрошенням.",  -- db:8218
[621319924] = "Не намагайтеся телепортуватися до одного з міст ваших ворогів. Це не спрацює — тут ми, можливо, всі дружимо, але вдома старі образи залишаються...",  -- db:8218
[373983767] = "Мешканці Найтхевена точно знають, як веселитися!",  -- db:8219
[778871571] = "Ці феєрверки справді видають гарний «БУМ», чи не так?",  -- db:8219
[645164591] = "Це місячне світло відведе тебе до Айронфорджа.  Але хто ж захоче покинути цю вечірку?",  -- db:8219
[402346189] = "Цьогорічне святкування Місячного фестивалю вийшло просто чудовим!",  -- db:8220
[879450014] = "Кажуть, що ці феєрверки використовують силу Місяця!",  -- db:8220
[970646375] = "Цей промінь місячного світла, що сяє яскравіше, перенесе вас до Дарнассуса.",  -- db:8220
[938282721] = "Якби я не знав краще, то сказав би, що цю вечірку організували орки!",  -- db:8221
[145793119] = "Ти бачив?  Останній феєрверк ледь не підпалив сорочку того карлика!  Ха!",  -- db:8221
[246012346] = "Цей місячний промінь перенесе вас до Оргримара.  Скористайтеся своїм запрошенням, коли захочете туди вирушити.",  -- db:8221
[721187011] = "Я обожнюю Місячний фестиваль!  Це чудове місце, де можна з розмахом розвіяти пил копитами!",  -- db:8222
[940445714] = "Я не знаю, як працюють ці феєрверки, але вони, безперечно, дуже гарні!",  -- db:8222
[809002846] = "Цей місячний промінь перенесе вас до Громового Утвісу.  Скористайтеся ним, коли захочете покинути фестиваль.",  -- db:8222
[975801257] = "Ніщо так не зігріває до самої душі, як невеличке святкування Місячного Нового року!",  -- db:8223
[876950557] = "Треба бути обережним, запалюючи феєрверки, коли не відчуваєш пальців...",  -- db:8223
[499176971] = "Цей промінь місячного світла веде до Підміста.  Коли будете готові, йдіть на відпочинок.",  -- db:8223
[160445255] = "Омен спить у глибинах озера Елунеара, але його можна викликати на південно-східному березі, поблизу лігвищ «Гробниці Штормрейдж». Там ви знайдете спеціальні пускові установки для ракетних снарядів...$B$BЗарядіть пускові установки ракетами, і з’являться слуги Омена.  Вистріліть ще ракет — майже три десятки — або киньте у його посіпаків «Свічки Елуни», і незабаром він прокинеться.",  -- db:8225
[130698254] = "Ми довго боролися за те, щоб наша земля знову набула колишньої слави, $c. Ми завжди будемо пильні щодо тих, хто вторгся в Кель’талас і осквернив його. Ми не знайдемо спокою, доки не виженемо їх з-під нашого погляду.$B$BНехай не залишиться нікого, хто стоїть на заваді син’дореї!",  -- db:8226
[130781349] = "Тут повний безлад, $c, і це все моя вина! Мене попереджали, щоб я покинула док, поки ще є час, але чи я прислухалася? Ні.$B$BЩо ж мені тепер робити? Ті огидні кровні ельфи, «Нещасні», вкрали мої магічні товари і, здається, з’їли їх. Я майже впевнена, що це означає: їх уже не повернути. А мурлоки з «Грімскейл» посеред ночі викрали решту моїх товарів! До того ж, щоб добити чесну торговку, коли вона вже й так у скруті, моя команда покинула корабель!$B$BЗдається, я зараз розплачуся.",  -- db:8227
[430538404] = "Привіт, $c. Це справді тривожні часи, якщо ось таким має стати наш улюблений Квель-Талас.",  -- db:8228
[25239498] = "«Нещасні» — це постійний головний біль для мене, $N. Коли вони не становлять небезпеки для самих себе, використовуючи нестабільні магічні джерела, щоб задовольнити свої жаги, вони вигадують безглузді інтриги проти нашого поважного суспільства.",  -- db:8229
[127897782] = "Сподіваюся, з Лораталісом усе гаразд, $c. Може, мені самому варто піднятися на Вежу Сутінкового Вітру? Може, мені слід було це зробити ще спочатку?",  -- db:8232
[832979826] = "Людина може жити з собою та своїм соромом лише певний час, $c, перш ніж їй доведеться вжити заходів, щоб виправити свої помилки.",  -- db:8233
[705081073] = "Хаос, ось що це таке!  Усі ці істоти з’явилися з нізвідки й тепер безладно бігають туди-сюди!  А куди ж подівся Магістр зі своїми учнями?  Залишили мене тут саму, навіть не сказавши: «Привіт, Віллітен, може, підеш з нами?»$B$BЯка нахабність!",  -- db:8234
[30915781] = "Ми настільки занурилися в цю війну, що дехто з нас забув знайти час для кохання.",  -- db:8235
[421222103] = "Це була справжня битва. Давайте трохи перепочинемо.",  -- db:8237
[441900035] = "Привіт, $gmister:miss;.  Ти схожий на $C з вишуканим смаком у вині.  Хочу попросити тебе про послугу, і, здається, можу зробити тобі пропозицію, від якої не зможеш відмовитися... забудь про це!",  -- db:8238
[514956981] = "На що ти дивишся, $glad : lass;?  Ніколи раніше не бачила карлика, що?$B$BКраще йди собі, якщо не хочеш неприємностей.",  -- db:8239
[185317630] = "А, мабуть, це ти, $glad : дівчино; яку доручили провести мені екскурсію по Лісу Еверсонга.  Досить довго добиралася сюди, чи не так?$B$BГаразд, рушаємо.  Не будемо марнувати ні хвилини.",  -- db:8240
[757659437] = "Схоже, ти вже знайшов кохання. Можеш подарувати мені знак кохання, але я тобі нічого гарного не дам. Я чекаю на когось особливого.",  -- db:8241
[260855570] = "Не знаю, що на мене найшло. Моє серце палає, наче розпечена сталь.",  -- db:8251
[486439782] = "Коли так довго працюєш з машинами, іноді забуваєш про справжні серця.",  -- db:8254
[553416711] = "Коли проживеш стільки, скільки я, про кохання можна легко забути на довгі роки. Завжди приємно, коли тобі про це нагадують.",  -- db:8255
[148847222] = "Ми, орки, зазвичай — досить замкнутий народ, але останнім часом ніхто вже не приховує своїх почуттів.",  -- db:8263
[994681856] = "Те, що це не моє серце, ще не означає, що його не можна розбити.",  -- db:8270
[511473477] = "Вітання та найкращі побажання з маєтку «Рейвенхолдт», мандрівнику.",  -- db:8280
[398414939] = "Схоже, тобі розбили серце. Приходь, коли тобі не буде так сумно.",  -- db:8282
[943182190] = "Я б з тобою поговорив, якби ти пахнув краще. Було б непогано, якби ти користувався одеколоном.",  -- db:8285
[393918264] = "Що, у тебе немає жетона, щоб мені дати? Ти що, мене не любиш?",  -- db:8286
[273122800] = "Мені б ти більше подобався, якби ти наніс трохи парфумів.",  -- db:8289
[753826992] = "Що?! Як тобі вдалося прокрастися повз мою в'язницю... е-е, мого підручного, що стояв там? Ну, гадаю, так навіть краще. Останнім часом продажі трохи впали.$B$BЧим можу задовольнити твої пекельні потреби, $c?",  -- db:8292
[760130961] = "Дуже хитро ти тут так пробрався, $N.$B$BЩо? Здивований, що я знаю твоє ім’я? Я ж демон — це наша робота. Я також знаю твоє справжнє ім’я, тож тобі краще купити щось дороге.",  -- db:8292
[769809119] = "Прийшов за вудкою? Або, може, просто запасаєшся рунами?$B$BЗачекай-но! Ти що, просто намагаєшся звалити на мене купу мотлоху?! Проклята моя нескінченна тяга купувати, купувати, купувати!",  -- db:8292
[714997486] = "Що? Ні, я не займаюся ремонтом обладунків. Еверлук — приблизно миля на північ, $g brother : sister;.$B$BА тепер або щось купи, або йди геть, поки я не покликав свого чаклуна, щоб він розібрався з тобою!",  -- db:8292
[773478259] = "Я б з тобою поговорив, якби ти пахнув краще. Може, нанести трохи одеколону? Або парфумів?",  -- db:8303
[703727024] = "Ми отримали наказ згори знищити Раджакса. Якщо говорити суто технічно, то його слід ліквідувати без жодних поблажок.",  -- db:8304
[260036380] = "Моє завдання — взяти участь у змаганнях. Якщо вам щось знадобиться, у мене, можливо, є запасні матеріали.",  -- db:8305
[285748252] = "Ні, я не шукаю, але багато інших людей шукають кохання. Тобі варто купити мої «жетони кохання», нанести трохи одеколону чи парфумів, а потім роздати їх усім навколо!",  -- db:8306
[985793191] = "Знаки кохання — це невеликі послання про прихильність, які ви можете дарувати закоханим мешканцям містечок і міст.  Такі люди віддячать вам подарунком, що свідчить про їхнє захоплення.$B$BАбо, якщо ви вже користуєтеся чиєюсь прихильністю, то, як мінімум, вони подарують вам знак дружби.",  -- db:8307
[268454814] = "Якщо ви нанесете одеколон або парфуми, то одразу побачите, хто схильний до романтичних стосунків. Саме такі люди приймають знаки уваги... і дарують подарунок у відповідь.$B$BАле пам’ятайте: щоб подарувати комусь знак уваги, ви повинні пахнути саме так, як треба! Чоловікам подобається аромат парфумів, тоді як жінки віддають перевагу одеколону.",  -- db:8308
[228030553] = "Ви запитаєте, хто ж найпопулярніший герой королівства?  Ось поточний рейтинг!$B$BТралл: $2200w$БКейрн: $2201w$БСильвана: $2202w$БВсього Орда: $2207w$B$ББолвар: $2203w$БМагні: $2204w$BТиранда: $2205w$BЗагальний результат Альянсу: $2206w$B$BЯкщо ви хочете проголосувати, не забудьте здати свої колекції подарунків!",  -- db:8312
[435017018] = "Привіт!  Я — Кві К. Педдлфіт!  Я тут, щоб дізнатися, хто з усіх героїв Азерота найпопулярніший!$B$BМені справді приємно бачити, як стільки захоплених шанувальників вітають своїх лідерів, але... знаєте, що порадувало б мене ще більше?$B$BCілунок!",  -- db:8313
[421959349] = "Ось підсумкові результати!$B$BТралл: $2200w$БКейрн: $2201w$БСильвана: $2202w$БЗагалом «Орда»: $2207w$B$ББолвар: $2203w$БМагні: $2204w$BТиранде: $2205w$BЗагальний результат Альянсу: $2206w$B$BУ Альянсу найпопулярніший герой!",  -- db:8315
[727160464] = "Коли ви даруєте жителям містечка знаки любові, натомість отримуєте різні подарунки.  Деякі з них ви захочете залишити собі та використовувати, а інші можна зібрати разом і подарувати своєму улюбленому герою!  Завітайте до Кві К. Педдлфіта, щоб здати їх.$B$BКві можна знайти поблизу Болвара, Магні або Тиранди.",  -- db:8317
[134429543] = "Коли ви даруєте жителям містечка знаки любові, натомість отримуєте різні подарунки.  Деякі з них ви захочете залишити собі та використовувати, а інші можна зібрати разом і подарувати своєму улюбленому герою!  Завітайте до Кві К. Педдлфіта, щоб здати їх.$B$BКві можна знайти поблизу Кейрна, Сильвани та Тралла.",  -- db:8319
[43374831] = "Зміст сторінок цього тома, здається, постійно змінюється. У тебе виникає відчуття, ніби твої думки витікають з голови і поглинаються книгою.",  -- db:8321
[996006109] = "Перед вашими очима постає ціла гама зображень, форм і орнаментів. Здається, книга знає, наскільки ви вправні у роботі зі шкірою, і пропонує вам вибір — але майте на увазі: ви можете вибрати лише одне, і, зробивши вибір, вже не зможете змінити свого рішення!",  -- db:8326
[86774643] = "Я не можу навчити тебе ремеслу обробки драконової шкіри, $N. Тобі треба вирушити до Танарісу й знайти будинок Нараїна Сутфенсі. Коли ти туди дістанешся, ознайомся з книгою «Пророцтва для початківців».",  -- db:8327
[119089570] = "Трал проявив велику доброту, надавши мені притулок на своїх землях. У будь-якому разі, я не хочу зловживати його гостинністю. Було б великою ганьбою, якби я завдав нашому вождю будь-яких неприємностей.",  -- db:8332
[476301373] = "Намагайся не привертати до себе занадто багато уваги — я чекаю, поки король надасть мені аудієнцію. Не те щоб мені було неприємно чекати — я почуваюся цілком у безпеці в оточенні всіх цих кремезних охоронців.",  -- db:8333
[91706145] = "Я змирився з тим, що можу втратити своє життя. Але втратити Ісіду — це те, чого я не зможу витримати навіть після власної смерті.",  -- db:8334
[230549489] = "Вітаю, друже!  Може, тебе зацікавлять ектоплазмові конденсатори?  Або, можливо, чудовий всенаправлений спектральний асимілятор?",  -- db:8335
[81509223] = "Що тепер? Хіба ти не бачиш, що я зараз досить зайнятий?",  -- db:8336
[345924225] = "Поки що я в порядку, не хвилюйся за мене. Я знайду спосіб вибратися звідси, щойно проведу кілька очищувальних ритуалів у цій кімнаті. Це місце опоганено мерзенною магією, $N.",  -- db:8344
[878125565] = "Наша найновіша атракція — до речі, абсолютно безкоштовна — це мініатюрні танки, або «Тонки», як ми їх дотепно назвали. Ними можна керувати з будь-якої консолі управління «Тонк», розташованих по всій території ярмарку.$B$BВсе, що вам потрібно зробити, — це активувати вільну консоль управління. Кожен «тонк» буде оснащений стандартним набором пристроїв та випадковою спеціальною здатністю, яку ви зможете застосувати проти ворога!$B$BВлаштовуйте епічні битви з друзями, катайтеся по території ярмарку або просто влаштовуйте шалений хаос... вибір за вами!",  -- db:8347
[434801024] = "«Бластенхаймер 5000 Ультра» — це найсучасніша одномісна метальна установка. Ця гармата, що вистрілює боєприпаси зі швидкістю, близькою до швидкості дракона, є гордістю та радістю родини Бластенхаймерів, всесвітньо відомої своїми досягненнями в авіації та у сфері вибухових речовин!$B$BЯкщо ви хочете злетіти в небо й літати вільно, як птах, знайдіть Максиму Бластенхаймер на південному краю центрального пагорба Громового Уступу. Вона націлить вас на ціль, що знаходиться далеко на півдні, над озером Стоунбулл!",  -- db:8349
[935109796] = "Кажуть, що Кел’Тузад шукає легендарний «Атіеш» — великий посох Хранителя.$B$BТак, саме той посох, який колись належав Медіву.",  -- db:8350
[278553246] = "Будьте обережні, $r. Ми, члени Братства Світла, не такі поблажливі, як наші побратими, коли йдеться про відправлення правосуддя над тими, хто чинить зло цьому світу.$B$BГоре тим, хто розгніває Корфакса.$B$BЯкщо у вас немає ніяких справ до мене чи інших членів Братства, будь ласка, залиште нас, щоб ми могли продовжити наше засідання. $B",  -- db:8351
[4572411] = "Король Ліч намагається заявити про свою присутність у нашому світі. Не можна допустити, щоб це сталося.$B",  -- db:8352
[770769963] = "Що таке «Братство Світла»? Ну... По суті, ми всі — члени «Сріблястого Світанку», але таких членів, яких не стримують мораль, почуття провини та марні людські емоції. Вважайте нас «Скарлетним хрестовим походом» без дурості, відсутності лідерства та сліпого фанатизму.$B$BНе дозволяйте Скарлетному командиру переконати вас у протилежному.$B$BІ не кажіть Тиросусу, що я це сказав... Було б страшенно прикро, якби мені довелося жорстоко покалічити його, якщо раптом спалахне бійка.$B",  -- db:8353
[897089159] = "«Срібний Світанок» — можливо, й безсилі ідеалісти, але їхній ошуканий лідер розуміє, що вони не в змозі протистояти супротивнику. Мене відправили сюди як посланця «Скарлатового Хрестового Походу». Посла, якщо хочете... Сумнівно, що нам вдасться хоча б трохи похитнути армії Кель'Тузада — об'єднані вони чи ні, — але, можливо, ми зможемо стримати їх достатньо довго, щоб сталося якесь диво.$B$BА що стосується мене? Я загину в бою...$B$B<Марджан знизує плечима.>$B",  -- db:8354
[368551835] = "Ця назва вводить в оману. Насправді я дуже приємна людина, якщо мене краще пізнати.",  -- db:8355
[931869032] = "Вони ледь не відправили на це зібрання мого брата, Локсі. Він навіть не може доглядати за своїми гончими, не кажучи вже про те, щоб гідно представляти «Скарлетний хрестовий похід».",  -- db:8356
[696501718] = "Я чекав...$B$B<Римблат кашляє.>$B$BВибачте, стара звичка. Я — Римблат із «Земляного кільця».",  -- db:8357
[120113365] = "Привіт, $c. Вибач, будь ласка, я зараз розмовляю з Римблатом. Він вважає, що навіть цю землю ще можна врятувати.",  -- db:8358
[538308806] = "Чого ти хочеш, лемінг? Зникни з моїх очей, перш ніж дізнаєшся, чому мене називають «Гнівним чарівником».",  -- db:8359
[541832097] = "Перший комплект броні «Дредноут» був виготовлений виключно для Скарлетного Верховного лорда Могрейна. Одягнувши повний комплект, Верховний лорд виглядав немов демон із глибин Нетера.$B$Б «О, це було справді вражаюче видовище, коли Могрейн, високо піднявши «Попелоносія», кидався у стотицю воїнів Плетіння, а потім виходив з іншого боку в хмарі пилу та полум’я — а вороги залишалися попелом під його ногами».",  -- db:8363
[795465280] = "Лише після його суперечливої смерті лицарі та воїни Лордаерона почали носити обладунки подібного зразка на честь свого загиблого героя. Хоча смерть Могрейн стала великою перемогою для Кель'Тузада, наслідки її мученицької загибелі відчувалися аж до кінця війни.$B$BДе хтось падав, там багато хто піднімався...",  -- db:8364
[303080862] = "Я — те, що ви називаєте капіталістом, $r.",  -- db:8366
[720327919] = "О, привіт... е-е, як тебе звати?$B$BТа неважливо, що ж привело тебе до мого «другого дому» тут, у мальовничій сільській місцевості?",  -- db:8374
[290691470] = "Привіт, $c. Сподіваюся, ти гарно проводиш час? Що думаєш про вечірку? Я дуже сподіваюся, що у нас нічого не закінчується. Ніщо так не псує свято, як нестача напоїв та закусок, чи не так?$B$BТак, що ж, мені треба піти до інших гостей. Приємно проведіть час.",  -- db:8375
[49240059] = "Вітаю, мій $g володарю : пані;. Сподіваюся, ви гарно проводите час?",  -- db:8378
[363674191] = "Хіба це не просто чудово? Я так рада, що лорд Салтеріл щовечора влаштовує такі вечірки, особливо з огляду на всі ті неприємності, що відбуваються на півдні. Це ніби допомагає про все це забути, чи не так?",  -- db:8379
[86711880] = "Як і Кел’Тузад, я колись теж був магом Кірін-Тор. І, як і Кел’Тузад, я шукаю легендарний Атіеш — великий посох Хранителя. Наші долі так переплелися, $c.",  -- db:8388
[840437472] = "Нащадок Егвінн, той, хто мав стати останнім Хранителем Тірісфала... Медів.",  -- db:8389
[831272324] = "Це легендарна історія, яку я не маю ані часу, ані бажання переповідати. Достатньо знати, що Медів був останнім із Стражів. Великий жезл Атіеш був джерелом його сили та вогнищем розтління.",  -- db:8390
[370837543] = "Зіпсованість занепалого титана. Зіпсованість Руйнівника. Адже посох був викуваний із насіння ненависті. Саме це, звісно, й привело мене сюди...",  -- db:8391
[830869226] = "Після падіння Каражана Кірін-Тор відправив групу магів, щоб обшукати вежу та вилучити всі цінні предмети... з метою «дослідження». Саме тоді й було виявлено легендарний посох, який потім доставили до Даларана.",  -- db:8392
[464313424] = "Далі сталася низка трагічних подій, що призвели до загибелі кожного мага Кірін-Тор, який торкався Атіеша.$B$BСправа в тому, що це був артефакт, наділений свідомістю. Свідомістю, яку йому надав Саргерас...",  -- db:8393
[852640873] = "<Анжела киває головою.>$B$BПісля цих смертей «Шістка» вирішила, що найкращим виходом буде закрити посох за непроникними магічними бар’єрами та призначити наглядача: охоронця посоху... Цим наглядачем мала стати я.",  -- db:8394
[147022306] = "Більше розповідати особливо нема чого. Даларан був майже повністю зруйнований Архімондом, а посох зник — ймовірно, його розтрощили механізми безпеки бар’єру.$B$BДехто вважає, що саме цей посох став причиною помсти Архімонда.",  -- db:8395
[175790471] = "Після падіння Даларана я покинув Кірін-Тор. Я роками охороняв Атіеш, але моє призначення в Кірін-Торі було відібране у мене одним махом. Я знайду цей посох, хай навіть на це піде все життя. Ось так я приєднався до «Срібного Світанку» і саме тому я зараз тут.",  -- db:8396
[167734215] = "Я відстежував різні уламки посоха по всьому цьому світі і, роблячи це, виявив плани Кел’Тузада щодо відновлення посоха. Він уже зібрав кілька уламків посоха, які перебувають у його найнадійніших помічників.$B$BЯ не можу достатньо наголосити на тому, як важливо не допустити, щоб великий посох Хранителя потрапив до рук Кель'Тузада. Чесно кажучи, я навіть не уявляю, чим це може закінчитися, окрім катастрофи грандіозних масштабів.",  -- db:8397
[43213919] = "Це влада, недоумку.$B$B<Очі Матауса потемніли.>$B$BЦі дурні відправляють таких ідіотів, як ти, до Наксрамаса, щоб ти приніс звідти осквернені обладунки, аби вони могли їх очистити й повернути їм колишню славу.$B$B<Матаус плюнув.>$B$BСама думка про таку цілковиту дурість змушує мене задихатися від огиди.$B$BЯ теж шукаю цю броню, але в її найогиднішому й найоскверненішому вигляді.",  -- db:8398
[180728054] = "Я не прикидаюся, черв’яку. Темрява, яку містять такі предмети, цілком може знищити нас обох. Ось чому ціна така висока. Якщо я й помру, то лише як багатій.$B$BІ мені начхати, як ти помреш, головне — щоб ти зробив те, про що я прошу. Принеси мені те, що мені потрібно, і ми обоє виграємо — або помремо, але я вже пояснював це...",  -- db:8399
[125792997] = "Ми надто милосердні до цих негідників. Треба кожному з них проткнути мечем.$B$BЇхня зухвалість у бухті Сансейл — це непростимо.",  -- db:8402
[156575302] = "Це був довгий день, протягом якого доводилося знищувати бездумних представників Плеті, що нескінченно марширують по «Мертвій Шрамі». Сподіваюся, ти тут, щоб допомогти, а не марнувати мій час пустою балаканиною.",  -- db:8403
[381647439] = "Я не можу вчити таурена їздити на рапторі.",  -- db:8407
[615156458] = "Ці огидні тварюки розбігаються по всьому світу.$B$BЯкщо ви віддаєте перевагу полюванню на відкритому повітрі, то більшість із них ви знайдете поблизу Плагвуда та Террордейла, а особливо багато їх у тунелі «Павутина жаху». Вони також можуть з'являтися майже в будь-якому таборі «Порази» у Східних Землях Чуми.$B$BЯкщо ви завзятий дослідник підземель, то знайдете чимало таких істот у Стратгольмі, а також декількох некрофіендів у Шоломансі.",  -- db:8408
[25695816] = "Ти що, дурний? Ти що, не помітив тих КІСТЯНИХ СТВОРІНЬ, які просто кишать по всьому ландшафту на твоєму шляху сюди?$B$B<Рохан зітхає.>$B$BЯкщо ти любиш мандрувати на природі, то знайдеш скелетних створінь по всьому Західному та Східному Краю Чуми. Повір мені, їх неможливо не помітити — вони точно не пропустять тебе, якщо трапиться нагода.$B$BЯкщо ти любиш підземелля, то Стратхольм і Схоломанс — це саме те місце, де можна знайти кісткові фрагменти.",  -- db:8409
[989935035] = "Ще один чудовий, похмурий день тут, у Транквілліені, чи не так, $c?$B$BЧим можу вам допомогти?",  -- db:8410
[861972830] = "Немає більшої свободи, ніж ширяти в небі, $c. Чим я можу вам допомогти сьогодні?",  -- db:8411
[795200553] = "Привіт, друже. Чим я можу тобі допомогти сьогодні?",  -- db:8412
[639272221] = "А, гарне запитання.$B$BЯкщо ви віддаєте перевагу полюванню на відкритій місцевості, елементалів можна знайти тут, у Землях Чуми, Азшарі, Палаючих Степах, Фелвуді, Сілітусі, Зимовій Весні та навіть у кратері Ун’Горо.$B$BЯкщо ви з тих, хто сміється в обличчя небезпеці, то, можливо, вам варто відвідати Діре-Маул. Я чув, що за його стінами мешкає чимало елементальних виродків. Також вам не завадить розшукати елементалів, яких використовують темнозалізні гноми в Глибинах Чорної Скелі.",  -- db:8414
[353007479] = "Це серйозне запитання? Ти справді не знаєш?$B$BЯкщо ти з тих боягузів, які бояться занадто забруднити руки, то уламки Темного заліза можна знайти на істотах у Палаючих степах та Палючому ущелині.$B$BЯкщо ж ти — кровожерливий шукач пригод, то в підземеллях Шпиля Чорної Скелі та Глибин Чорної Скелі ти знайдеш чималий запас цих уламків.",  -- db:8415
[981678356] = "Якщо ви належите до тих, хто віддає перевагу полюванню на відкритому повітрі, то як треанти Фелвуда, так і лашери Ун’Горо стануть для вас чудовим джерелом листя.$B$BЯкщо ж ви більше схильні до ризику, східне та західне крила Діре-Маула забезпечать вас майже невичерпним запасом дикого листя.",  -- db:8416
[598041710] = "$C, поглянь, що вони зробили з нашою улюбленою землею. «Скорб» треба знищити!",  -- db:8417
[373820061] = "Це вимагатиме певних зусиль, але я думаю, що ми зможемо врятувати життя цього кривавого ельфа.",  -- db:8418
[579214310] = "Хто ти?  Мені... так... холодно.",  -- db:8419
[186934194] = "Соромно, що ми, син'дореї, втратили так багато з того, що колись називали своїм домом. Незабаром ми відновимо свої сили й відвоюємо наші південні землі у Плеті!",  -- db:8421
[829925846] = "Я надто зайнятий, щоб грати з тобою в «вгадай запах», $r. Скажи, що тобі потрібно, або забирайся з моїх очей!",  -- db:8422
[588533436] = "Високопоставлений виконавчий чиновник і Дама Ауріферус змушують мене чекати, але у мене немає на це часу! Мої друзі там гинуть, $c!",  -- db:8423
[681352798] = "Більше ніж день тому я відправив рейнджера Саліссу на південь, до анклаву, а рейнджера Летваліна — на захід, до Транквіллієна! Ви бачили когось із них? Чи це ви — той помічник, якого відправили назад?",  -- db:8424
[41400175] = "Іноді мені здається, що я ніколи більше не повернуся до ролі простого службовця на службі у Дами Ауріфероус. Я не створений для війни.$B$BНа щастя, є такі, як ти, які палають бажанням повернути Кель'Таласу колишню красу. Знищ Плеть, $c! Знищ їх, де тільки зможеш!",  -- db:8425
[273651536] = "О, ось і $g герой : героїня; цієї години! Радий знову тебе бачити, $N! Сподіваюся, ти й досі знищуєш «Скорж» скрізь, де їх зустрічаєш?",  -- db:8426
[453308300] = "Мені повідомили, що тобі вдалося допомогти рейнджеру Валанні та лейтенанту в Зеб'Сорі.$B$BДякую, $c. Гадаю, мені слід тепер повертатися до Енклави Далекокроків.",  -- db:8428
[432473229] = "Що тебе сюди привело, $c?",  -- db:8429
[429084272] = "О, привіт, $r. Як бачиш, я ще не почав працювати. А тепер, якщо ти мене вибачиш, я дуже зайнятий.",  -- db:8431
[931191110] = "Ласкаво просимо до Транквіллієна, $c. Прошу вибачення за те, в якому стані ви його застали. Як ви бачите, у нас виникли певні труднощі, але «Покинуті» та їхня володарка Сильвана Віндранер були настільки люб’язні, що надали нам значну допомогу в скрутну хвилину.$B$BЯкщо ви можете допомогти, будь ласка, не вагайтеся. Нам знадобиться будь-яка допомога у боротьбі проти незліченних сил, що виступили проти нас.",  -- db:8433
[764180743] = "Настав час Орді та Альянсу звернути погляд на північ і звернути увагу на вторгнення Плеті. Останніми днями території Калімдору та Східних Королівств зазнали нападів. Чи візьмете ви зброю, щоб врятувати свою землю від руйнування з їхнього боку?",  -- db:8434
[695269870] = "Не бійся меча, малий. А от баранина — ось що тебе підведе!",  -- db:8435
[754907119] = "Жахлива історія — те, що сталося з тими мулами... Метц мене за це покарає.",  -- db:8438
[37970415] = "Дуже важливо з’ясувати, що саме замишляють нічні ельфи, $c! Будь ласка, зосередьте всі свої зусилля на цьому.",  -- db:8439
[587368585] = "Ми надзвичайно задоволені вашими діями проти нічних ельфів. Викривши їхній задум щодо використання вузлів лей-ліній та так званих місячних кристалів для шпигунства за нами, ви на порядок посилили наші позиції тут.$B$BМи вам вдячні, $N.",  -- db:8440
[515916755] = "Це ви — підкріплення? Нічні ельфи зазнали нищівної поразки!",  -- db:8441
[617625167] = "Добре, що ти вчасно деактивував місячний кристал в Ан'овіні, $c! Заходь у будь-який час, коли захочеш допомогти мені з дослідженнями.",  -- db:8442
[995334097] = "Як я можу працювати в таких умовах?! І ще всі ці огидні Покинуті навколо! Я сумую за Транквіллієном і Квель'Таласом!",  -- db:8445
[678404766] = "$R, доповідай! Які важливі новини ти приніс? Не зволікай... Дама Ауріфероус і я саме ведемо стратегічну дискусію.",  -- db:8447
[161361350] = "Ласкаво просимо до каплиці «Надія Світла», незнайомцю.",  -- db:8448
[587145132] = "Наші каравани вирушають приблизно двічі на день, але хай мене чорт візьме, якщо «Скорб» не робить усе можливе, щоб завадити Дідьє та його мулам доставляти вантажі на передову. Найбожевільніше, що я коли-небудь бачив. Якби тільки у нас були героїчні авантюристи, які допомогли б захистити ці вантажі...",  -- db:8452
[588706848] = "У мене занадто багато справ, а часу на них замало, $r! Будь ласка, не заважай мені.",  -- db:8454
[19237711] = "У мене занадто багато справ, а часу на них замало, $r! Будь ласка, не заважай мені.$B$BЯкщо ти заражений слизом личинок або гниттям гулів, я, можливо, зможу тобі допомогти.",  -- db:8455
[374697826] = "<Кровний ельф швидко приходить до тями, коли ти вливаєш йому зілля в рот.>$B$BI Я завдячую тобі своїм життям, $c.  Без твоєї допомоги я б не витримав болісних тортур Плети.",  -- db:8456
[64919589] = "<Кровний ельф лежить на підлозі, перебуваючи в стані штучно викликаного заціпеніння.>",  -- db:8457
[532136185] = "<Жінка з племені «Покинутих» згорнулася калачиком на підлозі, на обличчі у неї гримаса. Наразі вона, схоже, не в змозі самостійно підвестися.>",  -- db:8459
[542582323] = "Ааааааа... Цей головний біль мене просто вбиває.$B$BМабуть, тебе послали, щоб мене врятувати.  Досить довго вони тягнули!  Ти хоч уявляєш, що вони тут роблять з в’язнями?",  -- db:8460
[864780408] = "<Кровний ельф безсило лежить на столі. Хоча він ще дихає, схоже, що він став жертвою сильних седативних токсинів.>",  -- db:8461
[635774266] = "Радий бачити вас, $r. Я тут, щоб надавати поради Верховному Виконавцю — він може ними користуватися на свій розсуд. Я впевнений, що разом ми зможемо перетворити Орду на ще могутнішу силу, ніж раніше, і раз і назавжди відкинути загрозу Плеті!",  -- db:8462
[607477262] = "<Варніс сильно кашляє, коли відновлювальний напій починає діяти.>$B$BДякую, що врятували мене.  Я мушу негайно повернутися до Транквіллієна!",  -- db:8463
[356481962] = "Якщо ви бажаєте обговорити важливе питання, $c, можливо, доцільніше буде попросити про аудієнцію у Дами Ауріфероус. Проте попереджаю вас: вона дуже зайнята, і, можливо, вам доведеться чимало почекати.",  -- db:8466
[712873394] = "Зазвичай я не маю права розмовляти з вами безпосередньо; скоріше, вам слід було б попросити про аудієнцію у пані. Однак я саме вам доручив це завдання, тож що саме нам потрібно обговорити?",  -- db:8467
[621488415] = "$C, Дама Ауріферус висловила мені свою велику вдячність за ту послугу, яку ви надали нам у минулому. Вона хоче висловити вам надію, що ви й надалі будете відстоювати інтереси син’дореїв тут, у Примарних землях.",  -- db:8468
[568676623] = "На нас чекає важлива робота, $N.  Давай атакуємо наших ворогів, поки вони не насторожі.  Давай покажемо їм, що помста синдореїв ніколи не забуває і не прощає.",  -- db:8470
[528902138] = "Хвилі війни знову насуваються. З холодної півночі некрополі Короля Ліча взяли в облогу наші землі. Він та його проклятий генерал, Кел’Тузад, відправляють літаючі некрополі, щоб вторгнутися в усі куточки світу.",  -- db:8471
[479762622] = "Оце ж справжня халепа! Як мені тепер зібрати зразки руди для магістрів, якщо шахти заполонили гноли-шкідники?",  -- db:8472
[435225951] = "Де вона, мабуть, може бути? Я вже досить давно відправив свою ученицю, Шатарію, до шахт «Андерлайт», що на заході. Нам потрібно якнайшвидше отримати ті зразки руди, інакше наш експеримент провалиться!",  -- db:8474
[930352951] = "Якби руда «Андерлайт» не була доставлена так вчасно, наші дослідження зазнали б невдачі.$B$BПочекайте, поки Шатарія знову з’явиться тут. У мене для неї є кілька цікавих завдань — можете бути впевнені!",  -- db:8475
[365829162] = "Сін'дорей за останні роки втратили надто багато. Нашу землю, наші домівки, навіть нашу ідентичність...$B$BНастав час почати все це повертати.",  -- db:8476
[710934070] = "Перш ніж ми зможемо подолати зовнішні перешкоди, такі як «Скорб» та тролі Амані, нам слід подолати перешкоди, що походять зсередини. «Нещасні» вже достатньо довго доставляють нам клопоти; настав час їх знищити.",  -- db:8477
[469867771] = "Як думаєш, ти міг би допомогти мені звідси вибратися?",  -- db:8478
[14602080] = "Серед численних пергаментних аркушів із переліками та іншою інформацією від «Далеких вершників» один особливо виділяється. Це малюнок огидного троля — мабуть, найстрашнішої істоти, яку ви коли-небудь бачили!",  -- db:8479
[518822478] = "Дійсно, пагорби Вінтерспринга зараз намагаються вистояти під час чергового наступу Плеті. Ваша допомога була б для них дуже корисною.$B$BКількість некрополісів, що залишилися: $2284W",  -- db:8480
[495616484] = "Наразі ця територія вільна від впливу Плеті. Боюся, що їхнє повернення — лише питання часу.",  -- db:8481
[630086023] = "Якщо найближчим часом до Палаючих степів не буде надіслано додаткове підкріплення, я побоююся, що Плеть створить там свою оперативну базу. Якщо є можливість, вам слід вирушити туди, щоб допомогти захисникам.$B$BКількість некрополісів, що залишилися: $2281W",  -- db:8484
[824816804] = "Знання свого ворога може дати чимало переваг.  Візьміть цей урок до серця, $N.$B$BЧим більше ми дізнаємося про «Скорб», тим краще будемо готові до перемоги над ними.",  -- db:8485
[875976219] = "«Скорб» створює невеликі перевалочні пункти в районах, що зазнають атак, отримуючи зв’язок та іншу допомогу від некрополісів, які літають над ними. З того, що нам відомо, єдиний спосіб їх винищити — це знищити наземні сили, що оточують ці пункти.",  -- db:8486
[154942331] = "Ви можете залишатися в анклаві «Фарстрайдер» скільки завгодно, $c. Ми радо приймаємо всіх, хто готовий допомогти нам у наших справах у Примарних землях.",  -- db:8487
[114685975] = "Блукаючі магічні сили можуть чинити дивні впливи на землю, стихії та навіть душі померлих.",  -- db:8488
[708469899] = "Ти проявив себе з найкращого боку, $N. Поборовши гнолів у Шахтах Андерлайта та муміфікованих тролів у Катакомбах Амані, ти завдав потужного удару нашим ворогам!$B$B$G Молодець! : Може, колись зустрінемося, щоб випити, що скажеш?;",  -- db:8490
[217818268] = "Радий знову тебе бачити, $g! : чудово!; Ми добре працюємо разом; $g, до зустрічі. : Сподіваюся, ми й надалі будемо так працювати.;",  -- db:8491
[315438334] = "До мене дійшла інформація з певних джерел щодо реакції леді Сильвани на твої дії та повернення її намиста. Я й досі вважаю, що ти вчинив правильно; не переймайся надто тим, як відреагувала леді.$B$BА тепер розкажи, у чому справа.",  -- db:8492
[127846307] = "Що тут сказати, $c? Ти — справжній $g герой : героїня! Ти не тільки особисто врятувала багатьох моїх рейнджерів, а й завдала вирішального удару по тролям із Шейдоупайн. Ти впевнений, що не хочеш залишитися тут і стати одним із моїх «Далекобіжників»?$B$BПрощавай, $N.",  -- db:8493
[662358384] = "Твоя допомога у боротьбі з тролями Шейдоупайн виявляється безцінною, $c. Продовжуй у тому ж дусі, і, можливо, нам вдасться знову зосередитися на боротьбі з Плетью.",  -- db:8495
[891263684] = "Ти завдав вирішального удару по тролям з Шейдоупайн, $N. Я лише сподіваюся, що нам вдасться достатньо швидко зібрати сили, щоб добити їх, перш ніж вони отримають підкріплення з Зул’Амана.$B$BБуло б добре, якби Транквіллієн надіслав нам підкріплення.",  -- db:8496
[145312013] = "Звісно, $N. Вам потрібно лише сказати, про яку репутацію ви хотіли б дізнатися.$B",  -- db:8498
[499813978] = "Безумовно, $N.$B$Bмандрівники, яких «Світанок» вважає почесними, повинні надати загалом 40 знаків, щоб отримати доступ до предметів вищого рівня. Щоб отримати доступ до предметів ще більшої сили, їм потрібно буде здати загалом 150 знаків.$B$BI мушу визнати, що ціна висока навіть для тих, кого «Світанок» вважає почесними.$B",  -- db:8499
[391894509] = "Звісно, $N.$B$BМандрівники, яких «Світанок» вважає шанованими, повинні надати загалом 14 знаків, щоб отримати доступ до предметів вищого рівня. Щоб отримати доступ до предметів ще більшої сили, їм потрібно буде здати загалом 90 знаків.$B$BТим, кого «Світанок» вважає шанованими, вартість предметів вищого рівня здасться цілком прийнятною! Вартість предметів ще більшої сили все ж залишається високою.$B",  -- db:8500
[351339615] = "Ситуація набагато гірша, ніж багатьом дають зрозуміти. «Покинуті» перебувають тут як союзники у боротьбі проти нашого спільного ворога — «Покарання».$B$BПовірте мені: без них Примарні землі були б втрачені, а «Пораза» вже давно заполонила б усі Еверсонгові ліси!$B$BАле понад усе нам потрібна ваша допомога, щоб повернути наші колись славні землі!",  -- db:8501
[242131203] = "Звісно, $N.$B$BМандрівники, яких «Світанок» вважає видатними, повинні надати загалом 12 знаків, щоб отримати доступ до предметів вищого рівня. Щоб отримати доступ до предметів ще більшої сили, їм потрібно буде здати загалом 54 знаки.$B$BТі, кого «Світанок» вважає видатними, отримують найбільші знижки.$B",  -- db:8502
[860961098] = "Звісно, $N.$B$BПригодники, яких «Світанок» вважає дружніми, повинні здати загалом 60 знаків, щоб отримати доступ до предметів вищого рівня. Щоб отримати доступ до предметів ще більшої сили, їм потрібно буде здати загалом 220 знаків.$B$BМушу визнати, що для мандрівників, яким «Світанок» не прихильний, ціна є досить високою.$B",  -- db:8503
[127919183] = "Ці рунічні камені захищають землі Еверсонга від зараження Плетью.  Західний рунічний камінь втратив свою силу ще давно, що змусило нас спалити землю навколо нього.$B$BПоки я живий, я не дозволю, щоб решта рунічних каменів підвели нас.  Це моя клятва.",  -- db:8504
[31970247] = "Ну, ти ж не проїхав весь цей шлях, щоб просто побалакати за чашкою чаю. Давай подивимося, як ти міг би допомогти нам вибратися з цієї ситуації.",  -- db:8505
[174631470] = "Є ті, хто скаже, що «Срібний хрестовий похід» — це вже минуле. Я один із них, але не тому, що «Покарання» зазнало поразки.$b$bНі… а через їхню впертість.  Вони стали надто схожими на церкву, від якої відокремилися: надто жорсткими, надто підпорядкованими честі та порядку.  Принаймні, саме це я намагаюся пояснити Бартоломею.$b$bЗвісно, це може звучати дещо шовіністично, але це гарний привід для дискусії.",  -- db:8506
[819443082] = "Це все, на що вони здатні?$B$B<Омаріон змушує себе посміхнутися.>$B$BУ тебе немає рішучості протистояти такому монстру, як Кел’Тузад. Ти розсиплешся перед його посіпаками — так само, як і ті, хто був перед тобою...$B$BЗалиш мене тут помирати. Я відмовляюся повертатися у світ, який захищає таких, як ти.$B",  -- db:8507
[240677467] = "Майстер-ремісник Омаріон просто зник однієї ночі. Наче дим на вітрі... Пуф! І зник! Ех, тепер я залишився єдиним, хто виготовляє речі для хлопців на передовій.",  -- db:8513
[576936209] = "<Омаріон щось бурмоче собі під ніс.>$B$BАле звичайно, я можу тобі допомогти, любий $g хлопче:дівчино;. Це моє останнє бажання... моє найзаповітніше прагнення. Будь ласка, візьми цей посібник. Інформація на його сторінках — це збірка всього, що я знаю і чого навчився за останні 30 з гаком років мого жалюгідного життя. Передай цей посібник моєму нікчемному підмайстру, який, мабуть, сидить на своєму товстому заду в каплиці «Надія Світла».",  -- db:8516
[123494315] = "<Тарсіс стогне.>$B$BМожливо, ще є час... Слухай уважно, смертний.$B$BЯ шукав крізь час і по всьому Нетеру. Укладав угоди з натовпом злих і підлих істот, настільки жахливих...$B$B<Тарсіс кашляє кров’ю у долоні.>$B$BЧи ти... чи ти повіриш, що навіть Елуна відвернулася від мене, $r? Померти тут, саме так, саме зараз...",  -- db:8517
[169688376] = "Те, що я зробив... такі жахливі речі...$B$B<Тарсіс починає ридати.>",  -- db:8518
[812222854] = "Я — представник Високого роду, $r. Зараз це вже нічого не означає. Проте колись цим світом правили представники Високого роду. Десять тисяч років тому...",  -- db:8519
[629139245] = "Я б повернув це собі, смертний. Атіеш... З його допомогою я б знову створив Високородних. Я б повернув собі все. Навіть Королеву...",  -- db:8520
[133598997] = "<Тарсіс слабко хапає тебе за комір. Навіть у смерті ти бачиш у його очах неймовірну силу.>$B$BЧи справді? Тоді слухай уважно, бо з моїх вуст ось-ось вирветься ще більше нісенітниць. У цій цитаделі ти знайдеш справу всього мого життя: точне місцезнаходження кожного уламка розбитого посоха.",  -- db:8521
[9890323] = "Атіеш, Великий жезл Хранителя. Жезл, що передавався з покоління в покоління кожному з Хранителів Тірісфала. Жезл, спотворений Саргерасом. Жезл останнього Хранителя. Жезл Медівха.",  -- db:8522
[12954540] = "<Очі Тарсіса спалахують.>$B$BI Я колись тримав його в руках... Я тримав його, незважаючи на попередження Кірін-Тора. Я тримав його, смертний... Нескінченна сила. Сила робити те, що я бажав, так, як я бажав. І так само швидко її у мене відібрали. Але я скуштував... І цього смаку було достатньо.",  -- db:8523
[133322330] = "<Тарсіс отримав серйозні поранення.>",  -- db:8524
[572267271] = "Битва йде успішно. Сили «Скорб’ї» здаються ослабленими. Я вірю, що це лише питання часу, коли ми виженемо їх з наших берегів. Я спрямую свою магію на вас, щоб допомогти у цій боротьбі.",  -- db:8526
[645492532] = "Перші кроки в нашій боротьбі проти Плетіння проходять успішно. Ми вже досягли певних успіхів, і, сподіваюся, моя допомога сприятиме вашим подальшим перемогам у цій битві.",  -- db:8527
[461848409] = "Вона загубилася, коли впала Фіолетова Цитадель… розлетілася на сорок дві частини.",  -- db:8529
[440112754] = "Кел'Тузад доклав чималих зусиль, намагаючись відновити жезл. Його уламки колись були розкидані по всьому цьому світі — від Калімдора до Південних морів. Я сам колись мав у своєму розпорядженні двадцять таких уламків — доки їх у мене не викрали поплічники Кел'Тузада. Ось чому я тут.",  -- db:8530
[706983494] = "Ти що, не слухав? Ні, я дуже сумніваюся, що ми б зараз вели цю розмову, якби Кел’Тузад зібрав жезл. Кел’Тузад тримає головку. Його підлеглі володіють сорока уламками Атіеша. Останній фрагмент — основу — виявив Бранн Бронзобородий. Востаннє його бачили в пустелі Сілітус; безсумнівно, він робив усе можливе, щоб триматися якнайдалі від невблаганних розшукувачів, яких Кел'Тузад розіслав по всьому світу.",  -- db:8531
[651455860] = "Наші Святилища витягують магічну енергію з потоків лей-ліній, які пролягають нашими землями, залишаючись невидимими для неозброєного ока.$B$BПісля зникнення Сонячного колодязя саме вони забезпечують нас стабільним і надійним джерелом енергії.",  -- db:8534
[66671992] = "Те, що селище Фейрбріз досі стоїть, є свідченням непохитності нашого народу. Ми ніколи більше не визнаємо поразки від Плеті.",  -- db:8535
[813546559] = "З дороги, ти мерзенний пес! Ревілгаз врятував мене від шибениці, але моє покарання може виявитися майже таким самим жахливим.",  -- db:8536
[252339347] = "Тобі краще не влаштовувати проблем, $N!",  -- db:8537
[987338712] = "Чим можу тобі допомогти, $N?  Швидше, у мене немає цілого дня!",  -- db:8538
[926741919] = "Чим я можу вам допомогти?  Ні, зачекайте!  А чим ви можете мені допомогти?",  -- db:8539
[323815003] = "Ви з великою відданістю служили нашій справі, $N.  Дозвольте мені подарувати вам невичерпне джерело нашої стихійної квінтесенції.",  -- db:8541
[898649809] = "З поверненням, $N.  Ти довів, що є гідним союзником у боротьбі з Рагнаросом, і ми завжди раді бачити тебе серед нас.",  -- db:8542
[726168978] = "Це список із «Притулку Салтеріла»?  Без сумніву, його світлість зажадає пляшку мого найкращого вина.  І, звісно, будь-який друг лорда Салтеріла заслуговує на спеціальну ціну на таке чудове марочне вино.",  -- db:8550
[350964577] = "Ми виграли битви проти «Скордж» із загальним призовим фондом у розмірі $2219W. Зберися з силами, $N, адже ця війна ще далеко не закінчена.",  -- db:8551
[477658287] = "Якщо у вас є гроші, у мене є їжа та напої, щоб задовольнити ваш апетит. Кожна мідна монета йде на те, щоб підтримувати «Ретріт» у ідеальному стані.",  -- db:8552
[399195331] = "Це список від лорда Салтеріла, що у вас там? Так, я можу продати вам партію закусок, щойно з вогню.",  -- db:8553
[372265498] = "У мене є на продаж найрізноманітніші товари, ціна — $c.  Переглядайте на свій розсуд.",  -- db:8556
[155822424] = "Список... як цікаво.  А, так, партія феєрверків для лорда Салтеріла.  Він за них ще не заплатив; ти прийшов, щоб придбати їх від його імені, $c?",  -- db:8557
[123658274] = "Невже цим неживим немає кінця?  Схоже, що на кожного гуля чи скелета, якого ми вбиваємо, на його місце приходять двоє.",  -- db:8558
[835953998] = "$C, ти часом не бачив кур'єра по дорозі сюди? Ми чекаємо звісток із Сільвермуна, а їхній посланець запізнюється!",  -- db:8561
[536765160] = "Іноді я стою тут, дивлячись на ліс за озером, і бачу цю землю такою, якою вона колись була... зеленою й сповненою життя.",  -- db:8564
[657671538] = "Нам дійсно треба придумати, як впоратися з цими смердючими тролями з Шейдоупайн!",  -- db:8565
[782108630] = "Мушу сказати, $c, ти не тільки доставила мені мою «отруту», а й найжорстокіше розправилася з тими тролями. У тебе є всі задатки, щоб стати справді талановитою молодою $g: леді!",  -- db:8566
[301782616] = "Ми мусимо зберігати пильність, $c! Між Дар’Ханом-Зрадником та його «Бичем», а також тролями з Тіньової Сосни, яких підтримує могутність Зул’Амана, нам ледь вдається триматися на плаву. Нам справді не слід розсіювати свою увагу!$B$B Сподіваюся, ти тут, щоб допомогти.",  -- db:8569
[742091205] = "Я радий, що ти тут, щоб допомогти, $c. Чим швидше ми розберемося з цими тролями, тим швидше зможемо відправити цю навалу туди, звідки вона прийшла.",  -- db:8570
[62551042] = "З однією групою тролів впоралися, залишилася ще одна. Ти навіть не уявляєш, як я ціную те, що ти робиш, $N! До твого приходу я не думав, що нам коли-небудь вдасться взяти під контроль проблему в Шейдоупайн.",  -- db:8571
[813156255] = "Ти навіть не уявиш, яка наволоч останнім часом до нас набігала. Більшість із них приносить більше клопоту, ніж нібито допомагає. Зовсім не так, як ти.$B$BТи впевнений, що не хочеш приєднатися до «Далеких вершників»?",  -- db:8572
[790872008] = "«Покарання» задіяло лише невеликі сили проти кожної зі столиць Азерота, тоді як їхні основні війська періодично атакують такі землі:$B$BAзшара, Спустошені землі, Палаючі степи, пустелю Танаріс, Східні Землі Чуми та Зимову Весну.",  -- db:8573
[995014917] = "Що вас сюди привело, $N?  У цих краях нечасто зустрінеш людей.  Мабуть, на те є свої причини.",  -- db:8575
[920831347] = "Ви хочете навчитися ковальській справі чи, можливо, хочете розповісти мені про щось інше?",  -- db:8576
[154193763] = "Нам з тобою дуже пощастило, що ми живі!",  -- db:8579
[633325234] = "У цих краях нечасто зустрінеш учнів, чи не так?  Я починаю думати, що це тому, що магістри доручають нам усю ту небезпечну роботу, якою самі воліють не займатися.",  -- db:8580
[1768465] = "У Світлі ми — одне ціле, $g брате : сестро;, але я не можу тебе навчити.",  -- db:8584
[897797134] = "Ти прийшов, щоб навчитися, мисливцю?",  -- db:8585
[578001198] = "Чи прагнете ви вдосконалити свої навички воїна?",  -- db:8587
[417049838] = "Ми, послідовники таємних і стихійних шляхів, йдемо нескінченним шляхом пізнання. Чи саме тому ти звертаєшся до мене за порадою? Ти бажаєш продовжити навчання?",  -- db:8589
[602200456] = "У Світлі ми всі відкидаємо тіні, мій $g брате : сестро;.  Чи шукаєш ти сьогодні подальших настанов?",  -- db:8591
[696603552] = "У міру того, як ви здобуватимете популярність у нашому місті, я зможу надати вам більше товарів, $N.  Оскільки спорядження в дефіциті, ми можемо дозволити собі надавати його лише тим, кому довіряємо.",  -- db:8617
[424179696] = "Так приємно тебе бачити, $g брате : сестро;!  Це місце викликає у мене мурашки по шкірі.  Поки ти тут, обов’язково скористайся численними можливостями, які надають ці так звані «Покинуті».",  -- db:8619
[523835311] = "Це не моя вина... ЦЕ НЕ МОЯ ВИНА!!!$B$BЯкби вони просто зробили те, що я їм казав, усе було б добре. Але ні! Вони не хотіли слухати.$B$BТепер вони всі мертві.$B$BЯ просто хочу додому. Додому, до Срібного Місяця. Я так втомився.",  -- db:8620
[511850175] = "Привіт, $c. Якщо ти ще цього не зробив, тобі дійсно варто поговорити з Фарстрайдер Соланною.",  -- db:8638
[660439869] = "Якщо ви загубили якусь частину своєї зандаларської броні, я, можливо, зможу вам допомогти.",  -- db:8645
[315965601] = "Я дуже вдячний тобі за допомогу, $c!",  -- db:8650
[953441765] = "А, то це ти знайшов того листа. Дякую за... новини, мабуть, про мою родину. Будь ласка, пригощайся тим, що я можу запропонувати.",  -- db:8653
[495851916] = "Хоча ми й дісталися до обітованої землі, $N, попереду ще багато роботи. Наші люди не дістануться до Каел’таса, якщо ми будемо відчайдушно кидатися через Замежжя.$B$B Треба знайти безпечні маршрути, забезпечити себе ресурсами та уникати ворогів або знищувати їх.",  -- db:8659
[743433088] = "Дякую за те, що принесли цей список!  Моя нога вже майже одужала, тож я зможу дійти пішки до місця аварії.",  -- db:8663
[992585844] = "Як ми взагалі звідси виберемося?",  -- db:8664
[254120218] = "Дякую за турботу про озеро, лашерів та совиних людей, $c.",  -- db:8665
[830785975] = "Ніхто не буде ставити під сумнів твої дії, $c.  Ти зробив те, що треба було зробити.",  -- db:8666
[890278274] = "Радий бачити, що ти живий і здоровий, $N!",  -- db:8667
[363243681] = "Ще раз дякую за те, що поповнили наші запаси цілющих кристалів. Я чула, що ви допомагаєте людям повсюди. Продовжуйте у тому ж дусі!",  -- db:8669
[181845061] = "Сподіваємося, що не вся Аутленд така безплідна, як цей регіон. Це досить різка зміна порівняно із зеленими луками та лісами Еверсонга.",  -- db:8674
[259576250] = "У Замежжя існують демонічні сутності, набагато могутніші за все, що ми коли-небудь бачили у Старому Світі.$B$BВелика сила дістанеться тим, хто не боїться її, а навчиться приборкувати та опановувати її.",  -- db:8675
[154109721] = "UDB: Відсутній текст англійською мовою",  -- db:8676
[909330443] = "Чим я можу допомогти?",  -- db:8678
[804772188] = "Аутленд просто просочений магічною енергією — вона витає у самому повітрі.  Ти це відчуваєш, $N?  Я не можу уявити місця, яке б краще підходило нашій расі.  Незабаром у син’дореї з’явиться нова земля, яку ми зможемо назвати своєю!",  -- db:8680
[965941995] = "Мій чоловік зник кілька днів тому. Ми вирушили в це паломництво разом; ми мали завершити його разом.$B$BЧерез ці всі турботи я почала частіше, ніж слід, черпати енергію з кристалів мани.",  -- db:8681
[670946678] = "Драконояструби, якщо їх правильно виростити, насправді бувають досить ручними. Хіба це не дивовижно? Бути такими дружніми й товариськими, якщо їх правильно виростити, і такими лютими та смертоносними в дикій природі... Я їх просто дуже люблю.",  -- db:8682
[799783591] = "Не... хвилюйся... за мене...",  -- db:8683
[151186411] = "Я справді не думаю, що наша ситуація така вже й погана. Я впевнений, що незабаром усе налагодиться і потужність Санвелла буде відновлено. Просто не може бути, щоб все було настільки погано, як усі це змальовують.",  -- db:8684
[78407544] = "Дружба з «Сонячними мандрівниками» окупилася: я маю змогу проводити дослідження з об’єктами, яких можна знайти лише в Замежжя, а вони отримують… мою чарівну особистість і сувору привабливість.",  -- db:8685
[578168197] = "Ти вважаєш, що я жорстоко поводжуся з цим черв’яком?$B$BЦього місяця вони вбили двох моїх людей!  Ми занадто лагідні до цієї жалюгідної наволочі.",  -- db:8698
[352762363] = "Ласкаво просимо до селища Фейрбріз.  Сільвермун практично знехтував нами, але ми не збираємося звідси йти.  Це наш дім.",  -- db:8699
[574520868] = "Моя робота полягає в одному-єдиному завданні: забезпечити безперебійну роботу Західного Святилища.$B$BПрошу вибачити за мій запал, але, як ви бачите, ситуація тут трохи вийшла з-під контролю.",  -- db:8700
[297727861] = "Чи можуть за цим стояти саботажники з числа нічних ельфів?  Сумніваюся.  З огляду на те, як ми навантажували Західне Святилище, це було лише питанням часу, коли щось піде не так.",  -- db:8700
[948192627] = "Після загибелі Імператорів магічний захист, що блокував телепортацію всередині храму, значно ослаб. Якщо ви бажаєте, я можу перенести вас до лігва Імператорів.",  -- db:8701
[766631643] = "Тепер, коли Оуро вбитий, шлях до останньої кімнати вільний. Якщо бажаєте, я можу перенести вас туди.",  -- db:8702
[386713710] = "Насолоджуєшся фестивалем, $c?$b$bПоки «Стражі Вогню» доглядають за вогнищами сьогодення, я, як історик, зберігаю спогади про минулі фестивалі. Звісно, я також документую цьогорічні урочистості. Поки що все йде добре, чи не так?$b$bЗнаєш, $n, у всіх святкових вогнищах, що палають протягом усього свята, криється сила. Ми дбаємо про свої, але я впевнений, що священні полум’я палають і в глибині міст наших ворогів...",  -- db:8703
[12514661] = "Якщо ти шукаєш роботу, $c, бери кирку й берися за копання. Там руїни простягаються, скільки око сягає!",  -- db:8712
[554505197] = "Вітаю, $N. Ми з моїми побратимами, Синами Лотара, вже майже двадцять років застрягли на цьому жалюгідному світі. Ми трималися, як могли, але мене досі дивує, що загрози, з якими ми стикаємося сьогодні, — це лише тіні наших минулих невдач.$B$BМожливо, ти допоможеш нам спокутувати їх?  $B",  -- db:8713
[665698737] = "Масштаби корупції в Аутленді справді вражають, $c. «Коло Сенаріону» сподівається з’ясувати, як цим істотам вдалося вижити. Дослідження цієї зруйнованої, змученої землі та її мешканців може ще навчити нас, як зцілити хворі частини нашого власного світу.",  -- db:8715
[686996003] = "Ти виглядаєш розгубленим, $c. Не змушуй мене відправляти тебе працювати на будівництво стін разом з іншими роботягами.",  -- db:8717
[324196825] = "Радий бачити тебе, $c. Твоє прибуття до Тралмара не могло статися в більш вдалий час. Вождь розраховує на нас, оскільки сам не може бути тут.",  -- db:8718
[431731849] = "Тралмар потребує тебе, $c. Вождь потребує тебе. Будь готовий виконати свій обов’язок.",  -- db:8719
[460516071] = "Лише небагато поєдинків виграються завдяки одній лише силі. У кінцевому підсумку перемогу приносять хитрість, рефлекси та знання своєї зброї.",  -- db:8724
[125391336] = "Ще один герой? Доля сьогодні нам посміхається, $N.",  -- db:8733
[495959714] = "Я чув дещо про твої подвиги, $N.  Я знаю, що, перебуваючи тут, у Занедбаних землях, ти поводитимешся гідно, як справжній герой син’дореї!",  -- db:8740
[286841591] = "Вітаю вас, $c.",  -- db:8750
[735554113] = "У мене немає часу на пусті балачки, $c. Я мушу подбати про паломників і переконатися, що вони готові до довгої подорожі, яка їх чекає.",  -- db:8751
[476483517] = "Ласкаво просимо до «Falcon Watch», $c. Я дбаю про потреби паломників і допомагаю їм продовжувати їхню довгу подорож. Якщо ви ще не вирушили у паломництво, я можу надати вам необхідну інформацію.",  -- db:8752
[455568906] = "Завжди йди у Світлі, $N.",  -- db:8754
[798705044] = "Ласкаво просимо до «Фарстрайдер Ретріт». Ми — рейнджери, які присягнули захищати наш народ від ворогів як зблизька, так і здалеку.",  -- db:8755
[134911747] = "Мені здається, я починаю шкодувати, що вирушив у це паломництво. Я передбачав, що дорога буде важкою, і подорожі для мене не в новинку, але я не був готовий до суворих випробувань Аутленду.$B$BНа додачу до всього, цей Талеріс, здається, хоче вигнати мене звідси, перш ніж я повністю відновлю свої сили.",  -- db:8756
[549575706] = "О... я тебе знаю?",  -- db:8759
[891111774] = "Вибачте, я не спілкуюся з прислугою.",  -- db:8759
[295459549] = "А ви хто?",  -- db:8759
[687439201] = "Боюся, ви мене сплутали з кимось, хто хоче з вами поговорити.",  -- db:8759
[860738767] = "Привіт, $N!  Тобі подобається вечірка?",  -- db:8760
[535879043] = "Привіт усім, це $N!",  -- db:8760
[217050360] = "У цьому колі новини поширюються швидко. Дякую за поповнення запасів!",  -- db:8760
[261280023] = "Ця вечірка — просто найкраща!  Ти з цим згоден?",  -- db:8760
[860307954] = "Обов’язково спробуйте закуски «Springpaw» — вони просто неймовірні!",  -- db:8760
[334172800] = "Хм... Мені здається, цьогорічний «Suntouched Special» все-таки не такий вже й особливий. Ти з цим згоден, $N?",  -- db:8760
[344930461] = "Я чула чутку, що сьогодні ввечері ми всі підемо дивитися битву зі «Скорб’ю» на кордоні. Як це чудово й розпусно!",  -- db:8760
[636730047] = "Ти можеш повірити, яка нахабна ця Елісара Санстрайкер?  Думає, що зможе привернути увагу лорда Салтеріла?  А ти бачив, у що вона одягнена?  Таке вже минулорічне.  Справді, це сумно.",  -- db:8760
[169562394] = "Мені вдалося загнати себе в досить скрутне становище. Далекозорий Регулкут намагався мене попередити, але моя необережність зрештою далася взнаки.$B$BI Я спустився сюди, щоб дослідити руїни Зет’Гора, але по дорозі зіткнувся з Легіоном. Тепер єдине, що мені від цього залишилося, — це гидка рана на нозі.",  -- db:8767
[49250571] = "Цей випромінювач мене доводить до сказу! Мені не вистачає всіляких деталей, необхідних для його ремонту.",  -- db:8775
[208415042] = "$N!  Ще раз дякую за допомогу.",  -- db:8776
[377938945] = "Ні, ці ремонтні роботи ще не закінчилися. Але це вже не надовго.",  -- db:8777
[92328208] = "Привіт!  Дуже приємно познайомитися!",  -- db:8787
[936060949] = "Вітаю.  Ви тут, щоб допомогти?",  -- db:8788
[800266244] = "Просто пам’ятай, $N, у наших інтересах, щоб ти зробив якомога більше для цих… цих людей.",  -- db:8789
[12227265] = "Вітаю, $r! Сподіваюся, у тебе сьогодні все добре?",  -- db:8790
[68824578] = "Є якісь новини з дому, $c?",  -- db:8791
[971724287] = "Доброго дня. Сподіваюся, у вас сьогодні все добре?",  -- db:8794
[46724873] = "Так приємно побачити ще одного брата чи сестру з си'ндорей $g! Як ви можете собі уявити, розмов тут не надто багато.",  -- db:8795
[19020420] = "Дуже приємно, що ви знайшли час поговорити зі мною. Будь ласка, допоможіть Альянсу всіма можливими способами.",  -- db:8797
[405180273] = "Хоча ми можемо багато чого навчити інші раси Альянсу, нам є чому повчитися й у них. Будьте пильними, уважними та відкритими, $c.",  -- db:8799
[692743694] = "Слава тобі, $c.",  -- db:8800
[139564830] = "Хіба це місто не прекрасне, $c?  Мені так приємно, що ми знайшли таких чудових друзів серед цих нічних ельфів.",  -- db:8801
[677596634] = "Вітаю,  я — Віндікатор Паланаар, мандрівний паладин Світла.  Я прибув сюди, щоб допомогти нічним ельфам.",  -- db:8802
[650241437] = "Я щиро сподіваюся, що нам вдасться принести Світло в ті місця Ашенвейлу, де воно було покинуте.",  -- db:8803
[597041374] = "Це буде так весело!  Ти так не думаєш, моя люба?",  -- db:8805
[104093119] = "Це Баландар Брайтстар відправив тебе, щоб ти мене врятував?",  -- db:8808
[771366355] = "О, чудово! Це було дуже весело, чи не так? Потроху я знищую все більше цих огидних Загублених. Незабаром я буду готовий спробувати це на драенах!",  -- db:8809
[707409474] = "Нехай духи ведуть тебе, $r.",  -- db:8810
[436098343] = "Сили кланам, $c!  Що тебе сюди привело?",  -- db:8811
[719556474] = "Ти завжди бажаний гість серед нас, $c.  Принаймні поки що.",  -- db:8813
[464631532] = "Хіба це не чарівно! Як тобі вдалося вибратися з Долини? Можливо, тобі варто повернутися туди, поки хтось не відправив за тобою пошукову групу.",  -- db:8821
[337672364] = "У мене більше немає для тебе роботи, $N. Але я хочу, щоб ти знав: той червоний окунь, яким ми поділилися, був чимось особливим, і я ніколи цього не забуду...",  -- db:8822
[406812273] = "Звісно, у мене є для тебе робота! Ми завжди шукаємо мисливців. Сподіваюся, тобі пощастить більше, ніж тим драенам, яких нам довелося відправити назад до Екзодару — на поховання.$B$B<Актеон сміється.>$B$BЯ жартую! Ти б бачив вираз свого обличчя. Їх відправили назад до Екзодару для лікування незначних поранень. Нічого такого, від чого б вони не одужали...",  -- db:8823
[341748338] = "Повертайся до свого народу і скажи їм, щоб вони надіслали до мене одного з ваших шаманів.",  -- db:8824
[450875839] = "Повернися до драені та скажи їм, щоб надіслали мені одного зі своїх шаманів.",  -- db:8825
[342629487] = "Чи достатньо тобі розуміння, щоб продовжувати, шамане? Чи знаєш ти, чому ти тут?",  -- db:8827
[432982967] = "Це чудовий день, щоб просто жити й бути в гармонії з природою.",  -- db:8829
[634829767] = "І навіщо мені з вами розмовляти, $r?",  -- db:8830
[255740416] = "Не лякайтеся... хоча мої грифони, можливо, й не зовсім живі, вони все одно вірно доправлять вас до місця призначення. Скажіть мені... яку вежу ви шукаєте?",  -- db:8834
[481783300] = "Я обов’язково помщуся!",  -- db:8836
[941375935] = "Доброго дня.  Що привело вас сьогодні до табору «Чілвінд»?",  -- db:8846
[86830085] = "Доброго дня, $c.$B$BЯ чекаю на відповідь від одного з радників Верховного Тана щодо аудієнції. Мені довелося докласти чимало зусиль, щоб отримати можливість пред’явити свої повноваження.$B$BI’ve heard the Wildhammer described as ‘wary of outsiders,’ but that’s proven to be quite an understatement.  Сподіваюся, ситуація покращиться, коли я матиму нагоду зустрітися з Фетербеардом, який, як мені сказали, виступає за тісніші зв’язки з Альянсом.",  -- db:8847
[758796772] = "Чого ти хочеш?$B$BПідходити до незнайомців без приводу — це трохи грубо, чи не так?",  -- db:8848
[771863851] = "Нехай світло буде з тобою, $c.",  -- db:8851
[360874146] = "Схоже, допомога нарешті прибула!  Мешканці Оменаї вітають вас у нашому таборі вцілілих, $N.",  -- db:8852
[83780114] = "Вітаю, $N. Я — Ландро Лонгшот, керівник «Чорного полум’я». Можливо, досі ти не чув про «Чорне полум’я». Це мене не дивує — ми робимо все, щоб так і залишалося. Ми воліємо уникати… вплутування у фракційні суперечки.$B$B«Чорне полум’я» спеціалізується на наданні найкращих послуг та розваг, які можна купити за гроші, — чи то рідкісні товари, чи то гладіаторські бої, чи то прибуткові азартні ігри.$B$BВи шукаєте тут щось конкретне?$B",  -- db:8855
[720521149] = "Ах — дивацтва та раритети. Ми спеціалізуємося на найунікальніших предметах Азерота для вибагливих мандрівників.$B$BОскільки ви звертаєтеся до мене, ви, мабуть, уже маєте уявлення про те, що саме шукаєте. Тож, $N, який предмет вас цікавить?",  -- db:8856
[997066396] = "Тобі щось потрібно, $c?  Можливо, я зможу тобі допомогти.",  -- db:8858
[300499728] = "<Жриця Ільдінаре підозріло дивиться на тебе.>",  -- db:8861
[8988462] = "Я — нічний ельф, незнайомцю. Хоча ти, можливо, нічого не знаєш про мій народ, ми ж багато знаємо про тебе та твоїх предків. Ти, можливо, не називаєш себе ередаром, але за зовнішністю у вас багато спільного.$B$BТи допоміг моїм союзникам, і за це я тобі вдячний; але наразі ти йдеш по хиткому шляху. Можливо, з часом тобі вдасться розвіяти сумніви та побоювання, що таїться в моєму серці.",  -- db:8862
[589222632] = "Досі ти дуже допоміг, $N. Тобі варто було б допомогти й іншим мешканцям табору.$B$BІ не переймайся через тих гоблінів — я про все подбаю.",  -- db:8865
[488058275] = "Радий знову бачити тебе, $N. Можливо, коли все трохи заспокоїться, я зможу поговорити з тобою про той безцінний скарб, який ми втратили...",  -- db:8866
[18992372] = "На що ти дивишся?",  -- db:8867
[702854345] = "Я — Адамант Айронхарт із великого міста Айронфордж. Як ви, мабуть, здогадалися, поглянувши на мою форму, колись я був членом елітної гвардії Айронфорджа. Так, я був правою рукою Магні! Принаймні доти, доки не пішов у відставку. Зараз я займаюся археологією. Це, власне, просто хобі; до того ж я вирішив, що це чудовий спосіб побачити світ!",  -- db:8868
[331774063] = "<Коулен ридає.>",  -- db:8869
[872171500] = "Що я міг зробити, щоб дати богам привід обрушитися на мене з такою люттю? Усе, що мені було дорого, зникло — загинуло або було знищено. Мою родину відібрали у мене лісові звірі. Мій дім зрівняли з землею. Мій корабель затонув.$B$BЯ — зломлена людина, що опинилася на зруйнованому острові.$B$BМожливо, ти тут, щоб довершити справу? Зроби це швидко, я не чинитиму опору. Забери моє життя, незнайомцю; я надто боягузливий, щоб зробити це сам. Моя рука тремтить… лезо не влучить у ціль.$B",  -- db:8870
[517935587] = "Якщо не боги, то хто? Як? Що могло спричинити таку ворожнечу?",  -- db:8871
[606806254] = "Легіон? Демони? Вони полюють на тебе? На мій народ теж полював Легіон: їхні темні повелителі прагнули приректи нас на прокляття.$B$B<Коулен витирає сльози.>$B$BСаме тому я переїхав сюди зі своєю родиною ще дуже-дуже давно.",  -- db:8872
[23361281] = "Вітаю, $c. До того, як нічні ельфи запросили драені приєднатися до них тут, ця галявина була практично забута.$B$BКалдорей тісно пов’язані з цими землями, і для нас, драені, велика честь, що вони попросили нас долучитися до відродження «Лісової пісні».",  -- db:8873
[522163355] = "Приємно бачити тут нове обличчя. Наш форпост невеликий, а ворогів багато. Ми оточені тими, хто прагне нас знищити: сатири на заході, орки з лісозаготівельного табору «Військова пісня» на півдні та демони з Пагорба Фелфайр.$B$BМи вдячні драенам за те, що вони прийняли наше запрошення приєднатися до нас у зміцненні «Лісової пісні» проти цих незліченних загроз.",  -- db:8874
[14359015] = "Приємно знову чути тут, у «Лісовій пісні», голоси інших. Я вже почав відчувати, ніби я — останній із калдореїв, який коли-небудь побачить ці землі перед тим, як вони поринуть у розпад.",  -- db:8875
[199659407] = "Чи відчуваєте ви зло, що насувається з півдня?  На ім’я Руки, його треба знищити!",  -- db:8876
[554086681] = "Маючи вас і ваш народ як союзників, ми вирішили залишитися на цьому острові й відбудувати його. Нехай Елуна благословить вас, герою.$B$BХоча смуток і досі час від часу навідується, я думаю, ми виживемо.$B",  -- db:8880
[956383570] = "Ти ж $r, так?  Мені дуже приємно бачити тебе тут!  Нам знадобиться будь-яка допомога, яку ми зможемо отримати.",  -- db:8881
[928564540] = "Треба вбити демонів, $c.  Чи вистачить тобі мужності зробити те, що треба?",  -- db:8883
[158836082] = "Оскільки значна частина їхніх демонів знищена, Легіон двічі подумає, перш ніж знову напасти на наш лісозаготівельний табір.  Проте я все ще відчуваю, що демонічне зло не затихає.",  -- db:8887
[17876062] = "Слава величному герою!",  -- db:8893
[16499168] = "Історія вашої подорожі буде розповідатися ще багато років!",  -- db:8893
[833794963] = "Нарешті у мене з’явилася історія, яку я зможу розповісти своїм онукам… Серед нас жив зрадник королівства!$B",  -- db:8893
[281219502] = "Чесно кажучи, мені цей гном ніколи не подобався...",  -- db:8893
[837736028] = "Нам пощастило, що ми пережили це випробування. Якби не ти, всі мешканці цього острова могли б загинути!",  -- db:8893
[215338367] = "Цікаво, скільки ще таких, як він, живе серед нас. Я знав Спарка роками — ніколи б не подумав, що він зрадник.",  -- db:8893
[356227787] = "Ласкаво просимо до «Forest Song», $c. Якщо я можу чимось вам допомогти, будь ласка, дайте мені знати.",  -- db:8939
[347549705] = "<Лакей стоїть непохитно, напруживши м’язи.>",  -- db:8952
[679176547] = "Що привело тебе аж сюди, маленький $r?",  -- db:8954
[146520349] = "Вітаю, $c.  До мене сюди так мало хто заходить.  Чим я заслужив таку честь?",  -- db:8956
[16871440] = "Я чекав на вас.",  -- db:8959
[6728867] = "Залиш мене в спокої. Мені немає чого сказати таким, як ти.",  -- db:8960
[440534941] = "Говори тихіше, $c!",  -- db:8962
[945653653] = "Якщо у вас є що сказати, то кажіть!",  -- db:8962
[713336881] = "Ти — цивільна особа з $T: цивільна особа;?",  -- db:8962
[471714399] = "Я зайнятий, давай швидше!",  -- db:8962
[421901590] = "Як просувається ваш пошук Марка?",  -- db:8964
[305218745] = "Це чудовий день, $c!",  -- db:8965
[523670176] = "Я не можу висловити вам свою вдячність за те, що ви зробили моє паломництво можливим!",  -- db:8966
[619934317] = "Здається, заражені карлики-нічні мисливці наближаються з півночі. На твоєму місці я б саме звідти й розпочав полювання.",  -- db:8974
[955016016] = "Ого, ти там геть провалився. Давай вважатимемо це репетицією, гаразд? Готовий вийти ще раз?",  -- db:8975
[561589023] = "Публіка не з тих, що легко піддаються, але ти зможеш її завоювати. Готовий спробувати ще раз?",  -- db:8981
[167503477] = "Чим можу вам допомогти, незнайомцю?",  -- db:8990
[306155893] = "Мене звати Гурф, незнайомцю. Гурф Сміливий!",  -- db:8991
[558043930] = "Я — Мурдо, найстарший мисливець із Стілпайна.",  -- db:8992
[858666939] = "Боюся, що зараз я досить зайнятий ремонтом підків. Чи не могли б ви зайти іншим разом?",  -- db:9002
[186731938] = "То ти знаєш про «Фіолетове око»?  Може, пізніше я знайду для тебе час.$B$B Мені треба повертатися до роботи.",  -- db:9004
[162941850] = "<Схоже, Ералан жує якусь смертоносну траву.>$b$bЯкщо ти хочеш приготувати любовне зілля, то потрапив не за адресою.  Засліплювати, калічити й вбивати — це моя справа, і, сподіваюся, твоя теж.",  -- db:9005
[246362225] = "Я відчуваю твоє прагнення до влади, $c.",  -- db:9006
[949964191] = "Світло дарує нам силу та магію, щоб перемогти.",  -- db:9007
[787604991] = "Ласкаво просимо до Реєстру гільдій.  Чим можу вам допомогти?",  -- db:9008
[104669314] = "Привіт, дитинко.",  -- db:9009
[412151782] = "Щоб краще тебе чути, дитино.",  -- db:9010
[359482119] = "Щоб краще тебе бачити, дитино моя.",  -- db:9011
[839475597] = "Разом ми впораємося з цією проблемою забруднення води.",  -- db:9015
[100461316] = "Ти зробив чудову справу, $N.  Ти завжди ласкаво запрошений сюди.",  -- db:9016
[272161440] = "Прийшли за приладдям для ковальства, так?",  -- db:9019
[855375886] = "У мене є свіже м'ясо, риба та гриби.  І випивки вдосталь!",  -- db:9020
[604960253] = "Усе, що сталося після катастрофи, здається мені лише розмитим спогадом. Здається, ніби минуло ціле життя з того часу, як я перебував на борту «Екзодара».$B$BЗараз моя реальність обмежується цим островом із його мутантами та нескінченним морем агентів кровних ельфів. Незабаром мені здаватиметься, ніби я ніколи й не знав нічого іншого...",  -- db:9034
[160951364] = "Дякуємо за попередження, $N! Ми підготуємося!",  -- db:9038
[959774909] = "Обіцяний, ми дякуємо тобі за попередження. Плем’я Стілпайн буде готове.",  -- db:9039
[590353857] = "Дякуємо за попередження, $N. Ми підготуємося до оборони.",  -- db:9040
[225478969] = "Що означає бути «Рукою Аргуса»... Ми — слуги Світла. Ми служимо беззаперечно. Ми гинемо беззаперечно.",  -- db:9044
[152716227] = "Тебе послали мене знайти? Ну, я не повернуся без своїх людей.",  -- db:9045
[838486205] = "Так, я — один із «Зламаних». Сподіваюся, це вас не турбує? Будь то «Зламані» чи драені, нам доводиться терпіти глузування, з якими іноді стикаються деякі з нас у нашому суспільстві. Головне — це краще розуміння та взаємодія з елементами цього світу.",  -- db:9050
[452578242] = "Ти що, з глузду з’їхав? Поглянь навколо, смертний. Хіба ти не бачиш, що стоїш на розколотій землі? Залиш це місце, інакше тобі доведеться страждати так само, як страждали я та мій народ...",  -- db:9056
[74782110] = "Ти що, не тільки божевільний, а й сліпий?$B$BЯ — привид — жорстоке нагадування про цивілізацію, яка вже давно перестала існувати, — прив’язаний до землі, яку мені не вдалося захистити.$B$BДавно — десять тисяч років тому — я був з плоті й крові, так само, як і ти. Я був принцом цієї землі та вершником драконів, благословенним Ісерою Сну.",  -- db:9057
[878255246] = "Хіба ти не чув про Ісеру? Охоронницю природи? Аспект Сну? Вона — покровителька всіх зелених драконів! Так, саме сама Ісера подарувала моєму королівству своє потомство. Ми стояли пліч-о-пліч із цими благородними створіннями, і вони дозволили нам верхи на них вирушити в бій проти наших ворогів. Усе було добре протягом багатьох століть… аж доки…",  -- db:9058
[454701443] = "Потомство Десвінга... Доброзичливість Ісери викликала гнів Десвінга — покровителя Чорного драконячого полку. Вони напали на нас, коли ми спали! Багато хто загинув під час першої хвилі атаки, але зелені дракони піднялися, щоб захистити нас.$B$B<Принц Торет вказує на острів.>$B$BВід колись величних драконів залишилися лише кістки. Жоден з них не вцілів.",  -- db:9059
[409353244] = "Я загинув останнім. Коли я відчув, як моя душа покидає мою смертну оболонку, я склав клятву на крові.$B$B<Принц Торет хитає головою.>$B$BA між цією землею та мною було укладено угоду: моя кров за цей світ. Я став єдиним хранителем історії свого народу.$B$BЯ не зможу спочивати, доки не буду впевнений, що історія вершників драконів Лорет’Арана не загубиться в глибинах часу.",  -- db:9060
[352715590] = "Студенти трохи схожі на овець. Вони корисні й навіть симпатичні, коли їх направляєш і приділяєш їм пильну увагу.$B$BАле варто залишити їх на хвилину без нагляду — як вони одразу ж падають зі скелі або тонуть у неглибокій річці.",  -- db:9061
[385593849] = "На цій дошці розміщено різні оголошення та повідомлення про винагороди за виконання завдань, що звучать досить небезпечно. Нічого особливого не привертає вашу увагу; можливо, варто перевірити ще раз пізніше.",  -- db:9062
[1258588] = "Вітаю, громадянине. Прошу вас піти, якщо вам немає до мене ніяких питань.",  -- db:9063
[655973947] = "Маршал Віндзор чекав на вас, $N. На жаль, зараз він зайнятий. Він має незабаром повернутися.",  -- db:9064
[894941019] = "Ви це зробили! Чудово! Маршал Віндзор чекає на вас. Хочете, щоб я зараз попередив його?",  -- db:9065
[165170769] = "Слава тобі, чемпіоне. Про твої подвиги розповідатимуть упродовж століть. Можливо, одного дня твоя статуя стоятиме серед героїв Штормовію.",  -- db:9066
[410668926] = "Тримайся від мене подалі, $r! Невідомо, коли хвороба знову мене наздожене.$B$BПросто залиш мене в спокої, поки це не сталося знову.",  -- db:9067
[442886374] = "Оглянувши труп, ти приходиш до висновку, що це, мабуть, «Кривавий лицар» Доунстар — ватажок невдалого штурму Десхолма.",  -- db:9070
[92616402] = "Під час обшуку одягу та спорядження трупа ви знайдете потрібні вам знаки розрізнення, які не постраждали ні від бою, ні від несприятливих умов навколишнього середовища.",  -- db:9072
[5681488] = "Нехай благословення Елуни буде з вами.  Чим я можу допомогти?",  -- db:9073
[141713747] = "Вітаємо, $c.  Ми раді, що ви вирішили завітати до нас.",  -- db:9074
[392928883] = "Вітаю, $c. Я — Курос, другий із Тріумвірату Руки.",  -- db:9077
[774272559] = "Я дивився, як вони безжально його били. Їхній безжалісний лейтенант поводився так, ніби така жорстокість — це цілком нормальне явище. Під час цих жорстоких побоїв я відчував, як ламаюся.$B$BДивлячись, як Захисник Саруан приймав їхні удари, я почав плакати. Не від страху... Я плакала від смутку. Від того, що з драені з Тріумвірату поводилися таким чином. Якби ж я тільки могла звільнитися від своїх пут. Якби ж...$B",  -- db:9079
[540346309] = "Через те, що здавалося вічністю, «Захисник» втратив свідомість. Тортури виявилися занадто важкими навіть для нього. Той жорстокий — Матіс, як я дізнався, його звали — спробував привести Саруана до тями, обливши його понівечене тіло водою, змішаною з інфекцією. Але Саруан не прокинувся.$B",  -- db:9080
[721849456] = "Я хотів закричати, але з моїх губ вирвався лише тихий стогін. За цей акт непокори мене негайно побили. Лежачи на землі, я бачив, як Матіс ходив туди-сюди перед тілом Саруана. Він виглядав явно стурбованим. Він заявив, що Сіронас чи Сірона, чи якась подібна істота здерла б з нього шкіру до кісток, якби Саруан загинув від побоїв. $B",  -- db:9081
[971084043] = "Те, що організація «Сіронас» мала плани щодо Саруана... $B$B<Текст раптово обривається, і довгий рядок зникає зі сторінки. Цей драені загинув під час написання цього запису.>$B",  -- db:9082
[792872257] = "Почніть пошуки на півночі, $N. Наші розвідники виявили «Варп-поршень» поблизу берегової лінії.",  -- db:9097
[712594822] = "Якби наші вороги зрозуміли, що ми лише прагнемо жити з ними в злагоді, то, можливо, нам не довелося б нападати на них, щоб вижити?",  -- db:9106
[162638097] = "Їхній час ще настане, $N.$B$BІ коли це станеться, я буду там.",  -- db:9107
[954139851] = "Оскільки нові вороги вже на порозі, ми не повинні дозволити нашим давнім ворогам скористатися нашою ситуацією!",  -- db:9108
[444529549] = "Ти можеш повірити, що це таке місце?  Звісно, якщо мене запитати, то тут трохи задушливо.",  -- db:9109
[856993238] = "Скажи, ти, бува, не бачив ту арку в озері на заході? Цікаво, куди вона веде? Треба б мені там попірнути.",  -- db:9110
[992824918] = "Якби тільки я не підвернув ногу, коли заходив сюди, я б зараз був там разом із друзями. Хм, а якщо добре подумати, може, краще, що я тут, зовні?",  -- db:9112
[682452515] = "Фхуор любить маленьких спорелінгів.  Вони рятують Фхуора.  Не їдять їх.$B$BFхуор ненавидить нагу.  Фхуор розтрощить!",  -- db:9113
[55881916] = "Я — Есом, третій із Тріумвірату.",  -- db:9117
[381048571] = "Тут спочивають останки Відера Грінтумба, одного з друїдів-супутників Спостерігача Джанга. Судячи з усього, його вбили швидко й безжально, коли він намагався втекти з Рабських кліток.",  -- db:9118
[32733555] = "Мені майже вдалося!$B$BЯ прийшов сюди, щоб довести існування Квагміррана — того найлегендарнішого з грибних велетнів.  Моє бажання здійснилося — так би мовити.$B$BВи мусите мене звільнити!  Натомість я надам вам благо, яке допоможе вам впоратися з Квагмірраном.",  -- db:9119
[35648575] = "Слава богу, що ти тут!  Ми з Клоу досліджували це місце, коли на нас напав володар боліт Муселек.  Він може керувати тваринами, навіть друїдами!$B$BНа жаль, Клоу в той момент застряг у вигляді ведмедя і тепер став улюбленцем володаря боліт.  Я не наважуюся перетворитися на кота, інакше він схопить і мене теж!$B$BБоюся, тобі доведеться битися з Клоу, щоб врятувати його.  Просто продовжуй рухатися на захід — ти його не пропустиш.",  -- db:9121
[484329692] = "Оскільки я, мабуть, єдиний, хто вижив із «Зламаних», для мене є і обов’язком, і честю продовжувати шаманські вчення Далекоглядного Нобундо.",  -- db:9122
[543415354] = "Хай їм грець, цим кровним ельфам та їхній безрозсудній магії!",  -- db:9123
[354173490] = "Не марнуйте мій час.  Чого ви хочете?",  -- db:9124
[113688507] = "Хіба ти не бачиш, що я тут зайнятий?",  -- db:9124
[5922513] = "Так?  Чого ти хочеш?",  -- db:9124
[274155692] = "А ви хто?",  -- db:9124
[210391680] = "Нехай Світло підкоряється вашій волі у всіх ваших починаннях.",  -- db:9127
[772467889] = "<Затриманий агент «Санхок» підозріло дивиться на тебе.>$B$BI Я тебе ніколи раніше не бачив. Хто ти такий?",  -- db:9136
[384189320] = "Я терпляче чекаю на замовлення, $c.",  -- db:9143
[633581589] = "Оскільки це грубе переривання вже закінчилося, як я вже казав, Квагмірран знаходиться неподалік!$B$BЯк і обіцяв, я можу наділити вас магічним благословенням, яке має допомогти вам у боротьбі з ним.",  -- db:9144
[217739261] = "[На ламаній загальній мові] Настав час святкувати.",  -- db:9145
[544938793] = "Ти пройшов довгий шлях, $N. Справді довгий шлях... Але я знав, що тобі судилося досягти великих висот. Ми всі це знали. Слава $N!$B$BІ ще раз дякую за те, що вирішив нашу проблему з гномами...",  -- db:9149
[14205704] = "Я хотів би ще раз подякувати тобі за те, що ти для мене зробив. Ти надав мені сміливості, щоб відвоювати свій дім у лісових звірів. І завдяки цьому я знайшов Магвіна!",  -- db:9160
[628914733] = "Серед нас перебуває чемпіон драені. Це свято на честь рятівника Азурміста та Бладміста!",  -- db:9162
[494332802] = "Я не маю уявлення, хто ти, але дуже радий, що ти тут. Архімонд і його армія «Покарання» можуть атакувати в будь-який момент, $C. Чи станеш ти разом з нами протистояти цьому злу?",  -- db:9168
[472958240] = "Дякую, $R. А тепер готуйтеся. Архімонд наступає, і ми мусимо відтермінувати неминуче, скільки зможемо.",  -- db:9169
[591507854] = "Ми маємо триматися, скільки зможемо! Борімося далі!",  -- db:9170
[949828591] = "Я — керівник оборони «Кривавої варти». Чим можу вам допомогти?",  -- db:9172
[309689254] = "Привіт, ви завітали сюди, щоб дізнатися про конфлікт у Бладмісті?",  -- db:9172
[987267146] = "Ми беззаперечно служимо Світлу. Можливо, вам цікаво дізнатися трохи більше про нашу мету?",  -- db:9172
[305148822] = "[Недосконалим загальним мовою] Стілпайн, будь готовий! Дуже дякую!",  -- db:9173
[229773717] = "Ласкаво просимо до штаб-квартири «Кривавих лицарів» — захисників Кель'Таласа, вірних слуг Срібного Місяця та справжніх володарів Світла.",  -- db:9174
[77653336] = "Як мої люди можуть воювати, коли стихії перебувають у такому хаосі? Хіба вони не бачать, що без підтримки стихій світ просто не може існувати?",  -- db:9182
[920846376] = "У мене зараз немає часу на проповіді, $c. Шукай знання деінде.",  -- db:9186
[542302510] = "Схоже, ти помилився, $c.",  -- db:9187
[74575088] = "Вітаю, $n. Сподіваюся, за тобою сюди ніхто не стежив?",  -- db:9188
[611590130] = "Нам, $c, майже немає про що говорити. Можливо, тобі варто пошукати інших людей, які більше поділяють твої погляди.",  -- db:9189
[241806426] = "Приємно бачити тут когось розсудливого. Чим можу допомогти?",  -- db:9190
[670476575] = "А, колега-рейнджер. Що тобі потрібно?",  -- db:9190
[74280809] = "Тобі явно бракує здібностей, щоб осягнути тонкощі таємного, $c. Забирайся геть.",  -- db:9191
[116764377] = "Чим я можу допомогти вам у навчанні?",  -- db:9192
[814181114] = "Наш шлях — для тих, хто має залізну волю та непохитну рішучість. Схоже, ти не володієш жодною з цих рис, $c.",  -- db:9193
[810554677] = "Нехай вітри ведуть тебе, $N.",  -- db:9196
[394964720] = "Ця книга містить інформацію про види рослин Аутленду.  Більшість описаних рослин є ендеміками Зангармаршу.$B$BТаблиці та діаграми дещо виходять за межі вашого розуміння.  Можливо, автор міг би дати вам кілька підказок.",  -- db:9197
[250188602] = "Мені завжди подобалося сортувати й упорядковувати речі.  Мабуть, я це успадкувала від мами.",  -- db:9199
[46748733] = "Вивчення нових видів рослин має надзвичайно важливе значення для нашої експедиції. І мова йде не лише про лікарські чи їстівні рослини.$B$BРослини є основою існування багатьох інших форм життя. Розуміння їх дозволяє нам краще осягнути природу в цілому.",  -- db:9199
[895074984] = "Завдяки тобі наші діти будуть у безпеці, $N.  Відправляйся до Спореггара і познайомся з моїм народом.  Всі вони чули про тебе тільки найкраще.",  -- db:9204
[401182411] = "Захисники «Кривавої Варти» захищають цей форпост від будь-якої загрози.",  -- db:9206
[412171657] = "«Захисники» прибули, щоб захистити «Блад-Вотч» від загрози з боку «Санхока».",  -- db:9206
[566177995] = "Нещодавно до нас дійшла звістка про те, що поблизу «Векторної котушки» було прикликано істоту, наділену величезною силою. Не бійтеся: якщо щось загрожуватиме місту, ми віддамо свої життя, аби його захистити.",  -- db:9206
[453917920] = "$N!  Я надто добре пам’ятаю твої мисливські здібності.  Може, у Странглторні ти й почав не дуже впевнено, але ти не здався і став одним із найкращих, коли вполював старого Бангалаша.$B$BАле послухай, $g хлопче : дівчино;, здобич тут, у Замежжя, — це щось справжнє.  І в мене є шрами, що це підтверджують!",  -- db:9221
[819491018] = "«Палаюча Легіон» чинить на нас сильний тиск, але наша оборона тримається. Кожна мить, протягом якої ми утримуємо Архімонда подалі від Світового Дерева, наближає нас до перемоги.",  -- db:9230
[292984948] = "Не дайте себе обдурити руїнами, що нас оточують, $c.  Даларан як і раніше залишається могутнім.",  -- db:9241
[654365335] = "«Каразан — це більше, ніж просто будівля, $N.  Якби ви простежили енергетичні лінії, що проходять через Азерот, то побачили б, що всі вони сходяться саме там».$B$B<Альтурус вказує на невидиму точку під вежею.>$B$BЦікаво, чи не так?",  -- db:9242
[133672688] = "Архімаг Альварекс колись написав трактат, у якому розглядав захоплюючу теорію. Він висунув гіпотезу про існування точної копії Каразана в іншому світі, відмінному від нашого, і про те, що обидва ці світи якимось чином займають один і той самий простір.$B$BНезабаром після цього він збожеволів. Дуже шкода.",  -- db:9242
[652584003] = "Через слова «РОЗШУКУЄТЬСЯ: Дескло» проведено товсту червону риску. «Цю винагороду отримав героїчний $N, який переміг цю страхітливу тварину», — йдеться в написі, зробленому тим самим червоним чорнилом.",  -- db:9245
[83326377] = "На цій дошці розміщені різні оголошення та повідомлення про винагороди.",  -- db:9246
[833914060] = "Ласкаво просимо до Забра'джина, $c. Я — Тіньовий Мисливець Денджай, наглядач цього форпосту та командувач військ Темного Списа в Зангармарші.",  -- db:9248
[790763451] = "Тільки не думай навіть про те, щоб втекти з моїми маленькими мурлоками! У мене очі яструба, а вуха... вуха... як у когось із надзвичайно гострим слухом!",  -- db:9249
[867768285] = "Тор'гаш вірить, що може передбачити майбутнє, роздивляючись нутрощі птахів або кидаючи кісточки своїх предків. Насправді ж достатньо просто звернутися до духів. Але не намагайся йому це пояснити, $N. Він дуже впертий.",  -- db:9250
[515727114] = "Ти довів, що є дуже вправним мисливцем, $N.  Але є ще одна тваринка, яка не дає тобі спати... Тускер!",  -- db:9256
[204284401] = "Ти вполював їх усіх: Бахлора, Бантара, Гутріппера і навіть могутнього Таскера! Ти справді найкращий мисливець на велику дичину з усіх, кого я знаю!",  -- db:9257
[15003341] = "Коли я вперше побачив гриби, вищі за дерева, я не був упевнений, чи зможу вважати це місце своїм домом. Але з часом просто перестаєш на це звертати увагу.",  -- db:9259
[397347331] = "Не забудьте виділити трохи часу на риболовлю, поки ви перебуваєте в Зангармарші. Ніколи не знаєш, коли знову побачиш воду.",  -- db:9260
[6490626] = "З вершини Телредора відкривається чудовий краєвид, чи не так?",  -- db:9262
[363029431] = "Мисливець за тінями Денджай відправив мене сюди разом із невеликим загоном будівельників і воїнів, щоб заснувати цей форпост. Ми ледь встигли його добудувати, а він уже вимагає звітів!$B$BЯкщо вам потрібні припаси, я можу запропонувати дещо, але ми все ще чекаємо на першу партію поставок.",  -- db:9267
[727710628] = "Якщо ти коли-небудь зустрінеш знахаря Тор’гаша, скажи йому, що його зілля та обереги не діють! Я робила все, як він мені казав, а Магаша все одно дивиться тільки на Зураї.$B$BНе вір нічому, що тобі каже цей шаман-шахрай!",  -- db:9268
[210087794] = "У Реавіджа стільки ж тактовності, скільки у кодо! Найсмішніше те, що він навіть не підозрює, наскільки він передбачуваний. Я бачу, як він на мене витріщається, коли думає, що ніхто не дивиться.$B$BВін мене лякає. Я б дуже хотів, щоб Тіньовий Мисливець Денджай не відправив його з нами. Створення «Болотяного Посту» було ідеальною нагодою, щоб позбутися його.",  -- db:9269
[825851656] = "Гарадар лежить у руїнах, незнайомцю. Відтоді, як Велика Мати захворіла, Гарош впав у глибоку депресію. Він, безперечно, не пішов у свого батька.$B$B<Куркуш зітхає.>$B",  -- db:9271
[542055444] = "Тут наведено оголошення про винагороду за лідерів нагів племен «Темний гребінь» та «Кривава луска».",  -- db:9274
[19780301] = "Вони загинули. Усі до одного...$B$BКоли «Темнокровні» прорвалися крізь наші ряди, мене охопило щось, чого я не можу зрозуміти. Скажи, чи відчував ти коли-небудь таку лють, що вся твоя істота палає? Таке пекло, що висушує все живе? Таке пекло, що спалює кров у твоїх жилах? Саме це я й відчув.$B$B<Очі Саурфанга на мить спалахнули червоним.>$B$BI був останнім, хто залишився живим. Мене оточили 30 з них... «Темнокровні»... Я нічого не пам’ятаю після того бачення. Я знепритомнів і прокинувся лише через деякий час.",  -- db:9275
[529694507] = "Попереду насуваються темні часи, незнайомцю...",  -- db:9276
[711612605] = "Духи дуже схвильовані. Ми мусимо з’ясувати причину цього заворушення.",  -- db:9277
[735889791] = "Хемет — найкращий мисливець, якого я знаю. Ми випадково зустрілися на пагорбах Вінтерспринга в Азероті багато місяців тому.  Ми з ним вистежували одну й ту саму здобич: великого кота на ім’я Рак’шірі.$B$BЗамість того, щоб битися за здобич, ми уклали парі: той, хто здобуде шкуру морозного меча, зможе вимагати від іншого будь-що.  На мою вічну ганьбу, саме так я й отримав прізвисько «Фіц».$B$BХіба я схожий на Фіца?",  -- db:9283
[860680266] = "Могутній мисливець, $N, повертається. Розкажи мені історію про те, як ти вистежував свою останню здобич.",  -- db:9284
[862259959] = "Так, так, мені вже краще, але мені тут, внизу, якось подобається.",  -- db:9286
[210987844] = "Чи знаєш ти, хто ми такі, незнайомцю? Ми — маг'хари — коричневі орки, як, як я чув, називає нас твій народ. Маг'хари — це ті, хто вижив: ті, хто вижив після падіння династії; ті, хто вижив після Червоної віспи; ті, хто вижив у розтрощеному світі...$B$BЯ — Йорін, син Кілрога; останній з роду «Мертвого ока»: вождь клану «Кривавої ущелини».",  -- db:9289
[604539309] = "Ми б не розбилися, якби Хемет навчився не стріляти крізь елерони, коли намагається вполювати дичину на землі!$B$BАле не переймайся, я її швидко полагоджу.",  -- db:9290
[60709761] = "Я ТАК рада, що злий Ганклі Роттенфіст отримав по заслугах!  У мене є багато скінів, якщо хочеш, можеш дати кілька Гарольду.",  -- db:9292
[575650981] = "Велика Мати виховала нас усіх. Життя кожного маг’харі, якого ви бачите, якимось особливим чином торкнулася Велика Мати. Ми будемо дуже сумувати за нею, коли вона піде з життя.",  -- db:9297
[736396249] = "Прабабуся розповідає мені, що мене назвали на честь великого оркського героя.",  -- db:9297
[106763175] = "Ви організуєте низку подій, які змусять орків «Кіл’Сорроу» з фортеці Кіл’Сорроу повірити, що огри «Вармаул» напали на їхню базу, а потім — ще одну серію подій, щоб огри «Вармаул» повірили, ніби орки «Кіл’Сорроу» атакують їхню базу.$B$BЗробіть це — і ви вирішите обидві наші проблеми.$B$B«Боулдерфіст» поверне свою територію, а ваш народ буде захищений від нападів з боку «Боулдерфіст», «Вармаул» та «Тіньової ради».",  -- db:9369
[857382264] = "Особи, які зареєструвалися, зобов’язані проконсультуватися з начальником в’язниці Буллоком перед розміщенням будь-якого завдання.$B$BОсоби, виявлені під час розміщення несанкціонованих оголошень, будуть притягнуті до відповідальності.$B$BЗабороняється розміщувати оголошення.",  -- db:9373
[578860344] = "Якщо шукаєте роботу, загляньте на дошку оголошень, $r.",  -- db:9375
[43452884] = "Вони не поважають померлих, $r. Цим людожерам треба дати урок.",  -- db:9376
[389406131] = "Ми повинні шукати тих, хто вижив. Якщо хтось ще живий, ми повинні хоча б спробувати врятувати його...",  -- db:9377
[961544916] = "Хто ти?  Що тобі тут потрібно?",  -- db:9383
[756492522] = "Чому ти так з нами вчинив?",  -- db:9383
[225956642] = "Там ЧОТИРИ ліхтарі!",  -- db:9383
[186817809] = "Мої люті теромоти помстяться за мене!",  -- db:9383
[810902664] = "Куди всі поділися?",  -- db:9383
[214448492] = "Гості на вечері повинні виявляти більше поваги!",  -- db:9383
[667379019] = "О, яке священне місце тут зруйновано!",  -- db:9383
[944997191] = "Помаж мою голову цілющим бальзамом.  Тобі подобається мій терновий вінець?",  -- db:9383
[479693451] = "Я можу навчити вас майнінгу.  Цікаво?",  -- db:9384
[18988538] = "Я можу навчити вас фітотерапії.  Цікаво?",  -- db:9385
[81173924] = "Неймовірно! Твоя перемога над Анатероном затримала Архімонда на шляху до його мети й наблизила нас до перемоги. Однак мої війська не можуть тут залишатися. Ми з воїнами виснажені, і настав час відступати. Якщо ваші сили ще не вичерпалися, рушайте на схід, до табору Тралла. Саме там ми знову дамо бій. Будьте здорові.",  -- db:9387
[895972560] = "Ми мусимо повернути ті ящики з припасами!",  -- db:9389
[683246027] = "Цей ліс — моторошне місце. Тут повно злих сил не тільки з боку Альянсу, тож будьте обережні.",  -- db:9392
[816515481] = "Орда — не єдина небезпека в цьому лісі. Не дайте себе обдурити його уявним спокоєм.",  -- db:9393
[196885650] = "Зійди з дороги, $r. Хіба ти не бачиш, що ми посеред бою!",  -- db:9395
[735346174] = "Чудово! Вбити такого Володаря Ями, як Азгалор, — це неабияке досягнення, друже мій. Якби у нас було більше часу, я б із задоволенням послухав історію про тебе та твоїх товаришів. Однак Архімонд не дасть нам такої перепочинки. Мої розвідники вже повідомили, що Легіон збирає величезні сили за межами нашого табору, а Архімонд уже зовсім близько до Світового Дерева. Ми евакуюємося за допомогою леді Праудмур. Тобі слід негайно вирушати до Світового Дерева. Доля нашого світу ще не вирішена.",  -- db:9398
[801900570] = "Тут лежить труп одного з «Зламаних».  Дивно, але, судячи з усього, причиною його смерті не стала жодна з мутованих метеликів.$B$BМожливо, це якось пов’язано з дивним предметом, що лежить прямо поруч із його простягнутою рукою?",  -- db:9401
[260413659] = "Вітаю, чемпіоне! Ти коли-небудь замислювався над тим, щоб повністю присвятити себе кар’єрі гладіатора? Ми з тобою могли б заробити цілу гору золота.",  -- db:9403
[378762356] = "Тепер, коли мене побили до напівсмерті, чого ти ще хочеш?",  -- db:9406
[434839043] = "Ми розберемося з цією різаниною, хай це буде останнє, що ми зробимо!",  -- db:9407
[825595211] = "Ми будемо дуже вдячні за вашу допомогу в боротьбі з Палким Легіоном. Леді Джейна Праудмур потребує вашої допомоги на передовій.",  -- db:9408
[683946487] = "Момент, якого ми так боялися, настав, $C. Архімонд дістався до Нордрасіля і почав поглинати енергію Світового Дерева. Малфуріону потрібно більше часу, щоб його план спрацював, тож ми мусимо зробити те, що раніше здавалося неможливим. Ви повинні атакувати Архімонда безпосередньо, поки мої війська стримують потоки військ Палаючого Легіону, що наближаються до вершини гори.",  -- db:9410
[806599554] = "Ласкаво просимо до «Таверн часу»!",  -- db:9414
[687155884] = "Відпочиньте свої втомлені ноги, у нас є ціла вічність...",  -- db:9414
[435342425] = "Можу запропонувати вам випивку? Запевняю вас, вона витримана як ніяка інша!",  -- db:9414
[310560419] = "О ні, тільки не ти знову!  Іди геть!",  -- db:9425
[653044689] = "Ось що я з’ясував на основі інформації, яку ви зібрали під час опитування.$B$BЄ два основних табори кузні: «Табір кузні: Ненависть», що розташований безпосередньо на захід від того місця, де ми стоїмо, та «Табір кузні: Страх», що розташований безпосередньо на південний захід. У кожному таборі є транспортер Легіону, одна кузня та кілька веж захисту від заклинань. Крім того, табори охороняють гнівні вартові, озброєні пекельними гарматами. І нарешті, у кожному таборі є наглядач — володар ями.$B$BГаразд, це не повинно становити жодних проблем...$B$B<Альтруїс сміється.>",  -- db:9427
[111426379] = "Руїни «Двох шпилів» ще не взяті під контроль! Мені наказано видавати бойові прапори лише тоді, коли обидва маяки будуть запалені, а територія — під контролем. Вирушайте туди й захопіть ці маяки!",  -- db:9433
[358213566] = "Ще раз дякую, $N, за допомогу в з’ясуванні того, що тут сталося в хащах.",  -- db:9444
[489030624] = "Моя робота — піклуватися про цих бідолах.  Я приймаю допомогу від усіх, хто готовий простягнути руку допомоги, будь то альдори чи скриери.$B$BУ нас така нестача персоналу, що я не відмовив би навіть огру, якби той умів накласти джгут.  Політика міста для мене не має великого значення.",  -- db:9451
[539028667] = "Ви можете в це повірити?  Цей ефірний створіння не має на собі жодного ока василіска!$B$BА його ватажок ще й має нахабство називати себе «Принцом-контрабандистом»!",  -- db:9452
[293489872] = "Будь обережним, $c. Ліс сповнений прихованих небезпек і потенційних ворогів.",  -- db:9472
[957035033] = "Ви тут, щоб допомогти Альдору?",  -- db:9478
[194860170] = "Якщо ти чекаєш на якесь офіційне привітання, то тебе чекає розчарування, $c. У нас тут не дотримуються традицій. Дійсно працює те, що працює.",  -- db:9481
[235272452] = "Серед інших уривків пергаменту, прикріплених до цього оголошення про розшук, одна записка особливо виділяється. Це заклик знищити «кісткових бичів» з Кісткових Пусток.",  -- db:9482
[966186670] = "Ні, не переймайся.  Зі мною таке часто трапляється.$B$B<Таела виглядає то розвеселеною, то роздратованою.>$B$BЯ — високий ельф, а не кровний ельф.  Не хвилюйся, я не збираюся висмоктати з тебе всю магію.",  -- db:9484
[480835574] = "«Бонелашери», я їх усіх ненавиджу!$B$BЯкби не втрата ока і ті напади непритомності, які іноді мене охоплюють, я б постійно виходив на вулицю і їх розстрілював!",  -- db:9485
[463943620] = "Там, $c, розкинувся цілий величезний ліс. Нехай шаман бавиться з духами, а воїни — зі своїми мечами. Саме в Тероккарі я зароблю свій статок.",  -- db:9487
[860959193] = "Малуказ безперервно базікає про історичне значення цього лісу, але я не можу собі дозволити занурюватися в історію, доки не вирішаться наші поточні проблеми.$B$BIЯ не кажу, що його робота тут неважлива, але хтось же має дбати про оборону та логістику утримання цієї фортеці.",  -- db:9488
[89405875] = "Доки я не подорожував Награндом і не дійшов до лісу, я побоювався, що занадто багато з нашої первісної культури було втрачено. Я вдячний, що виявилося, я помилявся.$B$BТут є стільки роботи!",  -- db:9489
[302408342] = "Відкриття Темного Порталу принесло звістку про долю мого народу. В певному сенсі моє вигнання вберегло мене від участі в їхній загибелі, але бачити, як Далекобіжці приєдналися до Каел'таса...$B$BI ніколи не уявляв, що мої колишні побратими здатні на таке.$B$BПовернення додому, про яке я колись мріяв, ніколи не відбудеться. Цей ліс — єдиний дім, що в мене залишився.",  -- db:9490
[589780045] = "Коли я тільки приїхала, я сподівалася зустріти того, на честь кого названо це місто.$B$B<Розелет оглядається навколо.>$B$BБільшість молодих високих ельфів переростають етап «Я хочу стати Далекокроком» до того, як їх беруть у підмайстри. Потім настає етап «Я стану магістром».$B$BЧесно кажучи, не думаю, що я коли-небудь повністю подолала фазу «Далекобіжника». Ніхто не мріє стати швачкою, коли виросте, але ж не можна, щоб Далекобіжці бігали голі, як казала моя мама.",  -- db:9492
[994675505] = "<Кайде сичить на тебе.>$B$BЗамовкни, інакше на нас накинуться орки й Альянс, ти, незграбний дурень!$B$BОсь так, кивни головою, а коли ми закінчимо розмову, ти підеш геть і забудеш, що знайшов мене тут.",  -- db:9494
[742731557] = "Можливо, ми й працюємо разом, але це лише підкреслює необхідність дотримуватися обережності. Ще раз нагадую: будьте обережні у своїх словах і вчинках.$B$BI можу запевнити, що ми далеко не єдині тут.",  -- db:9495
[349112207] = "Так?  Чорт забирай, тепер доведеться починати все з нуля!",  -- db:9502
[699097410] = "Тренуюся!  Скоро я стану достатньо вправним, щоб приєднатися до інших заклинателів і увійти до «Тіньового лабіринту» в Аучіндуні.$B$B Сподіваюся, що мені випаде нагода закликати когось великого!  Може, когось такого великого, як Мурмур, хоча я б не втратив над ним контроль!",  -- db:9503
[420473775] = "Привіт, юний $r.",  -- db:9507
[456704293] = "Привіт, люба. Я — Гея, старійшина Маг’харів.$B$B<Велика мати Гея кашляє.>$B$BЯкщо ти тут, можна з упевненістю припустити, що портал відкрився. Більшість орків тут були занадто молоді або занадто хворі, щоб пам’ятати Темний портал.$B$B<Велика мати Гея вказує на орків навколо себе.>$B$BБагато з них були сиротами або незабаром мали ними стати. Так, Чорна Рука не допустив би іншого. Тримати хворих подалі від здорових. Виживуть лише найсильніші... Принаймні так кажуть.",  -- db:9508
[928385364] = "Вони виросли тут. Ми захищали їх від небезпеки. Ми робили все, що могли, щоб повернути їм здоров’я. Багато хто загинув, але набагато, набагато більше стали сильними. Як, наприклад, Гарош...$B$B<Велика Мати Гея зітхає.>$B$BВін втратив своє серце, знаєш. Він каже мені, що я — його рівновага. Що без мене жага крові, яка поглинула його батька і, зрештою, прокляла наш народ, опанує й його.",  -- db:9509
[972573337] = "<Велика мати Гея слабко сміється.>$B$BЗвісно, ні, люба. Але вірити треба не мені...$B$BГарош може очолити Маг'харів. Він сильний і мудрий. Усі духи схвалюють його. Йому просто потрібно повірити в себе. Він так сильно боїться... Він боїться настільки глибоко, що, якщо він дозволить собі розслабитися, його гнів поглине його самого та все, що буде поруч із ним.",  -- db:9510
[899345185] = "Якби я тільки знала, люба. Він не послухає ані тебе, ані мене. Чесно кажучи, саме тому я й досі тут. Саме тому я не поїхала разом із матір’ю Кашур. Він мусить знайти своє серце. Без лідера наш народ не переживе зиму.",  -- db:9511
[227991113] = "<Велика Мати Гея посміхається.>$B$BЯ вже стара. Мій час настав. Коли я відійду, моя душа перейде у світ духів. Саме там я стану поруч із своїми предками. Саме там ми будемо пильнувати за нашим народом.$B$BКоли Гарад був живий, обов’язки Матері Кашур були такими самими, як і мої зараз.",  -- db:9512
[801688198] = "Обов’язок матері клану — слухати. Слухати вітер, воду, вогонь і землю. Збирати інформацію для свого клану так само, як інші збирають хутра, щоб зігрітися. Я спілкуюся саме з духами... У моїх снах Мати Кашур розмовляє зі мною так само, як колись з нею розмовляли духи... Коли я відійду, я так само розмовлятиму з Дракією та Селестіною.$B$B<Велика Мати Гея посміхається.>",  -- db:9513
[609280470] = "Ось ще кілька запалювальних пристроїв, $N. Будьте обережні з ними — при неправильному використанні вони можуть спричинити серйозні порушення у часі.",  -- db:9515
[879200588] = "Нам треба з'ясувати, що ця таємнича група робить тут, у селі Грангол'вар!",  -- db:9520
[905496322] = "У нас тут є обов’язок, $g boy : girl;, — подбати про те, щоб ніхто нас не застав зненацька.$B$BА це означає діяти на випередження!",  -- db:9521
[900382796] = "Мабуть, я десь припустився помилки, якщо мене відрядили саме сюди.",  -- db:9522
[839790802] = "Чи достатньо ти відточив свої навички, щоб засвоїти те, чого я тебе навчатиму?",  -- db:9546
[445098393] = "Ласкаво просимо до банку «Роял Ексчейндж», $g, пане/пані. Чим можу допомогти?",  -- db:9563
[10053834] = "Вітаємо. Чим ми, співробітники банку «Роял Ексчейндж», можемо вам допомогти сьогодні?",  -- db:9563
[78124350] = "Дякуємо, що ви обрали «Банк Сільвермуна». Чим я можу вам допомогти сьогодні?",  -- db:9564
[574761222] = "Ласкаво просимо до Банку Сільвермуна, $g пане : пані;. Чи бажаєте Ви скористатися послугами депозитарію?",  -- db:9564
[149766157] = "Так, $t громадянин : громадянин;, яке важливе питання ви хочете довести до мого відома?",  -- db:9566
[541698170] = "Привіт!  Як ти думаєш, ти міг би допомогти мені звідси вибратися?",  -- db:9568
[935374082] = "Так?  У чому справа?",  -- db:9574
[546042209] = "Тут немає на що дивитися. Проходьте далі.",  -- db:9577
[912666715] = "Це тебе не стосується. Іди собі.",  -- db:9577
[740461590] = "Не дивіться так здивовано, побачивши мене тут, $r. Прихід драені та їхній союз з моїм народом були передбачені Курцем-Провидцем.",  -- db:9583
[123741867] = "Будь ласка, нічого мені не кажи. Я не хочу знову мати з ними неприємності.",  -- db:9587
[926888087] = "Ми щойно приїхали сюди, а вже поховали занадто багато наших друзів і товаришів.",  -- db:9591
[45644213] = "Якщо ти тут не для того, щоб допомогти справі, то забирайся геть.",  -- db:9595
[929156303] = "З вашою допомогою нам, можливо, вдасться виграти цю справу!",  -- db:9596
[705966726] = "За цими деревами лежить Таррен-Мілл. Суматоха в Дурнхолді має дати нам трохи часу, щоб знайти Тарету, перш ніж уся околиця заповниться людськими солдатами. Давайте перевіримо сусідню комору, а потім вирушимо до міста.",  -- db:9597
[774088509] = "Я можу навчити вас знімати шкуру.  Цікаво?",  -- db:9599
[127547649] = "Дякую вам, друзі, за те, що допомогли Тролу втекти. Тепер я лише сподіваюся, що ви зможете допомогти й мені. Сьогодні вранці я прокинувся й виявив, що опинився у цій магічній в’язниці. Якийсь дивний чарівник сказав мені, що мені доведеться деякий час тут залишитися.",  -- db:9610
[984859411] = "Так, друзі. Цей чоловік аж ніяк не був чарівником з Даларана. Його одяг виглядав досить чужим, а акцент був незнайомим. Він лише бурмотів щось про час то, час сьо. Вам доведеться знайти того чарівника й переконати його звільнити мене.",  -- db:9613
[827300538] = "Я радий, що Тарета жива. Тепер нам треба знайти спосіб звільнити її від магічних пут.",  -- db:9614
[931165293] = "Як представник Нижнього Міста, я тут, щоб висловити нашу позицію: Аучіндун необхідно очистити від зарази Тіньової Ради.  Тобто, якщо ми хочемо зберегти хоч якусь надію на майбутнє та запобігти катастрофі, масштаби якої перевершать навіть створення Кісткових Пусток!$B$BНаші народи вже занадто багато натерпілися. Я тут, щоб домогтися припинення цих страждань!",  -- db:9615
[220693395] = "Якщо ви хочете тут перепочити, просто скажіть!",  -- db:9618
[223366738] = "Дякую за допомогу у приготуванні мазі, $N. Як тільки вона трохи полегшить біль, я спробую перевірити, як далеко зможу дійти на цій нозі.",  -- db:9619
[161397939] = "Ласкаво просимо до Гарадара, мандрівнику. Ти шукаєш місце для відпочинку?",  -- db:9620
[893843593] = "Ах... Можливо, ще один шаман прагне просвітлення? Чи, бува, духи говорять нечітко? Чи хочеш ти, щоб я допоміг тобі розгледіти те, що чекає на тебе попереду?",  -- db:9621
[860662403] = "Я — Скалтеш, провідник шаманів, які шукають тут просвітлення... але навіть тим, хто йде іншими шляхами, можна дещо показати. Хочете подивитися?",  -- db:9622
[435874729] = "Випий з цієї флакончика, і туман на деякий час розсіється. Йди разом із духами, друже мій.",  -- db:9623
[90648963] = "Під час свята «Зимової завіси» Дід Мороз залишає іграшки для всіх під ялинкою в Айронфорджі!",  -- db:9626
[601162709] = "Моя сестра Сіланна не усвідомлює, що в цих лісах небезпека дедалі зростає. Але, хочеш ти того чи ні, щойно я завантажу цей віз, ми переїдемо за міські стіни. $b$bСхоже, у мене тут більше мішків, ніж потрібно. Можливо, вони тобі знадобляться.$B",  -- db:9630
[121643663] = "У мене небагато часу на розмову, $r. Тобто, якщо ти, звичайно, не готовий допомогти вирішити цю проблему з шахтою.",  -- db:9631
[494380662] = "Не знаю, як тобі віддячити за допомогу з шахтами. Тепер залишилося лише переконати шахтарів повернутися до роботи.",  -- db:9632
[759622057] = "<Ісфар зітхає.>$B$BA Кілька будиночків на деревах ще не роблять дім, але це було значним покращенням порівняно з Залами Сетхека.$B$BХоч у Шаттраті й було затишно, я не можу змусити себе повернутися до свого справжнього дому в Скеттісі без сестри. Вона досі ув’язнена в Залах Сетхека, де її тримає наш старший брат.",  -- db:9634
[636967110] = "Ось наш шанс! Випустіть мене з цієї клітки!",  -- db:9636
[203352630] = "Колись «Кільце випробувань» було місцем великої слави та честі. Але потім з’явився картель «Стімвідл» зі своїми возами, навантаженими золотом, та перами, гострішими за будь-яку сокиру орків...",  -- db:9637
[359191967] = "Сетек вважають себе справжніми та найвідданішими послідовниками володаря всіх араккоа. Не запитуйте про володаря, $r, адже його таємниці відомі лише пернатому народу.$B$BСетек розцінили руйнування Аучіндуна як прихід нашого володаря на цю планету. Вони вирушили до руїн, взявши з собою реліквії нашого найвеличнішого героя, Терока.$B$BВони й досі шукають Повелителя серед руїн храму, але я розгледів їхні брехні. Я більше не є одним із них.",  -- db:9638
[421514174] = "Коли я востаннє бував у залах, Король Талонів Ікісс носив із собою Перо Терокка як знак своєї влади.$B$BМій брат, Темний Ткач Сіт, носив Маску Терокка під час наших ритуалів.$B$BЩодо Саги про Терокка, то точно невідомо, де вона знаходиться, але зазвичай її зберігали в центрі одного з рунічних кіл у великих склепінчастих залах.",  -- db:9639
[66068497] = "«Король Кігтів» Ікісс — один із ватажків Сетхеків, поряд із моїм братом, Темним Ткачем Ситом.$B$BСаме вони очолили вигнання Сетхеків зі Скеттіса до руїн Аучіндуна. Спочатку Ікісс був харизматичним лідером, але з часом він зійшов з розуму.$B$BТепер він відкрито проголошує, що є відродженим Терокком! Він справді очікує, що аракоа схилять перед ним коліна як перед своїм правителем. Чи можете ви повірити в таку його зарозумілість?",  -- db:9640
[333264181] = "Він — найвеличніший герой, якого коли-небудь знали аракоа.$B$BКажуть, що в давні часи він власноруч, своїми кігтями, збудував місто Скеттіс. Він був нашим найвеличнішим захисником і захисником, але покинув нас, коли ми відвернулися від поклоніння Рукмару.$B$BМи почали поклонятися новому володареві, який обіцяв нам незліченну силу та статус у космосі.$B$BДехто каже, що Терокк і Рукмар — це одне й те саме, і що він відвернувся від нас, коли ми відвернулися від нього.",  -- db:9641
[213870535] = "Самі м’язи й жодного розуму — ось що таке прості робітники! Вони чудові, коли їх можна мотивувати, але їх треба «завести», якщо ти розумієш, про що я.",  -- db:9642
[920345164] = "Як і все, що ти бачиш, $c?",  -- db:9643
[86498398] = "Якщо у вас є гроші, у мене є те, що вам потрібно.",  -- db:9644
[247566150] = "Озирніться навколо і дайте мені знати, якщо щось вас зацікавило.",  -- db:9645
[554240053] = "Не поспішайте, огляньте зброю.  Я також ремонтую зброю та обладунки, якщо вам потрібні такі послуги.",  -- db:9646
[120045174] = "У мене є саме те, що тобі потрібно, щоб накласти своє закляття.",  -- db:9647
[501227253] = "Шукаєте реактиви чи отруйні речовини? Якщо так, то ви потрапили за правильною адресою!",  -- db:9649
[511991342] = "Я продаю товари, необхідні майстрам. Тільки найнеобхідніше, нічого особливого.",  -- db:9650
[105837762] = "Ви заблукали? Більшість міських торговців розташовані поблизу центру міста.",  -- db:9652
[602326975] = "Я ношу з собою всяку дрібничку, але здебільшого — просто всяку дрібничку.",  -- db:9653
[507653547] = "Прикро, що серед наших численних ворогів на Півострові Пекельного Вогню є й орки з Цитаделі Пекельного Вогню.$B$BАле... хто краще за орків може кинути виклик Орді та загартувати її?",  -- db:9657
[462226904] = "Радий знову тебе бачити, $N! Ще кілька коригувань — і траєкторія стрибка буде ідеальною!",  -- db:9659
[266486663] = "Святкування Місячного фестивалю, яке організовують друїди, відбувається в Місячній галявині. Якщо вам занадто далеко їхати, вони пропонують транспорт від місячного джерела в Парку.",  -- db:9662
[448995468] = "Дід Мороз знаходиться перед банком в Айронфорджі. Біля дерева поруч із ним роздають подарунки.",  -- db:9686
[538490876] = "Відправляйтеся до «Містичного кварталу» в Айронфорзі та поговоріть там із друїдами нічних ельфів. Вони зможуть перенести вас до Місячної галявини, де ви зможете долучитися до святкування Місячного фестивалю.",  -- db:9688
[739549088] = "У Місячній галявині у розпалі святкування Місячного фестивалю. Ви можете дістатися туди пішки, або скористатися транспортом, який пропонують друїди з Енклави Сенаріону.",  -- db:9692
[246697872] = "Я подорожував незліченною кількістю світів, але ніколи не бачив такого веселого свята, як це свято «Зимової завіси». Вам варто відправитися до Айронфорджа, величного міста гномів, щоб побачити це на власні очі.",  -- db:9694
[538126231] = "Друїди Азерота влаштовують велике свято в Місячній галявині. Якщо ви знайдете в місті учасників місячного фестивалю, вони зможуть перенести вас туди.",  -- db:9696
[95394507] = "Якщо ви знайдете учасників святкування Місячного фестивалю в Срібному Місяці, вони зможуть перенести вас до Місячної галявини, щоб ви могли долучитися до святкування.",  -- db:9700
[119559170] = "Ви знайдете Великого Батька Зиму в центрі Долини Сили. Просто шукайте дерево.",  -- db:9702
[772659372] = "Святкування Зимової завіси дарує велике тепло в холодну пору року, а його серце — в Оргримарі.",  -- db:9706
[229121765] = "Ми й досі дотримуємося традицій, але свято Зимової завіси тепер здається порожнім. У Оргримарі ж влаштовують справжнє свято.",  -- db:9710
[502085338] = "Для багатьох із «Покинутих» Місяць тепер займає в наших серцях те місце, де колись було Сонце. Однак, якщо ви вирішите долучитися до святкування, вирушайте до Місячної галявини в Калімдорі. У тронній залі над Андерсіті ви знайдете друїдів, які перенесуть вас туди.",  -- db:9712
[377559710] = "Ви — підійдіть сюди. Хіба ці клинки не найвищої якості? Ви, безперечно, захочете придбати їх у мене. Ніде більше ви не знайдете зброї, виготовленої з такою майстерністю та ретельністю, $r.",  -- db:9713
[977566436] = "На що ти так витріщаєшся, $r?",  -- db:9714
[426920358] = "Найдивовижніша з вечірок на честь Місячного фестивалю відбувається в Місячній галявині. Але не йдіть туди пішки — друїди з Долини Мудрості можуть перенести вас туди.",  -- db:9716
[564781824] = "На диких рівнинах Награнда можна влаштувати одне з найкращих полювань, які я коли-небудь бачив.",  -- db:9729
[14137806] = "Ти любиш рибу, $r? У мене тут є риба. Якщо тобі подобається свіжа риба, найсвіжіша, що тільки може бути, — заходь і скуштуй мої товари.",  -- db:9730
[163522649] = "Забирайся з моїх очей, малий! Хіба ти не бачиш, що я тренуюся? Саме так, твій покірний слуга стане наступним чемпіоном «Вармаула».$B$BТак, я вже майже готовий до «Кільця крові» на півночі, у старих руїнах «Сміючої Черепа». Але навіть не думай про це, малий. Ти надто слабкий. Гургток, диктор рингу, навіть не дозволить тобі зазирнути всередину того рингу, не кажучи вже про те, щоб там битися.$B$BА тепер забирайся звідси, поки це не зробило тебе.",  -- db:9734
[58742751] = "О, поглянь-но на себе. Ти який великий і міцний... Може, ти вважаєш себе достатньо сильним, щоб вийти на «Кривавий ринг» і зійтися в поєдинку з чемпіоном Вармаула?$B$B<Боєць сміється.>$B$BНавряд чи, але якщо ти коли-небудь захочеш випробувати свою силу, «Кривавий ринг» розташований далеко на півночі, біля гір, що розділяють Награнд і Зангармарш. Гургток керує змаганнями у старих Руїнах Сміючого Черепа, а також роздає призи. До речі, про призи — кажуть, цього сезону вони просто неймовірні!",  -- db:9735
[76099592] = "Слідчий намагається з’ясувати, що ці криваві ельфи роблять тут, у Награнді. З того, що я чув, вони шукають залишки кристалічного порошку з Ошу’гуна — діамантової гори на заході.$B$BБез сумніву, щоб використати його в якійсь підступній інтризі чи мікстурі...$B$BЯкщо ви хочете допомогти нашій справі та зупинити цих кровоельфів, конфлікт розгортається прямо зараз на північному заході, у Халаа. Кровоельфи та солдати «Руки Аргуса» ведуть бій! Приєднуйтесь і покажіть їм, що таке справедливість!",  -- db:9738
[334657048] = "Драені повернулися! Ця група напала на двох моїх найкращих вовчих вершників, коли ті патрулювали західні дороги. Звісно, ми здобули перемогу в цій сутичці.$B$BЗараз я не впевнений, що саме відбувається, але, судячи з того, що повідомляють мої розвідники, по всій Халаа повно кров'яних ельфів і драені. Я не є прихильником кров'яних ельфів, але якщо є щось, що я ненавиджу, то це саме драені. Якщо побачите драені або їхніх союзників у Халаа, не забудьте дати їм від лупи за мене.$B$BХалаа знаходиться на заході... Якщо раптом захочете вирушити туди вже зараз.",  -- db:9739
[655953737] = "Ми вже захопили руїни Твін-Спайр! Біжіть туди й захищайте їх!",  -- db:9749
[65660624] = "Мисливець за тінями Денджай використовує цю дошку для розміщення важливих оголошень та новин про винагороди за ворогів Забра'джина.",  -- db:9752
[75937698] = "Ааа, не зміг втриматися, правда? Хочеш стати кращим, сильнішим, швидшим? Кожен із цих амулетів гарантовано зробить саме те, що я кажу. Не зволікай — купуй одну з цих чудодійних дрібничок! Навіть за подвійну ціну це дешево!",  -- db:9755
[144160337] = "Ласкаво просимо. Можливо, ви хочете тут трохи перепочити або, може, перекусити?",  -- db:9766
[285314239] = "Ми маємо розгадати таємницю гігантського кристала, що впав з неба на хребет «Падіння неба».",  -- db:9769
[998238657] = "Іноді найпростіший підхід до вирішення проблеми є найкращим.",  -- db:9770
[87946591] = "Якщо вас коли-небудь захопить Легіон, скажіть їм: «Xar il romath da tidesbi». Вони вб’ють вас миттєво за образу свого бога, позбавивши вас нестерпних тортур або чогось гіршого...",  -- db:9771
[872809387] = "Ми тут, щоб захищати інтереси Гаджетзана в Ун'Горо, і це не ваша справа.",  -- db:9774
[741096604] = "Півострів Пекельного Вогню — це зруйноване королівство, безжальне й невблаганне до своїх мешканців. Перед тим, як вирушати туди, обов’язково відремонтуйте своє спорядження та запасіться необхідним.",  -- db:9775
[870499194] = "Говори тихіше і не відводь погляду, $N. Тут нас оточують вороги.",  -- db:9777
[646421499] = "Перш ніж я відвезу тебе до Дурнхолда, ти повинен отримати від Ерозіона пачку запальних бомб. Адже ти ж не хочеш марнувати час.",  -- db:9780
[736233089] = "Вона ж красуня, чи не так? Скайрі... вірний грифон нашого командира. Сам Курдран проводить аудієнції у фортеці. Коли він зайнятий, я доглядаю за нашою Скайрі. Вона — чудова істота, найсильніша й найзапекліша з усіх. Вона готова померти за Курдрана. Ви ніколи не зустрічали більш відданої душі. Для мене — справжня честь піклуватися про неї.",  -- db:9805
[331702567] = "«Нетерсторм» не завжди був таким, яким ви його бачите зараз.$B$BКолись ця занепала земля була відома як Рівнини Фаралона. Мало що з тих часів вціліло після того, як тут запанувало зло.",  -- db:9826
[47620674] = "$C, не нападай, це лише маскування! Я — шпигун, який працює на коаліцію Нижнього міста, що базується в Шаттраті.$B$BСподіваюся, ти тут, щоб допомогти!",  -- db:9827
[462004044] = "Архімаг Варгот довірив мені свій посох, коли наказав мені втекти від нападу кровних ельфів на Фіолетову Вежу. Я зробив так, як він наказав, сподіваючись знайти притулок у старому поселенні драені — Арклоні.$B$BАле перепочинку не судилося. Я потрапив прямо в передній край військ Палкого Легіону. Демони вирвали у мене посох, але мені вдалося врятуватися.$B$BХоча мій наставник нічого не знає про мою поразку, мені все одно соромно.",  -- db:9828
[744279591] = "Давним-давно, у вимірі космосу, незбагненному для смертних розумів, з’явилася на світ — якщо це слово взагалі можна застосувати до неї — істота настільки неймовірної сили, що сам факт її появи розтрощив усю навколишню реальність.$B$BВідома лише як Мурмур, вона була самою сутністю звуку, і почути її голос означало пізнати вічну смерть!",  -- db:9834
[268466611] = "Воно існувало лише заради хаосу, і навіть найменший його шепіт означав знищення цілих світів!$B$BТа все ж були ті, хто намагався поклонятися цій бездумній істоті.  Були навіть ще більш божевільні, які наважилися мріяти про те, щоб керувати нею!",  -- db:9835
[1977137] = "Затхлі сторінки кодексу ніби чарівним чином перегортаються самі, спрямовуючи вашу увагу на певний розділ, оминаючи жахи, які жодним смертним очам не слід бачити.$B$BКнига відкривається на сторінці, яка чомусь здається «правильною», але водночас такою неправильною.",  -- db:9836
[587566393] = "І ось, як могутні падали, тремтячи біля його ніг, боячись, що він може звернути свої слова проти них.$B$BАле ці шарлатани, ці поклоняючіся притворці неіснуючої релігії, все одно лаяли неминуче, марно намагаючись контролювати свого «бога».  Байдужий і, ймовірно, навіть не помічаючи їх, Мурмур позіхнув — і вони поринули в небуття.$B$BПроте одному з них якось вдалося вижити, і в своєму божевіллі він знайшов спосіб привести Мурмура у цей світ.",  -- db:9837
[20371759] = "Цей смертний, що володів таємним і темним знанням, якому ніхто не міг дорівнятися, розробив метод посилення своїх здібностей до виклику істот шляхом захоплення та використання незліченних душ.$B$BЦілі цивілізації були знищені за допомогою його пристроїв для поглинання душ, які слугували паливом для ритуалу, завдяки якому він та його спільники мали намір привести Мурмура у свій світ.",  -- db:9838
[457137303] = "І вони справді викликали Мурмура.$B$BБули застосовані потужні магічні заклинання утримання та приглушення, які підтримувалися постійним надходженням душ, що подавалися в них.  Та все ж вони не могли контролювати звіра, не могли підкорити його своїй волі.$B$BЦі смертні почали розробляти різні стратегії, і одна за одною всі вони зазнавали невдачі.  І тим самим вони послабили ритуали, випадково надавши Мурмуру найменшу крихту свободи.$B$BЦього було цілком достатньо.",  -- db:9839
[454092723] = "Лише ця книга вціліла після катастрофи, що знищила їхній світ. Ті горді й нерозумні люди, які сподівалися підкорити космічну істоту з незбагненною силою.$B$BЧи зробили б ви, володар кодексу, те саме?$B$BЧи придумали ви надійний спосіб викликати Мурмура або будь-яку іншу істоту, про яку обережно шепочуться на цих нечестивих сторінках?$B$BПобачимо.",  -- db:9840
[823207773] = "Привіт!  Приємно бачити нове обличчя — до мене не часто заходять гості, а технічні фахівці не надто вправні співрозмовники.$B$BI Готовий побитися об заклад, що ти прямуєш до Зони 52.  Я правий?",  -- db:9841
[465326245] = "Рокет-Чіф Фузелаж, командир B.O.O.M — «Мозкового центру орбітальних операцій та механіки» — до ваших послуг.$B$BУсі системи готові?!  Схоже, що ракета X-52 «Nether-Rocket» ще потребує чимало доопрацювань!$B$BНу ж бо, люди... до старту залишилося НІКОЛИ!",  -- db:9844
[425986068] = "Ласкаво просимо до фортеці Аллеріан, $N.",  -- db:9845
[885496409] = "Це ж делікатна робота, розумієш?  Не можна просто поспішати, інакше щось напевно зламається.$B$BНаприклад, голова Фузеляжа!$B$BМоже, тобі цікаво, що там з моїми роботами?  Я постійно працюю над Mk. I, а Mk. II на мить набув свідомості, перш ніж у нього вибухнув конденсатор мозку і він збожеволів!$B$BЯ вирішив пропустити III і IV і відразу перейшов до Mk. V — моєї гордості та радості!",  -- db:9846
[847066102] = "Будь обережним серед руїн, $c. Духи Кірін-Тор, яких ти там зустрінеш, не сприймуть тебе як друга.$B$BЛише ми з хранителем — єдині, чиї душі зберегли достатньо міцний зв’язок із цим місцем, щоб зберегти свою повну ідентичність після смерті.",  -- db:9847
[584801052] = "Кірін'Вар простояв 20 довгих років і пережив незліченні напади орків, але не зміг встояти перед силами Каель'таса. Чоловік, який колись називав себе членом Кірін-Тор, вбив усіх нас, крім одного.$B$BАрхімаг Варгот вижив після нападу, тож Каель'тас ув'язнив його у Фіолетовій Вежі, захистивши її магією, яка забороняє прохід будь-кому з Кірін-Тор.",  -- db:9848
[244726536] = "Ти прочитав Греку оголошення про розшук?$B$BГрек хоче допомогти!",  -- db:9853
[273210552] = "Доброго дня, що вас сюди привело?$B$BЦе дитячий будинок для дітей з Аутленду, які втратили батьків і не мають нікого, хто б про них піклувався.$B$BМожливо, ви тут, бо розглядаєте можливість усиновлення?",  -- db:9854
[76885209] = "Чим можна вас порадувати?  Присуньте стільця та випийте келих.$B$BЯ — Бутс, головний міксолог у «B.O.O.M.» і бармен екстра-класу!$B$BЯкщо вам потрібна міцна випивка, старий Бутс — до ваших послуг.",  -- db:9863
[673575184] = "Ви — кореспондент «Gadgetzan Times»? Якщо ви просто підете за мною, я покажу вам свою експериментальну установку...$B$B<Скажіть магу, що ви не той репортер, на якого вона чекає.>$B$BO, то це не ви? Ну що ж, якщо вам потрібні реактиви, знайдіть те, що потрібно, і не затримуйтеся. Я чекаю на когось.",  -- db:9868
[196386019] = "Радіація?!$B$BNі, тобі не варто про це турбуватися!  Боже, у що тільки люди не вірять у наш час.$B$BTому, що ти думаєш про нашу діяльність тут, внизу?  Найсучасніше, друже!  Повір мені.",  -- db:9869
[858712230] = "На цій дошці вивішено два помітні оголошення: одне від Папи Вілера, а інше — від «Ракетного вождя» Фузеляжа.$B$BOголошення Папи схоже на оголошення про розшук деталі для машини.  А оголошення «Ракета-Шефа» стосується винагороди за голову величезного гірського велетня!$B$BПодробиці обох оголошень викладені дуже дрібним почерком гобліна, який, звісно ж, ледь розбірливий.",  -- db:9872
[863792666] = "На дошці тут вивішено кілька важливих оголошень.$B$BОднак, як вказується дрібним шрифтом, ви ще не зовсім готові до виконання жодного з цих завдань.  Обов’язково загляньте сюди пізніше!",  -- db:9873
[490097735] = "Подрібнювачі?!  Вони вже не справляються зі своїм завданням.  Це вже вчорашній день!$B$BЯкщо ми збираємося будувати ракети — якщо ми збираємося запустити X-52 — нам потрібні кращі технології!",  -- db:9875
[234781900] = "Чого ти хочеш, $r?",  -- db:9886
[411385817] = "Що таке «олог»? Краще запитати: що не є «ологом». Це означає, що я вивчаю все! Насправді я настільки добре розбираюся в «усьому», що гарантовано буду найрозумнішим ефірним істотою, якого ви коли-небудь зустрічали — або поверну вам гроші.$B$BВибачте. Це в мені промовляє дилер...",  -- db:9894
[416561067] = "Я не худий і не підступний. Насправді, обидві ці натяки я вважаю образливими.$B$BА тепер забирайся з моїх очей, поки я не встромив тобі свій посох у зад.",  -- db:9895
[69025347] = "<Голова персонажа розмивається, коли він повертається, щоб оглянути околиці.>$B$BЯкби ти бачив рівнини Фаралона, ти б не повірив, що це те саме місце. Лише кілька місяців тому ці поля цілком могли б бути частиною Вестфолла.$B$BТепер усього цього немає, але як і чому?",  -- db:9901
[573605983] = "Стан цієї землі гірший, ніж я міг собі уявити. Якщо руйнування триватимуть такими темпами, Фаралон — вибачте, Нетерсторм — дуже скоро перетвориться на космічний щебінь.$B$BЦікаво, де це все закінчиться? А може, краще запитати: «Чи закінчиться це взагалі?»",  -- db:9901
[608881935] = "<Здається, образ архімага дивиться крізь тебе, а не на тебе.>$B$BСтрічки та потоки магічної енергії тут то набирають силу, то слабшають, ніби ця місцевість потопає в морі магічної сили. Навіть перший катаклізм не спричинив таких руйнувань.",  -- db:9901
[884650318] = "Я помщуся Каел'тасу за це знущання над Кірін-Тором! Колись він був серед нас як брат, але ми більше не брати.$B$BНастане час розплати.$B$B<Архімаг похмуро киває головою, не радіючи цій перспективі.>$B$BКаель'тас — це більше, ніж просто мандрівний маг. Як тільки я звільнюся з вежі, ми з Равандвіром допоможемо кожному, хто протистоїть йому.",  -- db:9901
[728500121] = "Сфера, що стоїть за моєю спиною, колись давала змогу зазирнути у події, що відбувалися в Азероті.$B$BЗвичайно, прокляття Каель’таса все це змінило, але протягом років нашої ізоляції багато магів знаходили розраду в її образах.$B$BХтось дивився у сферу, щоб згадати; хтось — щоб забути.",  -- db:9902
[5832216] = "<Архімаг Варгот обдарував вас іронічною посмішкою.>$B$BУ проклятій Фіолетовій Вежі вдосталь місця.$B$BУ будь-яку пору року ви можете знайти мене тут.",  -- db:9902
[380064036] = "Тієї ночі, коли Каель’тас зрівняв село з землею, я не міг нічим допомогти. Його магія вже зачинила мене у вежі, посилюючи мої муки тим, що змушувала мене спостерігати за смертю моїх товаришів.$B$BІ досі їхні голоси лунають здалеку, будячи мене посеред ночі.",  -- db:9902
[364945256] = "Якщо вас послали вбити мене, будь ласка, візьміть талон і дочекайтеся своєї черги.",  -- db:9903
[403677868] = "Тихіше!  Я не хочу, щоб вони мене тут побачили.$B$BОй, це мене просто до сказу доводить!  Хто ці ефірні істоти такі, щоб так поводитися?$B$BЦе МОЯ територія!",  -- db:9904
[112756098] = "Будь ласка, залиш мене наодинці з моїм смутком.",  -- db:9905
[859107293] = "Від цієї дитини у мене мурашки по шкірі. Він цілий день стоїть там, спілкуючись зі своїм дідусем. Потім він повертається, щоб розповісти мамі, що йому сказав дідусь, а вона — звісно ж — лише посміхається й киває головою.$B$BЯгнята! Леммінги! Усі вони!$B",  -- db:9914
[771353540] = "Якщо ви станете другом Нижнього міста, можливо, ми зможемо налагодити ділові стосунки?",  -- db:9918
[581901922] = "Ви можете повірити в цю неймовірну технологію?!$B$BIЯ дуже радий, що мені дозволили залишитися тут разом з ними. Я багато чого навчуся... і, можливо, навіть отримаю щось для себе!",  -- db:9919
[578069569] = "Стільки справ!  Стільки треба зробити, а часу так мало!$B$BДе ж я поклав той пірогайковий ключ?  Я знаю, що він десь тут... Я ж щойно обпік ним пальці!",  -- db:9923
[795925974] = "У цій сфері діяльності знання трохи магії завжди стають у нагоді. Ілюзії не завжди здатні обдурити всіх, але зазвичай їх цілком вистачає, щоб виконати завдання.",  -- db:9925
[897693137] = "Що ти тут робиш?  Хіба тобі не слід працювати над енергетичним трубопроводом?$B$BMи більш ніж удвічі збільшили обсяг енергії, яку постачаємо до Фортеці Темпест, і не можемо собі дозволити, щоб хтось байдикував.  Ми не хочемо, щоб тут повторилася ситуація з «Ультрісом».",  -- db:9926
[670076979] = "Звісно ж, Манафордж Ультріс!  Де ти взагалі був?$B$BМанафордж перевантажився і спричинив потужний вибух.  Це спричинило розрив у реальності, і тепер крізь нього напливають істоти з Порожнечі.  Їх можна побачити всюди на північному сході.",  -- db:9927
[846062046] = "Ви повинні почуватися тут у безпеці; після нападів на «Манафорж Дуро» ми посилили заходи безпеки на цьому об’єкті.",  -- db:9929
[241641111] = "«Манафордж Дуро» — це об’єкт, розташований найближче до «Фортеці Бурі», тому на нього припадає основне навантаження.$B$BЯк вам, мабуть, відомо, перевантаження цих манафорджів призводить до витоків у трубопроводах.  Енергія, що випромінюється, приваблює небажаних мана-істот.  У багатьох місцях витоків ми стикалися з навалою манових істот; наразі найсильніше постраждала саме «Манафорж Дуро».",  -- db:9930
[301924971] = "Робота з цією технологією — справжній головний біль.  Усе побудовано в такому незрозумілому стилі.",  -- db:9931
[171294773] = "Хіба вам, новобранцям, нічого не вчать? Ці манафоржі були побудовані з частин фортеці «Темпест», призначених для вилучення енергії з Нетера.$B$BНаару використовували цю технологію для живлення свого корабля під час подорожей. Дехто зауважував, що ця технологія може бути небезпечною для використання на суші. Їх негайно змусили замовкнути.",  -- db:9934
[441118874] = "Це моя пристрасть, знаєш. І за життя, і після смерті я люблю виготовляти обладунки. Будь ласка, стався до мене так, ніби я живий драені, незнайомцю. Дозволь мені знову відчути, що це таке... Надай мені честь відремонтувати твої речі.",  -- db:9936
[422496159] = "Консорціум помститься зрадникам із «Заксіс»!",  -- db:9937
[457820205] = "$N, Сини Лотара воюють тут, на Півострові Пекельного Вогню, вже два десятиліття.  З усіх боків нас оточують місцеві орки та пекельні демони «Палкого хрестового походу», і хоча наші серця все ще б’ються нестримно, роки війни значно зменшили наші ряди.$B$BВи та приплив нового покоління героїв Азерота — справді довгоочікуване поповнення!",  -- db:9939
[421775284] = "Орки. Здається, я борюся з ними все своє життя.$B$BДвадцять років тому ми розгромили Орду й зруйнували стіни їхньої Цитаделі Пекельного Вогню. Ми загнали огидних зеленошкірих на самий край прірви! Після цього, за винятком кількох сутичок, розгромлені орки більше ніколи не становили для нас загрози.$B$BДотепер. $B",  -- db:9941
[498571835] = "Чоловіки та жінки з «Оплоту Честі» пролили стільки крові й втратили свою молодість на цій жахливій землі... і все ж вони не втрачають духу!$B$BТепер ви та ваші соратники з Азероту можете допомогти нам переломити хід подій. Ви даєте нам надію, що одного дня ми зможемо повернутися на свою батьківщину.",  -- db:9944
[284011872] = "Мій молодший брат — справжня висхідна зірка в Консорціумі. Звісно, він занадто скромний, щоб це визнати.",  -- db:9948
[133219464] = "Коли він каже «молодший брат», він не згадує, що ми близнюки. Насправді він старший лише на кілька хвилин.$B$BНе дайте себе обдурити його фразою про «висхідну зірку». Я ніколи не стану трейдером такого ж рівня, як він.",  -- db:9949
[637670544] = "Вітаю тебе, $r. Про те, що я тут роблю, розповім іншим разом. Ой, це було невдало.$B$BМи з братом застрягли тут, між нашим часом і сьогоденням. Ми не наважуємося піти, боячись спричинити часовий парадокс. Терпляче чекаємо, поки дракони повернуть нас у нашу власну часову лінію.$B$BСкільки часу минуло, питаєте? Я, чесно кажучи, не знаю. Запитайте мого брата.$B$BХочете трохи сиру?",  -- db:9951
[938646103] = "Ні, тобі не здається. У мене справді голос молодої орки. Але послухай-но, $g boy:girl;, подорожі в часі дивно впливають на організм.$B$BДо речі, це 250 років.",  -- db:9953
[396537606] = "Так, я застряг тут вже скільки себе пам'ятаю.$B$BУ минулому житті я був зброярем. Можливо, я зможу щось для тебе полагодити?",  -- db:9954
[766195517] = "Нарешті хтось спустився, щоб зі мною поговорити! Хочеш послухати кілька моїх рим?",  -- db:9955
[877878247] = "Йду вулицею! Дивлюся на свої ноги! Спостерігаю, як листя опадає з дерев!",  -- db:9956
[450815114] = "Ця неземна телепортаційна платформа вкрита яскравими кнопками та перемикачами, але, схоже, вже давно не використовується.",  -- db:9958
[857909879] = "«Smokeywood Pastures» відкрила свої магазини в Оргримарі та Айронфорзі. Цікаво, що вони придумають цього року?",  -- db:9962
[85297719] = "Друїди влаштовують у Місячній галявині велике свято Місячного фестивалю. Якщо йти пішки занадто далеко, вони організовують перевезення людей із великих міст.",  -- db:9964
[409015754] = "Я ніколи не бачив нічого подібного до цих драконів з Нижнього Світу. Схоже, вони успадкували характер свого батька, але стали чимось зовсім іншим.",  -- db:9968
[351872130] = "У цьому світі є лише 3 типи людей: конкуренти, клієнти та співробітники. Конкурентів слід безжально знищувати, клієнтів — балувати, а співробітників — суворо контролювати.$B$BНезалежні підрядники — це міф. Вони хочуть отримувати вищу зарплату, ніж співробітники, але щоб до них ставилися як до клієнтів. Ніколи не довіряйте тому, хто називає себе таким.",  -- db:9971
[825145414] = "Радий знову тебе бачити, $N. Хочеш, щоб я відвів тебе до лігва господаря?",  -- db:9978
[23649140] = "Басейн Араті заполонили «Осквернителі». Чи допоможеш ти нам, $N?",  -- db:9979
[661760603] = "Вперед, $N, у Басейн Араті! Вбивай, ВБИВАЙ, як ніколи раніше!",  -- db:9981
[324530702] = "Перед вами — вхід до Ущелини «Військової пісні». Чи будете ви там битися з огидним Альянсом?",  -- db:9982
[600382780] = "Радий бачити тебе, $c. Навіть зараз Орда атакує Ущелину Воєнної Пісні. Чи будеш ти там битися пліч-о-пліч з Альянсом?",  -- db:9983
[480737700] = "Що ти тут робиш?! Забирайся зі своїми балачками до Долини Альтерак, там ти потрібен!",  -- db:9984
[540826665] = "ЧОРТ ЗАБЕРИ! Чому я мушу залишатися тут, щоб вести інших до Долини Альтерак, коли міг би сам там битися? А ти! Ти прийшов битися з Альянсом?",  -- db:9985
[687077705] = "Ліс наповнений насінням змін. Наші нові друзі, драені, вже тут, і ми допоможемо їм облаштувати власне місце.",  -- db:9986
[175989333] = "Я організував твій переліт до Манафордж-Коруу. Ти готовий, $N? Тебе висадять за лінією фронту, тож переконайся, що взяв із собою все необхідне.",  -- db:9990
[855156972] = "Ще один солдат на шляху до Фортеці Честі... За бородою Курдрана, їм не завадить допомога!",  -- db:9991
[503680716] = "Ви хочете щось купити?  Або, може, хочете щось продати?$B$BСаме для цього ми й тут, друже.$B$BБудь ласка, скажіть, чим можу допомогти.",  -- db:9994
[292618577] = "Тром'ка, $gbrother:sister;! Ласкаво просимо до Аутленду. Орді потрібні всі сили, які вона тільки може зібрати в цьому зруйнованому світі. Обіцяю тобі: якщо ти прийшов у пошуках славної битви, то тут ти отримаєш її вдосталь.",  -- db:9996
[694914064] = "Поспішай, $c — нам тут війну вести треба, чи ти що, не помітив?",  -- db:9997
[164769904] = "Ах, ласкаво просимо, герою. Ти повернувся, щоб знову захистити Хранителя? Не забудь взяти з собою хроно-маяк!",  -- db:10001
[102762348] = "Вітаю, $N. Дійте обережно...",  -- db:10002
[805629382] = "Тром'ка, $c. Ти, мабуть, новачок. Виглядаєш свіжим і ще не зіпсованим жахами цієї землі.$B$B<Сержант Шаттерскалл плюнув у пил.>$B$BЦе зміниться.",  -- db:10005
[184427433] = "Наша експедиція благополучно пройшла через Портал і заснувала нову базу під назвою Тралмар. Однак, як ви бачите, «Палаюча Легіон» вторглася сюди й відрізала нас від наших братів. Очевидно, демони сподіваються відвоювати Темний Портал і не дати нам зібрати підкріплення з Азероту.",  -- db:10006
[100958543] = "Мої брати зі Штормовію радили мені не йти в армію... Я радий, що не послухався їх!",  -- db:10009
[810720332] = "Яструбобіжці — благородні істоти.  Обов’язково завжди добре ставитеся до свого яструбобіжця; мало що небезпечніше за розлюченого яструбобіжця.",  -- db:10011
[852920187] = "Я впевнений, що з нашою допомогою ботанік Таерікс зможе знайти рішення наших проблем.",  -- db:10012
[305310693] = "Збираєтеся до Аутленду? Завітайте до Вікстона Пінчвістла в зоні 52 Нетершторма. Як офіційний продавець арени «Бойового цирку Стімвідл», він пропонує на продаж найрізноманітніші дивовижні предмети тим, хто має достатньо очок арени.",  -- db:10018
[9153661] = "Не хочеш допомогти мені знищити портал у тому таборі «Палаючого Легіону» на півдні?",  -- db:10019
[400394936] = "Ці люди приїхали з Шаттрата кілька ночей тому і з того часу не перестають сваритися.$B$BIРадий, що це тебе не відлякало — я вже почав думати, що вони відлякують потенційних клієнтів.",  -- db:10022
[150166264] = "Сподіваюся, ці мешканці Шаттрата скоро припинять воювати. Вони вже починають діяти мені на нерви.$B$B Чим можу допомогти?",  -- db:10022
[238813004] = "Війська драені та їхні союзники з Альянсу ведуть бої з Ордою в «Оку Бурі» в Замежжя. Чи приєднаєтеся ви до них, щоб переламати хід битви на нашу користь?",  -- db:10025
[313808039] = "Орда не може дозволити драені та їхньому втручаючомуся Альянсу контролювати всі джерела мани в Замежжя. Чи приєднаєтеся ви до кривавих ельфів у їхньому штурмі «Ока Бурі»?",  -- db:10026
[268732716] = "Привіт, $c!  Ти з’явився для виконання льотного завдання?",  -- db:10027
[250458416] = "Якщо ви бували в Зангармарші, то, можливо, зустрічали там хлопця на ім’я Деніелс. Ну, знаєте — той, що носить дивний шолом і відгукується лише на ім’я «Спеціаліст».$B$BЗвісно, я навчив його всьому, що він знає.$B$BНехай вас не вводить в оману його ошатний одяг. У душі я досі залишаюся розбійником. Деніелс і я провели разом багато часу в окопах, але це було до того, як я пішов на пенсію. Наскільки я знаю, він досі десь там, влаштовуючи їм пекло.",  -- db:10031
[134016247] = "$N, будь ласка, обов’язково повідомте Гаруджу про наш успіх.",  -- db:10039
[551553836] = "Посланець Талуун взяв мене з собою, сподіваючись, що я зможу розповісти нашим новим союзникам про стихії цього світу... але ніхто не хоче слухати.",  -- db:10040
[952439295] = "Хоча основна увага Ша'тар як і раніше зосереджена на Долині Тіньового Місяця та Іллідані, ми не можемо ігнорувати загрозу, яку становить Каель'тас Сонстройдер.",  -- db:10042
[92563439] = "Мені набридло охороняти посла Сансорроу, $n. Може, трохи потренуємося? Можливо, хтось із нас чогось навчиться.",  -- db:10044
[96893425] = "Коли ви наближаєтеся до консолі, кристал доступу, який ви маєте при собі, починає тихо гудіти й пульсувати світлом.$B$BA Потік інформації хлине у ваш розум, і раптом ви усвідомлюєте рівні виробництва енергії манафорги, її стабільність та обсяги постачання до різних трубопроводів.  Консоль чекає на вашу команду.",  -- db:10045
[618986511] = "Не чіпай плащ! Так, так, я знаю, що ти теж хочеш такий. Усі хочуть мати один із моїх плащів. Повір мені, людино низьких моральних і соціальних стандартів, одного дня я збагачуся на продажу своїх плащів. Усі — відсюди аж до Айронфорджа — знатимуть ім’я Бартоло Гінсетті. Бренд «Гінсетті» буде бажаним для всіх!",  -- db:10047
[27018019] = "На бороду Мурадіна, $c. Ця земля стоїть на межі знищення. Я не можу уявити, щоб тут хтось вижив після закінчення Другої війни.",  -- db:10052
[349433238] = "Я шукаю когось, хто міг би допомогти мені з завданням, яке вже давно слід було виконати.$B$BВи здаєтеся мені підходящою людиною.",  -- db:10054
[492762704] = "Завдяки роботі, яку ти виконав для мене біля руїн Фаралона, я знову встигаю за графіком. Зараз я збираю свою команду, щоб вирушити туди.$B$BДякую, $N.",  -- db:10055
[312852684] = "Легіон усюди... з ними треба розібратися!",  -- db:10056
[812389794] = "Завдяки вам ми зможемо реалізувати наші плани щодо Руїн Фаралону.",  -- db:10057
[859075164] = "Ефіріум потемнів… спотворився. Помста стала їхнім єдиним виходом, і всіх, хто стоїть на їхньому шляху або не приєднується до їхньої справи, вони вважають ворогами. Багато хто побачив, що Ефіріум стрімко котиться у божевілля, і пішов геть. Кілька «Принців Нексусу» з ради Ефіріуму покинули Ефіріум, щоб утворити інші групи та фракції з іншими цілями. Консорціум — один із прикладів таких відгалужених угруповань. Протекторат — ще один...",  -- db:10060
[440483242] = "Привіт. Я — Вікстон Пінчвістл, офіційний торговець на арені «Бойового цирку Steamwheedle». Якщо у вас є відповідна репутація, у мене є товари, від яких у вас потече слинка.",  -- db:10062
[306310355] = "Якщо вас нудить, зверніться до Пестла. Можливо, у нього є щось від захитування.",  -- db:10063
[699320825] = "<Учень час від часу озирається через плече, мабуть, реагуючи на звуки, яких ти не чуєш.>$B$BДоброго дня, $N. Вибач, якщо я здаюся розсіяним, але я саме виконую доручення фермера Натіна. Я хочу, щоб усі його коні були підковані до того, як він повернеться з ратуші. Чим я можу вам допомогти?",  -- db:10064
[169064096] = "Агент Я-сікс і я отримали від командування Протекторату завдання найвищого пріоритету — знищити всі сліди зараження істотами Порожнечі на Ультрісі. Це мали бути тактичні удари. Нашим останнім завданням перед поверненням до спостережного пункту Протекторату мав стати удар по володареві Порожнечі на ім’я Арконус, який наживався на плотських істотах цієї місцевості.$B$BНа жаль, ми прибули трохи запізно. Я-сікс і я розлучилися під час перестрілки з плотними тварюками. Тепер він опинився в пастці всередині, заблокований за лінією фронту.$B",  -- db:10065
[986678383] = "Обов’язково завітайте до Вікстона Пінчвістла в Зоні 52 Нетершторма. Як офіційний продавець на Арені Бойового цирку «Стімвідл», він пропонує на продаж найрізноманітніші неймовірні предмети тим, хто має достатню кількість очок Арени.",  -- db:10069
[887420245] = "Що ти кажеш?! Я щось чула про одну з тих дивних істот-драені в Долині Героїв. Можливо, вона щось знає; а я — ні.",  -- db:10101
[355743344] = "Ми не любимо паладинів. Ельфійка приїхала до міста, оселилася в Королівському кварталі. Її супроводжує паладин. Поговори з нею, дізнайся про паладинів.",  -- db:10107
[494104088] = "Паладин? Ти, бува, не пробував зілля від Аптекаря чи щось подібне? Я чув чутки, що якийсь ельфійський загін відвідав Темну Леді в Андерсіті. Можливо, хтось із них щось знає.",  -- db:10108
[375747723] = "Твоя допомога була неоціненною, друже.$B$BI можу запевнити тебе, що Експедиція Сенаріону зробить усе, що в її силах, аби протистояти будь-яким майбутнім зараженим кристалам, які Іллідан скине з небес.",  -- db:10109
[441374810] = "Воно тут... десь... Я це знаю. Десь у цій бібліотеці є ті знання, які я шукаю...",  -- db:10124
[254560275] = "Ця вежа — це суцільне божевілля. Це не бібліотека, а величезний стог сіна з книг, і я навіть не думаю, що голка там взагалі є! Ну, що я там робив?",  -- db:10125
[944641801] = "Ваша присутність тут заважає виконанню дуже важливої роботи. Будь ласка, негайно вийдіть. На чому я зупинився?",  -- db:10126
[870826135] = "СТОП, $c! Шлях до наступного боса не тут. Спробуй інший шлях.",  -- db:10128
[373760969] = "Вітаю, смертний. Я — Навууд, головний дослідник на цьому спостережному посту Протекторату.",  -- db:10152
[874460671] = "Те, що ми покинули Каельтаса, було найкращим рішенням, яке будь-хто з нас коли-небудь приймав. Його послідовники або занадто засліплені, або занадто налякані, щоб усвідомити, куди він їх веде.$B$BМи ж, навпаки, не такі.",  -- db:10153
[411629054] = "Серед ефірних істот є такі, які займаються саме плоттю та істотами з плоті. Цих істот називають «помічниками плоті».",  -- db:10179
[58085486] = "Якщо ви хочете зареєструвати гільдію, раджу звернутися за інформацією безпосередньо в межах міста Сільвермун.",  -- db:10182
[1041681] = "Амір, можливо, і хвилюється через те, що роблять прихильники Ethereum, але я повністю зосереджений на справжній небезпеці: Dimensius.",  -- db:10202
[485830779] = "У інші часи та в іншому місці мене б вважали лише юнцем. А тут я — досвідчений воїн, готовий жити й померти за славу наару.$B$BНас було десятеро, коли ми увійшли до «Манафордж Ара». Усі інші загинули від рук Легіону.",  -- db:10209
[437515523] = "Настав час зіткнутися з Сокретаром, $N.  Ви готові?",  -- db:10210
[14597956] = "Це Скрайери послали тебе зв’язатися зі мною? Ти зовсім не схожий на Скрайера.",  -- db:10211
[378181133] = "Говори швидше; у мене немає часу на пусті балачки. «Покинуті» стали силою, з якою треба рахуватися, але за день ще багато чого треба встигнути. Це місто само собою не керується.$b$bЧого ти хочеш?",  -- db:10212
[539816304] = "Гаразд, $c. Ти вважаєш, що в тебе вистачить сил, щоб довести свою майстерність на аренах бойового турніру «Steamwheedle Fighting Circuit»?",  -- db:10215
[221970859] = "Ви знайдете майстрів бою біля бойового столу в Залі зброї.",  -- db:10216
[257376941] = "Ви знайдете бойових майстрів, які зібралися на Терасі Воїнів.",  -- db:10217
[151592061] = "Ви знайдете майстрів бою у військовій кімнаті фортеці Штормовій.",  -- db:10218
[565308447] = "Відправляйтеся до Хантер-Райз. Там ви знайдете майстрів бою.",  -- db:10220
[776501758] = "Ви знайдете майстрів бою всередині Залу хоробрих у Долині Честі.",  -- db:10221
[149084071] = "Ти йдеш до «Роял-Квотер». Вони всі там, сидять колом по кімнаті.",  -- db:10222
[414407119] = "О, так, я купила мафіни!",  -- db:10224
[109214972] = "Людино, я — капітан Саїд із Протекторату, а ці солдати, що стоять поруч зі мною, — мої месники. Ми чекаємо на накази від плотського створіння, яке знищило провідник порожнечі. За наказом цього плотського створіння ми піднімемося до лігва Діменсіуса й чекатимемо на сигнал, щоб завдати остаточного удару!$B$BЦе тривало занадто довго... Володар порожнечі незабаром зіткнеться з нашою об’єднаною міццю!",  -- db:10229
[664359413] = "Нетер-дракон дивиться на тебе з схваленням.",  -- db:10230
[414502302] = "Ось і все, $N. Ми стягуємо плату за ваші замовлення! Лише скажіть слово — і ми з моїми людьми вступимо в бій!",  -- db:10232
[855485078] = "Ласкаво просимо до «Еко-Дома» у Середньому Королівстві, мандрівнику. Хочу попередити тебе: будь обережним у спілкуванні з тим гобліном, Шаулі. Не пригадую, щоб хтось раніше вживав слово «приятель» як розділовий знак.",  -- db:10233
[951371719] = "Якщо ти вже збираєшся сюди прийти, то принеси хоч якусь користь, бо той тіньовий мисливець там майже нічого не робить.",  -- db:10236
[40474555] = "Битва за гору Гіжал — одна з найбільш ретельно охоронюваних подій цієї часової лінії.  Якщо зловмисник змінить її результат, це вплине на всі наступні моменти в історії.$B$BЯк головний супутник Аспекта, я набагато краще відчуваю плин часу, ніж інші бронзові дракони.  Нещодавно я відчув ледь помітну хвилю в часі, що виходила від подій, пов’язаних із битвою на горі Гіял.  Хтось або щось намагається змінити цю часову лінію, і це необхідно зупинити.",  -- db:10237
[960240825] = "Чого ти хочеш? Говори відверто. Я не збираюся довіряти тобі жодного зі своїх Елекків, доки ти не доведеш свою відданість і дружбу до нашого народу.",  -- db:10239
[486939969] = "Наша робота в «Живому гаї» не повинна опинитися під загрозою. Від його подальшого здоров’я та зростання залежить саме наше життя.",  -- db:10245
[699901134] = "Якщо я правильно зрозумів, ти вже робиш хорошу справу для Сильванаара.$B$BПродовжуй у тому ж дусі, і, можливо, нам вдасться зберегти наш дім тут.",  -- db:10247
[673382575] = "Іди відпочинь, мандрівнику. Наші багаття — у твоєму розпорядженні.",  -- db:10249
[863685018] = "Саме тут Гул'дан розірвав зв'язок між орками та духами стихій. Його невгамовна жага до влади не могла бути вгамована навіть повним знищенням драені. Він мусив також знищити Дренор, спустошивши землю та висмоктавши всю її енергію для використання у своїй війні.$B$BТепер залишилися лише залишки його божевілля.$B$BПоглянь на вівтар, $r — ця земля назавжди проклята...",  -- db:10250
[394931505] = "Я вшановую своїх предків згідно з давніми шаманськими традиціями. Ми ніколи не повинні забувати про ті жертви, які вони принесли, щоб ми могли бути тут.$B$BА ми, у свою чергу, маємо принести необхідні жертви, щоб у наших нащадків було майбутнє.$B$BЩо привело тебе до мене, $c?",  -- db:10251
[282794419] = "Не так давно нам довелося відбивати фортецю «Громового Лорда» у сусідніх огрів.$B$BВи приїхали, щоб допомогти нам утримати наші оборонні позиції?  Я знаю, що Гор’дрек шукає підмогу.",  -- db:10252
[525153238] = "Як тобі війна, $n? Просто пам’ятай, чому ми тут… Це значно полегшує боротьбу і смерть.",  -- db:10253
[779309651] = "Експедиційний пункт — важке місце для дислокації, але воно має вирішальне значення для оборони Честі. Інформація, зібрана тут, а також бої, які ведуть наші солдати проти Легіону та орків Зет’Гора, мають неоціненне значення для кампанії Альянсу «Пекельний вогонь».",  -- db:10255
[817843473] = "Я чув, що ти вже почав брати на себе частину роботи тут.$B$BДобре. Я вже почав хвилюватися, що нам доведеться тебе «переконувати», щоб ти допомагав.",  -- db:10256
[688635239] = "Шкіра, що туго натягнута між кістками, — це заклик до зброї проти головного захисника Сильванаара Альянсу та Живого Гаю на заході.",  -- db:10257
[725937084] = "Привіт, я Азімі! Я часто приходжу сюди, щоб продавати чоловікам свіжі фрукти та воду. Ви голодні чи, може, хочете пити?",  -- db:10258
[75785945] = "Фу!  Хіба я виглядаю так, ніби в мене є час на пусті балачки?$B$BХіба так?$B$BШвидше переходь до справи.  Треба вбити огів!",  -- db:10259
[544925107] = "Ласкаво просимо до Притулку Сенаріону, $n. Мені доручили запропонувати вам придбати найнеобхідніші товари, якщо вони вам знадобляться.",  -- db:10266
[64936236] = "Ти готовий битися проти Гвардії Штормпайка в Долині Альтерак, $n?",  -- db:10269
[590371220] = "Боргрім, можливо, має рацію. Можливо, нам дійсно варто зробити перерву.$B$BАле раз ми вже тут, мені не терпиться взятися за справу і дослідити, що ж може запропонувати ця земля.",  -- db:10271
[202010658] = "$n, радий тебе бачити. Наші союзники-гноми потребують нашої допомоги в Долині Альтерак. Чи допоможеш ти їм?",  -- db:10272
[966863409] = "Навіть зараз неживі, що володіють власною волею, ведуть битву проти Ліги Аратора в Аратській улоговині. Чи допоможете ви «Осквернителям» перемогти людей та їхніх союзників з Альянсу?",  -- db:10276
[461778172] = "Тром'ка, $n.  У «Ущелині Воєнних пісень» потрібні такі герої, як ти.",  -- db:10277
[63996980] = "Наші друзі з Альянсу збираються, щоб битися пліч-о-пліч із «Срібнокрилими вартовими» в Ущелині Воєнної Пісні. Чи вирушиш ти туди, щоб допомогти їм?",  -- db:10279
[565858444] = "Вітаю, мандрівнику. Я — Оронок. Будь ласка, сідай біля мого багаття й зігрійся.$B$BСтережись голодних звірів із розтрощеного шельфу під нами!",  -- db:10280
[101104894] = "Не забувай, $c, що в Азероті досі точаться запеклі бої. Чи повернешся ти, щоб допомогти Орді в Долині Альтерак?",  -- db:10282
[29545390] = "Тром'ка, $c. Ти знав, що наша битва зі «Срібнокрилими вартовими» в Ущелині Воєнної Пісні досі триває? Твоя присутність там була б дуже доречною...",  -- db:10283
[706195311] = "Я подолав велику відстань у пошуках способу остаточно перемогти Лігу Аратора в Аратській улоговині, але той неотесаний Адам Етернум, одягнений лише в набедрену пов’язку, переслідує кожен мій крок.$B$b$BТа все ж, якби такі вбивці, як ти, повернулися до Азероту, можливо, ми змогли б раз і назавжди перемогти Альянс!",  -- db:10284
[593265413] = "Як справи? Наситилися Замежжям і готові повернутися до Долини Альтерак, щоб дати Орді прочуханки?",  -- db:10285
[927541600] = "«Срібні крила» досі ведуть боротьбу з Ордою в Ущелині Воєнної Пісні, $c. Залишається лише дізнатися, чи повернетеся ви туди, щоб допомогти їм.",  -- db:10286
[20522998] = "Я прибув до Аутленду, сподіваючись знайти могутні артефакти, які допомогли б Лізі Аратора у боротьбі проти Осквернителів в Аратській улоговині... але все, що я знайшов, — це ця чудова магічна набедрена пов'язка, безглуздий гном-помічник і егоцентричний нежить-переслідувач, який наполягає, що я вкрав його сірий череп, чи щось таке.$B$b$BУ будь-якому разі, чи не хотіли б ви приєднатися до Ліги в її боротьбі, поки я продовжую свої пошуки?",  -- db:10287
[813482697] = "<Складається враження, що Орік з’явився тут лише як невдала спроба додати комічного ефекту, і на нього не варто звертати уваги, бо це лише підбадьорить його.>",  -- db:10288
[143952998] = "<Це гігантський, броньований бойовий кіт із сідлом. Хіба це не досить безглуздо й без того, щоб він ще й розмовляв?>",  -- db:10290
[208804279] = "Лише маг може опанувати магію порталів, $c.",  -- db:10291
[93011528] = "Маг... ти хочеш опанувати магію порталів, так?",  -- db:10292
[634665642] = "Королівське товариство аптекарів Підміста прагне допомогти нашим союзникам-оркам тут, у Замежжя. Це чудова нагода зміцнити наші зв’язки та знайти нові зразки й сполуки для дослідження.$B$BСполуки… такі як отрути.",  -- db:10293
[982907466] = "«Whitereach Post» — це для мене, м’яко кажучи, несподівана зупинка. Мої клієнти розраховують, що я доставляю їхні товари, і я починаю сумніватися, чи встигну я вчасно, зважаючи на всі ці затримки.",  -- db:10299
[674619489] = "Гей, не відкривай клітку!  Гаразд?$B$BЦі огри потрапили саме туди, куди я їх і хотів заманити.",  -- db:10300
[425787183] = "Мені кажуть, що пил і спека на Півострові Пекельного Вогню досить неприємні... Я цього не знаю, але довіряю своїм шанованим союзникам, які ще живі.",  -- db:10301
[865984407] = "Не варто легковажно ставитися до втрати навичок елементальної шкіряної справи. Якщо ви вирішите відмовитися від них, то забудете й усі рецепти, для яких потрібні ці навички!",  -- db:10302
[909352880] = "Ти не зможеш придбати тут жодного «Яструбобіжця», доки не доведеш свою цінність та відданість нашому народу.$bНе повертайся, доки не здобудеш повагу серед кровних ельфів. Геть звідси!",  -- db:10305
[291086241] = "Ці орки, мабуть, дуже хочуть закріпитися в Замежжя! Якби я тобі сказав, скільки вони платять за мою лояльність, ти б мене вбив від заздрощів!",  -- db:10306
[320826882] = "Якщо у тебе є золото, я можу навчити тебе їздити на яструбобігуні.",  -- db:10308
[911634682] = "Ти повинен завоювати повагу у кровних ельфів, перш ніж я навчу тебе їздити верхи, $c.",  -- db:10310
[272919388] = "Я прибув сюди в рамках свого дослідження відсталої культури, якою колись був клан «Громового Володаря».$B$BВони були слабкими й піддалися спокусі влади, що супроводжувала перетворення на фел-орків завдяки крові Маннорота.$B$BЯ прочитав усі їхні тексти.  Мене особливо цікавить пошук артефакту — барабана, стріли та таблички, які загубилися, коли ми розгромили огрів з Блейдспайра та відтіснили їх назад у їхню фортецю.",  -- db:10322
[654672830] = "Бездиханне тіло Ар'тора й досі зависає в повітрі завдяки демонічній магії. Вони забирають у нього все, навіть після смерті...",  -- db:10323
[731126050] = "Я радий, що ти вирішив приєднатися до нашої справи.  В якості нагороди я наповню перстень залишками «Криниці Вічності», які ти мені приніс.$B$BI пропоную тобі чотири різні шляхи, за допомогою яких ти зможеш розкрити їхню силу.  Вибирайте мудро, $N.  Піски часу легко течуть в одному напрямку, але не в іншому.",  -- db:10324
[701619704] = "Я... помер.$B$BЧому я досі тут? Невже немає тих чудових мисливських угідь, куди я маю піднятися?$B$BNі... Спочатку я мушу виконати своє завдання. Перш ніж я зможу покинути цей світ, треба віднайти другу частину «Шифру прокляття».",  -- db:10327
[672897889] = "Не варто легковажно ставитися до втрати навичок ковальства. Якщо ви вирішите відмовитися від них, то забудете всі рецепти, для виготовлення яких потрібні навички ковальства!",  -- db:10329
[692215078] = "Як забажаєш, $N. Мисливець на духів готовий.",  -- db:10338
[94465852] = "Я відслужив свій термін у окопах і багато років присвятив навчанню молодих бійців. Приємно повернутися додому. Хай там що з ним сталося, це — мій дім.",  -- db:10339
[163398073] = "Доглядати за цими безстрашними звірами, які стоять між моїми одноплемінниками та смертю, — це честь.",  -- db:10339
[315699978] = "Ці людожери закопали мене тут по шию, а потім забули повернутися.$B$BАга, чувак, смішно.  Смійся скільки хочеш.  Ось я — голова привида без тіла.$B$BЗвісно, якщо ти захочеш мені допомогти, я, можливо, зможу винагородити тебе.$B$BАле ні, смійся далі.",  -- db:10341
[291738121] = "Стій рівно, солдат! Тепер ти перебуваєш під командуванням гвардії Кор'крона.",  -- db:10350
[761791111] = "Феральфени, що мешкають у Зангарських болотах, мають плетені кошики з хитрими замками.  Вони, безперечно, стануть випробуванням навіть для вашої вправності.",  -- db:10354
[796828106] = "Скрині у фортеці Кіл'Сорроу в Награнді стануть серйозним випробуванням навіть для розбійника з вашими неабиякими навичками.",  -- db:10355
[75119039] = "Станція Тошлі — найкраща!  Усамітнення та наявність дивних джерел енергії з Замежжя створюють ідеальні умови для екстремальних експериментів!",  -- db:10359
[892674739] = "Ти розмовляв з моїм клоном... тобто... з моїм близнюком?",  -- db:10360
[358329410] = "Не можу повірити, що вони змусили мене вивезти мій транспортер за межі міста!   Більшість гномів, які постраждали в результаті аварії, за кілька тижнів знову набули якоїсь людиноподібної форми, і для мене мала б бути честю взяти участь у такому грандіозному гномському експерименті!$B$BB Крім того, нам потрібні були яйця!$B",  -- db:10363
[811855539] = "Дякую, що витягнув мене звідти. Я у тебе в боргу!",  -- db:10373
[293668593] = "Тепер я, мабуть, зможу звідси вибратися. Дякую!",  -- db:10373
[743081250] = "Це лише невеличкий збірник пісень, який, як мені здалося, тобі може сподобатися. У ньому містяться слова пісні під назвою «Плач Високородних» — тієї самої, яку леді Сильвана зачарувала прямо з повітря.",  -- db:10378
[719310532] = "Поштові скриньки ви знайдете всередині або безпосередньо біля банків та готелів Альдора та Скрайєрів.",  -- db:10403
[982903355] = "Біля готелів драені та кровоельфів на Піднесенні Альдора та Уступі Скрайєра знаходяться майстри стайні.",  -- db:10404
[693442679] = "Інессера — кмітлива жінка, яка продає різноманітні дорогоцінні камені, а також матеріали для ювелірної справи. Її крамницю можна знайти в північній частині Альдор-Райз.",  -- db:10411
[819259213] = "Лісріт спочатку може здатися трохи... грізною, але у неї є саме те, що вам потрібно. Вона продає свої товари біля великої бібліотеки на Рівні Скрайєра.",  -- db:10412
[512001268] = "Високого чарівника Бардолана можна знайти в Бібліотеці Провидців на Рівні Скрайєра. Цей великий майстер свого мистецтва оточений своїми учнями: майстрами, ремісниками, фахівцями та підмайстрами.",  -- db:10415
[64912289] = "Сеймура, головного шкіряника в Шаттраті та великого майстра цієї справи, можна знайти на відкритому ринку Нижнього міста.",  -- db:10419
[868896942] = "Ми почнемо бій, коли ти будеш готовий, $N.",  -- db:10421
[673917864] = "Я ВОЛОДІЮ БІЛЬШ НІЖ ДВОМА МОВАМИ: ДВОРФІВСЬКОЮ, ГНОМІВСЬКОЮ ТА ДУЖЕ ПОШИРЕНОЮ МОВОЮ ЛЮДЕЙ.  АЛЕ Я НЕ МАЮ ЖОДНОГО УЯВЛЕННЯ, ЩО ТИ КАЖЕШ!$B$BГОВОРИ ГОЛОСНІШЕ; Я НЕ ЧУЮ ТЕБЕ ЧЕРЕЗ СКРИП МОЇХ ШЕСТЕРЕНЬ!",  -- db:10422
[245432974] = "Ага, ага... ласкаво просимо на мою станцію.$B$BНу, що скажеш?  Досить непогано вийшло, чи не так?$B$BУ всякому разі, я радий, що позбувся тих занудних ельфів із Сильванаара.$B$BПостарайся бути корисним тут; є чимало експериментів та інших справ, у яких ти можеш допомогти.",  -- db:10423
[662572185] = "Слава Наару, $N.  Світло незабаром переможе своїх ворогів.",  -- db:10424
[634428703] = "<Від некроліта випромінюються хвилі темної магії.>",  -- db:10434
[883312379] = "<Замерзла, гарчача паща оркового вовка пронизує тебе до кісток.>",  -- db:10439
[93605270] = "Я — науковець, який досліджує і час, і звук, тож не зовсім розумію, як мені тут думати чи знайти час, щоб хоч щось зробити, коли навколо такий галас?!$B$BЧому ці дурні не можуть піти підірватися десь інде?$B$BНу що ж, принаймні я гарно виглядаю.  Слухай, $g хлопче : lovely;, я тебе тут раніше бачив?",  -- db:10444
[655740493] = "Для багатьох представників мого народу я відомий як зрадник... як песик Іллідана. Наразі краще, щоб вони й надалі так думали.",  -- db:10447
[187618546] = "Усі винагороди за надані послуги виплачуватиме воєнний посланець Сардон Трусліс.$B$BРозклеювати оголошення заборонено.",  -- db:10448
[136407726] = "Усі винагороди за надані послуги виплачуватиме Варколлер Бірсноут.$B$BРозклеювати оголошення заборонено.",  -- db:10449
[392921518] = "Вас цікавить вивчення тонкощів ювелірного мистецтва?",  -- db:10451
[497739357] = "Що ви хотіли б дізнатися про ювелірну справу?",  -- db:10454
[513986258] = "Доки ти не освоїш рівень «Учень» у ювелірній справі, ми більше не будемо розмовляти.",  -- db:10455
[658387300] = "Я поділюся з вами своїми знаннями з ювелірної справи.",  -- db:10456
[443442281] = "Хотів би я мати більше часу, щоб навчити всіх, хто прийшов до мене раніше, але, на жаль, так не буває. Доки ти не засвоїш усе, чого може навчити Падаар, я не зможу тобі допомогти.",  -- db:10458
[625960188] = "Мені дуже приємно, що я можу допомогти такому досвідченому майстру, як ви, дізнатися більше про ювелірну справу. Що ви хотіли б дізнатися?",  -- db:10459
[164028336] = "Я дуже зайнятий, $r.$B$BУ нас виникла жахлива проблема, яку потрібно вирішити негайно!",  -- db:10460
[729784042] = "Коли ти воюєш у лавах «Рауграйдерів» Разака, ти дізнаєшся дещо про те, як виконувати накази.$B$BПо-перше, ти воюєш до самої смерті.  По-друге, дивись перше.",  -- db:10466
[780263394] = "Потрібно нагострити клинок чи, можливо, придбати нову зброю? Краще перестрахуватися, ніж потім шкодувати...",  -- db:10467
[944733868] = "Якщо ви шукаєте молоток, то потрапили за правильною адресою.",  -- db:10468
[233731660] = "$G Син: Пані, я не буду вам брехати: тут справи йдуть не дуже добре. На нас постійно нападають комахи, і на кону стоїть сам наш спосіб життя, наша свобода!$B$BВи будете відповідальною громадянкою і допоможете нам?",  -- db:10469
[898410975] = "Чудово! Дивовижно! Прекрасний виступ!",  -- db:10471
[784909089] = "У молодості я наполегливо готувалася, щоб стати відлюдницею-священицею. Про жінок-екзархів тоді практично ніхто не чув.$B$BСьогодні гендерна приналежність не має великого значення — вирішальну роль відіграють мужність і переконання.",  -- db:10473
[668202693] = "Якщо ви готові й бажаєте швидко повернутися до звичайного часового потоку, я можу перенести вас до Андорму в Печерах Часу.",  -- db:10474
[864538423] = "Ви тут, щоб допомогти впоратися з заворушеннями?",  -- db:10491
[435255710] = "Геть, смертний! Твоєму роду тут не раді...",  -- db:10496
[766958469] = "Можна вивести людину з лав «Синів Лотара», але не можна вирвати з неї дух «Синів».$B$B<Коваль знизує плечима.>$B$BВажко пояснити, але я просто відчуваю, що зараз мені не місце в «Охоронній фортеці», ось і все.$B$BМожливо, мені судилося стати частиною чогось більшого.",  -- db:10500
[682269193] = "«Ще зарано тобі мною керувати, адже ти щойно вийшов із гри».",  -- db:10505
[888191933] = "Які б поради я не міг дати, щоб допомогти вам у боротьбі з ограми, ви їх отримаєте!",  -- db:10508
[837509208] = "Згідно з описом оголошення, потрібно вбити величезного вовка. Судячи з усього, вона мешкає на південь від Гострого хребта, неподалік від фортеці Орди.",  -- db:10509
[883170360] = "Вітаю, $c — я — офіцер з нагородження, який діє від імені міста Сільвермун.  Мій обов’язок — допомагати мандрівникам, які отримали печатки нагород Орди.$B$BЯ приймаю печатки в різних кількостях, але найвигіднішим для вас варіантом обміну буде здача набору з десяти печаток одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від міста Срібного Місяця за свій обов’язок і службу.",  -- db:10530
[57061519] = "Вітаю, $c — я офіцер з нагородження, що діє від імені Екзодара.  Мій обов’язок — допомагати мандрівникам, які отримали Печатки нагород Альянсу.$B$BI приймаю печатки в різних кількостях, але найвигіднішим для вас варіантом обміну буде здача набору з десяти печаток одразу.  Коли ви здасте свої печатки, я внесу ваші подвиги до наших записів.  У результаті ви отримаєте визнання від Екзодара за свій обов’язок і службу.",  -- db:10531
[32839881] = "Ми прибули до Руанського лісу, щоб спробувати відновити природну рівновагу в цих горах.$B$BОднак втручання араккоа та культа драконів ускладнює це завдання.$B$BНа щастя, є такі, як ти та Самія, які готові нам допомогти.",  -- db:10534
[740324212] = "Ха-ха, ти знову тут?  Ти ж не сподіваєшся, що я передумаю, правда?$B$BЗабирайся геть.",  -- db:10535
[66993541] = "Я відчуваю заряд у вашій паранарбулатричній зоні! Ви, мабуть, нещодавно користувалися «Зефіріум Капаціторіум» — ви не зможете скористатися ним знову, доки заряд не зникне...",  -- db:10537
[962753723] = "Я перебуваю тут за дорученням свого господаря, барона Сейблмейна, щоб допомогти Експедиції Сенаріону у вирішенні проблем, пов’язаних із культом драконів.$B$BIЯ є своєрідним експертом у цих питаннях.",  -- db:10538
[304832335] = "Нуар, ти добре почуваєшся?  Ти сьогодні виглядаєш не так, як зазвичай.",  -- db:10539
[966225388] = "Гаразд, щодо наради.  Тоді давайте перейдемо до справи.$B$BСправа в тому, що збір деревини та худоби з Руанського лісу, за який ви відповідаєте, майже зупинився.$B$BНам потрібні ці ресурси, але ви дозволили друїдам Експедиції Сенаріона втрутитися!",  -- db:10541
[2408630] = "Мені не потрібні виправдання, я вимагаю результатів!$B$BТи думаєш, те, що ми тут робимо, — це жарт?  Якщо ми не зробимо це як слід, то не тільки так звані благодійники прийдуть до нас, але й нас визнають негідними підвищення в рядах «Чорного крила».$B$BЦе те, чого ти хочеш?",  -- db:10542
[589569677] = "Ти міг би хоча б спробувати звучати трохи переконливіше.$B$BСлухай, Нуаар, я не збирався тобі цього розповідати, але, мабуть, варто, бо це стосуватиметься й тебе.  Макснар планує тотальний напад на друїдів у Руанському лісі.  І він має намір їх повністю знищити.$B$BНам і так вистачає проблем із боями проти огрів Боулдермоків, тож ми не можемо собі дозволити ще один фронт.  Я домовився про тимчасове перемир’я з аракоа.$B$BНу, що скажеш?",  -- db:10543
[60762407] = "Саме зараз ми завершуємо останні приготування.  Решта залежатиме від того, як швидко ви зможете мобілізувати свої сили в Рууан-Веалді.$B$BЯк ви гадаєте, чи зможете ви впоратися з цим і зробити це швидко?",  -- db:10544
[23506515] = "Ось це настрій!$B$BЯ радий, що ми провели цю невеличку зустріч.  Тепер я набагато спокійніше ставлюся до цієї атаки.  З такими лідерами, як ти, на передовій, як ми можемо програти?$B$BГаразд, ти отримав свої накази.  А тепер повертайся до Руанського лісу й втілюй їх у життя!",  -- db:10545
[484511497] = "Каразан не завжди був таким… зловісним.  Каразан поринув у темряву лише після смерті Медівха.  Або після того, що ми вважаємо смертю Медівха.",  -- db:10546
[189913406] = "Схоже, вам може знадобитися переправа через Велике море. Що ж, ви потрапили в потрібне місце — це причал корабля «Мрія Діви», найкращого пасажирського судна, що курсує цими водами. Коли він прибуде, просто підніміться на борт, і, не встигнете озирнутися, як вже будете насолоджуватися сонцем на піщаних пляжах Стренглторна.",  -- db:10547
[119916507] = "Ти дійшов аж сюди, солдате. Тепер назад дороги немає.",  -- db:10549
[292663712] = "Суньте босові в руку монетку — і подивіться, що з того вийде. Я люблю свою роботу. Хоча, якби я зміг придумати спосіб перевести того маленького бешкетника Снурка в цей порт… ну, краще й уявити не можу. Але я готовий побитися об заклад, що ти тут не через мої ділові практики. Ти шукаєш цепелін до Андерсіті, я правий? Ну, це чудово, бо він пришвартований прямо тут, за моєю спиною. О, і, до речі, якщо побачиш Снурка, скажи за мене кілька добрих слів, гаразд?",  -- db:10550
[472980474] = "Привіт, красуне, тобі потрібна підвозка до Гром'гола? Кажуть, у тих джунглях там дуже спекотно, може, я приєднаюся до тебе на короткий відпочинок і покажу тобі справжню джунглеву кішку.",  -- db:10551
[230482090] = "Звісно, немає жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить вас до Андерсіті швидше й безпечніше, ніж будь-який човен, а краєвид звідти справді захоплює дух. До речі, про дихання: на борту цепеліна заборонено палити, а під час польоту заборонено застосовувати вогняні заклинання.",  -- db:10552
[978516297] = "Привіт, наглядачу.  Готовий до атаки?",  -- db:10553
[46106898] = "Ці друїди відкрили для себе неймовірне джерело сили! Вони можуть перетворюватися на тварин... випромінювати блискавки та яскраве місячне світло... Я мушу з’ясувати, як їм це вдається!$B$BМожливо, під цими мантіями вони носять батарейки...",  -- db:10554
[735745966] = "<Аракоа дивиться на тебе пронизливим поглядом, то зупиняючи на тобі погляд, то дивлячись крізь тебе.>$B$BЩо ж принесли наші зусилля, як не ще більшу огиду, ніж та, яку ми намагалися запобігти?",  -- db:10556
[472210554] = "З цього причалу можна дістатися до Терамора. Прислухайтеся до моїх слів: для представників Альянсу подорожі цими землями рідко бувають безпечними. Будьте обережні й пильнуйте за спиною.",  -- db:10557
[176580632] = "У Замежжя наші війська ведуть боротьбу проти Орди за контроль над Оком Бурі. Боротися серед бурхливих енергій Нетера — справа небезпечна. Чи вистачить у вас сил, щоб приєднатися до нас?",  -- db:10558
[914278243] = "$N! Підійди сюди! Ти, мабуть, знаєш про битву, що вирує в Долині Альтерака. Нам потрібні всі боєздатні бійці, яких тільки зможемо зібрати. Бийся разом із Гвардією Штормпайк і переможи Морозних Вовків!",  -- db:10560
[849091297] = "Цей політ приведе вас до найвіддаленішої точки «Співаючого хребта».  Дуже небезпечно!$B$BДля цього польоту мені знадобиться підписана відмова від претензій...",  -- db:10561
[202943473] = "Ми завжди з нетерпінням чекаємо на нові дані про польоти! Куди ви хочете полетіти?",  -- db:10562
[789474215] = "То що ж це таке? Хіба ти не бачиш, що я зайнятий карлик?",  -- db:10563
[902149335] = "Хоча дослідження цих нових земель, без сумніву, є важливим, ти не повинен залишати Азерот! Зараз, як ніколи раніше, ти нам потрібен у боротьбі проти Осквернителів. Ці ресурси необхідно захистити!",  -- db:10565
[455692679] = "Ти, $c! Нам потрібна твоя допомога! Жорстокі орки з племені «Військової пісні» руйнують дивовижну красу Ешенвейлу, і нам потрібна твоя сила, щоб протистояти їм на полі бою. Повернися з нами до Азероту й бийся за честь «Срібнокрилих вартових»! Приєднаєшся до нас?",  -- db:10566
[106592898] = "Є старе прислів’я: «Дай людині рибу — і ти нагодуєш її на один день. Навчи людину ловити рибу — і ти нагодуєш її на все життя». Звісно, можливо, ви захочете приготувати цю рибу — і саме тут я й приходжу на допомогу.",  -- db:10568
[922887618] = "Привіт, $n!  Як там твої пригоди? Мої експерименти просуваються чудово...$B$BОбов’язково зв’яжися зі мною пізніше!   Можливо, у мене з’являться для тебе нові можливості для випробувальних польотів!",  -- db:10569
[131321109] = "Сила і честь, $c. Нам потрібні такі завзяті воїни, як ти, у Долині Альтерак; територію «Морозних Вовків» треба захищати! Чи повернешся ти до Азероту, щоб надати нам допомогу?",  -- db:10570
[21779102] = "$R! Так, саме ти! Навіщо ти марнуєш час, байдикуючи в цьому розваленому місті, коли твоє справжнє місце — в Аратській улоговині? Ліга Аратора веде безжалісний наступ; твій внесок необхідний, і ти отримаєш нагороду!",  -- db:10571
[658743540] = "$C, повернувшись до Азерота, ми бачимо, що «Срібнокрилі вартові» заважають нам просуватися лісом. Нам потрібна ваша допомога на фронті, щоб відкинути їх назад! За допомогу ви завоюєте велику честь і репутацію серед «Військових вершників» — приєднуйтесь до нас вже зараз!",  -- db:10572
[26884257] = "Незабаром розпочнеться турнір гоблінів «Steamwheedle Fighting Circuit». Зараз на їхніх аренах проводяться тренувальні поєдинки, але змагання за рейтинг розпочнуться через $4262d.",  -- db:10576
[639427506] = "Розпочався турнір гоблінів «Бойовий цикл Стімвідла». У Гаджетзані, а також біля арен у Награнді та в Горах Лезового Краю ви можете знайти організаторів арени, які продають ліцензії на участь команд в арені.",  -- db:10578
[971650723] = "<Сивочолий гладіатор говорить уривчастою Загальною мовою.> Що? У тебе до мене якісь претензії? Вирішуй це на арені. Я не витрачаю час на твої дрібні «орди» та «альянси».",  -- db:10597
[548919786] = "Гладіатори заробляють право носити таке спорядження, як моє, перемагаючи в рейтингових поєдинках на арені.",  -- db:10598
[796651336] = "<Досвідчений гладіатор говорить уривчастою мовою орків.> Що? У тебе до мене якісь претензії? Вирішуй це на арені. Я не витрачаю час на твої дрібні «орди» та «альянси».",  -- db:10599
[477313075] = "Привіт! Ти чув про Бойовий турнір «Стімвідл»? У Гаджетзані, а також біля арен у Награнді та в Горах Лезового Краю можна знайти організаторів арен, які продають статути команд для участі в турнірі.",  -- db:10601
[663328040] = "Привіт.  Робиш перерву, наглядачу?  Ми тебе тут вже не так часто бачимо, відколи тебе перевели до Рууанського лісу.$B$BПоглянь, що я можу тобі запропонувати.  Можливо, з часу нашої останньої розмови тут мало що змінилося, але у мене є чимало цікавого.$B$BІ не забувай про нас!",  -- db:10602
[679451195] = "Мою огиду до перерв затьмарює лише моя ненависть до Груула, Вбивці Драконів, та його семи синів!",  -- db:10603
[955630658] = "Рейтингові поєдинки на арені розпочнуться о $4262d. Майбутні чемпіони вже активно відточують свої навички та збирають найкраще спорядження. А ви будете готові?",  -- db:10604
[259083982] = "Ти повинен... звільнити... моїх дітей...",  -- db:10605
[395897587] = "Вони не зможуть так триматися! Їхні крила рано чи пізно не витримають...",  -- db:10606
[36852729] = "Ага, ще один $c, який мріє стати гладіатором, так? Чудово!$B$BI продає абонементи на арену, які тобі знадобляться для участі в рейтингових поєдинках «Бойового турніру Стімвідл».",  -- db:10608
[109716315] = "Пост «Спайнебрейкер» — чудове місце для дислокації! Аберації з «Кривавої Ущелини» знаходяться так близько, що аж відчувається сморід їхньої гнилої крові! Чи може бути краще місце, щоб помститися клану, який зрадив своїх побратимів і уклав угоду з демонами?",  -- db:10610
[541819449] = "Фейрвезер і я перебуваємо тут, щоб відстоювати інтереси Сильванаара.$B$BДруїди проявили неабияку гостинність, але думка про те, що Орді дозволять пройти через ці землі, викликає у мене мурашки по спині.",  -- db:10612
[204072245] = "Боротьба проти Каель'таса та Іллідана триває на всіх фронтах.  Поразка не є варіантом.",  -- db:10625
[702243136] = "Я розумію, що ти приєднався до нас лише нещодавно, тому, можливо, ще не знаєш про наші традиції. У Місячній галявині зараз триває грандіозне свято. У цю пору року ми вшановуємо наших старших, і ти, безперечно, запрошений! Якщо хочеш долучитися, приїжджай до одного з наших міст!",  -- db:10631
[942614106] = "Місячний фестиваль в Азероті в самому розпалі! Поверніться туди та вшануйте своїх старших під час цього чудового свята! Основні урочистості відбуваються в Місячній галявині, але ми організували зручне сполучення зі Штормовію, Айронфорджа, Дарнассуса, Грім-Блаффа, Оргримара та Андерсіті. Сподіваємося побачити вас там!",  -- db:10634
[276175686] = "У цьому місці приховані таємниці, які ми, орки, так прагнемо розкрити. Таємниці нашого минулого, таємниці нашого майбутнього, а також таємниці, що дають змогу зазирнути вглиб нас самих.$B$BЯ сподіваюся розгадати ці таємниці... чи підеш ти цим шляхом разом зі мною?",  -- db:10636
[531799441] = "У лісі щось не так. Ми мусимо з’ясувати, у чому справа, поки не стало запізно!",  -- db:10637
[827327572] = "Незабаром я пущу коріння і засну.   Але перш ніж відпочити, мені ще треба дещо зробити.",  -- db:10640
[807236566] = "Ти на короткий час приніс зелень на мою землю.  Цього достатньо.  Я спокійний.  Я готовий до свого довгого сну.",  -- db:10641
[981837653] = "Успіх!  Я налаштувався на Цитадель Пекельного Вогню та магію, що в ній таїться.  О, яка сила!$B$BУ цьому місці безліч орків Фелу... але це ще не все!  Я відчуваю демонічну силу й усередині тих стін...$B$BЯкщо ти відкриєшся, я заволодію твоїм розумом — на короткий час, звичайно — і, взявши перо та пергамент, запишу для тебе свої висновки...",  -- db:10643
[322144168] = "Нас оточують вороги. Я хотів би забезпечити мок’наталам краще життя, але сили, з якими ми боремося, вирішили інакше.$B$BЯкщо ви хочете довести мок’наталам свою гідність, допоможіть нам знищити їх.",  -- db:10645
[382805166] = "Дивуєшся тому, що бачиш, незнайомцю?$B$BМи вшановуємо душі наших предків, підтримуючи полум’я їхньої пам’яті та віддаючи їм шану.",  -- db:10647
[740888024] = "Я можу навчити тебе алхімії.  Цікаво?",  -- db:10649
[222858886] = "Я можу дати вам уроки з інженерії.  Цікаво?",  -- db:10650
[34319640] = "Я можу навчити вас мистецтву зачарування.  Цікаво?",  -- db:10651
[860602019] = "Я можу навчити вас кравецькій справі.  Цікаво?",  -- db:10652
[377020918] = "Я можу навчити вас майстерності роботи зі шкірою.  Цікаво?",  -- db:10653
[470357105] = "Я можу навчити тебе ковальству.  Цікаво?",  -- db:10654
[431322652] = "Радий знову тебе бачити, друже.",  -- db:10655
[631497466] = "Приємно прогулятися й розім'яти всі чотири кінцівки. Чим я можу тобі допомогти, $c?",  -- db:10657
[438203184] = "Вітаю, $C.  Якщо дозволите, я хотів би нагадати вам, що — поки я налаштовуюся на магію Цитаделі Пекельного Вогню — за моїми п’ятами, безсумнівно, будуть ганятися вартові Пекельного Вогню!$B$BТож будьте гідним членом своєї Орди та зіграйте роль героя... і захистіть мене!",  -- db:10659
[760607424] = "Пошуки мого народу.  Наша боротьба проти Альянсу.  Війна з ограми та їхніми господарями — гроннами.$B$BУсе це тяжким тягарем лягає на мої плечі, $c.$B$BНавіть мені час від часу не завадить трохи допомоги.",  -- db:10661
[829505574] = "«Кузня Смерті» перебуває під управлінням Ради Тіней під пильним наглядом Легіону.",  -- db:10664
[438897377] = "Нижче зображено об’єкт із влучною назвою «Кузня Смерті». Якби Раді Тіней дозволити діяти на власний розсуд, вона забезпечувала б Легіон нескінченним потоком інферналів.",  -- db:10666
[458310654] = "Ми знаємо, що послідовники культу драконів збираються по той бік тунелю. Ми будемо чинити опір саме тут.",  -- db:10667
[306994497] = "Вітаю, $N. Я спеціалізуюся на мистецтві роботи з первинною місячною тканиною. Кравці, які хочуть стати фахівцями з місячної тканини, часто просять мене навчити їх нашим методам.",  -- db:10669
[845811853] = "Боюся, що я мало чого можу тебе навчити, $c. Звісно, ти можеш переглянути мої товари, але вони тобі не знадобляться.",  -- db:10670
[568977773] = "Приємно познайомитися! Я — Гідж, місцевий експерт із кравецької справи «Спелфайр» тут, у Шаттраті. Не те щоб тут була якась конкуренція, але якщо ви хочете навчитися кравецькій справі «Спелфайр» і ще не визначилися зі спеціалізацією, я можу вам допомогти.",  -- db:10671
[750865937] = "Якщо ви не кравець, то, мабуть, жодна з моїх викрійок вас не зацікавить, але можете сміливо переглядати!",  -- db:10672
[384906123] = "Вибач, $c, але мої товари найкраще підходять тим, хто знає, в який кінець голки втягується нитка.$B$BI Можу запевнити тебе, що кравецька справа — це набагато більше, ніж просто нанесення монограм на носовички.",  -- db:10674
[422752756] = "Ці «Сльози Богині» були благословенні Елуною, і їхня сила допоможе тобі протистояти мерзенній магії Архімонда. Використовуй їхню силу з розумом.",  -- db:10675
[465037419] = "Вони бояться моїх слів. Вони роблять мене прикладом для інших. Знущаються над єдиним істинним богом, Нептулоном.$B$B<Скар'тіс плюється.>$B$BНастане відплата, смертний. Славна рука Тідхантера одного дня пронесеться серед невіруючих, наче коса над новим урожаєм.",  -- db:10676
[891529560] = "Ці пустки позначені жахливою магією. Ми повинні зробити все, що в наших силах, аби загоїти цю велику рану.",  -- db:10677
[576752720] = "«Ворота Смерті» — це портал, що веде у світ, де «Палаюча Легіон» розводить своїх фельних псів та інших жахливих істот, схожих на собак.  Кожного разу, коли ви бачите одну з цих істот, знайте: саме звідти вона прийшла, і спочатку вона проходить саме тут.$B$BНещодавно ми дізналися, що Палка Легіон значно активізувала виклик цих істот через портал.$B$BВи мусите закрити «Ворота Смерті», перш ніж це перетвориться на нестримну хвилю і все буде втрачено!",  -- db:10679
[768995932] = "Я прибув на цю землю, щоб очистити страждаючі душі, але після нападу боюся, що моя місія зазнала невдачі.  Так багато людей забрали пустки.  Будь ласка, ви мусите їм допомогти.",  -- db:10680
[657255100] = "Коли я вперше відкрив свою академію розбійників у Шаттраті, тут було далеко не так людно. Потім почали масово прибувати біженці, і наару знадобилися всі вільні будівлі, щоб їх розмістити.$B$BНаразі я закрив свою академію, але це не назавжди. Я знайду нове місце для неї.$B$BТоді нове покоління розбійників опанує такі основи, як «вирвана посмішка», бойове грабування та звинувачення когось іншого у порушенні ефекту «Поліморф». І хто ж може забути головне правило розбійництва — справжні розбійники не роблять фінтів.",  -- db:10686
[211733967] = "Секрет уміння ухилятися полягає в тому, щоб усвідомити: найкращі п’ятнадцять секунд у твоєму житті — це часто останні.",  -- db:10686
[641426594] = "Мечі, кігті, кинджали — звичайно, я навчав розбійників користуватися ними всіма. А от булави — я до булав не торкаюся і не буду навчати жодного розбійника, якому спаде на думку ними користуватися.$B$BУ булаві немає нічого таємного. Якщо ти обереш цей шлях, тебе чекає гучне вбивство та довге прибирання.",  -- db:10686
[587971053] = "Мої ранкові заняття завжди заповнені молодими хлопцями з блискучими очима. Однак мало хто з них проходить перший тест.$B$BI Я вже перестав кричати: «Коли я скажу „зникніть“, ви маєте зникнути». Вони ніколи не слухають. Тепер цей тест просто відсіває некомпетентних.",  -- db:10686
[311820497] = "Ніколи не виходьте з дому без достатнього запасу спалахувального порошку, особливо якщо працюєте з іншими. Гарантую, що у когось він обов’язково закінчиться.$B$BКоли доводиться обирати між тим, щоб поділитися матеріалами, чи дозволити бідолазі загинути, я допомагаю… принаймні, здебільшого.",  -- db:10686
[733498880] = "Я — Заревхі з Консорціуму. Мої вміння як трансмутатора відомі у тисячі світів.",  -- db:10687
[227309325] = "Ой, ні!  Мій Фей-Фей нізащо не взяв би чужі речі!  Він хороший песик... просто іноді йому потрібна увага.  Дайте йому ласощі — і самі побачите!",  -- db:10689
[831719666] = "Раніше я розважався, приймаючи виклики від усіх, хто їх пропонував, але мені вже давно набридли такі легкі перемоги.$B$BНаразі я присвячую час тому, щоб налагодити свій бізнес з продажу реагентів і написати книгу про свої пригоди в «Молоті Сутінків».",  -- db:10691
[94364355] = "Я не збираюся навчати тебе, доки ти не здобудеш повагу в очах драені.",  -- db:10705
[288773579] = "О, дякую!  Ця чорна безодня всередині мене зникла!  Я знову бачу... і бачу обличчя свого рятівника!",  -- db:10706
[799201800] = "Зникни, $c!  Залиш нас у спокої, інакше ми наступного разу увійдемо в тебе і покажемо тобі, що таке справжнє відчай!",  -- db:10707
[106953315] = "Тепер, коли ви перемогли мене, випробуйте свої сили один проти одного!  Оберіть одного з королів, щоб розпочати гру.",  -- db:10718
[360499533] = "Ви хочете зі мною поговорити, $r?",  -- db:10720
[565064321] = "Я бачив чимало небезпек у цих пустках. Хто знає, які ще істоти причаїлися в пилу, щоб влаштувати засідку на необережних?",  -- db:10721
[648425607] = "У вас недостатньо репутації у Альдора або ви не присягнули їм на вірність.",  -- db:10722
[786246426] = "У вас недостатньо репутації у «Скрайєрів» або ви не присягнули їм на вірність.",  -- db:10723
[843828620] = "Якщо ви хочете знайти нашого майстра-тренера паладинів, зверніться до Чемпіона Бачі. Він чекатиме на вас на Площі Далекобіжників.",  -- db:10724
[717140874] = "Силанн, одна з найкращих кухарок у місті, знаходиться нагорі в таверні «Відпочинок мандрівника». У її помічниці ви також можете придбати кулінарні приналежності.",  -- db:10725
[1391747] = "Ви маєте на увазі готель «Сільвермун Сіті» чи таверну «Притулок мандрівника»?",  -- db:10726
[397378215] = "Таверна «Відпочинок мандрівника» розташована між «Алеєю Старших» та «Базаром». Дістатися до неї можна з будь-якого з цих місць.",  -- db:10727
[625335061] = "Конфлікти в Аутленді — найкривавіші з усіх, що я коли-небудь бачив.  А найтрагічнішими їхніми жертвами є діти, які залишаються без батьків.$B$BЗараз, коли Шаттрату загрожують аракоа зі Скеттіса, сиріт, про яких потрібно піклуватися, стане ще більше.  Ці діти часто живуть без надії на світле майбутнє.$B$BАле ви маєте силу щось із цим зробити.  Зараз триває Тиждень дітей, $c, і я благаю вас стати волонтерами, щоб подарувати радість і диво в життя дитини.",  -- db:10729
[397494626] = "Мені самотньо.  Хотілося б, щоб тут було більше дітей мого віку.  Іноді я сумую за життям у дитячому будинку в місті Шаттрат.",  -- db:10730
[87131794] = "Ми вже приїхали?",  -- db:10732
[145073780] = "Якщо демони впали, то звідки вони впали?",  -- db:10732
[653342631] = "Здається, мені треба прийняти ванну.  *вдихає*  Здається, тобі теж треба!",  -- db:10732
[686302718] = "Чи можна вважати паладина-таурена «святою коровою»?",  -- db:10732
[126708637] = "У цій сукні я виглядаю товстою?",  -- db:10732
[683854477] = "Готовий побитися об заклад, що Іллідан — насправді хороший хлопець.  Йому просто теж потрібна мама.",  -- db:10732
[951635657] = "Готовий побитися об заклад, що морозиво смакувало б краще, якби воно було в розетці!",  -- db:10732
[553493404] = "У хлопчиків — «коті», а у дівчаток — краса!",  -- db:10732
[377638343] = "Я вільний!  Але таємниця... тепер у небезпеці.  Треба попередити Акаму!",  -- db:10733
[145992271] = "Чому Замежжя більше не називається Дренором?",  -- db:10734
[548407122] = "<Мортіс поглядає в небо.>$B$BPев певному сенсі я заздрю свободі, якою користуються Рук і Корвакс. Бути вільним від земних обов’язків — це справді велике благословення.$B$BMайбутнє знову побачить мене в польоті, але спершу я мушу виконати одне завдання.",  -- db:10735
[476229769] = "Арана перемогли? Так... Я відчуваю, що його хватка послабилася — хоч і зовсім трохи. Але цього достатньо, щоб я міг виконувати свої обов’язки швейцара! Чи хочете ви, щоб я переніс вас до Бібліотеки Хранителя, $N?",  -- db:10741
[910051108] = "Радий знову тебе бачити, $C $N.  Дорнаа розпитувала про тебе.",  -- db:10742
[389753276] = "Конфлікти в Замежжя є найкривавішими з усіх, що я коли-небудь бачив.  А їхніми найтрагічнішими жертвами є діти, які залишаються без батьків.$B$BЗараз, коли Шаттрату загрожує небезпека з боку аракоа зі Скеттіса, з’явиться ще більше сиріт, про яких потрібно буде піклуватися. Ці діти часто живуть без надії на світле майбутнє.",  -- db:10744
[926877615] = "<Друїд, здається, міцно заснув і нічого не помічає навколо себе.>",  -- db:10745
[80990921] = "Благаю вас, $r, поспішіть. Вони не перестають мене переслідувати! Я не можу втекти від них навіть тут!",  -- db:10746
[467575373] = "Іленія Мунфайр, майстриня зброї з народу нічних ельфів, яка мешкає на Терасі Воїнів у Дарнассусі, може навчити вас стріляти з лука.",  -- db:10748
[733378752] = "Біксі Вобблбонк у цьому самому магазині може навчити вас володінню кинджалами. Якщо ви все ще шукаєте десь за межами міста, то й інші — Ву Пін у Штормовії та Іленія Мунфайр у Дарнассі — можуть показати вам дещо. Щодо мене, то я ніколи не був прихильником ножових боїв.",  -- db:10749
[999187697] = "Іленія Мунфайр, майстер зброї з народу нічних ельфів на «Терасі воїнів» у Дарнассусі, або Булівіф, майстер зброї з народу гномів у «Тімберлайн Армс» в Айронфорзі, можуть навчити вас користуватися кулачною зброєю.",  -- db:10750
[227749615] = "Булівіф, майстер зброї-карлик із магазину «Тімберлайн Армс» в Айронфорзі, може навчити вас користуватися вогнепальною зброєю.",  -- db:10751
[46970780] = "Я перебуваю тут за дорученням принца Нексуса Харамада. У «Штормовій Вежі» відбуваються дивні події.",  -- db:10752
[957073274] = "Гномка Біксі, майстриня зброї, може навчити вас стріляти з арбалетів. Її можна знайти в магазині «Тімберлайн Армс» в Айронфорджі.",  -- db:10753
[799398780] = "Майстер зброї-гном Булівіф може навчити вас володінню як одноручними, так і дворучними сокирами. Його можна знайти в магазині «Тімберлайн Армс» в Айронфорзі.",  -- db:10754
[957283797] = "Булівіф може навчити вас правильно орудувати булавою, незалежно від її розміру. Його можна знайти в таверні «Тімберлайн Армс» в Айронфорзі.",  -- db:10755
[282293502] = "Ву Пін — майстер володіння списоподібною зброєю. Він навчає своїх учнів у «Арсеналі Веллера» в Штормовії.",  -- db:10756
[141559565] = "Навичкам володіння палицями навчають як Ву Пін, майстер, якого можна знайти в «Арсеналі Веллера» у Штормовії, так і Іленія Мунфайр, яка навчає нічних ельфів на «Терасі воїнів» у Дарнассусі.",  -- db:10757
[777115161] = "Є лише один майстер меча: Ву Пін. Його можна знайти в «Арсеналі Веллера» у Штормовії.",  -- db:10758
[297842622] = "І Іленія Мунфайр на Терасі Воїнів у Дарнассусі, і Біксі Вобблбонк із таверни «Тімберлайн Армс» в Айронфорзі можуть навчити вас правильно користуватися метальним зброєю.",  -- db:10759
[586390717] = "Іленія Мунфайр, майстриня зброї з народу нічних ельфів, яка мешкає на Терасі Воїнів у Дарнассусі, може навчити вас стріляти з лука.",  -- db:10760
[259145044] = "Ось мій відважний товариш Біксі Вобблбонк — він може навчити вас стріляти з арбалетів. Якщо ж ви шукаєте інших інструкторів, то, можливо, варто звернутися до Ву Пінга в «Арсеналі Веллера» у Штормовії.",  -- db:10761
[938113359] = "Біксі може навчити вас кидати метальні зброї. Якщо вам більше до вподоби Дарнассус, поговоріть з Іленією Мунфайр на Терасі Воїнів у цьому місті.",  -- db:10762
[224342194] = "Булівіф може навчити вас користуватися сокирами! Він десь тут, у цій крамниці.",  -- db:10763
[564495799] = "Булівіф саме в цій крамниці може навчити вас користуватися кулачною зброєю. Якщо його методи навчання вам не до душі, я чув, що майстер зброї нічних ельфів у Дарнассусі, Іленія Мунфайр, теж добре розбирається в цій зброї! Вона перебуває там, на Терасі Воїнів.",  -- db:10764
[694901512] = "Зброя — це спеціалізація Булівіфа! Він десь тут, у цьому магазині.",  -- db:10765
[259919854] = "Булави — це фірмова спеціалізація Булівіфа! Він десь тут, у крамниці, бурчить собі під ніс.",  -- db:10766
[543690723] = "Якщо ви хочете навчитися володінню зброєю, я можу вам у цьому допомогти.",  -- db:10767
[902825982] = "А, ти хочеш тренуватися за кордоном? Я тобі допоможу. Скажи, яка зброя тебе зацікавила.",  -- db:10768
[943409256] = "І Ханаші, і Сайок можуть навчити вас користуватися одноручними та дворучними сокирами. Їх можна знайти в Долині Честі в Оргримарі.",  -- db:10770
[107637149] = "Майстри зброї в Долині Честі в Оргримарі — Сайок і Ханаші — можуть навчити вас стріляти з лука.",  -- db:10771
[230650713] = "Арчібальд — майстер арбалета. Він є майстром зброї в Підмісті, що розташоване у Військовому кварталі.",  -- db:10772
[96446774] = "Навчитися володінню кинджалом можна у двох майстрів зброї: Арчібальда у Військовому кварталі Підміста та Сайока у Долині Честі в Оргримарі.",  -- db:10773
[499224225] = "Бойовим мистецтвам з використанням рукопашної зброї навчає Сайок, майстер зброї-орк з Оргримара. Він проводить свої дні в Долині Честі.",  -- db:10774
[956156683] = "Нашим інструктором зі стрільби є Ансеква — майстер зброї з племені тауренів, що мешкає на нижньому центральному пагорбі Грім-Скелі.",  -- db:10775
[565684862] = "Навичка володіння булавами викладається Ансекхвою, яку можна знайти на нижньому центральному пагорбі Грім-Скелі.",  -- db:10776
[438035283] = "Майстер зброї з племені «Покинутих» Арчібальд досконало володіє довгим копьєм. Він навчає інших у Військовому кварталі Підміста.",  -- db:10777
[506823752] = "Навичкам володіння посохом навчають Ханаші, майстер зброї-троль із Долини Честі в Оргримарі, та Ансеква, майстер зброї-таурен, який проводить тренування на нижньому центральному пагорбі Громового Уступу.",  -- db:10778
[310265153] = "Арчібальд, майстер зброї в Андерсіті, може навчити вас володінню як одноручними, так і дворучними мечами. Він перебуває у Військовому кварталі.",  -- db:10779
[94244010] = "Сайок і Ханаші, майстри зброї з Оргримара, — справжні майстри у справі метальної зброї. Вони навчають охочих учнів у Долині Честі.",  -- db:10780
[558893430] = "Арчібальд — майстер арбалета. Він — майстер зброї в Підмісті, що розташоване у Військовому кварталі.",  -- db:10781
[878047596] = "Арчібальд — майстер арбалета. Він — майстер зброї в Підмісті, що розташоване у Військовому кварталі.",  -- db:10781
[603213083] = "Сайок, цей потворний орк, навчить тебе володінню кинджалами. Якщо хочеш навчитися чомусь іншому, звернися до Арчібальда у Військовому кварталі Андерсіті, гаразд?",  -- db:10782
[99241591] = "Хочеш комусь дати по морді, так? Звернися до Сайока — він тут. Він тебе навчить.",  -- db:10783
[118516360] = "Наш інструктор зі стрільби — це Ансеква, майстер зброї тауренів, що мешкає на нижньому центральному пагорбі Громового Уступу.",  -- db:10784
[134502801] = "Булави, про які розповіла Ансеква, знайдені на нижньому центральному пагорбі Грім-Скелі.",  -- db:10785
[283128427] = "Арчібальд, майстер зброї з «Забутих», знається на довгих колючих зброях. Він навчає інших у Військовому кварталі Підміста, друже.",  -- db:10786
[751530546] = "Арчібальд, майстер зброї з Андерсіті, навчить тебе володіти як одноручними, так і дворучними мечами, друже. Він у Військовому кварталі.",  -- db:10787
[698563451] = "Ханаші тут знається на посохах. Якщо тобі потрібен більш досвідчений інструктор, вирушай до Громового Уступу. Ансеква навчить тебе на нижньому центральному пагорбі там.",  -- db:10788
[613368485] = "Якщо ти прийшов не для того, щоб тренуватися, відійди і дай мені спокійно працювати.",  -- db:10789
[800344439] = "Не розумію, навіщо тобі вивчати ще щось... але, мабуть, можу підказати тобі правильний напрямок. А яке саме навчання тебе цікавить?",  -- db:10790
[960441023] = "Будьте обережні з «Ефіріумом», який оточує нас з усіх боків.",  -- db:10791
[364559863] = "Приходьте, і я покажу вам, як їздити на найкращих тваринах, яких ви коли-небудь бачили. Ви... мабуть, маєте достатньо золота, щоб покрити витрати, сподіваюся?",  -- db:10792
[537412713] = "Ласкаво просимо до «Евергроув», $c. Таймон і я вже деякий час вивчаємо аракоа з «Кромки Клинка» і виявили кілька тривожних відмінностей між ними та їхніми родичами з Тероккара.",  -- db:10793
[638938894] = "Справжні віруючі живуть у ганьбі з того дня, як наші зрадливі родичі зі Скеттіса викрали у нас книгу, розбили її скрижаль і поховали уламки у своєму жалюгідному місті!$B$BМолись, щоб ворон обрав саме тебе для її відновлення, сину мій. Будь вірним і завжди пам’ятай пророцтво: «Зі снів своїх ворогів ворон вилетить у світ».",  -- db:10796
[145303211] = "Ти ходив до Мог'дорга?",  -- db:10798
[489079703] = "Я шукаю $g героя : героїню; найвищої майстерності.  $G Він : Вона; об’єднає інших, щоб врятувати клан Бладмаул та всіх огрів цих гір від тиранії наших гроннських гнобителів.$B$BПовертайся до мене, коли навчишся всьому, чому зможеш.  Але, $c, до того часу зберігай це в таємниці, щоб гронни не дізналися про наш підпільний рух.",  -- db:10799
[731596006] = "Щоб скинути кайдани й знову жити як вільні огри, ми мусимо перемогти Синів Груула!$B$BЩоб наш підпільний опір мав шанс на успіх, ми маємо діяти тихо, але швидко.",  -- db:10800
[89727803] = "Боюся, що полковника Жюля можна врятувати лише за допомогою небезпечного ритуалу... екзорцизму.",  -- db:10801
[536771832] = "Чи не обманюють мене очі? Це справді ти, брате Роккарам, після стількох років?$B$BЯкщо ти шукаєш Сай'ккала, він ходить серед кристалів у західній частині Вершини Вихору. Він, здається, заклопотаний тим, що називає там «брутальною, примітивною присутністю», хоча, здається, нічого незвичайного не відбувається.",  -- db:10807
[516747698] = "Можливо, ти дещо знаєш про поводження з тваринами, але чи піднімався ти коли-небудь у небо? Ми, Вайлдхаммери, вміємо літати на вітрі не гірше за інших. За невелику плату, якщо в тебе вистачить сміливості, я навчу тебе як слід.",  -- db:10808
[883798836] = "Схоже, ти знаєшся на звірах, що бігають по суші, але якщо хочеш злетіти, тобі знадобляться тренування та наполегливість. І золото. У тебе ж є золото, правда?",  -- db:10817
[335224873] = "Чудові тварини, чи не так? Виверни, яких ми тут вирощуємо, привчені витримувати найсуворіші та найдивніші погодні умови, які тільки може запропонувати Дренор. Ви переконаєтеся, що вони надійні та витривалі.",  -- db:10818
[368782252] = "Коли я виросту, я хочу стати шкіряником!",  -- db:10821
[666462961] = "Щодо цієї... особи надійшло кілька скарг. Мені сказали, що він, так би мовити, сумнівна особистість. Я тут для того, щоб з’ясувати, чи є його бізнес законним... і вжити заходів, якщо виявиться, що це не так.",  -- db:10830
[599795265] = "Якщо вам вдасться зібрати повну колоду карт «Бурі», ви отримаєте в нагороду «Велику темномісячну карту Гніву».   Це збільшить ваші шанси нанесення критичного удару заклинаннями або фізичними атаками, доки ви не завдасте такого удару.",  -- db:10831
[221701073] = "Якщо вам вдасться зібрати колоду карт «Божевілля», ви отримаєте в нагороду «Велику темномісячну карту божевілля».   Сила божевілля наповнюватиме вас щоразу, коли ви вбиватимете ворога.",  -- db:10832
[70241516] = "Якщо вам вдасться зібрати повну колоду карт «Благословення», ви отримаєте в нагороду «Велику темномісячну карту хрестового походу».   Це збільшить шкоду, яку ви завдаєте своїми заклинаннями та атаками, у міру продовження бою.",  -- db:10833
[787429137] = "Якщо вам вдасться зібрати повну колоду карт «Фурій», ви отримаєте в нагороду «Велику темномісячну карту помсти».   Під час використання цієї карти кожен, хто вас атакує, ризикує зазнати святої помсти.",  -- db:10834
[842319571] = "Будьте обережні, друзі. Зрадник медитує у залі, що знаходиться трохи далі.",  -- db:10835
[68893896] = "Тсс! Говори тихіше. Дівчата сплять.",  -- db:10837
[510418975] = "Тобі краще швидко прокинутися, новачку. Це не наш затишний задній двір за межами Скеттіса — це гори «Лезо Клинка»! Один неправильний рух — і все, кінець!",  -- db:10841
[604981144] = "Не роби це своїм домом. Може, хочеш щось поїсти?",  -- db:10848
[534646054] = "О, так! Хочеш спробувати ці зброї на смак, черв’ячку? Тоді заходь!",  -- db:10850
[905837449] = "Як ти збираєшся змагатися з цими пітонами? Ооооо, так, брате!",  -- db:10850
[616815910] = "Ти це чуєш? Чуєш ці вигуки, брате? Вони вболівають за Рулкстера!",  -- db:10850
[74530083] = "Що ти будеш робити, коли «Рулк-а-манія» накинеться на тебе, брате????!",  -- db:10850
[893046542] = "$G Брате:Сестро;, відтепер ти вважаєшся кровним родичем Нетервінгів. Увесь Нетервінг тепер буде підтримувати тебе! Настав час завдати удару по самому серцю наших ворогів, друже! Ми мусимо повернути собі нашу втрачену спадщину.",  -- db:10854
[382466462] = "Ти багато зробив для нашої справи, $N, але не зможеш просунутися далі, доки не опануєш мистецтво польоту. Лише найвідважніші вершники здатні допомагати «Нетервінг».",  -- db:10855
[704132553] = "Ви, мабуть, дивувалися, як це так, що я, як для огра, можу говорити так чітко. Це побічний ефект кристалів, що ростуть на терасі, яка оточує Огрі’лу.  Огри, що мешкають там, подарували мені цей посох, а кристал у ньому, у свою чергу, наділив мене розумовими здібностями.$B$BСаме завдяки вашим постійним діям у Огрі'лі, що нагорі, я сподіваюся, що одного дня зможу принести це благо всім моїм братам-ограм.  Я дякую вам, мій $g королю : королево;, за все, що ви зробили й ще зробите.",  -- db:10860
[984628438] = "Ще один, так? Ти ніколи не впораєшся...",  -- db:10862
[226796023] = "Просто пам’ятайте, що щодня можна вибрати лише одне завдання зі збору ресурсів. Крім того, ми завжди шукаємо нові кристали. Будь-який нікчемний робітник може принести їх до базового табору.",  -- db:10863
[279728639] = "У мене для тебе нічого нового немає, хлопче. Ти вже виріс із фізичної праці...",  -- db:10864
[21518183] = "«Вплив Іллідана на моє плем'я дуже сильний, $N. Скоро все це закінчиться, так чи інакше.$B$BТи готовий, $N?  Майбутнє мого народу залежить від нас.",  -- db:10866
[196057423] = "У UDB відсутній текст про США",  -- db:10872
[514999168] = "Не розголошуй того, що тут чуєш і бачиш, $r.",  -- db:10877
[1177082] = "Грок, чув, що ти — новий $g король : королева; усіх огрів. Вітаю... вітаю... вітаю, маленький $r.",  -- db:10879
[314050028] = "Чим можу вам допомогти, $c?",  -- db:10887
[101634982] = "Купа черепів тхне огидою. Ти побоюєшся, що аракоа нещодавно поповнили цю купу.",  -- db:10888
[39225654] = "Якщо ви шукаєте гаджети, дрібнички, штучки, пристосування, штуки, прилади чи пристрої, то ви потрапили саме туди, куди треба!",  -- db:10889
[358697075] = "Ти здаєшся мені знайомим...",  -- db:10892
[598583273] = "Перед моїми очима промайнули образи подій, що відбуваються по всьому світу, та тих, що ще можуть статися. Багато з них є похмурими, але нам не слід вважати, що їх неможливо змінити.",  -- db:10893
[588600821] = "Стій струнко, солдат!",  -- db:10901
[603851379] = "Хай на тебе тисяча проклять, $r! Ця в’язниця не втримає мене довго!",  -- db:10903
[572776112] = "Забирайся звідси, поки я тебе не побив своїм бутерангом.",  -- db:10904
[195712072] = "О, тобі тепер подобається моя пов'язка на око, так? Ну, просто подбай про те, щоб тобі самому не довелося її носити, $g, хлопче : дівчинко;.",  -- db:10906
[895824967] = "Що?  Як це?  Я тут трохи зайнятий, друже!$B$BЗвісно, якщо ти прийшов допомогти, у мене є скільки завгодно часу.",  -- db:10907
[603300915] = "За допомогою кристальної кузні Фел ви можете перетворити свої осколки Апексіса на нестабільні флакони звіра. Ці флакони роблять того, хто їх вип’є, спритнішим, сильнішим і витривалішим.$B$BЗробіть свій вибір нижче.",  -- db:10910
[897048474] = "<Коли ви кладете осколки Апексиса в кристальну кузню Фелу і тягнете за важіль, пристрій видає неземний звук, подрібнюючи їх на пил.  Через кілька миттєвостей ваша колба вискакує з його «рота».>",  -- db:10911
[925536525] = "<Коли ви кладете осколки Апексиса в кристальну кузню Фелу і тягнете за важіль, пристрій видає неземний звук, подрібнюючи їх на пил.  Через кілька миттєвостей з його «рота» вискакують ваші флакони.>",  -- db:10912
[787721348] = "У кристальній кузні Башира ви можете перетворити свої осколки Апексісу на нестабільні флакони чаклуна. Ці флакони роблять того, хто їх вип’є, розумнішим і витривалішим, а також підвищують ефективність його магії, що завдає шкоди та лікує.$B$BЗробіть свій вибір нижче.",  -- db:10913
[584405374] = "<Коли ви кладете осколки Апексиса в порожнину кристальної кузні Башира і тягнете за важіль, пристрій буквально розкладає їх на атоми.  Через кілька миттєвостей ваша колба з’являється у вас під ногами.>",  -- db:10914
[976179356] = "Ми сподіваємося, що ви зможете позбавити нас від головного болю.  Спробуйте самі мати десять синів, і всі вони хочуть займатися тим, до чого не мають хисту!$B$BПроте, як батько, ми робимо те, що мусимо.",  -- db:10916
[26298064] = "У тебе є сини, $c?$B$BДавай тобі щось скажемо: нам здається, що ми були набагато щасливішими до того, як потрапили в Огрі'лу, а кристали зробили нас більш свідомими. Раніше ми б просто вдарили їх по голові, щоб вони замовкли.  А тепер вони тільки й роблять, що дошкуляють нас з приводу Небесної гвардії Ша'тарі.$B$BНезнання — це щастя!",  -- db:10917
[312693626] = "Як відносно новий мешканець Огрі'ли, ти ще недостатньо знайомий з місцевими кристалами, щоб повною мірою скористатися їхніми перевагами.  До того ж у тебе лише одна голова.$B$BМи ж, навпаки, живемо тут вже дуже давно.  Тож, як ви можете собі уявити, ми досить добре розбираємося в багатьох речах.$B$BOстаннім часом ми зацікавилися демонами з таборів кузень.  А точніше, ми придумали спосіб назавжди позбутися їх.$B$BПринаймні, так виглядає теорія.",  -- db:10919
[595062825] = "Ми б хотіли створювати більше ніж одну темну руну на день, але це було б марною тратою часу. Це просто фізично неможливо.  До того ж, ми навіть не можемо надійно створювати їх з такою швидкістю.$B$BІ повірте нам: якби тут був хтось інший, достатньо розумний, щоб допомогти, його б залучили до роботи, і ми мали б стільки темних рун, скільки потрібно.",  -- db:10920
[29483883] = "У кристальній кузні Башира ви можете перетворити свої осколки Апексіса на нестабільні флакони чаклуна.  Ці флакони роблять того, хто їх вип'є, розумнішим, витривалішим, а також підвищують ефективність його магії, що завдає шкоди та лікує.$B$BОднак, схоже, у вас немає необхідних десяти осколків, щоб придбати хоча б один флакон.",  -- db:10921
[539646797] = "За допомогою кристальної кузні Фел ви можете перетворити свої осколки Апексіса на нестабільні флакони звіра. Ці флакони роблять того, хто їх вип’є, спритнішим, сильнішим і витривалішим.$B$BОднак, судячи з усього, у вас немає десяти осколків, необхідних для придбання навіть одного флакона.",  -- db:10922
[348760221] = "Гахк — новачок в Огрі'лі, як маленький $r. Тут — справжній рай, про який завжди розповідають інші огри, що живуть внизу.  Але у Гака болять голови від кристалів, які роблять його розумнішим.$B$B<Обидві голови Гака кивають одна одній.>$B$BМи вчимося виготовляти кристально-ковані темні руни.  Коли ми це навчимося, ми розтрощимо демонічні портали!",  -- db:10923
[54177009] = "Гах тепер розумний! Ми знаємо, як перетворити темну руну на кристально-викувану темну руну!",  -- db:10924
[871997520] = "$N розбив портал, це добре, але демони знову його зміцнили.$B$B$N приніс Гаку ще одну темну руну, і Гак виготовив для $N спеціальну темну руну, викувану з кристалів!",  -- db:10925
[769421811] = "Ласкаво просимо до Огріли, $c.$B$BМісцеві огри зуміли набути надзвичайної гостроти розуму завдяки магічним випромінюванням навколишніх кристалів.  Хоча ми й не до кінця розуміємо, як це працює, ми полюбили наш новий дім і прагнемо лише жити в мирі.$B$BНа жаль, демони та ефірні істоти, а особливо Чорний Драконячий Політ, не дають нам спокою.",  -- db:10926
[107951477] = "Від імені всього Огрі'ла ми дякуємо тобі за твої зусилля, $N.$B$B<Ліва голова Чу'а'лора киває, а права — посміхається тобі.>$B$BІ не забувайте, що, допомагаючи нам тут, ви також допомагаєте захищати наших братів і сестер внизу, для яких ви стали ніби $g королем : королевою;.",  -- db:10927
[771303173] = "Ні, не варто. Ти ще не достатньо сильний, щоб брати участь у рейтингових поєдинках. Проте ти можеш знайти «Майстра боїв на Арені» і провести кілька тренувальних раундів. Ніколи не рано починати тренуватися.",  -- db:10929
[491558104] = "Ти прийшов, щоб завдати мені болю? Я не маю ніякого стосунку до війни, $r.$B$BI я лише кволий вчений, будь ласка, залиш мене в спокої!",  -- db:10930
[169401866] = "Яйце виглядає міцним, як і має бути у яйця Чорного Драконячого Польоту. Можливо, якби ви поклали поруч із ним велику кількість осколків Апексісу, їхні вібрації змусили б його тріснути?$B$BШкода, що у вас, схоже, немає тих тридцяти п’яти осколків Апексісу, які потрібні для цього.",  -- db:10932
[236972670] = "<Анжела знову ласкаво промовляє до фелхантера, а потім звертає увагу на тебе.>$B$BДжирсі завжди був меншим за всіх інших фелхантерів, але це його ніколи не турбувало. А Замежжя все це змінить, правда, Джирсі?$B$BMамин маленький ангелик виросте великим і грізним фелхантером, так, саме так!",  -- db:10934
[53015276] = "Тут ти знайдеш чимало цікавих занять, $N.",  -- db:10937
[73236771] = "Ой, ти ж не дарма не сидів склавши руки, правда?!  Не знаю, як тобі віддячити за те, що ти розніс тих демонів і поповнив наші запаси верхових тварин.$B$Ти значно полегшив нам роботу.  Так тримай, $g хлопче : дівчино;!",  -- db:10938
[206377923] = "Ми повинні знову встановити повний контроль над цими шахтами!",  -- db:10939
[222635324] = "Я мушу негайно покинути це місце!",  -- db:10947
[610424866] = "Реліквія Апексіс мерехтить, виказуючи прихований у ній розум.",  -- db:10948
[245562800] = "Пам'ятник Апексісу височіє над вами.",  -- db:10949
[369268857] = "Встаньте струнко, капітане!",  -- db:10950
[965038151] = "Очі, що палають усередині призми, наповнюють твій розум відчуттям жаху... особливо з огляду на те, що у тебе немає тридцяти п’яти осколків Апексіса, необхідних для виклику його демона.",  -- db:10951
[460822355] = "Ти ж ще молодий пташеня, чи не так?  Очі мене підводять.$B$BI Припускаю, ти прийшов, щоб придбати одну з моїх екзотичних книг?",  -- db:10953
[211133122] = "Забудь про товар Вікстона. Хочеш щось по-справжньому класне? Тоді звертайся до Крікселя. У мене є саме те, що тобі потрібно — за умови, що ти маєш відповідну репутацію. Ну, знаєш, на арені. Це не для слабаків, хлопче.",  -- db:10957
[427618295] = "Наразі ми проводимо фокус-тестування «Битви за гору Гіжал». Щоб взяти участь, вам потрібно мати репутацію «Почесний» у фракції «Фіолетове Око».$B$BЦю репутацію можна заробити під час проходження Каразана.",  -- db:10961
[775991322] = "Тепер, коли ти налаштувався на гору Гіжал, я можу телепортувати тебе до Печер Часу. Просто дай мені знати, коли будеш готовий.",  -- db:10962
[803661577] = "Тепер, коли у вас є ключ до Чорного храму (Медальйон Карабора), я можу телепортувати вас прямо до Чорного храму. Просто скажіть, коли будете готові.",  -- db:10964
[646555601] = "Ласкаво просимо, друже! Що б ти хотів подивитися?",  -- db:10965
[32279495] = "Вітаємо, $G брате:сестро;. Чим ми можемо допомогти?",  -- db:10966
[737382753] = "Чим ми можемо вам допомогти?",  -- db:10967
[87693840] = "Наша їжа має вгамувати навіть найсильніший голод.",  -- db:10973
[92013279] = "Все ще голодний, $G, брате/сестро? Чим можемо допомогти?",  -- db:10974
[88245908] = "Друже, ми підготували для тебе справжнє свято.",  -- db:10975
[697059643] = "Які смачні ласощі ми можемо вам запропонувати?",  -- db:10976
[586676173] = "Доброго дня.  Коли ви трохи підніметеся по службових сходах у лавах «Небесної гвардії Ша’тарі», я зможу запропонувати вам прямий переліт до «Аванпосту Небесної гвардії» — нашої бази на вершинах гір «Лезо Краю».",  -- db:10980
[471420068] = "Хіба тобі, $g хлопче : дівчино, немає чого кращого робити, ніж базікати зі мною?$B$BА тепер іди туди й доведи, на що ти здатний!",  -- db:10988
[658819763] = "Оце так, $g хлопче : дівчино!  Ми всі пишаємося тим, як ти працюєш!$B$BІ знаєш, якщо захочеш швидко заскочити на нашу іншу базу в горах Скетіл, підійди й поговори з координаторкою «Небесної варти» Іреною.  Вона все для тебе організує.",  -- db:10989
[378464175] = "Бачу, ти вже не мало часу тут провів, $c.$B$BПроведи ще більше — демони ще не зникли, новачку.",  -- db:10992
[948872589] = "Здається, твоє ім'я на вустах у всіх на цьому форпості. Не дай цьому закрутити тобі голову — я знаю, що ти можеш краще!$B$BЯ стежитиму за тобою, новачку.",  -- db:10994
[588647962] = "Гаразд, визнаю, ти довів свою спроможність і навіть більше, $N.$B$BЯкщо я раніше був суворий до тебе, то лише тому, що побачив у тобі іскру справжнього «Небесного стража».  Смію сказати, що ти — найкращий ас у нашій команді!$B$BКоли завгодно, якщо захочеш допомогти, я з великою гордістю вручу тобі ще одну партію бомб.",  -- db:10995
[607570120] = "Привіт, $c!$B$B<Хаті хитро поглядає на тебе.>$B$BЯкщо захочеш ще раз роздобути для нас трохи ефірних променів, обов’язково зазирни до мене!",  -- db:10997
[972209924] = "Знаєш, $N, для мене велика честь працювати з тобою!$B$BКоли ти не будеш зайнята боротьбою, може, ми могли б $g сходити кудись повечеряти? : влаштувати дівочий вечір?;$B$BO, а я вже згадувала, що тепер ми можемо дуже швидко доправити тебе до нашої бази в горах Скетіл?  Якщо хочеш, поговори про це з координаторкою «Небесної варти» Іреною.",  -- db:11001
[594236049] = "Отже, ти багато де буваєш, але нам ніяк не вдається зустрітися після роботи.$B$BЦе через мене?$B$B<Хаті навмисно намагається підняти настрій.>$B$Б у будь-якому разі, я просто хотіла сказати, що я... ми дуже цінуємо все, що ти робиш для «Скайгард»!",  -- db:11002
[828622215] = "Сподіваюся, ти не вважаєш мене сталкером чи чимось подібним, $N.$B$BЯ маю на увазі, я знаю, що ти зараз дуже відомий у «Скайгарді», і, ну... Я впевнений, що ти не захочеш проводити час із таким нікчемним нікчемою, як я.$B$BАле якщо ти коли-небудь захочеш зустрітися, просто щоб поспілкуватися, або навіть пополювати на промені, зазирни в будь-який час!  Я буду тут.$B$BЯ сумую за тобою...",  -- db:11004
[634199637] = "Ці реліквії — справді велика таємниця. Можливо, регулярно вивчаючи їх, ви зможете краще оцінити їхні можливості.",  -- db:11007
[511637032] = "Сталь не є міцною, величний, — плоть міцніша за неї. Сталь черпає свою силу від того, хто нею володіє. Але досить про це... Чим ми можемо тобі допомогти, величний?",  -- db:11008
[171685234] = "<Ліва голова Чу'а'лора каже:>$B$BНам дуже імпонує твоя готовність допомогти нам...$B$B<Його права голова підсумовує:>$B$B... і ми хочемо, щоб ти знав: ми дуже цінуємо твої зусилля!",  -- db:11009
[68374257] = "Твоє ім'я тут починають шанувати.$B$B<Лівий око Чу'а'лора пронизує тебе своїм кам'яним поглядом.>$B$BПродовжуй у тому ж дусі, $N!",  -- db:11010
[728209981] = "Тут, в Огрі'лі, у нас є час, щоб замислитися над загадкою сталі. Але досить про це — чим ми можемо допомогти?",  -- db:11016
[283237694] = "У вас є сталь, яку потрібно обробити?",  -- db:11017
[690316222] = "Ми не можемо висловити вам достатню вдячність за все, що ви зробили, аби захистити нашу родину, $N.$B$BІ ви ж розумієте, що ми раніше жартували, коли пропонували продати вам одного з наших синів?  Ні, серйозно... хоча ми відчуваємо, що на нас чекає ще кілька головних болів.$B$BДжуніоре, сиди спокійно, добре?!",  -- db:11018
[605246135] = "Нам починає подобатися маленький $N! Ти просто чудово розправляєшся з демонами!",  -- db:11019
[56996027] = "Привіт, друже! Чим ми можемо тобі допомогти?",  -- db:11025
[585397556] = "Ми завжди готові допомогти.",  -- db:11026
[369389] = "Тобі подобається у нас в Огрі'лі?$B$BУ нас є безліч речей, які наші огри виготовляють день і ніч.  Найкраще ми залишаємо, щоб продати нашим найкрутішим гостям, таким як ти!$B$BТож, коли ти будеш там займатися своїми справами й робити гори безпечнішими, заглядай до нас час від часу, щоб подивитися, що у нас є.$B$BУдачі тобі там, $g друже : chicky;.",  -- db:11029
[605953795] = "<Верховний володар Мор’гор віддає честь.>",  -- db:11032
[446867222] = "Гей, пам’ятайте, $N, ми надамо вам можливість придбати ці речі, коли ви робитимете добрі справи. Це щось на зразок карми чи чогось такого.$B$BТож допомагайте, де тільки можете, зокрема нашим друзям зі «Скайгард», що знаходяться трохи північніше.$B$BСупер... дякую!",  -- db:11035
[357412713] = "Чуа'лор дуже добре відгукується про тебе, $N.  Якщо хочеш, у нас є кілька сортів спеціального пива «Огр», які ми продаємо.$B$BВони справді дуже смачні!",  -- db:11036
[911285149] = "Що тут скажеш, $N?  $G Чувак : Чувачка;, все, що є в магазині, ти можеш купити!$B$BТочно!",  -- db:11038
[949130217] = "Які секрети професії я можу допомогти вам розкрити сьогодні?",  -- db:11045
[402948965] = "Ну ж бо, ну ж бо. Якщо ти хоч раз як слід підготував шкіру, я покажу тобі, як виготовити практичні речі.",  -- db:11049
[894789779] = "Я чув розповіді про справді вправного коваля з-за моря на ім’я Сару Стілф’юрі. Якщо ти хочеш займатися своїм ремеслом, тобі слід вирушити до кузні в Оргримарі, $c. Бажаю успіху.",  -- db:11051
[383317482] = "Ну ж бо, $r. Яка формула вас сьогодні цікавить?",  -- db:11055
[914686523] = "Ми розпочинаємо штурм Башир-Лендінга, щоб дослідити їхню «Кристальну кузню». Допоможіть нам, якщо зможете! Наш ефірний корабель «Скайгард» вирушить приблизно через $4581d.",  -- db:11056
[314113561] = "Від цієї купи черепів виходить жахлива, темна енергія.",  -- db:11058
[748021662] = "Потрібні матеріали для роботи в польових умовах?",  -- db:11059
[773476099] = "Потрібно замовити якісь матеріали?",  -- db:11061
[106894714] = "Вітаємо, мандрівнику.",  -- db:11064
[311712595] = "Наш фахівець з «Ефір-тех» та його супровід прямують до Башир-Лендінг. Зустріньте їх там і допоможіть у виконанні їхньої місії!",  -- db:11065
[840141364] = "Наша ефір-тех «Скайгард» разом зі своїм ескортом досліджує кристальну кузню Башира. Їй потрібна допомога! Відправляйтеся до Башир-Лендінг, знайдіть ефір-тех і захистіть її!",  -- db:11066
[792268737] = "Не варто легковажно ставитися до втрати навички «Майстерність еліксирів».$B$B$B$BВи абсолютно впевнені?",  -- db:11075
[183391874] = "Відмовитися від навички «Майстерність трансмутації» — це не те, до чого слід ставитися легковажно.$B$BВи абсолютно впевнені?",  -- db:11076
[455024050] = "Усі заступники Іллідана загинули, $N.  Шлях уперед відкритий, якщо ти готовий.",  -- db:11077
[821524712] = "Я відчуваю, що ти розчистив шлях до моїх братів. Мій зв’язок із ними та з храмом досі залишається міцним. Чи бажаєш ти заглибитися всередину?",  -- db:11081
[379235409] = "Нещодавно тут були мої брати.  Мої стосунки з ними стали не такими тісними.  У дворі стоїть могутня постать, яка охороняє шлях вперед.",  -- db:11082
[51372628] = "Ласкаво просимо, $N. Принеси мені знаки, якими Іллідан нагороджує своїх наймогутніших поплічників, і я надам тобі доступ до своїх алхімічних товарів.",  -- db:11085
[818595452] = "«Дрейкс» — це мій бізнес, $N. Я уповноважений продавати їх нашим найвищим офіцерам.",  -- db:11090
[118649366] = "Що тобі потрібно, $c?",  -- db:11091
[704639299] = "Давай звідси забиратися!",  -- db:11093
[441532816] = "Кристалічні фокуси?  Звісно, ми пояснимо це, оскільки у тебе лише половина розумових здібностей, щоб розібратися в цьому самостійно.$B$BA Виснажений кристалічний фокус можна поєднати з десятьма осколками Апексісу за допомогою простої процедури, в результаті чого утворюється заряджений кристалічний фокус.  Ці заряджені фокуси мають певні цілющі властивості, але важливішим є їхнє використання разом із одержимим демоном.$B$BБачите, заряджений фокус можна використовувати, щоб одержимий демон міг проявити особливі здібності.  Через деякий час Гахк доручить вам завдання, пов’язане саме з цим.",  -- db:11094
[753817773] = "Я погоджуся на вашу допомогу в проведенні цієї перевірки, $c. Не вважайте, що я довірятиму вашим висновкам чи мотивам без власної перевірки.",  -- db:11128
[324694735] = "Розум неживого Безголового Вершника охоплений одержимістю! Під час «Хеллоу-Енду» його напади на це село стають все частішими й жахливішими.",  -- db:11143
[242182012] = "Безголовий вершник нападає на село!  Хтось повинен врятувати дітей і зупинити його!",  -- db:11145
[690663102] = "Поки що ми позбулися загрози Безголового вершника. Ми можемо знову зітхнути з полегшенням, але доки його не буде переможено, коли він знову з’єднається зі своєю головою, він може повернутися.",  -- db:11147
[605971136] = "Чесно кажучи, я не знаю, де зараз знаходиться цепелін...",  -- db:11163
[17528748] = "Цепелін мав би щойно прибути до Оргримара.",  -- db:11165
[499449806] = "Цепелін мав щойно прибути до Гром'гола...",  -- db:11167
[802809905] = "Цепелін мав щойно прибути до Оргримара...",  -- db:11169
[563110524] = "Цепелін, мабуть, щойно вилетів з Оргримара...",  -- db:11170
[104620791] = "Цепелін мав щойно вилетіти з Гром'гола...",  -- db:11172
[673757940] = "Цепелін мав щойно прибути до Андерсіті.",  -- db:11173
[178525609] = "Цепелін, мабуть, щойно вилетів з Оргримара.",  -- db:11174
[519190222] = "Цепелін, мабуть, щойно вилетів з Андерсіті.",  -- db:11175
[320983460] = "Безголовий вершник нападає!  Пожежі загрожують знищити все село!  Що нам робити?",  -- db:11177
[971796280] = "Цепелін мав щойно прилетіти до Гром'гола.",  -- db:11180
[589267446] = "Цепелін, мабуть, щойно вилетів із Гром'гола.",  -- db:11181
[815364170] = "Цепелін, мабуть, щойно вилетів з Андерсіті.",  -- db:11182
[453828027] = "Я цілий день витрачаю на пошуки запчастин для цепеліна, а Фреза навіть не має совісті платити мені погодинну зарплату. Але ти ж не через це прийшов, правда? Готовий побитися об заклад, що ти хочеш дізнатися, де знаходиться цепелін. Що ж, тобі пощастило — у мене тут є пристрій для відстеження цепеліна!",  -- db:11189
[118943444] = "Торговця на ім’я Гріфтах було вигнано з цього міста за шахрайство. Ми плануємо дуже ретельно перевірити ці дрібнички, які він продає. Будь ласка, не чіпайте його прилавок і дайте нам виконати нашу роботу.",  -- db:11196
[299994363] = "В Азероті ви не знайдете кращого пива.",  -- db:11209
[360520739] = "Ми, «Thunderbrews», пишаємося тим, що є найкращим пивоварним заводом у всіх королівствах.",  -- db:11210
[70383705] = "Ого! Ви справді хочете купити у нас?",  -- db:11211
[268394212] = "Хіба ти не бачиш, що мені треба кудись йти й з кимось зустрітися! Відійди вбік, селянине!",  -- db:11215
[356735567] = "Можу лише припустити, що ви знаєте, хто я. І все ж ви наполягаєте на тому, щоб мене турбувати?$b$bЩо ж вам може бути потрібно, що вимагає моєї уваги?",  -- db:11217
[895915021] = "Так, ну, послухай-но, $c. Я старший, ніж здаюся, і мудріший за свої роки. Тобі краще не ставити під сумнів мої слова.$B$BПослухай, тобі не обов’язково вірити мені на слово. Прочитай сам дописи на будь-якій місцевій дошці оголошень. Я всюди!$b$bПросто зроби собі послугу й ігноруй ті, у заголовку яких є слово «РОЗШУКУЄТЬСЯ». Це прості непорозуміння, запевняю тебе.",  -- db:11221
[21369447] = "Що замовиш, сонечко?",  -- db:11230
[271695855] = "О, я — кухарка?  Мабуть, це правда.  Барменці доводиться час від часу працювати на кухні, і за ці роки я вивчила кілька рецептів.  Нічого надто особливого, але страви досить ситні, щоб наповнити солідний живіт Грока.",  -- db:11231
[56268076] = "Вибач, $N, але ти вже дізнався все, що я знаю про кулінарію. Звісно, ніколи не знаєш, коли наші кухарі придумають щось нове, тож не соромся і обов’язково завітай до нас ще коли-небудь.",  -- db:11233
[18626181] = "Мій брат Крікс вважає, що йому доводиться нелегко на роботі в Оргримарі. Але ніщо не зрівняється зі смородом цього місця. Принаймні начальник мав стільки совісті, що виплатив мені надбавку за шкідливі умови праці!$B$BЩо? Хочеш подивитися, де знаходиться цепелін? Добре, що у мене тут є прилад для відстеження цепелінів!",  -- db:11234
[343754107] = "Будьте насторожі. Ми — перша лінія оборони Терамора проти численних ворогів у болотах.",  -- db:11243
[14480425] = "Тепер, коли дезертири захопили Лост-Пойнт, вежа Норт-Пойнт стала найвіддаленішим з форпостів Терамора.",  -- db:11245
[975265846] = "Що такий хлопець, як я, може зробити для такого $r, як ти, у такий час?$B",  -- db:11256
[595976466] = "Можу щось для тебе зробити, $c?$B",  -- db:11256
[105672399] = "Якщо ти тут, щоб отримати свою частину великого виграшу, то краще ставай у чергу!$b$bМоя частка вже давно запізнюється....$B",  -- db:11256
[694642108] = "Не маю поняття, хлопче. Я тут ще новачок.$b$bНасолодився я вбивством тролів і питтям грогу, це тобі можу сказати. Залишилося тільки побачити той скарб, який Бадд постійно обіцяє....$B",  -- db:11257
[346374535] = "Ти маєш на увазі команду Бадда? Так, він нікого не розрізняє. Він візьме на роботу будь-кого, хто вміє поводитися з лопатою.$b$bЗа винятком нежиті. Бадд їх ненавидить. Швидше за все, боїться їх.$B",  -- db:11258
[853099202] = "Так, ніколи не знаєш, хто приєднається наступним, або, якщо на те пішло, хто помре наступним.$b$bМоя порада? Не прив’язуйся до когось надто сильно.",  -- db:11258
[25287318] = "Погоджуюся. Бадд назбирав всяку шпану з усіх куточків світу.$b$bСхоже, коли є безкоштовний алкоголь, знайдеться чимало людей, готових відкласти свої суперечки вбік.",  -- db:11258
[925970167] = "<вдихає повітря і кривиться>$b$bОсь це й є запах пригод, $c!",  -- db:11259
[686669649] = "<гік>Послухай-но, $r. Провди день-два, борючись із дикими тролями, а потім скажи мені, як ти пахнеш!",  -- db:11259
[110011448] = "О, це. Розумієш, останнім часом у таборі не було нічого, крім орківського грогу.$b$bОрківський грог, здається, мені не підходить, якщо ти розумієш, про що я...",  -- db:11259
[416171308] = "Ласкаво просимо до Сентрі-Пойнт, $c.",  -- db:11264
[55765853] = "Слухай, друже!$b$bЯ розповім тобі все, що знаю, але спочатку ти маєш врятувати мене від цих дикунів та їхніх кровожерливих ведмедів.$b$bДомовилися?",  -- db:11279
[431422733] = "Я ще ніколи не стикався з таким холодом, $r. Навіть без льоду та снігу замерзлі пустки Нортренда випробовують на міцність.",  -- db:11285
[792574590] = "Скажи, ти мені здаєшся знайомим. Ми вже зустрічалися?",  -- db:11287
[134370928] = "Я вас знаю?",  -- db:11287
[984192065] = "Дозволь дати тобі пораду: ніколи не довіряй гномам.",  -- db:11287
[257625506] = "<Бадд закочує очі, побачивши, як ти наближаєшся>$b$bАх, так, майбутній знаменитості $n!$b$bЧим я заслужив честь вашої компанії?",  -- db:11299
[895582399] = "Ну-ну, $n, просто розслабся і зроби глибокий вдих. Тобі справді треба навчитися довіряти мені.$b$bТвій брак досвіду в таких ситуаціях змушує тебе панікувати, а паніка завжди перебільшує реальність. Отже, як бачиш, ніякої кризи насправді немає.$b$bТепер, коли ми це з’ясували, я мушу попросити тебе перестати бути таким негативним. Це погано впливає на бойовий дух екіпажу....",  -- db:11302
[430863499] = "Якби ж у нас тут був священик або друїд. Я не можу продовжувати навчання, поки не одужаю від травм.",  -- db:11311
[532217845] = "Зачекай, тільки не кажи... $n, так?$b$bЧим можу допомогти?$B",  -- db:11313
[964996012] = "Привіт! Нас блокують ті нікчемні пірати в затоці! Як думаєш, зможеш нам допомогти — скинути на них кілька бомб?!$B$BНаш викрадений цепелін уже тут; заскакай на борт, поки він не відплив!",  -- db:11320
[805028232] = "Привіт! Нас блокують ті нікчемні пірати в затоці! Як думаєш, зможеш нам допомогти, скинувши на них кілька бомб?!$B$BНаш викрадений цепелін відлетить менш ніж за $3078w хвилин.  Не забудь піднятися на борт, коли він вирушить!",  -- db:11322
[276301366] = "Привіт! Нас блокують ті нікчемні пірати в затоці! Як думаєш, зможеш нам допомогти — скинути на них кілька бомб?!$B$BНаш викрадений цепелін уже майже тут... Здається, я вже чую його.  Не забудь піднятися на борт, коли він відлетить!",  -- db:11324
[420188393] = "Я в полоні!$B$BВони збили мене і мій прекрасний цепелін прямо з неба. І за що? За те, що я перевозив людей і матеріали для Орди? У цьому ж немає нічого нового!$B$BА тепер вони змушують мене кружляти нею навколо затоки, щоб мати змогу бомбити піратів. У мене просто немає запчастин, щоб підтримувати її в такому стані! Я ледь тримаю її на плаву за допомогою слюни та дроту!$B$BЯ не несу відповідальності за те, що з вами станеться, але вам краще сісти на борт, поки вона не відпливла.$B$BЦе злочин, кажу вам!",  -- db:11328
[201611181] = "Я в полоні!$B$BВони збили мене і мій прекрасний цепелін прямо з неба. І за що? За те, що я перевозила людей і матеріали для Орди? У цьому ж немає нічого нового!$B$BА тепер вони змушують мене кружляти на ній навколо затоки, щоб мати змогу бомбити піратів. У мене просто немає запчастин, щоб підтримувати її в такому стані! Я ледь тримаю її на плаву за допомогою слюні та дроту!$B$BЯкщо ти вирішив їм допомогти, вона має повернутися в порт менш ніж за хвилину.$B$BЦе злочин, кажу тобі!",  -- db:11330
[280364411] = "День і ніч я тільки й роблю, що сиджу тут, виготовляю боєприпаси та перетягую тятиви арбалетів.$B$BI, мабуть, ти хочеш, щоб я щось зробив і для тебе?",  -- db:11352
[807493827] = "Що відбувається?",  -- db:11356
[532648176] = "Я хочу повернутися до дитячого будинку!",  -- db:11356
[271278148] = "Матроно!  Цей лихий чоловік нас з’їсть?",  -- db:11356
[273043049] = "Якби мій тато був живий, він би загасив ці пожежі!",  -- db:11356
[521736186] = "Якби моя мама була жива, вона б загасила ці пожежі!",  -- db:11356
[506753972] = "Він пішов?  Ура!",  -- db:11358
[380095195] = "Безголовий вершник був страшним, але я не злякався!  Тільки не я!",  -- db:11358
[685439476] = "Безголовий вершник втік!",  -- db:11358
[15686665] = "Якщо він повернеться, ти знову будеш з ним битися?",  -- db:11358
[241504764] = "Якби ж у мене був такий $gfather:mother;, як ти!",  -- db:11358
[340206635] = "«Хеллоуз-Енд» — це моторошне свято, але мені воно подобається!",  -- db:11359
[911609354] = "Ти бачив Безголового вершника?  Наглядачка каже, що якщо я на нього подивлюся, він перетворить мене на гарбуз!",  -- db:11359
[182648816] = "Біля бочки з водою можна наповнити відро.  Так весело плескатися!",  -- db:11359
[526859510] = "Я раніше бачив, як солдати зі Штормовію гасили пожежу. Вони були справжніми героями!",  -- db:11359
[14442873] = "Безголовий вершник живе у Скарлетському монастирі. Іноді він виходить і лякає дорослих, але мене — ні!",  -- db:11359
[253551436] = "Я вже раніше взяв трохи цукерок у готелі.  Не можу дочекатися, щоб взяти ще!",  -- db:11359
[834542108] = "Ця дошка використовується представниками «Стімвідл» у «Мадспрокет» для розміщення оголошень про винагороди та вакансії.",  -- db:11365
[950852866] = "Справді! Я надав їм усі можливі переваги, які тільки міг. Я просто не можу уявити, що пішло не так.$b$bОсь, $c, візьми один. Я вніс кілька змін — насправді, це лише невеликі вдосконалення. Тепер немає жодних виправдань для невдачі!",  -- db:11370
[427134911] = "Може, краще відійдіть трохи подалі. Потрошіння риби — це брудна робота.",  -- db:11376
[786581256] = "Королівське товариство аптекарів вітає вас у Нортренді, $c.  Тож, що ви зробите, аби допомогти нам у служінні Сильвані?",  -- db:11384
[59646801] = "Ситуація тут гірша, ніж я думав! Цей цепелін — це ледь не купа покрученого металу та палаючого палива!",  -- db:11403
[938743394] = "Ласкаво просимо до Терамора, $c.",  -- db:11406
[964953364] = "У мене небагато часу на розмови, якщо це не терміново, громадянине. Ворота Терамора — це моя найважливіша відповідальність.",  -- db:11424
[193677477] = "Слава Світлу, що Дефіаси й гадки не мають про дайвінг!",  -- db:11432
[217279240] = "Ласкаво просимо до Терамора.",  -- db:11457
[445562687] = "Які заклинання тебе сьогодні цікавлять, $c?",  -- db:11458
[872623139] = "Приємно познайомитися, $c.",  -- db:11469
[773751689] = "Існує вісім типів карт «Темного Місяця»: «Звірі», «Благословення», «Елементалі», «Фурії», «Божевілля», «Портали», «Бурі» та «Воєначальники», у кожній масті — по вісім карт, від туза до вісімки. Якщо ви зберете всі вісім карт однієї масті, то зможете перетворити їх на колоду, яку можна віддати професору Таддеусу Палео в обмін на потужний амулет.$B",  -- db:11472
[356483614] = "Розум Безголового Вершника охоплений божевіллям! Під час «Хеллоу-Енду» він може напасти на це селище в будь-яку мить.",  -- db:11473
[359604228] = "Безголовий вершник підпалив село!  Ми мусимо захистити дітей!",  -- db:11474
[458796034] = "Безголовий вершник атакує!  Швидше, допоможіть своїм побратимам з Орди захистити село!",  -- db:11475
[431115533] = "Безголовий вершник, принаймні наразі, був відігнаний. Ми можемо на деякий час зітхнути з полегшенням, але мусимо завжди залишатися пильними.",  -- db:11476
[132563243] = "Ти бачив Безголового вершника? Якщо він з’явиться тут, я з ним поб’юся і відберу його гарбуз!",  -- db:11477
[234123039] = "Мені подобається гратися у бочці з водою, але мені кажуть, що вона не призначена для дітей.",  -- db:11477
[109786384] = "Мені подобається гратися у бочці з водою, але мені кажуть, що вона не для дітей.",  -- db:11477
[221576229] = "Кажуть, що бочка та відра призначені для гасіння пожеж. Ви пожежник?",  -- db:11477
[502940513] = "Безголовий вершник мешкає у Скарлетському монастирі разом з усіма іншими моторошними привидами та людьми.",  -- db:11477
[403125991] = "У готелі роздають цукерки та ласощі!  Стражник Грімвотч каже, що якщо вони не дадуть нам ласощів... то ми зможемо зіграти з ними жарт!",  -- db:11477
[381481744] = "Вітаю, друже, і ласкаво просимо на найграндіозніше шоу в Замежжя!$B$BБудь ласка, підходьте ближче й насолоджуйтеся всім, що ми можемо запропонувати.  Подивіться на дивовижні речі, які Ярмарок Темної Місяця відкрив у цьому величезному й таємничому світі!  Ми не шкодували коштів, щоб подарувати вам захоплюючі враження, які сподобаються дітям будь-якого віку!",  -- db:11482
[210770227] = "Я даю капітану поради з тих питань, про які він вирішує мені розповісти, але у мене таке відчуття, що він волів би почути вашу думку.",  -- db:11496
[32499264] = "Стільки ротів, яких треба годувати, і хто це має робити? Я!$B$BГотувати, прибирати та все інше!",  -- db:11498
[545145405] = "За все своє життя я й подумати не міг, що колись побачу таку чудову нову межу.$B$BЯкби тільки вона не була заплямована злом і знаннями, які краще залишити прихованими.",  -- db:11502
[634020955] = "Ти досягнув меж моїх знань, але попереду ще багато чого потрібно дізнатися. За морем, у Кварталі магів міста Штормовій, мешкає видатний кравець. Його звати Джорджіо Болеро, і, гадаю, саме він тепер буде навчати тебе. Іди й поговори з ним.",  -- db:11551
[762123089] = "Земля... замерзла. Ми тут — легка здобич; ці «м’ясні фургони» нікуди не поїдуть.",  -- db:11562
[769318487] = "Як це виглядає?  Земля замерзла, наче камінь!$B$BКолеса цих «м’ясних фургонів» розраховані, у кращому разі, на їзду по багнюці.  Щоб їх витягнути, нам знадобиться якась потвора і ланцюги.",  -- db:11564
[466707576] = "Я ніколи не назву селище Брекенволл своїм домом. Бо це означало б відмовитися від надії повернути наші законні землі.",  -- db:11567
[443685762] = "Що ж, мабуть, я тобі винен подяку, $r.$b$b. Правда в тому, що я вже думав, ніби випив свій останній кухоль, поки ти не з’явився.",  -- db:11578
[798132699] = "Ооо, величезне спасибі, що витягли мене з тієї клітки, бо я пробула там так довго, а там пахло фаршем з баранини, який тиждень пролежав на сонці, та й взагалі я не люблю баранину, бо коли я була маленькою, ну, ще меншою, мене насправді на хвилину перетворили на вівцю, тож я знаю, як це — бути вівцею, і я не хочу, щоб мене хтось з’їв, особливо перерослий троль, переодягнений у котика...$b$b<Ешлі робить глибокий вдих.>$b$bЯк моє волосся?$B",  -- db:11582
[303794594] = "Залишені напризволяще моряки Альянсу знають, що їм не уникнути смерті, але все одно чинять нам запеклий опір.$B$BЦе водночас вражає й викликає жаль.",  -- db:11586
[865383270] = "За кілька годин Альянс у «Занедбаному березі» зазнає нищівної поразки. Вони оточені й перебувають у чисельній меншості.",  -- db:11586
[789077424] = "З волі Сильвани наші вороги будуть розгромлені.",  -- db:11586
[67195701] = "Саме ці дві гармати вздовж стіни сповільнюють наш наступ. Без їхнього прикриття наші війська змогли б штурмувати їхні укріплення без жодних втрат.$B$BАбо знищити ці гармати, або чекати, поки в них закінчиться боєприпаси. Гадаю, вибір за Ансельмом.",  -- db:11588
[581024579] = "Безголовий вершник, який колись був лицарем «Срібної Руки» та героєм серед своїх побратимів-паладинів, опинився під прокляттям.  Збожеволівши в «Скарлатовому монастирі», він вважає, що саме він живий, а ми — мертві.$B$BТепер його запал уже не служить Світлу.  З настанням Свята Хеллоу він сіє морок і вогонь у селах Азерота.",  -- db:11590
[771754014] = "Свобода! Життя Краза закінчилося.$b$bДякую тобі, $c.",  -- db:11602
[221340996] = "Кразу ніколи не слід було приїжджати до цього проклятого місця... Треба було знати, що не можна довіряти людині. Я був сліпим дурнем, $c, так само як і ти, якщо підеш за його порадою.$b$bМого сина, який зник два місяці тому, востаннє бачили разом із людиною на ім’я Бадд. Він сказав мені, що я зможу знайти його за стінами Зул’Амана...$b$bЯ пішов за його людьми сюди і потрапив у полон разом з усіма іншими. Без твоєї допомоги я був приречений на смерть.$b$bДякую тобі, незнайомцю.",  -- db:11604
[84959867] = "Заходьте з холоду та трохи відпочиньте свої втомлені кістки. Ми радо вас приймемо.",  -- db:11607
[645556479] = "Іди у світлі, дитино моя.",  -- db:11614
[399149663] = "$G Пане; Пані! Я тут, щоб допомогти вам і захистити вас.$B$BЯкі ваші вказівки?",  -- db:11622
[569586488] = "Довгі роки я був розгублений. А тепер, нарешті, я розумію, наскільки темною стала моя душа...",  -- db:11625
[847707759] = "Голова гарбуза зловісно тліє...",  -- db:11645
[216134155] = "Поспішай, $c!$b$bЦя криза ще далеко не взята під контроль.",  -- db:11655
[944690094] = "Ти шукаєш, куди б переправитися, $N?  Мої кажани доставлять тебе туди в одну мить.",  -- db:11662
[655205995] = "Будь обережним, $r.$b$bЦі трупи — це все, що залишилося від моїх найкращих бійців.",  -- db:11667
[95410089] = "Ці «Пондсакери» з Альянсу — справді сміливці! Штурмувати есмінці «Покинутих» з повним екіпажем… це, мабуть, найсамогубніша поведінка, про яку я коли-небудь чув.",  -- db:11671
[873885697] = "Ми з сестрами раді вітати вас, $r.",  -- db:11673
[938099307] = "Будьте пильні, $n.$b$bМи ще не вийшли з лісу...",  -- db:11676
[634398665] = "Я тут, щоб допомогти вам і захистити вас.$B$BЯк нам далі завдати удару по ворогу?",  -- db:11689
[905955602] = "Підійди ближче, юнаку; мої вуха вже не ті, що колись, а підвищувати голос мені не хочеться.",  -- db:11691
[896716149] = "Стільки способів використання чуми, а часу так мало!",  -- db:11724
[786631651] = "Ти — справжня втіха для очей!$B$BТреба попрацювати, а часу небагато.",  -- db:11738
[429435198] = "Горт не боїться загинути. Ці «Покинуті» просто знову мене зібрали до купи.",  -- db:11742
[97427818] = "Горт іноді губиться.  Горт добре вбиває людей, тому його призначили сержантом.  Але тепер Горту ніколи не доводиться нікого вбивати!",  -- db:11742
[254645665] = "Врикули більші й сильніші за нас. Але ми привабливіші!",  -- db:11742
[836215611] = "«Бластенхаймер 5000 Ультра-гармата» — це найсучасніший одномісний метальний пристрій. Ця гармата, що вистрілює свій заряд зі швидкістю, близькою до швидкості дракона, є гордістю та радістю родини Бластенхаймерів, всесвітньо відомої своїми досягненнями в галузі авіації та вибухових речовин!$B$BЯкщо ви хочете злетіти в небо й літати вільно, як птах, зверніться до Максими Бластенхаймер на Терасі Світла в місті Шаттрат. Вона націлить вас на мішень у невеликому ставку за межами міських стін!",  -- db:11743
[943899937] = "Говори тихіше, $c. Не хочемо, щоб вони нас почули.",  -- db:11746
[857248393] = "Я все життя провів у війську. Я воював у багатьох війнах, під різними прапорами — але це завжди були чужі битви.$B$BЦього разу все інакше. Кожен солдат «Покинутих», якого ви тут бачите, прийшов сюди з єдиною метою. Артаса треба вбити.",  -- db:11796
[507377127] = "Зголодніли? Тут можна й переночувати.",  -- db:11797
[222158544] = "Будь насторожі, $r, нас тут оточують ходячі мерці.",  -- db:11799
[356310732] = "Ми, рознощики чуми, зазвичай дещо практичніші, ніж звичайні аптекарі. Адже ми займаємося логістикою поширення чуми.$B$BЦе не означає, що наші теоретичні знання не є бездоганними. Просто ми віддаємо перевагу... практичним завданням.",  -- db:11827
[669954283] = "Я тобі дуже вдячний, $c.$b$bЯкщо я можу щось для тебе зробити, просто скажи.",  -- db:11851
[928457473] = "З боку Ліги Дослідників було дуже люб’язно дозволити мені приєднатися до них. Однак, з огляду на небезпеки, що чатують у Рівенвуді та його околицях, схоже, я вчинив нерозумно, вирушивши туди без супроводу.",  -- db:11858
[313191864] = "Я буду сумувати за табором «Вінтерхуф», але розумію, чому вождь Аштотем прийняв таке рішення. Дім — це затишок, який ми не завжди можемо собі дозволити.",  -- db:11874
[242004623] = "Гей, ти що, не бачиш, що я тут намагаюся випити?",  -- db:11880
[410326932] = "Кістки... плоть... м’язи... сухожилля... хрящі... все це зливається тут під моєю ножівкою.",  -- db:11884
[64272393] = "Ось тобі, $g, хлопче : дівчино;. Використовуй їх з розумом!",  -- db:11898
[522022295] = "Звісно. Я знайшов його на трупі карлика, що лежав неподалік.",  -- db:11910
[577188674] = "Звичайно.",  -- db:11912
[305233440] = "Привіт!  Те, що я вмію ганятися на баранах краще за всіх, ще не означає, що я не долучуся до допомоги пивоварам.  Ви теж можете допомогти, якщо хочете.$b$bАле зачекайте, це ще не все!$b$bДопомагаючи в організації Пивного фестивалю, ви отримаєте шанс прокататися на найшвидших баранах у всьому світі!",  -- db:11945
[182119323] = "У темні часи зав'язуються дивні дружні стосунки. Можливо, варто завітати до старого Лордаерона, щоб подивитися, як «Покинуті» спалюють свого маленького чоловічка з лози.",  -- db:11956
[429034179] = "Я розумію, що це свято започаткувала не наша союзники, а Орда. Чому ми їх наслідуємо, я не знаю.",  -- db:11957
[987036673] = "Ми святкуємо те, що хтось звільнився від чого? Та ну, кому це взагалі цікаво?! Більше цукерок!",  -- db:11958
[730722162] = "Кажу вам, роздавати всі ці безкоштовні цукерки — це просто поганий бізнес. Або... може, це просто «заманлива пропозиція»... спочатку заманюють вас у корчму, а потім здирають з вас шалені гроші за м’ясо. Це геніально!",  -- db:11960
[880431927] = "Коли «Хеллоуз-Енд» закінчиться, ми розтрощимо всі ці гарбузи. Це буде найкращий день у моєму житті!",  -- db:11961
[503382862] = "Святкувати появу на світ ще одного смертельного ворога — це, м’яко кажучи, дивна річ. Проте ми приєднаємося до наших союзників у їхніх урочистостях.",  -- db:11962
[300831167] = "«Покинуті» мають повне право святкувати свою свободу. Що ще може бути важливішим?",  -- db:11963
[469399440] = "Я не розумію, яке значення має те, що «Покинуті» щоночі спалюють велике плетене опудало, але наші власні ритуали, мабуть, здаються їм не менш дивними.",  -- db:11964
[215261329] = "Під час свята «Кінець Хеллоу» ми відзначаємо день, коли сама Королева Банші визволила нас із лап Короля Ліча та Плеті. Не пропустіть фестиваль «Вікермен», який щовечора проводиться за межами Андерсіті.",  -- db:11966
[561419078] = "Мої клієнти шукають безліч рідкісних і цінних предметів.$B$BСаме ви могли б принести їх мені, $c. Натомість я запропоную вам те, чого ви так прагнете.$B$BЧи не поговоримо детальніше про те, що я сподіваюся сьогодні придбати?",  -- db:12044
[123101727] = "Ми облаштували цю ділянку для відпрацювання навичок пожежогасіння. Адже ніколи не знаєш, коли місту загрожуватиме небезпека!",  -- db:12049
[853941703] = "Готовий побитися об заклад, ти вважаєш себе крутим, еге ж, хлопче? Гадаю, у мене може щось для тебе знайдеться, якщо ти зможеш показати себе на арені. Класна штука, не така, як у Крікселя. Це вже минулий сезон, розумієш?$b$bО, і гарного тобі дня.",  -- db:12052
[34243672] = "На «Брюфесті» завжди не вистачає бочок!$b$bЯ позичу тобі одного зі своїх баранів.$b$bКожного разу, коли ти принесеш мені бочку, я дам тобі кілька жетонів.  Я навіть дозволю тобі користуватися бараном трохи довше за кожен бочонок, який ти принесеш мені!  $B$BЗверни увагу! Якщо ти почнеш це завдання, то не зможеш повторити його до завтра.$B$BТи впевнений, що готовий до цього?",  -- db:12076
[572749528] = "Я розумію, що багато хто шукає романтики в тавернах і на таких фестивалях, як цей, але алкоголь притуплює почуття і затуманює розум, не даючи тверезо оцінити труднощі повсякденного життя!$b$bАле я знайшов рішення! Після багатьох випробувань і поневірянь я сконструював надзвичайний пристрій, який дає тобі всі переваги алкоголю без жодних недоліків! У цих окулярах БУДЬ-ХТО виглядає привабливо!$b$bМмм... включаючи тебе, красуне! Знаєш що? Я зроблю тобі знижку!",  -- db:12080
[128959962] = "Хіба вона не красуня? Хочеш прокататися на ній?",  -- db:12082
[190194807] = "Привіт!  Чи хочете ви дізнатися більше про гоночних баранів та гонки баранів?",  -- db:12083
[173614314] = "Коли ви візьметеся за одне з цих завдань, ми позичимо вам барана. Це позика, тож вона не триватиме вічно. Баран може здатися повільним, але просто трохи послабте поводи — і він прискорить крок.$b$bНаші барани обожнюють яблука. Ми розклали кілька бушелів яблук уздовж шляху, тож не забудьте там зупинитися. З’ївши яблука, ваш баран забуде про те, як він втомився.",  -- db:12084
[79961229] = "Коли ти сідаєш на барана, ти отримуєш і поводи. Але це не ті поводи, що у твоєї бабусі — ти мусиш ними користуватися!$b$bПросто кілька разів ослаб поводи, щоб набрати швидкість. Продовжуй ослаблювати їх — і вперед!  Ти полетиш!$b$bАле чим швидше він біжить, тим швидше втомлюється. Тож треба бути обережним.$B",  -- db:12085
[662928577] = "Як тільки ви почнете послаблювати поводи на барані, ви помітите, як змінюється його швидкість. Спочатку він йде кроком. Послабте поводи ще трохи — і він перейде на рись. Якщо під час рисі ще більше послабити поводи, він перейде на кантер. А якщо під час кантера послабити поводи ще більше, він перейде на галоп.$B$B",  -- db:12086
[538777857] = "Як тільки ви почнете послаблювати поводи на барані, ви помітите, як змінюється його швидкість. Спочатку він іде кроком. Послабте поводи ще трохи — і він перейде на рись. Якщо під час рисі ще більше послабити поводи, він перейде на кантер. А якщо під час кантера послабити поводи ще більше, він перейде на галоп.",  -- db:12086
[879380432] = "Якщо занадто довго тримати барана в рисі або галопі, він втомиться. Якщо ви хочете, щоб баран трохи відновив сили, дайте йому пройти кроком або риссю. Якщо поблизу є бушелі яблук, відведіть його туди, щоб він міг відпочити.$B$B",  -- db:12087
[241192003] = "Якщо занадто довго тримати барана в галопі, він втомиться. Якщо ви хочете, щоб баран трохи відновив сили, дайте йому пройти кроком або риссю. Якщо поблизу є бушелі з яблуками, відведіть його туди, щоб він міг відпочити.",  -- db:12087
[83684375] = "Гонки на баранах простіші, ніж здається, але щоб довести свою майстерність до досконалості, потрібні певні навички. Просто користуйтеся поводами, їжте яблука, якщо є можливість, і не давайте барану перевтомитися.$B$B",  -- db:12088
[284527460] = "Гонки на баранах простіші, ніж здається, але щоб досконало їх освоїти, потрібна вправність. Просто користуйтеся поводами, їжте яблука, якщо є можливість, і не давайте барану перевтомитися.",  -- db:12088
[648580826] = "Так? У чому справа?$B$BЧас нікого не чекає!",  -- db:12090
[161353396] = "Якщо ви заробите достатньо призових квитків «Пивного фестивалю», то в обмінному пункті в таборі «Пивного фестивалю» вам можуть поставити на руці штамп «Почесний пивовар».$b$bЦей штамп дозволить мені продати вам верхового барана «Пивного фестивалю». Але майте на увазі: вони коштують недешево!",  -- db:12092
[504608023] = "Привіт, друже, у мене тут справжній прорив, якого ще ніхто ніколи не бачив!  І він на продаж — за копійки!$b$bРозумієш, мені набридло витрачати гроші в тавернах у пошуках ідеальної людини.  Тому я зробив ці окуляри, і тепер УСІ виглядають просто ідеально.  Я маю на увазі, що з цими штучками ти НІКОЛИ не помилишся!$b$bТож, хочеш їх випробувати й трохи поповнити мою кишеню?  Оскільки ти виглядаєш так класно, я навіть зроблю тобі знижку!",  -- db:12098
[751078502] = "Зараз звичайні собаки навіть близько до мене не підходять. Я був у відчаї, коли дізнався про це... Раніше я дуже любив цих тварин.$B$BПроте «чумні собаки» — чудова заміна. Вони, щоправда, не такі вже й... приємні на вигляд. Але, зрештою, я теж не красень!",  -- db:12103
[560148335] = "Привіт, друже, готовий спробувати найкраще пиво у всіх світах?",  -- db:12105
[431228450] = "Тут ми відпрацьовуємо прийоми пожежогасіння.  Слава «Покинутим»!",  -- db:12108
[361000783] = "Та аварія між цим місцем і Разор-Хіллом серйозно зіпсувала процес варіння пива!  А ще не допомагає те, що карлики Темного Заліза, здається, нападають приблизно щогодини!$b$bТож якщо хочеш допомогти, ось що треба зробити.  Я позичу тобі віжки та одного зі своїх баранів.$b$bКожного разу, коли ти принесеш мені бочку, я дам тобі кілька жетонів.  Я навіть дозволю тобі користуватися бараном трохи довше за кожен бочонок, який ти принесеш мені!$b$bАЛЕ, як тільки ти почнеш це робити, ти не зможеш повторити це до завтра.$b$bТи впевнений, що готовий до цього?",  -- db:12113
[489017435] = "Бачу, ти роздивляєшся наших законно придбаних гоночних баранів...  Бачу, ти хочеш долучитися до сенсації — гонок на баранах...  Але перш ніж грати, треба попрацювати.$b$bЩо ж, робота й розвага — це практично одне й те саме, коли йдеться про цих баранів.",  -- db:12114
[48301287] = "Ахой, друже!  Як справи, ти, морський вовк!$B$BТут справжній ажіотаж, ти, бешкетнику!",  -- db:12120
[227013365] = "Виглядаєш просто чудово, друже! Ти що, пограбував якогось багатія-постачальника? Краще поділися здобиччю... Не будь боягузливим цуценям, друже!",  -- db:12120
[618730674] = "Дивись-но туди, друже! Той мерзенний бобо прилип до обличчя Кваші. Цього глухого матроса чекає сувора кара, чувак... Його протягнуть під кілем і зроблять з нього привида, чувак.",  -- db:12120
[807016790] = "Це правда, друже!  Немає жорсткіших моряків, ніж ці пірати з Північного моря, чувак!$B$BB Краще не заводи з ними суперечку, чувак.  Забудь про це!  Половина цих ідіотів-матросів мріють поцілувати дочку капітана, друже!",  -- db:12120
[371133981] = "Ти просто дурний і зухвалий, чувак! Ти хочеш мене роздратувати, ти, клятий пес-негідник?$B$Бга, ну ж бо, ти, боягузливий негідник. Побачимося при першому світлі!",  -- db:12121
[660110979] = "<Старий Айсфін обережно дивиться на тебе, його риб’яче око кліпає, а він один раз киває головою вгору-вниз, лаконічно відмахуючись.>",  -- db:12130
[406802691] = "Порада розумному, чужинцю: повертайся туди, звідки ти прийшов.$b$bЦе місце не для безтурботних мандрівників. Воно проковтне таких, як ти, і виплюне твої кістки.",  -- db:12135
[258639349] = "Ця велика гарбузова ліхтарня стоїть посеред села.",  -- db:12137
[159303745] = "Гарбуз розбитий, і більше ніяких скарбів у ньому немає.",  -- db:12138
[802805830] = "Розбивши гарбуз, ти знайдеш захований скарб!  Це найкращий день у твоєму житті!",  -- db:12140
[955932760] = "Вітаю вас, нехай Світло Елуни буде з вами.",  -- db:12162
[94655908] = "Я б із задоволенням прочитав це тобі!$B$BНе стій біля моєї могили й не плач,$BЯ там не лежу, я не сплю.$B$BЯ — у тисячі вітрів, що дмуть,$Bнад яскравим і сяючим снігом Нортренда.$B$BЯ — лагідні дощі,$Bщо падають на поля Вестфолу, вкриті золотим зерном.$B$BЯ — у ранковій тиші,$Bзелених і пишних джунглів Странглторна.$B$BЯ — у гучних і величних барабанах,$Bу громоподібному тупоті копит по Награнду.$B$BЯ — це зірки, що тепло сяють,$Bнад Дарнасусом, що лагідно мріє.$B$BЯ — це птахи, що співають,$BЯ — у кожній прекрасній речі.$B$BНе стойте біля моєї могили й не плачте,$BЯ там немає. Я не вмираю.$B",  -- db:12163
[224387031] = "Скажу тобі, полювати як слід можна тільки тоді, коли ти добряче нап’єшся!",  -- db:12165
[570746474] = "<Сокіл голодно кричить, вимагаючи їжі.>",  -- db:12168
[344570763] = "Краще не висовуйся, «друже»! Якщо розумієш, про що я!$B$Бя-я-я!",  -- db:12170
[963488022] = "Я тут керую боями. Хочете зробити ставку — робіть це сміливо — а того, кого спіймають на підтасовуванні результатів, чекає прогулянка по дошці.$B$BIЯ сам про це подбаю!",  -- db:12173
[930568172] = "День у день божевільний Джона Стерлінг вимагає від мене лише одного — мити палуби.$B$BМити палуби?!$B$BЯ ж маг, я не займаюся миттям! Принаймні не таким банальним способом.",  -- db:12176
[610465713] = "То що буде?  Ром?  Ель?$B$BАбо, може, щось інше?",  -- db:12179
[932524320] = "Ти збираєшся влаштувати Джеку витівку на очах у його хлопців?$B$BДля цього треба чимало... дурості.  Ну, тобі це дорого обійдеться.  Я не збираюся ризикувати своїм життям заради чогось меншого, ніж золото.  І тобі краще почекати, поки я не зникну з дороги, перш ніж робити будь-які кроки.",  -- db:12180
[831112098] = "Привід випити ніколи не завадить!",  -- db:12181
[325940284] = "З поверненням, $N.",  -- db:12185
[961860228] = "Цей проклятий Джона Стерлінг приведе нас прямо до загибелі. Якби він більше часу проводив поза своєю печерою, то зрозумів би, яка це дурість — нападати на професійні військово-морські сили в умовах війни.",  -- db:12186
[823231293] = "Той чувак, що там, дуже засмучений через свій килимок.",  -- db:12190
[681420712] = "Добрий вечір, пане.",  -- db:12191
[266111777] = "Я, ма... ма... мабуть, ти хочеш поїхати назад до того форпосту. Так?",  -- db:12193
[28646830] = "Цю бочку елю охороняє Джарвен Тандербрю.  Поки він перебуває в підвалі, до бочок нікому не можна торкатися.",  -- db:12198
[751856505] = "Часи змінюються, $N.  Настала війна.$B$BЧи зможе наш народ виявити себе в цій ситуації та допомогти нашим союзникам... чи ми залишимося осторонь?",  -- db:12208
[354569075] = "У мене мало часу на розмови, вибачте.",  -- db:12209
[348377153] = "Хіба ти не бачиш, що я тут працюю, $glad:lass;? Забирайся звідси, поки Ковальський не побачив, як я базікаю.",  -- db:12210
[306794850] = "Нас залишилося небагато, $N.  Повернення нашого давнього ворога викликає велике занепокоєння.",  -- db:12213
[197774733] = "Так, саме так її звуть, і це справді чудовий корабель.$b$bЗнаєте, у таких суден можна багато чому навчитися. Один великий поет колись сказав: «Кораблі, що пропливають уночі й спілкуються між собою мимохідь, лише подаючи сигнал і віддалений голос у темряві; так і на океані життя ми пропливаємо й спілкуємося один з одним — лише погляд і голос, а потім знову темрява й тиша».",  -- db:12217
[95363636] = "Якщо ви бажаєте перекусити, шеф-кухар Грейс із задоволенням подбає про ваші потреби.",  -- db:12218
[880277936] = "Пан Комбс, судновий інженер і квартирмейстер, може забезпечити вас усім необхідним. Він також непогано ладнає з технікою, тож якщо ваше спорядження потребує ремонту, звертайтеся до нього.",  -- db:12219
[578673164] = "А, так, це... ім'я. Ну... як то кажуть, добре ім'я, як і добра репутація, здобувається багатьма вчинками, а втрачається одним. Немає потреби вдаватися в подробиці «як» і «чому»; достатньо сказати, що саме так мене називають деякі люди.",  -- db:12220
[430280836] = "Мертві повстають і мстяться кожному, хто наважиться пройти через їхні володіння. Повертайтеся назад!$B",  -- db:12221
[817275155] = "Щоб нам вдалося створити портал на острів Квель'Данас та до Сонцеколодязя, що знаходиться на ньому, ми мусимо знайти джерело енергії, достатньо потужне, щоб активувати портал.$B$BНаразі ми виконали $3269w відсотків від запланованого обсягу робіт. Чи допоможете ви нам, $c?",  -- db:12226
[286928000] = "Цей портал не схожий на інші, що ведуть назад до Азероту. Щоб підтримувати його, нам потрібно здобути більше манових комірок.$B$BАбо це, або ми ризикуємо втратити доступ до Острова Квель'Данаса та Сонцеколодязя.",  -- db:12227
[473508819] = "Вітаю, $r.$b$bМій магазин нарешті відкрився. Сподіваюся, вам сподобається те, що ви побачите!",  -- db:12237
[886377600] = "Доброго дня, $c.$b$bЩоб допомогти у цій справі, потрібно зробити ще багато чого. На жаль, я мало що можу для вас зробити, поки не отримаю всі необхідні матеріали.$b$bНаразі я зібрав $3223w$ відсотків коренів «бритвенного рогу», необхідних для початку роботи. Запевняю вас, будь-яка ваша допомога буде варта витрачених зусиль.",  -- db:12238
[638084382] = "Це ворота, через які війська Кела відступили до Сонцеколодязя. Деякі з його посіпак досі залишаються тут; Легіон винагородив їх у вельми… незвичайний спосіб.",  -- db:12239
[708463666] = "Ви бачили пошкоджені вартові, що блукають островом?  Кілька модифікацій кристалів, які керують їхньою поведінкою, дозволять нам взяти їх під контроль і використати для убезпечення тактично важливих точок.$B$BСвятилище «Досягнення Сонця» незабаром стане нашим.  Ми виконали $3244w відсотків цієї мети.",  -- db:12240
[683702591] = "Нам вдалося захопити «Санктум». Ми можемо й надалі переманювати вартових і використовувати їх як охоронців на інших стратегічно важливих об’єктах.",  -- db:12241
[27573048] = "Ми повинні подбати про те, щоб більше ніхто не загинув у морі.",  -- db:12243
[932072904] = "Вибач, $c, але я мушу зосередитися на роботі.",  -- db:12244
[314723278] = "Багато хто загинув у морях. Мені та вогникам доручено шукати ці душі.",  -- db:12245
[558084266] = "Ми з вогниками спостерігаємо за морем у пошуках загублених душ.",  -- db:12246
[790456775] = "Море — це небезпечне місце, $c.  Ми повинні бути пильними.",  -- db:12247
[826215049] = "На жаль, зараз я не можу з вами поговорити.",  -- db:12248
[693560377] = "Захоплення «Санктуму досяжності Сонця» стало першим кроком у нашому бойовому плані. Наступним завданням є взяття під контроль зброярні.$B$BМи виконали $3233w відсотків від поставленої мети.",  -- db:12255
[603905783] = "Ми взяли під контроль зброярню, але наша робота на острові ще не завершена.",  -- db:12256
[639625947] = "Мені наказано створити відволікаючий маневр у «Мертвій Шрамі», щоб наші війська змогли захопити арсенал «Сонячного Досягу». Можливо, це не так захопливо, як вбивати демонів віч-на-віч, але якщо це допоможе нам виграти цю битву, то я повністю за.$B$BМи виконали $3233w відсотків від поставленої мети.",  -- db:12257
[478599768] = "Ми захопили зброярню, $N.  Однак не варто зупинятися на досягнутому.  Легіон, безсумнівно, цього не зробить.",  -- db:12258
[106175397] = "Активація захисних заклинань у святилищі допоможе нам швидше його убезпечити. Ми не хочемо, щоб будь-які «Прокляті» стали нам на заваді, коли ми розпочнемо повномасштабну атаку на Легіон і Келя.$B$BМи виконали $3244w відсотків від поставленої мети.",  -- db:12260
[876837663] = "Екіпаж «Bravery» докладе всіх зусиль, щоб зробити вашу подорож якомога швидшою та приємнішою.",  -- db:12262
[65840431] = "Вибачте, але нам доведеться поговорити іншим разом. До побачення.",  -- db:12263
[674499572] = "Ласкаво просимо до «The Bravery», $gsir:madame;. А тепер, якщо ви мене вибачите...",  -- db:12264
[321403342] = "Не дуже вдале ім’я для моряка, чи не так?",  -- db:12267
[793422320] = "Ми пообіцяли докласти всіх зусиль, щоб захистити пасажирів корабля «The Bravery». Морський шлях між Аубердіном і гаванню Штормовію повинен залишатися безпечним.",  -- db:12270
[997147233] = "Якщо у тебе бурчить у животі, звернися до шефа камбуза Стілбеллі, але, між нами кажучи, тобі, мабуть, краще почекати. Він не дарма носить таке ім’я.",  -- db:12273
[669000167] = "Будьте обережні на борту «Благословення Елуни», $r.  Хоча Елуна благословила нас зустріччю з новими друзями, нам також довелося пережити чимало випробувань у морі.$b$bПроте порятунок душ, загублених у морі або в новому світі, — це справді благословення від Елуни.",  -- db:12277
[185164308] = "Елуна неодноразово благословила нас усіма тими відкриттями, яких ми досягли.  Але ми маємо залишатися пильними, $c.",  -- db:12278
[481961531] = "Вибач, $r, я мушу зосередитися на роботі.",  -- db:12279
[631152351] = "Ласкаво просимо на борт «Maiden's Fancy». Подорож до порту має пройти без перешкод.",  -- db:12281
[845356456] = "Дивовижно, чого можна навчитися у гнома, якщо його досить сильно стиснути: хитрих маленьких хитрощів, як викрутитися з скрутного становища, як спекти смачне печиво і навіть як змайструвати літальний апарат.",  -- db:12282
[836640324] = "Як тільки можу. Це чудове фізичне навантаження, а ще завдяки цьому я в курсі того, чим вони займаються — а це, як показує мій досвід, завжди нічого доброго.",  -- db:12283
[49407835] = "Урррк... якщо той ненажерливий шеф-кухар з камбуза запропонує тобі свою «фірмову страву», зроби собі послугу — викинь її в океан. Можливо, вона вб’є кількох макрур, а не твоє бажання жити.",  -- db:12284
[628093142] = "Привіт, $r.$b$bДавайте братися до справи! Немає сенсу чекати на припаси, які, можливо, ніколи не надійдуть.$b$bМені потрібна ковадло, щоб як слід екіпірувати наші війська. Наразі її готовність становить $3228w відсотків.$b$bА коли ковадло буде готове, я зможу викувати для вас набагато більше потужних предметів.",  -- db:12285
[265354189] = "Привіт, $n.$b$bТепер, коли я закінчив створювати свою ковадло, можу приступити до екіпірування наших військ. Це важливий крок, але попереду ще багато роботи.$b$bА що для тебе ще важливіше, з’явилися нові речі, які я можу створити і які, можливо, тебе зацікавлять.",  -- db:12286
[221500084] = "Ми захопили гавань, і цей корабель — приємний бонус. Шкода, що він ще не готовий до плавання.$B$BTим часом мені доручили проконтролювати боротьбу з нагами на узбережжі Грінгілл.$B$BГадаєш, зможеш мені допомогти?",  -- db:12287
[135142214] = "<Бурчить>  Мабуть, ці гори з’явилися нізвідки...  Усі п’ять разів!",  -- db:12289
[123242838] = "<Бурчить>  Можна було б подумати, що розбити цепелін об океан — це складно.  А ще складніше — зробити це аж чотири рази!",  -- db:12289
[710457129] = "<Бурчить> Хотілося б сказати, що нам вдалося уникнути аварійних приводнень у озерах. Хотілося б сказати, що ми впали в озеро лише один раз... але нам вдалося впасти аж у чотири різні озера, включаючи озеро Лордамере!",  -- db:12289
[672831787] = "Мене вражає, що гілки сосен, здається, не завдають нашому кораблю особливої шкоди.$b$bХоча це, звичайно, не виправдовує тих трьох випадків, коли ми врізалися в якийсь ліс.",  -- db:12289
[434522271] = "Я ніколи не думав, що колись побачу Телдрасіл... І вже точно не думав, що ми вріжемося в Телдрасіл.",  -- db:12289
[333645812] = "Нам уже двічі вдалося пробратися через Грім-Скелю!",  -- db:12289
[699060278] = "<Бурчить> Я досі не розумію, як нам вдалося пробратися крізь «Тисячу Голків» без жодної подряпини, а потім розбитися в «Мерехтливих рівнинах»!",  -- db:12289
[134896015] = "Якщо ви любите гострі відчуття, наш капітан — найкращий! Я обожнюю цю роботу!",  -- db:12290
[996451980] = "Не питай...",  -- db:12291
[744217673] = "Я радий, що ти запитав. Наші зусилля з захоплення зброярні становлять $3233w відсотків від запланованого.$B$B Я знаю, що бойова магічка Аринна та провісник Інууро потребують твоєї допомоги. Знайди їх усередині Святилища «Досяжність Сонця» на острові Квель'Данас.",  -- db:12300
[429911867] = "З останнього, що я чула від Хаути, вона зазначила, що ми пройшли $3228w відсотків шляху до мети.$B$BЯ не можу навіть висловити, наскільки важливо для наших зусиль, щоб ми їх створили. Нашим бійцям знадобляться краща броня та зброя, а ковадло й кузня — це ключ до цього.$B$BКоваля ви знайдете за зброярнею «Сонячний Край», $N.",  -- db:12301
[226279058] = "Ні, на жаль, ми ще не захопили гавань. Однак, за повідомленнями, ми вже пройшли $3238w відсотків$ цього шляху.$B$B$N, якщо хочете допомогти, зверніться до магістра Іластара та захисника Каалана в зброярні «Сонячний Край» на острові Квель'Данас.",  -- db:12302
[364782171] = "Алхімічна лабораторія ще не зовсім готова, $N. Однак Мар'на каже, що вона завершила її монтаж на $3223w відсотків.$B$BЯкщо ви хочете допомогти їй у цьому, ви знайдете її всередині таверни в гавані «Сонячний берег».",  -- db:12303
[747665981] = "Ми намагаємося зруйнувати Агамат — Перші Ворота. Будь ласка, $c, вирушай на острів Квель'Данас і допоможи, як тільки зможеш!",  -- db:12304
[677353013] = "Агамат, Перші Ворота прорвані, і двох заступників Кіл’яедена — леді Сакролаш та Великого чаклуна Алітеса — необхідно знищити.$B$BЗберіть своїх друзів, $c, і подбайте про це! Рохендор, Другі Ворота — наша наступна ціль.",  -- db:12305
[877633343] = "«Залізний орел». Хм. Це пасажирський корабель, а не бойовий літак! Але що ж, робота є робота, і я буду терпіти капітана «Бомбаста», доки за це платить принц.$b$bУ будь-якому разі, ласкаво просимо на борт.",  -- db:12314
[521389749] = "Трохи зайнятий.",  -- db:12315
[598393394] = "Що? Я тут зайнятий.",  -- db:12315
[10974534] = "На чергуванні. Іди. Геть.",  -- db:12315
[606008626] = "Потрібно щось полагодити? Скористайтеся Vend-O-Tron D-Luxe.",  -- db:12315
[489365557] = "Ми захищаємо цей дирижабль під час його перельоту з Оргримара до базового табору Гром'гол у Долині Странглторн.",  -- db:12316
[137356279] = "Зараз ні, $gpal:sugar;... У мене є справи. До зустрічі.",  -- db:12317
[744560576] = "Ми майже закріпили свій контроль над «Санс-Річ». Якщо нам вдасться не допустити надходження підкріплення до гавані, ми неодмінно досягнемо успіху.$B$BМи виконали $3238w відсотків від поставленої мети.",  -- db:12319
[152407566] = "Ми це зробили, $N. Тепер, коли «Sun's Reach» під нашим контролем, нас відділяє лише кілька миттєвостей від абсолютної перемоги.",  -- db:12320
[122779583] = "Я збираю кошти на спорудження пам’ятника на честь тих, хто загинув у війні. Важливо не забувати про жертви, які ми принесли заради перемоги.$B$BМи досягли $3275w відсотків від поставленої мети.",  -- db:12322
[128314972] = "Хіба цей меморіал не прекрасний? Важливо пам’ятати про ті моменти в нашій історії, коли приносилися великі жертви, щоб ми не забули, якою ціною даються всі війни — навіть ті, що закінчилися перемогою.",  -- db:12323
[893910151] = "Ласкаво просимо на борт $c.  Розслабтеся та насолоджуйтеся подорожжю.  На борту «The Purple Princess» ми хочемо, щоб ви відпочили.  На нижній палубі встановлені автомати з напоями та закусками — якщо вам щось знадобиться під час подорожі.",  -- db:12327
[702643180] = "Будь ласка, дайте мені кілька секунд перепочити.",  -- db:12330
[300133157] = "Дай мені ще п’ять хвилин поспати, чувак...",  -- db:12331
[206128814] = "Зараз я зайнятий.",  -- db:12332
[447168785] = "Потрібно щось полагодити? Скористайтеся Vend-O-Tron.",  -- db:12332
[475880631] = "Зараз у мене немає часу розмовляти.",  -- db:12332
[748638274] = "Політ із Гром'гола до Андерсіті — чудовий, хоча й без особливих подій.  Хоча це не привід засинати на службі.",  -- db:12333
[98213431] = "Заходь з-поміж попелу та бруду. Трохи витрися.",  -- db:12334
[178842492] = "Не вступай у бій з ворогом, не підготувавшись, $N.  Я можу надати тобі дуже потужні предмети... за умови, що ти доведеш нам свою надійність.",  -- db:12338
[532559512] = "Прислужникам Кела незабаром дадуть урок смиренності. Ми розгромимо армію «Мечів Світанку» і відберемо у них гавань «Сонячний Мис».$B$BМи виконали $3238w відсотків від нашої мети.",  -- db:12339
[358635112] = "«Сонячний Край» — наш. Собаки Кела втікають... Настав час покласти край їхнім мукам!",  -- db:12340
[346937699] = "Ммррглглглг? Глбмр брмрргл глмррбмрргл.$B$BГрглгрлбрр мрргл!!!",  -- db:12343
[779575787] = "Найкращий захист — це напад; це знає кожен.",  -- db:12347
[727008292] = "Потужна зброя ні до чого, якщо ти не проживеш достатньо довго, щоб нею скористатися, $c.",  -- db:12348
[54624821] = "Гауургггл! Блргл-бргл гргл!",  -- db:12349
[70849798] = "Я ж не сліпий, знаєш. Я бачу, що тут відбувається!",  -- db:12352
[32992314] = "Блург-аургугле-мрр?",  -- db:12360
[672674408] = "Мої брати й сестри збожеволіли! Чи не могли б ви допомогти мені вибратися звідси?",  -- db:12361
[143709391] = "Глуг-бмргл-грггл!",  -- db:12362
[8346196] = "Маууррггл, буль-бур!",  -- db:12362
[692497265] = "Глумрргл?",  -- db:12362
[547758056] = "Брргл-брргл, Мрргл-Мрргл! Глук!",  -- db:12362
[587369965] = "Блрмрргл гулргл грр.",  -- db:12362
[824604501] = "РАВГРЛРЛРЛРРЛГРЛ!!!",  -- db:12362
[73934570] = "Мрглрглрглргл... глргл?",  -- db:12362
[989817123] = "Мрглмргл Глрггл!",  -- db:12362
[804414569] = "Немає часу на розмови — мені треба працювати!",  -- db:12363
[605928136] = "Ти мене розумієш? А я тебе розумію!",  -- db:12363
[881561361] = "$R, навіщо мені з тобою розмовляти? Це ж, мабуть, саме твої люди й влаштували цей безлад!",  -- db:12363
[95790070] = "Треба зібрати молюсків і вполювати косаток. Допоможіть або не заважайте!",  -- db:12363
[917948958] = "Блурглгр мурбргл... жартую, я тебе розумію.",  -- db:12363
[831456092] = "Ти вже з’ясував, чому наші брати й сестри в селі збожеволіли?",  -- db:12363
[389126721] = "Я знав, що нам ні в якому разі не слід було заходити в ті печери. Це ненормально!",  -- db:12363
[599223365] = "У новому королі Мргл-Мргл є щось підозріле, але я ніяк не можу зрозуміти, що саме.",  -- db:12363
[269750379] = "Хай прокляті будуть Каел'тас і його фелкровні! Усе, над чим ми працювали, зникло, але вони дурні, якщо думають, що ми не будемо чинити опір. Леді Ліадрін уже шукає нове джерело сили для нашого ордену. Нас не знищити так легко.",  -- db:12370
[536676193] = "На Фестивалі літнього вогню кожен знайде щось для себе!",  -- db:12376
[930539834] = "По всій країні наші вогнища палають яскраво й міцно!",  -- db:12376
[518121169] = "Ти вже танцювала біля стовпа зі стрічками?",  -- db:12376
[967325109] = "Я захоплююся майстерністю жонглерів з факелами.",  -- db:12376
[435074923] = "Ви дісталися до багаття Альянсу! Оскверніть це багаття та загасіть його!",  -- db:12377
[159558001] = "Нам потрібно підготувати цей аванпост до наступу на басейн Шолазар.$B$BНе стій просто так, $c. Виходь і захищай честь Орди, проливаючи кров!",  -- db:12382
[614413648] = "Мені доведеться прибрати цей безлад, але я зроблю це без нарікань.$B$BЯкщо у вас хоч трохи гордості за Орду, ви мені допоможете!",  -- db:12384
[270923607] = "Духи промовляють навколо нас. Ти слухаєш, $r?",  -- db:12387
[876395401] = "«Культ Сутінків» прагне зруйнувати все те, за збереження чого ми боремося. Наш святий обов’язок — не допустити, щоб ця біда сталася, $r.",  -- db:12390
[469656639] = "Я зганьблений. Мені слід було загинути разом із провидцем у Магмоті.$B$BЗалиште мене наодинці з моїми думками.",  -- db:12394
[462624899] = "Елемент повітря тут неспокійний. Будьте обережні... вони не дадуть вам пройти без наслідків.",  -- db:12395
[367360552] = "Мені боляче бачити, як моїх предків турбують у їхніх могилах.$B$BМи мусимо знищити проклятого духа вашого командувача Стілджоу, того, хто нерозважливо провів свій караван через ці священні землі.",  -- db:12403
[603026584] = "Тільки ти можеш врятувати мене від Каганішу, $N.",  -- db:12413
[600494290] = "Ми втратили чимало наших вершників-вітряків під час розвідувальних місій на захід. «Покарання» безжально розправляється з будь-якими потенційними шпигунами.$B$BНа щастя, я придумав рішення, яке ставить під загрозу лише життя самого вершника. Рівень виживання тих, кого переправляють через Рівнини Насам, становить 30%. Це на 30% краще, ніж тоді, коли ми використовували вершників вітру!",  -- db:12417
[575734706] = "Я зганьблений. Мені слід було загинути разом із провидцем у Магмоті.",  -- db:12419
[277286949] = "І «Пристань Гароша», і «Пал’єа» були знищені туманом. Ми єдині, хто настільки божевільний, щоб залишитися тут, друже!",  -- db:12422
[857825546] = "Те, що ти бачиш тут, на цьому узбережжі, — це не наслідок дій «Покарання». Насправді ми вважаємо, що «Покарання» теж бояться туману — можливо, саме тому вони сюди не заходять.$B$BРозумієш, друже, цей туман — живий. У цих повітряних пагонах ховається смерть...$B$BЯкщо ти потрапиш у його обійми, ти зникнеш. Туман забере тебе!$B$BМи ніколи не бачили, щоб хтось повернувся з туману живим.",  -- db:12424
[928841056] = "З моменту приземлення тут я бачив жахи, які раніше переслідували мене лише в найстрашніших кошмарах, але ніщо не могло підготувати мене до того, що чекає за туманом.$B$B<Муту киває головою.>$B$BКрізь цей туман, не далі ніж за кілька ярдів від нас, стоять кровожерливі істоти, відомі як Квальдір. Ніхто не повернувся з туману, і лише небагато з тих, хто спочатку перебував на причалі, коли насунувся туман, змогли врятуватися. З того часу ця територія була оголошена Хеллскрімом забороненою зоною. Заходьте на власний ризик...",  -- db:12426
[816072942] = "Я... А ти...$B$B<Муту здригається.>$B$BТи прийшов мене врятувати?",  -- db:12427
[137575527] = "Ти — справжня втіха для очей! Я занадто слабкий, щоб розірвати ланки цих іржавих кайданів.$B$BНу що ж, не стій просто так! Розв’яжи мене!",  -- db:12433
[198052775] = "У мене зараз тут повно справ, $c.$B$BЧим можу вам допомогти?",  -- db:12435
[809133368] = "Говори повільніше, дитино, я ще не звик до твоєї дивної мови.",  -- db:12440
[882172311] = "Будь ласка, говоріть тихіше — пані Хамат уже літня, і їй потрібен відпочинок.",  -- db:12441
[613934383] = "Ну що ж, сідайте. Це може зайняти деякий час.$B$BКоли ми вперше прибули до цього замерзлого пекла, генерал Арлос, що перебував у фортеці «Валіанс», доручив мені та моїй групі літаючих сміливців особливе завдання: створити передову авіабазу для операцій Альянсу.$B$BЦя злітно-посадкова смуга — результат цієї роботи. Повірте, це було нелегко — з усіма цими огидними звірами та землею, твердою як камінь від морозу! Але ми впоралися, і ще й швидко!",  -- db:12456
[559374477] = "У будь-якому разі, нам потрібно було закачати велику кількість піску та нафти для обладнання. Сусідні водойми виявилися для цього ідеальними.$B$BДеякий пісок навіть виявив магічні властивості… Хіба це не відкриває нові можливості!? Але це вже інша історія.$B$BОтже, ми злили більшу частину води й побудували насосну станцію прямо посередині. Усе йшло як по маслу, аж поки одного дня головна всмоктувальна труба не забилася.",  -- db:12457
[879645307] = "Звісно, про це я дізнався пізніше, бо в той момент мене там не було.$B$BКоли вони збільшили силу всмоктування насоса, на поверхню випливли уламки робота, який виглядав як гном! Звісно, ці дурні працювали день і ніч, щоб зібрати його назад, не сказавши нам ні слова.$B$BСаме тоді ми втратили зв’язок із насосною станцією.",  -- db:12458
[642885058] = "Після кількох днів тиші я відправив розвідувальний загін на платформу. Вони так і не повернулися.$B$BNаступного дня я відправив ще одну групу — з тим самим результатом, а під час повітряної розвідки втратив кілька літальних апаратів.$B$BТоді я відправив когось на південь по допомогу, а ми затаїлися, готуючись до найгіршого. Ми зосередили всю свою увагу на виготовленні броні, зброї та роботів, щоб вийти туди в повному складі.$B$BКоли ми це зробили кілька днів тому, ми не могли повірити своїм очам!",  -- db:12459
[821551550] = "Як я вже казав, те, що ми там побачили, не піддавалося жодному поясненню.$B$BМоїх людей ніде не було видно, але натомість там була справжня армія роботів та андроїдів, які займалися своїми справами!$B$BУсі дроїди виглядали як гноми, і вони сказали, що чекали на нас. Насправді, по-своєму дивному, вони поводилися так, ніби знали нас. Нас оточили й швидко відвели на верхню частину насосної станції.$B$BСаме там ми побачили їхнього ватажка і те, що він робив із гномами, які вижили!",  -- db:12460
[718645553] = "Він називав себе Гірмейстер Мечазод. Коли ми прибули, він був зайнятий перетворенням тих, хто вижив, на механічних істот!$B$BВін тепло нас привітав і пояснив, що був одним із перших гномів, яких коли-небудь створив той, кого він називав «Великим Архітектором» — титан-хранитель із залів легендарного Ульдуара.$B$BСудячи з усього, саме він і був тим уламком, який моя команда випадково засмоктала з місця, де він вийшов з ладу тисячі років тому. Нам просто пощастило, що ми побудували насосну станцію прямо над ним.",  -- db:12461
[663318192] = "Механіки станції зібрали його заново, повертаючи до «життя».$B$BІ тепер, на знак подяки, він збирався віддячити нам, вилікувавши всіх нас від того, що він називав «Прокляттям плоті».$B$BЗа словами Мехазода, це стан, який зрештою спіткає всі творіння Титанів! Іншими словами, ми всі нібито починаємо як якісь роботи, а протягом тисяч років повільно перетворюємося на плотських істот!$B$BАбсурд, я знаю.",  -- db:12462
[509542304] = "Мені це не здавалося якимось особливим «ліком», і я не мав наміру просто стояти й слухати якогось божевільного робота, поки він розправлявся з моїми людьми!$B$BМи зробили те, що зробив би будь-який розсудливий гном... ми втекли! Ну, власне, більшість із нас стрибнула з парашутами з краю платформи, але ви розумієте, про що йдеться.$B$BНебагато хто з нас зміг повернутися сюди, і ми досі розкидані по всьому світу, бо мусимо ще й боротися з усім іншим — наприклад, з магнатаурами на півночі та Плетью на сході. А щоб ще більше погіршити ситуацію, Орда щойно влаштувалася на північному заході!",  -- db:12463
[902983406] = "І ось у такій ситуації ми зараз опинилися, $N.$B$BМи ніяк не зможемо впоратися з усім цим самотужки, і, чесно кажучи, я відчуваю, що це мені трохи не під силу. Джинки знає, що потрібно робити. Тобі слід негайно піти до неї.$B$BЯ лише сподіваюся, що тобі вдасться витягнути нас із цієї халепи цілими й неушкодженими.",  -- db:12464
[60357279] = "Вчинки цих дезертирів ганьблять нас усіх. Ця ганьба настільки сильна, що її треба побачити на власні очі, щоб зрозуміти. Саме тому Уг’тор тут… Хлопчик повинен навчитися.",  -- db:12472
[624992376] = "Будь обережним у цих краях, $r. Місцеві жителі безжальні.",  -- db:12475
[139677529] = "Отже, $N, який товар тебе цікавить?",  -- db:12494
[716694845] = "Ах — дивацтва та раритети. Ми спеціалізуємося на найунікальніших предметах Азерота для вибагливих мандрівників.$B$BОскільки ви звертаєтеся до мене, ви, мабуть, уже маєте уявлення про те, що саме шукаєте.",  -- db:12495
[85297074] = "Чи знали ви, що алхіміки можуть перетворювати певні дорогоцінні камені?  Ми з Мар'ною обговорювали це.$B$BIЯ переконаний, що, з огляду на її майстерність, як тільки її лабораторія буде готова, ми з нею зможемо створити дорогоцінні камені, які, як вважалося, були втрачені в часі.",  -- db:12496
[181614697] = "Ми це зробили, $N.  Марна навчилася перетворювати дуже особливі дорогоцінні камені.  А я навчився з ними працювати.",  -- db:12497
[177795707] = "Ласкаво просимо, $c. Ти прийшов вшанувати це полум’я?$b$bПам’ятай: наші святкові багаття палають у кожній землі, де є поселення Альянсу. Якщо зможеш, знайди час, щоб вшанувати кожне з них.$b$bОрда теж розпалює свої багаття. Тобі варто зневажити такі негідні спроби, коли ти їх побачиш.",  -- db:12504
[806820094] = "Ось вони — Полум’я літа!",  -- db:12506
[528950037] = "Обережно, не обпечіться!",  -- db:12506
[673720943] = "Вам подобається Фестиваль вогню?",  -- db:12506
[724235292] = "Ласкаво просимо! Чи вшанували ви вже полум’я цієї землі?",  -- db:12506
[486492049] = "Хоча наступи Несінгварі на дику природу Нортренда було зупинено, його чергова спроба вторгнення — лише питання часу. Ти повинен залишатися пильним, $N!$B$B. І, перш за все, не піддавайся жодним спокусам, які можуть постати перед тобою... Демон спробує зачарувати вас. Коли це станеться, ви повинні протистояти йому!",  -- db:12511
[627853437] = "Хай мене чорт забере, якщо ці кляті «Скорж» змусять нас піти геть! Ми, поселенці, пожертвували всім, щоб почати нове життя в Нортренді.$B$BПовірте, ми будемо боротися до останнього.",  -- db:12521
[666089949] = "Камінь випромінює пронизливий холод, охолоджуючи повітря навколо себе та платформу, на якій він лежить. Глибоко в його гранях пульсує блакитне світло, ніби чекаючи чогось.",  -- db:12524
[522597824] = "Декому з нас вдається уникнути військової служби. Хороший рибалка завжди знадобиться… адже навіть генералам треба їсти.",  -- db:12528
[829810575] = "Ще один звичайний день на кухні. Згодом це, звичайно, набридає.",  -- db:12529
[861453324] = "Моя зміна вже майже закінчилася. Не можу дочекатися, щоб трохи подрімати, розумієш, про що я?",  -- db:12530
[982945835] = "Потрібне золото? Ось вам на суму 5 000 монет.",  -- db:12532
[849723251] = "Артас колись був людським принцом.  Армія, яку він очолював у Нортренді, зазнала жахливої долі.$B$BМій брат, Тассаріан, був у складі тієї армії.",  -- db:12534
[340046732] = "Ми — шахтарі, селяни та ремісники, а не солдати. Але якщо доведеться, ми захистимо нашу землю голими руками.",  -- db:12538
[647357156] = "Вибачте, але мої послуги можуть бути корисними лише мисливцям.",  -- db:12539
[68535638] = "Вибачте, але мої послуги можуть бути корисними лише друїдам.",  -- db:12540
[228532227] = "Чим можу вам допомогти, $c?",  -- db:12541
[663950453] = "Я можу стерти всі твої таланти, щоб ти міг обрати нові.$b$bКожного разу, коли ти це робиш, це стає дедалі дорожчим.",  -- db:12542
[437301194] = "Вибачте, але мої послуги можуть бути корисними лише для магів.",  -- db:12544
[623889623] = "Вибачте, але мої послуги можуть бути корисними лише для паладинів.",  -- db:12545
[929177908] = "Вибачте, але мої послуги можуть бути корисними лише для священиків.",  -- db:12546
[395128794] = "Вибачте, але мої послуги можуть бути корисними лише розбійникам.",  -- db:12547
[369795869] = "Вибачте, але мої послуги можуть бути корисними лише шаманам.",  -- db:12548
[511029727] = "Вибачте, але мої послуги можуть бути корисними лише чаклунам.",  -- db:12549
[677627726] = "Вибачте, але мої послуги можуть бути корисними лише воїнам.",  -- db:12550
[996622146] = "Можу я вам щось запропонувати?  Мій асортимент трохи обмежений, але це й не дивно... з огляду на обставини.",  -- db:12553
[2260676] = "Що?",  -- db:12554
[235081812] = "Померти за свою країну — це обов’язок солдата. Але якщо називати цю війну безглуздям — це зрада, то я — зрадник.",  -- db:12555
[121455779] = "Зараз я дуже зайнятий, $r. Будь ласка, дай мені спокій.",  -- db:12556
[846002201] = "Зберися з думками, смертний. Це передова лінія війни, якої ти ще ніколи не бачив.$b$bТобі знадобиться повне володіння своїми здібностями, якщо ти хочеш бути хоч якоюсь користю.",  -- db:12566
[683496963] = "Коли Ахуне з’явиться на поверхні, чи будемо ми готові?",  -- db:12572
[294936862] = "Ой... $b$b Де я?",  -- db:12577
[874251347] = "Ласкаво просимо, $c. Ти прийшов вшанувати це полум’я?$b$bПам’ятай: наші святкові багаття палають у кожній землі, де є поселення Орди. Якщо зможеш, знайди час, щоб вшанувати кожне з них.$b$bАльянс теж розпалює свої багаття. Тобі варто зневажити такі негідні зусилля, коли ти їх побачиш.",  -- db:12582
[199785540] = "Тоді я радий, що ти прийшов. Тепер, коли ти знаєш про наші вогнища та про те, як їх шанувати... а також про вогнища наших ворогів і про те, як їх гасити... ти можеш повернутися до нього й отримати нагороду.",  -- db:12587
[186722891] = "Одним словом — магія.$b$bБезвідповідальні смертні, чиє життя таке коротке, навіть не замислюються над довгостроковими наслідками своїх вчинків.$b$bТаємні енергії використовуються надто безладно, порушуючи рівновагу світу. Якщо це триватиме й надалі, Азерот незабаром буде знищений.$b$bУ цьому обидві сторони згодні. Але ще до того, як вдалося скликати раду, Малігос втілив у життя свій власний план.$b$bНам не залишилося іншого вибору, як протистояти йому.",  -- db:12590
[401772639] = "Ми рухаємося вперед, $r, але надто повільно.",  -- db:12591
[997069084] = "Ми мусимо перемогти! Доля Азерота висить на волосині...",  -- db:12592
[877877867] = "Малігос, Ткач Заклинань, Володар Магії, Повелитель Блакитного Драконячого Польоту. Він є Аспектом блакитних драконів, одним із найдавніших створінь Азерота.$b$bКажуть, що він оговтується від божевілля, яке тривало тисячоліттями, але його останні дії змушують мене вважати, що він все ще далекий від здорового глузду.$b$bЙого рішенням нашої дилеми є пошук і знищення кожного смертного на Азероті, що володіє магією.$b$bЯк охоронці життя, це змусило Червоний драконячий полк вжити заходів.$b$bТепер дракони воюють проти драконів, і доля нашого крихкого світу висить на волосині.",  -- db:12593
[70596330] = "Я радий, що ти тут, $c. Військова ситуація на плато Санвелл досить похмура.",  -- db:12596
[336749452] = "Капітан Селана доручила мені допомогти вам у ваших діях тут, на плато Санвелл.",  -- db:12597
[141706934] = "Операція «Розбите Сонце» досягла значного прогресу на околицях острова Квель'Данас. Війська Кіл'яедена відступають, і в цьому хаосі мені вдалося очолити невеликий розвідувальний загін, який проник сюди, на плато Санвелл. Мої війська просунулися через площу Паргеліон, виявили групу кровоельфів «Сонячних мечів» і вступили з ними в бій. Ця сутичка швидко перетворилася на катастрофу.",  -- db:12598
[113671521] = "Захисники Кіл'яедена тут, на плато Санвелл, набагато сильніші за всіх, з ким ми стикалися на острові. Легіон навіть спотворив нашу технологію «Таємних охоронців» за допомогою фель-енергії, щоб створити щось набагато зловісніше. Лише один із цих «Захисників Сонячного Меча» практично знищив мої війська, і я віддав наказ про швидкий відхід. Я очікував, що мій загін буде повністю витіснений з плато, але ворог здивував мене, припинивши переслідування.",  -- db:12599
[164845221] = "Насолоджуєшся фестивалем, $c?$b$bПоки «Хранителі Вогню» доглядають за вогнищами сьогодення, я, як історик, зберігаю спогади про минулі фестивалі. Звісно, я також документую цьогорічні урочистості. Поки що все йде добре, чи не так?$b$bЗнаєш, $n, у всіх святкових вогнищах, що палають протягом усього свята, криється сила. Ми дбаємо про наші, але я впевнений, що священні полум’я палають і в глибині міст наших ворогів...",  -- db:12609
[491482796] = "Ласкаво просимо до нашого табору, $c. Якщо хочеш, можеш тут відпочити.",  -- db:12610
[208931415] = "Тут для нас нічого не залишилося.",  -- db:12611
[414815643] = "Мою родину безжально винищили. Навіть дітей.",  -- db:12611
[266939842] = "Нехай Король Ліч горить у пекельному вогні за те, що він накликав на цю землю.",  -- db:12611
[962902272] = "Зараз ми — народ, який не має власної батьківщини.",  -- db:12611
[426446464] = "«Скаурдж» — це безстрашна машина, покликана покласти кінець усьому життю на цій планеті.",  -- db:12611
[617403086] = "Той, кого називають Пекельний Крик, може виявитися нашою єдиною надією.",  -- db:12611
[919396757] = "Тепер нас може врятувати лише Орда.",  -- db:12611
[644537727] = "Чи надасть мені Орда можливість битися проти Плеті?",  -- db:12618
[16626195] = "Щоб помститися за свій народ, щоб вигнати лихо, яке охопило нашу землю, — я прийму твою присягу. Я віддам Орді все, що маю, і все, чим є.",  -- db:12619
[798755315] = "Лок'тар огар! Перемога або смерть — саме ці слова пов'язують мене з Ордою. Адже вони є найсвятішою та найголовнішою істиною для будь-якого воїна Орди.$B$BЯ добровільно віддаю своє тіло та кров Вождю. Я — знаряддя волі мого Вождя. Я — зброя, що виконує накази мого Вождя.$B$BВід цієї миті й до кінця днів я живу й вмираю — ЗА ОРДУ!",  -- db:12620
[198222009] = "Гей, чувак! Відведи мене до моїх братів-тролів!",  -- db:12622
[197602717] = "Час пограти в «троль-квач», друже!",  -- db:12622
[923346771] = "Мої брати-тролі, сьогодні вас чекає справжня веселість, чувак!",  -- db:12622
[131699047] = "Хі-хі-хі! Це буде весело, чувак!",  -- db:12622
[23206394] = "Ти впевнений, що ми йдемо в правильному напрямку, чувак?",  -- db:12622
[220696410] = "<вдихаю, вдихаю> Я відчуваю їх запах, чувак.",  -- db:12622
[727275344] = "Ніщо так не висловлює любов, як легке поплескування по голівці.",  -- db:12622
[542050555] = "Усі три ворота на плато Санвелл було зруйновано, $N.$B$BВи повинні зібрати свої сили та не дати Кіл’ядену проникнути в Азерот, поки ще не все втрачено!",  -- db:12623
[549510573] = "«Ріплаш» ніколи не повернеться до колишньої слави, але ці негідники, що катаються на човнах, заплатять за свої вчинки — клянуся!",  -- db:12626
[773072280] = "Наш обов’язок — захищати цих таунка та забезпечити їм той невеликий комфорт, який ми можемо їм запропонувати.",  -- db:12627
[705970175] = "Я ніколи не розумів, чому деякі пірати закопують свої скарби. А я... я люблю тримати їх під рукою.",  -- db:12636
[108520588] = "У гавані Моа'кі мешкають дві великі морські черепахи: «Мандрівник хвиль» і «Зелений острів». Вони плавають між Уну'пе та Камагуа.",  -- db:12640
[721036447] = "Не терпиться потрапити до Нортренда, чи не так? Пароплав «Кракен» відпливає звідси до фортеці «Валіанс» у Бореанській тундрі.",  -- db:12641
[595529105] = "Привіт! Сумуєш за Східними Королівствами, так? Ну, якщо тобі дійсно не терпиться повернутися, «Кракен» відпливає назад до Штормовію. Я, наприклад, із задоволенням насолодився б теплішою погодою!",  -- db:12644
[293417961] = "Наша благословенна велика морська черепаха, «Грін-Айленд», вирушає звідси до гавані Моа’кі в Драконовій Пустелі.",  -- db:12645
[971736359] = "Привіт. Хочеш повернутися до Старого Світу? Полети до Полян Тірісфал із шиком на «Хмароцілувальці».",  -- db:12646
[815816685] = "Нортренд чекає на вас, $r. Величний «Хмароцілувач» доправить вас прямо через море до Пристані Помсти у Виючому фіорді.",  -- db:12649
[138757511] = "Збираєшся додому, $c? «Могутній вітер» доправить тебе туди, якщо твій дім у Калімдорі. Вона летить прямо звідси до Дуротара.",  -- db:12650
[326248066] = "Розшукується за вбивство за зраду та інші зрадницькі дії проти Орди!$B$BУсі винагороди виплачує капітан Горт.",  -- db:12657
[923045851] = "Все, чого я коли-небудь прагнув, — це знову служити своєму королю. Заради людства, проти спільного ворога.$B$BНатомість я виявляю, що в наші ряди проникла культова нечисть... і все вказує на те, що джерелом цієї гнилі є Наксанар.",  -- db:12663
[195864476] = "Саме звідси надходять накази культистів. Їхній ватажок неодмінно незабаром з’явиться.$B$BНе пропустимо цю нагоду.",  -- db:12664
[285021973] = "Що?  Що?!  Іди геть.",  -- db:12666
[545354051] = "Якщо мені вдасться створити нову бойову машину, я знаю, що зможу отримати за неї чималу суму біля «Воріт Гніву».  $B$BДеякі з наших попередніх моделей були не зовсім… стабільними, але моя літаюча машина має спрацювати, якщо мені тільки вдасться розробити для неї ефективну бомбову систему.",  -- db:12667
[229141842] = "Стоячи перед цим стародавнім ідолом, ти відчуваєш дивну присутність.",  -- db:12669
[87663981] = "Там, де тисячоліттями спочивало «Око пророків», залишилася лише порожня ніша.",  -- db:12670
[981974343] = "Ласкаво просимо! Якщо вам потрібно місце для відпочинку, я можу вирішити цю проблему.",  -- db:12673
[894859904] = "Шукаєте «Арену Батлмастера»? Їх можна зустріти на дорозі між містами або в столицях.$B$BВи можете прив’язати мене як точку відправлення. Я також можу телепортувати вас до однієї зі столиць.",  -- db:12684
[178599935] = "Ласкаво просимо, $c!  Сподіваюся, ти не боїшся висоти!$b$bУ мене для тебе є тренувальний парашут.  Ці парашути призначені для швидкої посадки.  Якщо хочеш плавно спуститися на землю, скористайся кріпленням.  А якщо прагнеш гострих відчуттів і припливу адреналіну — просто стрибай.  У останню мить ти розгортаєш парашут.  Саме для цього їх і створили.  Швидка дія!  Ти готовий до швидкої дії?$b$bПарашут працює лише кілька секунд.  Тож тобі доведеться точно розрахувати час.  Я не впевнений, що ти з цим впораєшся, $c.  Хотів би побачити, як ти доведеш, що я помиляюся.",  -- db:12687
[496326713] = "Тобі краще звідси забиратися, якщо не хочеш опинитися в одній із цих кліток...",  -- db:12694
[372969040] = "Дякую, $c, за те, що подбав про те, щоб я отримав листа від свого брата.$B$BБудьте впевнені, його смерть не буде марною. Блакитний драконячий полк поплатиться за це.$B$BЯ особисто про це подбаю!",  -- db:12696
[292382741] = "Зроби свій внесок у боротьбу з Плетью, солдате! Повідомляй про будь-які підозрілі дії — спочатку вбивай, а потім вже розпитуй!",  -- db:12698
[281734660] = "Запам'ятайте мої слова: ці занедбані дурні стануть причиною нашої загальної загибелі!",  -- db:12699
[813955331] = "Якщо ти мене запитаєш — а ти ж запитав — то я вважаю, що нам слід вбити всіх аптекарів, поки не стало занадто пізно!",  -- db:12699
[793117742] = "Орда — це честь і війна. Я впевнений, що в діях цих аптекарів немає нічого почесного.",  -- db:12699
[968402307] = "Я стежу за тими приреченими ідіотами там, внизу. З ними ніколи не можна бути занадто обережним!",  -- db:12699
[950820091] = "Якщо вам доведеться мати справу з тим лікарем, будьте обережні. Що б вони там не замислили, це ненормально.",  -- db:12699
[565743609] = "Чувак, західні околиці цього місця просто кишать злочинцями. Тримайся подалі від цієї місцевості, якщо хочеш залишитися живим!",  -- db:12701
[59426892] = "Мої обов’язки в «Молоті Агмара» виходять далеко за межі догляду за тваринами у стайнях.",  -- db:12703
[327822926] = "«Вийшов з ладу? Я? Хе, нізащо, малий. Це була всього лише подряпина».",  -- db:12705
[504890682] = "Якби у мене було достатньо грошей, я міг би захопити світ...",  -- db:12708
[934461440] = "Ця консоль стоїть перед парою, що піднімається з уламків. Знизу чути звуки двигуна.",  -- db:12709
[237927203] = "Відчепися від мене, дурню!",  -- db:12715
[818964497] = "Що? Ти хочеш тренуватися під моїм керівництвом, $c? Тоді тобі краще бути готовим до важкої роботи.",  -- db:12718
[731503481] = "Якщо хочеш, можеш переночувати в казармі. Тільки не буди моїх хлопців, інакше я сам викину тебе на сніг.",  -- db:12720
[18260494] = "Дякую тобі, $N, за те, що врятував мене. Я ніколи не забуду твою мужність і рішучість.",  -- db:12721
[298679391] = "Для мене буде честю битися пліч-о-пліч з тобою як брат з Орди, $N. Я приймаю твою пропозицію.",  -- db:12722
[228358417] = "Ти не справжній мужик, поки не вб’єш дракона… мужик.",  -- db:12725
[176520164] = "Вітаю, $r.  Мені шкода, що вам довелося вперше побачити нашу священну землю в такому стані.",  -- db:12727
[730327722] = "Привіт. Якщо щось знадобиться, дай мені знати.",  -- db:12732
[724258548] = "У мене є їжа, якщо ти зголоднів, і ти можеш скористатися моїм наметом, якщо тобі потрібно відпочити.",  -- db:12734
[700323377] = "Може, на вулиці й не сніжить, але ночі тут такі морозні, що ніс просто відмерзне. Ліжка знаходяться в глибині приміщення — тільки не заважайте іншим.",  -- db:12735
[691677390] = "Хех. Нічого особистого, малюку, але тобі, мабуть, краще знайти інше місце, де переночувати. Не хотілося б, щоб твоя ніжна шкірка вкрилася синцями.",  -- db:12736
[702239034] = "Заходьте до каміна й відпочиньте, $r. Сподіваюся, запах риби вас не турбує.",  -- db:12738
[271051616] = "Через долини та вершини гори Гіял, крізь рухомі піски Сілітуса, проти жахливих армій Легіону — ми билися. Ми — безіменні, безликі сини та доньки Альянсу. Ім'ям Світла та силою Альянсу перший удар належить нам, а останній удар — це все, що бачать наші вороги.$B$BМи — 7-й Легіон.$B",  -- db:12739
[797438970] = "Вітаю!  Вам щось потрібно?",  -- db:12740
[880992751] = "Усі винагороди виплачуватиме головний виконавчий директор Врот після перевірки.$B$BЗацікавлені особи можуть звертатися за додатковою інформацією.$B$BАГЕНТАМ ВХОДУ ВТРАТИТИ!",  -- db:12750
[663238276] = "Ми знищимо живих... Тобто, я маю на увазі «Поразу», звичайно ж.$B",  -- db:12751
[333275141] = "<Тускарр підозріло дивиться на тебе.>$b$bНе затримуйся тут надовго. Ти не розумієш нашого народу, а я не хочу неприємностей.",  -- db:12755
[26912038] = "Небо — це небезпечне місце, друже. Будь пильним!",  -- db:12756
[724471574] = "Будь обережним у саду Ісери, смертний. Не завжди все є таким, яким здається.",  -- db:12758
[926131567] = "Тобі щось потрібно? Може, полагодити обладунки чи зброю? Гм?",  -- db:12759
[692308813] = "У скрутні часи потрібні рішучі заходи, $c.",  -- db:12770
[408027182] = "За природною красою цих пагорбів ховається велика темрява. Будь обережним, друже.",  -- db:12773
[426039433] = "Будьте обережні, адже поблизу чатують прокляті щупальця Короля Ліча.",  -- db:12774
[465736149] = "Схоже, що туалет на вулиці зараз зайнятий.",  -- db:12775
[259612410] = "Нехай Світло очистить тебе від зарази, хоробрий $N.",  -- db:12776
[996430583] = "Мій батько подарував мені свою бойову збрую та сокиру. Незабаром я знайшов їм гідне застосування.",  -- db:12777
[288371370] = "На щастя, туалет на вулиці зараз вільний.",  -- db:12779
[150762318] = "У нас закінчуються запаси їжі та напоїв.  Боюся, що мені немає чого вам запропонувати.",  -- db:12780
[817074614] = "Дякую за допомогу, $n. Ці морозивні ягоди — це, буквально, плоди твоєї праці.",  -- db:12781
[513248100] = "Говори тихіше, $c. Я в маскуванні і шпигую на користь «Веномспайт».",  -- db:12795
[613677611] = "Як думаєш, $c, ти зможеш мене звідси витягнути?",  -- db:12804
[747675119] = "О, чудово, ти прийшов мене врятувати. А тепер випусти мене звідси!",  -- db:12805
[662175820] = "Привіт, $g, друже : пані;. Я тебе тут бачив.$B$BНе міг би ти мене звідси витягнути?",  -- db:12806
[783536793] = "Я не знаю, що сталося. Я щойно прибув до Веномспайта, а потім раптом прокинувся в цій клітці!$B$B Ти прийшов мене врятувати?",  -- db:12808
[565224692] = "Кожні два роки дух змагань стає особливо палким... і ось настав саме цей час! Ми одягаємо цей плащ, вирушаючи на Поля битв, щоб вшанувати їх, прагнучи перемогти ворогів і заслужити їхню прихильність.",  -- db:12819
[816382694] = "Вам потрібно лише зійтися з нашими суперниками на будь-якому з полів бою. Незалежно від того, виграєте ви чи програєте, якщо ви протримаєтеся до кінця бою, вам надішлють поштою табард учасника змагань.",  -- db:12820
[450147145] = "Ви повинні перемогти наших суперників на будь-якому з полів бою. З кожною перемогою у вас з’являється шанс отримати золотий медальйон поштою.",  -- db:12821
[92153932] = "Ми швидко дізнаємося, якою ціною обходиться смерть у цій крижаній пустці, $N. Сила Короля Ліча простягається на кожен дюйм Нортренда, проникаючи навіть у саму землю! Він нацьковує на нас наших власних полеглих.$B$BЗ неба вершники на грифонах обрушують на нас свої мстиві грозові молоти, а на землі на нас нападають ходячі мерці.$B",  -- db:12823
[73880913] = "Гадаю, його посадили в клітку десь біля лісопилки.",  -- db:12827
[894002361] = "Ви повинні перемогти своїх суперників на будь-якому з полів бою. З кожною перемогою у вас з’являється шанс отримати золотий медальйон поштою.",  -- db:12828
[34212138] = "Вам потрібно лише зійтися з суперниками на будь-якому з полів бою. Незалежно від того, виграєте ви чи програєте, якщо ви протримаєтеся до кінця бою, вам на пошту надійде табард учасника змагань.",  -- db:12829
[370006479] = "Гадаю, він перебуває на південній стороні абатства.",  -- db:12830
[254795297] = "Кожні два роки дух змагання стає особливо палким... і ось настав саме цей час! І Альянс, і Орда одягають цей табард на полях битв, щоб вшанувати духів, прагнучи перемогти всіх ворогів і заслужити їхню прихильність.",  -- db:12831
[449426676] = "Гадаю, її тримають десь біля шибениці.",  -- db:12832
[812139359] = "Мені здається, я бачив, як його відвели на північну сторону абатства, біля мішеней для стрільби з лука.",  -- db:12833
[902295748] = "Вітаю, $c.$b$bТи хочеш, щоб Даррок відправив тебе до Венчур-Бей?",  -- db:12838
[457189829] = "Я вже зовсім близько до того, щоб розібратися з цією рудою. Ще трохи — і я знайду рішення!",  -- db:12844
[593536744] = "Привіт, $c!$b$b! Готові вирушити до Венчур-Бей і розтрощити кілька черепів Орди?",  -- db:12845
[824545695] = "Так, мій $g син : дочка;?",  -- db:12846
[637874408] = "<Верховний абат хвилину придивляється до тебе, а потім посміхається.>$B$BDобре, я знаю одне місце, дитино. Просто поцілуй мій перстень і дай мені знати, коли будеш готова.",  -- db:12848
[598347784] = "Тоді зустрінь мене біля входу в абатство. Я незабаром підійду.",  -- db:12849
[96038355] = "Я зробив свій внесок у знищення цілих цивілізацій... і те, що мені доводиться опускатися до спілкування з цим жалюгідним «Культом Проклятих», викликає у мене огиду.",  -- db:12850
[836913301] = "Гаразд, але цього разу будь з цим обережнішим!",  -- db:12851
[683272971] = "Говоріть тихіше. Не хочемо ж привертати увагу цих звіряток!",  -- db:12852
[496774972] = "Не турбуй мене дрібницями!",  -- db:12853
[917918133] = "Хіба ти не бачиш, що я зайнятий! Ми нізащо не встигнемо підготувати цю базу до повернення принца!",  -- db:12856
[566788659] = "Якби не ці кляті звірі, що спалили наші кораблі, ми б уже давно повернулися додому. А тепер залиш мене в спокої, щоб я міг повернутися до роботи!",  -- db:12856
[398128098] = "Хороший ключок може кардинально змінити ситуацію.",  -- db:12863
[256659598] = "Привіт, друже!  Бачу, у тебе є кілька жетонів Пивного фестивалю.  Як на те, у мене ще є кілька предметів з Пивного фестивалю на продаж.",  -- db:12864
[52598983] = "Хороший напій — це міцний напій.",  -- db:12867
[694469588] = "Бути членом клубу «Пиво місяця» — це просто чудово.",  -- db:12869
[79352847] = "Ти впорався, $g lad:lass;! Я вже думав, що тобі точно кінець!",  -- db:12882
[816605362] = "Що ти ще тут робиш? Повертайся до міста!",  -- db:12883
[537814256] = "Гей, $c, ти це бачив? Там, біля поверхні води... $b$b Ти теж це бачив, правда?",  -- db:12895
[246223617] = "Що-??$b$bНу, я називаю їх «невизначеними плавучими перешкодами». А там, звідки я родом, більшість взагалі заперечує їхнє існування.$b$bАле я знаю краще! Я навіть бачив їх зблизька! Останні роки я присвятив будівництву цього судна, щоб виявляти, відстежувати, документувати та, за потреби, знищувати їх!",  -- db:12896
[898586129] = "Не дайте себе обдурити, $r. Вони дуже невловимі. В одну мить вони є, а в наступну — вже зникли — це практично незрозуміло!$b$bМіж нами кажучи, я колись навіть тримав у руці шматочок одного з них! На жаль, я не встиг провести жодних вимірювань, як він зник! Просто зник....",  -- db:12897
[498289514] = "Ти багато знаєш...$b$bОдні кажуть, що вони просто спостерігають, інші вважають, що вони впливають на наше морське життя, а ще інші думають, що вони тут, щоб захопити Азерот!$b$bЯк тільки я збиватиму одного з них своїми ракетними боєголовками, я отримаю відповіді. Можеш у це вірити!",  -- db:12898
[913857430] = "Вітаю, $r.$B$BI, ми чекали на вас.",  -- db:12899
[100054753] = "Гаразд, рушаймо!",  -- db:12900
[422522042] = "Вершники на грифонах стоять за 10 кроків від нас, друже. Вони підвезуть тебе до Посту Торсона. Рушай!",  -- db:12905
[497886306] = "Навіть на мить не думай, що твої минулі досягнення дають тобі право на що-небудь, $N.  Це не так.$B$BЯкщо ти хочеш заслужити мою повагу, тобі доведеться за це поборотися.  Це означає беззаперечно виконувати мої накази і дотримуватися їх... без жодних винятків.",  -- db:12906
[726703486] = "Ласкаво просимо до табору «Онеква».",  -- db:12912
[795447307] = "S.T.O.U.T. — це не просто мішень для кидання пивних кухлів, це цінний тренувальний ресурс. Якщо ви зможете влучити в S.T.O.U.T., то, мабуть, зможете влучити в що завгодно!$b$bТільки постарайтеся не влучити в мене.",  -- db:12913
[315887068] = "Бегарістраш говорить правду; ситуація справді серйозна.  $B$BI може надати вам здатність викликати дракона із Зеленої Зграї.  Зверніться до Бегарістраша або Етерноса, якщо ви бажаєте скористатися силою Червоної чи Бронзової Зграї.",  -- db:12915
[748276367] = "Варос Клаудстрайдер та його охоронці кільця захищають друге кільце. Ваші дракони з легкістю впораються з охоронцями кільця, але Варос стоїть за непроникним щитом, створеним з енергії самого «Окулуса».  Десять центрифужних конструкцій живлять щит із кільця та платформ, розташованих вище.  Знищте їх, і Варос стане вразливим.$B$BI може надати вам силу, щоб викликати дракона з Червоної Боротьби.  Зверніться до Етерноса або Вердіси, якщо ви бажаєте скористатися силою Бронзових або Зелених.",  -- db:12916
[549102800] = "Більшість моїх побратимів зневажливо ставляться до «варварських» звичаїв Орди, і колись я теж належав до їхнього числа. Коли мене вперше відправили до цього дещо вологого й… ароматного місця, я проклинав свою долю.$b$bПроте під час навчання я почав цінувати те, що мене оточувало. У ньому є певний шарм, чи не так?$b$bАх, і мої дослідження, звісно ж, мали на меті дати змогу іншим магам повернутися сюди за допомогою заклинання. Може, навчу й тебе?",  -- db:12926
[128187647] = "Більшість моїх побратимів зневажливо ставляться до «варварських» звичаїв Орди, і колись я теж належав до їхнього числа. Коли мене вперше відрядили до цього дещо вологого й… ароматного місця, я проклинав свою долю.$b$bПроте під час навчання я почав цінувати те, що мене оточує. У ньому є певний шарм, чи не так?$b$b... Звісно, вам, мабуть, не цікаві мої дослідження, адже ви самі не є магом.",  -- db:12927
[307277165] = "Сіну а'маноре. Якщо ти хочеш навчитися відкривати портал до Терамора, я можу тобі показати, як це зробити.",  -- db:12933
[608760191] = "Ти просто приїхав покататися, $r?$B$BАбо тебе щось турбує?",  -- db:12937
[835211950] = "Послухай-но. Коли шукаєш відповіді, ніщо не зрівняється з гарним вибухом — чим більший, тим краще!$b$bАле, мабуть, на сьогодні з питаннями досить, $r.$b$bМої боєголовки — це секретна інформація, а елемент 115, який я створив для їхнього живлення, — ще більш секретний!$b$bНасправді, тобі краще просто повернутися до свого повсякденного життя і вдавати, ніби ми ніколи не зустрічалися.",  -- db:12938
[239291533] = "Ласкаво просимо, мандрівнику. Ти прийшов якраз вчасно.",  -- db:12939
[384674107] = "Чи викликає у вас нервозність присутність Чорного Дракона?$B$BДобре. Так і має бути. Це нервує й самих драконів. Хоча вони й досі дотримуються своїх прадавніх чеснот — вони не наважилися б напасти на мене тут.$B$BDурні.",  -- db:12942
[346157728] = "Слухай, $r.$b$bЯкщо ти шукаєш шреддер, щоб покататися, тобі доведеться піднятися на пагорби трохи північніше.$b$bЦей не працює.",  -- db:12943
[213612608] = "Спочатку ми відремонтували їх, щоб вирубувати тут ліси, але відтоді, як прибув альянс і почалися бої, ми використовуємо їх як бойові машини.$b$bПовір мені, $c. Якщо у тебе є ключ, ти був би божевільним, якби ним не скористався.",  -- db:12944
[696882682] = "Вони у Грека.$b$bМожливо, він дасть тобі одну, якщо ти йому допоможеш. Наступного разу, коли ти будеш на півночі, на лісозаготівельних угіддях «Блу Скай», обов’язково поговори з ним.",  -- db:12945
[2752088] = "Так?",  -- db:12946
[952700204] = "«Безмежний Драконячий Політ» намагається змінити долю принца Артаса Менетіла. Зараз ви знаєте його як Короля Ліча, але тут і зараз він ще був принцом Лордаерона, який намагався зробити все, що було б найкращим для його королівства. Сьогодні Артас робить дуже доленосний вибір, що призведе до того, що ми, Хранителі Часу, називаємо точкою перелому в часовій лінії.",  -- db:12949
[902484281] = "«Нескінченні» намагаються вчинити щось незвично витончене для них. Вони намагаються приховати докази, які змусять Артаса прийняти рішення про знищення Стратхолма. Їхні агенти застосували магію ілюзій до партій зараженого зерна в навколишній сільській місцевості, щоб ті виглядали нормально. Мені потрібно, щоб ти знайшов приховане зерно та застосував цей «Арканічний руйнівник» до цих партій. Люди Артаса шукають заражене зерно, і, коли ілюзія зникне, вони повинні швидко його знайти.",  -- db:12952
[564813791] = "Не думаю, що ми можемо дозволити собі упустити нагоду завоювати прихильність «червоного флоту». З огляду на майбутні битви, мати їх у союзники було б безцінним.",  -- db:12953
[600395990] = "<Командир перериває свій виклад, обертається і пильно дивиться на тебе, оцінюючи тебе з голови до ніг.>$B$BМені знадобиться хтось такий, як ти, $c.",  -- db:12958
[61882042] = "Так, $c, що це таке?",  -- db:12960
[480452314] = "Радий знову тебе бачити, $N.$B$B. Прийшов повторити тактику боротьби зі Скажем?",  -- db:12961
[148246890] = "Кохана, ці туфлі просто неймовірні!  Я кажу це буквально.  Кого ти вбила, щоб їх дістати?",  -- db:12963
[626712193] = "Привіт, бачу, у тебе є кілька жетонів «Пивного фестивалю». Якщо хочеш, у мене ще залишилося кілька речей з «Пивного фестивалю», які я можу продати.",  -- db:12968
[534726876] = "$N, радий тебе бачити!$B$BАбо, може, ми зустрічаємося вперше?$B$BЗараз я перебуваю в стількох місцях і часових вимірах, що іноді мені важко в усьому цьому розібратися.",  -- db:12976
[214703810] = "Колись я покинув поле бою, щоб розібратися з проблемами вдома, у Вестфолі. Здається, це було ціле життя тому. Дякую Світлу, що Дефіаси більше не становлять загрози.$B$BМи тут, далеко від дому, але якщо ми не виграємо цю битву, Вестфолу, куди можна повернутися, може й не залишитися.",  -- db:12982
[84049029] = "Мої маги-чарівники вже в дорозі і незабаром прибудуть.$b$bЗверніться до мене знову, коли вони повернуться,",  -- db:12990
[720108730] = "Вибачте, $r, але я зараз займаюся службовими справами і мене не можна відволікати.$b$bБудь ласка, вибачте.",  -- db:12991
[692189038] = "Молодці! Артас тепер знає про заражене зерно у Стратхолмі й збирається розпочати винищення. Однак щось все ще не зовсім гаразд. Я відчуваю в цій часовій лінії чужу присутність, окрім нас, а це означає, що «Нескінченний Драконячий Політ» десь тут.",  -- db:12992
[759972777] = "Я не знаю, і це мене турбує. Я зроблю все, що в моїх силах, аби знайти «Нескінченних». А тобі зараз потрібно приєднатися до армії Артаса й триматися поруч із ним.",  -- db:12993
[454358527] = "Ну, ти, звісно, не підпишеш жодних документів про вступ до лав армії, але тобі доведеться битися пліч-о-пліч з ним. Ти повинен переконатися, що Артас знищить Стратхольм і переможе Мал’Ганіса. Без Утера та Джейни йому знадобиться будь-яка допомога, яку він зможе отримати. Якщо ти поговориш з Артасом, він доручить тобі знищити війська Мал'Ганіса. Продовжуй виконувати завдання, поки я не з'ясую, що відбувається з «Нескінченними». Я зв'яжуся з тобою знову, коли дізнаюся більше.",  -- db:12994
[464429882] = "Удачі та бережіть себе. Ось уже йдуть Утер та Джайна.",  -- db:12995
[951193615] = "Були часи, коли я виривав тобі серце лише для того, щоб побачити вираз твого обличчя...",  -- db:12999
[228582006] = "Гей, друже!$b$bРадий знову тебе бачити... $N, так? Так, так, звичайно.$b$bМи з тобою станемо справжніми друзями. Дракуру знає такі речі.$b$b<На розфарбованому обличчі троля повільно розпливається посмішка.>",  -- db:13001
[553550838] = "Ой, чувак!$b$bЦе не те, на що схоже. Ну, може, й так...$b$bЦе складно.",  -- db:13011
[452668695] = "Ой, чувак! Я тебе знаю?$b$bАаа, так, Прігмон ніколи не забуває обличчя.$b$bТи... за мною стежиш, чувак? Бо що б там не було, Прігмон цього ніколи не робив!",  -- db:13012
[243699387] = "Вітаю, $r.$B$BЯкщо ви бажаєте допомогти в обороні храму, будь ласка, зверніться до лорда Афрасастраша, який перебуває всередині.",  -- db:13018
[355613269] = "Ласкаво просимо до мого табору, $r.$b$bЗовні вона не виглядає особливо вражаюче, але поки що вона тут, як вдома.",  -- db:13019
[457643215] = "Ми з містером Флоппі пішли на прогулянку, але потім заблукали, і мені було дуже страшно, бо там були вовки, знаєте, і вони нас переслідували, але потім я побачила цю вежу, і ми з містером Флоппі сховалися тут, а вовки зрештою відійшли через деякий час, і це було жахливо, і тепер ми не знаємо, як повернутися додому.",  -- db:13023
[279247951] = "Гадаю, вам краще піти, $g містер:міс;. Ви лякаєте містера Флоппі.",  -- db:13024
[943648618] = "Війська Плеті насуваються на нас.  Не втрачайте духу і продовжуйте боротися!",  -- db:13026
[668452259] = "Ми мусимо чинити опір!  Зберіться духом!  Спалюйте цю огидну чуму, де б ви її не знайшли!",  -- db:13028
[416560404] = "Привіт, $c!$b$bСподіваюся, ти не проти трохи попрацювати. Нам тут дуже знадобилася б допомога.",  -- db:13030
[639028238] = "Вітер і дерева шепочуть про невидимі неприємності. Земля виглядає здоровою, але тут відбувається набагато більше, ніж здається на перший погляд.",  -- db:13031
[49152885] = "Шкури для Орди, друже!  Тільки найкраще для наших військ!",  -- db:13033
[182002740] = "Щось перекусити в дорогу?  А може, щось освіжаюче, щоб насолодитися під час перегляду поєдинків?",  -- db:13034
[303240080] = "Вороги наступають на нас з усіх боків, і всі старійшини говорять про те, щоб покинути цей пост. Я вважаю, що ми повинні залишитися й битися, як справжні воїни.",  -- db:13035
[219630978] = "Я називаю її «Дух Гномерегана». Хіба вона не красуня? Без твоєї допомоги її б ніколи не відреставрували.",  -- db:13042
[880962228] = "У нас тут справжня халепа.",  -- db:13045
[806393469] = "Дякую Світлу за тебе!",  -- db:13047
[900193443] = "Привіт, $c. У нас тут зараз у розпалі битва.",  -- db:13047
[998519721] = "Що ти тут робиш?",  -- db:13047
[261836879] = "Хіба ти не $N? Я чув, що ти помер.",  -- db:13047
[797542861] = "Пиши коротко... тут йдуть запеклі бої. Мені треба зберігати пильність.",  -- db:13047
[871466555] = "Ти — новобранець? Це ж не стандартна броня.",  -- db:13047
[320925149] = "О, чудово, підкріплення!",  -- db:13047
[473726716] = "У тебе є повідомлення для мене?",  -- db:13047
[776626824] = "Ой... Я відчуваю себе розбитою...",  -- db:13060
[409189365] = "Не заважай мені, $c!  У мене тут аж два казани з бурхливим напоєм, і я мушу переконатися, що вони мають ідеальний смак!$B$BЯкщо ні, то майстер Корен Дайрбрю зніме з мене шкіру й зварить мене!",  -- db:13061
[163541861] = "Стає все цікавіше!  Це справді піднімає настрій!  І, $N, мушу сказати, ти дуже стильно одягаєшся, $gfellow:lass;!",  -- db:13063
[333993826] = "Так, $gsir:ma'am;, це справді чудовий напій!  Справді чудовий напій!",  -- db:13063
[523063137] = "Давайте заспіваємо пісню!$B$BBrew, brawl,$BBrew, brawl!$BA Я обираю життя Темного Заліза!$B$BHа-ха!  $N, ти мені подобаєшся!",  -- db:13063
[904211347] = "Так, на чому я зупинився?  А, так...  Отже, я сказав їй: «Але ти мені потрібна!  Ти мені потрібна!»... а вона просто розсміялася й поповзла геть!  Це чиста правда, $N.  Нага може бути такою жорстокою!",  -- db:13063
[956764924] = "Це класна штука!  Але трохи не вистачає смаку.  Думаю, я додам туди ще трохи часникового аромату...",  -- db:13064
[924571923] = "Ось це справді халепа.",  -- db:13070
[642105649] = "У будь-який інший день я б так не вчинив, але... Мені хочеться пити, а я ненавиджу пити наодинці.$B$BНа здоров’я!",  -- db:13074
[391504255] = "БУМ!$b$bЦе останнє, що я пам’ятаю...",  -- db:13077
[365210710] = "<зітхання>...$b$bМоже, хтось мені трохи допоможе?",  -- db:13078
[140416849] = "Не звертайте на мене уваги. Я просто старий чоловік, який чекає на старого... друга.",  -- db:13079
[243785931] = "Ооо, біль... просто нестерпний...",  -- db:13080
[653495259] = "Поспішай, $r.$b$bУ мене закінчується час.",  -- db:13081
[582117136] = "Швидше, $g брате : сестро;. Я тут протікаю...",  -- db:13082
[561241050] = "<зітхання>... Як думаєш, ми могли б вийти звідси, $c?$b$bЯ швидко втрачаю рідину!",  -- db:13083
[931434081] = "Що це таке? Хіба ти не бачиш, що я зайнятий?",  -- db:13089
[990673977] = "Слухай, скажи Швейцеру та Ройтау, що тут у нас усе під контролем. Їм не треба... Що?$B$BТебе не вони послали? То навіщо ти тоді марнуєш мій час?$B$BУ мене є робота!",  -- db:13093
[642953900] = "Вітаю, $r.$b$b, на жаль, прошу вибачити, але я зараз дуже зайнятий.",  -- db:13097
[345243921] = "Тут час має вирішальне значення, $n$. Чи готові ви пройти випробування?",  -- db:13098
[617069269] = "Ех, не треба було мені зголошуватися на посаду спеціаліста. Вони завжди просять нас робити неможливе!",  -- db:13118
[759918025] = "<Коли ви наближаєтеся, полонений кроколіск видає тихе гарчання.>",  -- db:13120
[426582998] = "Чудовий день для вилазки на природу, чи не так, $g, пане/пані?",  -- db:13121
[611005372] = "Бг'гррмл бргл брм!",  -- db:13134
[960066688] = "Випусти мене звідси, $r!",  -- db:13135
[756194557] = "Ви коли-небудь бачили таких селезнів, як тут? Це просто ідеальна здобич для полювання.",  -- db:13147
[118158151] = "Цей пост знаходиться під захистом, $r.$b$bВорог вже деякий час як витіснений з цієї території.",  -- db:13156
[566675023] = "Дякую, що визволили мене, $r.$b$bЯ досі трохи запаморочений від отрути. Гадаю, я залишуся тут, доки не відновлю сили.",  -- db:13157
[171718421] = "Швидко прийди до тями, нам треба рухатися далі.",  -- db:13177
[122426687] = "Зім'Торга здатна забезпечити нам певний рівень захисту, але вона значно ослабла через присутність Плетіння та дії драккарі.$B$BТепер нам з Ахунае доведеться подбати про решту наших оборонних заходів.",  -- db:13180
[236707156] = "Третій кільце охороняє хитрий маг-лорд Уром.  Він з’явиться самотній і беззахисний, але не дайте себе обдурити зовнішністю!  Уром — могутній чаклун, який керує цілою зграєю примарних істот.  Шукайте його нагорі.$B$BI може надати вам силу викликати дракона з Червоної Боротьби.  Зверніться до Етерноса або Вердіси, якщо ви бажаєте скористатися силою Бронзової чи Зеленої Боротьби.",  -- db:13237
[568098034] = "Найбільше випробування ще попереду.  Лей-Хранитель Ерегос — це Блакитний дракон неймовірної сили. Ви знайдете його, коли він літатиме над найвищим кільцем. $B$BПовна сила ваших драконів розблокована.  Використайте їхню силу, щоб перемогти Ерегоса!",  -- db:13238
[220339151] = "Ви відібрали контроль над Окулусом у військ Малігоса. Червоний полк у вашому боргу.",  -- db:13239
[788067737] = "«Бронзовий політ» у вас у боргу.",  -- db:13240
[860192837] = "«Green Flight» у вас у боргу.",  -- db:13241
[867229478] = "Рубінові дракони чудово справляються з пом'якшенням шкоди та захистом своїх союзників.$B$BЗа допомогою вміння «Пекучий гнів» вони можуть випускати струмені рідкого вогню, які перескакують від цілі до цілі, завдаючи з кожним стрибком дедалі більшої шкоди.$B$BЩоразу, коли рубіновий дракон отримує шкоду від атаки ворога, він отримує заряд ухилення.  Ці заряди можна використовувати для виконання серії маневрів ухилення, що дозволяють дракону протягом певного часу ухилятися від наступаючих атак і заклинань.",  -- db:13254
[609625424] = "Рубіновий дракон на повній потужності може застосувати здатність «Мученик», яка на короткий час захищає союзників, перенаправляючи всю ворожу магію на себе. Під час дії «Мученика» все ще можна виконувати маневри ухилення.",  -- db:13255
[495094350] = "Смарагдові дракони майстерно лікують себе, одночасно отруюючи ворогів.$B$BЗа допомогою «Висмоктуючої отрути» вони можуть висмоктувати здоров’я у своїх ворогів.  Повторне застосування цієї отрути може посилити ефект.$B$BЗа допомогою «Дотику кошмару» смарагдові дракони можуть зануритися у Світ Снів, перетворюючи частину своєї життєвої енергії на надзвичайно потужну атаку, яка ослаблює ціль, тимчасово зменшуючи її здатність завдавати шкоди.",  -- db:13258
[448945856] = "Смарагдовий дракон на повній потужності може застосувати здатність «Канал мрій», яка передає власну життєву енергію дракона союзникові, зцілюючи його. Здатність «Висмоктувальна отрута» можна використовувати для відновлення здоров’я, втраченого під час застосування цієї здатності.",  -- db:13259
[506335082] = "Ласкаво просимо до табору, $c.",  -- db:13261
[355094298] = "Подумай над тим, що ти побачив сьогодні, $n.$b$bМайбутнє вже визначено. Залишається лише вирішити, яку роль ти в ньому відіграватимеш, друже.",  -- db:13265
[593641696] = "Бегарістраш говорить правду: час спливає!$B$BПовна сила ваших драконів розкрилася.  Використайте їхню силу, щоб перемогти Ерегоса!",  -- db:13268
[91371164] = "Бегарістраш говорить правду; ситуація справді серйозна.  $B$BПовна сила ваших драконів розкрилася.  Використайте їхню силу, щоб перемогти Ерегоса!",  -- db:13269
[364700498] = "Не будьте занадто суворими до старого Насса. Він уже не такий молодий і витривалий, як колись.",  -- db:13271
[978029817] = "Проходьте далі. Тут нема на що дивитися.",  -- db:13289
[633634784] = "<Бладроуз дивиться на тебе з цікавістю.>$b$bНе можу не замислитися, чим саме ти заслужив таку увагу.$b$bБез образи...",  -- db:13290
[671042038] = "Будь ласка, поквапся, $N. Мені дуже боляче, а час спливає.",  -- db:13293
[971739093] = "Ми намагаємося підірвати цю стіну, щоб люди Віка могли працювати над новою сторожовою вежею в гавані та дорогою за нею, але цей безтолковий дурень скаржиться, що я витрачаю забагато пороху!$B$Блядь. Я займаюся підриванням ще з тих пір, як він ходив у підгузках. Якщо це ще довго триватиме, я виштовхну його в канал і сам закінчу всю цю кляту роботу!",  -- db:13301
[192567221] = "Як тільки цю стіну знесуть, ми почнемо будувати ще одну дорогу, що веде вниз до гавані Штормовію... але ця божевільна карлиця привезла стільки пороху, що його вистачило б, аби зрівняти з землею цілий квартал!$B$BI Не знаю, що собі думав майстер Алексстон, коли наймав її... Вона лається, злісна й уперта, як віслюк!",  -- db:13302
[984913191] = "«Скордж» — це пляма на цих незайманих землях.  Силою моїх творців я розчавлю під п’ятою кожну їхню стару кістку до останньої.",  -- db:13303
[249239120] = "Схоже, у тебе виникла та сама ідея, що й у мене. Ти, мабуть, у пошуках фруктів?",  -- db:13307
[366545410] = "Локен?! Це просто неприємно... Ми, можливо, й знешкодили залізних гномів, але готовий побитися об заклад, що десь ще є машина, яка випускає цілу купу цих залізних врикулів!",  -- db:13308
[631763697] = "Шукайте східну вежу для посадки цепелінів, що розташована за межами міста на південному сході.",  -- db:13311
[679594823] = "З цього причалу корабель «The Bravery» курсує між Штормвіном і Обердіном.",  -- db:13321
[372876714] = "Моя бідна літаюча машина. Вона не витримала аварії, і без запасних частин я ніколи не зможу її знову запустити!",  -- db:13322
[793262160] = "Незабаром, $n!$b$bНезабаром ти відчуєш справжню силу. Незабаром ти отримаєш нагороду за свою відданість і службу.$B",  -- db:13324
[161901756] = "Ласкаво просимо. Чи можу я запропонувати вам відпочинок або перекус?",  -- db:13328
[433086037] = "Чи подобається тобі новий дім, який я створив для своїх так званих поклонників?$B$BУ агонії смерті я прокляв їх усіх і затягнув за собою у цей особливий підземний світ, створений мною самим.$B$BГадаю, я буду насолоджуватися їхніми вічними муками, але насправді я прагну помститися своєму колишньому пророку!",  -- db:13331
[417100833] = "Ви прийшли, щоб щось купити в «Харгус», чи не так?",  -- db:13342
[141595216] = "Ще один прохач, який прагне отримати милість Короля Ліча?$b$bЛише гідні можуть отримати темні дари....",  -- db:13348
[255700681] = "Сподіваюся, архімаг оцінить те, через що мені довелося пройти, аби виконати свою частину угоди з Хеметом.",  -- db:13352
[76960977] = "Зараз тобі слід триматися ближче до Артаса!",  -- db:13353
[703956732] = "Картак приходить за м’ясом «великого язика». «Шалене Серце», подбайте, щоб його було вдосталь.",  -- db:13364
[864433316] = "Усе гаразд?",  -- db:13366
[85298764] = "Так?",  -- db:13366
[929279399] = "Приємно мати хорошого напарника на полюванні.",  -- db:13366
[92660612] = "Щось не так?",  -- db:13366
[683321568] = "Привіт! Як справи? У нас все добре... так, все добре-добре. Привіт!",  -- db:13367
[756631099] = "Ви коли-небудь спотикалися об власні ноги? Ми — так. Це трохи боляче. Ні, не варто так робити, це не весело. Ні.",  -- db:13367
[110467745] = "Привіт! Ти досить сильний і приємний, і все таке. Ти мені подобаєшся. Давай залишимося друзями, добре?",  -- db:13367
[810015725] = "Хочете, щоб ми вам у чомусь допомогли? У чому ми можемо допомогти? Ми добре вміємо допомагати.",  -- db:13367
[848123947] = "Я назавжди у боргу перед тобою, $N.",  -- db:13368
[264984583] = "Гарний день для польотів, чи не так?",  -- db:13375
[118931888] = "Я впізнаю справжнього майстра, коли бачу його. Ще раз дякую за те, що врятували мені життя!",  -- db:13376
[594518046] = "Поглянь, що ти накоїв, лицар смерті! Ти приніс славу Плеті!",  -- db:13382
[996080129] = "Випусти мене звідси, чувак!",  -- db:13390
[919509370] = "Ти ж не Скаурдж. Що ти тут робиш, чувак?",  -- db:13390
[730477158] = "Чому ж «Бич» дозволив тобі тут ходити, друже?",  -- db:13390
[90469501] = "Мені здається, ти заблукав, друже...",  -- db:13390
[218781318] = "Ти, Скорб, не бажаний гість у Зул’Драку!",  -- db:13391
[953592577] = "Зул’Драк належить Драккарі, чувак. І завжди належатиме!",  -- db:13391
[702984543] = "Ти, Скардж, тут провалишся, чувак.",  -- db:13391
[95442710] = "Наші люди винищать вас, «Скаж», до останнього!",  -- db:13391
[609109057] = "Відійди від мене, огидний Скаж!",  -- db:13391
[948201947] = "Як ти смієш! Забирайся з моїх очей!",  -- db:13396
[449608394] = "Мабуть, жоден справжній підлабузник зараз не займається балетом у своїх покоях.",  -- db:13396
[451499461] = "НІКОЛИ не вимовляй це ім'я в моїй присутності! Вважай це своїм єдиним попередженням!",  -- db:13396
[704725877] = "Я можу сказати, де його немає...",  -- db:13396
[913514013] = "Ймовірно, Хейган зараз займається прибиранням у своїй танцювальній студії, заваленій слизом та іншим сміттям.",  -- db:13396
[371057409] = "Це лише питання часу, коли чума охопить Нью-Авалон.",  -- db:13397
[810925925] = "У Файнеуса є те, що тобі потрібно, друже.",  -- db:13402
[378908442] = "$n! Я чекав на твоє повернення. Чому ти так довго затримався, друже?$b$bНастав час завершити перетворення «Блайтбладів».$b$bПриєднуйся до мене і стань свідком створення нашої армії!",  -- db:13422
[47334518] = "Це не зовсім те, на що я розраховував, але що ж... принаймні тут тепло.",  -- db:13431
[573895164] = "Одного дня Реджек стане могутнім воїном.",  -- db:13438
[702634614] = "Ці монстри вбили мого батька і викрали мою сестру. Вони за це поплатяться!",  -- db:13445
[511035247] = "Ласкаво просимо до моєї кухні! Тут ми готуємо одні з найкращих страв у Даларані.",  -- db:13449
[616088421] = "Сподіваюся, ти добре їм це даси. Давно вже час, щоб вони зникли.",  -- db:13451
[843334895] = "Я не вірю, що ти володієш достатньою гостротою розуму, щоб осягнути суть магії порталів.$B$BПроте ти можеш скористатися кристалом, що стоїть за моєю спиною, щоб телепортуватися до руїн під Далараном у Лісі Кришталевої Пісні.",  -- db:13455
[424602908] = "Як маг, ти належиш до обраного кола тих, хто вміє створити портал, щоб повернутися саме сюди.  Якщо ти готовий, я можу навчити тебе.$B$BІ пам’ятай, що ти завжди можеш скористатися кристалом, що стоїть за моєю спиною, щоб телепортуватися до руїн під Далараном у Лісі Кришталевої Пісні.",  -- db:13456
[98159964] = "Ласкаво просимо, друже, до перукарні! Зайшов підстригтися? Пофарбуватися? А може, щось інше?$B$BMи можемо доглянути за бородою, зробити пірсинг, змінити форму іклів і рогів, а навіть скорегувати риси неживих!$B$BСідай, і ми одразу візьмемося до роботи. Лише кілька монет відділяють тебе від нового, привабливішого «я»...",  -- db:13461
[734204372] = "Найбільше випробування ще попереду. Лей-Хранитель Ерегос — це Блакитний дракон неймовірної сили. Ти знайдеш його, коли він літатиме над найвищим кільцем.",  -- db:13468
[519966933] = "«Кам'яні зали» — підземелля 77–79 рівня в регіоні «Штормові вершини» — тепер доступне для тестування. Будь ласка, сформуйте повну групу перед телепортацією до підземелля. Камені зустрічі для цього підземелля поки що недоступні.$B$BЩоб покинути «Кам'яні зали», просто вийдіть через звичайний вихід усередині підземелля, і ви повернетеся сюди. Якщо ви загинете і відновитеся, вам слід телепортуватися назад від цього НПЦ.",  -- db:13469
[823468430] = "Що ти тут робиш так далеко? Тобі треба негайно повертатися до Стратхолма! Може, телепортувати тебе до Стратхолма?",  -- db:13470
[635118568] = "Знайди ті приховані ящики з зараженим зерном і застосуй до них свій «Таємничий дезактиватор»! Тоді Артас отримає докази, необхідні для того, щоб розпочати винищення мешканців Стратхолма.",  -- db:13471
[249833816] = "Що ти тут робиш? Артас зараз біля входу до Стратхолма, і ти мав би бути з ним! Біжи!",  -- db:13472
[904425045] = "Сімейства вихованців поділяються на три типи. Агресивні вихованці, такі як кішки, можуть завдавати шкоди, але не так добре її витримують. Витривалі вихованці, такі як черепахи, більше орієнтовані на захист і можуть відволікати увагу ворога, поки ви залишаєтеся на відстані. Хитрі вихованці, такі як павуки, поєднують в собі наступальні та оборонні здібності й особливо корисні на полях битв та аренах.$b$bУ міру накопичення досвіду ваш вихованець може вивчати нові таланти так само, як і ви, але трохи повільніше. Якщо ви коли-небудь захочете змінити таланти свого вихованця, просто поверніться до мене.",  -- db:13474
[173608120] = "Ти впевнений?$B$BКоли я витру з твоєї пам’яті знання про таланти, які ти опанував, назад дороги вже не буде.",  -- db:13475
[171734068] = "Дуже добре. Все готово.",  -- db:13476
[502964605] = "Саме тут я пожертвував усім, щоб звільнити свого батька. А тепер я прийшов, щоб знищити це...",  -- db:13485
[687677924] = "Ось, $n.$b$bА тепер, будь ласка, поверніть свою увагу до поточного завдання...",  -- db:13501
[534186517] = "Наші склади порожні.  Мені немає що продавати, доки ми не отримаємо нові поставки.",  -- db:13502
[158852] = "Оскільки тобі вдалося поповнити частину наших запасів, я можу знову взятися за приготування їжі.  Тож, чим я можу тобі допомогти?",  -- db:13503
[973392382] = "Чому всі дивляться на мене так, ніби це я розбив корабель?",  -- db:13506
[951104911] = "Хм... щось знайоме у твоєму обличчі, $r...  Дай мені хвилинку...$B$BAга-га! Вестфолл — ось звідки я тебе впізнав.  Ти ж $n!  Радий знову тебе бачити.  Але сподіваймося, що цього разу ти допоможеш нам довести справу до кінця.$B$BМи тут, далеко від Вестфолла, але якщо ми не виграємо цю битву, то, можливо, нам не буде куди повертатися.",  -- db:13510
[357774083] = "$N!  Я ледь впізнав тебе в твоєму новому вбранні.  У тебе все ще є та туніка... чи ти взяв шауси... а може, це був посох?   Не можу пригадати, це було так давно...$B$BЩо ж, я радий, що ти знову тут, щоб допомогти.  Нам знадобиться будь-яка допомога.  $N, якщо ти проявиш себе так само, як тоді у Вестфолі з Народною міліцією, у нас є шанс.$B$BЦе важкі часи, якщо ми не виграємо цю битву, Вестфолу, куди можна повернутися, може й не залишитися.",  -- db:13511
[871962976] = "З благословенням Світла та твоєю допомогою, $N, Дефіаси більше не становлять загрози.$B$BАле тут, нагорі, ми дуже далеко від Вестфолла, і якщо ми не виграємо цю битву, нам може не залишитися дому, куди можна повернутися.",  -- db:13512
[78307810] = "Привіт, друже.",  -- db:13519
[538318397] = "Так, Король Ліч впаде під нашим натиском. Ми здійснимо свою остаточну помсту.$B$BАле спершу ми подбаємо про те, щоб чума, відома як «Скарлетний напад», закінчилася раз і назавжди!",  -- db:13525
[170686036] = "Гаразд, але на твоєму місці я б прислухався, а не просто сліпо кивав головою на те, що почув.$B$BВсе починається, як і в усіх хороших історіях, зі зради. О, справа не в тому, що нас зрадили… зовсім ні. Король Ліч підняв нас, лицарів смерті, над усіма іншими.$B$BRато це ми зрадили його за допомогою верховного лорда Даріона Могрейна.$B$BУ фінальній битві в Каплиці Надії Світла на Землях Чуми, коли простаки були за крок від знищення, Тіріон Фордрінг допоміг Могрейну звільнитися від впливу Короля Ліча, який тримав у своїх лещатах його та всіх нас, хто був присутній.",  -- db:13526
[271629302] = "Оскільки Король Ліч утік, боячись Фордрінга, озброєного «Попелоносцем», нам вдалося без особливих зусиль відбити Ебон-Холд у решти військ Плеті.$B$BОднак це не вирішило конфлікт між нами та Скарлетним Хрестовим Походом.$B$BЯк «Покинуті» дізналися на власному гіркому досвіді, «Скарлет» ніяк не можуть відрізнити нас від «Плеті».$B$BМи мислимо самостійно, маємо власні мотиви, володіємо майже всіма рисами живих істот, а для них ми нічим не відрізняємося від бездумних рабів Короля Ліча.$B$BВони помилково вважають, що ми просто перевернемося на спину й прикинемося мертвими.",  -- db:13527
[421569396] = "<Верховний командувач пильно дивиться на тебе, перш ніж продовжити.>$B$BЯ саме збирався про це розповісти. Дійсно, коли верховна генералка Аббендіс висадила свої війська на Нортренді, вона змінила їхню назву на «Скарлетний Напад».$B$BНе минуло багато часу, як адмірал Бареан Вествуінд з’явився перед нею в Нью-Хертглені в Драконовій Пустці. Судячи з усього, вона його не чекала. Як і не очікувала, що він підірве її авторитет і відбере у неї повноваження.$B$BЙмовірно, ти причетний до її загибелі, але це не має значення. Після її смерті адмірал таємничо зник, і ми втратили його слід.",  -- db:13528
[898303719] = "Як я вже казав, ми втратили його слід, але я впевнений, що ти зможеш розібратися в цьому за мене. Я підозрюю, що він десь там, внизу, але мої шпигуни, які повернулися, не змогли визначити його місцезнаходження на острові.$B$B«Покинуті» з Веномспайта добре попрацювали, саботуючи Нью-Хертглен, але війська «Наступу», що перебувають там, — це загартовані в боях залишки тих, хто був у тому місці. На жаль, по дорозі вони підібрали краще спорядження, а також грифонів, відібраних у якихось дурнів десь.$B$BЯ намагаюся сказати, що це не буде прогулянкою по селу, $N, навіть для тебе.",  -- db:13529
[487321313] = "Ми почнемо вже за мить.$B$BI хочу чітко зазначити — ми тут не для того, щоб їх «розм’якшити». Ми тут не для того, щоб просто «залишити слід». Ми тут, щоб покласти край хворобі, яка називає себе «Скарлет Онслот».$B$BЯкщо ти не хочеш брати в цьому участь, якщо у тебе на це не вистачить сміливості, то краще відлітай зараз. Мені потрібна людина, яка буде з нами щодня, доки справа не буде завершена.$B$BЧи є ти тим $g чоловіком : жінкою;, $N?",  -- db:13530
[387220630] = "<Лорд-командувач викривляє обличчя в кривій посмішці, пильно оглядаючи тебе з голови до ніг.>$B$BСаме це я й хотів почути.",  -- db:13531
[265524625] = "Згадайте про всі ті страждання, яких «Скарлетс» заподіяли за ці роки. Тортури, фанатизм, вбивства.$B$BI не дозволить, щоб це тривало далі. А ви?",  -- db:13534
[757510393] = "«Хільдсміт» — це священне місце. Той, хто здобуде перемогу, отримає гарантію, що проживе все життя поруч із Торімом.",  -- db:13540
[926127220] = "Вітаю, $c. Я можу допомогти вам утримати ваших улюбленців у безпеці або знайти загублених вихованців.",  -- db:13557
[170072090] = "Ти стоїш перед майстром таємних мистецтв. Було б нерозумно кидати мені виклик. У моєму сліді залишилося чимало згорілих трупів.",  -- db:13573
[327824889] = "Моє життя й душа сповнені спогадів про нестерпну Орду. Минули часи смутку, відчаю та самопожертви. Гнів битви ніколи не покине мого серця!",  -- db:13574
[87874204] = "Що тут відбувається?$B$BТи прийшов поїсти, чувак? А може, навчитися готувати у найкращих, га?",  -- db:13581
[620417575] = "Шукаєте накидку?",  -- db:13583
[75720935] = "Вітаю, $c. Я можу допомогти тобі знайти зниклих супутників.",  -- db:13584
[104252511] = "Привіт! Може, хочете придбати рибальське спорядження або, можливо, взяти пару уроків?",  -- db:13591
[302203843] = "Радий знову тебе бачити, $N. Як я міг би коли-небудь забути того $g чоловіка : жінку, який врятував життя моїй сестрі?",  -- db:13609
[132679146] = "<Розвідник «Морознородних» намагається підвестися на ноги, коли ти наближаєшся, але спотикається й знову падає на землю, притискаючи руку до рани в боці, яка, судячи з усього, завдає йому сильного болю.>",  -- db:13611
[852071831] = "Не думаю, що це станеться, $G lad:lass;. Я втратив багато крові... Я нізащо не встигну повернутися.",  -- db:13612
[356641181] = "З долини вилітала зграя гарпій. На чолі їх очолювала велика гарпія на ім’я Сірана… Мені нікуди було втекти. Вони вже давно не були такими агресивними… Я цього не очікував… Я втратив пильність… Це моя власна провина.",  -- db:13613
[287987220] = "Трохи запізно... для цього... $G lad:lass;.$B$B<Розвідник з Роду Морозу кашляє кров'ю на сніг.>$B$BПокличте... ту дівку, що тут керує...$B$B<Розвідник з Роду Морозу знесилено падає, видихаючи останній подих.>",  -- db:13614
[172961839] = "Ласкаво просимо до нас, $c.",  -- db:13637
[101423793] = "Перш ніж ми почнемо, послухай, що я хочу тобі розповісти про нашого ворога. Ти ж не хочеш опинитися неготовим, коли ми будемо розбивати «Скордж» на полі бою.",  -- db:13640
[892559879] = "<Бранн дивиться на тебе з надією.>",  -- db:13641
[184298776] = "Уявіть собі, скільки мудрості та знань приховано в Ульдуарі. Можливо, саме там зберігаються таємниці самого життя!",  -- db:13642
[265739304] = "Боктар вважає цю аварію прикрою подією, але я вважаю, що нам слід винести з неї якийсь урок.",  -- db:13646
[278158720] = "Ми влипли по вуха, $r! Слідкуй за спиною!",  -- db:13658
[103529214] = "Рада бачити тебе, Сестро-воїнко. Я можу допомогти тобі знайти зниклих товаришів.",  -- db:13661
[226383006] = "Ходи, сестро-воїнко.$B$BНаїжся, виспись, щоб ти могла битися з усією своєю силою!",  -- db:13663
[724648280] = "Я можу сам про себе подбати, $N.",  -- db:13673
[230365223] = "Тепер ти чемпіон, друже! Як гадаєш, чи вистачить тобі сил захистити свій титул?",  -- db:13680
[610816580] = "Повернімося до роботи, поки наглядач нас не побачив.",  -- db:13682
[499504305] = "Гей, я тебе впізнаю! Мабуть, саме тобі я маю дякувати за те, що опинився тут. Той випадок з телепортацією — найкраще, що зі мною коли-небудь траплялося.$B$BЯкщо ти знову опинишся в Бореанській тундрі, передай моєму дублю — цьому доброчесному ботаніку — що я вже неабияк просунувся в житті!",  -- db:13695
[58668311] = "Я більше не навчаю Лицарів Смерті, бо мені набридли тупі новачки та їхні нескінченні запитання.$B$BА тепер забирайтеся геть.",  -- db:13699
[503009946] = "Чим я можу вам допомогти?",  -- db:13702
[55064195] = "Вітаю, $N. Це майстерня Хранителя Міміра.",  -- db:13703
[953853965] = "Яке знакове відкриття! Королівське товариство аптекарів роками працювало над розгадкою таємниць чуми Короля Ліча, і мені нарешті це вдалося!$B$BНезважаючи на цей переломний момент в історії, попереду ще так багато відкриттів. Мені ще треба провести чимало експериментів... знайти піддослідних...$B$BПринаймні мені не доводиться турбуватися про некрополі Плеті. Цю проблему вирішує Альянс. Тож у мене залишається чимало часу, щоб заглибитися в таємниці чуми й розкрити все, що зможу.",  -- db:13731
[560803484] = "Чим я можу вам допомогти?",  -- db:13734
[729257229] = "Чим можу вам допомогти?",  -- db:13737
[505486846] = "Я не довіряю тобі настільки, щоб говорити про такі речі.$b$bТи повинен поважати випробування, які випали на долю нашого народу, тягар, який ми несли...$b$bМожливо, якби ти приніс велику честь Дун-Ніффелему, я був би схильний поділитися з тобою знаннями нашого народу.",  -- db:13748
[293011959] = "Доброго дня, $r. Чим я можу вам допомогти сьогодні?",  -- db:13759
[786084211] = "Вибач, друже. Тільки уповноважені офіцери Орди можуть дати дозвіл на придбання транспортного засобу.",  -- db:13761
[74357667] = "Радий знову тебе бачити!$B$BКороль Стормхарт повідомив мені, що на деякий час відлучається... Схоже, до нього повернулися похмурі спогади, і тепер йому треба з кимось розрахуватися. Він дуже наполягав, щоб ми не супроводжували його, тож ми, як завжди, поважаємо його бажання.$B$BНа цей час я взяв на себе відповідальність за наш клан. Звісно, ти й надалі завжди бажаний гість у нас.",  -- db:13764
[202129416] = "Ти не таунка. Чому ти прийшов на священні місця поховання наших воїнів?",  -- db:13776
[171393295] = "Погляньте на них... їм важливо лише перевершити одне одного.",  -- db:13777
[553009280] = "Розумієте, Торім не схожий на цих гарпій.  Він — гідна істота, що за своїм статусом наближається до божественного рівня.$B$BВін служив титанам як охоронець Ульдуара та Тераси Творців.$B$BТак було доти, доки його дружину, Сіф, підло не вбив його брат.",  -- db:13778
[869284224] = "Торім втратив розум. Він обрушився зі своїм гнівом на своїх найулюбленіших союзників — крижаних велетнів.$B$BЦе одна з причин, чому й донині ця земля роздирається війною між хільднірами та Синами Ходіра... і чому Торім сам вигнав себе до Храму Бур.",  -- db:13779
[935900850] = "Який мені діло до того, що ці вовчиці та крижані велетні щодня вбивають одне одного?$B$BНі, ні... Я хочу, щоб Торім вийшов зі свого заціпеніння й зібрав усіх своїх союзників, щоб відвоювати Ульдуар.$B$BЯкщо йому це не вдасться, світ розпадеться на шматки!$B$BІ, звісно, я нагороджу тебе як слід.",  -- db:13780
[672777811] = "Чоловіки — з ними не можна жити, без них теж не можна. Ну, можна, звичайно... але це просто дуже нудно.",  -- db:13783
[842573690] = "Ці шахти — жахливе місце. На щастя, я не планую тут довго затримуватися.",  -- db:13784
[350466401] = "Ведмеді — це прекрасні тварини. Дикі, сильні й запеклі в бою... зовсім як ми, сестро.",  -- db:13785
[486325568] = "Хтось мене кликав...?",  -- db:13788
[847944331] = "Привіт, привіт!",  -- db:13790
[86729745] = "Привіт, peach — раді бачити тебе серед нас!",  -- db:13792
[340836965] = "Ми виявили цих протодраконів у Храмі Бронзових Драконів у Драконовій Пустці. Ми одразу зрозуміли, що вони — наші родичі, нащадки наших предків з давніх часів.$B$BВибачте, $c. Ви, мабуть, збентежені. Я — Пенумбріус із бронзового драконячого полку. Я прийняв цю форму з міркувань зручності. У людській подобі набагато легше спілкуватися та жити серед смертних.$B$BЧим я можу тобі допомогти?$B",  -- db:13797
[703062899] = "Привіт, $n! Чим я можу вам допомогти сьогодні?",  -- db:13798
[940696122] = "Старійшину Скайвардена можна знайти поблизу «Молота Агмара» у Драконовій Пустці.",  -- db:13816
[689394467] = "Старійшину Чоган'гаду можна знайти на Вершині Утгарда.",  -- db:13819
[854225282] = "Старійшина Лунаро перебуває біля руїн Тетис у Грізлі-Гіллз.",  -- db:13820
[876345164] = "Старійшину Кіліаса можна знайти всередині фортеці Драк'Тарон.",  -- db:13823
[729901284] = "Старійшина Фаргал оглядає Фростхолд у Штормових Вершинах.",  -- db:13828
[101247028] = "Ми не можемо дозволити Орді використати приховані таємниці Берега Предків проти нас. Чи приєднаєтеся ви до наших хоробрих воїнів там?",  -- db:13833
[232569034] = "Ми не можемо дозволити Альянсу використати проти нас таємниці «Намиста Предків». Чи приєднаєтеся ви до наших хоробрих воїнів там?",  -- db:13834
[508692194] = "«Флешверкс» — це серцевиною виробництва гулів, потвор та плотських гігантів «Скорбі». Якщо нам вдасться його знищити, Король Ліч буде значно ослаблений.",  -- db:13838
[875045766] = "Що вам потрібно?",  -- db:13841
[349822420] = "Ми служимо Торіму, сестро.",  -- db:13843
[912848482] = "Завжди приємно зустрічати таких героїв, як ви, на цій занедбаній землі. Чи можу я чимось вам допомогти?",  -- db:13844
[320954442] = "Звичайно! Іди з благословенням Елуни.",  -- db:13847
[713709454] = "Ми не повинні втрачати цілеспрямованість. Небезпека, пов’язана з тим, що ми можемо загубитися в миті, може поставити нас під загрозу. На жаль, солдатам потрібна перерва від цього божевілля.$B$BB Насолоджуйся перемогою, $N. Якби не ти, ми, можливо, втратили б «Авангард».",  -- db:13851
[713980175] = "Те, що я зараз роблю для Срібного Хрестового Походу, слід розглядати лише як виконання обов’язку. Як плату, якщо хочете. Верховний Лорд визволив мене з лап Короля Ліча і відкрив перед нами шляхи до спасіння. Однак слід розуміти, що наші методи різняться — і то суттєво. Я та Лицарі Чорного Меча допоможемо Срібному Хрестовому Походу закласти основи в Ледяній Короні, а потім наші шляхи розійдуться. Оплата здійснена в повному обсязі.$B$BA Нас чекає інша доля.",  -- db:13856
[299485353] = "Немає сумнівів, що ці хрестоносці є джерелом великого дискомфорту, $g брат:сестра;. Але що таке жертва без болю? Ти був зі мною в Каплиці Надії Світла. Ти бачив, як було принесено багато великих жертв. Зараз ми тут, щоб розрахуватися з Верховним лордом. Повністю відшкодувати його жертву.$B$BЯк тільки «Срібний хрестовий похід» закріпиться в стінах Ледяної Корони, ми вирушимо далі. На нас чекає інша доля.",  -- db:13857
[327166343] = "Захоплення Вершини хрестоносців — це лише перший крок у довгому й небезпечному шляху. Попереду ще багато роботи, перш ніж ми зможемо штурмувати Цитадель Льодової Корони.$B$BЦе стане можливим лише за допомогою тебе та таких, як ти, герою.",  -- db:13896
[398796972] = "Молот Оргріма готовий завдати удару в Лідовій Короні. Кращого носія ви не знайдете.",  -- db:13902
[354679093] = "Єдина причина, через яку ти досі живий, — це моя цікавість.",  -- db:13905
[549576681] = "Що б ти не збирався попросити, зроби це швидко.",  -- db:13908
[327192786] = "Далі ми самі розберемося, ти цілком заслужив перепочинок після цієї битви.",  -- db:13910
[560346224] = "Що це таке?",  -- db:13911
[885966589] = "«Срібний Світанок» координує боротьбу проти Плеті в Каплиці Надії Світла у Східних Землях Чуми. Зверніться туди за вказівками.",  -- db:13915
[716026374] = "Багато хто загинув у Вальгалі, і їхні тіла є свідченням сили наших традицій.$B$BЧи будуть твої кістки також розкидані по цьому місцю честі та битв, $N?",  -- db:13918
[657993867] = "Я мав би вбити тебе тут же, $r!$B$BПродовжуй свою безглузду балаканину, а потім забирайся геть!",  -- db:13919
[950323329] = "Ти ще не довів, що гідний кинути виклик у Вальхалі, $N.$B$BПовертайся, коли заслужиш собі ім’я.",  -- db:13921
[640779262] = "Е-е-е... Не... переймайся мною.$b$bЯ... закінчений...",  -- db:13930
[864157035] = "Е-е-е... Не... переймайся мною.$b$bЯ... закінчений....",  -- db:13930
[134847242] = "Збирали... інформацію... про Плеть.$b$bЗ’явилися війська Альянсу...$b$bМи сховалися — чекали, поки вони атакують ворота... а потім атакували їх з тилу.$b$bЗатиснуті між нами... і Плетью... це виявилося для них занадто...$b$b$g Брат:Сестра;... це було... чудово.",  -- db:13931
[876888670] = "Я віддав усе, що мав... за Орду...",  -- db:13935
[587040199] = "Чемпіоне $N, радий знову тебе бачити.$B$BТи повернувся до Вальгали, щоб допомогти другові в його випробуваннях?",  -- db:13946
[556524180] = "Зачекай, $g брате:пані;....$b$bЩе одне...",  -- db:13948
[969838584] = "Молодці! Артас благополучно вирушив до Нортренда!",  -- db:13950
[446531846] = "«Флешверкс» більше ніколи не будуть створювати солдатів для армій Короля Ліча.",  -- db:13978
[906640849] = "Будь ласка, дотримуйтесь законів Даларана, поки ви тут, незнайомцю.$B$BВи заблукали? Можливо, я можу допомогти вам щось знайти?",  -- db:14014
[811361182] = "«Бич» треба зупинити за будь-яку ціну. Ми не можемо дозволити їм виставити армію, яку вони тут формують.",  -- db:14028
[404819474] = "Наш шлях — священний. Ми краще оберемо смерть, ніж зрадимо Торіма і приєднаємося до таких, як Король Ліч.",  -- db:14033
[66566961] = "Будь ласка, $r.$b$bВідпусти мене...",  -- db:14035
[177501098] = "Не думай, $c.$b$bПросто... зроби це....",  -- db:14035
[562359910] = "Передайте моїй родині...$b$bМої останні думки були про них...",  -- db:14035
[843602266] = "Відпусти мене... Благаю тебе...",  -- db:14035
[101393707] = "Зроби це, $c... А потім... помстися за мене!",  -- db:14035
[571202811] = "Будь ласка, $r...$b$bНе залишайте нічого, що «Покарання» могло б воскресити!",  -- db:14035
[729109204] = "Мені важко повірити, що «Культ» був настільки недбалим, що залишив це тут.",  -- db:14037
[663452829] = "Чим я можу допомогти?",  -- db:14040
[571251512] = "Чим я можу вам допомогти?",  -- db:14041
[558493339] = "Доброго ранку!",  -- db:14042
[418511825] = "Чи є щось, за що ви могли б мені заплатити?",  -- db:14043
[345557976] = "Повітряна битва розгорається неподалік, $n.  І ми, і Орда відправляємо бомбардувальники в район «Бомбардування» та «Долину втраченої надії».  Чи приєднаєтеся ви до бою?",  -- db:14046
[40416866] = "Чи готовий ти, $N, розпочати штурм і відвоювати Підмісто для Орди?",  -- db:14050
[109863825] = "Елементи супроводжують нас у повній силі, $N. З їхньою допомогою ми зробимо все, що в наших силах, аби зупинити Варіматраса та Путреса! ЛОК’ТАР ОГАР!",  -- db:14051
[92798322] = "Ой, Боже! Говори тихіше, $N! Що? Ти хочеш, щоб нас убили?!$B$BЗвісно, я знаю, хто ти! Хто в Альянсі не знає ім’я $N?!$B$BSкажи, що думаєш про мій джампбот? Він створений за мотивами дизайну мехагнома. Стрункий і аеродинамічний!",  -- db:14052
[801482437] = "Ой, ой, ой! Тихіше, $N. Тихіше!$B$B<Бласт озирається.>$B$BМи ж не хочемо, щоб ті холодні врикули нас помітили, правда?$B$BЯк тобі мій стрибун-бот? Я зробив його на зразок мехагнома. Класно, еге ж?",  -- db:14053
[31648142] = "Нас чекає нелегкий шлях. Якщо ти сильний, залишайся тут, доки один із моїх загонів не буде готовий вирушити до Імірхейма. Їм знадобиться будь-яка допомога.",  -- db:14055
[381338488] = "Ну ти й потворний! Хоча це ще не означає, що ти не вмієш битися.$B$BОдин із моїх загонів незабаром має бути екіпірований і готовий до виходу — ставай у шеренгу зі своєю жалюгідною дупою й підіймайся разом з ними!",  -- db:14061
[530305372] = "Змагання на рейтинговій арені поновляться через $6318d.$B$BМайбутні чемпіони вже активно відточують свої навички та збирають найкраще спорядження. А ви будете готові?",  -- db:14062
[579672283] = "Цей портал веде до Печер Часу, що знаходяться глибоко під землею у далекому Танарісі.$B$BОднак, доки ти не станеш сильнішим, я мушу попросити тебе не вирушати туди.",  -- db:14066
[944623655] = "Я відчуваю запах пороху від усіх цих бомб і ракет!  Хочеш вийти туди й долучитися до веселощів?",  -- db:14067
[490347326] = "Голоси розмовляють зі мною.",  -- db:14068
[422322671] = "Я мушу підкоритися.",  -- db:14068
[650393677] = "Тобі треба звідси втекти, поки це не торкнулося й тебе!",  -- db:14068
[344075163] = "Це всюди навколо нас. Це в моїй голові!",  -- db:14068
[396019469] = "Сароніт... у ньому щось є!",  -- db:14068
[956934998] = "Тут щось є. Це в скелях і в землі!",  -- db:14068
[418961632] = "Я мушу звідси вибратися! Ти можеш мене визволити?",  -- db:14068
[612935612] = "Чи чуєте ви, як це звучить у вашій голові?",  -- db:14068
[771621325] = "Ми все ще готуємося. Нам ще знадобиться деякий час, щоб бути готовими.",  -- db:14069
[624306200] = "Ми вже майже готові до відправлення. Дайте нам ще трохи часу, щоб завершити підготовку.",  -- db:14070
[442436599] = "Під час своїх подорожей я дізнався рецепт плаща «Wispcloak».$B$BCей плащ — це епічний плащ для заклинань, який можна обміняти і який надає витривалість, силу заклинань, інтелект та швидкість відновлення мани.   Я шукаю гідну людину, якій можна було б передати цей рецепт.$B$BТой, хто пройшов усі звичайні підземелля Нортренда та отримав досягнення «Майстер підземель Нортренда», буде гідним дізнатися рецепт «Плаща вітру».",  -- db:14072
[564999539] = "Я відважився відправитися в темні куточки і дізнався рецепт пошиття «Плаща Смертельного холоду».$B$BCей плащ — епічний предмет для чарівників, який можна обміняти і який надає силу заклинань, швидкість та шанс критичного удару.   Я шукаю гідну людину, якій можна було б передати цей рецепт.$B$BТой, хто виконав більшість квестів у Нортренді та отримав досягнення «Знавець Нортренда», буде гідним отримати рецепт плаща «Холод смерті».",  -- db:14074
[403294396] = "Оскільки ти — досить досвідчений кравець, можу сказати, що знаю кілька особливих рецептів.   Я знаю рецепти як «Плаща Віспклока», так і «Плаща Смертельного холоду».",  -- db:14076
[921302524] = "Вітаю, $c.$B$BКоли Орда захопить фортецю Вінтерграсп, я відкрию портал для тих, хто бажає туди потрапити.$B$BНаступна битва розпочнеться в $3975w:$3976w$3782w:$3784w$3785w.",  -- db:14084
[957382132] = "Вітаємо, $c.$B$BАльянс тепер контролює фортецю Вінтерграсп. Якщо бажаєте, скористайтеся порталом.$B$BНаступна битва розпочнеться о $3975w:$3976w$3782w:$3784w$3785w.",  -- db:14085
[793291205] = "Вітаємо, $c.$B$BОрда тепер контролює фортецю Вінтерграсп. Якщо хочете, скористайтеся порталом.$B$BНаступна битва розпочнеться о $3975w:$3976w$3782w:$3784w$3785w.",  -- db:14086
[855235388] = "Привіт, друже.  Чим можу тобі допомогти?",  -- db:14087
[963711825] = "Привіт, зачекай секунду.  Бачу, у тебе немає власного літаючого маунта.$B$BТи, мабуть, не будеш особливо корисний іншим гоблінам тут, якщо не зможеш пересуватися.  Вони заплатили мені, щоб я позичав свої старі верхові тварини таким людям, як ти, — і це тобі нічого не коштуватиме.$B$BЦікаво?",  -- db:14088
[242068208] = "У мене є зачіпка щодо ключового каменю Норганнона, який охороняє вхід до архівів Ульдуара, але Титани розділили його на дві частини й сховали їх.$B$BOдин із фрагментів — оболонка ключового каменю — зберігається в Бібліотеці винахідників на північному узбережжі, на південь від самого Ульдуара. Перше, що вам потрібно зробити, — це відібрати у вартових бібліотеки уламки диска доступу.",  -- db:14089
[44248858] = "Коли йдеться про скарби, ніколи не варто поглядати на чуже барахло з наміром його привласнити. Крадене — це ж набагато приємніше, чи не так? Але безкоштовне — це безкоштовне, хай там як воно до цього дійшло!",  -- db:14090
[830213744] = "Я завжди готовий до гарної «знижки на три пальці». У крадіжці все залежить від спритності рук… а коли це не допомагає, тоді ти встромляєш щось гостре між ребер — і це теж залежить від спритності рук.$B$BВмілі руки цінуються більше, ніж стабільна зарплата, чуєш?",  -- db:14090
[874868065] = "Я не переймаюся ніякими Королями Лічів. Бачив, як багато великих шишок приходило й йшло — вони завжди щось налажали. Не минуло й багато часу, як з’являлася група, яка швидко відправляла їх у підручники історії. Цей — не виняток.",  -- db:14090
[293331321] = "Прийшов, щоб чимось допомогти?",  -- db:14115
[405738185] = "Секрет гоблінської інженерії полягає не в тому, щоб запобігти вибухам. Він полягає в тому, щоб спрямувати вибухи саме туди, куди потрібно.",  -- db:14118
[739760501] = "Я — Ксарантаур, Свідок.",  -- db:14119
[702079926] = "Хочете послухати історію?",  -- db:14119
[924733467] = "У вас є для мене якась історія?",  -- db:14119
[764154355] = "Ах так, я читав про тебе, $N.",  -- db:14119
[955503382] = "Я був одним із перших друїдів-тауренів, представником останнього покоління, яке навчав Шан’до Сенаріус, ще до приходу Легіону, до Великого Розколу, коли світ був ще молодим. До того, як усе змінилося.$B$BПоки мої побратими полювали на величезних звірів, я полював на історії. Саме ця жага, ця пристрасть до знань привела мене до мистецтва друїдів. Якийсь час ця жага вгамовувалася, коли я навчився розмовляти з деревами, скелями та звірами й слухав їхні історії.$B$BАле потім настав час, коли Сенаріус перестав ходити серед нас, і мої побратими почали забувати те, чого він нас навчив. Я ж не міг забути, і мені все ще потрібно було дізнатися більше про наш світ.$B$BТож я попрощався й вирушив за межі земель свого народу.",  -- db:14120
[184623445] = "Є щось, що треба затягнути, $r?",  -- db:14134
[251005657] = "Ми вже втратили тут кількох хороших людей. Я починаю сумніватися, чи варто приділяти цьому місцю нашу увагу.",  -- db:14137
[387203338] = "Незабаром розпочнеться фінальна битва, $N. Приготуйтеся!",  -- db:14142
[690270159] = "Ласкаво просимо, друже та союзнику «Драконівських зграй». Відпочинь тут, у наших залах.",  -- db:14149
[386126453] = "А, це ти, $N! Ласкаво просимо до нашого притулку. Відпочинь і наберіться сил — ти це більш ніж заслужив.",  -- db:14150
[645659055] = "Сьогодні в повітрі було жваво, еге ж, $N?  Може, тобі варто трохи перепочити, перш ніж знову вилітати.",  -- db:14155
[372085925] = "Обережно, $N.  А де твої мантії культиста?",  -- db:14159
[238583015] = "Ось і ти.  То ти готовий?  Як тільки почнемо, назад дороги вже не буде.",  -- db:14160
[477295996] = "Чи вистачить тобі, $r, сміливості зіткнутися з елітними драконами Малігоса у їхньому власному царстві?",  -- db:14169
[396993831] = "Вибач, друже. Тільки сертифіковані офіцери Альянсу можуть дати дозвіл на придбання транспортного засобу.",  -- db:14172
[324677273] = "Хіба це не просто чудово? Бачите, який тут потенційний прибуток?",  -- db:14177
[972793078] = "Хітрікс, Темний Володар, вривається до Вальгаласа з південного сходу!",  -- db:14177
[621900261] = "Привіт, маленький $r.",  -- db:14179
[94208345] = "Те, що щось працює, ще не означає, що його не можна покращити. Ти щось шукаєш, сонечко?",  -- db:14180
[864922532] = "Дозатор U.D.E.D. очікувано гуркоче на вас.",  -- db:14182
[571800344] = "«Смарагдова Мрія» перетворилася на небезпечне місце. Я дедалі більше турбуюся за тих, хто пожертвував своїм життям у Азероті, сподіваючись врятувати цей світ.",  -- db:14198
[558334518] = "Поспішай, $c.",  -- db:14204
[423351029] = "Так, малятко?",  -- db:14209
[975587522] = "Велика, блискуча, чарівна книга, яка допомагає створювати гліфи для заклинань та здібностей. Її завжди можна знайти поруч із інструктором з інскрипції в «Апотекаріумі».",  -- db:14213
[198494983] = "Не зволікайте, $r. Я втомився і не маю часу на приємності...",  -- db:14215
[345870460] = "Ось ти де!",  -- db:14218
[285352644] = "Ах, «Шляхетний сад». Так цікаво спостерігати, як інші відкидають свою гідність заради полювання на кольорові яйця. Хоча, треба визнати, вони дійсно оточені якоюсь дивною магічною аурою...",  -- db:14227
[757735091] = "Цукерки! Ось про що я й кажу; тільки б не довелося бігати по всьому місту, щоб їх знайти!",  -- db:14229
[836750514] = "Слухай, якщо люди хочуть бігати й копатися в землі у пошуках кольорових яєць, хто я такий, щоб їх засуджувати? Я все одно отримую частину прибутку від продажу фарби, та й цього року я вклав гроші в курей.",  -- db:14231
[446344935] = "Під час «Ноблгардену» ми святкуємо прихід весни. Це своєрідне освідчення в любові до життя та все таке інше.",  -- db:14234
[676619400] = "Ага, чувак, саме час радіти життю та весні. Ти вже зібрав багато яєць?",  -- db:14236
[226899078] = "Усе це свято — повна нісенітниця. Фарбовані яйця та «святкування життя» — фу.",  -- db:14237
[953798409] = "Вітаю, $c.$B$BКоли Альянс захопить фортецю Вінтерграсп, я відкрию портал для тих, хто бажає туди потрапити.$B$BЗараз триває битва. Поспішайте до Вінтерграспа та підтримайте наші війська!",  -- db:14240
[902930608] = "Вітаю, $c.$B$BКоли Орда захопить фортецю Вінтерграсп, я відкрию портал для тих, хто бажає туди потрапити.$B$BЗараз триває битва. Поспішайте до Вінтерграспа, щоб підтримати наші війська.",  -- db:14241
[763088160] = "Завдяки нашим новим союзникам-таункам Нортренд стане частиною Орди.",  -- db:14245
[308935637] = "Вітаю, $c!  Ласкаво просимо на борт «Cloudkisser».  Нортренд може виявитися дуже суворим місцем.  Сподіваюся, ти до цього підготувався.",  -- db:14248
[574458887] = "Тоді вам треба шукати Беніка Болтшира. Він знаходиться в самому центрі Дварфського кварталу, біля кузень.",  -- db:14249
[648774240] = "Гіпогрифи Веспристуса швидко доставлять вас до місця призначення.",  -- db:14254
[63731611] = "Саме Веспристуса ти шукаєш. Він пильнує за гіпогрифами, які прилітають і відлітають від підніжжя Телдрасіла.",  -- db:14254
[998669842] = "Після «Земль Чуми» та битви за Каплицю Надії Світла я не думав, що ми ще побачимо щось жахливіше.$B$BI Я помилявся.",  -- db:14286
[661376905] = "З підземних щурів виходить напрочуд смачне рагу.",  -- db:14313
[337668695] = "Вітаю, $g пане : пані;. Цей табір набагато кращий за той, що у мене був раніше.$B$BПриємно мати компанію. Вони були настільки люб’язні, що навчили мене деяким своїм бойовим прийомам, щоб я міг дати відсіч Орді.",  -- db:14315
[210638587] = "Вітаємо, $c. Наша позиція тут дещо вразлива, з огляду на концентрацію військ Орди на півдні.$B$Будь-яка ваша допомога буде дуже доречною.",  -- db:14316
[581634983] = "Я думав, що ніколи не позбудуся цього жахливого прокляття. Я тобі вдячний, незнайомцю.",  -- db:14319
[967121516] = "Прийміть це з моєю вдячністю, $c.",  -- db:14320
[453902580] = "Чим можу вам допомогти, $GSir:Dame;?",  -- db:14324
[768360886] = "Ти впевнений, що хочеш, щоб я допоміг тобі у битві проти Йогг-Сарона?",  -- db:14325
[662934981] = "Смертні, я в боргу перед вами за те, що ви звільнили мене від жахливої розпуси, яка панує в цьому місці. Хоча я ще не повністю оговтався, я можу допомогти вам у боротьбі з Йогг-Сароном.$B$Я можу наділити вас і ваших друзів «Швидкістю винахідливості», що збільшить ваш урон та швидкість руху. Крім того, я можу дестабілізувати матриці деяких форм життя на основі сароніту, зменшивши їхню швидкість атаки та заклинань.",  -- db:14334
[484956408] = "Що це таке, $c?",  -- db:14344
[643863119] = "Ой-ой, я й не думав, що колись матиму нагоду власноруч побачити Ульдуар. Та як же я міг відмовити, коли Бранн попросив мене допомогти фінансувати цю експедицію?!",  -- db:14362
[453129227] = "Я ніколи не думав, що нам вдасться втекти з тих спекотних джунглів! А тепер я — головний інженер цієї експедиції.",  -- db:14363
[588205455] = "Ці малята, можливо, і виглядають як брухт, але вони можуть мчати вперед, відкидаючи ворогів убік. Передній таран оснащено електроскопічним гіперконденсатором, що дозволяє йому випускати електричні розряди. $B$BНавіть башта була модернізована за допомогою протиповітряних ракет, що забезпечує їй безперечну перевагу над цими клятими руйнівниками.",  -- db:14364
[443929703] = "Ці красуні можуть метати вогонь, як ніхто інший. Ми навіть встановили додаткову гармату, гак-кішку та додали систему ручного впорскування палива. Якщо вам вдасться дістати рідкий пірит у механогномів, ви зможете використовувати його для метання вибухових речовин високої щільності або для турбо-прискорення своєї швидкості руху. $B$BПодивимося, чи зможуть ці дурні з Ліги Дослідників це перевершити!",  -- db:14368
[216204970] = "Добре, що ви, хлопці, з’явилися! Залізні гноми відтіснили нас сюди, і ми ледь утримуємо позиції. $B$BЩо ще гірше, вони почали підсилювати свої магічні захисні споруди. Якщо ми не атакуємо якнайшвидше, вони зможуть знищити нас в одну мить!$B$BНам вдалося відновити кілька облогових машин, руйнівників та мотоциклів, залишених експедиціями Альянсу та Орди, які були тут до нас. Однак усі наші пілоти загинули під час останнього штурму.$B$BТи повинен сісти за кермо цих машин і штурмувати ворота Ульдуара! $B$BBлагаю, $n! Ти — наша остання надія!",  -- db:14369
[567858077] = "Чим можу вам допомогти, шефе?",  -- db:14372
[571062534] = "Вітаю.",  -- db:14375
[6587008] = "Консоль виглядає старовинною, хоча на ній немає жодних ознак зносу чи руйнування.  Один слот, судячи з усього, призначений для великих круглих дисків.",  -- db:14383
[957792930] = "Ми здобудемо славу, коли виграємо цей турнір в ім’я Срібного Місяця.",  -- db:14392
[42591455] = "Король Магні очікує, що ми виграємо турнір і зробимо так, щоб він нами пишався. Ми не підведемо його.",  -- db:14396
[189326908] = "Коли турнір розпочнеться, усі побачать, як «Покинуті» вийдуть переможцями.",  -- db:14402
[255218940] = "Змагання будуть запеклими, але чемпіони Оргримара знищать усіх, хто стане нам на заваді.",  -- db:14403
[190175742] = "Ми змагаємося не лише за славу, а й для того, щоб вшанувати пам’ять наших предків і принести честь нашому народу.",  -- db:14404
[186690061] = "«Даркспірс» готові протистояти конкурентам і ворогам.",  -- db:14405
[548809844] = "Від імені «Сонячних розбійників» вітаю вас на турнірі. «Срібний хрестовий похід» доручив нам зареєструвати та підготувати тих, хто бажає взяти участь у змаганнях.",  -- db:14406
[270680838] = "Коли ти будеш готовий скласти іспит на звання «хороброго», я покличу одного з членів «Срібного хрестового походу».",  -- db:14408
[864186666] = "У цих залах приховані таємниці, які навіть не вкладаються в наші найсміливіші мрії.",  -- db:14420
[302087162] = "Для мене справжня честь мати можливість допомогти Бранну у дослідженні стародавнього Ульдуара.",  -- db:14428
[859713842] = "Бранн навчив мене всьому, що я знаю про подорожі.",  -- db:14429
[517885296] = "Радий бачити вас, $c.$B$BI навчає претендентів мистецтву кінного ближнього бою.",  -- db:14431
[290643879] = "Мішень для ближнього бою навчає аспірантів як атаці, так і обороні з коня.$B$BПідійдіть до мішені для ближнього бою та нанесіть їй удар «Прокол». Сила удару часто обертає мішень настільки сильно, що це може травмувати вас або вашого коня. Саме тут на допомогу приходить оборона.$B$BПеред атакою на мішень переконайтеся, що у вас є принаймні один рівень захисту, і продовжуйте накопичувати та оновлювати захист протягом усього тренування. Інакше ви цілком можете опинитися зкинутим з коня.$B$BТе саме стосується й реального бою верхи: збалансуйте атаку та оборону, завдаючи ударів «Укол» при кожній нагоді та підтримуючи свої шари захисту якнайкраще.",  -- db:14434
[892688757] = "Привіт, як справи?$B$BХочеш навчитися мистецтву «Штурму», $c?",  -- db:14436
[324263680] = "Ну що ж! Штурм верхи — це не просто розігнати свого скакуна до повної швидкості й кричати щосили... хоча це й є найцікавіше, хе-хе! Але завдання «Штурм» навчить вас тонкощам.$B$BA Удалий штурм — це, перш за все, правильний вибір відстані та вибору моменту. Не можна під’їжджати занадто близько, інакше не набереш достатньої швидкості. Але й занадто далеко теж не можна, інакше твій кінь втомиться! Щодо вибору моменту...$B$BПеред тим, як кидатися в атаку, переконайтеся, що у цілі для «Штурму» немає активного шару «Захисту». Якщо він є, скористайтеся «Пробивачем щита», щоб зробити її вразливою, і ТІЛЬКИ ПОТІМ кидайтеся в атаку!$B$BТе саме стосується і реальних боїв: намагайтеся збити захист супротивника перед тим, як кидатися в атаку!",  -- db:14437
[986365174] = "Ну що ж. Ще один $c, який прийшов, щоб навчитися мистецтву «Розбивача Щитів»...?",  -- db:14438
[770908461] = "Атака «Пробивач щита» на відстані проста для освоєння, але складна для досконалого володіння. Сама по собі вона може здаватися слабкою, але в поєднанні з «Ударами» та «Атаками з розбігу» «Пробивач щита» стає ефективним засобом для турнірних боїв.$B$BЗнайдіть ціль на відстані. Приділіть хвилинку, щоб зрозуміти дальність дії «Пробивача щита»... скільки місця вам потрібно і як далеко ви можете кинути спис.$B$BА що далі? Ну що ж. Почніть кидати і не зупиняйтеся, доки не проб’єте кожен шар захисту й не проколете вразливу ціль.$B$BЦя тактика стане вам у нагоді в реальному бою верхи: зруйнуйте захист супротивників… а потім розтрощіть їх!",  -- db:14439
[907296695] = "Все в свій час, друже. Скоро у мене для тебе з'явиться ще робота...",  -- db:14441
[945346288] = "Це справді так, друже. Наших запасів кристалів гнилі майже вистачить!",  -- db:14442
[340443125] = "Нехай некомпетентність Дармука більше не заважає нам! Терпіння, друже. Скоро у тебе з’явиться ще більше роботи...",  -- db:14443
[68137887] = "Тепер ти вже все знаєш, чувак! Готуйся... ми скоро атакуємо!",  -- db:14445
[309867716] = "Вибачте, $r, але придбати те, що я пропоную, можуть лише чемпіони Тандер-Блаффа.",  -- db:14458
[268168995] = "Геть звідси, $c!$B$BЛише чемпіони Андерсіті можуть придбати те, що я пропоную.",  -- db:14459
[419491912] = "Тільки чемпіони Оргримара можуть придбати те, що я пропоную.",  -- db:14460
[1803447] = "Тільки чемпіони Екзодару можуть придбати те, що я пропоную.",  -- db:14461
[506523625] = "Привіт!$B$BВибач, друже, але те, що у мене є, можуть купити лише чемпіони Гномерегана.",  -- db:14462
[19460743] = "Самамба, здається, ти потрапила не до того інтенданта!$B$BУ неї є лише те, що призначене для чемпіонів Сенджина...",  -- db:14464
[491279751] = "На жаль, придбати те, що я пропоную, можуть лише шановні чемпіони міста Сільвермун.",  -- db:14465
[998618294] = "Радий бачити тебе тут, $N.",  -- db:14473
[757485574] = "Щоб навчити «Веномхайда» і осідлати його, потрібна неабияка відданість справі.",  -- db:14474
[458772179] = "Вершники «Срібного хрестового походу» вірять у рівновагу та точність, вміло поєднуючи атаку й оборону.$B$BОднак, намагаючись збільшити дистанцію до вас, вони часто залишають себе вразливими для атак «Штурм».$B$BЗменшіть цю дистанцію за допомогою атаки «Штурм», перш ніж вони встигнуть зробити те саме, а потім застосуйте «Пробиття щита», обертаючись навколо них, щоб нанести ще кілька ударів «Прокол».",  -- db:14476
[680204251] = "Ти вже переміг одного з наших гонщиків сьогодні, тому я не можу прийняти твій виклик.",  -- db:14489
[321873387] = "Увімкнення вторинних оборонних систем призведе до знищення несанкціонованих форм життя за допомогою орбітальних установок.$B$BВи є несанкціонованою формою життя. Будь ласка, підтвердьте.",  -- db:14496
[294738042] = "Дозволено обхід заходів безпеки. Активовано допоміжні системи захисту.$B$BBДоступ до резервного вимкнення допоміжних систем можна отримати через окремі генератори, розташовані у вестибюлі.",  -- db:14497
[412644232] = "<Дитинча дивиться на тебе так, ніби намагається з’ясувати, чи ти його мати.>",  -- db:14527
[756364574] = "Жорстоке правління Короля Ліча принесло великі страждання всім мешканцям Нортренда, особливо дітям. Якщо ви є другом Оракулів або племені Френзіхарт із Шолазара, можливо, вам варто подумати про те, щоб на тиждень взяти під опіку сироту.",  -- db:14534
[317721054] = "Сироти, яких ми взяли до себе, походять із роздираємої війною долини Шолазар. Ви можете вибрати, кого доглядати: дитинча Оракула, що залишилося сиротою, чи цуценя Френзіхарта. Обидва будуть раді знайти нового друга, але ви зможете доглядати лише за одним із них.",  -- db:14537
[455413571] = "Ви це відчуваєте?$B$BУ День мертвих світ духів наближається до нас. Саме тому ми прикрашаємо могили наших дорогих покійних квітами, свічками та підношеннями: щоб знову їх привітати, хай навіть лише на деякий час.$B$BТож приєднуйтесь! Танцюйте зі мною! Давайте шанувати й вшановувати тих, кого ми втратили, у їхній примарній присутності, щоб вони могли їсти, пити, посміхатися й знати, що їх люблять.",  -- db:14543
[8238353] = "У День мертвих люди збираються на кладовищах, щоб відсвяткувати це свято разом із душами тих, кого вони втратили, та вшанувати їх пам’ять.$B$BЦі урочистості відбуваються на кладовищах будь-якого великого міста, де ви зможете готувати їжу, танцювати, одягати костюми та багато іншого.",  -- db:14544
[24766539] = "Приємно знову зустрітися з друзями та рідними, святкувати та ділитися спогадами про минуле.",  -- db:14552
[820843459] = "Напевно, ти хоч раз у житті був студентом, $c. Ти навчався у викладача і якимось чином почав його поважати, чи не так? Можливо, не як до людини, але принаймні як до того, хто знав більше за вас і був готовий вас навчати. Якщо ні, то уявіть собі...$b$bЩо б ви зробили, якби усвідомили, що ваш викладач, можливо, знає не так багато, як ви думали, і що, можливо, ви знайшли кращий шлях?",  -- db:14560
[365186398] = "Це жахливо! Я не повинен сидіти тут, ні на що не здатний, коли стільки всього треба зробити! Якби тільки моя рука не травмувалася там, у Нортренді... Але немає сенсу зациклюватися на цьому! Таху зрештою мене підлагодить і вилікує, а тим часом ми все одно будемо допомагати тут.$B$BТе, що ми не на фронті, ще не означає, що ми не можемо чимось допомогти.",  -- db:14561
[110181705] = "Ще одне нове обличчя? Дуже рада познайомитися. Я — Деліла.",  -- db:14562
[45399564] = "Якби мене тут не було, Зіппік загнав би нас прямо в Блафф. Ідіот.",  -- db:14614
[297942172] = "Привіт. У мене перерва.",  -- db:14617
[66526048] = "Привіт, сонечко. Цей цепелін, що тут стоїть, безкоштовно доправить тебе прямо до Громового Утвору. Кому потрібні виверни, коли є ми, гобліни, правда ж?",  -- db:14621
[955072850] = "На що ти там витріщаєшся, $r? Прийшов мучити засуджених?",  -- db:14623
[695438138] = "<Барон піднімає свої кайданки.>$B$BНу ж бо, $c. Ти мені довіряєш?",  -- db:14624
[593896671] = "Привіт, $N. Якщо ти шукаєш курси кулінарії, то потрапив у потрібне місце. Зазвичай у мене з’являється багато нових учнів, коли настає свято «Pilgrim’s Bounty».",  -- db:14627
[554214929] = "Якщо ви хочете дізнатися більше про традиційне свято «Pilgrim's Bounty», зверніться до будь-якої з господинь.",  -- db:14628
[815199549] = "Ви прийшли, щоб разом з нами відсвяткувати «Свято пілігримів»?",  -- db:14630
[381922901] = "Ласкаво просимо! Ви прийшли, щоб разом з нами відсвяткувати свято «Урожай паломників»? Будь ласка, сідайте за «Стіл достатку».$B$BСпробуйте все! Я впевнений, що ви знайдете щось до душі.",  -- db:14633
[928853928] = "«Щедрість паломників». Хм. Я можу зрозуміти бажання тауренів висловити свою вдячність і товариську солідарність вождю Орди, але що стосується Забутих?$B$BI Я думав, що вони вже давно відмовилися від таких сентиментальних традицій.",  -- db:14635
[123267621] = "«Свято паломників» — це час, щоб задуматися про власне щастя та поділитися ним із усіма, хто вас оточує.$B$BМи сподіваємося, що всі наші благородні союзники приєднаються до нас, щоб разом бенкетувати та святкувати.",  -- db:14640
[334729762] = "Цей свято так різко контрастує з типовою поведінкою людей. Хто б міг подумати, що такий невгамовно жадібний народ влаштує свято дарування та ділитися?$B$BПриємно це бачити. Дарнассус повинен докласти всіх зусиль, щоб підтримати та заохотити це.",  -- db:14641
[560900362] = "На «Стіл достатку» розставлено п’ять страв із «Урожаю пілігримів» — по одній перед кожним стільцем.$B$BСидячи на стільці, ви можете їсти цю страву скільки завгодно, а також передавати порції цієї страви на інші стільці. Насолоджуйтесь трапезою та діліться з друзями!$B$BЯкщо ви з'їсте достатню кількість будь-якої страви, ви отримаєте унікальні для неї переваги.$B$BКрім того, якщо ви з'їсте достатню кількість кожної страви, ви отримаєте «Дух ділитися»!",  -- db:14647
[165362848] = "Існують нагороди, гідні лише тих, хто здобув звання «Хрестоносця» — титул, що користується великою повагою як у «Срібного хрестового походу», так і серед усіх союзних народів.$B$BСам Тіріон доручив мені розшукати таких героїв і нагородити їх відповідними відзнаками.",  -- db:14661
[542285426] = "Ці звірі — дивовижні екземпляри. Тобі не варто соромитися того, що вони тебе перевершили.",  -- db:14667
[957958299] = "Чудово! Дай мені знати, коли будеш готовий до наступної спроби.",  -- db:14668
[297673710] = "Острів Завоювання багатий на цінні ресурси, і ми не можемо дозволити, щоб вони потрапили до рук Орди. Чи приєднаєтеся ви до бою?",  -- db:14670
[918225493] = "Острів Завоювання багатий на цінні ресурси, і ми не можемо дозволити, щоб вони потрапили до рук Альянсу. Чи приєднаєтеся ви до бою?",  -- db:14671
[718738017] = "Ми хочемо, щоб усім було весело на Brewfest.  Було б також добре, якби хтось це запам’ятав.$b$bЦі окуляри дають змогу кожному відчути, як це — бути п’яним, але без самого вживання алкоголю.  Одягніть окуляри — і ви п’яні!  Зніміть їх — і ви тверезі!$b$bХочете собі таку пару?",  -- db:14672
[127847016] = "Ти готовий битися за Орду, $c?",  -- db:14674
[573190173] = "Ти готовий битися за Альянс, $c?",  -- db:14675
[107070239] = "Молодець! Ти чудово впорався з усіма цими чудовиськами! Кажуть, наступне випробування має бути ще складнішим!",  -- db:14678
[563850348] = "Наразі нам вдається стримувати лорда Джараксуса, але ми не зможемо тримати його в полоні ще довго.",  -- db:14679
[552458042] = "Ти незабаром про це дізнаєшся. Ти готовий до наступного виклику?",  -- db:14680
[732400961] = "Це чудово, просто дай мені знак, коли потрібно зняти заклинання, що зв’язують.",  -- db:14682
[810056715] = "Протягом багатьох років я служив у цьому віддаленому куточку світу, вивчаючи місцевість і чекаючи свого часу. Нарешті наш час настав. Уся міць Оргримара тепер спрямована на Азшару — наші ворота до Ешенвейлу та панування над цим континентом. Ласкаво просимо на передову, $c.",  -- db:14690
[985377071] = "Ласкаво просимо до нашого магазину.  У нас є все, що вам потрібно... якщо вам потрібні товари для алхімії.",  -- db:14712
[288958659] = "Ні, це я тут інтелектуалка, і до мене не варто ставитися легковажно. Я могла б зварити цілюще зілля навіть із мийної води та кульбаб, хоча це я вам не покажу!$b$bУ будь-якому разі, якщо ви хочете щось придбати, зверніться, будь ласка, до Патрісії.",  -- db:14713
[901063672] = "Це було вражаюче виступ.  Але чи готові ви до наступного виклику?",  -- db:14737
[798397276] = "Сьогодні ти вразив усіх присутніх своїми вміннями на арені.  Настав час, щоб перед усіма тебе визнали чемпіоном турніру.",  -- db:14738
[797308014] = "Для виконання першого завдання вам потрібно осідлати бойового коня «Аргент».  Цих коней ви знайдете вздовж стін цього колізею.$b$bБудь ласка, осідлайте бойового коня, поговоріть зі мною, і тоді ми зможемо продовжити.",  -- db:14757
[71978751] = "Магнатаври не такі вже й дурні, як здається. Утримувати Гормока до настання його часу — завдання не з легких, але він зв’язаний настільки міцно, що ніякої небезпеки немає.",  -- db:14759
[392357345] = "Я піклуюся про цих створінь Гормока, оскільки він сам не може цього зробити. Я не повністю згоден із цією різаниною, але принаймні він матиме шанс битися.",  -- db:14760
[761673307] = "Єті — це люта й хитра істота, а цей екземпляр — один із найсильніших серед своїх побратимів. Ми підтримуємо його в стані сну, додаючи в їжу трави.$b$bПроте не думайте, що на рингу він буде млявим.",  -- db:14761
[548467833] = "Я приєднаюся до штурму Цитаделі Ледяної Корони, коли настане час нанести удар.",  -- db:14771
[755477827] = "Вітаємо, $c.$B$BНаразі «Орда» контролює фортецю Вінтерграсп, але битва вже розпочалася.  Поспішайте до Вінтерграспа та підтримайте наші війська!",  -- db:14777
[256127057] = "Ми вже деякий час доглядаємо за цими черв’яками. Сподіваюся, вони встигнуть набрати форму до турніру цієї організації. Адже тобі доведеться битися не з одним, а з двома йормунгарами.",  -- db:14779
[189548520] = "Вітаємо, $c.$B$BНаразі Альянс контролює фортецю Вінтерграсп, але битва вже розпочалася!  Поспішайте до Вінтерграспа та підтримайте наші війська!",  -- db:14781
[587753886] = "Вітаю, $c.$B$BНаразі Альянс контролює фортецю Вінтерграсп.  Коли битва ось-ось розпочнеться, зверніться до мене, щоб приєднатися до бою.$B$BНаступна битва розпочнеться через $4354k.",  -- db:14782
[531307190] = "Ти! Так, саме ти!$b$bПоглянь на мене і цінуй цю мить нашої зустрічі, бо незабаром світ дізнається і почне боятися імені та суворого обличчя Вілфреда Фізлбанга! Як тільки моє величне заклинання завершиться, ніхто не засумнівається в моїх здібностях!",  -- db:14787
[784330040] = "Вітаємо, $c.$B$BНаразі «Орда» контролює фортецю Вінтерграсп, але незабаром розпочнеться наступна битва.   Готуйтеся вирушити до Вінтерграспа та підтримати наші війська!$B$BНаступна битва розпочнеться через $4354k.",  -- db:14790
[543659299] = "Вітаємо, $c.$B$BНаразі Альянс контролює фортецю Вінтерграсп, але незабаром розпочнеться наступна битва.   Готуйтеся вирушити до Вінтерграспа та підтримати наші війська!$B$BНаступна битва розпочнеться через $4354k.",  -- db:14791
[693073226] = "Юстикар Маріель Трухарт попросила нас подбати про організацію турніру. Тих, хто заслужив право стати чемпіонами та довів свою спроможність у наших очах, просимо допомогти у виконанні цих обов’язків.",  -- db:14793
[862870201] = "Джастікар Маріель Трухарт попросила нас допомогти в організації та забезпеченні безпеки турніру, оскільки будівництво колізею завершено. Вона хоче, щоб ми співпрацювали з цими нікчемними виродками зі «Срібного Союзу», але вони лише заважають.",  -- db:14794
[769532485] = "Можливо, ми й діємо в тіні вищого світу, але тут, на передовій, наші здібності нарешті отримують належну повагу.",  -- db:14804
[429851446] = "Цей чаклун точно не викликав Стража Року! У наступному випробуванні тобі доведеться битися з лицарями Срібного Хрестового Походу. Гадаєш, ти готовий до цього випробування?",  -- db:14813
[163113002] = "Що ж, я подам сигнал Тіріону, коли ви будете готові вирушати.",  -- db:14814
[385742859] = "Ця сутичка була жорстокою й брутальною. Я вже багато років не бачив такої грандіозної бійки! Неймовірно!",  -- db:14815
[132480907] = "Не можу дочекатися, щоб це побачити! Схоже, вони вже готові до нового раунду, тож готуйтеся!",  -- db:14816
[969781653] = "Командна робота «Валькір» справді вражає. Тепер я розумію, чому нам було так важко їх обох захопити.",  -- db:14820
[499064942] = "Повірте на слово! Вам доведеться зіткнутися з двома наймогутнішими лейтенантами Валькір Артаса!",  -- db:14821
[537096199] = "Ну, сподіваюся, ти швидко одужаєш!",  -- db:14822
[992636844] = "Сенешаль турніру попросив нас взяти на себе частину обов’язків з організації змагань, оскільки будівництво колізею вже завершено. Тих, хто заслужив право називатися чемпіонами та довів свою спроможність у наших очах, просимо допомогти у виконанні цих обов’язків.",  -- db:14824
[29532079] = "Чудово, сьогодні ви продемонстрували, що є справжніми чемпіонами. З вами, які боретеся пліч-о-пліч із «Срібним хрестовим походом», перемога над «Плетью» неминуча!",  -- db:14828
[516026828] = "Ця похвала цілком заслужена. Тіріон незабаром сам захоче тебе похвалити. А ти помітив, що раптом стало трохи прохолодніше?",  -- db:14829
[177322441] = "Вітаємо, чемпіоне! Чи зібрав ти свої сили, готуючись до випробувань «Випробування Великого хрестоносця»? У цих випробуваннях можуть брати участь лише найсильніші та найдосвідченіші бійці. Щоб взяти участь у цих випробуваннях, ти повинен пройти звичайне «Випробування хрестоносця».",  -- db:14850
[357406906] = "«Випробування Великого хрестоносця» — це більш складний варіант «Випробування хрестоносця». Кожен бій є складнішим, і ви не зможете вільно повторювати спроби, доки не переможете. Після 50 невдалих спроб «Випробування Великого хрестоносця» на цьому тижні завершиться. Після успішного проходження «Випробування Великого хрестоносця» ви отримаєте додатковий скриню з нагородами як компенсацію. Чи готові ви до цього випробування?",  -- db:14853
[92686865] = "Радий знову тебе бачити, $N.",  -- db:14882
[445943784] = "Здивовані, що тут побачили орка? Не варто.$b$bЗа «Покинутими» треба стежити. Якби ми з самого початку приділяли їм більше уваги, можливо, події біля «Воріт Гніву» не сталися б.",  -- db:14931
[175747827] = "Сподіваюся, ви не шукаєте тих потвор. Аптекарям не можна довіряти, а це означає, що серед тих, хто патрулює коридори, немає жодного з їхніх маленьких створінь. Ми тут, щоб забезпечувати безпеку.",  -- db:14931
[137491891] = "Лок'тар. Не намагайтеся тут робити нічого підозрілого. Якщо ці неживі мають стати частиною Орди, то під нашим наглядом вони повинні поводитися як слід.",  -- db:14931
[558334983] = "Поспішайте, $r.",  -- db:14932
[526509624] = "Що таке, кістяк? Шукаєш когось іншого? Зараз у тебе є тільки я, тож якщо щось хочеш — кажи швидше.",  -- db:14933
[714012690] = "Готові побитися об заклад, що ви, негідники, вважали себе досить кмітливими біля Воріт Гніву, чи не так? Ігри скінчилися. Ми тут для того, щоб переконатися, що ви нічого не спробуєте.",  -- db:14933
[264200886] = "Я розповім тобі те, що тобі потрібно знати, але це ще не означає, що мені це має подобатися. Ми стежимо за тобою і такими, як ти.",  -- db:14933
[107512328] = "Я пам’ятаю, як ми з братом самостійно розбивали намети в пустелі Азшара. А погляньте, що з нею сталося зараз.",  -- db:15021
[565263308] = "Радий бачити тебе, брате/сестро з племені могавків $GBrother:Sister;.",  -- db:15038
[973679171] = "Що ти тут робиш, $c?",  -- db:15074
[124866615] = "Ось ти й тут! Я вже почав думати, що «Сонячні розбійники» перехопили тебе. Ти готовий передати фоліант нашим представникам у Лідовій Короні?",  -- db:15077
[726506198] = "Я не можу його довго затримувати, нам треба негайно вирушати!",  -- db:15081
[465406877] = "Ваш Йормунгар може рухатися лише тоді, коли ви занурилися під сніг, але під водою він не може атакувати. Як тільки ваш Йормунгар вирине на поверхню, він зможе застосувати свою потужну кислотну атаку, щоб проїсти броню Залізного Колоса. Будьте готові зануритися, щоб уникнути найруйнівніших атак Залізного Колоса.",  -- db:15119
[663395912] = "Вітаю, $glad:lass;. Я — Грелін Білобородий. Я прибув сюди, щоб оцінити загрозу, яку становить зростаюча кількість тролів у Долині Колдрідж. Що я виявив? Ситуація дещо тривожна...",  -- db:15132
[466432314] = "Ти — саме той $c, якого я шукав! Я тестую новий літальний апарат на ракетному двигуні, і мені потрібна твоя допомога!$B$BПросто візьми один із цих ременів і одягни його під броню.  Натисни кнопку збоку, і БУМ — і ти вже в повітрі.$B$BТільки не намагайся вкрасти мою розробку. Кожен із цих малюків оснащений «Транспонстером 8000», з’єднаним із тим, що у мене в руці. Якщо ти віддалишся від мене занадто далеко, «Транспонстер» вимкне головну ракету, і ти не зможеш злетіти, доки не повернешся.$B$BА де ж я поклав ті бланки про відмову від відповідальності?",  -- db:15134
[472353121] = "Ой-ой.  Справи у Фелікса складаються не дуже добре.",  -- db:15139
[877412824] = "Як справи, $c?",  -- db:15145
[515964310] = "Я затримаюся тут, доки не прибудуть підкріплення, але вам треба рухатися далі. У нас не буде багато часу, доки Артас не зрозуміє, що ми тут.",  -- db:15152
[251195798] = "Схоже, це останки Талоріена Доунсікера, останнього володаря «Квель'Делара».",  -- db:15155
[933427118] = "«Попелястий вердикт» — це елітна група найталановитіших майстрів з «Ебон Блейд» та «Срібного хрестового походу». Її створення символізує єдність наших сил у той час, коли ми готуємося до остаточного штурму на Короля Ліча та його поплічників.$b$bСаме завдяки зусиллям «Попелястого вердикту» ми відкрили, як підкорити первинний сароніт нашій волі.",  -- db:15159
[205386112] = "Поговоріть з алхіміком Фінклештейном, $c. Він допоможе вам знайти правильний шлях.$b$bПродемонструйте свою відданість, і вам відкриють їхні методи.",  -- db:15160
[365573783] = "Король Ліч уже близько, $n. Його голос дражнить мене...$b$bДавайте нарешті його замовчимо!",  -- db:15166
[843925563] = "Я зберу решту рабів і підготую їх до бою. Ми наздоженемо вас, перш ніж ви вступите в бій із Володарем Покарання Тираннусом.",  -- db:15172
[105018622] = "Пробачте мені, герої. Мені слід було послухатися Утера. Я… Я просто мусила переконатися на власні очі. Подивитися йому в очі востаннє. Мені дуже шкода.",  -- db:15189
[313129428] = "Ми в безпеці... поки що. З часу нашої останньої битви його сила зросла вдесятеро. Щоб знищити Короля Ліча, знадобиться могутня армія. Армія, більша за ту, яку здатна зібрати навіть Орда.",  -- db:15190
[194229884] = "Я затримаюся тут, доки не прибудуть підкріплення, але вам треба рухатися далі. Артас незабаром зрозуміє, що ми тут.",  -- db:15191
[697628634] = "Ти впевнений, $g lad:lass;? Тобі не знадобиться ще хвилина-дві?",  -- db:15195
[485024917] = "У нас немає часу на марнування, $c. Чому ти тут зволікаєш?",  -- db:15206
[322612739] = "У нас небагато часу, герою. Що тобі потрібно?",  -- db:15207
[686077166] = "Ти очікуєш, що я все це згадаю з пам’яті? Послухай. Мені не платили достатньо, щоб я це терпів, а в контракті було передбачено лише моє мовчання. Тож я просто кину тут на підлогу свій обліковий журнал, а ти його візьмеш і залишиш мене в спокої.$b$bЗрозумів?",  -- db:15211
[981940614] = "Що б тобі не знадобилося, Брейзі Гетц! Зрозумів?$B$BІ я маю на увазі не лише «законні» справи. ЩО Б ТОБІ НЕ ЗНАДОБИЛОСЯ, ДРУЖЕ! Будь-що...",  -- db:15214
[813985554] = "Стоячи так близько до леза, яке поклало кінець моєму життю... Біль... Він знову дається взнаки.",  -- db:15215
[281190893] = "Хоробрий воїн Орди, я вітаю тебе! Якби не ти та твої союзники, бойовий корабель Альянсу неодмінно знищив би нас.$B$BВідпочинь трохи, перш ніж ми почнемо штурм верхніх рівнів цитаделі.",  -- db:15217
[419562057] = "Ти впевнений, $N? Щоб досягти успіху, ми маємо протистояти «Скорбі» у повному складі. Якщо тобі не потрібно більше відпочинку, то почнемо.",  -- db:15218
[275942496] = "Я чув чутки, що мій син перебуває тут. Що він тепер — могутній лицар смерті на службі у Короля Ліча. Якщо це правда, то саме я маю покласти кінець цьому роду.$B$BТепер моє завдання — очолити «Молот Оргріма», піднятися на вершину Цитаделі Ледяної Корони та знищити всіх представників Плеті, які стануть нам на заваді. Ми вирушимо, коли ти та твої союзники будете готові.",  -- db:15219
[120059088] = "Коли ти будеш готовий, я проведу тебе до Сонцеколодязя.",  -- db:15240
[740795850] = "Стань на коліна поруч зі мною, друже. Під час останнього рейду я отримав кулю.$B$B<Ганн стогне від болю, намагаючись змінити положення. Його ліва рука стискає рану, з-поміж тремтячих пальців сочиться кров.>$B$BКоли карлики вперше вторглися в Пустощі, я задовольнявся тим, що заважав їхнім копачам і саботував їхнє спорядження. Мені слід було завдати смертельного удару, коли у мене була нагода.",  -- db:15246
[598889625] = "Тобі хіба не треба перевезти кілька пакунків?",  -- db:15282
[441535990] = "Щось смердить, і цього разу це не мої шкарпетки.",  -- db:15284
[205966398] = "Справді дивовижний меч, чи не так? Це не зброя, виготовлена карликами, ні, вона набагато давніша.$B$BЦі представники «Сонячних жниварів» та «Срібного союзу», здається, твердо налаштовані розгадати цю таємницю. Я вже працюю над звітом для Бранна.",  -- db:15287
[623842016] = "Я довго чекав на цей день, герою. Чи готові ти та твої союзники притягнути Короля Ліча до відповідальності? Ми рушимо в атаку за твоїм наказом!",  -- db:15290
[169178900] = "Ви застали мене в дуже важливий момент моїх досліджень! Не хвилюйтеся, можете приєднатися до мене у тихій задумі... з акцентом на «тихої», якщо, звичайно, ви не проти.",  -- db:15296
[788057499] = "Це рана, яку я завдав собі сам, друже. Я не міг змиритися з тим, щоб дивитися на світ, у якому я скоїв стільки жахіть, перебуваючи під владою Короля Ліча.$B$BЦе був мій перший крок до спокути, і якщо мої гріхи непідвладні прощенню, то я намагатимуся спокутувати їх до кінця свого життя.",  -- db:15297
[412805895] = "Зі сходу дме неприємний вітер, $c.",  -- db:15302
[604323155] = "«Фростмурн»: меч, що знищив наше королівство...",  -- db:15339
[453544514] = "Після незліченних невдач наших агентів у спробах здобути придатні для аналізу зразки хвороби «Скордж», я особисто вирушив на передову, щоб проконтролювати хід робіт. Як то кажуть, якщо хочеш, щоб справу зробили як слід...",  -- db:15340
[634320710] = "Це неймовірно! Ви вкриті потужною, заразною, фантастичною хворобою! Будь ласка, дозвольте мені зібрати ці бездоганні зразки. Я також усуну будь-які залишки інфекції у ваших соратників і нагороджу вас усіх за вашу хоробрість та самопожертву в ім’я медицини! Дайте знати, якщо ви готові продовжувати.$B$B[Перш ніж продовжувати, переконайтеся, що ВСІ учасники рейду знаходяться поруч, щоб вони отримали нагороди за ваше досягнення.]",  -- db:15343
[390562685] = "Смертні, ви врятували мене від долі, гіршої за смерть. Якби їх залишили напризволяще, чаклуни Короля Ліча зрештою зламали б мою волю й прирекли мене на вічні муки нежиття. Попереду вас чекає та, якій не пощастило: колись горда супутниця Малігоса, Сіндрагоса.$B$BСмертельно поранена після зради Нелтаріона й залишена помирати на самоті в снігах Ледяної Корони, вона тепер існує як істота, сповнена чистої ненависті. І все ж під цими шарами злоби все ще прихований благородний дух королеви драконів. Я вірю, що ще є надія на те, що душа Сіндрагоси зможе знайти спокій.",  -- db:15379
[17206105] = "Ти правильно запитав, юний $c.  Писарі здатні наносити на карти Таро знаки великої сили, хоча навіть вони не мають повного контролю над тим, що створюють.  За них вирішують долі.$b$bЯкщо тобі вдасться роздобути готову колоду, будь ласка, принеси її мені — і отримаєш чудову нагороду.",  -- db:15400
[466298398] = "Ми знищили останню перешкоду, що заважала проникнути до Залів Морозного Крила, $g lad:lass;. Лише Сіндрагоса стоїть між Королем Лічем і божественною карою! На що ж ти чекаєш?!",  -- db:15412
[736497753] = "Тепер усі перешкоди подолано, $N! Між Ліч-Королем і нами стоїть лише Сіндрагоса. Справедливість незабаром настане...",  -- db:15415
[210833558] = "Будь-де, тільки не тут...",  -- db:15432
[603952327] = "Вітаю, герою. Я виготовляю та продаю обладунки «Лашервів» Фрейї для друїдів.",  -- db:15445
[766507262] = "Вітаю, герою. Я виготовляю та продаю обладунки «Кровожер Анкахар» для мисливців.",  -- db:15449
[436736539] = "Вітаю, герою. Я виготовляю та продаю обладунки «Лорд Імірджар» для воїнів.",  -- db:15450
[761322576] = "Вітаю, герою. Я виготовляю та продаю обладунки «Кровомаг» для магів.$B",  -- db:15453
[39499738] = "Вітаю, герою. Я виготовляю та продаю обладунки «Темний ковен» для чаклунів.$B",  -- db:15454
[246932258] = "<Сіммер із «Гвардії Смерті» дивиться на тебе з надією.>",  -- db:15512
[338406209] = "Сіммер каже, що у Гордо є сміливість, але немає розуму. Що він мав на увазі?",  -- db:15531
[684516048] = "Гордо любить збирати квіти. Збирати квіти — це трохи схоже на вбивство.",  -- db:15531
[621150860] = "Тут прохолодно.",  -- db:15531
[292426826] = "Йохан каже, що Гордо потрібен кравець, щоб підтягнути йому живіт.",  -- db:15531
[950055042] = "Від імені славетного й досі нейтрального картелю «Стімвідл» сподіваюся, що вам сподобається тут.$B$BПам’ятайте: у Гаджетзані раді всім! Усім, крім піратів.",  -- db:15532
[456457162] = "Вам щось потрібно?",  -- db:15572
[495579861] = "Постійні жертви «Попелястого вердикту» та таких героїв, як ти, наближають нас усіх до остаточної перемоги. Тепер я прибув до Цитаделі Льодової Корони, щоб надати допомогу тим, хто бореться проти Плеті. Разом ми покладемо край тиранії Короля Ліча!",  -- db:15602
[86007813] = "«Ти кажеш, що зможеш зробити це самотужки? — запитую я. — Це проста дурість чи невиправдана впевненість, яку я бачу перед собою?»$B$BНі, я бачу це в твоїх очах. Ти мусиш це знати. Ти мусиш довести собі, що зможеш зробити це самотужки. Добре. Я відступлю з поля бою, якщо ти цього бажаєш.",  -- db:15603
[889186307] = "Щоб перемогти Короля Ліча, вам знадобиться не лише мужність. Удачі.",  -- db:15604
[419312038] = "Ви зробили свій вибір. Чи виживете ви завдяки цьому вибору, чи загинете — тепер залежить лише від вас.",  -- db:15605
[290127930] = "З початком «Офензиви «Воєнної пісні»» тут, у Цитаделі Ледяної Корони, перемога вже на долоні! Смерть Короля Ліча принесе славу Орді!",  -- db:15606
[506631810] = "Твій вибір був сміливим! Я поважаю твоє прагнення до слави та честі! Померти з гідністю, $N!",  -- db:15607
[566396770] = "Спробуйте не звертати уваги на пружні, пухнасті сіднички гарпій... ці істоти насправді дуже небезпечні!",  -- db:15664
[743891787] = "Так, я вже бачив тебе тут раніше! Як я міг забути? Якщо хочеш, я можу перенести тебе до Стратхолма прямо зараз.",  -- db:15704
[617535669] = "Війська Армії Вартових стримують Орду на всій території Калімдора. Поки війна триває в Попеліній Долині та Кам’яному Хребті, наші війська потрібні й тут, щоб захистити ці останні дикі землі та не дати ворогам закріпитися далі.",  -- db:15719
[431171936] = "Я тут лише на той випадок, якщо хтось знепритомніє. Новачки трохи перехвилюються й інколи перенапружуються.$B$B... ну, це, а ще іноді вибухає один із нових прототипів механо-танків. Ой!",  -- db:15779
[842804607] = "Я буду одним із перших, хто відгукнеться на заклик Вол'джина до зброї. А ти приєднаєшся до нас?",  -- db:15796
[678195282] = "Якщо тобі потрібна бита, ти потрапив у потрібне місце. Я відповідаю за всі бити для скаутів.",  -- db:15806
[651800317] = "Нехай духи ведуть тебе, $c.",  -- db:15846
[625412226] = "Кажу тобі, цей Корін Дайрбрю — справжній божевільний.$B$BЦе не МОЯ провина, що його не запросили взяти участь у Броварному фестивалі! Але це не завадило йому та всім його поплічникам із «Темного заліза» побити моїх співробітників і випити все моє пиво.$B$BХтось має покласти цьому край!",  -- db:15853
[759394696] = "Потрібно зупинити Володаря Морозу, Ахуне.$B$BНавіть зараз він набуває матеріальної форми, викликний зі своєї стихійної в’язниці божевільними культистами «Молота Сутінків».$B$BЯкщо йому дозволити повністю увійти в наш світ, він поховає нас під вічною зимою.",  -- db:15855
[456100965] = "Що?!  Що ти сказав?!  Як ти смієш!  Моє пиво не поступається жодній з тих гидот, які подають на Броварному фестивалі!$B$BТи заплатиш за цю образу, $c!",  -- db:15859
[646088644] = "Ласкаво просимо до Тінкер-Тауна!",  -- db:15863
[472651844] = "Цей шматок льоду відлунює глибоким, тріскучим гуркотом наступаючих льодовиків.  Його холод навіює думки про безжиттєву, нескінченну зиму.",  -- db:15864
[10798812] = "Час Залазане добігає кінця. Острови Ехо знову належатимуть племені Темних Списів!",  -- db:15865
[888710060] = "У «Даркспірс» знову є домівка! І без твоєї допомоги, $N, нам би це не вдалося. А тепер — святкуємо!",  -- db:15866
[769398511] = "Моє завдання — забезпечити, щоб весь цей напад пройшов як по маслу.$B$BГоловний майстер Меккаторк зараз перебуває на операції, але він має повернутися, щоб підкріпити війська, — це може статися будь-якої миті.  $B$BВін ніколи не запізнюється, тож просто зачекайте, і він обов’язково з’явиться.",  -- db:15868
[140636925] = "Швидше! Тобі треба поговорити з Меккаторком! Якщо ми не почнемо штурм найближчим часом, ми запізнимося.$B$BА мій начальник НЕНАВИДИТЬ, коли ми запізнюємося!",  -- db:15870
[609622563] = "Вольджин сказав мені, щоб я продовжував бити в барабан, поки він не повернеться. Якщо ти на нього чекаєш, то він скоро повернеться, щоб відвоювати Острови.$B$BПросто зачекай тут і насолоджуйся музикою!",  -- db:15873
[302875469] = "Ми готуємося відвоювати Острови Ехо. Залазане вже деякий час займається своєю магією вуду, переконуючи людей, що він мертвий, і проводячи стародавні темні ритуали.$B$BВін знає, що ми прийдемо, тож ми маємо подбати про те, щоб бути готовими.",  -- db:15876
[525209963] = "Нам потрібна допомога союзників на островах.$B$BЗен'табра вже деякий час опікується тваринами на островах.  Нам знадобиться її допомога та допомога тварин.$B$BBвонсамді — могутній лоа, який керує духами померлих на островах.  Його благословення має вирішальне значення для нашої атаки.$B$BЯк тільки наші союзники приєднаються до нас, Залазане та його армія тролів, що перебувають під контролем розуму, не матимуть жодних шансів!  Тоді Острови Відлуння стануть Темними Списами!",  -- db:15877
[448367547] = "У той час як мій брат, Дразіал, зосереджує свій аналіз на фізичних особливостях звірів спустошених земель, я, як правило, приділяю увагу інтелектуальним та духовним аспектам дикої природи.$B$BДійсно, ці звірі демонструють надзвичайно незвичайну силу, спритність і витривалість, але деякі з них також володіють великим інтелектом і здатністю до регенерації, що не пов’язані з їхньою фізичною сутністю.$B$BМожливо, вам буде цікаво допомогти мені у моїх дослідженнях, $r?",  -- db:16007
[832067370] = "Чого ти хочеш?",  -- db:16157
[569176878] = "Ех, і без цих нових клопотів тут і так важко підтримувати порядок! Сподіваюся, у тебе є хороші новини, $n...",  -- db:16211
[860570003] = "У Нетергарді іноді буває трохи задушливо. Іноді карлиці просто потрібно випити пива, щоб хоч на деякий час відволіктися від своїх обов’язків.",  -- db:16219
[23798934] = "Ласкаво просимо до Гром'гола, $C. Щоб уникнути непорозумінь з самого початку, хочу попередити, що в моєму базовому таборі не буде місця ледарям... Я очікую, що такий здоровий $R, як ти, буде тут виконувати свою частину роботи.",  -- db:16334
[110503528] = "Навіть у цьому віддаленому куточку світу знайте: погляд Пекельного Крику спрямований на вас.",  -- db:16335
[978494852] = "Мені набридло сидіти в цій дірі. Сподіваюся, що той жалюгідний клерк, який затримує повернення Даната, отримає по яйцях.",  -- db:16390
[105079804] = "За тебе!  За мене!  Нехай ми ніколи не сперечаємося.$b$bАле якщо все-таки сперечемося... Хай тебе чорт забере!  За мене.",  -- db:16418
[181469414] = "Ура! Вони вже втягнулися!",  -- db:16432
[550199821] = "Хочете придбати кілька піратських речей?",  -- db:16440
[946488315] = "Ласкаво просимо до Буті-Бей, $r.",  -- db:16441
[927608275] = "Нехай світло Сонця захищає тебе, $c.",  -- db:16491
[563766046] = "Ласкаво просимо до Доланаара, $c. Дай знати, якщо тобі знадобляться рецепти чи основні кулінарні інгредієнти.",  -- db:16510
[942286637] = "Це МІЙ УНІВЕРСАЛ!$B$БІЙ МЕНЕ!",  -- db:16528
[417063666] = "Будь насторожі, $c. Навіть Дуротар не захищений від наших ворогів.",  -- db:16535
[294276360] = "Мабуть, я прожив чарівне життя, $N. Повернутися у цей світ як член «Покинутих» та «Товариства аптекарів»... Я й не міг би мріяти про долю, яка б мені більше підходила.",  -- db:16583
[931592553] = "Привіт, красуне!  Не могла б ти нанести трохи лосьйону на мої відкриті ділянки?",  -- db:16644
[971128123] = "Ми мусимо забрати те, що належить нам. Від цього залежить наше виживання.",  -- db:16661
[92724595] = "<Майор коротко киває головою.>",  -- db:16719
[140951581] = "У всьому Оргримарі ви не знайдете кращої зброї.",  -- db:16901
[409698868] = "Ти мене шукаєш?",  -- db:17038
[480938809] = "Ти обов'язково повинен спробувати це пиво.",  -- db:17140
[66270913] = "Що привело тебе до такої зграї старих, віджилих пустельних псів, як ми?",  -- db:17151
[138850837] = "Хто ти?",  -- db:17235
[989139800] = "Тікай звідси, поки работорговці тебе не побачили!",  -- db:17235
[782654531] = "Ти... прийшов мене врятувати?",  -- db:17235
[54209899] = "Ласкаво просимо до «Торіум-Пойнт». Як Наглядач, я відповідаю за всю діяльність Братства Торіума. Хоча це переважно стосується видобутку корисних копалин, ковальства та деяких другорядних охоронних обов’язків, останнім часом ми все більше перетворюємося на бойову організацію… з необхідності.",  -- db:17268
[105701708] = "Дерак Найтфолл, до ваших послуг!",  -- db:17511
[511085867] = "Ласкаво просимо до селища Старфолл, мандрівнику. Ти прийшов, щоб допомогти нам?",  -- db:17586
[831571498] = "Ми раді вашій допомозі.",  -- db:17772
[83541437] = "Що?!",  -- db:17805
[979366939] = "Набрид вам хтось із ваших демонічних підлеглих? Хочете, щоб у нього було приємніше ім’я?$B$B$B$BЗа певну плату я можу допомогти вам знищити нинішнього підлеглого, щоб ви могли викликати зовсім нового...",  -- db:17816
[120131805] = "Лише найхоробріші та найшанованіші члени племені можуть заслужити честь бути похованими в Ред-Рокс.",  -- db:17838
[422177770] = "Життя мисливця за скарбами — це небезпечна справа. Не обманюйте себе.",  -- db:17861
[636673045] = "Оскільки всі облогові машини вже майже готові, мені стає трохи нудно!$B$B$B$BТи ж не інженер, правда? Може, порівняємо креслення...?",  -- db:18070
[139721856] = "Стій! Не йди далі, смертний. Ти недостатньо готовий, щоб протистояти силам Нескінченного Драконячого Польоту. Ходи, дозволь мені тобі допомогти.",  -- db:20201
[547893493] = "Сподіваюся, ця клята штука спрацює. «Араксес стукає по портативному транспондеру».",  -- db:20551
[348447098] = "Я тут, командире",  -- db:20551
[328942849] = "Ми виявили ціль, командире. «Я-6» і я розійшлися. Прошу підкріплення.",  -- db:20551
[809084421] = "Арксес! Надішли допомогу! Я заблокований у шахтах, я... я не впевнений, де саме перебуваю, але встиг кинути трасуючі кулі на землю позаду себе",  -- db:20551
[188465953] = "Я не можу прослідкувати сліди назад, на шляху занадто багато плотських чудовиськ. Надішліть когось туди... Прослідкуйте сліди... «Я-Шість», кінець зв’язку.",  -- db:20551
[478383300] = "Араксе, виходи на зв'язок... Араксе, ти там? Видимість нульова, нам заважають варп-бурі.",  -- db:20564
[249736327] = "Копія, Звіт про стан справ, Солдат.",  -- db:20564
[711143052] = "Зрозуміло, «Араксес». Підкріплення вже в дорозі. Залишайтеся на позиціях. Повторюю: залишайтеся на позиціях.",  -- db:20564
[437124326] = "Амір, кінець зв’язку.",  -- db:20564
[883255941] = "Саме тут Гул'дан розірвав зв'язок між орками та духами стихій. Його невгамовна жага до влади не могла бути вгамована навіть повним знищенням драені. Він мусив також знищити Дренор, зрівнявши землю з землею та висмоктавши всю її енергію для використання у своїй війні.  Тепер залишилися лише залишки його божевілля. Поглянь на вівтар, нічний ельфе — ця земля назавжди проклята......",  -- db:21024
[706020952] = "Роккарам, це ти?$B$BПробач, що поставив тебе під сумнів, сину мій. Мій зір вже не той, що колись, але ворон благословив мене довгим життям. Незабаром настане час, коли ти займеш моє місце. Я навчив тебе всьому, що знаю. $B$BЄдине, про що я шкодую, — це те, що не виявився гідним повернути нашу священну «Книгу Ворона».Істинні віруючі живуть у ганьбі з того дня, як наші зрадливі родичі зі Скеттіса вкрали у нас книгу, розбили її табличку й поховали уламки у своєму жалюгідному місті!$B$BMолись, щоб ворон обрав саме тебе для її відновлення, сину мій. Будь вірним і завжди пам’ятай пророцтво: «Зі снів своїх ворогів ворон вилетить у світ».",  -- db:22932
[821208475] = "<Омаріон щось бурмоче собі під ніс.>$B$BАле звичайно, я можу тобі допомогти, дорогий $N. Це моє останнє бажання... моє найзаповітніше прагнення. Будь ласка, візьми цей посібник. Інформація на його сторінках — це збірка всього, що я знаю і чого навчився за останні 30 з гаком років мого жалюгідного життя. Передай цей посібник моєму нікчемному підмайстру, який, мабуть, сидить на своєму товстому заду в каплиці «Надія Світла».",  -- db:24400
[888845592] = "Кравець, так? Добре. Чого б ти хотів навчитися, кравцю?$B$B",  -- db:24401
[905091945] = "Коваль, так? Добре. Чого б ти хотів навчитися, ковалю?$B$B",  -- db:24402
[171824891] = "Швець, так? Добре. Чого б ти хотів навчитися, швець?$B$B",  -- db:24403
[926971330] = "Це все, на що вони здатні?$B$B<Омаріон знаходить в собі сили посміятися.>$B$BУ тебе немає рішучості протистояти такому монстру, як Кел’Тузад. Ти розсиплешся перед його посіпаками — так само, як і ті, хто був перед тобою...$B$BЗалиш мене тут помирати. Я відмовляюся повертатися у світ, який захищає таких, як ти.",  -- db:24404
[185145269] = "Привіт, $N. Чим можу допомогти?",  -- db:31023
[88350905] = "Ти, мабуть, у скрутному становищі, якщо блукаєш цими Бедлендами, $c. У скрутному становищі, як і я.$B$BАбо, може, ти тут тому, що божевільний. Божевільний, як і я.",  -- db:50010
[23258702] = "Щоб служити Темній Леді та Варіматрасу, нам потрібно просунутися на фронті боротьби з людською інвазією.",  -- db:50013
[696824585] = "Ми вже зовсім близько до створення Нової Чуми, якої так палко прагне наша Темна Пані.",  -- db:50014
[83979668] = "Завдяки Вождю навіть тут, серед руїн нашої колишньої в’язниці, залишається деяка надія, і Орда знову піднімається.",  -- db:50015
[205473299] = "Привіт, громадянине! Мені потрібна твоя допомога...",  -- db:921061
[305291214] = "Привіт, друже. Мене звати Ремі. Я з Червоногір'я, що на сході, і приїхав сюди у справах, у справах. У тебе є щось... є щось??",  -- db:6157
[539995196] = "О, та це ж молодий, енергійний $c, якого, без сумніву, привели сюди розмови про мої подвиги на полях битв!$B$BЗараз немає часу на розповіді, адже попереду великі й важливі справи, які треба виконати!  Тож якщо ти прагнеш слави, то сьогодні тобі пощастить...",  -- db:1244
[749382036] = "Щоденник Джандіс Баров наповнений тирадами та мареннями про нежить. Ближче до кінця книги міститься те, що, судячи з усього, є викрійкою для пошиття якоїсь сумки.",  -- db:8121
[905550784] = "UDB Відсутній текст",  -- db:8122
[53392255] = "Пори року змінюються для всіх у свій час, але ти все ще перебуваєш у розквіті свого життя. Будь ласка, повернися до нас пізніше, $c, коли набудеш більше досвіду.",
[259309839] = "Війна проти Орди набрала повних обертів, $N. Зараз Альянс дуже потребує допомоги, і нам усім необхідно докласти зусиль, щоб допомогти.",
[197413980] = "Гарнізон Бел-Модан потребує допомоги у виконанні своєї місії зі закріплення позицій на західному кордоні Калімдора! Чи готові ви долучитися до цієї справи та захистити інтереси Альянсу?",
[587735034] = "Рікк соран ксі енкіл Маладат іл тічар, каркун. Рук маз зекул ши ашдж рака ксі енкіл ксі гулар те лок фарамос раккан? Енкілзар арчім...",
[384758754] = "Не дай себе обдурити тим «$rs» на Базарі, хлопче: завдяки метро, яке побудували ті гноми, перевозити товари з Айронфорджа простіше, ніж ти можеш собі уявити. Якщо вони спробують накинути імпортні збори, просто скажи їм, що купуватимеш спорядження в мене.",
[476197942] = "«Далекобіжці» були гордою групою рейнджерів; із падінням нашої землі вони теж залишилися позаду, проте саме в нас їхня спадщина житиме й надалі.",
[75993988] = "З часу падіння Сонцеколодязя ми намагаємося якомога менше витрачати ману. Колись ми були взірцем арканої сили, а тепер — лише тінь колишніх себе.",
[819570207] = "Це похмурі часи, але наших рідних треба вести до Світла. Їхні рани, хоч їх і неможливо повністю загоїти, треба лікувати з усіх сил.",
[842712880] = "Ви подолали велику відстань. Відпочиньте своє втомлене тіло під нашим дахом, і нехай Сонце веде вас.",
[711864086] = "Що можна робити в готелі?$B$BНу, зупинившись у готелі, ви відпочиваєте дуже комфортно. Завдяки цьому ви «відпочинете» набагато швидше, ніж у дикій місцевості. Коли ви добре відпочинете, ви більше навчитеся на власному досвіді.$B$BВи також можете звернутися до будь-якого господаря готелю, щоб отримати камінь повернення, який згодом можна буде використати для швидкого повернення до цього готелю.",
[698167253] = "Ласкаво просимо до «Buckle Up»! Вибачте за безлад — я перетворюю свою крамницю з обладунків на щось нове: пряжки для ременів! Якщо ви мрієте створити щось унікальне, то потрапили саме туди, куди треба.",
[266760575] = "Майстер Ву Пін досконало володіє майже всіма видами зброї, відомими людству. Особливо смертоносні його прийоми володіння мечем. Він проводить чимало часу в «Арсеналі Веллера», чекаючи на нові поставки зброї, тож якщо вам потрібне тренування — звертайтеся до нього.",
[140071676] = "Дженова Стоуншилд, що мешкає у Дварфському кварталі, — саме та, кого ви шукаєте. Вона доглядає за вихованцями мисливців, поки ті проходять навчання у її батька.",
[901386106] = "Ви ж чули про трамвай, правда? Це просто неймовірна поїздка! Він знаходиться в Дварфському районі, у самому кінці. А ще не забудьте тримати руки й ноги всередині трамвая, поки він рухається.",
[674418871] = "Пссс... Я можу допомогти тобі приховати свою справжню особу за допомогою підроблених документів, якщо ти принесеш мені 5 золотих.",
[766982552] = "Чого ти хочеш? Я зайнятий, тож йди собі.",
[687550633] = "Я вже по тому, як ти стоїш, бачу, що ти аж ніяк не воїн. $B$BЧому б тобі не зайнятися чимось безпечним, наприклад, почитати книжку?",
[272169233] = "Дослідження — це як дегустація нового елю чи свіжозвареного пива! Звісно, зрештою ти все одно нап’єшся.$B$BХоча дослідження — це набагато корисніше для здоров’я. Хіба що замість гарного грогу тобі дістануться якісь троги.",
[38410572] = "Гей, пане. Ви виглядаєте як $C з вишуканим смаком у вині. Я хотів би попросити вас про послугу, і, гадаю, можу зробити вам пропозицію, від якої ви не зможете відмовитися... Забудьте про це!",
[463461271] = "Шукаєш спільне сховище? Шукай деінде, друже.",
[826408151] = "Готовий побитися об заклад, що Грегор якось до цього причетний...",
[530059075] = "«Змова між фракціями» — фіг собі, тут відбувається щось інше.",
[309425636] = "Схоже, я закриваю справу...",
[691655211] = "Ласкаво просимо до Банку Штормовію. Ми пропонуємо відкриття фінансових рахунків та оренду сейфів для зберігання цінних речей. Чи маєте Ви вже у нас рахунок, пане?",
[822242265] = "Вітаю тебе, герою! Маю для тебе найсвіжіші новини з обох континентів та інших куточків світу.",
[226726707] = "Я дещо знаю про ювелірну справу, але якщо ти хочеш навчитися найскладнішим візерункам, тобі доведеться поговорити з моїм батьком. Він знає всі секрети цієї справи.",
[784896029] = "Наша родина користується в Штормовії чудовою репутацією завдяки своєму ремеслу. Ми виконували замовлення від представників знаті на виготовлення одних із найвишуканіших ювелірних виробів у всьому королівстві.",
[885000946] = "Чи можу я вам чимось допомогти?",
[318878438] = "Друже — Штормовій потребує твоєї допомоги та щедрості!$B$BНаші колись великі запаси текстилю критично скоротилися. Зараз Штормовій докладає зусиль у кількох напрямках, щоб відновити ці запаси для виробництва текстилю та бинтів! Ваш дарунок у вигляді тканини стане величезною допомогою для Штормовію, а також дозволить вам заслужити повагу його мешканців!",
[483685283] = "Виготовлено найкращими майстрами усього Телдрасілу, перевезено вручну з Калімдору до Азероту як знак зміцнення союзу між народом Великого Дерева та мешканцями цієї землі. Якщо вам щось знадобиться, просто скажіть.",
[358094326] = "Ішну-алах, брате. Чи є у тебе якісь звістки з-за кордону? Моє серце прагне новин про Телдрассіл.",
[241139576] = "Ласкаво просимо до «Блу Реклюз», де любителі магії збираються, щоб розвіятися. Хоча, звичайно, не в буквальному сенсі. Чим можу вам допомогти, пане?",
[497873099] = "Радий бачити тебе, $c. Ось моя порада тобі: подорожуючи світом, будь обережним із магією, бо вона спалить тих, хто не навчений.",
[843372173] = "Тобі краще відступити, поки не виникли проблеми, зрозуміло?",
[441651584] = "Темрява тебе не охоплює, $c. Припини свою балаканину й зникни з моїх очей! Забирайся геть!",
[572052415] = "Ти не чаклун, і в мене немає на тебе часу. Забирайся геть!",
[925597714] = "У мене немає часу на марну наволоч. Не набридай мені більше. Якщо ти не чаклун, шукай собі таких самих, $C.",
[12505467] = "Ласкаво просимо, кохана! Хочеш купити собі щось новеньке? Дай-но я візьму сантиметрову стрічку...",
[317523230] = "Навіть у холодних кам’яних стінах, таких як ті, що оточують це містечко, можна знайти спокій і мир. Насправді, їх можна знайти де завгодно... просто пошукайте цю гармонію всередині себе.",
[716714121] = "Вміння злитися з природою та приборкувати самих звірів — це навичка, яку варто опанувати.",
[895814395] = "Ви коли-небудь тримали в руках арбалет, не кажучи вже про те, щоб з нього стріляти? Від нього справді відчувається невеликий відбій.",
[159905293] = "Мене часто залучають до навчання новобранців Гвардії Штормовію володінню луками та арбалетами — як для оборони міста, так і для використання в бою.$B$BСкажу вам, це одне з тих завдань, які мені найменше подобаються.",
[117374411] = "Вітаємо, мандрівнику. Якщо ви хочете дістатися до нашої прадавньої батьківщини Калімдору, що на заході, вам знадобиться переправа на човні. Один із наших кораблів з Аубердіна регулярно робить зупинку тут, у Штормовії.$B$BНе хвилюйтеся, якщо човна ще немає — він прибуде в належний час.",
[319642684] = "<Схоже, у Гріфона щось на думці...>",
[324955275] = "Якщо ви бажаєте приєднатися до нас під час операції на Балорі, мій вірний грифон Стілвінг може доправити вас туди.",
[244185497] = "<Моряк Кейпвінд з цікавістю дивиться на тебе.>$B$BТобі щось потрібно, чи тебе просто зацікавив цей плащ?$B$BТи ще ніколи не бачив мешканців острова?",
[838386214] = "Ця гавань — цілком непогане місце для риболовлі!",
[88103713] = "Буває непросто впоратися з натовпом матросів та ворожнечею між ними та морськими піхотинцями.$B$B Саме тут на допомогу приходять старшини, такі як я.",
[656682707] = "Мені не часто випадає нагода поговорити з мешканцем материка.",
[795593236] = "Чим можу тобі допомогти, жителю материка?",
[452599459] = "Штормовій був настільки люб’язний, що запропонував нам житло та приміщення для розміщення нашого посольства. Гадаю, мине чимало часу, перш ніж ці два королівства дійдуть згоди й об’єднаються.",
[136764524] = "Море суворе й сповнене таємниць. Там ще багато чого, що нам належить відкрити, і ще багато чого, що експедиціям належить нанести на карти.$B$BВи можете розраховувати на нас — ми знайдемо невідомі куточки цього світу.",
[281434947] = "Штормовій не такий вже й поганий, як його описують мешканці Боралуса.",
[478377480] = "Моє завдання — розібратися у ворогу та виявити його слабкі місця.$B$BЯ міг би розповісти про численні недоліки Штормовію, але я тут не для цього.$B$BЧим я можу тобі допомогти, $R?",
[629548342] = "Нація Кул-Тирас щедра до своїх вірних підданих та тих, хто присягає їй на вірність.$B$BНаша вірність і відданість належать Королівству Лордаерону та Старому Альянсу.$B$BА кому ви віддані?",
[369506727] = "Мене відправили від імені Лорда Адмірала для ведення дипломатичних переговорів із нашими південними сусідами.$B$BМені було цікаво дізнатися, чи дотримується місцева знать старих традицій, і наскільки вони поважають занепалі сестринські королівства на півночі.$B$BЯкщо Кул-Тирас і Штормовій коли-небудь мають стояти пліч-о-пліч, то жорстокі істини треба викласти так, щоб усі їх чітко зрозуміли.$B$BЗ Чорнокровцями не можна укладати перемир’я, і немає ніякої честі в тому, щоб стояти пліч-о-пліч з тими, хто знищив те, що колись існувало.",
[976824988] = "Ми приїхали з Лох-Модана з товарами для торгівлі. Подорожувати на човні з Водно-болотних угідь до Штормовію з вантажем — справжня мука. На щастя, один друг із Дварфського кварталу позичив мені цей циганський візок, щоб товари дісталися до Амберширу. На жаль, він не згадав, що візок у жахливому стані, тож тепер мені доводиться чекати, поки Гардім його полагодить, і водночас пильнувати за можливими небезпеками. Мабуть, у житті купця бувають і злети, і падіння.",
[30043566] = "Ой! Тромлі не вистачило того, що я був його охоронцем — тепер я ще й мушу виконувати для нього всілякі доручення. Цьому негіднику краще б купити мені пінту, щойно ми дістанемося до Амберширу!",
[763940982] = "<Ця бідна тварина не звикла до цих країв; вона рясно пітніє і виглядає пригніченою та втомленою.>",
[907857827] = "Забирайся, ідіоте. Дай мені спокій — я хочу випити.",
[424093247] = "Не знаю, як їм це вдається... Ці поштові скриньки, мабуть, якісь чарівні портали чи щось таке. Адже я бачу, як люди цілий день збираються біля поштової скриньки поруч із банком і дістають з тієї маленької скриньки мечі, щити та різноманітні обладунки!",
[836834204] = "Ви можете знайти Олдвіна Лафліна в Центрі для відвідувачів Штормовію, що у Торговому районі.",
[768684502] = "Ах, «Позолочена троянда»... з її м’якими пуховими ліжками та теплими ваннами... лише від однієї думки про цей готель мені хочеться... ::позіхання:: Щасливці ті, хто збирається туди... Ви знайдете його в західній частині Торгового району.  ...приємні м’які подушки, теплі ковдри. ::позіхання::",
[761037774] = "Не вистачає сміливості покататися на грифоні, так? Що ж, на щастя для вас, у нас є альтернатива, завдяки якій ви зможете тримати ноги на землі… більш-менш. Це гномський транспортний засіб — трамвай «Діпрун». Він зручно розташований у глибині Дварфського кварталу.",
[538149629] = "Кравець, так? Ну, якщо ти пробудеш тут достатньо довго, то рано чи пізно почуєш з вуст в уста про Джорджіо Болеро. Він уже кілька місяців визначає модні тенденції. Якщо хочеш повчитися у нього, то знайдеш його в Кварталі магів на зовнішньому кільці.",
[715816652] = "Знаєш, я міг би проткнути орка наскрізь або розрубати троля. Я міг би навіть викарбувати свої ініціали на боці огра, але просто не можу знести зняття шкури з тварини. Хто б міг подумати, еге ж. $B$BНу, якщо у тебе вистачить сміливості, то йди до Маріс Грейнджер у «Захисну Шкуру» в Старому Місті.",
[195965471] = "Ніщо не зрівняється зі спілкуванням з природою... принаймні так мені кажуть нічні ельфи. Я не дуже люблю розмовляти з квітами та деревами, але впевнений, що Танніса зможе тобі допомогти. Вона перебуває у Кварталі магів, біля крамниці «Alchemy Needs».",
[997125575] = "Гей, це нагадало мені, що мені треба відремонтувати ракетні черевики. Порада тобі, друже: ракетні черевики й грифони — це несумісне поєднання. $B$BО, але тобі потрібні вказівки... просто прямуй до Дварфського кварталу, там у глибині ти знайдеш Лілліам Спаркспіндл.",
[14955323] = "А, ви шукаєте Лукана Корделла. Він має крамницю на околиці Чарівного кварталу, по дорозі до Стокейда. ",
[598301762] = "У таверні «Pig and Whistle» у Старому місті працює чудовий кухар. Я спостерігав, як він користується ножем під час приготування їжі, і, між нами кажучи, мені здається, що він не завжди був кухарем. Не зрозумійте мене неправильно... якщо ви все ще хочете навчитися, він — найкращий з усіх, хто у нас є.",
[469399170] = "Ти хочеш сказати, що звідси не відчувається запах диму з кузень гномів? Що ж, якщо хочеш навчитися ковальству, тобі слід шукати Терума Глибококузного. Він знаходиться у Гномському кварталі, що розташований трохи північніше від Соборної площі.",
[57680857] = "Чаклуни, так? Ну, не від мене це чули, але я чув чутки, що ці типи збираються в барі під назвою «Забита вівця» у Магічному кварталі. ",
[792088156] = "Якщо ви мрієте стати могутнім $c, то кращого наставника, ніж лорд Грейсон Шейдоубрейкер, годі й шукати. Його можна знайти в Соборі Світла на Соборній площі.",
[995624422] = "Торфін Стоуншилд приїхав до нас аж із Айронфорджа, щоб поділитися з нами своїм досвідом у полюванні. Якщо вас не бентежить димне повітря Кварталу гномів, то ви знайдете його в його будинку на північному сході цього кварталу.",
[468556598] = "Що ж, ви можете знайти Терідана або Мальдріна біля місячного колодязя в парку. Просто вирушайте до західної частини Штормовію, на північ від Району магів, але на захід від Соборної площі.",
[446372423] = "Витривалість Ву Піна просто вражає. Спостерігаючи, як він годинами відпрацьовує прийоми з зброєю, мені потім стало шкода тренувального манекена. Не можу придумати нікого, хто б краще підходив для того, щоб навчити вас бойовим мистецтвам зі зброєю.",
[257920850] = "Якщо вам потрібні найнеобхідніші речі для подорожей, сміливо переглядайте мій асортимент.",
[967618835] = "Ліси — небезпечне місце, а цивілізація часто знаходиться далеко. Я можу навчити вас, як вижити в суворих умовах дикої природи.",
[867613557] = "Моя найбільша мрія — виростити найбільший у світі гарбуз!$B$BА яка ваша?",
[994525086] = "Привіт, чим можу вам допомогти?",
[365745400] = "<Схоже, кінь тебе любить.>",
[322981025] = "Дірдж Квіккліф із Гаджетзана — майстер кулінарного мистецтва. Щоб вдосконалити свої навички, тобі слід знайти його.",
[761410001] = "Обміняйте квитки тут! Обміняйте свої квитки на призи! Заходьте!",
[650854513] = "Ласкаво просимо! Ласкаво просимо до «Дивного зоопарку Темної Місяця» Єбба Неблгіра — скарбниці живих легенд та міфічних дивацтв! Насолоджуйся візитом, друже!$B$BАле будь обережним, до чого торкаєшся! Серед цих експонатів є як жахливі, так і божественні артефакти та звірі! Вони можуть обпалити нерозсудливу руку надто допитливого глядача...",
[260043959] = "Ласкаво просимо на ярмарок, юний друже!  Ми зібрали для тебе дивовижні речі з усього світу.  О, і, будь ласка, дай мені знати, якщо тобі вдасться зібрати комплект карт «Менших темних місяців», адже майстер... тобто, мені було б дуже цікаво їх побачити.",
[626573454] = "Ми розкидали карти «Темного Місяця» по всьому світу, щоб перевірити, чи знайдуться гідні гравці, здатні зібрати повну серію будь-якої з чотирьох мастей. Якщо вам вдасться зібрати всі вісім карт однієї з мастей, ми нагородимо вас однією з «Великих карт Темного Місяця», яка виконує функцію потужного аксесуара, а також надасть доступ до Ярмарку Темного Місяця.",
[367642637] = "Якщо вам вдасться зібрати повну колоду карт воєначальників, ви отримаєте в нагороду велику карту героїзму «Темного Місяця». Ця карта час від часу відновлюватиме ваше здоров’я під час рукопашного бою.",
[424921353] = "Якщо вам вдасться зібрати повну колоду карт елементалів, ви отримаєте в нагороду «Велику карту Темної Місяця: Вир». Ця карта час від часу завдаватиме значної шкоди ворогу, з яким ви ведете бій.",
[471343373] = "Якщо вам вдасться зібрати повну колоду карт порталів, ви отримаєте в нагороду кращу карту «Темного Місяця» із «Викрученого Нетера». Ця карта час від часу повертатиме ваш дух у тіло після смерті та відновлюватиме вас.",
[132018725] = "Якщо вам вдасться зібрати колоду карт «Звірі», ви отримаєте в нагороду «Велику карту Темної Місяця» із зображенням блакитного дракона.  Вона дуже корисна для відновлення магічної енергії.",
[122718054] = "Привіт! І ласкаво просимо! На жаль, мій кіоск поки що не працює... Потрібно зробити чимало ремонтів...$B$BАле я все ще зобов'язаний кров'ю присягою викликати посмішку на вашому обличчі. Тож, будь ласка, посміхніться, інакше мені доведеться відрізати собі руку й утримуватися від споживання живого м'яса, доки вона не відросте...",
[633759862] = "Хто зачіпає Сайласа — той зачіпає й мене. Гарного дня.",
[789371698] = "Заходьте! Купуйте свої пекучі крильця прямо тут!",
[452905644] = "Вітаю, друже, і ласкаво просимо на найграндіозніше шоу в Азероті!$B$BБудь ласка, підходьте ближче й насолоджуйтеся всім, що ми можемо запропонувати. Подивіться на дивовижні речі, які Ярмарок Темної Місяця відкрив у цьому величезному й таємничому світі! Ми не шкодували коштів, щоб подарувати вам захоплюючі враження, які сподобаються дітям будь-якого віку!",
[756196155] = "Я давно знав, що ти мене знайдеш, $N.$B$BКожна свідома істота в цьому світі керується тими рішеннями, які вона приймає. Вибори породжують нові вибори, а ті, у свою чергу, формують особистість людини. Саме звідси бере початок твоя доля — з того, хто ти є, і з виборів, які ти робиш.$B$BЧи готовий ти дізнатися, у чому полягає твоя доля?",
[376704416] = "Ну що ж...$B$BВаш сеньйор доручив вам охороняти його кукурудзяні поля від браконьєрів і злодіїв. Однієї ночі під час патрулювання ви натрапили на виснаженого чоловіка в пошарпаному одязі, який крав кукурудзу з поля. Ви швидко зупиняєте його, і він одразу ж благає пощадити його. Він стверджує, що краде кукурудзу, щоб прогодувати свою родину, оскільки володар цих земель — ваш сеньйор — вимагає занадто високих податків. Ваш сеньйор справді відомий своїми суворими податками по всій країні.$B$BЗробіть свій вибір.$B",
[493029377] = "На вас чекає наступний вибір.$B$BВи — присяжний кат свого сеньйора. До вас привели чоловіка, якого мають стратити як зрадника сеньйора та вашого народу. Ви знаєте цю людину як близького, доброчесного друга, який одного дня загадково зник. Ви також знаєте, що злочини, за які його засудили, нібито призвели до загибелі багатьох невинних цивільних осіб. Побачивши вас, він благає про пощаду, стверджуючи, що його підставили вищі чини.$B$BЗробіть свій вибір.$B$B",
[572044708] = "Ваша доля вирішена, $c. Протягом наступних кількох годин ви відчуєте, що ваш дух перебуває в гармонії з вашою справжньою сутністю. Будьте обережні, адже ваша доля — і ваше майбутнє — ніколи не є такими очевидними, як вам може здаватися.$B$BЯкщо ви хочете отримати невеликий натяк на те, над чим варто замислитися у вашому майбутньому, обов’язково дайте мені знати. Я з радістю дам вам письмове пророцтво, за умови, що у вас є місце в інвентарі. Воно складене на основі проникливості, яку ви проявили, відповідаючи на мої запитання.",
[957564959] = "Ось ваше передбачення, $N. Нехай воно принесе вам користь.$B",
[824347724] = "На жаль... Мені прикро це казати, але наразі я не можу передбачити вам майбутнє, оскільки ви нещодавно вже отримували від мене прогноз.$B$BПоверніться до мене через кілька годин після того, як ви вперше отримали свій прогноз. Сили Долі встигнуть належним чином переналаштуватися, і я зможу зазирнути у ваше майбутнє.",
[229621027] = "«Бластенхаймер 5000 Ультра» — це надсучасна одномісна метальна установка. Ця гармата, що вистрілює боєприпаси зі швидкістю, близькою до швидкості дракона, є гордістю та радістю родини Бластенхаймерів, всесвітньо відомої своїми досягненнями в авіації та у сфері вибухових речовин!$B$BЯкщо ви хочете злетіти в небо й літати вільно, як птах, знайдіть Максиму Бластенхаймер на південному краю Хантер-Райз у Тандер-Блаффі. Вона націлить вас на ціль, що знаходиться далеко на півдні, на озері Стоунбулл!",
[493159199] = "Ніхто достеменно не знає, хто створив карти Темної Місяця і яке їхнє справжнє призначення, але можу сказати, що їх знаходили по всьому Азероту, зазвичай у руках лиходіїв, які намагалися розгадати їхні таємниці.$B$BІснує чотири типи карт Темної Місяця: «Звірі», «Елементалі», «Портали» та «Воєначальники», у кожній масті по вісім карт — від туза до вісімки. Якщо ви зберете всі вісім карт однієї масті, то зможете скласти з них колоду, яку можна передати професору Тадеусу Палео в обмін на потужний амулет.$B",
[629644269] = "Мені справді доведеться нелегко!$B$BA Партія неправильно розрахованих запобіжників і несправних проводів спричинила тут справжній хаос серед усіх роботів!",
[216500193] = "Гей, $g(громадянине!;громадянко!) Ти виглядаєш $g(міцним хлопцем;міцною дівчиною). Нас, охоронців, тут не так багато, і мені б не завадила твоя допомога...",
[859402161] = "Штормовій — це опора раси $r, яка зберігається завдяки силі волі та гостроті міцного меча.",
[841960075] = "Абатство Нортшир — це справді гарне й тихе місце.",
[909650861] = "Неприборкана дика природа може здаватися загрозливим супротивником. Але коли ви досконало вивчите її звички, вона стане просто ще одним потенційним ворогом.",
[99262125] = "Я знаю кількох людей у цих краях, які займаються однією чи двома професіями. Про яку саме професію ви маєте на увазі?",
[606188272] = "Гелен Пелтскіннер має багаторічний досвід зняття шкур з тварин для Адель Філдер з метою виготовлення шкіряних виробів. Гелен мешкає у своєму будинку біля Кристал-Лейк.",
[530462043] = "Хочеш навчитися кравецькій справі? Хм... Гадаю, у лісозаготівельному таборі Іствейл є кравець, який, можливо, допоможе тобі зробити перші кроки в цій справі. ",
[724700943] = "Якщо ви хочете навчитися видобувати руду, вам краще вирушити до Штормовію, у район карликів. Напевно, хтось із місцевих карликів зможе навчити вас цій професії.",
[625020465] = "Біля Кришталевого озера живе жінка на ім’я Адель Філдер. Вона виготовляє латки для місцевої охорони з залишків шкіри, які отримує від місцевої шкіряниці Гелен. Якщо ви зацікавлені в освоєнні цієї професії, то, ймовірно, саме до неї варто звернутися.",
[966415990] = "Пані Померой збирає трави для алхіміка, який мешкає на пагорбах між Нортширом і Штормовійом. Загляньте до неї в його хатинку й дізнайтеся, чи не навчить вона вас цій професії.",
[481978111] = "Лі виловив на Кришталевому озері кілька досить дивних речей. Він розповів мені історію про цю дивну маску, яку виловив кілька місяців тому. Як на мене, то, мабуть, він просто перебрав того вечора в барі «Lion’s Pride».",
[398138123] = "Лі Браун проводить цілий день, рибалячи біля Кристал-Лейк. Мабуть, у нього є чим поділитися та якісь поради, якими він міг би з вами поділитися.",
[616288888] = "Нещодавно я мав неприємну сутичку з декількома членами угруповання «Дефіас» з цих околиць, але Мішель Белль мене чудово підготувала. Звернися до неї в таверні «Гордість Лева» і запитай, чи не навчить вона тебе.",
[90275516] = "Зазвичай я залишаю такі справи гномам. Якщо ти хочеш освоїти цю професію, впевнений, що в Штормовії знайдеш гномів, які зможуть тебе навчити.",
[183709798] = "Хм... Наскільки я знаю, у цих краях працюють лише чарівники зі Штормовію. Чому б тобі не запитати у когось із вартових у Штормовії?",
[436209021] = "Томас, можливо, і не найкращий кухар у околиці, але у нього є кілька страв, які справді смакують. Зараз він працює в готелі «Lion's Pride Inn», тож якщо ви хочете навчитися цій професії, зверніться до нього.",
[797641693] = "Аргус — місцевий коваль у Голдширі. Я впевнений, що він міг би навчити вас ковальській справі.",
[819440139] = "У горах між Нортширом і Штормовійом живе алхімік, який, можливо, зможе тобі допомогти. Чому б тобі не завітати до нього?",
[773766936] = "В Елвінні є чимало тренерів. Якого саме ви шукаєте?",
[851024909] = "Мало хто в цих краях так вправно володіє мечем, як Лірія Дю Лак. Заглянь до неї за кузнею і поцікався, чи не має вона бажання навчити тебе чомусь новому.",
[335857858] = "О... один із таких типів. Ну, Максиміліан — єдиний у цих краях, хто розбирається в темних мистецтвах. Ймовірно, ти знайдеш його в темряві підвалу корчми «Лев’яча гордість».",
[138749130] = "Розбійник? Хм... Ну, я чула, що Керін Сильвіус тусується з цими сумнівними типами. Можливо, тобі варто з нею поговорити й дізнатися, що вдасться з’ясувати.",
[560193544] = "Готовий побитися об заклад, що Джосетта з радістю навчить тебе кільком новим заклинанням. Вона, мабуть, зараз у своїй кімнаті в готелі «Лев’яча гордість».",
[354069475] = "Зазвичай брата Вільгельма можна зустріти в глибині кузні, де він обмінюється історіями з Лірією. Він завжди готовий навчити інших паладинів новим навичкам.",
[771552570] = "Залдімар, мабуть, міг би навчити тебе кількох нових заклинань. Останнім часом він полюбив зупинятися в готелі «Лев’яча гордість», тож, можливо, тобі варто зазирнути в одну з кімнат і перевірити, чи він там.",
[920540047] = "Я чув, що у Штормовій живе гном, який здобув певну славу завдяки своїм мисливським здібностям. Можливо, тобі варто піти до нього й дізнатися, чи зможе він тобі допомогти.",
[554438353] = "Друїди? Я тут ніяких друїдів не бачив. Хоча у Штормовії є район, який нічні ельфи перетворили на своє власне місце.",
[98305927] = "Стара добра Ерма — вона вже багато років опікується місцевими тваринами. Я впевнений, що вона з радістю догляне за будь-якою твариною, яку ви захочете їй довірити. Її можна знайти прямо біля готелю «Lion’s Pride Inn».",
[411537370] = "Готель «Гордість Лева» у Голдширі нічим не поступається іншим готелям у цих краях. Завітайте сюди, і господар Фарлі подбає про те, щоб ви почувалися як вдома.",
[251556977] = "Я вважаю, що Алдвін Лафлін досі є майстром гільдії Штормовію. Коли ви пройдете через внутрішні ворота Штормовію, зверніть увагу на його резиденцію, яка знаходиться ліворуч від вас.",
[47148346] = "Майстер грифонів керує польотами грифонів у межах Штормовію. Якщо ви хочете прокотитися на грифоні, то саме туди вам і слід прямувати.",
[847184238] = "Банк? Ну, найближчий банк у цих краях — це «Штормовійська казна». Він розташований трохи далі по дорозі у Штормовії, неподалік від воріт.",
[99262125] = "Я знаю кількох людей у цих краях, які займаються однією чи двома професіями. Про яку саме професію ви маєте на увазі?",
[606188272] = "Гелен Пелтскіннер має багаторічний досвід зняття шкур з тварин для Адель Філдер з метою виготовлення шкіряних виробів. Гелен мешкає у своєму будинку біля Кристал-Лейк.",
[530462043] = "Хочеш навчитися кравецькій справі? Хм... Гадаю, у лісозаготівельному таборі Іствейл є кравець, який, можливо, допоможе тобі зробити перші кроки в цій справі. ",
[724700943] = "Якщо ви хочете навчитися видобувати руду, вам краще вирушити до Штормовію, у район карликів. Напевно, хтось із місцевих карликів зможе навчити вас цій професії.",
[625020465] = "Біля Кришталевого озера живе жінка на ім’я Адель Філдер. Вона виготовляє латки для місцевої охорони з залишків шкіри, які отримує від місцевої шкіряниці Гелен. Якщо ви зацікавлені в освоєнні цієї професії, то, ймовірно, саме до неї варто звернутися.",
[966415990] = "Пані Померой збирає трави для алхіміка, який мешкає на пагорбах між Нортширом і Штормовійом. Загляньте до неї в його хатинку й дізнайтеся, чи не навчить вона вас цій професії.",
[481978111] = "Лі виловив на Кристал-Лейк кілька досить дивних речей. Він розповів мені історію про цю дивну маску, яку виловив кілька місяців тому. Як на мене, то, мабуть, він просто перебрав того вечора в барі «Lion’s Pride».",
[398138123] = "Лі Браун проводить цілий день, рибалячи біля Кристал-Лейк. Мабуть, у нього є чим поділитися та якісь поради, якими він міг би з вами поділитися.",
[616288888] = "Нещодавно я мав неприємну сутичку з декількома членами угруповання «Дефіас» з цих околиць, але Мішель Белль мене чудово підготувала. Звернися до неї в таверні «Гордість Лева» і запитай, чи не навчить вона тебе.",
[90275516] = "Зазвичай я залишаю такі справи гномам. Якщо ти хочеш освоїти цю професію, впевнений, що в Штормовій ти знайдеш гномів, які зможуть тебе навчити.",
[183709798] = "Хм... Наскільки я знаю, у цих краях працюють лише чарівники зі Штормовію. Чому б тобі не запитати когось із вартових у Штормовії?",
[436209021] = "Томас, можливо, і не найкращий кухар у околиці, але у нього є кілька страв, які справді смакують. Зараз він працює в готелі «Lion's Pride Inn», тож якщо ви хочете навчитися цій професії, зверніться до нього.",
[797641693] = "Аргус — місцевий коваль у Голдширі. Я впевнений, що він міг би навчити вас ковальській справі.",
[819440139] = "У горах між Нортширом і Штормовійом живе алхімік, який, можливо, зможе тобі допомогти. Чому б тобі не завітати до нього?",
[773766936] = "В Елвінні є чимало тренерів. Якого саме ви шукаєте?",
[851024909] = "Мало хто в цих краях так вправно володіє мечем, як Лірія Дю Лак. Заглянь до неї за кузнею і поцікався, чи не хоче вона навчити тебе чомусь новому.",
[335857858] = "О... один із таких типів. Ну, Максиміліан — єдиний у цих краях, хто розбирається в темних мистецтвах. Його, мабуть, можна знайти в темряві підвалу корчми «Лев’яча гордість».",
[138749130] = "Розбійник? Хм... Ну, я чула, що Керін Сильвіус тусується з цими сумнівними типами. Можливо, тобі варто з нею поговорити й дізнатися, що вдасться з’ясувати.",
[560193544] = "Готовий побитися об заклад, що Джосетта з радістю навчить тебе кільком новим заклинанням. Вона, мабуть, зараз у своїй кімнаті в готелі «Лев’яча гордість».",
[354069475] = "Зазвичай брата Вільгельма можна зустріти в глибині кузні, де він обмінюється історіями з Лірією. Він завжди готовий навчити інших паладинів новим навичкам.",
[771552570] = "Залдімар, мабуть, міг би навчити тебе кількох нових заклинань. Останнім часом він полюбив зупинятися в готелі «Лев’яча гордість», тож, можливо, тобі варто зазирнути в одну з кімнат і перевірити, чи він там є.",
[920540047] = "Я чув, що у Штормовій живе гном, який здобув певну славу завдяки своїм мисливським здібностям. Можливо, тобі варто піти до нього й дізнатися, чи не зможе він тобі допомогти.",
[554438353] = "Друїди? Я тут ніяких друїдів не бачив. Хоча у Штормовії є район, який нічні ельфи перетворили на своє власне місце.",
[98305927] = "Стара добра Ерма — вона вже багато років опікується місцевими тваринами. Я впевнений, що вона з радістю подбає про будь-яку тварину, яку ви захочете їй довірити. Її можна знайти прямо біля готелю «Lion’s Pride Inn».",
[411537370] = "Готель «Гордість Лева» у Голдширі нічим не поступається іншим готелям у цих краях. Завітайте сюди, і господар Фарлі подбає про те, щоб ви почувалися як вдома.",
[251556977] = "Я вважаю, що Алдвін Лафлін досі є майстром гільдії Штормовію. Коли ви пройдете через внутрішні ворота Штормовію, зверніть увагу на його резиденцію, яка буде зліва від вас.",
[47148346] = "Майстер грифонів керує польотами грифонів у самому Штормовій. Якщо ви хочете прокотитися на грифоні, то саме туди вам і слід прямувати.",
[847184238] = "Банк? Ну, найближчий банк у цих краях — це «Штормовійська казна». Він розташований трохи далі по дорозі у Штормовії, неподалік від воріт.",
[613041938] = "Що привело вас до Вежі Азори? Чи це пошук знань, чи щось більше — таємні науки?$B$BЩо б це не було, я впевнений, що ми зможемо вам допомогти.",
[509615170] = "Багаторічний досвід застосування якісних методів розведення та ретельний догляд дають мені можливість представити вам цих коней! Будь ласка, не поспішайте, обираючи собі коня. Кінь — це супутник на все життя, друг. Не обділяйте себе — придбайте свого скакуна саме тут уже сьогодні!",
[301347601] = "Амбіції та прагнення Кул-Тирасу — це складна справа. Наша мета тут — визначити справжню цінність цих мешканців півдня та з’ясувати, чи можна довіряти жителям материка.$B$BЯкщо знать Штормовію доведе свою вірність старим звичаям і старим ідеалам, то, можливо, у нас з’явиться перспектива співпраці.$B$BПобачимо, куди насправді лежить серце Штормовію.",
[210193826] = "На перший погляд це, можливо, не дуже очевидно, $R, проте, запевняю вас, ми раді прийняти допомогу, яку Альянс надає нам у такі скрутні часи.",
[29439379] = "Я прибув сюди, щоб звернутися по допомогу до знаті Штормовію. Це виявилося складнішим завданням, ніж я очікував.",
[635653802] = "Андвін зараз, можливо, ще лише хлопчик, але одного дня він стане великим правителем. Його серце чисте й сповнене світла. Оскільки його батько зник, саме мені випадає обов’язок навчати його та керувати королівством, доки він не досягне повноліття.",
[259131868] = "Як тільки я знайду потрібного покупця, я зроблю великий куш і буду купатися в горах золота!",
[944325168] = "Я не сприймаю твої порожні погрози. Що ти збираєшся зробити, вбити мене? Тут, просто так, на очах у всіх? Навіть найнижчий агент «Рейвенхолдта» не опустився б до такого рівня непрофесіоналізму. У тебе немає на мене нічого.",
[72974655] = "Вітаємо, слухачу! Від імені «BootyBay Pirate Radio» я тут, щоб з’ясувати думку громадськості з найрізноманітніших питань. Кожна думка має значення, а голоси залишаються анонімними. У різних опитуваннях можуть бути різні умови голосування.",
[646634048] = "Система досягнень$B$BЧи хотіли б ви, щоб у грі OctoWoW була додана система досягнень (цілі, що відстежуються у стилі WotLK, з балами та нагородами, адаптовані для версії 1.12)?",
[227073709] = "Міжфракційні поля бою$B$BЧи підтримуєте ви міжфракційні поля бою?",
[388635213] = "Ішну-алах, сестро. Чи є у тебе якісь звістки з-за кордону? Моє серце прагне новин про Телдрассіл.",
[393590816] = "У Телдрасілі є чимало місць, які ви могли б відвідати. Скажіть мені, що ви шукаєте.",
[896283820] = "У лісах Телдрасіля панує темрява, і подорож ними стає дедалі небезпечнішою. Якщо ви раптом заблукаєте серед дерев, пам’ятайте про те, чого вас навчали, — так ви збільшите свої шанси повернутися додому цілими й неушкодженими.",
[694227633] = "Я не бачу в тобі духу воїна, дитино. У мене немає вчень, які могли б принести користь такому $c, як ти.",
[337329481] = "Шлях тих, хто обирає професію, є довгим і плідним. Який шлях ви оберете?",
[912767867] = "Багато матеріалів, необхідних кравцям, надходить через Дарнассус. Тож не дивно, що вони всі переїхали туди, щоб працювати. Якщо ви хочете стати кравцем, то вам краще вирушити до Дарнассуса.",
[27247119] = "Ви можете зустріти Раднаала, який відточує свою майстерність біля свого будинку на дорозі до Дарнассуса. Варто зайти до нього і дізнатися, чому він може вас навчити.",
[479523122] = "За роки своєї практики Надія стала справжньою майстринею з обробки шкіри. Рушайте на захід дорогою до Дарнассуса, щоб відвідати її, і, можливо, вона поділиться з вами своїми знаннями.",
[462894679] = "Малорну якимось чином вдається збирати найніжніші трави, не пошкоджуючи їх. Безперечно, саме у нього вам варто повчитися. Він живе трохи на схід від корчми в Доланаарі.",
[658992452] = "Через нещодавні напади в околицях озера Аль-Амет усі рибалки переїхали до Дарнасуса. Тобі варто спробувати знайти там когось, хто міг би тебе навчити.",
[70236134] = "Б'янсі часто допомагала вартовим, які патрулюють місцеві дикі території. Якщо ви хочете навчитися надавати першу допомогу, вам слід поговорити з нею.",
[74172438] = "Навички Б'янсі у наданні першої допомоги неодноразово виявлялися корисними. Якщо ви хочете навчитися у неї, її можна знайти трохи північніше від готелю в Доланаарі.",
[260093576] = "Аланна проводить більшу частину дня на Галявині Оракула, де займається своєю справою. Якщо ви бажаєте опанувати професію чарівника, вам слід вирушити туди, щоб знайти її.",
[947565692] = "Здається, Заррін добре розбирається в кулінарії. Чому б тобі не підійти до нього і не попросити, щоб він поділився з тобою кількома рецептами? Зазвичай він готує біля готелю в Доланаарі.",
[152836064] = "Знання Синдри в галузі алхімії дещо обмежені, але я впевнений, що їх вистачить, щоб ти зміг розпочати навчання. Вона займається своїм ремеслом трохи на схід від готелю в Доланаарі.",
[72527908] = "У околицях Доланаара ви знайдете безліч тренерів, які мають багаторічний досвід і готові надати вам індивідуальні заняття. До кого б ви хотіли, щоб я вас направив?",
[147114383] = "Мені колись випало щастя побачити, як Кіра Віндблейд билася. З огляду на те, що я побачив, я впевнений, що вона добре тебе навчить. Шукай її в таверні в Доланаарі.",
[149277707] = "Шукаєш розбійника? Гадаю, Яннок підходить під цей опис. Чому б тобі не піти поговорити з ним у таверні в Доланаарі?",
[908707433] = "Лорана Морнінглайт надає медичну допомогу мешканцям околиць Доланаара. Можливо, вона зможе навчити вас мистецтву священика.",
[423561017] = "Якщо ви шукаєте $c, то вам слід завітати до Дазалара. Зазвичай його можна знайти біля входу до корчми в Доланаарі.",
[718706582] = "Друїд Кал часто проводить час біля Місячного джерела в Доланаарі. Я впевнений, що він зможе надати тобі необхідне навчання.",
[687669663] = "Шукаєте когось, хто піклується про тварин? Тоді вам слід знайти Серіадне біля таверни в Доланаарі. Саме вона — та, кого ви шукаєте.",
[192755889] = "Якщо вам потрібен час, щоб відпочити й відновити сили, найкраще місце для цього — готель у Доланаарі. Готельний господар Келдамір подбає про те, щоб про вас добре подбали.",
[601906570] = "Питання такого офіційного характеру вирішуються виключно в Дарнасусі. Вам необхідно вирушити туди, щоб розпочати процес створення вашої гільдії.",
[703239761] = "Пором «Рут'теран» відправляється до Аубердіна з селища Рут'теран, розташованого біля підніжжя Телдрасіла. Портал у Дарнассусі дозволить вам безпечно дістатися до Рут'терана.",
[689364817] = "Банк розташований у тихому місті Дарнас. Якщо ви хочете зберігати там свої речі, вам слід туди завітати.",
[428096421] = "Виберіть товар, за який ви хочете отримати відшкодування.",
[10048727] = "Булівіф, майстер зброї-гном із крамниці «Тімберлайн Армс» в Айронфорджі, навчає володінню кулачними зброями, вогнепальною зброєю, одно- та дворучними сокирами, а також одно- та дворучними булавами.$B$BBіксі Вобблбонк, майстер зброї гномів у «Тімберлайн Армс» в Айронфорзі, навчає стрільбі з арбалета, володінню кинджалами та метальною зброєю.$B$БІленія Мунфайр, майстер зброї нічних ельфів, мешкає на $C's Terrace у Дарнассусі, де вона навчає стрільбі з лука, володінню кинджалами, кулачною зброєю, посохом та метальною зброєю.",
[100961606] = "Куди б ти $g(хотів;хотіла) полетіти, $g(хлопче;дівчино)? За кілька монет мої грифони доставлять тебе туди швидше, ніж навіть найшвидший кінь.",

}
